#include <stdio.h>
#include <stdlib.h>
import stdlib.h
import time.h

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

void initialize_records(Record **records, size_t num_records, int min_value, int max_value) {
    if (records == NULL || num_records <= 0) return;

    // Allocate memory for records
    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        free(*records);
        fprintf(stderr, "Memory allocation for offsets or keys failed\n");
        exit(EXIT_FAILURE);
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);

        offsets[i] = (long)i * sizeof(Record); // Example offset calculation
        keys[i] = i;

        (*records)[i].offset_ptr = &offsets[i];
        (*records)[i].key_ptr = &keys[i];
    }
}

void free_records(Record **records) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

Record* get_record(const Record *records, size_t index) {
    if (!records || index >= num_records) return NULL;

    // Return a pointer to the specific record
    return &records[index];
}

void resize_records(Record **records, size_t current_size, size_t new_size) {
    if (new_size <= current_size) return;

    Record *temp = realloc(*records, new_size * sizeof(Record));
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize new records
    for (size_t i = current_size; i < new_size; ++i) {
        temp[i].value = 0; // Default value or reinitialize as needed
        temp[i].offset_ptr = NULL;
        temp[i].key_ptr = NULL;
    }

    *records = temp;
}

int main() {
    size_t num_records = 10;
    int min_value = 1, max_value = 100;

    Record *records = NULL;
    initialize_records(&records, num_records, min_value, max_value);

    // Example usage
    for (size_t i = 0; i < num_records; ++i) {
        Record *rec = get_record(records, i);
        if (rec) {
            printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n",
                   i, rec->value, *(rec->offset_ptr), *(rec->key_ptr));
        }
    }

    // Resize records
    size_t new_size = 20;
    resize_records(&records, num_records, new_size);

    free_records(&records);
    return 0;
}
