#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function prototypes
void display_help(void);
void display_manpage(void);
void process_file(const char *filename, int print_line_numbers, const char *output_filename);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        display_help();
        return EXIT_FAILURE;
    }

    int print_line_numbers = 0;
    char *output_filename = NULL;
    int show_manpage = 0;

    // Parse command line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-cs") == 0) {
            print_line_numbers = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_filename = argv[++i];
        } else if (strcmp(argv[i], "--manpage") == 0) {
            show_manpage = 1;
        } else if ((strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0)) {
            display_help();
            return EXIT_SUCCESS;
        } else {
            // Assume input file is the first unprocessed argument
            process_file(argv[i], print_line_numbers, output_filename);
            break;
        }
    }

    if (show_manpage) {
        display_manpage();
    }

    return EXIT_SUCCESS;
}

void display_help(void) {
    printf("Usage: progname [options] <input_file>\n");
    printf("Options:\n");
    printf("  -cs          Print each line with its corresponding line number.\n");
    printf("  -o <file>    Redirect output to a specified file.\n");
    printf("  --manpage    Display detailed usage information.\n");
    printf("  -h, --help   Show this help message and exit.\n");
}

void display_manpage(void) {
    printf("Progname Manual\n");
    printf("Version: 1.0\n\n");
    printf("SYNOPSIS\n");
    printf("  progname [options] <input_file>\n\n");
    printf("DESCRIPTION\n");
    printf("  Progname processes an input file line by line.\n");
    printf("\nOPTIONS\n");
    printf("  -cs          Print each line with its corresponding line number.\n");
    printf("  -o <file>    Redirect output to a specified file.\n");
    printf("  --manpage    Display detailed usage information.\n");
    printf("  -h, --help   Show this help message and exit.\n\n");
}

void process_file(const char *filename, int print_line_numbers, const char *output_filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    FILE *out = stdout;
    if (output_filename) {
        out = fopen(output_filename, "w");
        if (!out) {
            perror("Error opening output file");
            fclose(file);
            return;
        }
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    long line_number = 1;
    long total_lines = 0;

    // Count lines first to set progress indicators
    fseek(file, 0, SEEK_SET);
    while ((read = getline(&line, &len, file)) != -1) {
        ++total_lines;
    }

    fseek(file, 0, SEEK_SET);

    if (print_line_numbers) printf("Processing %s...\n", filename);

    long processed_lines = 0;
    while ((read = getline(&line, &len, file)) != -1) {
        // Process line
        if (print_line_numbers)
            fprintf(out, "%ld: %s", line_number++, line);
        else
            fputs(line, out);

        ++processed_lines;

        // Progress indicator every 10%
        long progress = (long)((double)processed_lines / total_lines * 100.0);
        if ((progress % 10 == 0) && (progress != 0)) {
            printf("\rProgress: %ld%%", progress);
        }

        fflush(out);
    }

    // Final progress
    printf("\rProgress: 100%%\n");

    free(line);
    fclose(file);
    if (output_filename) fclose(out);

    printf("Processing of '%s' completed.\n", filename);
}
