#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define BUFFER_SIZE 1024

// Function to resolve hostname to IP address
char* resolve_hostname(const char *hostname) {
    struct hostent *host_entry;
    struct in_addr **addr_list;

    // Get the host information
    if ((host_entry = gethostbyname(hostname)) == NULL) {
        herror("DNS resolution failed");
        return NULL;
    }

    addr_list = (struct in_addr **)host_entry->h_addr_list;

    char *ip_address = malloc(INET_ADDRSTRLEN);
    if (!ip_address) {
        perror("Memory allocation for IP address failed");
        return NULL;
    }

    // Convert the first IP address to a string
    inet_ntop(AF_INET, *addr_list[0], ip_address, INET_ADDRSTRLEN);

    // Free host_entry as we don't need it anymore
    freehostent(host_entry);

    return ip_address;
}

// Function to calculate average of numerical values in a line
double calculate_average(char* line) {
    char *token = strtok(line, " ");
    double sum = 0.0, count = 0;

    while (token != NULL) {
        // Skip the first token as it's assumed to be hostname
        if (count > 0) {
            sum += atof(token);
        }
        token = strtok(NULL, " ");
        count++;
    }

    return (count > 1) ? (sum / (count - 1)) : 0.0;
}

int main() {
    char buffer[BUFFER_SIZE];
    FILE *file = fopen("network_config.txt", "r");

    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    while (fgets(buffer, sizeof(buffer), file)) {
        // Remove newline character
        buffer[strcspn(buffer, "\n")] = '\0';

        char *hostname = strtok(buffer, " ");
        if (!hostname) continue;

        char* ip_address = resolve_hostname(hostname);
        if (!ip_address) continue;

        double average = calculate_average(buffer);

        printf("%s,%f\n", ip_address, average);

        free(ip_address);  // Free dynamically allocated memory for IP address
    }

    fclose(file);

    return EXIT_SUCCESS;
}
