#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a log level enumeration
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

// Structure for a logging entry
typedef struct {
    time_t timestamp;
    LogLevel logLevel;
    char *message;
} LogEntry;

// Dynamic array structure to hold log entries
typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t count;
} LogManager;

// Function prototypes
LogManager* create_log_manager(size_t initial_capacity);
void free_log_manager(LogManager *manager);
int append_log_entry(LogManager *manager, LogLevel level, const char *message);
void rotate_logs(LogManager *manager);

// Create a log manager with an initial capacity
LogManager* create_log_manager(size_t initial_capacity) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    if (!manager) return NULL;

    manager->entries = (LogEntry **)calloc(initial_capacity, sizeof(LogEntry *));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    return manager;
}

// Free the log manager and its resources
void free_log_manager(LogManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]) {
            free(manager->entries[i]->message);
            free(manager->entries[i]);
        }
    }
    free(manager->entries);
    free(manager);
}

// Append a new log entry to the log manager
int append_log_entry(LogManager *manager, LogLevel level, const char *message) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LogEntry **new_entries = (LogEntry **)realloc(manager->entries, new_capacity * sizeof(LogEntry *));
        if (!new_entries) return -1; // Memory allocation failed

        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) return -2; // Memory allocation failed

    entry->timestamp = time(NULL);
    entry->logLevel = level;

    size_t message_length = strlen(message) + 1;
    entry->message = (char *)malloc(message_length);
    if (!entry->message) {
        free(entry);
        return -3; // Memory allocation failed
    }

    strcpy(entry->message, message);

    manager->entries[manager->count++] = entry;

    // Rotate logs if needed
    rotate_logs(manager);

    return 0;
}

// Rotate logs to manage disk space usage (stub for actual implementation)
void rotate_logs(LogManager *manager) {
    // Implement log rotation logic here
    // This could involve writing old entries to disk and freeing memory,
    // or compressing older logs, etc.
}

int main() {
    LogManager *log_manager = create_log_manager(10);
    if (!log_manager) {
        fprintf(stderr, "Failed to create log manager\n");
        return EXIT_FAILURE;
    }

    append_log_entry(log_manager, LOG_INFO, "This is an info message.");
    append_log_entry(log_manager, LOG_ERROR, "This is an error message.");

    // Clean up
    free_log_manager(log_manager);
    return 0;
}
```

### Design Choices

1. **Dynamic Array for Scalability**: The log entries are stored in a dynamic array that doubles its capacity when full. This approach balances between memory usage and performance, providing amortized O(1) time complexity for append operations.

2. **Memory Management**: Each `LogEntry` is dynamically allocated to minimize initial memory usage and allow flexibility as the number of logs grows. Memory allocation failures are handled gracefully by returning error codes without crashing the system.

3. **Log Rotation**: A stub function `rotate_logs()` is included to manage log storage, ensuring that disk space limits are respected. This would typically involve writing old entries to disk and freeing memory.

4. **Integration with Logging Frameworks**: The design supports various log levels and can be extended with hooks for additional features, such as different output formats or destinations.

5. **Performance Considerations**: By using dynamic allocation for messages, the system avoids excessive memory usage from fixed-size buffers, especially when handling varying message lengths. This choice is crucial in environments with limited resources.']

