import os
import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
import time

# Configure logging
logging.basicConfig(filename='file_processing.log', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def calculate_sha256(file_path):
    """Calculate the SHA-256 hash of a file by reading it in chunks."""
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):  # Read in 8KB chunks
                sha256.update(chunk)
        return sha256.hexdigest()
    except Exception as e:
        logging.error(f"Error processing file {file_path}: {e}")
        return None

def process_file(file_path, results):
    """Process a single file and store its SHA-256 hash."""
    digest = calculate_sha256(file_path)
    if digest is not None:
        results[file_path] = digest
    else:
        logging.error(f"Failed to calculate hash for {file_path}")

def validate_with_service(file_hash):
    """Simulate validation with an external service, handling network latency and failures."""
    try:
        # Simulating network call with a sleep
        time.sleep(0.1)
        if file_hash.startswith('a'):  # Example condition that might fail
            raise ConnectionError("Service unavailable")
    except Exception as e:
        logging.error(f"Validation failed for hash {file_hash}: {e}")

def process_directory(directory_path):
    """Process all files in a directory and calculate their SHA-256 hashes."""
    results = {}
    num_threads = min(32, os.cpu_count() + 4)  # Adjust the number of threads based on system resources

    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = []

        for root, _, files in os.walk(directory_path):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                futures.append(executor.submit(process_file, file_path, results))

        # Wait for all threads to complete
        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logging.error(f"Error in thread execution: {e}")

    # Validate hashes with the external service
    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = [executor.submit(validate_with_service, digest) for _, digest in results.items()]

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logging.error(f"Error during validation: {e}")

    # Summary
    successful_ops = len(results)
    failed_ops = sum(1 for file_path, digest in results.items() if not validate_with_service(digest))

    logging.info(f"Processing complete. Successful operations: {successful_ops}. Failed operations: {failed_ops}.")

# Example usage
if __name__ == "__main__":
