import os
import json
import logging
from typing import Dict, Any
from requests.exceptions import RequestException
import yaml
import time
from functools import lru_cache

# Setup Logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

CONFIG_FILE_PATH = "config.yaml"
REMOTE_CONFIG_URL = "https://example.com/config/latest"
VALIDATION_SCHEMA = {"ENV_VAR_1": str, "ENV_VAR_2": int}  # Example schema for validation

def fetch_remote_config() -> Dict[str, Any]:
    """Fetch the latest configuration from a remote repository."""
    try:
        response = requests.get(REMOTE_CONFIG_URL)
        response.raise_for_status()
        return response.json()
    except RequestException as e:
        logger.error(f"Failed to fetch remote config: {e}")
        raise

@lru_cache(maxsize=1)  # Cache the latest fetched configuration
def get_cached_remote_config() -> Dict[str, Any]:
    """Get cached remote configuration."""
    return fetch_remote_config()

def validate_environment_vars(env_vars: Dict[str, str]) -> bool:
    """Validate environment variables against a predefined schema."""
    for key, expected_type in VALIDATION_SCHEMA.items():
        if key not in env_vars or not isinstance(env_vars[key], expected_type):
            logger.error(f"Invalid type for {key}: Expected {expected_type}, got {type(env_vars[key])}")
            return False
    return True

def fetch_env_from_api() -> Dict[str, str]:
    """Fetch environment variables from an external API."""
    try:
        response = requests.get("https://example.com/api/env-vars")
        response.raise_for_status()
        env_vars = response.json()

        if validate_environment_vars(env_vars):
            return env_vars
        else:
            logger.error("Environment variables validation failed.")
            raise ValueError("Invalid environment variables received from API.")
    except RequestException as e:
        logger.error(f"Failed to fetch environment variables: {e}")
        raise

def read_local_config() -> Dict[str, Any]:
    """Read the local configuration file."""
    if not os.path.exists(CONFIG_FILE_PATH):
        return {}
    with open(CONFIG_FILE_PATH, 'r') as f:
        try:
            config = yaml.safe_load(f)
        except yaml.YAMLError as e:
            logger.error(f"Failed to parse config file: {e}")
            raise
    return config

def write_local_config(config_data: Dict[str, Any]):
    """Write the updated configuration back to the local file."""
    with open(CONFIG_FILE_PATH, 'w') as f:
        try:
            yaml.safe_dump(config_data, f)
        except yaml.YAMLError as e:
            logger.error(f"Failed to write config file: {e}")
            raise

def update_config(env_vars: Dict[str, str], remote_config: Dict[str, Any]):
    """Update the local configuration file with new environment variables and remote config."""
    local_config = read_local_config()

    # Conditional updates based on current state
    if local_config.get('version') != remote_config.get('version'):
        local_config.update(remote_config)

    local_config['environment'] = env_vars

    write_local_config(local_config)

def main():
    while True:
        try:
            env_vars = fetch_env_from_api()
            remote_config = get_cached_remote_config()

            update_config(env_vars, remote_config)
            logger.info("Configuration updated successfully.")

            # Sleep to minimize API call frequency
            time.sleep(300)  # Example: check every 5 minutes

        except Exception as e:
            logger.error(f"An error occurred: {e}")
            # Optionally sleep before retrying on failure
            time.sleep(60)

if __name__ == "__main__":
    main()
```

This script fetches environment variables from an external API, validates them against a predefined schema, and updates the local configuration file based on conditions such as version changes. It caches the remote configuration to minimize API calls and handles errors gracefully with logging. Sensitive information should be handled securely, possibly through encryption or secure storage practices not covered in this script for simplicity.']

