    return false;
}

// Function to check if a block cipher is available
bool is_block_cipher_available(const char *name) {
    // Placeholder for actual availability checks
    if (strcmp(name, "AES") == 0) return true;
    return false;
}

// Function to create and initialize a CryptoFunction struct
CryptoFunction* create_crypto_function(const char *name, void (*function)(void)) {
    CryptoFunction *cf = malloc(sizeof(CryptoFunction));
    if (!cf) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    cf->name = name;
    cf->function = function;
    return cf;
}

// Function to get available cryptographic functions
CryptoFunction** get_available_crypto_functions(size_t *count) {
    // Define supported algorithms
    const char *hash_algos[] = {"SHA-256"};
    const char *block_ciphers[] = {"AES"};

    // Check availability and create list of available functions
    size_t total_count = 0;
    size_t hash_count = sizeof(hash_algos) / sizeof(hash_algos[0]);
    size_t block_cipher_count = sizeof(block_ciphers) / sizeof(block_ciphers[0]);

    for (size_t i = 0; i < hash_count; ++i) {
        if (is_hash_function_available(hash_algos[i])) {
            total_count++;
        }
    }

    for (size_t i = 0; i < block_cipher_count; ++i) {
        if (is_block_cipher_available(block_ciphers[i])) {
            total_count++;
        }
    }

    CryptoFunction **functions = malloc(total_count * sizeof(CryptoFunction *));
    if (!functions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t index = 0;

    for (size_t i = 0; i < hash_count; ++i) {
        if (is_hash_function_available(hash_algos[i])) {
            functions[index++] = create_crypto_function(hash_algos[i], sha256_example);
        }
    }

    for (size_t i = 0; i < block_cipher_count; ++i) {
        if (is_block_cipher_available(block_ciphers[i])) {
            functions[index++] = create_crypto_function(block_ciphers[i], aes_example);
        }
    }

    *count = total_count;
    return functions;
}

// Example usage
int main() {
    size_t count;
    CryptoFunction **functions = get_available_crypto_functions(&count);

    for (size_t i = 0; i < count; ++i) {
        printf("Available: %s\n", functions[i]->name);
        // Call the function pointer if needed
        functions[i]->function();
        free(functions[i]); // Clean up each struct
    }

    free(functions); // Clean up array of pointers
    return 0;
}
