            let mut cache = self.cache.lock().unwrap();
            for config in value.into_iter() {
                cache.insert(config.name.clone(), config);
            }
        }

        Ok(())
    }

    async fn load_and_validate_configs(&self) -> io::Result<Vec<NetworkConfig>> {
        if let Some(last_updated) = &self.last_updated {
            if Duration::now().sub(*last_updated) < Duration::from_secs(300) { // Cache expiry time
                return Ok(self.cache.lock().unwrap().values().cloned().collect());
            }
        }

        let mut file = File::open(&self.config_path)?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;

        if let Ok(value) = serde_json::from_str::<Vec<NetworkConfig>>(&contents) {
            let valid_configs: Vec<_> = value.into_iter().filter(|config| config.validate()).collect();

            // Update cache
            self.cache.lock().unwrap().clear();
            for config in &valid_configs {
                self.cache.lock().unwrap().insert(config.name.clone(), config.clone());
            }

            self.last_updated = Some(Duration::now());

            info!("Loaded and validated configurations successfully.");

            Ok(valid_configs)
        } else {
            error!("Failed to parse JSON or validation errors occurred.");
            Err(io::Error::new(io::ErrorKind::InvalidData, "JSON parsing failed"))
        }
    }

    async fn generate_yaml(&self) -> io::Result<String> {
        let configs = self.load_and_validate_configs().await?;

        let yaml_vec: Vec<Yaml> = configs.into_iter().map(|config| {
            let mut map = YamlMap::new();
            map.insert("name".into(), config.name.clone().into());
            map.insert("ip_address".into(), config.ip_address.clone().into());
            map.insert("port".into(), config.port.to_string().into());

            Yaml::Map(map)
        }).collect();

        let mut string = String::new();
        {
            let emitter = YamlEmitter::with_out(&mut string);
            emitter.dump(Yaml::Array(yaml_vec))?;
        }

        Ok(string)
    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    // Setup logging
    env_logger::Builder::new()
        .filter_level(log::LevelFilter::Info) // Adjust level based on environment
        .init();

    let config_manager = ConfigManager {
        cache: Arc::new(Mutex::new(HashMap::new())),
        config_path: "path/to/config.json".to_string(),
        last_updated: None,
    };

    loop {
        if let Err(e) = config_manager.fetch_and_update().await {
            warn!("Failed to fetch updated network parameters: {}", e);
        }

        if let Ok(yaml_output) = config_manager.generate_yaml().await {
            println!("{}", yaml_output);  // Output YAML for deployment
        }

        sleep(Duration::from_secs(300)).await;  // Polling interval
    }
}
```

