namespace LoggingSystem {

    enum class LogLevel {
        DEBUG,
        INFO,
        WARN,
        ERROR
    };

    struct LogConfig {
        LogLevel level = LogLevel::INFO;
        std::string filePath;
        size_t maxFileSize = 10 * 1024 * 1024; // Default to 10 MB
    };

    class Logger {
    public:
        static std::map<std::string, LogConfig> configs;

        Logger(const std::string& subsystem) : subsystem_(subsystem), logStream_(nullptr) {
            auto it = configs.find(subsystem_);
            if (it != configs.end()) {
                config_ = it->second;
                openLogFile();
            }
        }

        ~Logger() {
            if (logStream_) {
                flushBuffer();
                logStream_->close();
            }
        }

        void setLogLevel(LogLevel level) {
            std::lock_guard<std::mutex> lock(mutex_);
            config_.level = level;
        }

        void setFilePath(const std::string& path) {
            std::lock_guard<std::mutex> lock(mutex_);
            config_.filePath = path;
            openLogFile();
        }

        void log(LogLevel level, const std::string& message) {
            if (level < config_.level) return;

            std::lock_guard<std::mutex> lock(mutex_);

            auto timestamp = getCurrentTimestamp();
            auto formattedMessage = formatMessage(level, timestamp, message);

            buffer_.push_back(formattedMessage);
            writeBuffer();

            // Also log to console
            std::cout << formattedMessage << std::endl;
        }

    private:
        std::string subsystem_;
        LogConfig config_;
        std::ofstream* logStream_ = nullptr;
        std::vector<std::string> buffer_;
        std::mutex mutex_;

        void openLogFile() {
            if (logStream_) {
                logStream_->close();
            }
            logStream_ = new std::ofstream(config_.filePath, std::ios_base::app);
            if (!logStream_->is_open()) {
                logStream_ = nullptr;
            } else {
                rotateLogFileIfNeeded();
            }
        }

        void writeBuffer() {
            for (const auto& msg : buffer_) {
                if (logStream_) {
                    *logStream_ << msg << std::endl;
                }
                flushLog();
            }
            buffer_.clear();
        }

        void flushLog() {
            if (logStream_) {
                logStream_->flush();
            }
        }

        void rotateLogFileIfNeeded() {
            if (!logStream_) return;

            logStream_->seekp(0, std::ios_base::end);
            if (logStream_->tellp() >= config_.maxFileSize) {
                logStream_->close();
                std::string newFilePath = config_.filePath + ".1";
                std::rename(config_.filePath.c_str(), newFilePath.c_str());
                openLogFile();
            }
        }

        void flushBuffer() {
            if (!buffer_.empty()) {
                writeBuffer();
            }
        }

        static std::string getCurrentTimestamp() {
            // Implement timestamp logic
            return "2023-10-05 12:34:56";
        }

        static std::string formatMessage(LogLevel level, const std::string& timestamp, const std::string& message) {
            static std::map<LogLevel, std::string> levelStrings = {
                { LogLevel::DEBUG, "[DEBUG]" },
                { LogLevel::INFO,  "[INFO]" },
                { LogLevel::WARN,  "[WARN]" },
                { LogLevel::ERROR, "[ERROR]" }
            };
            return "[" + timestamp + "] " + levelStrings[level] + " " + message;
        }

    public:
        static void updateConfig(const std::string& subsystem, const LogConfig& config) {
            configs[subsystem] = config;
        }
    };

    // Static member initialization
    std::map<std::string, LogConfig> Logger::configs;

} // namespace LoggingSystem

int main() {
    using namespace LoggingSystem;

    LogConfig config;
    config.level = LogLevel::DEBUG;
    config.filePath = "app.log";
    updateConfig("main", config);

    Logger logger("main");
    logger.log(LogLevel::INFO, "Application started.");
    logger.log(LogLevel::ERROR, "An error occurred.");

    return 0;
}
```']

