using System.Xml.Linq;

public class ConfigParser
{
    public List<string> ParseAndCreateDirectories(string xmlFilePath, string elementName, string baseDirectory, string envVarName)
    {
        var directoriesCreated = new List<string>();
        var warnings = new List<string>();

        try
        {
            if (!File.Exists(xmlFilePath))
                return directoriesCreated;

            XElement rootElement = XElement.Load(xmlFilePath);
            IEnumerable<XElement> elements = rootElement.Descendants(elementName);

            bool elementFound = false;
            foreach (var element in elements)
            {
                if (!elementFound)
                {
                    string dirPath = Path.Combine(baseDirectory, element.Value);

                    try
                    {
                        if (!Directory.Exists(dirPath))
                        {
                            EnsureParentDirectoryExists(baseDirectory);
                            Directory.CreateDirectory(dirPath);

                            SetEnvironmentVariableIfNecessary(envVarName, dirPath);
                            directoriesCreated.Add(dirPath);
                            elementFound = true;
                        }
                    }
                    catch (UnauthorizedAccessException)
                    {
                        Task.Run(() => CreateDirectoryAsyncWithRetry(dirPath)).Wait();
                        directoriesCreated.Add(dirPath); // Assume success if async succeeds
                    }
                }
                else
                {
                    warnings.Add($"Warning: Multiple instances of '{elementName}' found. Using first occurrence.");
                }
            }

            if (!elementFound)
            {
                Console.WriteLine($"Element '{elementName}' not found in XML configuration file.");
            }
        }
        catch (Exception ex)
        {
            warnings.Add($"Error processing XML file: {ex.Message}");
        }

        foreach (var warning in warnings)
        {
            Console.WriteLine(warning);
        }

        return directoriesCreated;
    }

    private void EnsureParentDirectoryExists(string parentPath)
    {
        string directory = Path.GetDirectoryName(parentPath) ?? parentPath;

        if (!Directory.Exists(directory))
        {
            try
            {
                Directory.CreateDirectory(directory);
            }
            catch (UnauthorizedAccessException ex)
            {
                Task.Run(() => CreateDirectoryAsyncWithRetry(directory)).Wait();
            }
        }
    }

    private void SetEnvironmentVariableIfNecessary(string envVarName, string value)
    {
        if (!string.IsNullOrEmpty(Environment.GetEnvironmentVariable(envVarName)))
            return;

        Environment.SetEnvironmentVariable(envVarName, value);
    }

    private async Task CreateDirectoryAsyncWithRetry(string path)
    {
        await Task.Run(() =>
        {
            int retryCount = 5;
            for (int i = 0; i < retryCount; i++)
            {
                try
                {
                    if (!Directory.Exists(path))
                        Directory.CreateDirectory(path);
                    break;
                }
                catch (UnauthorizedAccessException)
                {
                    // Log or handle permission issue if needed.
                    await Task.Delay(100); // Wait before retrying
                }
            }
        });
    }
}
