import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;
import java.util.logging.Logger;

public class StringHasher {
    private static final Logger logger = Logger.getLogger(StringHasher.class.getName());

    public Map<String, String> generateSHA256Hashes(Set<String> inputStrings) {
        Map<String, String> hashMap = new ConcurrentHashMap<>();

        inputStrings.parallelStream().forEach(inputString -> {
            try {
                if (inputString != null && !inputString.isEmpty()) {
                    MessageDigest digest = MessageDigest.getInstance("SHA-256");
                    byte[] encodedhash = digest.digest(inputString.getBytes(java.nio.charset.StandardCharsets.UTF_8));

                    StringBuilder hashStringBuilder = new StringBuilder();
                    for (byte b : encodedhash) {
                        String hexString = Integer.toHexString(0xff & b);
                        if (hexString.length() == 1) hashStringBuilder.append('0');
                        hashStringBuilder.append(hexString);
                    }

                    // Ensure no collisions occur by checking existing keys
                    synchronized (hashMap) {
                        String currentHash = hashStringBuilder.toString();
                        int attempts = 0;
                        while (hashMap.containsValue(currentHash)) {
                            currentHash = generateUniqueHash(inputString, encodedhash, attempts++);
                        }
                        hashMap.put(inputString, currentHash);
                    }
                } else {
                    logger.warning("Encountered an empty or null string: " + inputString);
                }
            } catch (NoSuchAlgorithmException e) {
                logger.severe("SHA-256 Algorithm not found: " + e.getMessage());
            } catch (Exception e) {
                logger.severe("Error processing string: " + inputString + ", Error: " + e.getMessage());
            }
        });

        return hashMap;
    }

    private String generateUniqueHash(String originalString, byte[] encodedhash, int attemptCount) {
        StringBuilder newStringBuilder = new StringBuilder();
        newStringBuilder.append(Integer.toHexString(attemptCount));

        for (byte b : encodedhash) {
            newStringBuilder.append(Integer.toHexString(0xff & b));
        }

        return newStringBuilder.toString();
    }

    public static void main(String[] args) {
        StringHasher hasher = new StringHasher();
        Set<String> sampleData = new HashSet<>();
        // Add test data to sampleData set

        Map<String, String> hashedMap = hasher.generateSHA256Hashes(sampleData);

        // Output or further process the hashedMap
    }
}
```

### Explanation:
- The method `generateSHA256Hashes` accepts a `Set` of strings and returns a map with each string mapped to its SHA-256 hash.
- We use `ConcurrentHashMap` for thread safety during parallel processing.
- Java's `parallelStream()` is utilized for processing the dataset in parallel, enhancing performance on multi-core systems.
- The code handles exceptions like missing algorithms or other runtime errors and logs them appropriately.
- The method checks for hash collisions by ensuring no two strings have the same hash value using a synchronization block.
- For collision resolution, an additional unique identifier based on the attempt count is appended to ensure uniqueness without altering the original string.']

