    public PageContentService(IMemoryCache cache, IHtmlUpdateService htmlUpdateService, IMessageQueue messageQueue)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _htmlUpdateService = htmlUpdateService ?? throw new ArgumentNullException(nameof(htmlUpdateService));
        _messageQueue = messageQueue ?? throw new ArgumentNullException(nameof(messageQueue));
    }

    public async Task<(bool needsRefresh, string response)> UpdatePageContentAsync(string pageSectionId, string elementId, string newHtmlContent)
    {
        if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId))
            return (false, "Invalid section or element ID.");

        if (newHtmlContent == null || newHtmlContent.Length > 10000) // Assuming a max length constraint
            return (false, "HTML content length is not within acceptable limits.");

        var cacheKey = $"{pageSectionId}_{elementId}";

        string currentContent;
        if (!_cache.TryGetValue(cacheKey, out currentContent))
        {
            currentContent = await _htmlUpdateService.GetHtmlContentAsync(pageSectionId, elementId);
            _cache.Set(cacheKey, currentContent, TimeSpan.FromMinutes(5)); // Cache for 5 minutes
        }

        if (!IsFormattingValid(currentContent) || !IsFormattingValid(newHtmlContent))
        {
            return (false, "Current or new HTML content is not in acceptable formatting.");
        }

        var policy = Policy.Handle<Exception>().WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        try
        {
            bool updateSuccessful = await policy.ExecuteAsync(async () =>
            {
                return await _htmlUpdateService.UpdateHtmlContentAsync(pageSectionId, elementId, newHtmlContent);
            });

            if (updateSuccessful)
            {
                _cache.Remove(cacheKey); // Invalidate cache
                _messageQueue.EnqueueChangeLog(new PageContentChangeLog(pageSectionId, elementId));
                return (true, "Content updated successfully.");
            }
        }
        catch (Exception ex)
        {
            await _messageQueue.EnqueueErrorLogAsync(ex);
            // Fallback to preserve existing content in case of failure
        }

        return (false, "Failed to update content. Existing content preserved.");
    }

    private bool IsFormattingValid(string htmlContent)
