["```javascript
const blueslip = require('blueslip');
const { promisify } = require('util');
const os = require('os');

async function manageTests(label, f, maxConcurrentTests, environmentConfig) {
    const execPromise = promisify(setImmediate);

    // Initialize resource management and monitoring
    let activeTestCount = 0;
    const testQueue = [];
    const report = [];

    const runTest = async () => {
        if (activeTestCount >= maxConcurrentTests || testQueue.length === 0) return;

        const { testCase } = testQueue.shift();
        ++activeTestCount;

        try {
            await blueslip.reset(); // Reset mock state
            console.log(`Running ${label}: ${testCase.name}`);

            await testCase.f(environmentConfig); // Execute the test case

            report.push({ name: testCase.name, status: 'passed' });
        } catch (error) {
            report.push({ name: testCase.name, status: 'failed', error: error.message || String(error) });
        } finally {
            --activeTestCount;

            blueslip.reset(); // Ensure mock state is reset after each test
            await execPromise(runTest); // Schedule next test execution
        }
    };

    // Dynamically adjust concurrency based on system load
    const adjustConcurrency = () => {
        const cpuLoad = os.loadavg()[0] / os.cpus().length;

        if (cpuLoad > 0.75 && maxConcurrentTests > 1) {
            --maxConcurrentTests;
        } else if (cpuLoad < 0.5) {
            ++maxConcurrentTests;
        }
    };

    // Load and queue test cases
    const loadTestCases = () => {
        try {
            const module = require(label);
            const testFunctions = Array.isArray(module.tests) ? module.tests : [module.tests];

            for (const test of testFunctions) {
                if (typeof test === 'function') {
                    testQueue.push({ name: test.name || `Test ${testQueue.length + 1}`, f: async (...args) => await promisify(test)(...args) });
                }
            }

            // Start executing tests
            for (let i = 0; i < maxConcurrentTests && testQueue.length > 0; ++i) {
                runTest();
            }
        } catch (error) {
            console.error(`Error loading module ${label}:`, error);
            report.push({ name: `Load Module ${label}`, status: 'failed', error: error.message || String(error) });
        }
    };

    // Start test suite
    loadTestCases();

    const monitorPerformance = () => {
        setInterval(() => {
            adjustConcurrency();
            console.log(`Current concurrency level: ${maxConcurrentTests}, Active tests: ${activeTestCount}`);
        }, 5000); // Adjust every 5 seconds
    };

    monitorPerformance();

    return new Promise((resolve) => {
        const checkCompletion = () => {
            if (testQueue.length === 0 && activeTestCount === 0) {
                resolve(report);
            } else {
                setTimeout(checkCompletion, 100); // Check completion every 100ms
            }
        };

        checkCompletion();
    });
}
```

This implementation efficiently manages test execution by balancing concurrency based on system load and handles both asynchronous tests and proper resource cleanup. It supports detailed reporting of test outcomes while considering performance monitoring for optimization over time."]

['```javascript
function generateFooterWithScripts(scripts) {
    const footer = document.createElement('footer');
    footer.setAttribute('role', 'contentinfo'); // For accessibility

    scripts.forEach(scriptObj => {
        const script = document.createElement('script');

        // Set mandatory properties
        if (typeof scriptObj.innerHTML === 'string') {
            script.textContent = scriptObj.innerHTML;
        }

        // Set optional attributes
        if (scriptObj.type) {
            script.setAttribute('type', scriptObj.type);
        }
        if (scriptObj.charset) {
            script.setAttribute('charset', scriptObj.charset);
        }
        if (typeof scriptObj.async === 'boolean') {
            script.async = scriptObj.async;
        }
        if (typeof scriptObj.defer === 'boolean') {
            script.defer = scriptObj.defer;
        }
        if (scriptObj.id) {
            script.setAttribute('id', scriptObj.id);
        }

        // Assign the script key as a data attribute for internal reference or debugging
        script.setAttribute('data-script-key', scriptObj.key);

        footer.appendChild(script);
    });

    document.body.appendChild(footer);
}

// Example usage:
const scriptsArray = [
    {
        key: 'analytics',
        innerHTML: `console.log("Analytics Script Loaded");`
    },
    {
        key: 'utility',
        type: 'module',
        charset: 'utf-8',
        async: true,
        innerHTML: `export function utilityFunction() { console.log('Utility Function'); }`
    }
];

generateFooterWithScripts(scriptsArray);
```

### Explanation
- **Role Attribute**: The footer is given a role attribute for accessibility.
- **Dynamic Script Creation**: Each script object can have optional attributes, ensuring flexibility.
- **Data Attribute for Key**: A `data-script-key` attribute helps in managing scripts internally.
- **Efficient DOM Manipulation**: Scripts are appended to the footer and then the footer to the body, minimizing reflows.
- **Scalability**: This approach allows easy addition of new script objects without major changes.']

["```javascript
// AngularJS function: refreshDialogFields

function refreshDialogFields(resourceId, url, fieldNamesToRefresh) {
    const dialogFields = getDialogFields(); // Assume this function retrieves all dialog fields.
    const pendingRequests = new Map();

    async function updateField(fieldName) {
        if (!fieldNamesToRefresh.includes(fieldName)) return;

        const key = `${resourceId}-${fieldName}`;
        if (pendingRequests.has(key)) return; // Prevent duplicate requests

        try {
            pendingRequests.set(key, true);
            const response = await sendMessageAndAwaitResponse(resourceName, fieldName);

            if (response.success) {
                updateDialogField(fieldName, response.data); // Assume this updates the field
            }
        } catch (error) {
            console.error(`Failed to refresh ${fieldName}:`, error);
        } finally {
            pendingRequests.delete(key);
        }
    }

    function sendMessageAndAwaitResponse(resourceName, fieldName) {
        return new Promise((resolve, reject) => {
            window.parent.postMessage({ type: 'refreshRequest', resourceName, fieldName }, url);

            const listener = (event) => {
                if (event.source !== window.parent || !event.data.type.startsWith('refreshResponse')) {
                    return;
                }

                const { resourceName: responseResourceName, fieldName: responseFieldName, success, data } = event.data;

                if (
                    resourceName === responseResourceName &&
                    fieldName === responseFieldName
                ) {
                    window.removeEventListener('message', listener);
                    resolve({ success, data });
                }
            };

            window.addEventListener('message', listener);

            // Optional timeout for race condition handling and network latency
            setTimeout(() => {
                window.removeEventListener('message', listener);
                reject(new Error(`Timeout waiting for response to refresh ${fieldName}`));
            }, 5000); // Adjust based on expected response time
        });
    }

    dialogFields.forEach(updateField);

    // Batch update if possible (depends on API/server capability)
}

// C++ function: insertAfterFirstOccurrence

#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& first, const std::string& second) {
    auto it = list.before_begin();
    bool found = false;

    for (auto nextIt = list.begin(); nextIt != list.end() && !found; ++nextIt) {
        if (*nextIt == first) {
            list.insert_after(nextIt, second);
            found = true;
        }
        it = nextIt;
    }

    if (!found) {
        list.push_back(second); // Append at the end if not found
    }
}

// Note: In a concurrent scenario for C++, consider using mutexes or other synchronization mechanisms
// to ensure thread safety when modifying shared data structures.
