// Directory configuration
const config = {
  directoryPath: './scripts',
  maxParallelLoads: 3,
};

// Utility function to log errors
function logError(error) {
  console.error(`Error: ${error.message}`);
}

// Function to dynamically load JavaScript files
async function loadScripts(directoryPath, fileNames, onLoaded) {
  const loadedFiles = new Set();

  async function processFile(fileName, index) {
    if (index >= fileNames.length || loadedFiles.size >= config.maxParallelLoads) return;

    try {
      const filePath = `${directoryPath}/${fileName}`;
      const response = await fetch(filePath);

      if (!response.ok) throw new Error(`Failed to load ${filePath}`);

      const scriptContent = await response.text();
      const blob = new Blob([scriptContent], { type: 'text/javascript' });
      const url = URL.createObjectURL(blob);

      const scriptTag = document.createElement('script');
      scriptTag.src = url;
      scriptTag.onload = () => {
        loadedFiles.delete(url);
        onLoaded(fileName); // Callback when a file is successfully loaded
        processFile(fileNames[index + 1], index + 1); // Load next file
      };

      scriptTag.onerror = () => logError(new Error(`Failed to execute ${filePath}`));
      document.head.appendChild(scriptTag);
    } catch (error) {
      logError(error);
    }

    await processFile(fileNames[index + 1], index + 1); // Try next file in case of error
  }

  for (let i = 0; i < config.maxParallelLoads; i++) {
    processFile(fileNames[i], i);
  }
}

// Function to fetch and modify filenames using C functions
