  try {
    const files = await fetch(`${config.directoryPath}/files.json`).then(res => res.json());

    if (!Array.isArray(files)) throw new Error('Invalid file list');

    await loadScripts(config.directoryPath, files, (loadedFile) => {
      console.log(`Loaded and executed: ${loadedFile}`);
      modifyFilenames([loadedFile]);
    });
  } catch (error) {
    logError(error);
  }
}

// Start the program
