### C Program (`modifyFilename.c`)

```c
#include <stdio.h>
#include <string.h>

void modifyFilename(const char *filename) {
    char new_filename[256];
    int digit_count = 0;

    for (int i = 0; filename[i] != '\0'; i++) {
        if (isdigit(filename[i])) digit_count++;
    }

    const char *file_extension = strrchr(filename, '.');
    if (!file_extension) {
        printf("Invalid file: No extension found\n");
        return;
    }

    snprintf(new_filename, sizeof(new_filename), "%s%d%s", filename, digit_count + 1, file_extension);

    // Ensure uniqueness and validity
    printf("%s\n", new_filename);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    modifyFilename(argv[1]);
    return 0;
}
```

