['```java
import java.util.concurrent.*;
import java.util.List;
import java.util.ArrayList;

public class ServiceManager {

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final LoadBalancer loadBalancer;
    private final MonitoringService monitoringService;
    private final ConfigurationManagement configManagement;
    private final List<ServiceInstance> instances = new CopyOnWriteArrayList<>();

    public ServiceManager(LoadBalancer loadBalancer, MonitoringService monitoringService,
                          ConfigurationManagement configManagement) {
        this.loadBalancer = loadBalancer;
        this.monitoringService = monitoringService;
        this.configManagement = configManagement;
    }

    public void start() {
        scheduler.scheduleAtFixedRate(this::adjustInstances, 0, 1, TimeUnit.MINUTES);
    }

    private void adjustInstances() {
        int requiredInstances = calculateRequiredInstances();
        int currentSize = instances.size();

        if (currentSize < requiredInstances) {
            for (int i = currentSize; i < requiredInstances; i++) {
                startNewInstance();
            }
        } else if (currentSize > requiredInstances) {
            for (int i = 0; i < currentSize - requiredInstances; i++) {
                stopInstance(instances.get(i));
            }
        }

        monitorAndLogHealth();
    }

    private int calculateRequiredInstances() {
        // Logic to determine number of instances based on demand
        return monitoringService.getCurrentDemand();
    }

    private void startNewInstance() {
        ServiceInstance instance = new ServiceInstance(configManagement.getRuntimeParameters());
        instances.add(instance);
        loadBalancer.registerInstance(instance);
        monitoringService.trackInstance(instance.getId(), "STARTED");
        log("Started new instance: " + instance.getId());
    }

    private void stopInstance(ServiceInstance instance) {
        try {
            instance.stop();
            loadBalancer.deregisterInstance(instance.getId());
            instances.remove(instance);
            monitoringService.trackInstance(instance.getId(), "STOPPED");
            log("Stopped instance: " + instance.getId());
        } catch (Exception e) {
            logError("Failed to stop instance: " + instance.getId(), e);
        }
    }

    private void monitorAndLogHealth() {
        for (ServiceInstance instance : instances) {
            if (!instance.isHealthy()) {
                retryOrTerminate(instance);
            }
        }
    }

    private void retryOrTerminate(ServiceInstance instance) {
        int retries = 0;
        while (retries < 3 && !instance.isHealthy()) {
            log("Retrying instance: " + instance.getId());
            try {
                instance.restart();
                retries++;
            } catch (Exception e) {
                logError("Retry failed for instance: " + instance.getId(), e);
            }
        }

        if (!instance.isHealthy()) {
            stopInstance(instance);
            monitoringService.reportFailure(instance.getId());
        }
    }

    private void log(String message) {
        // Flexible logging configuration
        System.out.println(message);  // Replace with appropriate logging framework
    }

    private void logError(String message, Exception e) {
        // Detailed error report for troubleshooting
        System.err.println(message + ": " + e.getMessage());
    }
}

