<?php

require 'vendor/autoload.php';

use Symfony\Component\Yaml\Yaml;
use Dotenv\Dotenv;

class EnvConfigManager {
    private $configCache = [];
    private const CACHE_DURATION = 300; // Cache duration in seconds
    private const CONFIG_PATH = __DIR__ . '/config/';

    public function loadEnvironment($environment) {
        $this->setEnvVarsFromYaml($environment);
        $this->loadVendorAutoloader();
        $this->configureApplication($environment);

        // Initialize Logger
        $this->initLogger();

        // Start fetching environment variable updates from external API
        $this->startAPIMonitoring($environment);
    }

    private function setEnvVarsFromYaml($environment) {
        $cacheKey = "env_{$environment}";

        if (isset($this->configCache[$cacheKey]) && 
            (time() - $this->configCache[$cacheKey]['timestamp']) < self::CACHE_DURATION) {
            $_ENV = array_merge($_ENV, $this->configCache[$cacheKey]['data']);
            return;
        }

        $configPath = self::CONFIG_PATH . "{$environment}.yaml";

        if (!file_exists($configPath)) {
            throw new Exception("Configuration file for environment {$environment} not found.");
        }

        $data = Yaml::parse(file_get_contents($configPath));
        $_ENV = array_merge($_ENV, $data);

        // Cache the configuration
        $this->configCache[$cacheKey] = [
            'timestamp' => time(),
            'data' => $data,
        ];
    }

    private function loadVendorAutoloader() {
        require __DIR__ . '/vendor/autoload.php';
    }

    private function configureApplication($environment) {
        // Application specific configuration can be done here
        echo "Configured for environment: {$environment}\n";
    }

    private function initLogger() {
        // Initialize logger to track configurations and changes
        $logger = new Monolog\Logger('config_logger');
        $fileHandler = new Monolog\Handler\StreamHandler(__DIR__ . '/logs/app.log', Monolog\Logger::INFO);

        $logger->pushHandler($fileHandler);
        $_LOGGER = $logger;
    }

    private function startAPIMonitoring($environment) {
        // Implement the polling mechanism
        while (true) {
            try {
                $this->fetchAndUpdateEnvVarsFromAPI();
            } catch (\Exception $e) {
                echo "Error fetching updates from API: {$e->getMessage()}\n";

                // Fallback strategy
                if (!isset($_ENV['API_FAILOVER_PATH'])) {
                    throw new Exception('External API is unavailable and no fallback path specified.');
                }

                $fallbackConfigPath = self::CONFIG_PATH . $_ENV['API_FAILOVER_PATH'];
                if (file_exists($fallbackConfigPath)) {
                    $data = Yaml::parse(file_get_contents($fallbackConfigPath));
                    $_ENV = array_merge($_ENV, $data);
                } else {
                    throw new Exception('Fallback configuration path not found.');
                }
            }

            sleep(60); // Polling interval in seconds
        }
    }

    private function fetchAndUpdateEnvVarsFromAPI() {
        // Dummy example of fetching from an API
        $apiUrl = $_ENV['CONFIG_API_URL'] ?? 'http://example.com/api/config';

        $response = file_get_contents($apiUrl);

        if ($response === false) {
            throw new Exception('Failed to fetch configuration updates.');
        }

        $data = json_decode($response, true);

        // Update environment variables
        $_ENV = array_merge($_ENV, $data);

        // Log the update
        global $_LOGGER;
        $_LOGGER->info("Environment variables updated from API: " . json_encode($data));
    }
}

try {
    $environment = getenv('APP_ENV') ?: 'development';
    $manager = new EnvConfigManager();
