            return Err(format!("Failed to install dependency {}: {}", dep, e));
        }
    }

    let mut command = Command::new("cargo")
        .arg("build")
        .arg("--manifest-path")
        .arg(format!("{}/Cargo.toml", project.name))
        .args(&project.build_params)
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    match rustc_driver::catch_with_exit_code(move || command.status().map_err(|e| e.to_string())) {
        Ok(status) if status.success() => Ok(()),
        Err(e) => Err(format!("Build failed for {}: {:?}", project.name, e)),
        _ => Err("Unknown build error".into()),
    }
}

fn install_dependency(dep: &str) -> Result<(), String> {
