        // Validate and sanitize input
        if (!$this->validateAndSanitizeInput($userData)) {
            return false;
        }

        // Check for duplicate entries
        if ($this->checkForDuplicateEntries($userData['email'])) {
            return false;
        }

        try {
            // Begin transaction to ensure atomicity
            $this->userService->beginTransaction();

            // Update user profile across distributed services
            $updateResult = $this->userService->updateProfile($userData);

            if (!$updateResult) {
                throw new Exception('Failed to update user profile');
            }

            // Commit the transaction after successful update
            $this->userService->commitTransaction();

            // Log changes asynchronously to prevent bottlenecks
            $this->loggerService->logAsync("User profile updated: " . json_encode($userData));

            return true;
        } catch (Exception $e) {
            // Rollback in case of any error during update
            $this->userService->rollbackTransaction();

            // Log the exception for debugging purposes
            $this->loggerService->logSync("Error updating user profile: " . $e->getMessage());

