<?php

function generateRandomStringAndHashPassword($length, $charset, $password, $hashAlgorithm) {
    // Generate random string
    $randomString = generateRandomString($length, $charset);

    // Hash the password
    $hashedPassword = hashPassword($password, $hashAlgorithm);

    return ['randomString' => $randomString, 'hashedPassword' => $hashedPassword];
