function readAsyncFile($filePath) {
    try {
        $loop = React\EventLoop\Factory::create();
        $filesystem = new React\Filesystem\Filesystem($loop);

        $future = $filesystem->file($filePath)->getContents();

        $contentsPromise = $future->then(
            function ($contents) {
                return (string)$contents;
            },
            function (Exception $e) {
                throw new Exception("File read error: " . $e->getMessage());
            }
        );

        $loop->run();

        return $contentsPromise->wait();
    } catch (Exception $e) {
        echo 'Error: ',  $e->getMessage(), "\n";
        return null;
    }
}

function generateRandomString($length, $charset) {
    if ($length < 1 || strlen($charset) < 1) {
        throw new InvalidArgumentException('Length and charset must be greater than zero.');
    }

    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[random_int(0, strlen($charset) - 1)];
    }

    return $randomString;
}

function hashPassword($password, $algorithm) {
    if (!in_array($algorithm, hash_algos(), true)) {
        throw new InvalidArgumentException('Unsupported hashing algorithm.');
    }

    return password_hash($password, constant("PASSWORD_" . strtoupper($algorithm)));
}

// Example Usage
try {
    $result = generateRandomStringAndHashPassword(10, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', 'mySecretPassword', 'sha256');
    echo "Random String: " . $result['randomString'] . "\n";
    echo "Hashed Password: " . $result['hashedPassword'] . "\n";

    // Reading a file asynchronously
    $fileContents = readAsyncFile('/path/to/your/file.txt');
    if ($fileContents !== null) {
        echo "File Contents: \n" . $fileContents;
    }

} catch (Exception $e) {
