["```javascript
const fetch = require('node-fetch');
const { Readable } = require('stream');

async function generatePEMCertificate(oAuthRequest) {
  const cache = new Map();

  async function fetchData(url) {
    if (cache.has(url)) {
      return cache.get(url);
    }

    try {
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`Failed to fetch ${url}: ${response.statusText}`);
      }

      const dataStream = new Readable();
      dataStream._read = () => {};

      let receivedData = '';
      for await (const chunk of response.body) {
        receivedData += chunk;
      }

      cache.set(url, receivedData);
      return receivedData;
    } catch (error) {
      console.error(`Error fetching data from ${url}:`, error.message);
      throw new Error(`Network or server issue when accessing ${url}`);
    }
  }

  try {
    const [privateKeyUrl, certificateUrl] = [
      oAuthRequest.privateKeyUrl,
      oAuthRequest.certificateUrl
    ];

    const privateKeyPromise = fetchData(privateKeyUrl);
    const certificatePromise = fetchData(certificateUrl);

    await Promise.all([privateKeyPromise, certificatePromise]);

    const privateKey = cache.get(privateKeyUrl);
    const certificate = cache.get(certificateUrl);

    if (!validatePEMData(privateKey) || !validatePEMData(certificate)) {
      throw new Error('Invalid PEM data');
    }

    return `-----BEGIN CERTIFICATE-----\n${formatAsPEMLines(certificate)}\n-----END CERTIFICATE-----`;
  } catch (error) {
    console.error(`Failed to generate PEM certificate: ${error.message}`);
    throw error;
  }
}

function validatePEMData(data) {
  const pemPattern = /^----[A-Z]+-----[\s\S]+?----[A-Z]+-----$/gm;
  return pemPattern.test(data);
}

function formatAsPEMLines(data, lineLength = 64) {
  let formattedData = '';
  for (let i = 0; i < data.length; i += lineLength) {
    formattedData += `${data.substring(i, i + lineLength)}\n`;
  }
  return formattedData.trim();
}
```"]

