### C Library for DNS Resolution

#### `dns_resolver.c`
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_HOSTNAME_LENGTH 256
#define TIMEOUT_SECONDS 5
#define CACHE_SIZE 100

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    struct in_addr ip;
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];
int cache_index = 0;

// Function to hash hostnames for quick lookup
unsigned int hash_hostname(const char *hostname) {
    unsigned long hash = 5381;
    int c;
    while ((c = *hostname++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % CACHE_SIZE;
}

// Function to resolve hostname to IP
int resolve_hostname(const char *hostname, struct in_addr *ip_address) {
    unsigned int index = hash_hostname(hostname);

    // Check cache first
    if (strcmp(dns_cache[index].hostname, hostname) == 0) {
        *ip_address = dns_cache[index].ip;
        return 1; // Cache hit
    }

    struct hostent *host_info = gethostbyname2(hostname, AF_INET);
    if (!host_info) {
        herror("DNS resolution failed");
        return 0; // Error
    }

    // Update cache
    strncpy(dns_cache[index].hostname, hostname, MAX_HOSTNAME_LENGTH);
    dns_cache[index].ip = *(struct in_addr *)host_info->h_addr;

    *ip_address = dns_cache[index].ip;
    return 1; // Success
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    struct in_addr ip_address;
    if (resolve_hostname(argv[1], &ip_address)) {
        printf("IP Address for %s: %s\n", argv[1], inet_ntoa(ip_address));
    } else {
        fprintf(stderr, "Failed to resolve hostname: %s\n", argv[1]);
    }

    return 0;
}
```

### PHP Component for User Authentication via OAuth 2.0

#### `oauth_auth.php`
```php
<?php

require_once 'vendor/autoload.php';

use League\OAuth2\Client\Provider\GenericProvider;
use Psr\Http\Message\ResponseInterface;

// Configure OAuth provider
$provider = new GenericProvider([
    'clientId'                => 'your-client-id',
    'clientSecret'            => 'your-client-secret',
    'redirectUri'             => 'https://your-redirect-uri.com/callback',
    'urlAuthorize'            => 'https://provider-url/authorize',
    'urlAccessToken'          => 'https://provider-url/token',
    'urlResourceOwnerDetails' => 'https://provider-url/resource'
]);

session_start();

// Function to authenticate user
function authenticateUser($code) {
    global $provider;

    try {
        // Obtain an access token using the authorization code grant.
        $accessToken = $provider->getAccessToken('authorization_code', [
            'code' => $code
        ]);

        // Fetch the resource owner details
        $user = $provider->getResourceOwner($accessToken);

        $_SESSION['user'] = $user->toArray();
        $_SESSION['token'] = (string) $accessToken;

    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        exit('Error: ' . $e->getMessage());
    }
}

// Function to check token validity
function isTokenValid() {
    if (!isset($_SESSION['token'])) return false;

    global $provider;
    try {
        // Use the access token to request a new one.
        $accessToken = $provider->getAccessToken('refresh_token', [
            'refresh_token' => $_SESSION['token']->getTokenRefresh()
        ]);

        $_SESSION['token'] = (string) $accessToken; // Update session with new token
    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        return false;
    }

    return true;
}

// Implement rate limiting using a simple counter mechanism
function checkRateLimit($user_id) {
    if (!isset($_SESSION['rate_limit'][$user_id])) {
        $_SESSION['rate_limit'][$user_id] = ['count' => 0, 'timestamp' => time()];
    }

    $current_time = time();
    $time_diff = $current_time - $_SESSION['rate_limit'][$user_id]['timestamp'];

    if ($time_diff > 60) {
        $_SESSION['rate_limit'][$user_id] = ['count' => 1, 'timestamp' => $current_time];
        return true;
    } else if ($_SESSION['rate_limit'][$user_id]['count'] < 10) {
        $_SESSION['rate_limit'][$user_id]['count']++;
        return true;
    }

    return false; // Rate limit exceeded
}

// Example usage:
if (isset($_GET['code'])) {
    authenticateUser($_GET['code']);
}

?>
```

### Considerations

1. **Caching**: DNS responses are cached in the C program to minimize latency.
2. **Scalability**: PHP sessions can be managed by a distributed session handler like Redis for horizontal scalability.
3. **Security**: Use HTTPS for OAuth 2.0 communications and store sensitive information securely.
4. **Rate Limiting**: A simple rate limiting mechanism is implemented in the PHP component.
5. **Flexibility**: Both components are designed to allow integration with additional services as needed.

Ensure proper configuration of environment-specific details like `clientId`, `clientSecret`, etc., for production readiness.']

