#include <iostream>
#include <vector>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <thread>
#include <algorithm>
#include <cstring>

// Define the structure of an OctreeNode.
struct OctreeNode {
    std::atomic<bool> isLeaf;
    char data[64]; // Placeholder for actual data
};

class ThreadSafeOctree {
public:
    ThreadSafeOctree(unsigned int initialCapacity = 8) 
        : capacity(initialCapacity), nodeCount(0) {
        resizeTree(initialCapacity);
    }

    ~ThreadSafeOctree() {
        delete[] nodes;
    }

    void insertNode(int index, const char* data, size_t dataSize) {
        std::unique_lock lock(mutex_);
        if (index < 0 || index >= capacity) throw std::out_of_range("Index out of bounds");

        auto& node = nodes[index];
        if (!node.isLeaf.load()) expandNode(index);

        std::memcpy(node.data, data, dataSize); // Ensure data alignment
    }

    const char* retrieveData(int index) {
        std::shared_lock lock(mutex_);
        if (index < 0 || index >= capacity) throw std::out_of_range("Index out of bounds");

        return nodes[index].isLeaf.load() ? nodes[index].data : nullptr;
    }

    void resizeCapacity(unsigned int newCapacity) {
        std::unique_lock lock(mutex_);
        if (newCapacity <= capacity) return;

        auto* oldNodes = nodes;
        unsigned int oldCapacity = capacity;
        resizeTree(newCapacity);

        // Copy existing data
        for (unsigned int i = 0; i < nodeCount && i < newCapacity; ++i) {
            nodes[i] = std::move(oldNodes[i]);
        }

        delete[] oldNodes;
    }

private:
    void resizeTree(unsigned int newCapacity) {
        auto* newNodes = new OctreeNode[newCapacity];
        memset(newNodes, 0, sizeof(OctreeNode) * newCapacity);

        capacity = newCapacity;
        nodes.swap(newNodes);
    }

    void expandNode(int index) {
        if (index < 0 || index >= capacity) return;

        auto& node = nodes[index];
        node.isLeaf.store(true); // Assume expansion logic sets it as a leaf
    }

    std::vector<OctreeNode> nodes;
    unsigned int capacity;
    size_t nodeCount;
    mutable std::shared_mutex mutex_;
};

int main() {
    ThreadSafeOctree octree(16);

    const char* data = "Example Data";
    octree.insertNode(0, data, strlen(data) + 1);

    try {
        std::cout << "Retrieved: " << octree.retrieveData(0) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
```

This code implements a basic thread-safe octree with dynamic resizing. It uses `std::atomic` for atomic operations on node properties and `std::shared_mutex` to allow concurrent read access while ensuring exclusive write access, which is useful in multi-threaded environments typical of high-performance applications like rendering. This setup provides a solid foundation for extending the structure with additional features or optimizations in future iterations.']

