#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define MAX_EVENTS_PER_SECOND 10000
#define WINDOW_SIZE 60000 // 60 seconds in milliseconds

typedef enum {
    EVENT_TYPE_1,
    EVENT_TYPE_2,
    // Add new event types here
} EventType;

typedef struct {
    uint64_t timestamp; // in milliseconds
    EventType type;
    int impact_score;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
} EventWindow;

// Function to initialize the sliding window
void init_event_window(EventWindow *window, size_t initial_capacity) {
    window->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    window->count = 0;
    window->capacity = initial_capacity;
}

// Function to add an event to the sliding window
void add_event_to_window(EventWindow *window, NetworkEvent event) {
    if (window->count == window->capacity) {
        // Double the capacity of the array
        size_t new_capacity = window->capacity * 2;
        NetworkEvent *new_events = (NetworkEvent *)realloc(window->events, new_capacity * sizeof(NetworkEvent));
        if (new_events) {
            window->events = new_events;
            window->capacity = new_capacity;
        }
    }
    window->events[window->count++] = event;
}

// Function to remove old events from the sliding window
void prune_old_events(EventWindow *window, uint64_t current_time) {
    while (window->count > 0 && current_time - window->events[0].timestamp >= WINDOW_SIZE) {
        memmove(&window->events[0], &window->events[1], (window->count - 1) * sizeof(NetworkEvent));
        window->count--;
    }
}

// Function to calculate the highest impact score
void calculate_highest_impact(EventWindow *window, int *highest_score, EventType *event_type, uint64_t *timestamp) {
    if (window->count == 0) return;

    *highest_score = -1;
    for (size_t i = 0; i < window->count; ++i) {
        if (window->events[i].impact_score > *highest_score) {
            *highest_score = window->events[i].impact_score;
            *event_type = window->events[i].type;
            *timestamp = window->events[i].timestamp;
        }
    }
}

// Function to process network events
void process_network_event(EventWindow *window, NetworkEvent event) {
    uint64_t current_time = (uint64_t)time(NULL) * 1000; // Current time in milliseconds

    prune_old_events(window, current_time);
    add_event_to_window(window, event);

    int highest_score;
    EventType highest_event_type;
    uint64_t highest_timestamp;

    calculate_highest_impact(window, &highest_score, &highest_event_type, &highest_timestamp);

    printf("Highest Impact Score: %d, Event Type: %d, Timestamp: %llu\n", highest_score, highest_event_type, highest_timestamp);
}

int main() {
    EventWindow window;
    init_event_window(&window, 1000); // Initial capacity of 1000 events

    // Simulate adding network events
    for (int i = 0; i < MAX_EVENTS_PER_SECOND * 60; ++i) { // Simulate one minute of events
        NetworkEvent event = {
            .timestamp = (uint64_t)time(NULL) * 1000 + i,
            .type = i % 2, // Alternate between two types for example
            .impact_score = rand() % 100
        };
        process_network_event(&window, event);
    }

    free(window.events);
    return 0;
}
```

### Key Points:
- **Sliding Window**: Uses a dynamic array to manage events within the last minute.
- **Memory Management**: Doubles capacity when needed to handle up to 10,000 events per second efficiently.
- **Pruning**: Removes old events that are outside the sliding window.
- **Impact Calculation**: Finds and prints the highest impact score along with event type and timestamp.']

