using UnityEngine;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private readonly DataFetcher dataFetcher;

    public RandomValueGenerator(int min, int max, DataFetcher dataFetcher)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot exceed maximum value.");
        }

        minValue = min;
        maxValue = max;
        this.dataFetcher = dataFetcher;

        // Initial validation against external data source
        if (!dataFetcher.IsRangeValid(min, max))
        {
            throw new InvalidOperationException("Range not supported by external data source.");
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range((float)minValue, (float)maxValue);
    }

    public int GetRandomInteger()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public void SetRange(int newMin, int newMax)
    {
        if (newMin > newMax)
        {
            throw new ArgumentException("New minimum value cannot exceed new maximum value.");
        }
        minValue = newMin;
        maxValue = newMax;

        // Revalidate range after update
        if (!dataFetcher.IsRangeValid(newMin, newMax))
        {
            throw new InvalidOperationException("Updated range not supported by external data source.");
        }
    }

    public int GetMiddleValue()
    {
        return (minValue + maxValue) / 2;
    }

    public int GetNearestEven()
    {
        int middle = GetMiddleValue();
        return middle % 2 == 0 ? middle : middle - 1;
    }
}

// Example of a DataFetcher class that interacts with an external data source
public class DataFetcher
{
    public bool IsRangeValid(int min, int max)
    {
        // Simulate a check against an external data source
        // For example, checking if the range is within supported limits
        return min >= 0 && max <= 100; // Simplified condition for demonstration
    }
}
