// Robust Asynchronous Reduction Function

/**
 * Processes an array of data streams using asynchronous reduction.
 * @param {Array} streams - Array of objects containing stream data and metadata.
 * @returns {Promise<number>} The reduced result after processing all streams.
 */
async function processStreams(streams) {
    const maxConcurrency = 100;
    const timeoutDuration = 5000; // 5 seconds

    // Helper function to handle timeouts
    async function withTimeout(promise, duration) {
        let timeoutId;
        const timeoutPromise = new Promise((_, reject) => {
            timeoutId = setTimeout(() => reject(new Error('Stream processing timed out')), duration);
        });
        return Promise.race([promise, timeoutPromise]).finally(() => clearTimeout(timeoutId));
    }

    // Helper function to retry a promise up to two times
    async function retryAsyncOperation(operation, retries = 2) {
        for (let attempt = 0; attempt <= retries; attempt++) {
            try {
                return await operation();
            } catch (error) {
                if (attempt === retries) throw error;
            }
        }
    }

    // Simulate processing of each stream
    async function processStream(stream) {
        const { data, metadata } = stream;

        // Define your reduction logic here; this is an example using sum
        return await retryAsyncOperation(() =>
            withTimeout(
                new Promise((resolve) => setTimeout(() => resolve(data.reduce((acc, val) => acc + val, 0)), 1000)),
                timeoutDuration
            )
        );
    }

    // Limit concurrency to maxConcurrency
    const chunkedStreams = [];
    for (let i = 0; i < streams.length; i += maxConcurrency) {
        chunkedStreams.push(streams.slice(i, i + maxConcurrency));
    }

    let result = 0;
    for (const chunk of chunkedStreams) {
        const promises = chunk.map(processStream);
        try {
            const results = await Promise.allSettled(promises);

            results.forEach((resultObj) => {
                if (resultObj.status === 'fulfilled') {
                    result += resultObj.value;
                } else if (resultObj.status === 'rejected') {
                    console.error(`Error processing stream: ${resultObj.reason.message}`);
                }
            });
        } catch (error) {
            console.error('Unexpected error:', error);
        }
    }

    return result;
}

// Tests
(async () => {
    const testStreams = [
        { data: [1, 2, 3], metadata: { timestamp: Date.now() } },
        { data: [4, 5], metadata: { timestamp: Date.now() } },
