// Define a structure to hold configuration data.
typedef struct {
    char **settings; // Dynamic array of settings (key-value pairs)
    int count;       // Number of settings
    pthread_mutex_t mutex; // Mutex for thread-safe access
} ConfigManager;

// Function prototypes
ConfigManager* init_config_manager();
void load_from_file(ConfigManager *manager, const char *filename);
void load_from_env(ConfigManager *manager);
void load_from_args(ConfigManager *manager, int argc, char **argv);
int update_setting(ConfigManager *manager, const char *key, const char *value);
const char* get_setting(const ConfigManager *manager, const char *key);
void free_config_manager(ConfigManager *manager);

// Initialize the configuration manager
ConfigManager* init_config_manager() {
    ConfigManager *manager = malloc(sizeof(ConfigManager));
    if (!manager) {
        perror("Failed to allocate memory for Config Manager");
        return NULL;
    }

    manager->settings = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    load_from_env(manager); // Load settings from environment variables by default
    return manager;
}

// Load settings from a configuration file
void load_from_file(ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    pthread_mutex_lock(&manager->mutex);
    // Assuming each line in the file is a key=value pair
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key && value) {
            update_setting(manager, key, value);
        }
    }
    pthread_mutex_unlock(&manager->mutex);

    fclose(file);
}

// Load settings from environment variables
void load_from_env(ConfigManager *manager) {
    extern char **environ;
    for (char **env = environ; *env != NULL; env++) {
        char *key_value = strdup(*env);
        char *equal_sign = strchr(key_value, '=');

        if (equal_sign) {
            *equal_sign = '\0'; // Split the string into key and value
            update_setting(manager, key_value, equal_sign + 1);
        }

        free(key_value);
    }
}

// Load settings from command-line arguments
void load_from_args(ConfigManager *manager, int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--") == 0) break;

        char *key_value = strdup(argv[i]);
        char *equal_sign = strchr(key_value, '=');

        if (equal_sign) {
            *equal_sign = '\0'; // Split the string into key and value
            update_setting(manager, key_value, equal_sign + 1);
        } else {
            free(key_value); // No valid key-value pair
        }
    }
}

// Update a setting in the configuration manager
int update_setting(ConfigManager *manager, const char *key, const char *value) {
    pthread_mutex_lock(&manager->mutex);

    // Check if the key already exists and update it
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->settings[i], key) == 0) {
            free(manager->settings[++i]); // Free old value
            manager->settings[i] = strdup(value);
            pthread_mutex_unlock(&manager->mutex);
            return 1;
        }
    }

    // If the key does not exist, add it
    char **new_settings = realloc(manager->settings, sizeof(char *) * (manager->count + 2));
    if (!new_settings) {
        perror("Failed to reallocate settings array");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->settings = new_settings;
    manager->settings[manager->count] = strdup(key);
    manager->settings[++manager->count] = strdup(value);

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

// Get a setting from the configuration manager
const char* get_setting(const ConfigManager *manager, const char *key) {
    pthread_mutex_lock((pthread_mutex_t*)&manager->mutex);

    for (int i = 0; i < manager->count; i += 2) { // Step by 2 to access keys only
        if (strcmp(manager->settings[i], key) == 0) {
            const char *value = manager->settings[i + 1];
            pthread_mutex_unlock((pthread_mutex_t*)&manager->mutex);
            return value;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*)&manager->mutex);
    return NULL; // Not found
}

// Free resources used by the configuration manager
void free_config_manager(ConfigManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->count; i++) {
        free(manager->settings[i]);
    }

    free(manager->settings);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
```

This C code implements a basic configuration manager that supports loading settings from files, environment variables, and command-line arguments. It uses a dynamic array to store key-value pairs and provides thread-safe operations with mutex locks for concurrent access. The functions cover initialization, setting updates, retrieval, and cleanup while handling errors and memory allocation gracefully.']

