char* appendSlashIfWithinLimit(const char *input, int size_limit) {
    if (input == NULL || size_limit <= 0) {
        return NULL;
    }

    int input_length = strnlen(input, size_limit);

    // Check for space to add '/'
    if (input_length + 1 > size_limit) {
        return NULL;
    }

    char *new_string = (char *)malloc(size_limit + 1); // Allocate memory
    if (!new_string) {
        return NULL; // Memory allocation failed
    }

    strncpy(new_string, input, input_length);
    new_string[input_length] = '/'; // Add '/'
    new_string[input_length + 1] = '\0'; // Null-terminate

    return new_string;
}
