function traverseDOM(node, selectorFn, results) {
    if (!node || typeof node !== 'object' || !Array.isArray(results)) {
        return; // Handle invalid input gracefully
    }

    if (selectorFn(node)) {
        results.push(node);
    }

    let child = node.firstChild;
    while (child) {
        traverseDOM(child, selectorFn, results); // Recurse into children
        child = child.nextSibling;
    }
}
