```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>

#define MAX_CACHE_SIZE 100

typedef struct CacheEntry {
    char *key;
    char **fields;
    double moving_average;
    struct CacheEntry *prev, *next;
} CacheEntry;

typedef struct {
    CacheEntry *head, *tail;
    size_t size;
    pthread_mutex_t lock;
} LRUCache;

typedef struct LogRecord {
    char **fields;
    int num_fields;
    double moving_average;
    pthread_rwlock_t rwlock;
} LogRecord;

LRUCache cache = {0};

void initialize_cache() {
    pthread_mutex_init(&cache.lock, NULL);
}

CacheEntry *create_cache_entry(char *key, char **fields, double moving_avg) {
    CacheEntry *entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    entry->key = strdup(key);
    entry->fields = fields;
    entry->moving_average = moving_avg;
    entry->prev = entry->next = NULL;
    return entry;
}

void insert_into_cache(char *key, char **fields, double moving_avg) {
    pthread_mutex_lock(&cache.lock);

    // Check if key is already in cache
    CacheEntry *entry = cache.head;
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            pthread_mutex_unlock(&cache.lock);
            return; // Key already present
        }
        entry = entry->next;
    }

    // Create new entry
    CacheEntry *new_entry = create_cache_entry(key, fields, moving_avg);

    if (cache.size >= MAX_CACHE_SIZE) {
        // Evict least recently used item
        CacheEntry *lru = cache.tail;
        if (lru) {
            if (lru->prev) lru->prev->next = NULL;
            cache.tail = lru->prev;
            free(lru->key);
            for (int i = 0; i < new_entry->num_fields; ++i) {
                free(new_entry->fields[i]);
            }
            free(new_entry->fields);
            free(new_entry);
        }
    }

    // Insert at head
    if (!cache.head) {
        cache.head = cache.tail = new_entry;
    } else {
        new_entry->next = cache.head;
        cache.head->prev = new_entry;
        cache.head = new_entry;
    }

    cache.size++;
    pthread_mutex_unlock(&cache.lock);
}

double calculate_moving_average(double *values, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; ++i) {
        sum += values[i];
    }
    return sum / count;
}

void process_log_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[4]; // Example thread pool
    initialize_cache();

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        int num_fields = 0;
        double last_three_values[3] = {0.0};
        LogRecord record;

        // Initialize fields
        record.fields = NULL;
        record.num_fields = 0;

        while (token) {
            record.fields = realloc(record.fields, sizeof(char *) * ++record.num_fields);
            record.fields[record.num_fields - 1] = strdup(token);

            if (num_fields >= 3) {
                for (int i = 2; i > 0; --i)
                    last_three_values[i] = last_three_values[i-1];
                last_three_values[0] = atof(token);
            }

            token = strtok(NULL, ",");
        }

        // Calculate moving average
        record.moving_average = calculate_moving_average(last_three_values, num_fields > 2 ? 3 : num_fields);

        pthread_rwlock_wrlock(&record.rwlock);
        insert_into_cache(line, record.fields, record.moving_average);
        pthread_rwlock_unlock(&record.rwlock);

        // Handle concurrency with threads
        int thread_id = 0; // Example of distributing work to threads
        if (pthread_create(&threads[thread_id++], NULL, process_record, &record) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);
}

void *process_record(void *arg) {
    LogRecord *record = (LogRecord *)arg;

    // Simulate processing
    printf("Processing record with moving average: %.2f\n", record->moving_average);

    // Free resources
    for (int i = 0; i < record->num_fields; ++i) {
        free(record->fields[i]);
    }
    free(record->fields);
    pthread_rwlock_destroy(&record->rwlock);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    process_log_file(argv[1]);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management:** Fields are dynamically allocated and freed to prevent leaks.
- **Moving Average Calculation:** Uses a fixed-size array for the last three values.
- **LRU Cache Implementation:** Maintains cache size with LRU eviction policy using a doubly linked list.
- **Concurrency Handling:** Uses `pthread_rwlock_t` for thread-safe access to records and manages threads for processing.
- **Error Handling:** Graceful handling of file opening errors. Further error checks can be added as needed.
- **Extensibility:** The design allows easy extension by adding more fields or metrics without major rewrites.']

