// Function to generate a timestamp in the format YYYYMMDDHHMMSS
char* generate_timestamp() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    // Allocate memory for the timestamp string
    char *timestamp = (char *)malloc(15 * sizeof(char));
    if (!timestamp) return NULL;

    strftime(timestamp, 15, "%Y%m%d%H%M%S", t);
    return timestamp;
}

// Function to generate a random number between 100 and 999
int generate_random_number() {
    // Seed the random number generator
    srand(time(NULL) ^ getpid());

    return rand() % 900 + 100;  // Ensure it's within [100, 999]
}

// Function to determine new file type based on last character of original name
char get_new_file_type(const char *filename) {
    if (!filename || strlen(filename) == 0)
        return 'A';

    int len = strlen(filename);
    char last_char = filename[len - 1];

    switch (last_char) {
        case 'A': return 'B';
        case 'B': return 'C';
        case 'C': return 'D';
        case 'D': return 'A';
        default: return 'A'; 
    }
}

// Main function to dynamically process the file path
char* modify_file_path(const char *filepath) {
    if (!filepath || strlen(filepath) == 0)
        return NULL;

    // Find the last occurrence of '.' or '/' in the filepath
    const char *last_dot = strrchr(filepath, '.');
    const char *last_slash = strrchr(filepath, '/');

    // Use whichever comes later (or earlier if neither are found)
    const char *base_end;
    if ((last_dot && last_slash) && (last_dot > last_slash))
        base_end = last_dot;
    else
        base_end = last_slash ? last_slash : filepath + strlen(filepath);

    // Calculate the length of the filename without extensions
    size_t basename_length = base_end - filepath;

    // Allocate memory for the new file path
    char *new_filepath = (char *)malloc(basename_length + 20); // Extra space for timestamp, random number, and new extension
    if (!new_filepath) return NULL;

    // Copy the original base of the filepath without any extensions
    strncpy(new_filepath, filepath, basename_length);
    new_filepath[basename_length] = '\0';

    // Generate a timestamp and a random number
    char *timestamp = generate_timestamp();
    int rand_num = generate_random_number();

    if (!timestamp) {
        free(new_filepath);
        return NULL;
    }

    // Determine the new file type based on last character of original filename
    char new_file_type = get_new_file_type(filepath);

    // Append timestamp, random number, and new extension to the base path
    sprintf(new_filepath + basename_length,
            "_%s_%03d.%c", timestamp, rand_num, new_file_type);

    free(timestamp);
    return new_filepath;
}

// Example usage (to be removed or commented out in production code)
int main() {
    const char *original_path = "example/path/to/file.A.txt";
    char *new_path = modify_file_path(original_path);

    if (new_path) {
        printf("Modified path: %s\n", new_path);
        free(new_path);
    } else {
        fprintf(stderr, "Failed to modify file path.\n");
    }

    return 0;
}
