['```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
import <dirent.h>
#include <sys/stat.h>
#include <string.h>

#define MAX_DIR_ENTRIES 1024
#define MAX_FILE_SIZE (10 * 1024 * 1024) // 10 MB for example

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AESCipher;

void handleErrors(void) {
    ERR_print_errors_fp(stderr);
    abort();
}

unsigned char* derive_key(const char* password, int* key_length) {
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    if (!password || !key_length) return NULL;

    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);

    *key_length = SHA256_DIGEST_LENGTH;
    return hash;
}

int aes_init(AESCipher* cipher, const char* password) {
    int key_length;
    unsigned char* derived_key = derive_key(password, &key_length);

    if (!derived_key || EVP_CIPHER_CTX_new(&cipher->ctx)) {
        handleErrors();
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, derived_key, cipher->iv))
        handleErrors();

    memset(derived_key, 0, key_length);
    free(derived_key);

    return 1;
}

void aes_cleanup(AESCipher* cipher) {
    if (cipher->ctx) EVP_CIPHER_CTX_free(cipher->ctx);
}

int initialize_theme_directory(const char* directory_path) {
    struct stat st = {0};

    if (stat(directory_path, &st) == -1) {
        mkdir(directory_path, 0700); // Create directory with user permissions
        if (mkdir(directory_path, 0700) != 0)
            return 0;

        // Set up a default theme if none exists.
        const char* default_theme_path = "default_theme.png";
        FILE* fp = fopen(default_theme_path, "rb");
        if (!fp) return 0;

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        rewind(fp);

        if (fsize > MAX_FILE_SIZE) {
            fclose(fp);
            remove(default_theme_path);
            return 0;
        }

        unsigned char* buffer = malloc(fsize + 1);
        if (!buffer) {
            fclose(fp);
            return 0;
        }

        fread(buffer, 1, fsize, fp);
        fclose(fp);

        // Copy default theme to directory
        char full_path[256];
        snprintf(full_path, sizeof(full_path), "%s/default_theme.png", directory_path);
        FILE* out_fp = fopen(full_path, "wb");
        if (!out_fp) {
            free(buffer);
            return 0;
        }

        fwrite(buffer, 1, fsize, out_fp);
        fclose(out_fp);

        free(buffer);
    }
    return 1;
}

int cache_themes(const char* root_directory) {
    DIR *dir = opendir(root_directory);
    if (!dir)
        return 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", root_directory, entry->d_name);

            struct stat st;
            if (stat(path, &st) == -1)
                continue;

            long fsize = st.st_size;
            if (fsize > MAX_FILE_SIZE)
                continue;

            // Cache the PNG file
            FILE* fp = fopen(path, "rb");
            if (!fp)
                continue;

            fseek(fp, 0, SEEK_END);
            long size = ftell(fp);
            rewind(fp);

            unsigned char *buffer = malloc(size + 1);
            fread(buffer, 1, size, fp);
            fclose(fp);

            // Further processing or caching logic goes here
            free(buffer);
        }
    }

    closedir(dir);
    return 1;
}

