#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>

#define MAX_CONCURRENT_PROCESSES 15
#define RETRY_LIMIT 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void execute_command(char *cmd, int retries) {
    if (retries > RETRY_LIMIT) return;

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        sleep(1); // Backoff before retrying
        execute_command(cmd, retries + 1);
        return;
    }

    if (pid == 0) { // Child process
        execlp("/bin/sh", "sh", "-c", cmd, NULL);
        // If exec fails, print error and exit
        perror("exec");
        exit(EXIT_FAILURE);
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child to finish

        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            printf("Command '%s' failed with exit code %d\n", cmd, WEXITSTATUS(status));
            execute_command(cmd, retries + 1);
        }
    }
}

int async_execute_commands(char *commands[], int num_commands) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    pid_t pids[MAX_CONCURRENT_PROCESSES];
    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
        pids[i] = -1;
    }

    int running_processes = 0;

    for (int i = 0; i < num_commands && running; ++i) {
        while (running_processes >= MAX_CONCURRENT_PROCESSES && running);

        if (!running) break;

        // Find a slot to run new command
        for (int j = 0; j < MAX_CONCURRENT_PROCESSES; ++j) {
            if (pids[j] == -1 || !waitpid(pids[j], NULL, WNOHANG)) {
                pids[j] = fork();
                if (pids[j] == 0) { // Child process
                    execute_command(commands[i], 0);
                    exit(EXIT_SUCCESS);
                } else if (pids[j] > 0) { // Parent process
                    running_processes++;
                } else {
                    perror("fork");
                    return 0;
                }
                break;
            }
        }
    }

    // Wait for remaining processes to complete
    while (running_processes > 0 && running) {
        int status;
        pid_t pid = waitpid(-1, &status, WNOHANG);
        if (pid > 0) {
            for (int j = 0; j < MAX_CONCURRENT_PROCESSES; ++j) {
                if (pids[j] == pid) {
                    pids[j] = -1;
                    running_processes--;
                    break;
                }
            }
        }
    }

    return 1;
}

int main() {
    char *commands[] = {"ls", "sleep 2 && echo Hello", "invalid_command"};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    if (async_execute_commands(commands, num_commands)) {
        printf("All commands started successfully.\n");
    } else {
        printf("Failed to start some commands.\n");
    }

    return 0;
}
