public class WebServerManager
{
    private readonly string _logFilePath = "web_server_log.txt";

    public async Task StartWebServerAsync(string directoryPath, string siteName, int timeoutSeconds, int port, long memoryLimit)
    {
        try
        {
            ValidateDirectory(directoryPath);

            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                Log("Web.config file is missing. Aborting server startup.", LogLevel.Error);
                return;
            }

            EnsureUniqueSiteName(directoryPath, siteName);

            var parameters = CreateStartupParameters(port, memoryLimit);

            using (var cancellationTokenSource = new CancellationTokenSource(TimeSpan.FromSeconds(timeoutSeconds)))
            {
                await StartServerAsync(directoryPath, siteName, parameters, cancellationTokenSource.Token);
            }
        }
        catch (Exception ex)
        {
            Log($"Exception encountered: {ex.Message}", LogLevel.Critical);
        }
    }

    private void ValidateDirectory(string directoryPath)
    {
        if (!Directory.Exists(directoryPath) || !new DirectoryInfo(directoryPath).GetAccessControl().IsContainer())
        {
            throw new DirectoryNotFoundException("The specified directory is invalid or inaccessible.");
        }

        // Additional checks for corruption can be added here.
    }

    private void EnsureUniqueSiteName(string directoryPath, string siteName)
    {
        var existingSites = Directory.GetFiles(directoryPath, "*.config", SearchOption.AllDirectories)
                                     .Select(f => Path.GetFileNameWithoutExtension(f))
                                     .ToList();

        if (existingSites.Contains(siteName, StringComparer.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("Site name conflicts with an existing server entry.");
        }
    }

    private string CreateStartupParameters(int port, long memoryLimit)
    {
        return $"--port {port} --memoryLimit {memoryLimit}";
    }

    private async Task StartServerAsync(string directoryPath, string siteName, string parameters, CancellationToken token)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = "dotnet",
            Arguments = $"run --project \"{directoryPath}\" {parameters}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process { StartInfo = startInfo })
        {
            try
            {
                process.Start();
                await Task.Run(() => process.WaitForExit(), token);

                Log($"Server for site '{siteName}' started successfully.", LogLevel.Info);
            }
            catch (OperationCanceledException)
            {
                Log("Server startup operation timed out.", LogLevel.Warning);
                process.Kill();
            }
            catch (Exception ex)
            {
                Log($"Failed to start server: {ex.Message}", LogLevel.Error);
            }
        }

        CleanupResources(process);
    }

    private void CleanupResources(Process process)
    {
        if (!process.HasExited)
        {
            process.Kill();
        }

        // Add more resource cleanup logic here if necessary.
    }

    private void Log(string message, LogLevel level)
    {
        var timestamp = DateTime.UtcNow.ToString("o");
        var logMessage = $"{timestamp} [{level}] {message}";

        File.AppendAllText(_logFilePath, logMessage + Environment.NewLine);

        // Optionally send logs to a centralized service
    }
}

public enum LogLevel
{
    Info,
    Warning,
    Error,
    Critical
}
