using System.Text;

public struct ConnectionStructure
{
    public Configuration Config;
    public string Title;
    public ConnectionState State;
}

public struct Configuration
{
    public Credentials Credentials;
    public int Timeout;
}

public struct Credentials
{
    // Assume credentials are stored as strings, but could be any type of sensitive data.
    public string Username;
    public string Password;
}

public enum ConnectionState
{
    Active,
    Inactive
}

public delegate bool CallbackFunction(string decryptedMessage);

public static class MessageProcessor
{
    private const int InvalidConfig = -1;
    private const int EmptyTitle = -2;
    private const int InactiveConnection = -3;
    private const int NullCallback = -4;

    public static int ProcessEncryptedMessage(
        string base64EncodedEncryptedMessage,
        ConnectionStructure connection,
        CallbackFunction callback)
    {
        // Validate the configuration object
        if (connection.Config == null || 
            connection.Config.Credentials == null)
        {
            return InvalidConfig;
        }

        // Validate title
        if (string.IsNullOrEmpty(connection.Title))
        {
            return EmptyTitle;
        }

        // Confirm that the connection state is active
        if (connection.State != ConnectionState.Active)
        {
            return InactiveConnection;
        }

        // Check callback function validity
        if (callback == null)
        {
            return NullCallback;
        }

        try
        {
            // Decrypt the message using Triple DES
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
            string decryptedMessage = DecryptTripleDES(encryptedBytes, connection.Config.Credentials.Username, connection.Config.Credentials.Password);

            // Invoke callback with decrypted message
            return callback(decryptedMessage) ? 0 : -5; // Return specific error if callback returns false
        }
        catch (Exception ex)
        {
            // Handle decryption or conversion errors gracefully
            Console.WriteLine($"Error: {ex.Message}");
            return -6;
        }
    }

    private static string DecryptTripleDES(byte[] data, string key, string iv)
    {
        using (var des = new TripleDESCryptoServiceProvider())
        {
            des.Key = Encoding.UTF8.GetBytes(key).Take(des.KeySize / 8).ToArray();
            des.IV = Encoding.UTF8.GetBytes(iv).Take(des.BlockSize / 8).ToArray();
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            using (var decryptor = des.CreateDecryptor())
            {
                using (var ms = new MemoryStream(data))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        using (var sr = new StreamReader(cs))
                        {
                            return sr.ReadToEnd();
                        }
                    }
                }
            }
        }
    }
}
