int process_json_config(const char *json_text, ServiceConfig *config) {
    json_error_t error;
    json_t *root = json_loads(json_text, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    if (!json_is_object(root)) {
        fprintf(stderr, "Root is not a valid JSON object\n");
        json_decref(root);
        return -1;
    }

    // Validate required fields
    const char *service_name = json_string_value(json_object_get(root, "service_name"));
    const char *endpoint = json_string_value(json_object_get(root, "endpoint"));
    json_t *timeout_json = json_object_get(root, "timeout");
    int retry_policy = RETRY_DELAYED; // Default value
    const char *auth_key = NULL;

    if (!service_name || !endpoint || !json_is_integer(timeout_json)) {
        fprintf(stderr, "Missing or invalid required fields\n");
        json_decref(root);
        return -1;
    }

    int timeout = json_integer_value(timeout_json);

    // Validate endpoint
    if (!is_valid_url(endpoint) || !resolve_dns(endpoint)) {
        fprintf(stderr, "Invalid or unresolved endpoint URL\n");
        json_decref(root);
        return -1;
    }

    // Validate timeout
    if (timeout <= 0 || timeout >= 300) {
        fprintf(stderr, "Timeout must be a positive integer less than 300 seconds\n");
        json_decref(root);
        return -1;
    }

    // Check retry policy
    json_t *retry_policy_json = json_object_get(root, "retry_policy");
    if (json_is_integer(retry_policy_json)) {
        int rp = json_integer_value(retry_policy_json);
        if (rp != RETRY_IMMEDIATELY && rp != RETRY_DELAYED) {
            fprintf(stderr, "Invalid retry policy\n");
            json_decref(root);
            return -1;
        }
        retry_policy = rp;
    }

    // Validate optional authentication key
    auth_key = json_string_value(json_object_get(root, "authentication_key"));
    if (auth_key && !validate_auth_key(auth_key)) {
        fprintf(stderr, "Invalid authentication key\n");
        json_decref(root);
        return -1;
    }

    // Set configuration values
    config->service_name = service_name;
    config->endpoint = endpoint;
    config->timeout = timeout;
    config->retry_policy = retry_policy;
    config->authentication_key = auth_key;

    json_decref(root);
    return 0; // Success
}

// Example usage of the function in a main program:
