public class MessageProcessor
{
    private static readonly object LockObject = new object();

    public Dictionary<int, string> ProcessMessages(string jsonInput, byte[] tripleDesKey, byte[] iv, byte[] hmacKey)
    {
        var result = new ConcurrentDictionary<int, string>();

        try
        {
            // Parse JSON input
            var jsonArray = JObject.Parse(jsonInput);
            int index = 0;

            foreach (var messageToken in jsonArray)
            {
                if (!messageToken.Value.Type.Equals(JTokenType.String))
                    continue; // Skip non-string values

                var base64EncryptedMessage = messageToken.ToString();

                try
                {
                    string decryptedContent = DecryptTripleDes(base64EncryptedMessage, tripleDesKey, iv);

                    if (VerifyHmac(decryptedContent, hmacKey))
                    {
                        result[index] = decryptedContent;
                    }
                    else
                    {
                        LogError($"Message at index {index} failed HMAC verification.");
                        result[index] = "Invalid - HMAC verification failed";
                    }

                }
                catch (Exception ex)
                {
                    LogError($"Failed to process message at index {index}: {ex.Message}");
                    result[index] = "Invalid - Decryption or Verification error";
                }

                index++;
            }
        }
        catch (JsonReaderException ex)
        {
