    private string DecryptTripleDes(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        using var des = new TripleDESCryptoServiceProvider();
        des.Key = key;
        des.IV = iv;

        var encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
        return Encoding.UTF8.GetString(des.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length));
    }

    private bool VerifyHmac(string messageContent, byte[] hmacKey)
    {
        using var hmac = new HMACSHA256(hmacKey);
