        if (!messageContent.StartsWith("HMAC:"))
            return false;

        var parts = messageContent.Split(new[] { ':' }, 2, StringSplitOptions.None);
        var originalHmacBase64 = parts[0].Replace("HMAC:", string.Empty);
        var messageWithoutHmac = parts.Length > 1 ? parts[1] : string.Empty;

        var computedHash = hmac.ComputeHash(Encoding.UTF8.GetBytes(messageWithoutHmac));
        var originalHmacBytes = Convert.FromBase64String(originalHmacBase64);

        return StructuralComparisons.StructuralEqualityComparer.Equals(computedHash, originalHmacBytes);
    }

