// Graph database manager using Boost
class GraphDatabaseManager {
public:
    using Vertex = boost::graph_traits<Graph>::vertex_descriptor;
    Graph graph_;

    void addRandomVerticesAndEdges(int numVertices, int maxDegree) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 999);

        for (int i = 0; i < numVertices; ++i) {
            Vertex v = boost::add_vertex(graph_);
            vertexProperties[v]["uuid"] = std::to_string(dis(gen));
            vertexProperties[v]["name"] = "Vertex_" + std::to_string(v);
        }

        for (auto& [v, props] : vertexProperties) {
            int degree = dis(gen) % maxDegree;
            while (degree--) {
                Vertex u = boost::add_vertex(graph_);
                addEdgeWithRandomProperties(v, u);
            }
        }
    }

private:
    std::map<Vertex, std::map<std::string, std::string>> vertexProperties;

    void addEdgeWithRandomProperties(Vertex v1, Vertex v2) {
        if (boost::edge(v1, v2, graph_).second == false) {
            boost::add_edge(v1, v2, graph_);
            edgeProperties[std::make_pair(v1, v2)]["weight"] = std::to_string(std::rand() % 100);
        }
    }

    std::map<std::pair<Vertex, Vertex>, std::map<std::string, std::string>> edgeProperties;
};

