typedef struct {
    int value;
    long *offset;
    int *key;
} record;

// Function to find the largest integer in an array
int findLargest(int *arr, size_t size) {
    if (size == 0) return INT_MIN; // Handle empty array case

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to initialize and manage records
record* initializeAndManageRecords(size_t num_records, int min_value, int max_value, 
                                   size_t *records_size) {
    // Allocate memory for the dynamic array of records
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize each record with a random value and allocate memory for pointers
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        // Allocate memory for offset and key pointers
        records[i].offset = (long *)malloc(sizeof(long));
        if (!records[i].offset) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            free(records); // Free previously allocated records
            return NULL;
        }

        records[i].key = (int *)malloc(sizeof(int));
        if (!records[i].key) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            free(records[i].offset);
            free(records); // Free previously allocated records and offsets
            return NULL;
        }
    }

    *records_size = num_records; // Store the number of records
    return records;
}

// Function to retrieve a specific record by index
record* getRecordByIndex(record *records, size_t index, size_t records_size) {
    if (index < records_size) {
        return &records[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

// Function to read integers from standard input and find the largest one
void processInputAndFindLargest() {
    int *array = NULL;
    size_t capacity = 0, current_size = 0;

    printf("Enter integers (non-integer input will terminate): \n");

    while (1) {
        if (current_size >= capacity) {
            capacity = capacity > 0 ? capacity * 2 : 4; // Double the capacity or initialize to 4
            int *new_array = realloc(array, capacity * sizeof(int));
            if (!new_array) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(array); // Free previously allocated memory
                return;
            }
            array = new_array;
        }

        if (scanf("%d", &array[current_size]) != 1) {
            break; // Break on non-integer input
        }
        current_size++;
    }

    int largest_value = findLargest(array, current_size);
    printf("The largest integer is: %d\n", largest_value);

    free(array); // Free allocated memory
}

int main() {
    size_t num_records;
    int min_val, max_val;

    printf("Enter number of records to initialize: ");
    if (scanf("%zu", &num_records) != 1 || num_records == 0) {
        fprintf(stderr, "Invalid input for number of records\n");
        return EXIT_FAILURE;
    }

    printf("Enter minimum value range for record values: ");
    if (scanf("%d", &min_val) != 1) {
        fprintf(stderr, "Invalid input for minimum value range\n");
        return EXIT_FAILURE;
    }

    printf("Enter maximum value range for record values: ");
    if (scanf("%d", &max_val) != 1 || max_val < min_val) {
        fprintf(stderr, "Invalid input for maximum value range\n");
        return EXIT_FAILURE;
    }

    size_t records_size;
    record *records = initializeAndManageRecords(num_records, min_val, max_val, &records_size);
    if (!records) {
        return EXIT_FAILURE; // Exit if memory allocation failed
    }

    processInputAndFindLargest();

    // Free allocated memory for each record
    for (size_t i = 0; i < records_size; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);

    return EXIT_SUCCESS;
}
