```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
    int *key;
} Record;

// Global variables for memory management and logging
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
#define LOG_ENABLED 1

#ifdef LOG_ENABLED
#define LOG(fmt, ...) fprintf(stderr, fmt "\n", ##__VA_ARGS__)
#else
#define LOG(...)
#endif

// Memory pool structure
typedef struct {
    void *pool;
    size_t size;
} MemoryPool;

MemoryPool create_memory_pool(size_t size) {
    MemoryPool mp = {malloc(size), size};
    return mp;
}

void free_memory_pool(MemoryPool mp) {
    if (mp.pool) {
        free(mp.pool);
    }
}

int allocate_records(int num_records, long *offsets, int *keys,
                     Record **records, size_t memory_limit) {

    pthread_mutex_lock(&mutex);

    size_t record_size = sizeof(Record);
    size_t key_array_size = num_records * sizeof(int);
    size_t offset_array_size = num_records * sizeof(long);

    // Calculate total required memory
    size_t total_memory_needed = record_size * num_records + key_array_size + offset_array_size;

    if (total_memory_needed > memory_limit) {
        pthread_mutex_unlock(&mutex);
        return -1;  // Indicate failure due to exceeding memory limit
    }

    MemoryPool mp = create_memory_pool(total_memory_needed);

    if (!mp.pool) {
        LOG("Failed to allocate total memory pool");
        pthread_mutex_unlock(&mutex);
        return -2;  // Allocation failed
    }

    offsets = (long *)((char *)mp.pool + record_size * num_records);
    keys = (int *)(offsets + num_records);
    *records = (Record *)mp.pool;

    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = 0;  // Initialize value
        (*records)[i].key = &keys[i];
        offsets[i] = (long)((char *)(*records + i) - (char *)mp.pool);
    }

    pthread_mutex_unlock(&mutex);

    LOG("Memory allocation successful: %zu bytes used out of %zu limit", total_memory_needed, memory_limit);

    return 0;  // Indicate success
}

int main() {
    long offsets[100];
    int keys[100];
    Record *records = NULL;
    size_t memory_limit = 1024 * 1024;  // 1 MB

    if (allocate_records(100, offsets, keys, &records, memory_limit) == 0) {
        printf("Memory allocated successfully.\n");
    } else {
        printf("Failed to allocate memory.\n");
    }

    // Cleanup
    free_memory_pool((MemoryPool){.pool = records});

    return 0;
}
```

This code implements a function `allocate_records` that handles memory allocation for the specified data structures while ensuring thread safety and adhering to the provided memory limit. It uses a simple logging mechanism controlled by preprocessor directives, which can be enabled or disabled as needed. The memory pool ensures efficient allocation and minimizes fragmentation, while mutexes ensure thread-safe operations.']

