#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} Collection;

void initialize_openssl() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    // Add other ciphers and digests as needed
}

Collection* create_collection(size_t initial_capacity) {
    Collection *coll = (Collection*)malloc(sizeof(Collection));
    if (!coll) return NULL;

    coll->offsets = (long*)calloc(initial_capacity, sizeof(long));
    coll->keys = (int*)calloc(initial_capacity, sizeof(int));
    coll->records = (record**)calloc(initial_capacity, sizeof(record*));

    if (!coll->offsets || !coll->keys || !coll->records) {
        free(coll->offsets);
        free(coll->keys);
        free(coll->records);
        free(coll);
        return NULL;
    }

    coll->count = 0;
    coll->capacity = initial_capacity;
    pthread_mutex_init(&coll->lock, NULL);

    initialize_openssl();
    return coll;
}

void resize_collection(Collection *coll) {
    size_t new_capacity = coll->capacity * 2;
    long *new_offsets = (long*)realloc(coll->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(coll->keys, new_capacity * sizeof(int));
    record **new_records = (record**)realloc(coll->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        // Handle allocation failure
        fprintf(stderr, "Allocation failed during resize.\n");
        exit(EXIT_FAILURE);
    }

    coll->offsets = new_offsets;
    coll->keys = new_keys;
    coll->records = new_records;
    coll->capacity = new_capacity;

    memset(coll->offsets + coll->count, 0, (coll->capacity - coll->count) * sizeof(long));
    memset(coll->keys + coll->count, 0, (coll->capacity - coll->count) * sizeof(int));
}

int add_record(Collection *coll, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&coll->lock);

    if (coll->count == coll->capacity) {
        resize_collection(coll);
    }

    record *new_rec = (record*)malloc(sizeof(record));
    if (!new_rec) {
        pthread_mutex_unlock(&coll->lock);
        fprintf(stderr, "Allocation failed for new record.\n");
        return -1;
    }

    int value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

    new_rec->value = value;
    new_rec->offset_ptr = &coll->offsets[coll->count];
    new_rec->key_ptr = &coll->keys[coll->count];

    coll->records[coll->count] = new_rec;
    (*new_rec->offset_ptr) = rand(); // Assign a random offset
    (*new_rec->key_ptr) = rand() % 1000; // Assign a random key

    coll->count++;
    pthread_mutex_unlock(&coll->lock);
    return 0;
}

record* get_record_by_index(Collection *coll, size_t index) {
    if (index >= coll->count) return NULL;

    pthread_mutex_lock(&coll->lock);
    record *rec = coll->records[index];
    pthread_mutex_unlock(&coll->lock);

    return rec;
}

void free_collection(Collection *coll) {
    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->records[i]);
    }
    free(coll->offsets);
    free(coll->keys);
    free(coll->records);
    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

int main() {
    srand(time(NULL));
    Collection *coll = create_collection(10);

    if (!coll) return EXIT_FAILURE;

    for (int i = 0; i < 20; ++i) {
        add_record(coll, 1, 100);
    }

    record *rec = get_record_by_index(coll, 5);
    if (rec) printf("Record at index 5: Value=%d, Offset=%ld, Key=%d\n", rec->value, *(rec->offset_ptr), *(rec->key_ptr));

    free_collection(coll);

    return EXIT_SUCCESS;
}
```

