#include <iostream>
#include <vector>
#include <memory>
#include <random>
#include <mutex>
#include <fstream>

namespace RecordManager {

    struct Record {
        int value;
        long offset1, offset2; // Pointers to offsets as per requirement
        int key;

        Record(int v = 0, long o1 = 0, long o2 = 0, int k = 0)
            : value(v), offset1(o1), offset2(o2), key(k) {}
    };

    class DynamicArray {
    private:
        std::vector<std::unique_ptr<Record>> records;
        mutable std::mutex mtx; // For thread safety
        std::mt19937 mtGenerator;

        void log(const std::string& message) const {
            std::lock_guard<std::mutex> lock(mtx); // Ensure logging is thread-safe
            std::ofstream logFile("record_manager.log", std::ios_base::app);
            if (logFile.is_open()) {
                logFile << message << "\n";
                logFile.close();
            }
        }

    public:
        DynamicArray(size_t size, int rangeMin = 0, int rangeMax = 100) 
            : mtGenerator(std::random_device{}()), records(size) {

            std::uniform_int_distribution<int> dist(rangeMin, rangeMax);
            for (size_t i = 0; i < size; ++i) {
                try {
                    auto record = std::make_unique<Record>(dist(mtGenerator), i * 10, i * 20, static_cast<int>(i));
                    records[i] = std::move(record);
                    log("Initialized record " + std::to_string(i));
                } catch (const std::bad_alloc& e) {
                    log("Memory allocation failed for record " + std::to_string(i));
                    throw;
                }
            }
        }

        ~DynamicArray() {
            log("Destructor called, cleaning up resources.");
        }

        void addRecord(const Record& newRecord) {
            std::lock_guard<std::mutex> lock(mtx);
            try {
                auto record = std::make_unique<Record>(newRecord);
                records.push_back(std::move(record));
                log("Added new record.");
            } catch (const std::bad_alloc&) {
                log("Failed to add a new record due to memory allocation failure.");
                throw;
            }
        }

        Record getRecord(size_t index) const {
            std::lock_guard<std::mutex> lock(mtx);
            if (index < records.size()) {
                log("Accessed record at index " + std::to_string(index));
                return *records[index];
            } else {
                throw std::out_of_range("Index out of range.");
            }
        }

        void updateRecord(size_t index, const Record& updatedRecord) {
            std::lock_guard<std::mutex> lock(mtx);
            if (index < records.size()) {
                try {
                    *records[index] = updatedRecord;
                    log("Updated record at index " + std::to_string(index));
                } catch (...) {
                    log("Failed to update record at index " + std::to_string(index));
                    throw;
                }
            } else {
                throw std::out_of_range("Index out of range.");
            }
        }
    };
}

int main() {
    try {
        RecordManager::DynamicArray arr(10); // Example: Initialize with 10 records
        auto record = arr.getRecord(0);
        std::cout << "Value at index 0: " << record.value << "\n";

        Record newRec{42, 100, 200, 1};
        arr.addRecord(newRec);

        Record updatedRec{84, 300, 400, 2};
        arr.updateRecord(0, updatedRec);
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << "\n";
    }

    return 0;
}
