#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CONFIG_FILE_PATH "config.txt"

typedef struct {
    long timestamp;
    char eventType[50];
    char message[256];
} Event;

// Function prototypes
void configureAndExecuteProcessingPipeline();
Event* readEventsFromFiles(const char *startTimestamp, const char *endTimestamp, size_t *eventCount);
long parseTimestamp(const char *timestampStr);
int loadConfiguration(char **startTimestamp, char **endTimestamp);
void processEvents(Event *events, size_t eventCount);
void calculateAverageFrequency(Event *events, size_t eventCount);

// Main function to configure and execute the processing pipeline
void configureAndExecuteProcessingPipeline() {
    char *startTimestamp = NULL;
    char *endTimestamp = NULL;

    // Load configuration from file and environment variables
    if (!loadConfiguration(&startTimestamp, &endTimestamp)) {
        fprintf(stderr, "Failed to load configuration\n");
        return;
    }

    size_t eventCount = 0;
    Event *events = readEventsFromFiles(startTimestamp, endTimestamp, &eventCount);

    // Free allocated memory for timestamps
    free(startTimestamp);
    free(endTimestamp);

    if (events == NULL) {
        fprintf(stderr, "Failed to allocate memory for events\n");
        return;
    }

    processEvents(events, eventCount);

    // Calculate average frequency of events over the time window
    calculateAverageFrequency(events, eventCount);

    // Free allocated memory for events
    free(events);
}

// Function to read and filter events from files based on timestamps
Event* readEventsFromFiles(const char *startTimestamp, const char *endTimestamp, size_t *eventCount) {
    long start = parseTimestamp(startTimestamp);
    long end = parseTimestamp(endTimestamp);

    if (start == -1 || end == -1) {
        fprintf(stderr, "Invalid timestamp format\n");
        return NULL;
    }

    Event *events = NULL;
    size_t capacity = 10;
    events = realloc(events, sizeof(Event) * capacity);
    if (!events) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    size_t count = 0;

    char filePath[256];
    while (fgets(filePath, sizeof(filePath), stdin)) {
        // Remove newline character
        filePath[strcspn(filePath, "\n")] = '\0';

        FILE *file = fopen(filePath, "r");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", filePath);
            continue;
        }

        char line[512];
        while (fgets(line, sizeof(line), file)) {
            Event event;
            sscanf(line, "%ld|%49[^|]|%255[^\n]", &event.timestamp, event.eventType, event.message);

            if (event.timestamp >= start && event.timestamp <= end) {
                if (count == capacity) {
                    capacity *= 2;
                    events = realloc(events, sizeof(Event) * capacity);
                    if (!events) {
                        perror("Failed to reallocate memory for events");
                        fclose(file);
                        free(events);
                        return NULL;
                    }
                }

                events[count++] = event;
            }
        }

        fclose(file);
    }

    *eventCount = count;
    return realloc(events, sizeof(Event) * count);
}

// Function to parse a timestamp from string
long parseTimestamp(const char *timestampStr) {
    if (!timestampStr) return -1;

    char *endPtr;
    long timestamp = strtol(timestampStr, &endPtr, 10);

    if (*endPtr != '\0') {
        return -1; // Not a valid number
    }

    return timestamp;
}

// Function to load configuration parameters from file and environment variables
int loadConfiguration(char **startTimestamp, char **endTimestamp) {
    FILE *file = fopen(CONFIG_FILE_PATH, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file\n");
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        if (strncmp(line, "START_TIMESTAMP=", 16) == 0) {
            *startTimestamp = strdup(line + 16);
        } else if (strncmp(line, "END_TIMESTAMP=", 14) == 0) {
            *endTimestamp = strdup(line + 14);
        }
    }

    fclose(file);

    // Override with environment variables if they exist
    char *envStart = getenv("START_TIMESTAMP");
    if (envStart && *startTimestamp) {
        free(*startTimestamp);
        *startTimestamp = strdup(envStart);
    } else if (!*startTimestamp) {
        fprintf(stderr, "START_TIMESTAMP not set\n");
        return 0;
    }

    char *envEnd = getenv("END_TIMESTAMP");
    if (envEnd && *endTimestamp) {
        free(*endTimestamp);
        *endTimestamp = strdup(envEnd);
    } else if (!*endTimestamp) {
        fprintf(stderr, "END_TIMESTAMP not set\n");
        return 0;
    }

    return 1;
}

// Function to process events
void processEvents(Event *events, size_t eventCount) {
    for (size_t i = 0; i < eventCount; ++i) {
        // Process each event (e.g., log or analyze)
        printf("Processing Event: %ld | %s | %s\n", events[i].timestamp, events[i].eventType, events[i].message);
    }
}

// Function to calculate average frequency of events over a time window
void calculateAverageFrequency(Event *events, size_t eventCount) {
    if (eventCount == 0) return;

    long startTime = events[0].timestamp;
    long endTime = events[eventCount - 1].timestamp;
    double totalTime = (endTime - startTime) / 1000.0; // Convert to seconds

    if (totalTime > 0) {
        double frequency = (double)eventCount / totalTime;
        printf("Average Event Frequency: %.2f events per second\n", frequency);
    }
}
