#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RANDOM_VALUE 1000

typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct RecordCollection {
    Record **records;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} RecordCollection;

// Function to initialize the collection
RecordCollection* init_record_collection(size_t num_records) {
    if (num_records == 0) return NULL;

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(num_records * sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            // Free previously allocated memory on failure
            while (--i) free(collection->records[i]);
            free(collection->records);
            free(collection);
            return NULL;
        }

        record->value = rand() % MAX_RANDOM_VALUE + 1; // Random value between 1 and MAX_RANDOM_VALUE
        record->offset = malloc(sizeof(long));
        record->key = malloc(sizeof(int));

        if (!record->offset || !record->key) {
            free(record);
            while (--i) free(collection->records[i]);
            free(collection->records);
            free(collection);
            return NULL;
        }

        collection->records[i] = record;
    }

    collection->count = num_records;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Function to add a new record
int add_record(RecordCollection *collection) {
    if (!collection || collection->count == 0) return -1;

    pthread_mutex_lock(&collection->lock);

    Record **new_records = realloc(collection->records, (collection->count + 1) * sizeof(Record *));
    if (!new_records) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->records = new_records;

    Record *record = malloc(sizeof(Record));
    if (!record) {
        free(new_records[collection->count]);
        collection->records = new_records; // Avoid dangling pointer
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    record->value = rand() % MAX_RANDOM_VALUE + 1;
    record->offset = malloc(sizeof(long));
    record->key = malloc(sizeof(int));

    if (!record->offset || !record->key) {
        free(record);
        free(new_records[collection->count]);
        collection->records = new_records; // Avoid dangling pointer
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->records[collection->count] = record;
    ++(collection->count);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Function to retrieve a specific record by index
Record* get_record_by_index(RecordCollection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);

    Record *record = collection->records[index];

    pthread_mutex_unlock(&collection->lock);
    return record;
}

// Function to update a record's value by index
int update_record_value(RecordCollection *collection, size_t index, int new_value) {
    if (!collection || index >= collection->count) return -1;

    pthread_mutex_lock(&collection->lock);

    Record *record = collection->records[index];
    if (record) {
        record->value = new_value;
        pthread_mutex_unlock(&collection->lock);
        return 0;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

// Function to free the collection
void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Main function for demonstration
int main() {
    srand(time(NULL));

    RecordCollection *collection = init_record_collection(10);
    if (!collection) {
        printf("Failed to initialize record collection\n");
        return 1;
    }

    add_record(collection);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = get_record_by_index(collection, i);
        if (record) {
            printf("Record %zu: Value=%d\n", i, record->value);
        }
    }

    free_record_collection(collection);

    return 0;
}
```

This code provides a dynamic collection of records with thread-safe operations for initialization, adding new records, retrieving by index, and updating values. It handles memory allocation failures gracefully and ensures resources are freed properly to prevent leaks.']

