use std::net::SocketAddr;
use tokio::runtime::Runtime;
use tokio_tungstenite::{connect_async, tungstenite::protocol::Message};
use reqwest::{Client, Url, Error as ReqwestError};
use log::{info, error};

#[derive(Debug)]
struct Record {
    value: i32,
    offset_ptr: *mut u64,
    key_ptr: *mut i32,
}

fn initializeAndManageRecords(num_records: usize, value_range: (i32, i32)) -> Result<Vec<Record>, &'static str> {
    // Allocate and initialize arrays
    let mut offsets: Vec<u64> = vec![0; num_records];
    let mut keys: Vec<i32> = vec![0; num_records];

    if offsets.is_empty() || keys.is_empty() {
        return Err("Memory allocation failed");
    }

    // Initialize records
    let mut rng = rand::thread_rng();
    let mut records = Vec::with_capacity(num_records);

    for i in 0..num_records {
        let value = rng.gen_range(value_range.0..=value_range.1);
        let offset_ptr = offsets.as_mut_ptr().add(i);
        let key_ptr = keys.as_mut_ptr().add(i);

        // Ensure non-null pointers
        if offset_ptr.is_null() || key_ptr.is_null() {
            return Err("Pointer allocation failed");
        }

        records.push(Record {
            value,
            offset_ptr: offset_ptr as *mut u64,
            key_ptr: key_ptr as *mut i32,
        });
    }

    Ok(records)
}

fn retrieve_record(records: &Vec<Record>, index: usize) -> Result<&Record, &'static str> {
    if index < records.len() {
        Ok(&records[index])
    } else {
        Err("Index out of bounds")
    }
}

// Helper function to find the maximum integer in an array
fn find_max_in_array(arr: &[i32]) -> Option<i32> {
    arr.iter().max().cloned()
}

// Function for Java Channel connection using Tokio and Tungstenite (WebSockets)
async fn connect_to_java_channel(addr: &str) -> Result<(), Box<dyn std::error::Error>> {
    let url = format!("ws://{}", addr);
    let (ws_stream, _) = connect_async(url).await?;
    println!("Connected to Java Channel at {}", addr);

    // Handle connection state changes
    while let Some(message) = ws_stream.next().await {
        match message? {
            Message::Text(text) => info!("Received: {}", text),
            _ => (),
        }
    }

    Ok(())
}

// Create an HTTP client and return a `RequestBuilder`
fn create_http_client_and_builder(url_str: &str, disable_tls_validation: bool) -> Result<reqwest::RequestBuilder, ReqwestError> {
    let client = Client::builder()
        .danger_accept_invalid_certs(disable_tls_validation)
        .build()?;

    Ok(client.get(url_str.parse::<Url>()?))
}

fn main() {
    // Initialize logger
    env_logger::init();

    // Example usage
    if let Ok(records) = initializeAndManageRecords(10, (0, 100)) {
        // Read integers from standard input
        let mut input: Vec<i32> = vec![];
        println!("Enter numbers separated by space:");
        for line in std::io::stdin().lock().lines() {
            if let Ok(num_str) = line {
                for num in num_str.split_whitespace() {
                    if let Ok(n) = num.parse::<i32>() {
                        input.push(n);
                    }
                }
            }
        }

        // Find and print the largest integer
        if let Some(max_value) = find_max_in_array(&input) {
            println!("Largest number: {}", max_value);
        } else {
            println!("No valid integers provided");
        }
    } else {
        error!("Failed to initialize records");
    }

    // Connect to Java Channel in an async runtime
    let addr = "127.0.0.1:8080";
    let rt = Runtime::new().expect("failed to create runtime");
    rt.block_on(connect_to_java_channel(addr)).unwrap_or_else(|err| error!("Connection failed: {:?}", err));

    // Create HTTP client and request builder
    if let Ok(builder) = create_http_client_and_builder("https://example.com", true) {
        println!("RequestBuilder created for URL: {}", "https://example.com");
    } else {
        error!("Failed to create RequestBuilder");
    }
}
