['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

// Function prototypes
void initialize_data(long **offsets, int **keys, Record **records, size_t num_records);
size_t count_disjoint_pairs(int *input_array, size_t array_size);
long measure_time(void (*func)(int*, size_t), int *array, size_t array_size);

// Union-Find functions
void make_set(UnionFindNode *nodes, int x) {
    nodes[x].parent = x;
    nodes[x].rank = 0;
}

int find(UnionFindNode *nodes, int x) {
    if (nodes[x].parent != x)
        nodes[x].parent = find(nodes, nodes[x].parent);
    return nodes[x].parent;
}

void union_sets(UnionFindNode *nodes, int x, int y) {
    int rootX = find(nodes, x), rootY = find(nodes, y);
    if (rootX != rootY) {
        if (nodes[rootX].rank > nodes[rootY].rank)
            nodes[rootY].parent = rootX;
        else if (nodes[rootX].rank < nodes[rootY].rank)
            nodes[rootX].parent = rootY;
        else {
            nodes[rootY].parent = rootX;
            nodes[rootX].rank++;
        }
    }
}

// Main function
void initialize_and_process_data(int *input_array, size_t array_size, size_t num_records) {
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    // Initialize data structures
    if (!initialize_data(&offsets, &keys, &records, num_records)) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Measure disjoint pairs counting time
    long processing_time = measure_time(count_disjoint_pairs, input_array, array_size);
    printf("Disjoint pairs count: %zu\n", count_disjoint_pairs(input_array, array_size));
    printf("Processing time: %ld ms\n", processing_time);

    // Free allocated memory
    free(offsets);
    free(keys);
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset_ptr);
        free(records[i].key_ptr);
    }
    free(records);
}

// Function implementations
void initialize_data(long **offsets, int **keys, Record **records, size_t num_records) {
    srand(time(NULL));
    *offsets = (long *)malloc(num_records * sizeof(long));
    *keys = (int *)malloc(num_records * sizeof(int));
    if (!*offsets || !*keys) return;

    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = rand() % 1000;
        (*keys)[i] = rand() % 1000;
    }

    *records = (Record *)malloc(num_records * sizeof(Record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100;
        (*records)[i].offset_ptr = &((*offsets)[i]);
        (*records)[i].key_ptr = &((*keys)[i]);
    }
}

size_t count_disjoint_pairs(int *input_array, size_t array_size) {
    UnionFindNode *nodes = (UnionFindNode *)malloc(array_size * sizeof(UnionFindNode));
    if (!nodes) return 0;

    for (size_t i = 0; i < array_size; ++i)
        make_set(nodes, input_array[i]);

    size_t disjoint_count = 0;
    for (size_t i = 1; i < array_size; ++i) {
        int root_i = find(nodes, input_array[i]);
        int root_prev = find(nodes, input_array[i - 1]);
        if (root_i != root_prev) {
            disjoint_count++;
            union_sets(nodes, root_i, root_prev);
        }
    }

    free(nodes);
    return disjoint_count;
}

long measure_time(void (*func)(int*, size_t), int *array, size_t array_size) {
    clock_t start = clock();
    func(array, array_size);
    clock_t end = clock();
    return (end - start) * 1000 / CLOCKS_PER_SEC;
}
```

