    pthread_mutex_t lock;
} UserProfile;

typedef struct HashTableEntry {
    UserProfile *profile;
    struct HashTableEntry *next;
} HashTableEntry;

HashTableEntry *hash_table[TABLE_SIZE];

unsigned int hash(int id) {
    return id % TABLE_SIZE;
}

UserProfile* create_profile(int id, const char *username) {
    UserProfile *profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) {
        perror("Failed to allocate memory for profile");
        return NULL;
    }

    pthread_mutex_init(&profile->lock, NULL);
    profile->id = id;
    profile->username = strdup(username);
    profile->friends = NULL;

    return profile;
}

void add_friend(UserProfile *profile, const char *friend_username) {
    pthread_mutex_lock(&profile->lock);

    Friend *new_friend = (Friend*)malloc(sizeof(Friend));
    if (!new_friend) {
        perror("Failed to allocate memory for friend");
        pthread_mutex_unlock(&profile->lock);
        return;
    }

    new_friend->username = strdup(friend_username);
    new_friend->next = profile->friends;
    profile->friends = new_friend;

    pthread_mutex_unlock(&profile->lock);
}

UserProfile* get_profile(int id) {
    unsigned int index = hash(id);

    HashTableEntry *entry = hash_table[index];
    while (entry) {
        if (entry->profile && entry->profile->id == id) {
            return entry->profile;
        }
        entry = entry->next;
    }

    return NULL;
}

void add_profile(UserProfile *profile) {
    unsigned int index = hash(profile->id);

    HashTableEntry *new_entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!new_entry) {
        perror("Failed to allocate memory for hash table entry");
        return;
    }

    new_entry->profile = profile;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
}

void free_profile(UserProfile *profile) {
    pthread_mutex_lock(&profile->lock);

    Friend *friend_node = profile->friends;
    while (friend_node) {
        Friend *temp = friend_node;
        friend_node = friend_node->next;

        free(temp->username);
        free(temp);
    }

    free(profile->username);
    pthread_mutex_unlock(&profile->lock);
    pthread_mutex_destroy(&profile->lock);
    free(profile);
}

void free_hash_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashTableEntry *entry = hash_table[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;

            free_profile(temp->profile);
            free(temp);
        }
    }
}

int main() {
    // Initialize hash table
    memset(hash_table, 0, sizeof(hash_table));

    // Example usage
    UserProfile *user1 = create_profile(1, "Alice");
    add_profile(user1);

    UserProfile *user2 = create_profile(2, "Bob");
    add_profile(user2);

    add_friend(user1, "Bob");

    UserProfile *retrieved_user = get_profile(1);
    if (retrieved_user) {
        printf("Retrieved user: %s\n", retrieved_user->username);
    }

    // Cleanup
    free_hash_table();

    return 0;
}
```

