#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Transaction {
    int account_id;
    time_t transaction_time;
    double amount;
    struct Transaction* next;
} Transaction;

typedef struct {
    Transaction* head;
    pthread_mutex_t lock;
} TransactionList;

Transaction* create_transaction(int account_id, time_t start_time, time_t end_time, double min_amount, double max_amount) {
    Transaction* trans = (Transaction*)malloc(sizeof(Transaction));
    if (!trans) return NULL; // Handle allocation failure

    trans->account_id = account_id;
    trans->transaction_time = start_time + rand() % (end_time - start_time);
    trans->amount = min_amount + ((double)rand() / RAND_MAX) * (max_amount - min_amount);

    return trans;
}

TransactionList* init_transaction_list(int num_transactions, time_t start_time, time_t end_time, double min_amount, double max_amount) {
    TransactionList* list = (TransactionList*)malloc(sizeof(TransactionList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;

    for (int i = 0; i < num_transactions; ++i) {
        Transaction* trans = create_transaction(i, start_time, end_time, min_amount, max_amount);
        if (!trans) continue; // Handle allocation failure

        pthread_mutex_lock(&list->lock);

        trans->next = list->head;
        list->head = trans;

        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

Transaction* get_transaction(TransactionList* list, int account_id) {
    pthread_mutex_lock(&list->lock);

    Transaction* current = list->head;
    while (current) {
        if (current->account_id == account_id) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void destroy_transaction_list(TransactionList* list) {
    pthread_mutex_lock(&list->lock);

    Transaction* current = list->head;
    while (current) {
        Transaction* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    srand(time(NULL));

    time_t start_time = 1609459200; // Jan 1, 2021
    time_t end_time = 1640995200;   // Dec 31, 2021

    TransactionList* list = init_transaction_list(1000, start_time, end_time, 10.0, 1000.0);

    if (list) {
        Transaction* trans = get_transaction(list, 42);
        if (trans) {
            printf("Transaction found: Account ID %d, Time %ld, Amount %.2f\n",
                   trans->account_id, trans->transaction_time, trans->amount);
        } else {
            printf("Transaction not found.\n");
        }

        destroy_transaction_list(list);
    }

    return 0;
}
```

