#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define INITIAL_SIZE 16
#define RANGE_MIN 0
#define RANGE_MAX 100

typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct RecordCollection {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* init_record_collection() {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = calloc(INITIAL_SIZE, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = INITIAL_SIZE;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int resize_collection_if_needed(RecordCollection *collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) return 0;

        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    return 1;
}

int add_record(RecordCollection *collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);

    if (!resize_collection_if_needed(collection)) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    record->value = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
    record->offset = malloc(sizeof(long));
    record->key = malloc(sizeof(int));

    if (!record->offset || !record->key) {
        free(record);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    *record->offset = offset;
    *record->key = key;

    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

Record* get_record_by_index(RecordCollection *collection, size_t index) {
    if (index >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];
    pthread_mutex_unlock(&collection->lock);

    return record;
}

int update_record_value(RecordCollection *collection, size_t index, int new_value) {
    if (index >= collection->count) return -1;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];
    record->value = new_value;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

int execute_command(const char *cmd) {
    pid_t pid = fork();
    if (pid == -1) return 0;

    if (pid == 0) {
        execlp("/bin/sh", "sh", "-c", cmd, NULL);
        exit(EXIT_FAILURE);
    }

    int status;
    waitpid(pid, &status, 0);

    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

int main() {
    srand(time(NULL));

    RecordCollection *collection = init_record_collection();
    if (!collection) {
        fprintf(stderr, "Failed to initialize record collection.\n");
        return EXIT_FAILURE;
    }

    add_record(collection, 100L, 1);
    add_record(collection, 200L, 2);

    Record *record = get_record_by_index(collection, 0);
    if (record) {
        printf("Record value: %d\n", record->value);
    }

    update_record_value(collection, 0, 42);
    record = get_record_by_index(collection, 0);
    if (record) {
        printf("Updated Record value: %d\n", record->value);
    }

    int command_success = execute_command("echo 'Hello, World!'");
    printf("Command execution success: %d\n", command_success);

    free_record_collection(collection);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety:** Mutex locks ensure thread-safe operations on the collection.
- **Dynamic Memory Management:** Handles resizing and allocation failures gracefully.
- **Concurrency in Command Execution:** Uses `fork` and `waitpid` to execute commands without blocking the main process.
- **Error Handling:** Comprehensive error checks for memory allocations and command execution.']

