#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define INITIAL_LIMIT 100
#define MAX_OPERATION_COUNT 500

typedef struct {
    sem_t semaphore;
    int limit;
    volatile int current_count;
    pthread_mutex_t mutex;
} Semaphore;

Semaphore* init_semaphore(int initial_limit);
void destroy_semaphore(Semaphore *sem);

int acquire_semaphore(Semaphore *sem, int count, int timeout_ms);
int release_semaphore(Semaphore *sem, int count);

void reset_semaphore_if_needed(Semaphore *sem);

// Diagnostic tools and logging
void log_semaphore_status(const Semaphore *sem);
void monitor_semaphore_performance(const char* metrics_file);

Semaphore* init_semaphore(int initial_limit) {
    Semaphore *sem = (Semaphore *)malloc(sizeof(Semaphore));
    sem->limit = initial_limit;
    sem->current_count = 0;

    if (sem_init(&sem->semaphore, 0, initial_limit) != 0) {
        perror("Failed to initialize semaphore");
        free(sem);
        return NULL;
    }

    if (pthread_mutex_init(&sem->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        sem_destroy(&sem->semaphore);
        free(sem);
        return NULL;
    }

    return sem;
}

void destroy_semaphore(Semaphore *sem) {
    sem_destroy(&sem->semaphore);
    pthread_mutex_destroy(&sem->mutex);
    free(sem);
}

int acquire_semaphore(Semaphore *sem, int count, int timeout_ms) {
    struct timespec ts;
    int rc;

    if (timeout_ms < 0) { 
        return sem_wait(&sem->semaphore); // Blocking
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1e6;

    rc = sem_timedwait(&sem->semaphore, &ts);

    if (rc == 0) {
        pthread_mutex_lock(&sem->mutex);
        sem->current_count += count;
        reset_semaphore_if_needed(sem);
        pthread_mutex_unlock(&sem->mutex);
    }

    return rc;
}

int release_semaphore(Semaphore *sem, int count) {
    pthread_mutex_lock(&sem->mutex);

    if (sem->current_count >= count) {
        sem_post(&sem->semaphore);
        sem->current_count -= count;
    } else {
        fprintf(stderr, "Attempt to release more than acquired\n");
    }

    pthread_mutex_unlock(&sem->mutex);
    return 0;
}

void reset_semaphore_if_needed(Semaphore *sem) {
    static int operation_counter = 0;

    if (++operation_counter >= MAX_OPERATION_COUNT) {
        pthread_mutex_lock(&sem->mutex);
        sem_init(&sem->semaphore, 0, sem->limit); // Reset semaphore
        sem->current_count = 0;
        operation_counter = 0;
        log_semaphore_status(sem); // Log the reset event
        pthread_mutex_unlock(&sem->mutex);
    }
}

void log_semaphore_status(const Semaphore *sem) {
    printf("Semaphore status: limit=%d, current_count=%d\n", sem->limit, sem->current_count);
}

void monitor_semaphore_performance(const char* metrics_file) {
    // Implement logging of performance metrics to a file or external system
}

// API Documentation and usage examples

/*
 * Semaphore Management Module API:
 *
 * 1. Initialization: 
 *    - `Semaphore* init_semaphore(int initial_limit);`
 *      Initializes a semaphore with an optional limit.
 *
 * 2. Acquisition:
 *    - `int acquire_semaphore(Semaphore *sem, int count, int timeout_ms);`
 *      Acquires the semaphore for 'count' units or until 'timeout_ms'.
 *
 * 3. Release:
 *    - `int release_semaphore(Semaphore *sem, int count);`
 *      Releases 'count' units of the semaphore.
 *
 * 4. Destruction: 
 *    - `void destroy_semaphore(Semaphore *sem);`
 *      Frees resources used by the semaphore.
 *
 * Usage Example:
 * ```c
 * Semaphore* sem = init_semaphore(INITIAL_LIMIT);
 * acquire_semaphore(sem, 1, 1000); // Try acquiring for 1 second
 * release_semaphore(sem, 1);
 * destroy_semaphore(sem);
 * ```
 */

// Unit Tests and Stress Tests

void run_tests() {
    // Implement unit tests for initialization, acquisition, release, and reset logic.
    printf("Running unit tests...\n");
}

int main() {
    Semaphore* sem = init_semaphore(INITIAL_LIMIT);

    if (!sem) return 1;

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void*)acquire_semaphore, (void*)sem);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    release_semaphore(sem, 1);

    destroy_semaphore(sem);

    run_tests();

    return 0;
}
```

**Notes:**

- The semaphore uses `sem_timedwait` for timeouts during acquisition.
- A reset mechanism is implemented to reinitialize the semaphore after a fixed number of operations.
- Logs and diagnostics can be extended by adding more detailed logging in `log_semaphore_status`.
- Configuration management, such as dynamic adjustments based on system load, would typically involve external libraries or services not shown here.
- The module includes basic error handling with appropriate messaging.
- Memory management is handled through careful allocation and deallocation of resources.
- This implementation can be extended to include integration with a database for persistent state management and more advanced diagnostic features. 

This code serves as a framework that you can further develop based on specific application requirements, such as the integration with external configuration systems or embedded platforms.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

#define INITIAL_SIZE 10

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} RecordManager;

// Function prototypes
void initializeAndManageRecords(RecordManager *manager, size_t initial_size, int range_min, int range_max);
int getRecordByIndex(const RecordManager *manager, size_t index, Record *out_record);
void saveRecordsToFile(const char *filename, const RecordManager *manager);
void loadRecordsFromFile(const char *filename, RecordManager *manager);
void resizeIfNeeded(RecordManager *manager);

// Helper function to allocate memory safely
void *safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initializeAndManageRecords(RecordManager *manager, size_t initial_size, int range_min, int range_max) {
    pthread_mutex_init(&manager->lock, NULL);

    manager->capacity = initial_size;
    manager->count = 0;
    manager->records = safeMalloc(sizeof(Record) * initial_size);

    for (size_t i = 0; i < initial_size; ++i) {
        manager->records[i].value = rand() % (range_max - range_min + 1) + range_min;

        // Allocate memory and handle failure
        long *offset = safeMalloc(sizeof(long));
        int *key = safeMalloc(sizeof(int));

        manager->records[i].offset = offset;
        manager->records[i].key = key;

        manager->count++;
    }
}

int getRecordByIndex(const RecordManager *manager, size_t index, Record *out_record) {
    if (index >= manager->count) return -1; // Index out of bounds

    pthread_mutex_lock(&manager->lock);
    memcpy(out_record, &manager->records[index], sizeof(Record));
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void saveRecordsToFile(const char *filename, const RecordManager *manager) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    // Write count and capacity
    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(&manager->capacity, sizeof(size_t), 1, file);

    // Write records
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(&manager->records[i].value, sizeof(int), 1, file);

        // Save the actual data pointed by offset and key
        long *offset = manager->records[i].offset;
        int *key = manager->records[i].key;

        fwrite(offset, sizeof(long), 1, file); 
        fwrite(key, sizeof(int), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void loadRecordsFromFile(const char *filename, RecordManager *manager) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    size_t count, capacity;

    // Read count and capacity
    fread(&count, sizeof(size_t), 1, file);
    fread(&capacity, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    // Resize if necessary
    if (manager->capacity < capacity) {
        Record *new_records = safeMalloc(sizeof(Record) * capacity);

        for (size_t i = 0; i < manager->count; ++i) {
            memcpy(&new_records[i], &manager->records[i], sizeof(Record));
            free(new_records[i].offset);
            free(new_records[i].key);
        }

        // Initialize new spaces
        for (size_t i = manager->count; i < capacity; ++i) {
            long *offset = safeMalloc(sizeof(long));
            int *key = safeMalloc(sizeof(int));

            new_records[i].offset = offset;
            new_records[i].key = key;
        }

        free(manager->records);
        manager->records = new_records;
    }

    // Load records
    for (size_t i = 0; i < count; ++i) {
        fread(&manager->records[i].value, sizeof(int), 1, file);

        long *offset = safeMalloc(sizeof(long));
        int *key = safeMalloc(sizeof(int));

        manager->records[i].offset = offset;
        manager->records[i].key = key;

        // Load the actual data pointed by offset and key
        fread(offset, sizeof(long), 1, file);
        fread(key, sizeof(int), 1, file);
    }

    manager->count = count;
    manager->capacity = capacity;

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void resizeIfNeeded(RecordManager *manager) {
    // This function will be called asynchronously to resize the records array
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        pthread_mutex_lock(&manager->lock);

        Record *new_records = safeMalloc(sizeof(Record) * new_capacity);

        for (size_t i = 0; i < manager->count; ++i) {
            memcpy(&new_records[i], &manager->records[i], sizeof(Record));
            free(new_records[i].offset);
            free(new_records[i].key);
        }

        // Initialize new spaces
        for (size_t i = manager->count; i < new_capacity; ++i) {
            long *offset = safeMalloc(sizeof(long));
            int *key = safeMalloc(sizeof(int));

            new_records[i].offset = offset;
            new_records[i].key = key;
        }

        free(manager->records);
        manager->records = new_records;
        manager->capacity = new_capacity;

        pthread_mutex_unlock(&manager->lock);
    }
}

// Asynchronous resizing would require a separate thread and mechanism to trigger it, typically using conditions or timers.
