['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    uint32_t user_id;
    time_t session_start_time;
    int64_t session_duration; // in seconds
} user_session;

typedef struct node {
    uint32_t key;
    user_session data;
    struct node *next;
} node_t;

typedef struct {
    node_t **buckets;
    pthread_mutex_t *locks;
    size_t num_buckets;
} hash_table_t;

uint32_t hash_function(uint32_t user_id, size_t table_size) {
    return user_id % table_size;
}

hash_table_t* create_hash_table(size_t num_buckets) {
    hash_table_t *table = (hash_table_t *)malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->buckets = (node_t **)calloc(num_buckets, sizeof(node_t *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->locks = (pthread_mutex_t *)calloc(num_buckets, sizeof(pthread_mutex_t));
    if (!table->locks) {
        free(table->buckets);
        free(table);
        return NULL;
    }

    for (size_t i = 0; i < num_buckets; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    table->num_buckets = num_buckets;
    return table;
}

void destroy_hash_table(hash_table_t *table) {
    if (!table) return;

    for (size_t i = 0; i < table->num_buckets; ++i) {
        node_t *current = table->buckets[i];
        while (current) {
            node_t *tmp = current;
            current = current->next;
            free(tmp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->locks[0]);
    free(table->locks);
    free(table);
}

int insert_session(hash_table_t *table, uint32_t user_id, time_t start_time, int64_t duration) {
    if (!table) return -1;

    uint32_t index = hash_function(user_id, table->num_buckets);
    pthread_mutex_lock(&table->locks[index]);

    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) {
        pthread_mutex_unlock(&table->locks[index]);
        return -1;
    }

    new_node->key = user_id;
    new_node->data.user_id = user_id;
    new_node->data.session_start_time = start_time;
    new_node->data.session_duration = duration;

    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index]);
    return 0;
}

user_session* get_session(hash_table_t *table, uint32_t user_id) {
    if (!table) return NULL;

    uint32_t index = hash_function(user_id, table->num_buckets);
    pthread_mutex_lock(&table->locks[index]);

    node_t *current = table->buckets[index];
    while (current) {
        if (current->key == user_id) {
            pthread_mutex_unlock(&table->locks[index]);
            return &(current->data);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

int remove_expired_sessions(hash_table_t *table, time_t current_time) {
    if (!table) return -1;

    int removed_count = 0;
    for (size_t i = 0; i < table->num_buckets; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        node_t **current_ptr = &(table->buckets[i]);
        while (*current_ptr) {
            node_t *entry = *current_ptr;
            if (current_time - entry->data.session_start_time > entry->data.session_duration) {
                *current_ptr = entry->next;
                free(entry);
                removed_count++;
            } else {
                current_ptr = &((*current_ptr)->next);
            }
        }

        pthread_mutex_unlock(&table->locks[i]);
    }

    return removed_count;
}

void initialize_sessions(hash_table_t *table, size_t num_sessions,
                         time_t start_time_min, time_t start_time_max,
                         int64_t duration_min, int64_t duration_max) {
    if (!table) return;

    srand(time(NULL));

    for (size_t i = 0; i < num_sessions; ++i) {
        uint32_t user_id = rand() % HASH_TABLE_SIZE;
