typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

// Node for the linked list to hold records
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Structure for managing dynamic array of records using a linked list
typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;  // For thread safety
} DataStructure;

void logMessage(const char *message) {
    printf("%s\n", message);
}

DataStructure* initializeDataStructure(size_t numRecords, int minValue, int maxValue) {
    if (numRecords == 0) return NULL;

    srand(time(NULL)); // Seed for random number generation

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) {
        logMessage("Memory allocation failed for data structure.");
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);
    ds->head = NULL;
    ds->count = 0;

    for (size_t i = 0; i < numRecords; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            logMessage("Memory allocation failed for new node.");
            // Free previously allocated nodes before returning
            while (ds->head != NULL) {
                Node* temp = ds->head;
                ds->head = ds->head->next;
                free(temp);
            }
            pthread_mutex_destroy(&ds->lock);
            free(ds);
            return NULL;
        }

        newNode->record.value = minValue + rand() % (maxValue - minValue + 1);
        newNode->record.offset = malloc(sizeof(long));
        newNode->record.key = malloc(sizeof(int));

        if (!newNode->record.offset || !newNode->record.key) {
            logMessage("Memory allocation failed for record fields.");
            free(newNode); // Free current node
            while (ds->head != NULL) {
                Node* temp = ds->head;
                ds->head = ds->head->next;
                free(temp);
            }
            pthread_mutex_destroy(&ds->lock);
            free(ds);
            return NULL;
        }

        newNode->record.offset[0] = 0; // Initialize offset
        newNode->record.key[0] = 0;    // Initialize key

        pthread_mutex_lock(&ds->lock);  // Ensure thread-safe operation
        newNode->next = ds->head;
        ds->head = newNode;
        ++ds->count;
        pthread_mutex_unlock(&ds->lock);

        logMessage("Initialized a new record.");
    }

    logMessage("Data structure initialized successfully.");
    return ds;
}

// Function to free the data structure
void freeDataStructure(DataStructure* ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);
    while (ds->head != NULL) {
        Node* temp = ds->head;
        ds->head = ds->head->next;
        free(temp->record.offset);
        free(temp->record.key);
        free(temp);
    }
    pthread_mutex_unlock(&ds->lock);

    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

