#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct CustomStruct {
    int value;
    int key;
    long offset;
    time_t creation_timestamp;
    unsigned int access_count;
} CustomStruct;

typedef struct Record {
    int key;
    long offset;
    CustomStruct* data;
} Record;

Record* initializeRecords(int num_records, int min_val, int max_val) {
    if (num_records <= 0 || min_val > max_val) return NULL;

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        records[i].key = i; // Unique integer key
        records[i].offset = rand() % 10000; // Random offset for demonstration

        CustomStruct* data = malloc(sizeof(CustomStruct));
        if (!data) {
            perror("Memory allocation failed for CustomStruct");
            // Free previously allocated memory to avoid leaks
            while (i-- > 0) free(records[i].data);
            free(records);
            return NULL;
        }

        records[i].data = data;

        // Initialize struct fields with default and random values
        data->value = min_val + rand() % (max_val - min_val + 1); 
        data->key = i; // Reference to its key
        data->offset = records[i].offset;
        data->creation_timestamp = time(NULL);
        data->access_count = 0;
    }

    return records;
}

void freeRecords(Record* records, int num_records) {
    if (!records) return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i].data);
    }
    free(records);
}

// Example usage
