    offset: i64,
}

type DataPtr = Arc<()>;

struct RecordManager {
    records: Mutex<HashMap<u32, (Record, DataPtr)>>,
    size: AtomicUsize,
}

impl RecordManager {
    fn new() -> Self {
        RecordManager {
            records: Mutex::new(HashMap::new()),
            size: AtomicUsize::new(0),
        }
    }

    fn initialize_and_manage_records(&self, num_records: usize) -> Result<(), &'static str> {
        let mut records = self.records.lock().map_err(|_| "Mutex poisoned")?;

        for i in 0..num_records {
            // Initialize each record with a key and offset
            let record_key = i as u32;
            let record_offset = i as i64 * 10; // Example offset logic
            let data_ptr = Arc::new(()); // Example reference-counted pointer

            if !records.insert(record_key, (Record { key: record_key, offset: record_offset }, data_ptr)).is_none() {
                return Err("Failed to allocate memory for records");
            }
        }

        self.size.store(num_records, Ordering::SeqCst);
        Ok(())
    }

    fn insert_record(&self, key: u32, offset: i64) -> Result<(), &'static str> {
        let mut records = self.records.lock().map_err(|_| "Mutex poisoned")?;
        if !records.contains_key(&key) {
            let data_ptr = Arc::new(()); // Example reference-counted pointer
            records.insert(key, (Record { key, offset }, data_ptr)).is_none()
                .then(|| Ok(()))
                .ok_or("Failed to insert record")
        } else {
            Err("Key already exists")
        }
    }

    fn retrieve_record(&self, key: u32) -> Option<(Record, DataPtr)> {
        let records = self.records.lock().map_err(|_| "Mutex poisoned").ok()?;
        records.get(&key).cloned()
    }

    fn update_record(&self, key: u32, new_offset: i64) -> Result<(), &'static str> {
        let mut records = self.records.lock().map_err(|_| "Mutex poisoned")?;
        if let Some((record, data_ptr)) = records.get_mut(&key) {
            record.offset = new_offset;
            Ok(())
        } else {
            Err("Record not found")
        }
    }

    async fn fetch_integers_from_external_source(&self, url: &str) -> Result<Vec<u32>, ReqwestError> {
        let client = HttpClient::new();
        let res = client.get(url).send().await?;

