                    .map(u64::try_from)
                    .collect())
        } else {
            Err(ReqwestError::new(reqwest::StatusCode::BAD_REQUEST, false))
        }
    }

    async fn establish_connection_with_java_channel(&self) -> Result<(), ReqwestError> {
        // Example using Tokio and TcpStream
        let mut stream = TcpStream::connect("127.0.0.1:12345").await?;
        Ok(())
    }

    async fn send_http_request(&self, url: &str, validate_cert: bool) -> Result<String, ReqwestError> {
        let client = HttpClient::builder()
            .danger_accept_invalid_certs(!validate_cert)
            .build()?;

        let res = client.get(url).send().await?;
        Ok(res.text().await?)
    }
}

fn create_semaphore(initial_value: usize) -> std::sync::Arc<std::sync::Semaphore> {
