#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CONCURRENT_DNS_REQUESTS 5

typedef struct {
    char *hostname;
    u_char ip_address[16];
} DNSRequest;

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
    int active_requests;
} FileProcessor;

void *dns_resolution(void *arg) {
    DNSRequest *request = (DNSRequest *)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(request->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (inet_ntop(AF_INET, &((struct sockaddr_in *)p->ai_addr)->sin_addr, 
                      (char *)request->ip_address, 16)) {
            break;
        }
    }

    freeaddrinfo(res);
    return request->ip_address;
}

void *process_file(void *arg) {
    FileProcessor *processor = (FileProcessor *)arg;

    pthread_mutex_lock(&processor->lock);

    if (processor->active_requests >= MAX_CONCURRENT_DNS_REQUESTS) {
        pthread_mutex_unlock(&processor->lock);
        return NULL;
    }

    processor->active_requests++;

    char line[1024];
    DNSRequest dns_request;
    pthread_t dns_thread;

    while (fgets(line, sizeof(line), processor->file)) {
        // Process each line to find hostname and initiate DNS resolution
        char *hostname = strchr(line, ' '); // Placeholder for actual logic to extract hostname

        if (hostname) {
            hostname++; // Move past delimiter
            dns_request.hostname = strdup(hostname);

            pthread_create(&dns_thread, NULL, dns_resolution, &dns_request);

            void *ip_result;
            pthread_join(dns_thread, &ip_result);

            if (ip_result) {
                printf("Resolved IP: %s\n", ip_result);
            }

            free(dns_request.hostname);
        } else {
            // Process line for numerical fields
            char *token = strtok(line, ",\t "); // Handle multiple delimiters
            int num1 = 0, num2 = 0;
            int found_num = 0;

            while (token) {
                if (found_num < 2 && sscanf(token, "%d", &num1)) {
                    if (found_num == 0)
                        num2 = num1;
                    else
                        num2 = num1;
                    found_num++;
                }
                token = strtok(NULL, ",\t ");
            }

            if (found_num >= 2) {
                double average = (num1 + num2) / 2.0;
                printf("Processed line: %sAverage: %.2f\n", line, average);
            } else {
                printf("Processed line: %s\n", line);
            }
        }
    }

    processor->active_requests--;

    pthread_mutex_unlock(&processor->lock);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2] ... <fileN>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int num_files = argc - 1;
    pthread_t threads[num_files];
    FileProcessor processors[num_files];

    for (int i = 0; i < num_files; ++i) {
        processors[i].file = fopen(argv[i + 1], "r");
        if (!processors[i].file) {
            perror("fopen error");
            continue;
        }

        pthread_mutex_init(&processors[i].lock, NULL);
        processors[i].active_requests = 0;

        pthread_create(&threads[i], NULL, process_file, &processors[i]);
    }

    for (int i = 0; i < num_files; ++i) {
        if (processors[i].file)
            fclose(processors[i].file);

        pthread_mutex_destroy(&processors[i].lock);
        pthread_join(threads[i], NULL);
    }

    return 0;
}
