#define CACHE_SIZE 100

typedef struct {
    float value;
    char *str;
    int ref_count;
} dataEntry;

// Cache for frequently accessed strings
typedef struct {
    char **cache;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
} StringCache;

StringCache string_cache = { .cache = NULL, .size = CACHE_SIZE, .lock = PTHREAD_MUTEX_INITIALIZER };

// Custom allocator with thread safety and memory management
void* custom_alloc(size_t size) {
    static pthread_mutex_t alloc_lock;
    static int initialized = 0;

    if (!initialized) {
        pthread_mutex_init(&alloc_lock, NULL);
        initialized = 1;
    }

    pthread_mutex_lock(&alloc_lock);

    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE); // Handle failure gracefully
    }

    pthread_mutex_unlock(&alloc_lock);
    return ptr;
}

// Increment reference count with thread safety
void increment_ref(dataEntry *entry) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    entry->ref_count++;
    pthread_mutex_unlock(&lock);
}

// Decrement reference count with thread safety
int decrement_ref(dataEntry *entry) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int ref_count;

    pthread_mutex_lock(&lock);
    if (entry->ref_count > 0)
        entry->ref_count--;
    ref_count = entry->ref_count;
    pthread_mutex_unlock(&lock);

    // If reference count is zero, free the string
    if (ref_count == 0) {
        free(entry->str);
    }

    return ref_count;
}

// Initialize dynamic array of dataEntry structures
void processAndStoreData(int num_entries, float min_val, float max_val) {
    srand(time(NULL));

    // Allocate memory for the entries
    dataEntry *entries = (dataEntry *)custom_alloc(num_entries * sizeof(dataEntry));

    for (int i = 0; i < num_entries; ++i) {
        // Set each float value to a random number within the given range
        entries[i].value = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);

        // Allocate memory for the string and initialize reference count
        entries[i].str = (char *)custom_alloc(50 * sizeof(char));
        snprintf(entries[i].str, 50, "String%d", i); // Example string allocation
        entries[i].ref_count = 1; // Initial reference count

        // Cache management: add to cache if not already cached
        pthread_mutex_lock(&string_cache.lock);
        for (size_t j = 0; j < string_cache.size; ++j) {
            if (!string_cache.cache[j] || strcmp(string_cache.cache[j], entries[i].str) == 0) {
                string_cache.cache[j] = entries[i].str;
                break;
            }
        }
        pthread_mutex_unlock(&string_cache.lock);
    }

    // Reading list of integers from standard input
    int n, *numbers;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    numbers = (int *)custom_alloc(n * sizeof(int));

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &numbers[i]);
    }

    // Finding and printing the largest integer
    int max_value = findMax(numbers, n);
    printf("The largest integer is: %d\n", max_value);

    // Free allocated resources
    free(entries);
    free(numbers);
}

// Helper function to find maximum value in an array of integers
int findMax(int *arr, size_t size) {
    if (size == 0) return INT_MIN; // Handle edge case for empty array

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max)
            max = arr[i];
    }

    return max;
}

int main() {
    processAndStoreData(10, 0.0, 100.0);
    return 0;
}
