['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct DataElement {
    double value;
    struct DataElement* next;
} DataElement;

typedef struct DataSet {
    float floatValue;
    char* stringData;
    DataElement* elementsHead;
} DataSet;

// Function prototypes
void manageDataSets(int numDataSets, float minRange, float maxRange);
DataSet* getDataSet(DataSet** dataSets, int index);
int addDataElementToDataSet(DataSet* dataSet, double value);
float computeAverage(float* numbers, size_t count);

void manageDataSets(int numDataSets, float minRange, float maxRange) {
    if (numDataSets <= 0 || minRange >= maxRange) return;

    DataSet** dataSets = malloc(numDataSets * sizeof(DataSet*));
    if (!dataSets) exit(EXIT_FAILURE); // Robust error handling for allocation failure

    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < numDataSets; ++i) {
        DataSet* dataSet = malloc(sizeof(DataSet));
        if (!dataSet) { free(dataSets); exit(EXIT_FAILURE); }

        dataSet->floatValue = minRange + ((maxRange - minRange) * rand() / (RAND_MAX + 1.0f));

        // Allocate and initialize string
        size_t strLength = rand() % 50 + 1; // Random length for demonstration
        dataSet->stringData = malloc(strLength);
        if (!dataSet->stringData) { free(dataSet); free(dataSets); exit(EXIT_FAILURE); }
        snprintf(dataSet->stringData, strLength, "DataSet_%d", i);

        dataSet->elementsHead = NULL;
        dataSets[i] = dataSet;
    }

    // Read floating-point numbers from standard input
    float* inputNumbers = NULL;
    size_t capacity = 0, count = 0;

    printf("Enter floating-point numbers (end with EOF):\n");
    while (scanf("%f", &count) == 1) {
        if (inputNumbers == NULL || count >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            float* newInputNumbers = realloc(inputNumbers, capacity * sizeof(float));
            if (!newInputNumbers) { free(dataSets); exit(EXIT_FAILURE); }
            inputNumbers = newInputNumbers;
        }

        inputNumbers[count++] = count;
    }

    // Compute and print average
    printf("Average: %.2f\n", computeAverage(inputNumbers, count));

    free(inputNumbers);
}

DataSet* getDataSet(DataSet** dataSets, int index) {
    if (index < 0 || dataSets[index] == NULL) return NULL;
    return dataSets[index];
}

int addDataElementToDataSet(DataSet* dataSet, double value) {
    if (!dataSet) return -1;

    DataElement* newElement = malloc(sizeof(DataElement));
    if (!newElement) return -1; // Error handling for allocation failure

    newElement->value = value;
    newElement->next = dataSet->elementsHead;
    dataSet->elementsHead = newElement;
    return 0;
}

float computeAverage(float* numbers, size_t count) {
    if (numbers == NULL || count == 0) return 0.0f;

    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    return sum / count;
}

int main() {
    manageDataSets(5, 0.0f, 100.0f);
    return 0;
}
```

### Key Points:
- The function `manageDataSets` initializes a specified number of datasets with random float values and dynamically allocated strings.
- It reads floating-point numbers from standard input and computes their average using the helper function `computeAverage`.
- Memory allocation is handled carefully, with checks for failures to prevent memory leaks.
- Functions are modular, allowing easy updates or extensions in the future.']

