    public void executeCommand(String command, String workingDirectory) throws Exception {
        File dir = new File(workingDirectory);

        if (dir.exists()) {
            deleteExistingFiles(dir);
        }
        ProcessBuilder pb = new ProcessBuilder(command.split(" "));
        pb.directory(dir);

        Process process = Runtime.getRuntime().exec(pb.command(), null, dir);
        StreamHandler handler = new StreamHandler(process.getInputStream());
        Thread thread = new Thread(handler);
        thread.start();

        // Assuming command execution is synchronous for simplicity.
        handler.waitForProcessCompletion();

    }

    private void deleteExistingFiles(File dir) {
        File[] files = dir.listFiles();
        if (files != null) {
            for (File file : files) {
                file.delete();
            }
        }
    }

    public static class StreamHandler implements Runnable {

        private final BufferedReader reader;
        private boolean finished;

        public StreamHandler(java.io.InputStream inputStream) throws Exception {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        @Override
        public void run() {
            try {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("Output: " + line);
                }
                finished = true;
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        public boolean waitForProcessCompletion() throws InterruptedException {
            while (!finished) {
                Thread.sleep(100);
            }
            return true;
        }
    }

    public static void main(String[] args) {
        JavaComponent jc = new JavaComponent();

        int[] exampleArray = {1, 5, 3, 9, 7};
        jc.jniFindAndPrintLargest(exampleArray);

        try {
            jc.executeCommand("echo Hello World", "./outputDir");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
