    offset_ptr: *const i64,
    key_ptr: *const i32,
}

async fn initializeAndManageRecords(num_entries: usize, offset_range: (i64, i64), key_range: (i32, i32)) -> Result<Vec<Record>, &'static str> {
    if num_entries == 0 { return Err("Number of entries must be greater than zero"); }

    let mut offsets = vec![0; num_entries];
    let mut keys = vec![0; num_entries];

    // Fill with random data
    let mut rng = rand::thread_rng();
    for i in 0..num_entries {
        offsets[i] = rng.gen_range(offset_range.0..=offset_range.1);
        keys[i] = rng.gen_range(key_range.0..=key_range.1);
    }

    let records: Vec<Record> = (0..num_entries).map(|i| {
        Record {
            value: rng.gen_range(0..100), // assuming a range of 0-99
            offset_ptr: offsets.as_ptr().add(i),
            key_ptr: keys.as_ptr().add(i),
        }
    }).collect();

    Ok(records)
}

async fn mock_channel_interface() -> Result<(), &'static str> {
