typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

int allocate_and_initialize(int num_records, long **offsets, int **keys, record ***records) {
    if (num_records <= 0 || !offsets || !keys || !records) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));

    if (!*offsets || !*keys) {
        fprintf(stderr, "Memory allocation failed for offsets or keys.\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    record **temp_records = malloc(num_records * sizeof(record *));
    if (!temp_records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = i * sizeof(long); // Simulated offset
        (*keys)[i] = rand() % 1000 + 1;   // Random key in range [1, 1000]

        temp_records[i] = malloc(sizeof(record));
        if (!temp_records[i]) {
            fprintf(stderr, "Memory allocation failed for record at index %d.\n", i);
            for (int j = 0; j < i; ++j) {
                free(temp_records[j]);
            }
            free(temp_records);
            free(*offsets);
            free(*keys);
            return -1;
        }

        temp_records[i]->value = rand() % 100 + 1; // Random value in range [1, 100]
        temp_records[i]->offset_ptr = &((*offsets)[i]);
        temp_records[i]->key_ptr = &((*keys)[i]);

        if (!validate_record(temp_records[i])) {
            fprintf(stderr, "Data integrity validation failed for record at index %d.\n", i);
            free(temp_records[i]);
            for (int j = 0; j < i; ++j) {
                free(temp_records[j]);
            }
            free(temp_records);
            free(*offsets);
            free(*keys);
            return -1;
        }
    }

    *records = temp_records;
    return 0;
}

int validate_record(record *r) {
    if (!r || !r->value || !r->offset_ptr || !r->key_ptr) {
        return 0; // Invalid pointers or zero value
    }
    long offset_val = *(r->offset_ptr);
    int key_val = *(r->key_ptr);

    if (offset_val < 0 || key_val <= 0) {
        return 0; // Invalid data range
    }

    return 1;
}

void free_resources(long *offsets, int *keys, record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
}
