        messages[i] = malloc(sizeof(Message));
        if (!messages[i]) {
            log_error(log_file_path, "Failed to allocate memory for a message structure.");
            for (size_t j = 0; j < i; ++j) {
                free(messages[j]->message_buffer);
                free(messages[j]);
            }
            free(messages);
            return -1;
        }

        messages[i]->client_id = rand() % 1000000; // Generate a random client ID
        messages[i]->message_buffer = malloc(max_message_size);
        if (!messages[i]->message_buffer) {
            log_error(log_file_path, "Failed to allocate memory for message buffer.");
            free(messages[i]);
            for (size_t j = 0; j < i; ++j) {
                free(messages[j]->message_buffer);
                free(messages[j]);
            }
            free(messages);
            return -1;
        }

        messages[i]->timestamp = time(NULL);
        messages[i]->status = 0;

        int send_success = 0;
        for (int attempt = 0; attempt < 3 && !send_success; ++attempt) {
            send_success = send_message_async(messages[i]);
            if (!send_success) {
                log_error(log_file_path, "Message sending failed. Retrying...");
            }
        }

        messages[i]->status = send_success ? 1 : -1;
    }

    // Simulate message cleanup periodically
    cleanup_pending_messages(messages, num_clients, max_message_size, cleanup_interval);

    for (size_t i = 0; i < num_clients; ++i) {
        if (messages[i]) {
            free(messages[i]->message_buffer);
            free(messages[i]);
        }
    }

    free(messages);
    return 0;
}
```

This C function is designed to manage dynamic memory allocation for a messaging system, handle asynchronous message sending with retries, and clean up messages based on a specified interval. It includes error logging and robust error handling to ensure efficient memory management and graceful failure handling.']

