#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
    long* offset;
    int* key;
    time_t last_accessed;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* initializeAndManageRecords(size_t initial_size, int min_value, int max_value) {
    if (initial_size == 0 || min_value > max_value)
        return NULL;

    RecordManager* manager = malloc(sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate RecordManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_size;
    manager->count = 0;

    // Allocate memory for records
    manager->records = malloc(manager->capacity * sizeof(Record*));
    if (!manager->records) {
        perror("Failed to allocate record array");
        free(manager);
        pthread_mutex_destroy(&manager->lock);
        return NULL;
    }

    srand(time(NULL));

    // Initialize records with random values and pointers
    for (size_t i = 0; i < initial_size; ++i) {
        Record* rec = malloc(sizeof(Record));
        if (!rec) {
            perror("Failed to allocate a record");
            continue;
        }

        rec->value = rand() % (max_value - min_value + 1) + min_value;
        rec->offset = malloc(sizeof(long));
        *rec->offset = rand(); // Random offset for demonstration
        if (!rec->offset) {
            perror("Failed to allocate offset");
            free(rec);
            continue;
        }

        rec->key = malloc(sizeof(int));
        *rec->key = rand() % 1000; // Random key for demonstration
        if (!rec->key) {
            perror("Failed to allocate key");
            free(rec->offset);
            free(rec);
            continue;
        }

        rec->last_accessed = time(NULL);

        manager->records[manager->count++] = rec;

        printf("Record initialized: value=%d, offset=%ld, key=%d\n", 
               rec->value, *rec->offset, *rec->key);
    }

    return manager;
}

void resizeRecords(RecordManager* manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    if (new_capacity <= manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));
    if (!new_records) {
        perror("Failed to resize record array");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->records = new_records;
    manager->capacity = new_capacity;

    printf("Resized records to capacity: %zu\n", manager->capacity);

    pthread_mutex_unlock(&manager->lock);
}

int saveRecordsToFile(RecordManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        Record* rec = manager->records[i];
        if (!rec)
            continue;

        fwrite(&rec->value, sizeof(int), 1, file);
        fwrite(rec->offset, sizeof(long), 1, file);
        fwrite(rec->key, sizeof(int), 1, file);
        fwrite(&rec->last_accessed, sizeof(time_t), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    printf("Records saved to %s\n", filename);
    return 0;
}

int loadRecordsFromFile(RecordManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    size_t record_count;
    fread(&record_count, sizeof(size_t), 1, file);
    resizeRecords(manager, record_count); // Ensure capacity

    for (size_t i = 0; i < record_count; ++i) {
        Record* rec = malloc(sizeof(Record));
        if (!rec) {
            perror("Failed to allocate a record");
            continue;
        }

        fread(&rec->value, sizeof(int), 1, file);
        rec->offset = malloc(sizeof(long));
        fread(rec->offset, sizeof(long), 1, file);

        rec->key = malloc(sizeof(int));
        fread(rec->key, sizeof(int), 1, file);

        fread(&rec->last_accessed, sizeof(time_t), 1, file);

        manager->records[i] = rec;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);

    printf("Records loaded from %s\n", filename);
    return 0;
}

void cleanup(RecordManager* manager) {
    if (!manager)
        return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        Record* rec = manager->records[i];
        if (rec) {
            free(rec->offset);
            free(rec->key);
            free(rec);
        }
    }

    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void createSnapshot(RecordManager* manager, const char* snapshot_filename) {
    snprintf(snapshot_filename, sizeof(snapshot_filename), "snapshot_%ld.dat", time(NULL));
    saveRecordsToFile(manager, snapshot_filename);
}
```

This code demonstrates a thread-safe mechanism to initialize and manage records with dynamic resizing capabilities. It includes saving/loading from files with error handling, periodic snapshots for auditing, and logging statements to monitor operations without significantly impacting performance.']

