        for (size_t i = manager->count; i < new_capacity; ++i) {
            new_records[i].value = rand() % 100;
            new_records[i].offset_ptr = &new_offsets[i];
            new_records[i].key_ptr = &new_keys[i];
        }
        manager->records = new_records;
        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->lock);
}

record* get_record(record_manager *manager, size_t index) {
    if (pthread_mutex_lock(&manager->lock) != 0) return NULL;

    record *res = NULL;
    if (index < manager->count) {
        res = &manager->records[index];
    }

    pthread_mutex_unlock(&manager->lock);
    return res;
}

void save_state(record_manager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->capacity, sizeof(size_t), 1, file);
    fwrite(manager->records, sizeof(record), manager->count, file);
    fwrite(manager->offsets, sizeof(long), manager->count, file);
    fwrite(manager->keys, sizeof(int), manager->count, file);

    fclose(file);
}

void load_state(record_manager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t new_capacity;
    fread(&new_capacity, sizeof(size_t), 1, file);

    record *new_records = realloc(manager->records, new_capacity * sizeof(record));
    long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));

    if (new_records && new_offsets && new_keys) {
        fread(new_records, sizeof(record), new_capacity, file);
        fread(new_offsets, sizeof(long), new_capacity, file);
        fread(new_keys, sizeof(int), new_capacity, file);

        manager->records = new_records;
        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->capacity = new_capacity;
        manager->count = new_capacity;
    }

    fclose(file);
}

void free_resources(record_manager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free(manager);
}
```

