    char severity[10]; // e.g., "INFO", "ERROR"
    char message[256];
    Metadata *metadata; // Linked list of metadata
    struct LogEntry *prev, *next;
} LogEntry;

// Doubly linked list for log entries
typedef struct {
    LogEntry *head, *tail;
    size_t buffer_size;
    pthread_mutex_t lock;
} LogManager;

LogManager* init_log_manager(size_t buffer_size) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    if (!manager) return NULL;

    manager->buffer_size = buffer_size;
    manager->head = manager->tail = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to allocate a new log entry
LogEntry* create_log_entry(time_t timestamp, const char *severity, const char *message) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    strncpy(entry->severity, severity, sizeof(entry->severity) - 1);
    strncpy(entry->message, message, sizeof(entry->message) - 1);
    entry->metadata = NULL;
    entry->prev = entry->next = NULL;

    // Allocate and initialize metadata (if needed)
    return entry;
}

// Add a log entry to the doubly linked list
void add_log_entry(LogManager *manager, LogEntry *entry) {
    pthread_mutex_lock(&manager->lock);

    if (!manager->head) {
        manager->head = manager->tail = entry;
    } else {
        entry->prev = manager->tail;
        manager->tail->next = entry;
        manager->tail = entry;
    }

    // Release the lock after adding
    pthread_mutex_unlock(&manager->lock);
}

// Function to free a log entry and its metadata
void free_log_entry(LogEntry *entry) {
    Metadata *meta = entry->metadata, *temp;

    while (meta) {
        temp = meta->next;
        free(meta->key);  // Assuming dynamic allocation
        free(meta->value);
        free(meta);
        meta = temp;
    }

    free(entry);
}

// Cleanup the log manager and all its entries
void cleanup_log_manager(LogManager *manager) {
    LogEntry *current = manager->head, *temp;

    while (current) {
        temp = current->next;
        free_log_entry(current);
        current = temp;
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

