#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
    char* data; // Dynamically allocated metadata field
} record;

// Define a hash map node structure for efficient lookup and uniqueness check
typedef struct hashmap_node {
    int key;
    record *record_ptr;
    struct hashmap_node *next;
} hashmap_node;

#define HASH_MAP_SIZE 101

hashmap_node **hash_map;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash(int key) {
    return key % HASH_MAP_SIZE;
}

// Function to initialize the hash map
void init_hash_map() {
    hash_map = malloc(HASH_MAP_SIZE * sizeof(hashmap_node*));
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        hash_map[i] = NULL;
    }
}

// Function to clean up the hash map and free memory
void cleanup_hash_map(int record_count, record **records) {
    for (int i = 0; i < record_count; ++i) {
        free(records[i]->data);
        free(records[i]);
    }
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        hashmap_node *node = hash_map[i];
        while (node != NULL) {
            hashmap_node *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(hash_map);
}

// Function to manage records
void manage_records(record **records, int record_count, int key, int value, const char* data_content) {
    pthread_mutex_lock(&lock);

    unsigned int index = hash(key);
    hashmap_node *node = hash_map[index];
    while (node != NULL) {
        if (node->key == key) {
            // Update existing record
            node->record_ptr->value = value;
            free(node->record_ptr->data);  // Free old data memory
            // Reallocate and copy new data
            size_t data_size = strlen(data_content) + 1; 
            node->record_ptr->data = malloc(data_size);
            strcpy(node->record_ptr->data, data_content);
            pthread_mutex_unlock(&lock);
            return;
        }
        node = node->next;
    }

    // Insert new record
    if (key >= 0 && key < record_count) {
        size_t data_size = strlen(data_content) + 1; 
        records[key]->data = malloc(data_size);
        strcpy(records[key]->data, data_content);
        records[key]->value = value;

        // Update hash map with new entry
        hashmap_node *new_node = malloc(sizeof(hashmap_node));
        new_node->key = key;
        new_node->record_ptr = records[key];
        new_node->next = hash_map[index];
        hash_map[index] = new_node;
    }

    pthread_mutex_unlock(&lock);
}

// Main function for demonstration (not part of the request)
int main() {
    int record_count = 10;

    // Pre-allocate memory for records
    record *records[record_count];
    init_hash_map();

    for (int i = 0; i < record_count; ++i) {
        records[i] = malloc(sizeof(record));
        records[i]->key = i;
        size_t data_size = 10; // Example fixed initial memory allocation
        records[i]->data = malloc(data_size);
        strcpy(records[i]->data, "Initial");
        records[i]->value = 0;
    }

    manage_records(records, record_count, 5, 100, "Updated Data for Key 5");

    printf("Record with key 5: Value=%d, Data=%s\n", records[5]->value, records[5]->data);

    // Cleanup
    cleanup_hash_map(record_count, records);
    return 0;
}
```

**Justification of Design Choices:**

1. **Memory Usage:** 
   - By pre-allocating memory for the `records` array and `data` fields during initialization, we avoid repeated dynamic allocations which improve performance but increase initial memory usage.

2. **Execution Speed:**
   - Using a hash map facilitates O(1) average-time complexity operations for insertions and updates, making it efficient even as data grows.

3. **Thread Safety:** 
   - Mutex locks are used to ensure that concurrent access to shared resources (like the `records` array and hash map) is thread-safe, minimizing race conditions in multi-threaded environments.

4. **Ease of Maintenance:**
   - The use of a simple linked list within each bucket of the hash map helps keep the code straightforward while providing efficient key uniqueness checks.

These choices balance memory usage with speed and maintainability for a system where `manage_records` might be invoked repeatedly under varying conditions.']

["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char* purpose;
} Record;

int initialize_records(int numRecords, unsigned int seed, const char* template_str, 
                       long min_offset, long max_offset, Record** records) {
    if (numRecords <= 0 || !template_str || !records)
        return -1;

    *records = malloc(numRecords * sizeof(Record));
    if (*records == NULL)
        return -2;

    // Seed the random number generator for reproducibility
    srand(seed);

    long total_allocated_memory = numRecords * sizeof(Record);
    char buffer[256];

    for (int i = 0; i < numRecords; ++i) {
        Record* record = &(*records)[i];

        // Random offset within the specified range
        record->offset = min_offset + rand() % (max_offset - min_offset + 1);

        // Unique key derived from index
        record->key = i;

        // Allocate and format string description
        snprintf(buffer, sizeof(buffer), template_str, record->key);

        record->purpose = malloc(strlen(buffer) + 1); // +1 for null terminator
        if (record->purpose == NULL) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j)
                free((*records)[j].purpose);

            free(*records);
            return -3;
        }

        strcpy(record->purpose, buffer);

        total_allocated_memory += strlen(buffer) + 1; // Add size of string
    }

    return (int)total_allocated_memory;
}

void free_records(int numRecords, Record* records) {
    if (!records)
        return;

    for (int i = 0; i < numRecords; ++i) {
        free(records[i].purpose);
    }

    free(records);
}
```

This C code defines a function to manage a collection of records. It initializes each record with a random offset within a specified range, assigns a unique key based on the index, and allocates memory for a string description using a provided template. The `initialize_records` function handles errors gracefully by cleaning up previously allocated resources if any allocation fails during initialization. Finally, it returns the total size of all dynamically allocated memory, aiding in debugging and performance tuning. There's also a helper function, `free_records`, to free the allocated memory when no longer needed."]

