#include <time.h>

#define INITIAL_SIZE 10000
#define MAX_RECORDS 10000
#define DATA_SIZE 256

typedef struct {
    int value;
    char *data;
} record;

typedef struct {
    int config_param;
    // Add other configuration fields as needed
} metadata;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long *offsets;
int *keys;
record *records;
metadata *metas;
int current_size;

// Function prototypes
void initialize_memory(int initial_records);
void resize_arrays(int new_size);
void cleanup_memory();
void set_unique_keys(int range);
void update_record_values(int range);
void handle_failure(void (*cleanup_func)(void), const char* error_message);

void memory_manager_function(int initial_records, int key_range) {
    pthread_mutex_lock(&lock);

    if (!offsets || current_size < initial_records) {
        resize_arrays(initial_records);
    }

    initialize_memory(initial_records);
    set_unique_keys(key_range);
    update_record_values(1000); // Assuming range 0 to 999 for random values

    pthread_mutex_unlock(&lock);
}

void initialize_memory(int initial_records) {
    current_size = initial_records;
    offsets = (long *)malloc(current_size * sizeof(long));
    keys = (int *)malloc(current_size * sizeof(int));
    records = (record *)malloc(current_size * sizeof(record));
    metas = (metadata *)malloc(current_size * sizeof(metadata));

    if (!offsets || !keys || !records || !metas) {
        handle_failure(cleanup_memory, "Memory allocation failed");
        return;
    }

    for (int i = 0; i < current_size; ++i) {
        offsets[i] = i; // Example initialization
        keys[i] = -1;
        records[i].value = 0;
        records[i].data = malloc(DATA_SIZE);
        if (!records[i].data) {
            handle_failure(cleanup_memory, "Memory allocation for data field failed");
            return;
        }
        memset(records[i].data, 0, DATA_SIZE);
        metas[i].config_param = 42; // Example config
    }
}

void resize_arrays(int new_size) {
    long *new_offsets = (long *)realloc(offsets, new_size * sizeof(long));
    int *new_keys = (int *)realloc(keys, new_size * sizeof(int));
    record *new_records = (record *)realloc(records, new_size * sizeof(record));
    metadata *new_metas = (metadata *)realloc(metas, new_size * sizeof(metadata));

    if (!new_offsets || !new_keys || !new_records || !new_metas) {
        handle_failure(cleanup_memory, "Memory reallocation failed");
        return;
    }

    offsets = new_offsets;
    keys = new_keys;
    records = new_records;
    metas = new_metas;

    for (int i = current_size; i < new_size; ++i) {
        offsets[i] = i;
        keys[i] = -1;
        records[i].value = 0;
        records[i].data = malloc(DATA_SIZE);
        if (!records[i].data) {
            handle_failure(cleanup_memory, "Memory allocation for data field failed");
            return;
        }
        memset(records[i].data, 0, DATA_SIZE);
        metas[i].config_param = 42; // Example config
    }

    current_size = new_size;
}

void cleanup_memory() {
    if (offsets) free(offsets);
    if (keys) free(keys);
    for (int i = 0; i < current_size; ++i) {
        if (records[i].data) free(records[i].data);
    }
    if (records) free(records);
    if (metas) free(metas);

    offsets = keys = records = metas = NULL;
}

void set_unique_keys(int range) {
    srand(time(NULL));
    for (int i = 0; i < current_size; ++i) {
        int key, attempts = 0;
        do {
            key = rand() % range;
            if (++attempts > range) {
                fprintf(stderr, "Duplicate key error: could not find unique key\n");
                break;
            }
        } while (key == -1 || check_key_existence(key));

        keys[i] = key;
    }
}

int check_key_existence(int key) {
    for (int i = 0; i < current_size; ++i) {
        if (keys[i] == key) return 1;
    }
    return 0;
}

void update_record_values(int range) {
    for (int i = 0; i < current_size; ++i) {
        records[i].value = rand() % range;
    }
}

void handle_failure(void (*cleanup_func)(void), const char* error_message) {
    fprintf(stderr, "%s\n", error_message);
    cleanup_func();
}
