#include <pthread.h>
#include <time.h>

#define CACHE_SIZE 10

typedef struct {
    float value;
    char *str;
    int ref_count;
} dataEntry;

typedef struct DataNode {
    dataEntry entry;
    struct DataNode *next;
} DataNode;

typedef struct {
    int key;
    int value;
    void *data;
} record;

typedef struct {
    record *records;
    size_t capacity;
    pthread_mutex_t mutex;
} RecordManager;

typedef struct {
    DataNode *head;
    size_t size;
    char **cache;
    int cache_capacity;
    pthread_mutex_t mutex;
} StringCache;

void initStringCache(StringCache *cache) {
    cache->head = NULL;
    cache->size = 0;
    cache->cache = malloc(CACHE_SIZE * sizeof(char *));
    for (int i = 0; i < CACHE_SIZE; ++i)
        cache->cache[i] = NULL;
    cache->cache_capacity = CACHE_SIZE;
    pthread_mutex_init(&cache->mutex, NULL);
}

void freeStringCache(StringCache *cache) {
    DataNode *current = cache->head;
    while (current) {
        DataNode *next = current->next;
        free(current->entry.str);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->mutex);
    free(cache->cache);
}

char* allocateString(const char *str, StringCache *cache) {
    pthread_mutex_lock(&cache->mutex);

    // Check cache first
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->cache[i] && strcmp(cache->cache[i], str) == 0) {
            pthread_mutex_unlock(&cache->mutex);
            return cache->cache[i];
        }
    }

    // Allocate new string
    char *new_str = strdup(str);
    if (!new_str) {
        pthread_mutex_unlock(&cache->mutex);
        fprintf(stderr, "Failed to allocate memory for string\n");
        exit(EXIT_FAILURE);
    }

    // Add to linked list and cache
    DataNode *node = malloc(sizeof(DataNode));
    node->entry.str = new_str;
    node->next = cache->head;
    cache->head = node;

    // Evict if necessary
    if (cache->size >= CACHE_SIZE) {
        DataNode *evicted = cache->head;
        cache->head = evicted->next;
        free(evicted->entry.str);
        free(evicted);

        // Shift cache down by one
        for (int i = 0; i < CACHE_SIZE - 1; ++i)
            cache->cache[i] = cache->cache[i + 1];
        cache->cache[CACHE_SIZE - 1] = NULL;
    } else {
        cache->size++;
    }

    pthread_mutex_unlock(&cache->mutex);
    return new_str;
}

void incrementRefCount(StringCache *cache, const char *str) {
    pthread_mutex_lock(&cache->mutex);
    DataNode *current = cache->head;
    while (current) {
        if (strcmp(current->entry.str, str) == 0) {
            current->entry.ref_count++;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->mutex);
}

void decrementRefCount(StringCache *cache, const char *str) {
    pthread_mutex_lock(&cache->mutex);
    DataNode *current = cache->head;
    while (current) {
        if (strcmp(current->entry.str, str) == 0) {
            if (--current->entry.ref_count == 0) {
                // Remove from linked list
                DataNode **indirect = &cache->head;
                while (*indirect && strcmp((*indirect)->entry.str, str) != 0)
                    indirect = &(*indirect)->next;

                if (*indirect) {
                    DataNode *to_free = *indirect;
                    *indirect = to_free->next;

                    // Remove from cache
                    for (int i = 0; i < CACHE_SIZE; ++i) {
                        if (cache->cache[i] && strcmp(cache->cache[i], str) == 0) {
                            cache->cache[i] = NULL;
                            break;
                        }
                    }

                    free(to_free->entry.str);
                    free(to_free);
                }
            }
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->mutex);
}

dataEntry* initDataEntries(size_t size, float min_val, float max_val, StringCache *cache) {
