        char str[20];
        snprintf(str, sizeof(str), "Data_%zu", i);
        entries[i].str = allocateString(str, cache);
        entries[i].ref_count = 1;
    }

    return entries;
}

void freeDataEntries(dataEntry *entries, size_t size) {
    for (size_t i = 0; i < size; ++i)
        free(entries[i].str);
    free(entries);
}

