    pthread_mutex_lock(&manager->mutex);

    // Check if the key already exists
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i].key == key) {
            manager->records[i].value = value;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    // Resize array if necessary
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        record *new_records = realloc(manager->records, new_capacity * sizeof(record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->mutex);
            fprintf(stderr, "Failed to allocate memory for records\n");
            exit(EXIT_FAILURE);
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    // Add new record
    manager->records[manager->size].key = key;
    manager->records[manager->size].value = value;
    manager->records[manager->size].data = NULL;  // Initialize data to NULL
    manager->size++;

    pthread_mutex_unlock(&manager->mutex);
}

void initRecordManager(RecordManager *manager, size_t capacity) {
