#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char* purpose;
} Record;

// Function to generate random numbers within a range using seed
long generateRandom(long min, long max, unsigned int *seed) {
    const unsigned int a = 1103515245;
    const unsigned int c = 12345;
    const unsigned int m = 1 << 31;

    // Update the seed and return a random number within [min, max)
    *seed = (a * (*seed) + c) % m;
    long rand_num = ((*seed) / (float)m) * ((max - min) + 1) + min;
    return rand_num;
}

// Function to create records with selective initialization
size_t createRecords(Record **records, int numRecords, unsigned int seed, const char* template_str, 
                     long offset_min, long offset_max, const int *init_indices, int init_count,
                     size_t memory_threshold) {

    // Allocate memory for the arrays
    long *offsets = (long *)calloc(numRecords, sizeof(long));
    int *keys = (int *)malloc(numRecords * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 0;
    }

    // Total memory size
    size_t total_memory_size = numRecords * sizeof(long) + numRecords * sizeof(int);

    // Initialize records array with selective initialization
    for (int i = 0; i < numRecords; ++i) {
        if (!init_indices || (init_count > 0 && !bsearch(&i, init_indices, init_count, sizeof(int), cmp_int))) {
            offsets[i] = 0;
            keys[i] = -1;
        } else {
            unsigned int current_seed = seed + i; // Unique seed for each element
            offsets[i] = generateRandom(offset_min, offset_max, &current_seed);
            keys[i] = i; // Key derived from the index
            total_memory_size += sizeof(char *) + strlen(template_str) + 1; // Memory for the string pointer and the string itself
        }
    }

    *records = (Record *)calloc(numRecords, sizeof(Record));

    if (!*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return 0;
    }

    total_memory_size += numRecords * sizeof(Record);

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];

        if (keys[i] != -1) { // Check if initialized
            char purpose_buffer[256];
            snprintf(purpose_buffer, sizeof(purpose_buffer), template_str, keys[i]);

            char *purpose = strdup(purpose_buffer);
            if (!purpose) {
                fprintf(stderr, "Memory allocation for string failed.\n");
                free(offsets);
                free(keys);
                free(*records);
                return 0;
            }

            (*records)[i].purpose = purpose;
            total_memory_size += strlen((*records)[i].purpose) + 1; // Include null terminator
        } else {
            (*records)[i].purpose = NULL;
        }
    }

    if (total_memory_size > memory_threshold) {
        fprintf(stderr, "Warning: Total memory usage exceeded threshold.\n");
    }

    free(offsets);
    free(keys);

    return total_memory_size;
}

// Comparison function for bsearch
int cmp_int(const void *a, const void *b) {
    int arg1 = *(const int *)a;
    int arg2 = *(const int *)b;

    return (arg1 > arg2) - (arg1 < arg2);
}
