#include <time.h>

typedef struct {
    int value;
} Record;

typedef void (*DataInitCallback)(void* buffer, size_t size);

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    void*** dataBuffers;
    size_t capacity;
    size_t count;
    DataInitCallback initDataCallback;
    int logEnabled;
    FILE* logFile;
} DynamicArrayManager;

void LogError(const char *message) {
    if (logEnabled && logFile != NULL) {
        time_t now = time(NULL);
        fprintf(logFile, "[%s] Error: %s\n", ctime(&now), message);
    }
}

DynamicArrayManager* InitializeManager(size_t initialCapacity, DataInitCallback initDataCallback, int logEnabled) {
    DynamicArrayManager* manager = (DynamicArrayManager*)malloc(sizeof(DynamicArrayManager));
    if (!manager) {
        LogError("Failed to allocate memory for manager");
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->initDataCallback = initDataCallback;
    manager->logEnabled = logEnabled;

    manager->offsets = (long*)malloc(initialCapacity * sizeof(long));
    manager->keys = (int*)malloc(initialCapacity * sizeof(int));
    manager->records = (Record**)malloc(initialCapacity * sizeof(Record*));
    manager->dataBuffers = (void***)malloc(initialCapacity * sizeof(void**));

    if (!manager->offsets || !manager->keys || !manager->records || !manager->dataBuffers) {
        LogError("Failed to allocate memory for arrays");
        free(manager);
        return NULL;
    }

    if (logEnabled) {
        manager->logFile = fopen("error.log", "a");
        if (!manager->logFile) {
            LogError("Failed to open log file");
        }
    } else {
        manager->logFile = NULL;
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        manager->records[i] = NULL;
        manager->dataBuffers[i] = NULL;
    }

    return manager;
}

int UpdateManager(DynamicArrayManager* manager, long offset, int key, Record record) {
    if (offset < 0 || key < 0) {
        LogError("Invalid offset or key");
        return -1;
    }

    size_t index = offset % manager->capacity;

    if (manager->records[index] == NULL) {
        // Allocate memory for the new record and data buffer
        manager->records[index] = &record;

        void* dataBuffer = malloc(sizeof(int));  // Example buffer allocation
        if (!dataBuffer) {
            LogError("Failed to allocate memory for data buffer");
            return -1;
        }

        if (manager->initDataCallback != NULL) {
            manager->initDataCallback(dataBuffer, sizeof(int));
        }

        manager->dataBuffers[index] = &dataBuffer;

        // Store the key and offset
        manager->keys[index] = key;
        manager->offsets[index] = offset;

        if (manager->count < manager->capacity) {
            manager->count++;
        }
    } else {
        // Update existing record
        Record* existingRecord = manager->records[index];
        *existingRecord = record;

        // Optionally update the data buffer
        void** dataBufferPtr = manager->dataBuffers[index];
        if (manager->initDataCallback != NULL) {
            manager->initDataCallback(*dataBufferPtr, sizeof(int));
        }
    }

    return 0;
}

void FreeManager(DynamicArrayManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->dataBuffers[i] != NULL) {
            free(*manager->dataBuffers[i]);
        }
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->dataBuffers);

    if (manager->logEnabled && manager->logFile != NULL) {
        fclose(manager->logFile);
    }

    free(manager);
}

void ExampleDataInitCallback(void* buffer, size_t size) {
    // Custom initialization logic
    memset(buffer, 0, size);
}
