        return NULL;
    }

    collection->records = malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        log_error("Failed to allocate memory for records.");
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

int record_exists(RecordCollection* collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

void resize_records(RecordCollection* collection) {
    size_t new_capacity = collection->capacity * 2;
    Record* resized_records = realloc(collection->records, new_capacity * sizeof(Record));

    if (!resized_records) {
        log_error("Failed to reallocate memory for records.");
        return; // Handle failure
    }

    collection->records = resized_records;
    collection->capacity = new_capacity;
}

void add_record(RecordCollection* collection, int key, long offset, CustomDataType* data) {
    pthread_mutex_lock(&collection->mutex);

    if (record_exists(collection, key)) {
        log_error("Duplicate key detected. Skipping record.");
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    if (collection->count == collection->capacity) {
        resize_records(collection);
        if (collection->count == collection->capacity) { // Check again after resizing
            pthread_mutex_unlock(&collection->mutex);
            return; // Handle failure
        }
    }

    Record new_record = {key, offset, data};
    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->mutex);
}

void free_record_collection(RecordCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].data);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int main() {
    RecordCollection* collection = init_record_collection(10);

    if (!collection) return 1;

    for (int i = 0; i < 15; ++i) { // Example usage with potential duplicate keys
        CustomDataType* data = malloc(sizeof(CustomDataType));
        if (!data) {
            log_error("Failed to allocate memory for CustomDataType.");
            continue;
        }
        data->value = i * 10;

        add_record(collection, i, (long)i * 1000, data);
    }

    free_record_collection(collection);

    return 0;
}
```

This code defines a structure `RecordCollection` that contains an array of records with synchronization mechanisms. It includes functions to initialize the collection, check for existing keys, resize the record storage dynamically if needed, and add new records while ensuring thread safety using mutex locks. Error handling is incorporated throughout, especially in memory allocation processes, along with basic logging functionality. The program also demonstrates how to use these functionalities.']

