typedef struct {
    size_t length;
    char *data;
} MemoryStruct;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->length + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->length]), contents, realsize);
    mem->length += realsize;
    mem->data[mem->length] = '\0';

    return realsize;
}

void logMessage(const char *level, const char *message) {
    pthread_mutex_lock(&lock);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] [%s]: %s\n", timestamp, level, message);
    pthread_mutex_unlock(&lock);
}

void generateRandomString(char *str, size_t length, const char *charset) {
    const size_t charsetSize = strlen(charset);
    for (size_t i = 0; i < length; ++i) {
