    chunk.length = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "https://api.example.com/verify?transaction_id=%s", transaction->transaction_id);

        curl_easy_setopt(curl, CURLOPT_URL, buffer);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            logMessage("ERROR", "Failed to verify transaction with API");
            free(chunk.data);
            curl_easy_cleanup(curl);
