        free(chunk.data);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return 1;  // Assume valid for demonstration purposes
}

void processTransactionData(const char *filename, const char *start_date, const char *end_date) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        logMessage("ERROR", "Failed to open file");
        return;
    }

    Transaction *transactions = NULL;
    size_t transaction_count = 0;
    double total_volume = 0.0;
    int valid_transaction_count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the CSV line and extract relevant fields
        Transaction newTransaction;
        sscanf(line, "%[^,],%lf,%[^,\n]", newTransaction.transaction_id, &newTransaction.amount, newTransaction.date);

        if (strcmp(newTransaction.date, start_date) >= 0 && strcmp(newTransaction.date, end_date) <= 0) {
            // Verify transaction with external API
            if (!verifyTransactionWithAPI(&newTransaction)) {
                logMessage("WARNING", "Transaction verification failed");
                continue;
            }

            // Calculate hash of the transaction ID
            char hashed_id[TRANSACTION_ID_LENGTH];
            hashTransactionId(newTransaction.transaction_id, hashed_id);
            printf("Hashed Transaction ID: %s\n", hashed_id);

            // Generate a random string for demonstration purposes
            char random_string[20];
            generateRandomString(random_string, sizeof(random_string) - 1, "abcdefghijklmnopqrstuvwxyz");
            logMessage("INFO", random_string);

            // Allocate memory dynamically for transactions
            size_t new_size = (transaction_count + 1) * sizeof(Transaction);
            Transaction *new_transactions = realloc(transactions, new_size);
            if (!new_transactions) {
                logMessage("ERROR", "Memory allocation failed");
                free(transactions);
                break;
            }
            transactions = new_transactions;

            // Store the transaction
            transactions[transaction_count++] = newTransaction;
            total_volume += newTransaction.amount;
            valid_transaction_count++;
        } else {
            logMessage("WARNING", "Invalid date format or out of range, skipping");
        }
    }

    fclose(file);

    if (transactions) {
        double average_amount = transaction_count ? total_volume / transaction_count : 0.0;
        printf("Total Transaction Volume: %.2f\n", total_volume);
        printf("Average Transaction Amount: %.2f\n", average_amount);

        logMessage("INFO", "Transaction processing completed");
        free(transactions);
    }

    printf("Valid Transactions Processed: %d\n", valid_transaction_count);
}

int main() {
    srand(time(NULL));
    processTransactionData("transactions.csv", "2023-01-01", "2023-12-31");
    return 0;
}
