#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char *transactionId;
    time_t timestamp;
    double amount;
    int isLegit;
} Transaction;

typedef struct {
    Transaction **transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionQueue;

typedef struct {
    TransactionQueue queue;
    pthread_rwlock_t cacheLock;
    Transaction **cache;
    size_t cacheCapacity;
    size_t cacheCount;
} StreamProcessor;

void log_message(int level, const char *message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("[INFO] %s\n", message);
    }
}

void error_exit(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
    exit(EXIT_FAILURE);
}

TransactionQueue* create_queue(size_t initial_capacity) {
    TransactionQueue *queue = malloc(sizeof(TransactionQueue));
    if (!queue) {
        error_exit("Failed to allocate memory for transaction queue.");
    }
    queue->transactions = calloc(initial_capacity, sizeof(Transaction *));
    if (!queue->transactions) {
        free(queue);
        error_exit("Failed to allocate memory for transactions.");
    }
    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_transaction(TransactionQueue *queue, Transaction *transaction) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        Transaction **new_transactions = realloc(queue->transactions, new_capacity * sizeof(Transaction *));
        if (!new_transactions) {
            error_exit("Failed to resize transaction queue.");
        }
        queue->transactions = new_transactions;
        queue->capacity = new_capacity;
    }

    queue->transactions[queue->count++] = transaction;

    pthread_mutex_unlock(&queue->lock);
}

void free_queue(TransactionQueue *queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        if (queue->transactions[i]) {
            free(queue->transactions[i]->transactionId);
            free(queue->transactions[i]);
        }
    }
    free(queue->transactions);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

void processTransactionStream(StreamProcessor *processor, const char *sourceData) {
    // Simulate dynamic schema parsing and validation
    Transaction *transaction = malloc(sizeof(Transaction));
    if (!transaction) {
        error_exit("Failed to allocate memory for transaction.");
    }

    // Parse source data into transaction fields (simulated)
    transaction->transactionId = strdup("txn12345");
    transaction->timestamp = time(NULL);
    transaction->amount = 100.0;
    transaction->isLegit = 1; // Assume legitimacy check passed

    // Filter transactions by date range
    time_t current_time = time(NULL);
    if (difftime(current_time, transaction->timestamp) < 60*60*24*30) { // Within the last month
        enqueue_transaction(&processor->queue, transaction);

        // Simulate API call for verification with retry logic on failure
        int api_success = 1; // Assume API call succeeded
        if (!api_success) {
            log_message(LOG_LEVEL_ERROR, "API call failed. Retrying...");
            // Retry mechanism (not fully implemented)
        }

        // Cache the transaction
        pthread_rwlock_wrlock(&processor->cacheLock);
        if (processor->cacheCount < processor->cacheCapacity) {
            processor->cache[processor->cacheCount++] = transaction;
        } else {
            // Implement cache eviction policy (LRU, FIFO, etc.)
            free(processor->cache[0]);  // Simplest form of eviction
            memmove(processor->cache, &processor->cache[1], 
                    (processor->cacheCapacity - 1) * sizeof(Transaction *));
            processor->cache[processor->cacheCapacity - 1] = transaction;
        }
        pthread_rwlock_unlock(&processor->cacheLock);

        // Log processing details
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Processed transaction ID: %s", transaction->transactionId);
        log_message(LOG_LEVEL_DEBUG, log_buffer);

        // Detect anomalies (simple threshold-based)
        if (transaction->amount > 10000.0) {
            log_message(LOG_LEVEL_WARNING, "Anomaly detected: High transaction amount.");
        }
    } else {
        free(transaction->transactionId);
        free(transaction);
    }
}

void cleanup(StreamProcessor *processor) {
    // Free resources
    free_queue(&processor->queue);

    pthread_rwlock_wrlock(&processor->cacheLock);
    for (size_t i = 0; i < processor->cacheCount; ++i) {
        free(processor->cache[i]->transactionId);
        free(processor->cache[i]);
    }
    free(processor->cache);
    pthread_rwlock_unlock(&processor->cacheLock);

    pthread_rwlock_destroy(&processor->cacheLock);
    free(processor);
}

int main() {
    StreamProcessor *processor = malloc(sizeof(StreamProcessor));
    if (!processor) {
        error_exit("Failed to allocate memory for stream processor.");
    }

    processor->queue = *create_queue(10);
    processor->cacheCapacity = MAX_CACHE_SIZE;
    processor->cache = calloc(MAX_CACHE_SIZE, sizeof(Transaction *));
    if (!processor->cache) {
        free_queue(&processor->queue.queue);
        free(processor);
        error_exit("Failed to allocate memory for cache.");
    }
    processor->cacheCount = 0;
    pthread_rwlock_init(&processor->cacheLock, NULL);

    // Simulate processing stream data
    const char *data_stream[] = {"source1_data", "source2_data"};
    size_t num_sources = sizeof(data_stream) / sizeof(data_stream[0]);

    for (size_t i = 0; i < num_sources; ++i) {
        processTransactionStream(processor, data_stream[i]);
    }

    cleanup(processor);
    return 0;
}
