#define MAX_CONFIGS 5000
#define DEFAULT_RANGE_START 1
#define DEFAULT_RANGE_END 100

typedef struct {
    int config_value;
    char *settings;
} Config;

typedef struct {
    Config *configs[MAX_CONFIGS];
    size_t count;
    double *doubles;
    char **string_keys;
    pthread_mutex_t lock;
    pthread_mutex_t log_lock;
} MemoryManager;

typedef struct {
    time_t timestamp;
    int user_id;
} AccessLog;

static MemoryManager manager = {0};

void initialize_manager(size_t initial_size) {
    pthread_mutex_init(&manager.lock, NULL);
    pthread_mutex_init(&manager.log_lock, NULL);

    manager.count = 0;
    manager.doubles = malloc(initial_size * sizeof(double));
    manager.string_keys = calloc(initial_size, sizeof(char*));

    for (size_t i = 0; i < initial_size; ++i) {
        manager.configs[i] = malloc(sizeof(Config));
        manager.configs[i]->settings = malloc(256); // Example size
        manager.configs[i]->config_value = 0;
    }
}

void deallocate_manager() {
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.configs[i]->settings);
        free(manager.configs[i]);
    }

    free(manager.doubles);
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.string_keys[i]);
    }
    free(manager.string_keys);

    pthread_mutex_destroy(&manager.lock);
    pthread_mutex_destroy(&manager.log_lock);
}

int is_unique_key(const char *key, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (manager.string_keys[i] && strcmp(key, manager.string_keys[i]) == 0) {
            return 0;
        }
    }
    return 1;
}

void log_access(int user_id, int index) {
    pthread_mutex_lock(&manager.log_lock);

    // Log access details; for simplicity, we just print it.
    printf("Config %d accessed by User %d at %ld\n", index, user_id, time(NULL));

    pthread_mutex_unlock(&manager.log_lock);
}

void update_configs(size_t new_size, int range_start, int range_end) {
    pthread_mutex_lock(&manager.lock);

    if (new_size > manager.count) {
        // Resize arrays
        double *temp_doubles = realloc(manager.doubles, new_size * sizeof(double));
        char **temp_keys = realloc(manager.string_keys, new_size * sizeof(char*));

        for (size_t i = manager.count; i < new_size; ++i) {
            manager.configs[i] = malloc(sizeof(Config));
            manager.configs[i]->settings = malloc(256); // Example size
            manager.configs[i]->config_value = 0;
        }

        if (temp_doubles && temp_keys) {
            manager.doubles = temp_doubles;
            manager.string_keys = temp_keys;
        } else {
            // Handle reallocation failure gracefully
            fprintf(stderr, "Failed to resize memory\n");
            pthread_mutex_unlock(&manager.lock);
            return;
        }
    }

    for (size_t i = 0; i < new_size && i < MAX_CONFIGS; ++i) {
        if (!manager.configs[i] || !manager.string_keys[i]) continue;

        int unique_key_found = 0;
        while (!unique_key_found) {
            char key[20];
            snprintf(key, sizeof(key), "key_%zu", rand() % (range_end - range_start + 1) + range_start);

            if (is_unique_key(key, manager.count)) {
                unique_key_found = 1;
                manager.string_keys[i] = strdup(key);
            } else {
                fprintf(stderr, "Duplicate key found: %s\n", key);
            }
        }

        manager.configs[i]->config_value = rand() % (range_end - range_start + 1) + range_start;
    }

    manager.count = new_size;

    pthread_mutex_unlock(&manager.lock);
}

void access_config(int user_id, size_t index) {
    if (index >= manager.count || !manager.configs[index]) return;

    log_access(user_id, index);

    // Simulate config usage
    printf("Accessing Config %zu with value: %d\n", index, manager.configs[index]->config_value);
}

void resize_and_update_configs(size_t new_size, int range_start, int range_end) {
    if (new_size > MAX_CONFIGS) {
        fprintf(stderr, "Requested size exceeds maximum allowed configs\n");
        return;
    }

    update_configs(new_size, range_start, range_end);
}

int main() {
    initialize_manager(1000); // Initial pre-allocation

    resize_and_update_configs(2000, DEFAULT_RANGE_START, DEFAULT_RANGE_END);

