#define ERROR_MEMORY_ALLOCATION -2

int receive_data(int socket_fd, int *data_array, size_t max_ints) {
    // Simulated function to mimic receiving data from a network socket.
    // In actual implementation, this would involve non-blocking I/O or select/poll for robustness.

