    size_t total_bytes_to_receive = max_ints * sizeof(int);
    while (bytes_received < total_bytes_to_receive) {
        ssize_t received = recv(socket_fd, data_array + bytes_received, total_bytes_to_receive - bytes_received, 0);
        if (received == -1) {
            // Handle network error or retry logic as needed
            return ERROR_MEMORY_ALLOCATION;
        }
        if (received == 0) {
            // Connection closed by peer; handle appropriately.
            return ERROR_MEMORY_ALLOCATION;
        }
        bytes_received += received;
    }
    return SUCCESS;
}

int find_largest_integer(const int *array, size_t num_ints) {
    if (num_ints == 0) {
        fprintf(stderr, "Array is empty.\n");
        exit(EXIT_FAILURE);
    }

    int largest = array[0];
    for (size_t i = 1; i < num_ints; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int process_socket_data(int socket_fd, size_t max_request) {
    if (max_request > MAX_INTS) {
        fprintf(stderr, "Request exceeds maximum allowed integers.\n");
        return ERROR_REQUEST_TOO_LARGE;
    }

    int *data_array = malloc(max_request * sizeof(int));
    if (!data_array) {
        perror("Failed to allocate memory for data array");
        return ERROR_MEMORY_ALLOCATION;
    }

    int result = receive_data(socket_fd, data_array, max_request);
    if (result != SUCCESS) {
        free(data_array);
        return result;
    }

    int largest_int = find_largest_integer(data_array, max_request);

    free(data_array); // Ensure we free the allocated memory
    return largest_int;
}
