['Below is a C code implementation of the described task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 1000
#define MAX_RECORDS 10000

typedef struct {
    int value;
} CustomData;

typedef struct {
    int key;
    long offset;
    CustomData *data;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate record collection");
        return NULL;
    }

    collection->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!collection->records) {
        perror("Failed to allocate records array");
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int record_exists(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

void resize_collection_if_needed(RecordCollection *collection) {
    if (collection->count >= collection->capacity && collection->capacity < MAX_RECORDS) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            perror("Failed to resize records array");
            return;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
}

int add_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    if (record_exists(collection, key)) {
        printf("Error: Duplicate key %d\n", key);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    resize_collection_if_needed(collection);

    Record new_record = { .key = key, .offset = offset, .data = malloc(sizeof(CustomData)) };
    if (!new_record.data) {
        perror("Failed to allocate custom data");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->records[collection->count++] = new_record;

    printf("Added record with key %d\n", key);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_record(RecordCollection *collection, int key, int newValue) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].data->value = newValue;
            printf("Updated record with key %d\n", key);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    printf("Error: Record with key %d not found\n", key);
    pthread_mutex_unlock(&collection->lock);
    return -1;
}

void delete_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            free(collection->records[i].data);
            memmove(&collection->records[i], &collection->records[i + 1],
                    (--collection->count - i) * sizeof(Record));
            printf("Deleted record with key %d\n", key);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    printf("Error: Record with key %d not found\n", key);

    pthread_mutex_unlock(&collection->lock);
}

void destroy_record_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].data);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Placeholder functions for web API integration

void handle_put_request(RecordCollection *collection, int key, int newValue) {
    update_record(collection, key, newValue);
}

void handle_delete_request(RecordCollection *collection, int key) {
    delete_record(collection, key);
}
```

### Key Points:
- **Memory Management**: Uses `malloc`, `realloc`, and `free` to manage memory dynamically.
- **Concurrency**: Utilizes a mutex (`pthread_mutex_t`) to ensure thread safety when accessing or modifying the collection.
- **Error Handling**: Logs errors for duplicate keys, allocation failures, etc.
- **Dynamic Resizing**: Doubles the capacity of the array when needed, up to a maximum limit.
- **API Placeholder Functions**: Includes simple functions for handling PUT and DELETE requests.']

