#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <time.h>
#include <pthread.h>

// Define constants for maximum buffer sizes and cache settings
#define MAX_BUFFER_SIZE 4096
#define CACHE_MAX_ENTRIES 1000
#define DATE_FORMAT "%Y-%m-%d"
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

typedef struct {
    char *transaction_id;
    double amount;
    time_t transaction_date;
} Transaction;

typedef struct {
    Transaction **transactions;
    size_t count;
    size_t capacity;
} TransactionList;

typedef struct {
    TransactionList *valid_transactions;
    pthread_mutex_t lock;
    int valid_count;
    int invalid_format_count;
    double total_volume;
    double average_amount;
} Stats;

// Global variables
Stats global_stats = {0};
pthread_mutex_t stats_lock;

// Function declarations
void* processTransactionData(FILE *file, const char *start_date_str, const char *end_date_str);
void parseCSVLine(const char *line, Transaction **transaction, int *valid_format);
time_t stringToTime(const char *date_str);
int isDateInRange(time_t date, time_t start_date, time_t end_date);
void addTransaction(TransactionList *list, Transaction *transaction);
void calculateStats(Stats *stats);
void logWarning(const char *message, int level);

// Cache for API verification
typedef struct {
    char *transaction_id;
    int verified;
} VerificationCacheEntry;

VerificationCacheEntry *verification_cache[CACHE_MAX_ENTRIES];
size_t cache_index = 0;

int verifyTransactionWithAPI(const char *transaction_id) {
    // Simulated API call with caching mechanism
    for (size_t i = 0; i < CACHE_MAX_ENTRIES; ++i) {
        if (verification_cache[i] != NULL && strcmp(verification_cache[i]->transaction_id, transaction_id) == 0) {
            return verification_cache[i]->verified;
        }
    }

    // Simulated API call
    int verified = rand() % 2; // Randomly simulate success or failure

    // Update cache with new entry
    verification_cache[cache_index] = malloc(sizeof(VerificationCacheEntry));
    if (verification_cache[cache_index] != NULL) {
        verification_cache[cache_index]->transaction_id = strdup(transaction_id);
        verification_cache[cache_index]->verified = verified;
        cache_index = (cache_index + 1) % CACHE_MAX_ENTRIES;
    }

    return verified;
}

void* processTransactionData(FILE *file, const char *start_date_str, const char *end_date_str) {
    char line[MAX_BUFFER_SIZE];
    TransactionList transactions = {0};
    pthread_mutex_init(&global_stats.lock, NULL);
    time_t start_date = stringToTime(start_date_str);
    time_t end_date = stringToTime(end_date_str);

    while (fgets(line, sizeof(line), file)) {
        Transaction *transaction;
        int valid_format;

        parseCSVLine(line, &transaction, &valid_format);

        if (!valid_format) {
            logWarning("Invalid date format encountered", LOG_LEVEL_INFO);
            free(transaction->transaction_id);
            free(transaction);
            continue;
        }

        if (verifyTransactionWithAPI(transaction->transaction_id)) {
            pthread_mutex_lock(&global_stats.lock);
            global_stats.valid_count++;
            global_stats.invalid_format_count += !valid_format;
            addTransaction(&transactions, transaction);
            pthread_mutex_unlock(&global_stats.lock);
        } else {
            logWarning("Transaction verification failed", LOG_LEVEL_INFO);
        }

        // Memory management
        if (transactions.count >= transactions.capacity) {
            size_t new_capacity = transactions.capacity == 0 ? 1024 : transactions.capacity * 2;
            Transaction **new_array = realloc(transactions.transactions, new_capacity * sizeof(Transaction *));
            if (!new_array) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }
            transactions.transactions = new_array;
            transactions.capacity = new_capacity;
        }

        free(transaction->transaction_id);
        free(transaction);
    }

    calculateStats(&global_stats);

    for (size_t i = 0; i < transactions.count; ++i) {
        free(transactions.transactions[i]->transaction_id);
        free(transactions.transactions[i]);
    }
    free(transactions.transactions);

    pthread_mutex_destroy(&global_stats.lock);
    return NULL;
}

void parseCSVLine(const char *line, Transaction **transaction, int *valid_format) {
    // Simulated CSV parsing logic
    *transaction = malloc(sizeof(Transaction));
    if (!*transaction) {
        fprintf(stderr, "Memory allocation failed\n");
        *valid_format = 0;
        return;
    }

    (*transaction)->transaction_id = strdup("12345"); // Placeholder
    (*transaction)->amount = 100.0; // Placeholder
    const char *date_str = "2023-10-01"; // Placeholder

    time_t transaction_date = stringToTime(date_str);
    if (transaction_date == ((time_t)-1)) {
        free((*transaction)->transaction_id);
        free(*transaction);
        *valid_format = 0;
    } else {
        (*transaction)->transaction_date = transaction_date;
        *valid_format = 1;
    }
}

time_t stringToTime(const char *date_str) {
    struct tm tm = {0};
    if (strptime(date_str, DATE_FORMAT, &tm) == NULL) {
        return ((time_t)-1);
    }
    return mktime(&tm);
}

int isDateInRange(time_t date, time_t start_date, time_t end_date) {
    return (date >= start_date && date <= end_date);
}

void addTransaction(TransactionList *list, Transaction *transaction) {
    list->transactions[list->count++] = transaction;
}

void calculateStats(Stats *stats) {
    pthread_mutex_lock(&stats->lock);
    stats->total_volume = 0.0;
    for (size_t i = 0; i < stats->valid_transactions->count; ++i) {
        stats->total_volume += stats->valid_transactions->transactions[i]->amount;
    }
    stats->average_amount = stats->valid_transactions->count > 0 ? stats->total_volume / stats->valid_transactions->count : 0.0;
    pthread_mutex_unlock(&stats->lock);
}

void logWarning(const char *message, int level) {
    if (level >= LOG_LEVEL_INFO) {
        printf("WARNING: %s\n", message);
    }
}
