#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PROFILES 10000
#define HASH_TABLE_SIZE 10007

typedef struct UserProfile {
    int id;
    char username[256];
    pthread_mutex_t lock;
    struct UserProfile **friends;
    size_t friend_count;
    int blocked_friends[MAX_PROFILES]; // Simplified with a fixed-size array for simplicity
    time_t last_active;
    unsigned long version;
} UserProfile;

typedef struct HashNode {
    UserProfile *profile;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **table;
    pthread_mutex_t lock;
} HashTable;

HashTable hash_table;
UserProfile *profiles[MAX_PROFILES];
pthread_mutex_t profile_locks[MAX_PROFILES] = {0};

void init_hash_table(HashTable *ht) {
    ht->table = (HashNode **)malloc(HASH_TABLE_SIZE * sizeof(HashNode *));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        ht->table[i] = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
}

unsigned long hash(int id) {
    return id % HASH_TABLE_SIZE;
}

void add_profile(UserProfile *profile) {
    unsigned long index = hash(profile->id);

    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    node->profile = profile;
    node->next = NULL;

    pthread_mutex_lock(&hash_table.lock);
    if (!hash_table.table[index]) {
        hash_table.table[index] = node;
    } else {
        HashNode *current = hash_table.table[index];
        while (current->next) current = current->next;
        current->next = node;
    }
    pthread_mutex_unlock(&hash_table.lock);

    profiles[profile->id] = profile;
    pthread_mutex_init(&profile_locks[profile->id], NULL);
}

UserProfile *get_profile(int id) {
    unsigned long index = hash(id);

    HashNode *current = hash_table.table[index];
    while (current) {
        if (current->profile->id == id) {
            return current->profile;
        }
        current = current->next;
    }

    return NULL;
}

void update_username(int id, const char *new_username) {
    UserProfile *profile = get_profile(id);
    if (!profile) return;

    pthread_mutex_lock(&profile->lock);
    strncpy(profile->username, new_username, sizeof(profile->username));
    profile->version++;
    pthread_mutex_unlock(&profile->lock);
}

void block_friend(int id, int friend_id) {
    UserProfile *user = get_profile(id);
    if (!user || user->id == friend_id) return;

    pthread_mutex_lock(&user->lock);
    user->blocked_friends[friend_id] = 1;
    pthread_mutex_unlock(&user->lock);
}

void unblock_friend(int id, int friend_id) {
    UserProfile *user = get_profile(id);
    if (!user || user->id == friend_id) return;

    pthread_mutex_lock(&user->lock);
    user->blocked_friends[friend_id] = 0;
    pthread_mutex_unlock(&user->lock);
}

void cleanup_inactive_profiles() {
    time_t now = time(NULL);

    for (int i = 0; i < MAX_PROFILES; ++i) {
        UserProfile *profile = profiles[i];
        if (!profile) continue;

        pthread_mutex_lock(&profile->lock);
        if (now - profile->last_active > 30*24*60*60) { // Example: inactive for more than a month
            // Handle cleanup logic, such as unlinking from hash table and freeing memory
            free(profile->friends);
            pthread_mutex_unlock(&profile_locks[i]);
            free(profile); // Simplified cleanup
        }
        pthread_mutex_unlock(&profile->lock);
    }
}

void log_change(const char *message) {
    // Implement a thread-safe logging mechanism here
    printf("%s\n", message);  // Placeholder for actual logging logic
}

void rollback_profile(int id, unsigned long version) {
    UserProfile *profile = get_profile(id);
    if (!profile || profile->version < version) return;

    pthread_mutex_lock(&profile->lock);
    // Implement logic to revert to the specified version
    // This may involve maintaining a history of changes or states
    pthread_mutex_unlock(&profile->lock);
}

void monitor_memory_usage() {
    // Implement memory monitoring and reporting mechanism here
}

int main() {
    init_hash_table(&hash_table);

    // Example usage
    UserProfile *new_profile = (UserProfile *)malloc(sizeof(UserProfile));
    new_profile->id = 1;
    strcpy(new_profile->username, "Alice");
    add_profile(new_profile);

    update_username(1, "Alice Updated");

    block_friend(1, 2);   // Assume user with ID 2 exists
    unblock_friend(1, 2);

    cleanup_inactive_profiles();
    log_change("Test log entry");

    return 0;
}
