#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <microhttpd.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
} CustomDataType;

typedef struct {
    int key;
    long offset;
    CustomDataType *data;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection rc = {NULL, 0, 0};

pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *msg) {
    pthread_mutex_lock(&log_lock);
    fprintf(stderr, "%s\n", msg);
    fflush(stderr);
    pthread_mutex_unlock(&log_lock);
}

void free_record(Record *record) {
    if (record != NULL) {
        free(record->data);
        free(record);
    }
}

int init_record_collection(size_t initial_capacity) {
    pthread_mutex_init(&rc.lock, NULL);
    rc.records = calloc(initial_capacity, sizeof(Record *));
    if (!rc.records) return -1;
    rc.capacity = initial_capacity;
    return 0;
}

void cleanup_record_collection() {
    pthread_mutex_lock(&rc.lock);

    for (size_t i = 0; i < rc.count; ++i) {
        free_record(rc.records[i]);
    }

    free(rc.records);
    rc.records = NULL;

    pthread_mutex_unlock(&rc.lock);
    pthread_mutex_destroy(&rc.lock);
}

int add_or_update_record(int key, long offset, int value) {
    pthread_mutex_lock(&rc.lock);

    for (size_t i = 0; i < rc.count; ++i) {
        if (rc.records[i]->key == key) {
            pthread_mutex_unlock(&rc.lock);
            log_message("Duplicate key detected. Record update skipped.");
            return -1;
        }
    }

    if (rc.count >= rc.capacity) {
        size_t new_capacity = rc.capacity * 2;
        Record **new_records = realloc(rc.records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&rc.lock);
            log_message("Memory allocation failed during resize.");
            return -1;
        }
        memset(new_records + rc.capacity, 0, (new_capacity - rc.capacity) * sizeof(Record *));
        rc.records = new_records;
        rc.capacity = new_capacity;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&rc.lock);
        log_message("Memory allocation failed for record.");
        return -1;
    }

    record->key = key;
    record->offset = offset;
    record->data = malloc(sizeof(CustomDataType));
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&rc.lock);
        log_message("Memory allocation failed for custom data type.");
        return -1;
    }

    record->data->value = value;

    rc.records[rc.count++] = record;

    pthread_mutex_unlock(&rc.lock);
    return 0;
}

int update_record_value(int key, int new_value) {
    pthread_mutex_lock(&rc.lock);

    for (size_t i = 0; i < rc.count; ++i) {
        if (rc.records[i]->key == key) {
            rc.records[i]->data->value = new_value;
            pthread_mutex_unlock(&rc.lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&rc.lock);
    log_message("Record not found for update.");
    return -1;
}

int delete_record(int key) {
    pthread_mutex_lock(&rc.lock);

    for (size_t i = 0; i < rc.count; ++i) {
        if (rc.records[i]->key == key) {
            free_record(rc.records[i]);
            memmove(&rc.records[i], &rc.records[i + 1],
                    (rc.count - i - 1) * sizeof(Record *));
            --rc.count;
            pthread_mutex_unlock(&rc.lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&rc.lock);
    log_message("Record not found for deletion.");
    return -1;
}

static int answer_to_connection(void *cls, struct MHD_Connection *connection,
                                const char *url, const char *method,
                                const char *version, const char *upload_data,
                                size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "PUT") == 0 || strcmp(method, "DELETE") == 0) {
        int key = atoi(url + strlen("/record/")); // Extract key from URL
        if (key <= 0) {
            const char *response_str = "Invalid request.";
            struct MHD_Response *response;
            response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
            int ret = MHD_queue_response(connection, MHD_HTTP_BAD_REQUEST, response);
            MHD_destroy_response(response);
            return ret;
        }

        if (strcmp(method, "PUT") == 0) {
            // Example logic for handling PUT request
            char *post_data = strdup(upload_data); // Duplicate post data
            int new_value = atoi(post_data);       // Simple value extraction

            free(post_data);

            if (update_record_value(key, new_value) != 0) {
                const char *response_str = "Record update failed.";
                struct MHD_Response *response;
                response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
                int ret = MHD_queue_response(connection, MHD_HTTP_INTERNAL_SERVER_ERROR, response);
                MHD_destroy_response(response);
                return ret;
            }

            const char *response_str = "Record updated successfully.";
            struct MHD_Response *response;
            response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
            int ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
            MHD_destroy_response(response);
            return ret;

        } else if (strcmp(method, "DELETE") == 0) {
            // Example logic for handling DELETE request
            if (delete_record(key) != 0) {
                const char *response_str = "Record deletion failed.";
                struct MHD_Response *response;
                response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
                int ret = MHD_queue_response(connection, MHD_HTTP_INTERNAL_SERVER_ERROR, response);
                MHD_destroy_response(response);
                return ret;
            }

            const char *response_str = "Record deleted successfully.";
            struct MHD_Response *response;
            response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
            int ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
            MHD_destroy_response(response);
            return ret;
        }
    }

    const char *response_str = "Method not allowed.";
    struct MHD_Response *response;
    response = MHD_create_response_from_buffer(strlen(response_str), (void *) response_str, MHD_RESPMEM_PERSISTENT);
    int ret = MHD_queue_response(connection, MHD_HTTP_METHOD_NOT_ALLOWED, response);
    MHD_destroy_response(response);
    return ret;
}

int main() {
    if (init_record_collection(100) != 0) {
        log_message("Failed to initialize record collection.");
        return EXIT_FAILURE;
    }

    struct MHD_Daemon *daemon;
    daemon = MHD_start_daemon(MHD_USE_SELECT_INTERNALLY, 8888, NULL, NULL,
                              &answer_to_connection, NULL,
                              MHD_OPTION_END);
    if (NULL == daemon) {
        log_message("Failed to start the HTTP server.");
        cleanup_record_collection();
        return EXIT_FAILURE;
    }

    printf("Server running on http://localhost:8888\n");
    getchar(); // Keep the program running

    MHD_stop_daemon(daemon);
    cleanup_record_collection();

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Memory Management**: Proper allocation, deallocation, and resizing of memory to manage records.
- **Concurrency**: Uses mutex locks for thread-safe operations on shared data structures.
- **Error Handling**: Logs errors with detailed messages for debugging and monitoring.
- **RESTful API**: Implements PUT and DELETE endpoints using `libmicrohttpd` for HTTP requests handling.
- **Scalability Considerations**: Designed to handle concurrent access efficiently, which can be extended for distributed systems.

