#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

typedef struct {
    double value;
    char *text;
    unsigned long timestamp;
} dataEntry;

// Global variables for thread safety and synchronization
dataEntry *dataCollection = NULL;
size_t capacity = 0, size = 0;
pthread_mutex_t collectionMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile = fopen("process_log.txt", "a");

void logOperation(const char *message) {
    pthread_mutex_lock(&collectionMutex);
    fprintf(logFile, "%s\n", message);
    fflush(logFile);
    pthread_mutex_unlock(&collectionMutex);
}

double computeAverage(double *array, size_t length) {
    double sum = 0.0;
    for (size_t i = 0; i < length; ++i) {
        sum += array[i];
    }
    return (length > 0) ? sum / length : 0.0;
}

void resizeDataCollection(size_t newCapacity) {
    dataEntry *newCollection = realloc(dataCollection, newCapacity * sizeof(dataEntry));
    if (newCollection == NULL) {
        logOperation("Error: Memory allocation failure during resizing.");
        return; // Handle memory error gracefully
    }
    capacity = newCapacity;
    dataCollection = newCollection;
    logOperation("Data collection resized successfully.");
}

void processAndPersistData(size_t initialEntries, double rangeMin, double rangeMax) {
    pthread_mutex_lock(&collectionMutex);
    if (capacity < initialEntries) {
        resizeDataCollection(initialEntries);
    }
    size = initialEntries;

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        dataCollection[i].value = rangeMin + ((double) rand() / RAND_MAX) * (rangeMax - rangeMin);
        char buffer[256];
        printf("Enter string for entry %zu: ", i);
        if (fgets(buffer, sizeof(buffer), stdin)) {
            size_t len = strlen(buffer);
            if (buffer[len-1] == '\n') buffer[--len] = '\0'; // Remove newline
            dataCollection[i].text = malloc(len + 1);
            if (dataCollection[i].text) {
                strcpy(dataCollection[i].text, buffer);
            } else {
                logOperation("Error: Memory allocation failure for string.");
                continue; // Handle memory error gracefully
            }
        } else {
            logOperation("Error: Failed to read input.");
            dataCollection[i].text = NULL;
        }
        dataCollection[i].timestamp = time(NULL);
    }
    pthread_mutex_unlock(&collectionMutex);

    double userInputs[100];
    size_t numInputs = 0;
    printf("Enter numbers (max 100, end with non-number): ");
    while (numInputs < 100) {
        if (scanf("%lf", &userInputs[numInputs]) != 1) break;
        ++numInputs;
    }

    double average = computeAverage(userInputs, numInputs);
    printf("Computed Average: %f\n", average);

    FILE *file = fopen("data_collection.dat", "wb");
    if (file == NULL) {
        logOperation("Error: Failed to open file for writing.");
        return;
    }

    fwrite(&size, sizeof(size), 1, file);
    for (size_t i = 0; i < size; ++i) {
        fwrite(&dataCollection[i], sizeof(dataEntry), 1, file);
        free(dataCollection[i].text); // Free strings after saving
    }
    fclose(file);

    logOperation("Data persisted to file successfully.");
}

void handlePeriodicSnapshots() {
    while (1) {
        sleep(60); // Take snapshot every minute

        pthread_mutex_lock(&collectionMutex);
        FILE *snapshotFile = fopen("snapshot.dat", "wb");
        if (!snapshotFile) {
            logOperation("Error: Failed to open snapshot file for writing.");
            pthread_mutex_unlock(&collectionMutex);
            continue;
        }

        fwrite(&size, sizeof(size), 1, snapshotFile);
        for (size_t i = 0; i < size; ++i) {
            fwrite(&dataCollection[i], sizeof(dataEntry), 1, snapshotFile);
        }
        fclose(snapshotFile);

        logOperation("Snapshot taken successfully.");
        pthread_mutex_unlock(&collectionMutex);
    }
}

int main() {
    processAndPersistData(10, 0.0, 100.0);

    pthread_t snapshotThread;
    pthread_create(&snapshotThread, NULL, (void *)handlePeriodicSnapshots, NULL);

    pthread_join(snapshotThread, NULL); // Wait for the thread to complete
    fclose(logFile);
    free(dataCollection);

    return 0;
}
