#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Helper function to find the largest unique integer.
int findLargestUnique(const int *array, size_t size) {
    if (size == 0) return INT_MIN; // Edge case: no elements

    int *seen = calloc(size, sizeof(int));
    int max_value = INT_MIN;

    for (size_t i = 0; i < size; ++i) {
        if (!seen[array[i]]) {
            seen[array[i]] = 1;
            if (array[i] > max_value) {
                max_value = array[i];
            }
        }
    }

    free(seen);
    return max_value == INT_MIN ? -1 : max_value; // Return -1 if no unique numbers
}

// Function to read, validate and process integers.
void processIntegers(int min_range, int max_range) {
    size_t capacity = 10;
    size_t count = 0;

    int *array = malloc(capacity * sizeof(int));
    if (!array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    printf("Enter integers (non-integer or EOF to stop):\n");

    while (scanf("%d", &array[count]) == 1) {
        if (count >= capacity) {
            size_t new_capacity = capacity * 2;
            int *temp = realloc(array, new_capacity * sizeof(int));
            if (!temp) {
                perror("Failed to reallocate memory");
                free(array);
                exit(EXIT_FAILURE);
            }
            array = temp;
            capacity = new_capacity;
        }

        // Validate integer range
        if (array[count] < min_range || array[count] > max_range) {
            fprintf(stderr, "Integer out of range: %d\n", array[count]);
            continue; // Skip invalid numbers
        }

        count++;
    }

    printf("Largest unique integer in the valid input is: %d\n",
           findLargestUnique(array, count));

    free(array);
}

int main() {
    int min_range = -1000;
    int max_range = 1000;

    processIntegers(min_range, max_range);

    return 0;
}
```

### Key Considerations

- **Memory Management**: The code uses `malloc` and `realloc` to handle dynamic memory allocation efficiently. It doubles the capacity when needed.

- **Error Handling**: Uses error checks for failed memory allocations with appropriate error messages.

- **Unique Values**: Utilizes an array (`seen`) to track unique integers in a given range, ensuring no duplicates affect the result.

- **Range Validation**: Each integer is checked against specified bounds. Invalid inputs are skipped without affecting valid data processing.

- **Output**: The largest unique integer within valid input constraints is printed. If no valid number exists, `-1` is returned.

This solution assumes a reasonable dataset size and system capacity to manage memory and avoid overflow issues by validating each input value carefully before processing.']

