#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEFAULT_INT_VALUE 0

// Global mutex for thread safety
pthread_mutex_t lock;

// Function to read integers from standard input into a dynamically allocated array
int* readIntegers(int *size) {
    int capacity = 10;
    int *array = malloc(capacity * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *size = 0;
    int value;
    while (scanf("%d", &value) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(int));
            if (!array) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        array[(*size)++] = value;
    }

    return array;
}

// Helper function to find the maximum integer in an array
int findMaxInteger(const int *array, int size) {
    if (size == 0) {
        fprintf(stderr, "Array is empty\n");
        exit(EXIT_FAILURE);
    }

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Simulated function to handle HTTP PUT requests
void handlePutRequest(const char *id, const char *data) {
    pthread_mutex_lock(&lock);
    // Update resource logic here
    printf("Resource with ID %s updated with data: %s\n", id, data);
    pthread_mutex_unlock(&lock);
}

// Simulated function to handle HTTP DELETE requests
void handleDeleteRequest(const char *id) {
    pthread_mutex_lock(&lock);
    // Delete resource and return default values logic here
    printf("Resource with ID %d deleted. Returning default value: %d\n", atoi(id), DEFAULT_INT_VALUE);
    pthread_mutex_unlock(&lock);
}

// Main function for demonstration purposes
int main() {
    pthread_mutex_init(&lock, NULL);

    int size;
    int *numbers = readIntegers(&size);

    printf("Largest integer: %d\n", findMaxInteger(numbers, size));

    // Simulate handling HTTP requests
    handlePutRequest("123", "updated_data");
    handleDeleteRequest("123");

    free(numbers);
    pthread_mutex_destroy(&lock);

    return 0;
}
