#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint64_t doc_id;
    char *content;
    time_t last_access_time;
    int ref_count;
} documentEntry;

typedef struct {
    documentEntry **entries;
    size_t capacity;
    pthread_mutex_t lock;
} DocumentArray;

#define CACHE_SIZE 10

// Cache structure
typedef struct {
    uint64_t doc_id;
    char *content;
    time_t last_access_time;
} cache_entry;

cache_entry cache[CACHE_SIZE];
int cache_index = 0;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void custom_allocator(char **ptr, size_t size) {
    pthread_mutex_lock(&DocumentArray.lock);
    *ptr = (char *)malloc(size);
    if (*ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&DocumentArray.lock);
}

void init_document_array(DocumentArray *docArray, size_t num_entries) {
    pthread_mutex_init(&docArray->lock, NULL);

    docArray->capacity = num_entries;
    docArray->entries = (documentEntry **)malloc(num_entries * sizeof(documentEntry *));
    if (!docArray->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_entries; ++i) {
        docArray->entries[i] = (documentEntry *)malloc(sizeof(documentEntry));
        if (!docArray->entries[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        docArray->entries[i]->doc_id = i + 1;
        custom_allocator(&docArray->entries[i]->content, 256); // Pre-allocate with a fixed size
        docArray->entries[i]->last_access_time = time(NULL);
        docArray->entries[i]->ref_count = 0;

        memset(docArray->entries[i]->content, 0, 256); // Initialize content buffer
    }
}

void update_last_access_time(DocumentArray *docArray, uint64_t doc_id) {
    pthread_mutex_lock(&docArray->lock);
    for (size_t i = 0; i < docArray->capacity; ++i) {
        if (docArray->entries[i]->doc_id == doc_id) {
            docArray->entries[i]->last_access_time = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&docArray->lock);
}

void increment_ref_count(DocumentArray *docArray, uint64_t doc_id) {
    pthread_mutex_lock(&docArray->lock);
    for (size_t i = 0; i < docArray->capacity; ++i) {
        if (docArray->entries[i]->doc_id == doc_id) {
            docArray->entries[i]->ref_count++;
            break;
        }
    }
    pthread_mutex_unlock(&docArray->lock);
}

documentEntry *get_document_entry(DocumentArray *docArray, uint64_t index) {
    pthread_mutex_lock(&docArray->lock);
    if (index >= 1 && index <= docArray->capacity) {
        documentEntry *entry = docArray->entries[index - 1];
        update_last_access_time(docArray, entry->doc_id);
        return entry;
    }
    pthread_mutex_unlock(&docArray->lock);
    return NULL;
}

void cache_document_entry(uint64_t doc_id, const char *content) {
    pthread_mutex_lock(&cache_lock);

    // Simple round-robin cache replacement
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].doc_id == 0 || cache[i].doc_id == doc_id) {
            cache[i].doc_id = doc_id;
            free(cache[i].content);
            custom_allocator(&cache[i].content, strlen(content) + 1);
            strcpy(cache[i].content, content);
            cache[i].last_access_time = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&cache_lock);
}

void flush_cache_to_disk() {
    // Implement disk flushing logic here
}

void process_operations(DocumentArray *docArray) {
    char operation[10];
    uint64_t doc_id, index;

    while (scanf("%s", operation) != EOF) {
        if (strcmp(operation, "read") == 0) {
            scanf("%lu", &index);
            documentEntry *entry = get_document_entry(docArray, index);
            if (entry) {
                printf("Content: %s\n", entry->content);
            } else {
                printf("Document not found.\n");
            }
        } else if (strcmp(operation, "update") == 0) {
            scanf("%lu", &index);
            char content[256];
            scanf(" %[^\n]", content); // Read line with spaces
            documentEntry *entry = get_document_entry(docArray, index);
            if (entry) {
                free(entry->content);
                custom_allocator(&entry->content, strlen(content) + 1);
                strcpy(entry->content, content);
                cache_document_entry(entry->doc_id, entry->content);
                printf("Document updated.\n");
            } else {
                printf("Document not found.\n");
            }
        } else if (strcmp(operation, "delete") == 0) {
            scanf("%lu", &index);
            pthread_mutex_lock(&docArray->lock);
            for (size_t i = 0; i < docArray->capacity; ++i) {
                if (docArray->entries[i]->doc_id == index) {
                    free(docArray->entries[i]->content);
                    free(docArray->entries[i]);
                    memmove(&docArray->entries[i], &docArray->entries[i + 1],
                            (docArray->capacity - i - 1) * sizeof(documentEntry *));
                    docArray->capacity--;
                    printf("Document deleted.\n");
                    break;
                }
            }
            pthread_mutex_unlock(&docArray->lock);
        }
    }

    flush_cache_to_disk();
}

int main() {
    DocumentArray docArray;
    init_document_array(&docArray, 100); // Initialize with 100 entries

    process_operations(&docArray);

    for (size_t i = 0; i < docArray.capacity; ++i) {
        free(docArray.entries[i]->content);
        free(docArray.entries[i]);
    }
    free(docArray.entries);
    pthread_mutex_destroy(&docArray.lock);

    return 0;
}
