#define MAX_BUFFER_SIZE 10000

typedef struct {
    int *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} IntegerStream;

IntegerStream* initialize_stream(size_t initial_capacity) {
    if (initial_capacity > MAX_BUFFER_SIZE || initial_capacity == 0) {
        return NULL;
    }

    IntegerStream *stream = malloc(sizeof(IntegerStream));
    stream->data = malloc(initial_capacity * sizeof(int));
    stream->count = 0;
    stream->capacity = initial_capacity;
    pthread_mutex_init(&stream->lock, NULL);
    return stream;
}

void free_stream(IntegerStream *stream) {
    if (stream != NULL) {
        free(stream->data);
        pthread_mutex_destroy(&stream->lock);
        free(stream);
    }
}

int validate_integer(char *packet) {
    char *endptr;
    long val = strtol(packet, &endptr, 10);

    // Check for conversion errors
    if (*endptr != '\0' || endptr == packet) {
        return 0; // Invalid integer
    }

    // Ensure the value fits in an int
    if (val < INT_MIN || val > INT_MAX) {
        return 0;
    }

    return 1;
}

int update_largest(int *largest, int new_value) {
    if (*largest == -1 || new_value > *largest) {
        *largest = new_value;
    }
    return *largest;
}

void process_integer_stream(IntegerStream *stream, char **packets, size_t num_packets) {
    int largest = -1;
    for (size_t i = 0; i < num_packets; ++i) {
        if (!validate_integer(packets[i])) continue;

        pthread_mutex_lock(&stream->lock);

        if (stream->count == stream->capacity) {
            size_t new_capacity = stream->capacity * 2;
            if (new_capacity > MAX_BUFFER_SIZE) {
                printf("Buffer overflow, terminating gracefully.\n");
                break;
            }
            int *new_data = realloc(stream->data, new_capacity * sizeof(int));
            if (!new_data) {
                printf("Memory allocation failed, exiting.\n");
                pthread_mutex_unlock(&stream->lock);
                exit(EXIT_FAILURE);
            }
            stream->data = new_data;
            stream->capacity = new_capacity;
        }

        int value = atoi(packets[i]);
        stream->data[stream->count++] = value;

        // Update the largest integer encountered
        update_largest(&largest, value);

        pthread_mutex_unlock(&stream->lock);
    }

    printf("Largest integer encountered: %d\n", largest);
}

int main() {
    IntegerStream *stream = initialize_stream(1000);
    if (!stream) {
        fprintf(stderr, "Failed to initialize stream.\n");
        return EXIT_FAILURE;
    }

    // Simulating packet input (in a real-world scenario, this would be network data)
    char *packets[] = {"42", "-1", "100", "abc", "5000"};
    size_t num_packets = sizeof(packets) / sizeof(packets[0]);

    process_integer_stream(stream, packets, num_packets);

    free_stream(stream);

    return EXIT_SUCCESS;
}
```']

