    TransactionProcessor() : stopFlag(false), logLevel(LogLevel::INFO) {}

    void processTransactionStream(const std::vector<Transaction>& transactions, 
                                  const std::tm& startDate, const std::tm& endDate);

private:
    void parseAndValidate(Transaction& transaction);
    bool verifyTransactionWithAPI(const Transaction& transaction);
    double calculateTotalVolume();
    double calculateAverageAmount();
    void logTransactionInfo(const Transaction& transaction, LogLevel level = LogLevel::INFO);
    void flushArchivedData();

