    std::condition_variable cv;
    std::queue<Transaction> transactionQueue;
    std::atomic<bool> stopFlag;
    std::unordered_map<std::string, double> cache; // Cache for API responses
    std::vector<double> slidingWindow; // For anomaly detection
    size_t slidingWindowSize = 1000; // Example window size

