    LogLevel logLevel;
};

void TransactionProcessor::processTransactionStream(const std::vector<Transaction>& transactions, 
                                                    const std::tm& startDate, const std::tm& endDate) {

    auto worker = [this]() {
        while (!stopFlag) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !transactionQueue.empty() || stopFlag; });

            if (stopFlag && transactionQueue.empty()) break;

            Transaction transaction = transactionQueue.front();
            transactionQueue.pop();
            lock.unlock();

            try {
                parseAndValidate(transaction);

                // Verify with external API
                bool isValid = verifyTransactionWithAPI(transaction);
                if (!isValid) continue;

                // Log transaction info
                logTransactionInfo(transaction);

                // Anomaly detection (conceptual)
                double avg = calculateAverageAmount();
                if (transaction.amount > 3 * avg) {
                    std::cout << "Anomalous Transaction Detected: ID " << transaction.id << "\n";
                }

            } catch (const std::exception& e) {
                logTransactionInfo(transaction, LogLevel::ERROR);
            }
        }
    };

    std::vector<std::thread> workers;
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back(worker);
    }

    for (const auto& transaction : transactions) {
        if (!isWithinDateRange(transaction.timestamp, startDate, endDate)) continue;

        std::lock_guard<std::mutex> lock(mtx);
        transactionQueue.push(transaction);
        cv.notify_one();
    }

    stopFlag = true;
    cv.notify_all();

    for (auto& worker : workers) {
        worker.join();
    }
}

