['Below is an example C++ code that addresses your requirements:

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <condition_variable>
#include <random>
#include <atomic>

#define MAX_RECORDS 50000

struct CustomDataType {
    int value;
    long offset;
    int key;
};

struct Record {
    int uniqueKey;
    long offset;
    CustomDataType* data;
};

class RecordManager {
private:
    std::vector<Record*> records_;
    std::unordered_map<int, size_t> keyIndexMap_;
    std::mutex mutex_;
    std::atomic<bool> running_;

public:
    RecordManager(size_t initialCapacity) : running_(true) {
        if (initialCapacity > MAX_RECORDS) initialCapacity = MAX_RECORDS;
        records_.reserve(initialCapacity);
    }

    ~RecordManager() {
        for (auto record : records_) {
            delete record->data;
            delete record;
        }
    }

    bool addOrUpdateRecord(int key, long offset, CustomDataType* data) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = keyIndexMap_.find(key);
        if (it != keyIndexMap_.end()) {
            records_[it->second]->offset = offset;
            delete records_[it->second]->data;
            records_[it->second]->data = data;
            return true; // Updated existing record
        }

        if (records_.size() >= MAX_RECORDS) {
            std::cerr << "Maximum capacity reached, unable to add more records.\n";
            return false;
        }

        Record* newRecord = new Record{key, offset, data};
        keyIndexMap_[key] = records_.size();
        records_.push_back(newRecord);

        return true; // Added new record
    }

    bool deleteRecord(int key) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = keyIndexMap_.find(key);
        if (it == keyIndexMap_.end()) {
            std::cerr << "Key not found for deletion.\n";
            return false;
        }

        size_t index = it->second;
        delete records_[index]->data;
        delete records_[index];

        records_[index] = records_.back();
        keyIndexMap_[records_[index]->uniqueKey] = index;

        records_.pop_back();
        keyIndexMap_.erase(it);

        return true; // Deleted record
    }

    void startBackgroundService() {
        std::thread([this]() {
            while (running_) {
                int delay = rand() % 1000;
                std::this_thread::sleep_for(std::chrono::milliseconds(delay));

                if (!running_.load()) break;

                std::cout << "Stopping background service...\n";
                // Send message to messaging system here
            }
        }).detach();
    }

    void stopBackgroundService() {
        running_ = false;
    }
};

// Simulated web API endpoint functions for PUT and DELETE requests.
void handlePutRequest(RecordManager& manager, int key, long offset, CustomDataType* data) {
    if (manager.addOrUpdateRecord(key, offset, data)) {
        std::cout << "PUT request successful: Key=" << key << "\n";
    } else {
        std::cerr << "PUT request failed.\n";
    }
}

void handleDeleteRequest(RecordManager& manager, int key) {
    if (manager.deleteRecord(key)) {
        std::cout << "DELETE request successful: Key=" << key << "\n";
    } else {
        std::cerr << "DELETE request failed.\n";
    }
}

int main() {
    RecordManager manager(1000);

    // Start background service
    manager.startBackgroundService();

    // Simulated API requests
    CustomDataType data1 = {42, 12345, 1};
    handlePutRequest(manager, 1, 12345, new CustomDataType(data1));

    CustomDataType* defaultData = new CustomDataType{0, 0, -1};
    handleDeleteRequest(manager, 1);

    // Stop background service
    manager.stopBackgroundService();

    return 0;
}
```

