- **Concurrency:** Uses `std::mutex` for thread-safe operations on the records. The `std::atomic<bool>` variable manages the running state of background services safely across threads.

- **Dynamic Resizing:** Efficiently handles resizing by avoiding reallocation when possible, and managing indices with an unordered map to allow direct access.

- **Error Handling:** Includes basic error handling for memory allocation failures, duplicate keys during addition, and invalid requests.

- **Background Service:** Starts a detached thread that periodically sleeps before stopping the service, simulating a random delay between starts and stops. 

This code is structured to be easily extendable and maintainable while ensuring performance through cache-friendly data structures and careful synchronization for concurrent access.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
    double *weight;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t mutex;
} RecordArray;

void init_random() {
    srand((unsigned int)time(NULL));
}

record* create_record(int min_value, int max_value, long key_range, double weight_range) {
    record *rec = (record *)malloc(sizeof(record));
    if (!rec) return NULL;

    rec->value = rand() % (max_value - min_value + 1) + min_value;

    rec->offset = (long *)malloc(sizeof(long));
    if (!rec->offset) {
        free(rec);
        return NULL;
    }
    *rec->offset = rand() % key_range;

    rec->key = (int *)malloc(sizeof(int));
    if (!rec->key) {
        free(rec->offset);
        free(rec);
        return NULL;
    }
    *rec->key = rand() % (2 * key_range); // Assume keys can be both positive and negative

    rec->weight = (double *)malloc(sizeof(double));
    if (!rec->weight) {
        free(rec->key);
        free(rec->offset);
        free(rec);
        return NULL;
    }
    *rec->weight = ((double)rand() / RAND_MAX) * weight_range;

    return rec;
}

int init_record_array(RecordArray *arr, size_t num_records, int value_min, int value_max, long key_range, double weight_range) {
    pthread_mutex_init(&arr->mutex, NULL);

    arr->records = (record *)malloc(num_records * sizeof(record));
    if (!arr->records) return -1;

    arr->count = num_records;
    for (size_t i = 0; i < num_records; ++i) {
        record *rec = create_record(value_min, value_max, key_range, weight_range);
        if (!rec) {
            while (i > 0) free(arr->records[--i]);
            free(arr->records);
            pthread_mutex_destroy(&arr->mutex);
            return -1;
        }
        arr->records[i] = *rec;
        free(rec);
    }

    return 0;
}

record* get_record(const RecordArray *arr, size_t index) {
    if (index >= arr->count) return NULL;

    pthread_mutex_lock(&arr->mutex);

    record *rec_copy = (record *)malloc(sizeof(record));
    if (!rec_copy) {
        pthread_mutex_unlock(&arr->mutex);
        return NULL;
    }

    *rec_copy = arr->records[index];
    rec_copy->offset = (long *)malloc(sizeof(long));
    rec_copy->key = (int *)malloc(sizeof(int));
    rec_copy->weight = (double *)malloc(sizeof(double));

    if (!rec_copy->offset || !rec_copy->key || !rec_copy->weight) {
        free(rec_copy->offset);
        free(rec_copy->key);
        free(rec_copy->weight);
        free(rec_copy);
        pthread_mutex_unlock(&arr->mutex);
        return NULL;
    }

    *rec_copy->offset = *(arr->records[index].offset);
    *rec_copy->key = *(arr->records[index].key);
    *rec_copy->weight = *(arr->records[index].weight);

    pthread_mutex_unlock(&arr->mutex);

    return rec_copy;
}

int update_record(RecordArray *arr, size_t index, int new_value, long new_offset, int new_key, double new_weight) {
    if (index >= arr->count) return -1;

    pthread_mutex_lock(&arr->mutex);

    if (!arr->records[index].offset || !arr->records[index].key || !arr->records[index].weight) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    arr->records[index].value = new_value;
    *(arr->records[index].offset) = new_offset;
    *(arr->records[index].key) = new_key;
    *(arr->records[index].weight) = new_weight;

    pthread_mutex_unlock(&arr->mutex);

    return 0;
}

double calculate_average(const RecordArray *arr) {
    if (arr->count == 0) return 0.0;

    double sum = 0.0;
    size_t valid_count = 0;

    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->records[i].value != 0) { // assuming 0 is an invalid value
            sum += arr->records[i].value;
            valid_count++;
        }
    }

    pthread_mutex_unlock(&arr->mutex);

    return valid_count > 0 ? sum / valid_count : 0.0;
}

void free_record_array(RecordArray *arr) {
    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->records[i].offset);
        free(arr->records[i].key);
        free(arr->records[i].weight);
    }

    free(arr->records);
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

int main() {
    init_random();

    RecordArray arr;
    int value_min = 1, value_max = 100;
    long key_range = 5000;
    double weight_range = 10.0;

