record* initialize_records(int num_records, int max_limit, int value_range_min, int value_range_max, float weight_range_min, float weight_range_max) {
    if (max_limit < 0 || num_records > max_limit) return NULL;

    record *records = malloc(max_limit * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records && i < max_limit; ++i) {
        records[i].value = value_range_min + rand() % (value_range_max - value_range_min + 1);
        records[i].offset = malloc(sizeof(long));
        if (!records[i].offset) {
            fprintf(stderr, "Memory allocation failed for offset\n");
            free(records[i].offset); // Clean-up partially allocated memory
        } else {
            *(records[i].offset) = i; // Example initialization of the pointer
        }

        records[i].key = i;
        records[i].weight = weight_range_min + ((float)rand() / RAND_MAX * (weight_range_max - weight_range_min));
    }

    log_memory_usage(num_records * sizeof(record));

    return records;
}

void update_record(record *records, int index, int new_value, float new_weight, int num_records) {
    if (!records || index < 0 || index >= num_records) return;

    records[index].value = new_value;
    records[index].weight = new_weight;

    // Log the update
    printf("Updated record at index %d: value=%d, weight=%.2f\n", index, new_value, new_weight);
}

void add_record(record **records, int *num_records, int max_limit, int new_value, float new_weight) {
    if (!records || !*records || *num_records >= max_limit) return;

    // Shift records to remove the oldest record
    for (int i = 1; i < max_limit; ++i) {
        (*records)[i - 1] = (*records)[i];
    }

    // Add new record at the end
    int last_index = max_limit - 1;
    (*records)[last_index].value = new_value;
    (*records)[last_index].weight = new_weight;
    (*records)[last_index].key = last_index;

    log_memory_usage(max_limit * sizeof(record));

    // Increment number of records, but ensure it doesn't exceed max limit
    if (*num_records < max_limit) {
        ++(*num_records);
    }
}

float average_weights(const record *records, int num_records) {
    float total_weight = 0.0;
    for (int i = 0; i < num_records; ++i) {
        total_weight += records[i].weight;
    }
    return num_records > 0 ? total_weight / num_records : 0.0f;
}

void free_records(record *records, int max_limit) {
    if (!records) return;

    for (int i = 0; i < max_limit; ++i) {
        free(records[i].offset);
    }
    free(records);

    printf("All records and associated memory have been freed.\n");
}

