#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define CACHE_SIZE 10

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
    double *weight_ptr;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    // Cache management
    Record **cache;
    size_t cache_count;
    size_t cache_capacity;
} RecordManager;

// Function prototypes
RecordManager* create_record_manager(size_t num_records);
void free_record_manager(RecordManager *manager);
int initialize_external_data(long **offsets, int **keys, double **weights, size_t count);
void log_discrepancy(const char *message);
Record** allocate_and_initialize_records(size_t num_records);
double random_double(double min, double max);
int within_range(int value, int min, int max);
void cache_record(RecordManager *manager, Record *record);
Record* get_from_cache(RecordManager *manager, int index);

// Function to create and initialize a record manager
RecordManager* create_record_manager(size_t num_records) {
    RecordManager *manager = (RecordManager*) malloc(sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for RecordManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    // Initialize records and cache
    manager->records = allocate_and_initialize_records(num_records);
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->count = num_records;
    manager->capacity = num_records;

    manager->cache = (Record**) malloc(CACHE_SIZE * sizeof(Record*));
    if (!manager->cache) {
        perror("Failed to allocate memory for cache");
        free_record_manager(manager);
        return NULL;
    }
    manager->cache_count = 0;
    manager->cache_capacity = CACHE_SIZE;

    return manager;
}

// Function to deallocate a record manager
void free_record_manager(RecordManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);

    free(manager->cache);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Function to initialize external data
int initialize_external_data(long **offsets, int **keys, double **weights, size_t count) {
    // Simulating external data initialization
    *offsets = (long*) malloc(count * sizeof(long));
    *keys = (int*) malloc(count * sizeof(int));
    *weights = (double*) malloc(count * sizeof(double));

    if (!*offsets || !*keys || !*weights) return 0;

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand() % 10000;
        (*keys)[i] = rand() % 100;
        (*weights)[i] = random_double(0.1, 10.0);
    }
    return 1;
}

// Function to log discrepancies
void log_discrepancy(const char *message) {
    fprintf(stderr, "Discrepancy: %s\n", message);
}

// Function to allocate and initialize records
Record** allocate_and_initialize_records(size_t num_records) {
    Record **records = (Record**) malloc(num_records * sizeof(Record*));
    if (!records) return NULL;

    long *offsets;
    int *keys;
    double *weights;
    if (!initialize_external_data(&offsets, &keys, &weights, num_records)) {
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i] = (Record*) malloc(sizeof(Record));
        if (!records[i]) {
            while (i--) free(records[i]);
            free(records);
            free(offsets); free(keys); free(weights);
            return NULL;
        }

        records[i]->value = rand() % 1000; // Random int within range
        records[i]->offset_ptr = &offsets[i];
        records[i]->key_ptr = &keys[i];
        records[i]->weight_ptr = &weights[i];

        cache_record(NULL, records[i]);
    }
    free(offsets); free(keys); free(weights);
    return records;
}

// Function to generate a random double within a range
double random_double(double min, double max) {
    return ((double) rand() / RAND_MAX) * (max - min) + min;
}

// Function to check if an int is within a specific range
int within_range(int value, int min, int max) {
    return value >= min && value <= max;
}

// Function to cache records
void cache_record(RecordManager *manager, Record *record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->cache_count < manager->cache_capacity) {
        manager->cache[manager->cache_count++] = record;
    } else {
        // Implement cache replacement strategy if needed
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a record from the cache
Record* get_from_cache(RecordManager *manager, int index) {
    if (index < 0 || index >= manager->cache_count) return NULL;

    return manager->cache[index];
}

int main() {
    srand(time(NULL));
    size_t num_records = 100;
    RecordManager *manager = create_record_manager(num_records);

    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return EXIT_FAILURE;
    }

    // Example usage of retrieving a record from cache
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < num_records && i < CACHE_SIZE; ++i) {
        Record *record = get_from_cache(manager, i);
        if (record)
            printf("Record %zu: Value=%d, Offset=%ld, Key=%d, Weight=%.2f\n",
                   i, record->value, *(record->offset_ptr), *(record->key_ptr), *(record->weight_ptr));
    }
    pthread_mutex_unlock(&manager->lock);

    free_record_manager(manager);
    return EXIT_SUCCESS;
}
