#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
    double *weight;
    time_t timestamp;
} record;

typedef struct {
    record *records;
    size_t size;
    pthread_rwlock_t lock;
} RecordArray;

// Function prototypes
RecordArray* create_record_array(size_t num_records);
void free_record_array(RecordArray *arr);
record* get_record(const RecordArray *arr, size_t index);
int update_record(RecordArray *arr, size_t index, int value, int key, double weight, time_t timestamp);
double calculate_average_value(const RecordArray *arr);
void find_min_max_values(const RecordArray *arr, int *min_value, int *max_value);
void sort_records_by_key(RecordArray *arr, int ascending);
void sort_records_by_timestamp(RecordArray *arr, int ascending);
void initialize_random_generator();

// Function implementations
RecordArray* create_record_array(size_t num_records) {
    RecordArray *arr = (RecordArray *)malloc(sizeof(RecordArray));
    if (!arr) return NULL;

    arr->records = (record *)calloc(num_records, sizeof(record));
    if (!arr->records) {
        free(arr);
        return NULL;
    }

    arr->size = num_records;
    pthread_rwlock_init(&arr->lock, NULL);

    initialize_random_generator();

    for (size_t i = 0; i < num_records; ++i) {
        arr->records[i].value = rand() % 100; // Example range [0, 99]
        arr->records[i].offset = malloc(sizeof(long));
        if (!arr->records[i].offset) goto cleanup;
        *arr->records[i].offset = rand() % 100000;

        arr->records[i].key = malloc(sizeof(int));
        if (!arr->records[i].key) goto cleanup;
        *arr->records[i].key = rand() % 1000; // Example range [0, 999]

        arr->records[i].weight = malloc(sizeof(double));
        if (!arr->records[i].weight) goto cleanup;
        *arr->records[i].weight = (double)(rand() % 100) / 10.0; // Example range [0.0, 9.9]

        time(&arr->records[i].timestamp);
    }

    return arr;

cleanup:
    for (size_t i = 0; i <= index; ++i) {
        free(arr->records[i].offset);
        free(arr->records[i].key);
        free(arr->records[i].weight);
    }
    free(arr->records);
    pthread_rwlock_destroy(&arr->lock);
    free(arr);
    return NULL;
}

void free_record_array(RecordArray *arr) {
    if (!arr) return;

    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->records[i].offset);
        free(arr->records[i].key);
        free(arr->records[i].weight);
    }
    free(arr->records);
    pthread_rwlock_destroy(&arr->lock);
    free(arr);
}

record* get_record(const RecordArray *arr, size_t index) {
    if (!arr || index >= arr->size) return NULL;

    pthread_rwlock_rdlock(&arr->lock);
    record *rec = &arr->records[index];
    pthread_rwlock_unlock(&arr->lock);

    return rec;
}

int update_record(RecordArray *arr, size_t index, int value, int key, double weight, time_t timestamp) {
    if (!arr || index >= arr->size) return -1;

    pthread_rwlock_wrlock(&arr->lock);
    record *rec = &arr->records[index];

    rec->value = value;
    *rec->key = key;
    *rec->weight = weight;
    rec->timestamp = timestamp;

    pthread_rwlock_unlock(&arr->lock);

    return 0;
}

double calculate_average_value(const RecordArray *arr) {
    if (!arr || arr->size == 0) return 0.0;

    double sum = 0.0;
    pthread_rwlock_rdlock(&arr->lock);
    for (size_t i = 0; i < arr->size; ++i) {
        sum += arr->records[i].value;
    }
    pthread_rwlock_unlock(&arr->lock);

    return sum / arr->size;
}

void find_min_max_values(const RecordArray *arr, int *min_value, int *max_value) {
    if (!arr || !min_value || !max_value || arr->size == 0) return;

    pthread_rwlock_rdlock(&arr->lock);
    *min_value = arr->records[0].value;
    *max_value = arr->records[0].value;

    for (size_t i = 1; i < arr->size; ++i) {
        if (arr->records[i].value < *min_value) *min_value = arr->records[i].value;
        if (arr->records[i].value > *max_value) *max_value = arr->records[i].value;
    }
    pthread_rwlock_unlock(&arr->lock);
}

void sort_records_by_key(RecordArray *arr, int ascending) {
    if (!arr || arr->size == 0) return;

    pthread_rwlock_wrlock(&arr->lock);

    qsort(arr->records, arr->size, sizeof(record), [](const void *a, const void *b) -> int {
        const record *rec_a = (const record *)a;
        const record *rec_b = (const record *)b;
        if (ascending)
            return (*rec_a->key > *rec_b->key) - (*rec_a->key < *rec_b->key);
        else
            return (*rec_b->key > *rec_a->key) - (*rec_b->key < *rec_a->key);
    });

    pthread_rwlock_unlock(&arr->lock);
}

void sort_records_by_timestamp(RecordArray *arr, int ascending) {
    if (!arr || arr->size == 0) return;

    pthread_rwlock_wrlock(&arr->lock);

    qsort(arr->records, arr->size, sizeof(record), [](const void *a, const void *b) -> int {
        const record *rec_a = (const record *)a;
        const record *rec_b = (const record *)b;
        if (ascending)
            return rec_a->timestamp > rec_b->timestamp ? 1 : rec_a->timestamp < rec_b->timestamp ? -1 : 0;
        else
            return rec_b->timestamp > rec_a->timestamp ? 1 : rec_b->timestamp < rec_a->timestamp ? -1 : 0;
    });

    pthread_rwlock_unlock(&arr->lock);
}

void initialize_random_generator() {
    srand(time(NULL));
}
