typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t count;
    pthread_rwlock_t lock;
} DynamicRecordCollection;

void init_aes(AES_KEY *aesKey, const unsigned char *key) {
    if (AES_set_encrypt_key(key, 128, aesKey) < 0) {
        perror("Failed to set AES key");
        exit(EXIT_FAILURE);
    }
}

void encrypt_data(unsigned char *plaintext, size_t length, AES_KEY *aesKey, unsigned char *ciphertext) {
    AES_cbc_encrypt(plaintext, ciphertext, length, aesKey, NULL, AES_ENCRYPT);
}

unsigned char compute_md5(const void *data, size_t len, unsigned char output[MD5_DIGEST_LENGTH]) {
    MD5((unsigned char *)data, len, output);
}

unsigned char compute_sha256(const void *data, size_t len, unsigned char output[SHA256_DIGEST_LENGTH]) {
    SHA256((unsigned char *)data, len, output);
}

DynamicRecordCollection* create_record_collection(size_t initial_count) {
    DynamicRecordCollection *collection = (DynamicRecordCollection*)malloc(sizeof(DynamicRecordCollection));
    if (!collection) {
        perror("Memory allocation failed for collection");
        exit(EXIT_FAILURE);
    }

    collection->records = (Record**)calloc(initial_count, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        perror("Memory allocation failed for records array");
        exit(EXIT_FAILURE);
    }

    collection->count = initial_count;
    pthread_rwlock_init(&collection->lock, NULL);

    unsigned char aes_key[] = "0123456789abcdef"; // Example key
    AES_KEY aes_encrypt_key;

    init_aes(&aes_encrypt_key, aes_key);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            free(collection->records[i]);
            perror("Memory allocation failed for record");
            exit(EXIT_FAILURE);
        }

        int value = rand() % 100; // Example range [0, 99]
        unsigned char plaintext[sizeof(int)];
        memcpy(plaintext, &value, sizeof(int));

        unsigned char encrypted_value[sizeof(int)];
        encrypt_data(plaintext, sizeof(int), &aes_encrypt_key, encrypted_value);

        record->value = value;
        record->offset = (long*)malloc(sizeof(long));
        if (!record->offset) {
            free(record);
            perror("Memory allocation failed for offset");
            exit(EXIT_FAILURE);
        }
        *record->offset = rand(); // Example offset

        record->key = (int*)malloc(sizeof(int));
        if (!record->key) {
            free(record->offset);
            free(record);
            perror("Memory allocation failed for key");
            exit(EXIT_FAILURE);
        }
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        compute_md5(encrypted_value, sizeof(int), md5_hash);

        memcpy(record->key, md5_hash, sizeof(int));

        collection->records[i] = record;
    }

    return collection;
}

Record* get_record(DynamicRecordCollection *collection, size_t index) {
    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    pthread_rwlock_rdlock(&collection->lock);
    Record *record = collection->records[index];
    pthread_rwlock_unlock(&collection->lock);

    return record;
}

void destroy_record_collection(DynamicRecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
    }

    free(collection->records);
    pthread_rwlock_destroy(&collection->lock);
    free(collection);
}

int main() {
    size_t initial_count = 10;
    DynamicRecordCollection *collection = create_record_collection(initial_count);

    Record *record = get_record(collection, 5);
    if (record) {
        printf("Value: %d\n", record->value);
    }

    destroy_record_collection(collection);

    return 0;
}
