#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define structures
typedef struct {
    int value;
    long *offsetPtr;
    int *keyPtr;
} RecordData;

typedef struct {
    long offset;
    int key;
    RecordData *data;
} Record;

typedef struct {
    uint64_t documentID;
    char *content;
    time_t lastAccessTime;
} DocumentEntry;

// Custom allocator function and cache
#define CACHE_SIZE 10

DocumentEntry *docCache[CACHE_SIZE];
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

void* customAllocator(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

DocumentEntry* getCachedDocument(uint64_t docID) {
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (docCache[i] && docCache[i]->documentID == docID) {
            pthread_mutex_unlock(&cacheMutex);
            return docCache[i];
        }
    }
    pthread_mutex_unlock(&cacheMutex);
    return NULL;
}

void cacheDocument(DocumentEntry *entry) {
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (!docCache[i] || strcmp(docCache[i]->content, entry->content) != 0) {
            docCache[i] = entry;
            break;
        }
    }
    pthread_mutex_unlock(&cacheMutex);
}

// Function to manage records and documents
void manageRecordsAndDocuments(size_t recordCount, size_t documentCount, int minValue, int maxValue) {
    Record *records = (Record*)customAllocator(recordCount * sizeof(Record));
    DocumentEntry *documents = (DocumentEntry*)customAllocator(documentCount * sizeof(DocumentEntry));

    // Initialize records with random values
    srand(time(NULL));
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].offset = rand() % 10000;
        records[i].key = rand() % 100;
        RecordData *data = (RecordData*)customAllocator(sizeof(RecordData));
        data->value = minValue + rand() % (maxValue - minValue + 1);
        data->offsetPtr = &records[i].offset;
        data->keyPtr = &records[i].key;
        records[i].data = data;
    }

    // Initialize documents with sequential IDs
    for (size_t i = 0; i < documentCount; ++i) {
        uint64_t docID = i + 1;
        char *content = (char*)customAllocator(256);
        snprintf(content, 256, "Document content %lu", docID);

        DocumentEntry entry = {docID, content, time(NULL)};
        documents[i] = entry;
        cacheDocument(&documents[i]);
    }

    // Operations processing
    char operation[10];
    int index;
    while (scanf("%s %d", operation, &index) == 2) {
        if (strcmp(operation, "read") == 0 && index >= 0 && index < documentCount) {
            DocumentEntry *doc = getCachedDocument(documents[index].documentID);
            if (!doc) doc = &documents[index];
            printf("Read Document %lu: %s\n", doc->documentID, doc->content);
        } else if (strcmp(operation, "update") == 0 && index >= 0 && index < documentCount) {
            char newContent[256];
            scanf("%s", newContent);
            free(documents[index].content);
            documents[index].content = strdup(newContent);
            printf("Updated Document %lu\n", documents[index].documentID);
        } else if (strcmp(operation, "delete") == 0 && index >= 0 && index < documentCount) {
            free(documents[index].content);
            for (size_t i = index; i < documentCount - 1; ++i) {
                documents[i] = documents[i + 1];
            }
            --documentCount;
            printf("Deleted Document %lu\n", documents[index].documentID);
        } else {
            fprintf(stderr, "Invalid operation or index\n");
        }
    }

    // Clean up
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i].data);
    }
