Record* allocate_records(size_t count) {
    records = calloc(count, sizeof(Record));
    if (!records) {
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }

    record_count = count;
    return records;
}

void resize_records(size_t new_count) {
    pthread_mutex_lock(&lock);
    Record* temp = realloc(records, new_count * sizeof(Record));
    if (!temp) {
        perror("Failed to resize records");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }
    records = temp;
    record_count = new_count;
    memset(records + record_count - new_count, 0, (new_count - count) * sizeof(Record));
    pthread_mutex_unlock(&lock);
}

void initialize_records(size_t count, int min_val, int max_val) {
    allocate_records(count);

    long* offsets = malloc(count * sizeof(long));
    int* keys = malloc(count * sizeof(int));

