['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    long offset;
    int key;
    record r;
} record_entry;

typedef struct Node {
    int key;
    record_entry entry;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} hash_table;

typedef struct {
    record_entry *entries;
    size_t size;
    size_t capacity;
    hash_table ht;
    pthread_rwlock_t rwlock;  // read-write lock for concurrency
} dynamic_array;

// Function declarations
dynamic_array* init_dynamic_array(size_t initial_capacity, int value_range);
record_entry get_record(dynamic_array* da, size_t index);
void update_record_value(dynamic_array* da, size_t index, int new_value);
void iterate_records(const dynamic_array* da, void (*callback)(const record_entry*, void*), void *arg);
void free_dynamic_array(dynamic_array* da);

// Utility functions for hash table
unsigned int hash(int key, size_t capacity) {
    return (unsigned int)key % capacity;
}

Node* create_node(int key, const record_entry& entry) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->key = key;
    new_node->entry = entry;
    new_node->next = NULL;

    return new_node;
}

// Initialize dynamic array and hash table
dynamic_array* init_dynamic_array(size_t initial_capacity, int value_range) {
    dynamic_array* da = malloc(sizeof(dynamic_array));
    if (!da) return NULL;

    pthread_rwlock_init(&da->rwlock, NULL);
    pthread_mutex_init(&da->ht.lock, NULL);

    da->entries = calloc(initial_capacity, sizeof(record_entry));
    if (!da->entries) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = initial_capacity;

    size_t hash_table_capacity = next_prime(initial_capacity * 2); // Choose a good capacity
    da->ht.buckets = calloc(hash_table_capacity, sizeof(Node*));
    if (!da->ht.buckets) {
        free(da->entries);
        free(da);
        return NULL;
    }
    da->ht.size = 0;
    da->ht.capacity = hash_table_capacity;

    srand(time(NULL)); // Initialize random seed

    for (size_t i = 0; i < initial_capacity; ++i) {
        record_entry entry;
        entry.offset = rand(); // Example offset, replace with real data if needed
        entry.key = rand() % value_range; // Random key in given range
        entry.r.value = rand() % value_range;

        entry.r.offset_ptr = &entry.offset;
        entry.r.key_ptr = &entry.key;

        pthread_rwlock_wrlock(&da->rwlock);
        da->entries[da->size++] = entry;
        unsigned int index = hash(entry.key, da->ht.capacity);

        Node* new_node = create_node(entry.key, entry);
        if (!new_node) {
            pthread_rwlock_unlock(&da->rwlock);
            continue; // Handle memory allocation failure
        }

        pthread_mutex_lock(&da->ht.lock);
        new_node->next = da->ht.buckets[index];
        da->ht.buckets[index] = new_node;
        ++da->ht.size;
        pthread_mutex_unlock(&da->ht.lock);

        pthread_rwlock_unlock(&da->rwlock);
    }

    return da;
}

// Retrieve a specific record by its index
record_entry get_record(dynamic_array* da, size_t index) {
    if (index >= da->size) return (record_entry){0};

    pthread_rwlock_rdlock(&da->rwlock);
    record_entry entry = da->entries[index];
    pthread_rwlock_unlock(&da->rwlock);

    return entry;
}

// Update the value of a record at a given index
void update_record_value(dynamic_array* da, size_t index, int new_value) {
    if (index >= da->size) return;

    pthread_rwlock_wrlock(&da->rwlock);
    da->entries[index].r.value = new_value;
    pthread_rwlock_unlock(&da->rwlock);
}

// Iterate over all records
void iterate_records(const dynamic_array* da, void (*callback)(const record_entry*, void*), void *arg) {
    pthread_rwlock_rdlock(&da->rwlock);

    for (size_t i = 0; i < da->size; ++i) {
        callback(&da->entries[i], arg);
    }

    pthread_rwlock_unlock(&da->rwlock);
}

// Free dynamic array and hash table
void free_dynamic_array(dynamic_array* da) {
    if (!da) return;

    for (size_t i = 0; i < da->ht.capacity; ++i) {
        Node* current = da->ht.buckets[i];
        while (current) {
            Node* to_free = current;
            current = current->next;
            free(to_free);
        }
    }

    free(da->ht.buckets);
    free(da->entries);

    pthread_rwlock_destroy(&da->rwlock);
    pthread_mutex_destroy(&da->ht.lock);

    free(da);
}

// Example callback function
void print_record(const record_entry* entry, void* arg) {
    (void)arg; // Unused parameter
    printf("Key: %d, Value: %d\n", *entry->r.key_ptr, entry->r.value);
}

int main() {
    dynamic_array* da = init_dynamic_array(10, 100);

    if (!da) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return EXIT_FAILURE;
    }

    iterate_records(da, print_record, NULL);

    record_entry rec = get_record(da, 5);
    printf("Retrieved Record - Key: %d, Value: %d\n", *rec.r.key_ptr, rec.r.value);

    update_record_value(da, 5, 999);
    rec = get_record(da, 5);
    printf("Updated Record - Key: %d, Value: %d\n", *rec.r.key_ptr, rec.r.value);

    free_dynamic_array(da);

    return EXIT_SUCCESS;
}

// Utility to find the next prime number for hash table capacity
size_t next_prime(size_t n) {
    // Implementation of a simple algorithm to find the next prime
    if (n % 2 == 0) ++n;
    while (!is_prime(n)) ++n;
    return n;
}

int is_prime(size_t n) {
    if (n <= 1) return 0;
    for (size_t i = 2; i * i <= n; ++i) {
        if (n % i == 0) return 0;
    }
    return 1;
}
