#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>

#define ERROR_FILE_NOT_FOUND -1
#define ERROR_READ_FAIL -2
#define ERROR_INVALID_FORMAT -3
#define ERROR_OUT_OF_MEMORY -4
#define RETRY_LIMIT 5

typedef struct {
    int value;
} record;

int validate_and_read_data(const char *filename, long **offsets, int **keys, size_t *size) {
    FILE *file = fopen(filename, "r");
    if (!file) return ERROR_FILE_NOT_FOUND;

    long retry_count = 0;
    while (retry_count < RETRY_LIMIT && !file) {
        sleep((1 << retry_count));
        file = fopen(filename, "r");
        ++retry_count;
    }

    if (!file) return errno == ENOENT ? ERROR_FILE_NOT_FOUND : ERROR_READ_FAIL;

    // Count lines for size determination
    *size = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        (*size)++;
    }
    rewind(file);

    *offsets = malloc(*size * sizeof(long));
    *keys = malloc(*size * sizeof(int));

    if (!*offsets || !*keys) {
        free(*offsets);
        free(*keys);
        fclose(file);
        return ERROR_OUT_OF_MEMORY;
    }

    for (size_t i = 0; i < *size; ++i) {
        if (fscanf(file, "%ld %d", &((*offsets)[i]), &((*keys)[i])) != 2) {
            free(*offsets);
            free(*keys);
            fclose(file);
            return ERROR_INVALID_FORMAT;
        }
        if ((*offsets)[i] <= 0 || (*keys)[i] < 0) {
            free(*offsets);
            free(*keys);
            fclose(file);
            return ERROR_INVALID_FORMAT;
        }
    }

    fclose(file);
    return 0; // success
}

int validate_unique_keys(int *keys, size_t size) {
    if (size == 0) return 1;

    int seen[size];
    memset(seen, 0, sizeof(seen));
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] >= size || seen[keys[i]]) return 0;
        seen[keys[i]] = 1;
    }
    return 1;
}

int initialize_records(record **records, int minValue, int maxValue, size_t size) {
    *records = malloc(size * sizeof(record));
    if (!*records) return ERROR_OUT_OF_MEMORY;

    srand(time(NULL)); // Seed for randomness

    for (size_t i = 0; i < size; ++i) {
        if (minValue > maxValue) { 
            (*records)[i].value = 0;
        } else {
            int value = minValue + rand() % ((maxValue - minValue) + 1);
            (*records)[i].value = value;
        }
    }

    return 0; // success
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const char *filename = "data.txt";
    long *offsets = NULL;
    int *keys = NULL;
    size_t data_size;

    int result = validate_and_read_data(filename, &offsets, &keys, &data_size);
    if (result != 0) {
        fprintf(stderr, "Error reading file: %d\n", result);
        return result;
    }

    if (!validate_unique_keys(keys, data_size)) {
        fprintf(stderr, "Keys are not unique.\n");
        cleanup(offsets, keys, NULL);
        return ERROR_INVALID_FORMAT;
    }

    record *records = NULL;
    int minValue = 1, maxValue = 100; // Example range
    result = initialize_records(&records, minValue, maxValue, data_size);

    if (result != 0) {
        fprintf(stderr, "Error initializing records: %d\n", result);
        cleanup(offsets, keys, NULL);
        return result;
    }

    // Utilize the initialized structures

    // Cleanup resources
    cleanup(offsets, keys, records);

    return 0;
}
