#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <fcntl.h>
#include <json-c/json.h>
#include <time.h>

#define DEFAULT_BUFFER_SIZE 1024
#define DEFAULT_TIMEOUT 30
#define MAX_THREADS 10

typedef struct {
    int buffer_size;
    int timeout;
    char server_address[256];
    int port;
} Config;

typedef struct {
    FILE *log_file;
    int log_level;
} Logger;

Logger logger = {NULL, 1}; // Default to info level logging

void initialize_logger() {
    logger.log_file = fopen("server.log", "a");
    if (!logger.log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

void log_message(const char *level, const char *message) {
    time_t now;
    struct tm *t;
    time(&now);
    t = localtime(&now);

    if (strcmp(level, "DEBUG") >= 0 && logger.log_level <= 1 ||
        strcmp(level, "INFO") >= 0 && logger.log_level <= 2 ||
        strcmp(level, "WARNING") >= 0 && logger.log_level <= 3 ||
        strcmp(level, "ERROR") >= 0) {

        fprintf(logger.log_file, "[%02d:%02d:%02d] %s: %s\n", t->tm_hour, t->tm_min, t->tm_sec, level, message);
    }
}

Config load_config() {
    Config config = {DEFAULT_BUFFER_SIZE, DEFAULT_TIMEOUT, "127.0.0.1", 8080};
    char *config_file_path = getenv("CONFIG_FILE");

    if (!config_file_path) return config;

    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        log_message("ERROR", "Config file not found, using defaults.");
        return config;
    }

    struct json_object *parsed_json;
    struct json_object *buffer_size, *timeout, *server_address, *port;

    char buffer[1024];
    fread(buffer, 1, sizeof(buffer), file);
    fclose(file);

    parsed_json = json_tokener_parse(buffer);

    if (json_object_object_get_ex(parsed_json, "buffer_size", &buffer_size) &&
        json_object_object_get_ex(parsed_json, "timeout", &timeout) &&
        json_object_object_get_ex(parsed_json, "server_address", &server_address) &&
        json_object_object_get_ex(parsed_json, "port", &port)) {

        config.buffer_size = json_object_get_int(buffer_size);
        config.timeout = json_object_get_int(timeout);
        strncpy(config.server_address, json_object_get_string(server_address), sizeof(config.server_address));
        config.port = json_object_get_int(port);

    } else {
        log_message("WARNING", "Missing required configuration fields, using defaults.");
    }

    json_object_put(parsed_json);
    return config;
}

void* handle_client(void *arg) {
    int client_socket = *(int*)arg;
    free(arg);

    char buffer[DEFAULT_BUFFER_SIZE];
    while (1) {
        memset(buffer, 0, DEFAULT_BUFFER_SIZE);
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer), 0);
        if (bytes_received <= 0) break;

        // Process the message (placeholder)
        printf("Received: %s\n", buffer);

        // Echo back to client
        send(client_socket, buffer, strlen(buffer), 0);
    }

    close(client_socket);
    return NULL;
}

void start_tcp_server(Config config) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message("ERROR", "Socket creation failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message("ERROR", "Set socket options failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(config.server_address);
    address.sin_port = htons(config.port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("ERROR", "Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        log_message("ERROR", "Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while (1) {
        new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            log_message("WARNING", "Accept failed");
            continue;
        }

        int *client_sock = malloc(sizeof(int));
        *client_sock = new_socket;

        if (pthread_create(&threads[thread_count++], NULL, handle_client, client_sock) != 0) {
            log_message("ERROR", "Failed to create thread for new connection");
            close(new_socket);
            free(client_sock);
        }

        if (thread_count >= MAX_THREADS) {
            for (int i = 0; i < MAX_THREADS; ++i) {
                pthread_join(threads[i], NULL);
            }
            thread_count = 0;
        }
    }

    close(server_fd);
}

void* health_check_handler(void *arg) {
    // Placeholder: Implement real-time metrics
    printf("Health check endpoint accessed.\n");
    return NULL;
}

int main() {
    initialize_logger();

    Config config = load_config();
    log_message("INFO", "Server starting with configuration:");
    char info[512];
    snprintf(info, sizeof(info), "Buffer Size: %d, Timeout: %d, Server Address: %s, Port: %d",
             config.buffer_size, config.timeout, config.server_address, config.port);
    log_message("DEBUG", info);

    // Start TCP server in a separate thread
    pthread_t server_thread;
    if (pthread_create(&server_thread, NULL, (void*)start_tcp_server, &config) != 0) {
        log_message("ERROR", "Failed to start TCP server");
        exit(EXIT_FAILURE);
    }

    pthread_join(server_thread, NULL);

    fclose(logger.log_file);
    return 0;
}
