#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <pthread.h>

typedef struct {
    char *description;
    int priority;
    struct timeval timestamp;
} Task;

typedef struct {
    Task **tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskList;

// Utility function to generate a random string
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *str = malloc(length + 1);
    if (str) {
        for (size_t i = 0; i < length; ++i) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[i] = charset[key];
        }
        str[length] = '\0';
    }
    return str;
}

// Initialize task list with a specified number of tasks
TaskList* initialize_task_list(size_t initial_capacity, size_t desc_length_min, size_t desc_length_max, int priority_min, int priority_max) {
    TaskList *list = malloc(sizeof(TaskList));
    if (!list) {
        perror("Failed to allocate memory for task list");
        return NULL;
    }

    list->tasks = calloc(initial_capacity, sizeof(Task*));
    if (!list->tasks) {
        perror("Failed to allocate memory for tasks");
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < initial_capacity; ++i) {
        Task *task = malloc(sizeof(Task));
        if (!task) {
            perror("Failed to allocate memory for a task");
            continue;
        }

        size_t length = rand() % (desc_length_max - desc_length_min + 1) + desc_length_min;
        task->description = generate_random_string(length);
        task->priority = rand() % (priority_max - priority_min + 1) + priority_min;
        gettimeofday(&task->timestamp, NULL);

        list->tasks[list->count++] = task;
    }

    return list;
}

// Add a new task to the list
int add_task(TaskList *list, const char *description, int priority) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        Task **new_tasks = realloc(list->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            perror("Failed to reallocate memory for tasks");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }

    Task *task = malloc(sizeof(Task));
    if (!task) {
        perror("Failed to allocate memory for a task");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    size_t length = strlen(description);
    task->description = strdup(description);
    task->priority = priority;
    gettimeofday(&task->timestamp, NULL);

    list->tasks[list->count++] = task;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Update a specific task by its index
int update_task(TaskList *list, size_t index, const char *description, int priority) {
    if (index >= list->count) {
        fprintf(stderr, "Invalid index\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Task *task = list->tasks[index];
    free(task->description);
    size_t length = strlen(description);
    task->description = strdup(description);
    task->priority = priority;
    gettimeofday(&task->timestamp, NULL);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Retrieve a specific task by its index
Task* get_task(TaskList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Invalid index\n");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    Task *task = list->tasks[index];

    pthread_mutex_unlock(&list->lock);
    return task;
}

// Sort tasks based on their priority levels
void sort_tasks(TaskList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count - 1; ++i) {
        for (size_t j = i + 1; j < list->count; ++j) {
            if (list->tasks[i]->priority > list->tasks[j]->priority) {
                Task *temp = list->tasks[i];
                list->tasks[i] = list->tasks[j];
                list->tasks[j] = temp;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the task list and its contents
void free_task_list(TaskList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->tasks[i]->description);
        free(list->tasks[i]);
    }

    free(list->tasks);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Placeholder for periodic synchronization with an external data source
void synchronize_with_external_source(TaskList *list) {
    // This function would include network operations and handle potential latency and data integrity issues.
}

// Example usage
int main() {
    TaskList *task_list = initialize_task_list(10, 5, 20, 1, 100);
    if (!task_list) return EXIT_FAILURE;

    add_task(task_list, "New task description", 50);
    update_task(task_list, 0, "Updated task description", 30);

    Task *retrieved_task = get_task(task_list, 0);
    if (retrieved_task) {
        printf("Task: %s, Priority: %d\n", retrieved_task->description, retrieved_task->priority);
    }

    sort_tasks(task_list);

    synchronize_with_external_source(task_list);

    free_task_list(task_list);
    return EXIT_SUCCESS;
}
