#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int status_code;
    char *message;
} Event;

typedef struct {
    Event **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventLog;

EventLog* create_event_log(size_t initial_capacity) {
    EventLog *log = (EventLog *)malloc(sizeof(EventLog));
    log->events = (Event **)calloc(initial_capacity, sizeof(Event *));
    log->capacity = initial_capacity;
    log->count = 0;
    pthread_mutex_init(&log->lock, NULL);
    return log;
}

void destroy_event_log(EventLog *log) {
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        free(log->events[i]->message);
        free(log->events[i]);
    }
    free(log->events);
    pthread_mutex_unlock(&log->lock);
    pthread_mutex_destroy(&log->lock);
    free(log);
}

int insert_event(EventLog *log, time_t timestamp, int status_code, const char *message) {
    pthread_mutex_lock(&log->lock);

    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        Event **new_events = (Event **)realloc(log->events, new_capacity * sizeof(Event *));
        if (!new_events) {
            pthread_mutex_unlock(&log->lock);
            return -1; // Out of memory
        }
        memset(new_events + log->count, 0, (new_capacity - log->capacity) * sizeof(Event *));
        log->events = new_events;
        log->capacity = new_capacity;
    }

    Event *event = (Event *)malloc(sizeof(Event));
    if (!event) {
        pthread_mutex_unlock(&log->lock);
        return -1; // Out of memory
    }

    event->timestamp = timestamp;
    event->status_code = status_code;
    event->message = strdup(message);
    if (!event->message) {
        free(event);
        pthread_mutex_unlock(&log->lock);
        return -1; // Out of memory
    }

    log->events[log->count++] = event;

    pthread_mutex_unlock(&log->lock);
    return 0;
}

Event* get_event_by_index(EventLog *log, size_t index) {
    if (index >= log->count) return NULL;

    pthread_mutex_lock(&log->lock);
    Event *event = log->events[index];
    pthread_mutex_unlock(&log->lock);

    return event;
}

int update_event_message(EventLog *log, size_t index, const char *new_message) {
    if (index >= log->count) return -1;

    pthread_mutex_lock(&log->lock);

    Event *event = log->events[index];
    free(event->message);
    event->message = strdup(new_message);
    if (!event->message) {
        pthread_mutex_unlock(&log->lock);
        return -1; // Out of memory
    }

    pthread_mutex_unlock(&log->lock);
    return 0;
}

void cleanup_event_log(EventLog *log, size_t max_age_seconds) {
    time_t now = time(NULL);

    pthread_mutex_lock(&log->lock);

    for (size_t i = 0; i < log->count;) {
        if ((now - log->events[i]->timestamp) > max_age_seconds) {
            free(log->events[i]->message);
            free(log->events[i]);
            memmove(&log->events[i], &log->events[i + 1], (log->count - i - 1) * sizeof(Event *));
            --log->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&log->lock);
}
