    size_t count;
    pthread_mutex_t array_lock;
} RecordCollection;

RecordCollection* initialize_collection(size_t num_records, int value_range_min, int value_range_max) {
    if (num_records == 0 || value_range_min > value_range_max)
        return NULL;

    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;

    pthread_mutex_init(&collection->array_lock, NULL);

    collection->offsets = malloc(collection->capacity * sizeof(long));
    collection->keys = malloc(collection->capacity * sizeof(int));
    collection->records = malloc(collection->capacity * sizeof(Record));

    if (!collection->offsets || !collection->keys || !collection->records) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        pthread_mutex_destroy(&collection->array_lock);
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < num_records && collection->count < collection->capacity; ++i) {
        long offset = rand() % 10000; // Example offset generation
        int key = rand() % 10000;     // Example key generation

        collection->offsets[collection->count] = offset;
        collection->keys[collection->count] = key;

        collection->records[collection->count].value = value_range_min + rand() % (value_range_max - value_range_min + 1);
        collection->records[collection->count].offset_ptr = &collection->offsets[collection->count];
        collection->records[collection->count].key_ptr = &collection->keys[collection->count];

        ++collection->count;
    }

    HashTable* hash_table = malloc(sizeof(HashTable));
    if (!hash_table) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        pthread_mutex_destroy(&collection->array_lock);
        free(collection);
        return NULL;
    }

    hash_table->capacity = INITIAL_CAPACITY;
    hash_table->size = 0;

    hash_table->table = malloc(hash_table->capacity * sizeof(Node*));
    if (!hash_table->table) {
        free(hash_table->table);
        free(hash_table);
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        pthread_mutex_destroy(&collection->array_lock);
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < hash_table->capacity; ++i) {
        hash_table->table[i] = NULL;
    }

    pthread_mutex_init(&hash_table->lock, NULL);

    collection->hash_table = hash_table;

    // Populate the hash table
    for (size_t i = 0; i < collection->count; ++i) {
        int key = collection->keys[i];
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) continue;

        new_node->key = key;
        new_node->record = collection->records[i];
        new_node->next = NULL;

        size_t index = key % hash_table->capacity;
        pthread_mutex_lock(&hash_table->lock);

        Node* head = hash_table->table[index];
        if (!head) {
            hash_table->table[index] = new_node;
        } else {
            while (head->next)
                head = head->next;
            head->next = new_node;
        }

        ++hash_table->size;

        pthread_mutex_unlock(&hash_table->lock);
    }

    return collection;
}

Record* get_record(RecordCollection* collection, size_t index) {
    if (!collection || index >= collection->count)
        return NULL;

    pthread_mutex_lock(&collection->array_lock);

    Record* record = &collection->records[index];

    pthread_mutex_unlock(&collection->array_lock);

    return record;
}

int update_record_value(RecordCollection* collection, size_t index, int new_value) {
    if (!collection || index >= collection->count)
        return -1;

    pthread_mutex_lock(&collection->array_lock);

    collection->records[index].value = new_value;

    pthread_mutex_unlock(&collection->array_lock);

    return 0;
}

void iterate_records(RecordCollection* collection, void (*func)(const Record*)) {
    if (!collection)
        return;

    pthread_mutex_lock(&collection->array_lock);

    for (size_t i = 0; i < collection->count; ++i) {
        func(&collection->records[i]);
    }

    pthread_mutex_unlock(&collection->array_lock);
}

void free_collection(RecordCollection* collection) {
    if (!collection)
        return;

    if (collection->offsets) free(collection->offsets);
    if (collection->keys) free(collection->keys);
    if (collection->records) free(collection->records);

    pthread_mutex_destroy(&collection->array_lock);

    HashTable* hash_table = collection->hash_table;

    for (size_t i = 0; i < hash_table->capacity; ++i) {
        Node* head = hash_table->table[i];
        while (head) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    }

    if (hash_table->table) free(hash_table->table);

    pthread_mutex_destroy(&hash_table->lock);
    free(hash_table);

    free(collection);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    RecordCollection* collection = initialize_collection(100, 1, 100);

    if (collection) {
        iterate_records(collection, [](const Record* record) {
            printf("Value: %d\n", record->value);
        });

        free_collection(collection);
    }

    return 0;
}
