        printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n",
               i,
               arr->records[i]->value,
               *(arr->records[i]->offsetPtr),
               *(arr->records[i]->keyPtr));
    }
    pthread_mutex_unlock((pthread_mutex_t*)&arr->lock);
