HashTable* init_hash_table(size_t initialCapacity) {
    HashTable *hashTable = malloc(sizeof(HashTable));
    if (!hashTable) return NULL;

    hashTable->buckets = calloc(initialCapacity, sizeof(HashTableEntry *));
    if (!hashTable->buckets) {
        free(hashTable);
        return NULL;
    }

    hashTable->size = 0;
    hashTable->capacity = initialCapacity;
    pthread_mutex_init(&hashTable->lock, NULL);

    return hashTable;
}

void resize_hash_table_if_necessary(HashTable *hashTable) {
    double loadFactor = (double)hashTable->size / hashTable->capacity;
    if (loadFactor > LOAD_FACTOR_THRESHOLD) {
        // Implement resizing logic here
    }
}

int hash(int key, size_t capacity) {
    return abs(key) % capacity;
}

Record* get_record_by_key(HashTable *hashTable, int key) {
    pthread_mutex_lock(&hashTable->lock);
    size_t index = hash(key, hashTable->capacity);
    HashTableEntry *entry = hashTable->buckets[index];

    while (entry) {
        if (entry->key == key) {
            Record *record = entry->record;
            pthread_mutex_unlock(&hashTable->lock);
            return record;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&hashTable->lock);
    return NULL;
}

void insert_or_update_record_in_hash_table(HashTable *hashTable, Record *record) {
    pthread_mutex_lock(&hashTable->lock);

    size_t index = hash(record->keyPtr ? *record->keyPtr : 0, hashTable->capacity);
    HashTableEntry *entry = hashTable->buckets[index];

    while (entry) {
        if (entry->key == record->keyPtr ? *record->keyPtr : 0) {
            entry->record = record;
            break;
        }
        entry = entry->next;
    }

    if (!entry) {
        HashTableEntry *newEntry = malloc(sizeof(HashTableEntry));
        if (!newEntry) {
            pthread_mutex_unlock(&hashTable->lock);
            return;
        }

        newEntry->key = record->keyPtr ? *record->keyPtr : 0;
        newEntry->record = record;
        newEntry->next = hashTable->buckets[index];
        hashTable->buckets[index] = newEntry;

        hashTable->size++;
    }

    resize_hash_table_if_necessary(hashTable);
    pthread_mutex_unlock(&hashTable->lock);
}

void free_hash_table(HashTable *hashTable) {
    pthread_mutex_lock(&hashTable->lock);

    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashTableEntry *entry = hashTable->buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    pthread_mutex_unlock(&hashTable->lock);

    pthread_mutex_destroy(&hashTable->lock);
    free(hashTable->buckets);
    free(hashTable);
}

