#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    long *offset;
    int *key;
    float weight;
    struct Record *next;
} Record;

Record* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_random() {
    srand(time(NULL));
}

long random_long(long min, long max) {
    return rand() % (max - min + 1) + min;
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

void* allocate_memory(size_t count, size_t type_size) {
    void *ptr = malloc(count * type_size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* create_record(long offset_val, int key_val, float weight_val) {
    Record *record = (Record*)allocate_memory(1, sizeof(Record));
    record->value = random_int(0, 100); // Example range
    record->offset = allocate_memory(1, sizeof(long));
    *record->offset = offset_val;
    record->key = allocate_memory(1, sizeof(int));
    *record->key = key_val;
    record->weight = weight_val;
    record->next = NULL;
    return record;
}

void initialize_records(size_t num_records) {
    pthread_mutex_lock(&lock);
    head = create_record(random_long(0, 1000), random_int(1, 100), random_float(0.0, 1.0));
    Record *current = head;

    for (size_t i = 1; i < num_records; ++i) {
        current->next = create_record(random_long(0, 1000), random_int(1, 100), random_float(0.0, 1.0));
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

Record* get_record_by_index(size_t index) {
    pthread_mutex_lock(&lock);
    Record *current = head;
    size_t count = 0;

    while (current && count < index) {
        current = current->next;
        ++count;
    }

    pthread_mutex_unlock(&lock);
    return current;
}

void update_weight_by_index(size_t index, float new_weight) {
    pthread_mutex_lock(&lock);
    Record *record = get_record_by_index(index);

    if (record) {
        record->weight = new_weight;
    }
    pthread_mutex_unlock(&lock);
}

void delete_record_by_index(size_t index) {
    pthread_mutex_lock(&lock);
    if (!index) {
        Record *temp = head;
        head = head->next;
        free(temp->offset);
        free(temp->key);
        free(temp);
    } else {
        Record *current = head;
        for (size_t i = 0; current && i < index - 1; ++i) {
            current = current->next;
        }

        if (current && current->next) {
            Record *temp = current->next;
            current->next = temp->next;
            free(temp->offset);
            free(temp->key);
            free(temp);
        }
    }
    pthread_mutex_unlock(&lock);
}

void cleanup() {
    pthread_mutex_lock(&lock);
    Record *current = head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp->offset);
        free(temp->key);
        free(temp);
    }
    head = NULL;
    pthread_mutex_unlock(&lock);
}

int main() {
    init_random();

    size_t num_records = 1000; // Example number of records
    initialize_records(num_records);

    // Example operations
    Record *record = get_record_by_index(5);
    if (record) {
        printf("Record at index 5: Value=%d, Weight=%.2f\n", record->value, record->weight);
    }

    update_weight_by_index(5, 0.75);

    delete_record_by_index(10);

    cleanup();

    return 0;
}
