### Key Points:
- **Thread Safety**: A mutex is used to ensure thread safety during operations on the linked list.
- **Random Initialization**: Random values are generated for offsets, keys, and weights.
- **Error Handling**: Memory allocation failures are handled gracefully with `perror` and program exit.
- **Memory Management**: Proper cleanup of dynamically allocated memory is ensured.
- **Concurrency**: The use of mutex locks ensures that concurrent access does not lead to race conditions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
    unsigned long access_count;
    double average_retrieval_time;  // for performance metrics
} Record;

// Cache node
typedef struct CacheNode {
    Record *record;
    struct CacheNode *next;
} CacheNode;

// Logging levels
typedef enum { ERROR, WARNING, INFO, DEBUG } LogLevel;

// Cache structure
typedef struct {
    CacheNode **buckets;
    size_t capacity;
    size_t size;
} Cache;

// Data system structure
typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    Cache cache;
    LogLevel log_level;
} DataSystem;

// Function prototypes
void init_data_system(DataSystem *system, size_t num_records, long offset_range, int key_range, size_t cache_size);
int generate_random(int min, int max);
void log_message(LogLevel level, const char* message);
CacheNode* create_cache_node(Record *record);
void cache_insert(Cache *cache, Record *record);
Record* cache_retrieve(Cache *cache, long offset);

// Initialize the data system
void init_data_system(DataSystem *system, size_t num_records, long offset_range, int key_range, size_t cache_size) {
    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for offsets and keys
    system->offsets = (long *)malloc(num_records * sizeof(long));
    system->keys = (int *)malloc(num_records * sizeof(int));

    if (!system->offsets || !system->keys) {
        log_message(ERROR, "Memory allocation failed for offsets or keys.");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records
    system->records = (Record **)malloc(num_records * sizeof(Record *));
    if (!system->records) {
        log_message(ERROR, "Memory allocation failed for records.");
        free(system->offsets);
        free(system->keys);
        exit(EXIT_FAILURE);
    }

    // Initialize cache
    system->cache.capacity = cache_size;
    system->cache.size = 0;
    system->cache.buckets = (CacheNode **)calloc(cache_size, sizeof(CacheNode *));
    if (!system->cache.buckets) {
        log_message(ERROR, "Memory allocation failed for cache.");
        free(system->records);
        free(system->offsets);
        free(system->keys);
        exit(EXIT_FAILURE);
    }

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        system->offsets[i] = generate_random(0, offset_range);
        system->keys[i] = generate_random(0, key_range);

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            log_message(ERROR, "Memory allocation failed for a record.");
            // Free previously allocated memory
            while (--i >= 0) free(system->records[i]);
            free(system->records);
            free(system->offsets);
            free(system->keys);
            free(system->cache.buckets);
            exit(EXIT_FAILURE);
        }

        record->value = generate_random(0, 100); // example range
        record->offset_ptr = &system->offsets[i];
        record->key_ptr = &system->keys[i];
        record->access_count = 0;
        record->average_retrieval_time = 0.0;

        system->records[i] = record;
    }

    log_message(INFO, "Data system initialized successfully.");
}

// Generate a random integer within a specified range
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Log messages based on level
void log_message(LogLevel level, const char* message) {
    // Implement logging logic here (console/file)
    printf("[%s] %s\n", level == ERROR ? "ERROR" : level == WARNING ? "WARNING" :
           level == INFO ? "INFO" : "DEBUG", message);
}

// Create a new cache node
CacheNode* create_cache_node(Record *record) {
    CacheNode *node = (CacheNode *)malloc(sizeof(CacheNode));
    if (!node) return NULL;
    node->record = record;
    node->next = NULL;
    return node;
}

// Insert a record into the cache
void cache_insert(Cache *cache, Record *record) {
    // Simple hash function for demo purposes
    size_t index = (size_t)(record->offset_ptr - &((*(Record **)record)->offset_ptr)) % cache->capacity;

    CacheNode *node = create_cache_node(record);
    if (!node) return;

    node->next = cache->buckets[index];
    cache->buckets[index] = node;
    ++cache->size;
}

// Retrieve a record from the cache
Record* cache_retrieve(Cache *cache, long offset) {
    size_t index = offset % cache->capacity;
    CacheNode *node = cache->buckets[index];

    while (node) {
        if (*(node->record->offset_ptr) == offset) return node->record;
        node = node->next;
    }
    return NULL; // Not found
}
