}

// Initialize the dynamic list of tasks
TaskList* initialize_task_list(size_t num_tasks, size_t desc_min_len, size_t desc_max_len, int priority_min, int priority_max) {
    TaskList *list = malloc(sizeof(TaskList));
    if (!list) {
        perror("Failed to allocate memory for task list");
        exit(EXIT_FAILURE);
    }

    list->capacity = num_tasks;
    list->size = 0;
    list->tasks = calloc(num_tasks, sizeof(Task*)); // Allocate memory for tasks
    if (!list->tasks) {
        free(list);
        perror("Failed to allocate memory for tasks");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_tasks; ++i) {
        Task *task = malloc(sizeof(Task));
        if (!task) {
            // Free allocated resources on failure
            while (--i >= 0) free(list->tasks[i]);
            free(list->tasks);
            free(list);
            perror("Failed to allocate memory for task");
            exit(EXIT_FAILURE);
        }

        initialize_task(task, desc_min_len, desc_max_len, priority_min, priority_max);
        list->tasks[list->size++] = task;
    }

    return list;
}

// Add a new task to the dynamic list
void add_task(TaskList *list, size_t desc_min_len, size_t desc_max_len, int priority_min, int priority_max) {
    if (list->size >= list->capacity) {
        // Resize the array when capacity is reached
        size_t new_capacity = list->capacity * 2;
        Task **new_tasks = realloc(list->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            perror("Failed to reallocate memory for tasks");
            exit(EXIT_FAILURE);
        }

        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }

    // Initialize and add the new task
    Task *task = malloc(sizeof(Task));
    if (!task) {
        perror("Failed to allocate memory for task");
        exit(EXIT_FAILURE);
    }

    initialize_task(task, desc_min_len, desc_max_len, priority_min, priority_max);
    list->tasks[list->size++] = task;
}

// Update an existing task
void update_task(TaskList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Task index out of range\n");
        return;
    }

    Task *task = list->tasks[index];
    initialize_task(task, 5, 20, 1, 10); // Using arbitrary ranges for update
}

// Retrieve a specific task by its index
Task* get_task(TaskList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Task index out of range\n");
        return NULL;
    }

    return list->tasks[index];
}

// Initialize the dynamic arrays with memory management for configs
DynamicArrays* initialize_dynamic_arrays(size_t num_doubles, size_t num_strings, size_t num_configs) {
    DynamicArrays *arrays = malloc(sizeof(DynamicArrays));
    if (!arrays) {
        perror("Failed to allocate memory for dynamic arrays");
        exit(EXIT_FAILURE);
    }

    arrays->doubles = calloc(num_doubles, sizeof(double)); // Allocate double array
    arrays->strings = calloc(num_strings, sizeof(char*));  // Allocate string pointers array

    arrays->configs = malloc(num_configs * sizeof(Config*));
    if (!arrays->configs) {
        free(arrays->doubles);
        free(arrays->strings);
        free(arrays);
        perror("Failed to allocate memory for config structures");
        exit(EXIT_FAILURE);
    }

    // Pre-allocate settings and initialize configs
    for (size_t i = 0; i < num_configs; ++i) {
        arrays->configs[i] = malloc(sizeof(Config));
        if (!arrays->configs[i]) {
            // Free all previously allocated memory on failure
            while (--i >= 0) free(arrays->configs[i]);
            free(arrays->doubles);
            free(arrays->strings);
            free(arrays->configs);
            free(arrays);
            perror("Failed to allocate memory for config");
            exit(EXIT_FAILURE);
        }

        arrays->configs[i]->ref_count = 1;
        arrays->configs[i]->settings = malloc(sizeof(Settings)); // Allocate settings
        if (!arrays->configs[i]->settings) {
            // Handle allocation failure by freeing and exiting
            while (--i >= 0) free(arrays->configs[i]);
            free(arrays->doubles);
            free(arrays->strings);
            free(arrays->configs);
            free(arrays);
            perror("Failed to allocate memory for config settings");
            exit(EXIT_FAILURE);
        }

        // Initialize settings
        arrays->configs[i]->settings->setting_value = 0;
    }

    arrays->logs = NULL; // Initially, no logs
    arrays->log_size = 0;
    arrays->log_capacity = 10;

    return arrays;
}

// Resize log entries when capacity is exceeded
void resize_logs(LogEntry **logs, size_t *capacity) {
    size_t new_capacity = (*capacity) * 2;
    LogEntry *new_logs = realloc(*logs, new_capacity * sizeof(LogEntry));

    if (!new_logs) {
        perror("Failed to reallocate memory for logs");
        exit(EXIT_FAILURE);
    }

    *logs = new_logs;
    *capacity = new_capacity;
}

// Add a log entry
void add_log(DynamicArrays *arrays, const char *user) {
    if (arrays->log_size >= arrays->log_capacity) {
        resize_logs(&arrays->logs, &arrays->log_capacity);
    }

    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Failed to allocate memory for log entry");
        exit(EXIT_FAILURE);
    }

    gettimeofday(&entry->timestamp, NULL);
    strncpy(entry->user, user, sizeof(entry->user) - 1);
    entry->next = arrays->logs;
    arrays->logs = entry;
    arrays->log_size++;
}

// Update config without reallocating entire array
void update_config(Config *config, int new_value) {
    if (!config) return;

    config->settings->setting_value = new_value;
}

// Clean up the task list and free memory
void cleanup_task_list(TaskList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->tasks[i]->description);
        free(list->tasks[i]);
    }

    free(list->tasks);
    free(list);
}

// Clean up dynamic arrays and associated memory
void cleanup_dynamic_arrays(DynamicArrays *arrays) {
    // Free string pointers
    for (size_t i = 0; i < (arrays ? arrays->log_size : 0); ++i) {
        free(arrays->strings[i]);
    }

    // Free configs and their settings
    for (size_t i = 0; i < (arrays ? arrays->log_capacity : 0); ++i) {
        if (arrays->configs && arrays->configs[i]) {
            free(arrays->configs[i]->settings);
            free(arrays->configs[i]);
        }
    }

    // Free logs
    LogEntry *current = arrays->logs;
    while (current) {
        LogEntry *next = current->next;
        free(current);
        current = next;
    }

    // Free dynamic array components
    free(arrays->doubles);
    free(arrays->strings);
    free(arrays->configs);
    free(arrays);
}

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    TaskList *task_list = initialize_task_list(5, 10, 15, 1, 5); // Initialize task list
    DynamicArrays *dynamic_arrays = initialize_dynamic_arrays(1000, 500, 50); // Initialize dynamic arrays

    add_log(dynamic_arrays, "user_123"); // Log example access

    update_task(task_list, 2); // Example task update
    Task *task = get_task(task_list, 2); // Retrieve task by index

    if (task) {
        printf("Task Description: %s\n", task->description);
        printf("Priority: %d\n", task->priority);
    }

    Config *config = dynamic_arrays->configs[0]; // Example config update
    update_config(config, 42);

    cleanup_task_list(task_list); // Cleanup task list and free memory
    cleanup_dynamic_arrays(dynamic_arrays); // Cleanup dynamic arrays

    return 0;
}
```

### Key Points:
- **Memory Management**: All allocations are carefully managed with checks for failures. Memory is freed appropriately to prevent leaks.
- **Dynamic Array Resizing**: Tasks, logs, and configurations handle resizing dynamically when capacity limits are exceeded.
- **Efficiency Considerations**: The code uses `calloc` and `realloc` effectively to manage memory efficiently.
- **Logging Mechanism**: Logs record access with timestamps without degrading performance, stored in a linked list for efficient additions.
- **Config Updates**: Config structures can be updated in place to avoid unnecessary reallocations.

This implementation is designed to handle dynamic lists of tasks and configurations while ensuring robust memory management and scalability.']

