#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "libxml/parser.h"
#include "libxml/tree.h"

typedef struct Record {
    int value;
    long *offset_ptr;
    int *key_ptr;
    float weight;
