} Record;

typedef struct LinkedList {
    Record *head;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
LinkedList* create_linked_list_from_xml(const char *xml_file);
void free_linked_list(LinkedList *list, long *offsets, int *keys, float *weights);
Record* get_record_by_index(LinkedList *list, size_t index);
int update_weight_by_index(LinkedList *list, size_t index, float new_weight);
int delete_record_by_index(LinkedList *list, size_t index);

// Helper function to load configuration from XML
void load_config_from_xml(const char *xml_file, int *tile_size, int *world_width, 
                          int *world_height, float *camera_speed) {
    xmlDoc *doc = xmlReadFile(xml_file, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        exit(EXIT_FAILURE);
    }
    xmlNode *root_element = xmlDocGetRootElement(doc);

    for (xmlNode *node = root_element->children; node; node = node->next) {
        if (strcmp((const char *)node->name, "tileSize") == 0) {
            *tile_size = atoi((const char *)xmlNodeListGetString(doc, node->children, 1));
        } else if (strcmp((const char *)node->name, "worldWidth") == 0) {
            *world_width = atoi((const char *)xmlNodeListGetString(doc, node->children, 1));
        } else if (strcmp((const char *)node->name, "worldHeight") == 0) {
            *world_height = atoi((const char *)xmlNodeListGetString(doc, node->children, 1));
        } else if (strcmp((const char *)node->name, "cameraSpeed") == 0) {
            *camera_speed = atof((const char *)xmlNodeListGetString(doc, node->children, 1));
        }
    }

    xmlFreeDoc(doc);
}

// Create and initialize the linked list from XML configuration
LinkedList* create_linked_list_from_xml(const char *xml_file) {
    int tile_size, world_width, world_height;
    float camera_speed;
    load_config_from_xml(xml_file, &tile_size, &world_width, &world_height, &camera_speed);

    size_t num_records = tile_size; // Example: number of records is based on tile_size
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    float *weights = malloc(num_records * sizeof(float));

    if (!offsets || !keys || !weights) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(weights);
        return NULL;
    }

    pthread_mutex_init(&mutex, NULL);

    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation for list failed\n");
        free(offsets);
        free(keys);
        free(weights);
        return NULL;
    }
    list->head = NULL;

    srand(time(NULL)); // Seed the random number generator

    pthread_mutex_lock(&list->lock);

    Record *current = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % world_width; // Example offset
        keys[i] = rand() % world_height;   // Example key
        weights[i] = (float)rand() / RAND_MAX; // Random weight

        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Memory allocation for record failed\n");
            break;
        }
        new_record->value = rand() % 100; // Random value
        new_record->offset_ptr = &offsets[i];
        new_record->key_ptr = &keys[i];
        new_record->weight = weights[i];
        new_record->next = NULL;

        if (!list->head) {
            list->head = new_record;
        } else {
            current->next = new_record;
        }
        current = new_record;
    }

    pthread_mutex_unlock(&list->lock);

    return list;
}

// Free the linked list and associated arrays
void free_linked_list(LinkedList *list, long *offsets, int *keys, float *weights) {
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    free(offsets);
    free(keys);
    free(weights);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Retrieve a specific record by its index
Record* get_record_by_index(LinkedList *list, size_t index) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    for (size_t i = 0; current && i < index; ++i) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

// Update the weight of a record by its index
int update_weight_by_index(LinkedList *list, size_t index, float new_weight) {
    pthread_mutex_lock(&list->lock);

    Record *record = get_record_by_index(list, index);
    if (record) {
        record->weight = new_weight;
        pthread_mutex_unlock(&list->lock);
        return 0; // Success
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Failure: record not found
}

// Delete a record by its index
int delete_record_by_index(LinkedList *list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Failure: list is empty
    }

    Record **indirect = &list->head;
    for (size_t i = 0; *indirect && i < index; ++i) {
        indirect = &(*indirect)->next;
    }

    if (!*indirect) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Failure: record not found
    }

    Record *record_to_delete = *indirect;
    *indirect = record_to_delete->next;
    free(record_to_delete);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}
```

