#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1000

typedef struct {
    int device_id;
    float temperature;
    int status;  // e.g., 1 for active, 0 for inactive
    time_t timestamp;
    float humidity;
} SensorEntry;

typedef struct Node {
    SensorEntry entry;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    pthread_mutex_t locks[TABLE_SIZE];
} HashTable;

unsigned int hash(int device_id) {
    return device_id % TABLE_SIZE;
}

HashTable* create_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(TABLE_SIZE, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

void destroy_table(HashTable* table) {
    if (!table) return;

    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node* head = table->buckets[i];
        while (head) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    }

    free(table->buckets);

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table);
}

int add_sensor(HashTable* table, SensorEntry entry) {
    if (!table) return -1;

    int index = hash(entry.device_id);
    pthread_mutex_lock(&table->locks[index]);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->locks[index]);
        return -1;
    }

    new_node->entry = entry;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index]);

    return 0;
}

int update_sensor(HashTable* table, int device_id, SensorEntry updated_entry) {
    if (!table) return -1;

    int index = hash(device_id);
    pthread_mutex_lock(&table->locks[index]);

    Node* current = table->buckets[index];
    while (current) {
        if (current->entry.device_id == device_id) {
            current->entry = updated_entry;
            pthread_mutex_unlock(&table->locks[index]);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return -1;
}

int delete_sensor(HashTable* table, int device_id) {
    if (!table) return -1;

    int index = hash(device_id);
    pthread_mutex_lock(&table->locks[index]);

    Node* current = table->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->entry.device_id == device_id) {
            if (prev) {
                prev->next = current->next;
            } else {
                table->buckets[index] = current->next;
            }
            free(current);
            pthread_mutex_unlock(&table->locks[index]);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return -1;
}

SensorEntry* get_sensor(HashTable* table, int device_id) {
    if (!table) return NULL;

    int index = hash(device_id);
    pthread_mutex_lock(&table->locks[index]);

    Node* current = table->buckets[index];
    while (current) {
        if (current->entry.device_id == device_id) {
            SensorEntry* entry = &current->entry;
            pthread_mutex_unlock(&table->locks[index]);
            return entry;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

```

