    for line in reader.lines() {
        let mut parts = line?.split(',');
        if parts.len() != 3 {
            eprintln!("Invalid input format");
            continue;
        }

        let merchant_id = parts.next().unwrap().to_string();
        let currency_code = parts.next().unwrap().to_string();
        let amount: f64 = parts.next().unwrap().parse()?;

        // Create a transaction and initialize its fields
