        // Route the transaction to the appropriate payment gateway
        route_transaction(&transaction, &cache).await?;

        // Update the database with the new transaction
        update_transaction_in_db(&pool, &transaction).await?;
    }

    Ok(())
}

async fn route_transaction(transaction: &Transaction, cache: &Mutex<HashMap<String, String>>) -> Result<(), Box<dyn std::error::Error>> {
    let gateway_client = GatewayClient::new(&transaction.merchant_id, &transaction.currency_code);

    // Check cache first
    let mut cache_guard = cache.lock().await;
    if let Some(status) = cache_guard.get(&transaction.transaction_id.to_string()) {
        transaction.status = status.clone();
        return Ok(());
    }

    // Initiate the transaction via the gateway client
    gateway_client.initiate_transaction(transaction).await?;

    // Poll for status update
    loop {
        match gateway_client.poll_status(transaction).await {
            Ok(status) => {
                transaction.status = status;
                cache_guard.insert(transaction.transaction_id.to_string(), &status);
                break;
            }
            Err(e) if e.is_transient() => {
                tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
                continue;
            }
            Err(e) => return Err(Box::new(e)),
        }
    }

    Ok(())
}

