use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::io::{self, BufRead};
use std::net::TcpStream;
use std::time::Duration;
use reqwest::{Client, header};

const MAX_RECORDS: usize = 10_000;

struct Record {
    value: i32,
    offset_ptr: *mut u64,
    key_ptr: *mut i32,
}

struct RecordPool {
    records: Vec<Option<Record>>,
    free_indices: Vec<usize>,
}

impl RecordPool {
    fn new() -> Self {
        let mut pool = RecordPool {
            records: vec![None; MAX_RECORDS],
            free_indices: (0..MAX_RECORDS).collect(),
        };

        for i in 0..MAX_RECORDS {
            // Assuming safe offsets and keys allocation
            unsafe {
                let offset_ptr = Box::into_raw(Box::new(0));
                let key_ptr = Box::into_raw(Box::new(i as i32));

                pool.records[i] = Some(Record {
                    value: 0,
                    offset_ptr,
                    key_ptr,
                });
            }
        }

        pool
    }

    fn get_record(&self, index: usize) -> Option<&Record> {
        self.records.get(index).and_then(|record| record.as_ref())
    }

    fn update_record_value(&mut self, index: usize, new_value: i32) {
        if let Some(record) = &mut self.records[index] {
            record.value = new_value;
        }
    }

    fn delete_record(&mut self, index: usize) {
        if let Some(record) = &self.records[index] {
            unsafe {
                if !record.offset_ptr.is_null() {
                    Box::from_raw(record.offset_ptr);
                }
                if !record.key_ptr.is_null() {
                    Box::from_raw(record.key_ptr);
                }
            }
        }
        self.records[index] = None;
        self.free_indices.push(index);
    }

    fn insert_record(&mut self, record: Record) -> Option<usize> {
        if let Some(index) = self.free_indices.pop() {
            self.records[index] = Some(record);
            return Some(index);
        }
        None
    }
}

