void *(*custom_alloc)(size_t size);
void (*custom_free)(void *ptr);

// Initialization function for custom memory management
void set_memory_callbacks(void *(*alloc_fn)(size_t), void (*free_fn)(void *)) {
    custom_alloc = alloc_fn;
    custom_free = free_fn;
}

// Default allocation and deallocation functions
static void *default_alloc(size_t size) {
    return malloc(size);
}

static void default_free(void *ptr) {
    free(ptr);
}

void init_memory_callbacks() {
    set_memory_callbacks(default_alloc, default_free);
}

typedef struct {
    record *array;
    atomic_size_t count;
    atomic_size_t capacity;
    long *offsets;
    int *keys;
} storage_system;

storage_system* create_storage_system(size_t initial_capacity) {
    storage_system *system = (storage_system *)custom_alloc(sizeof(storage_system));
    if (!system) return NULL;

    system->array = (record *)custom_alloc(initial_capacity * sizeof(record));
    system->offsets = (long *)custom_alloc(initial_capacity * sizeof(long));
    system->keys = (int *)custom_alloc(initial_capacity * sizeof(int));
    atomic_store(&system->count, 0);
    atomic_store(&system->capacity, initial_capacity);

    if (!system->array || !system->offsets || !system->keys) {
        custom_free(system->array);
        custom_free(system->offsets);
        custom_free(system->keys);
        custom_free(system);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        system->offsets[i] = -1;
        system->keys[i] = -1;
    }

    return system;
}

void free_storage_system(storage_system *system) {
    if (!system) return;

    custom_free(system->array);
    custom_free(system->offsets);
    custom_free(system->keys);
    custom_free(system);
}

int add_record(storage_system *system, int value_range_min, int value_range_max) {
    size_t count = atomic_load(&system->count);
    if (count >= system->capacity * 0.8) {
        // Compact the array
        size_t new_capacity = system->capacity * 2;
        record *new_array = (record *)custom_alloc(new_capacity * sizeof(record));
        long *new_offsets = (long *)custom_alloc(new_capacity * sizeof(long));
        int *new_keys = (int *)custom_alloc(new_capacity * sizeof(int));

        if (!new_array || !new_offsets || !new_keys) {
            custom_free(new_array);
            custom_free(new_offsets);
            custom_free(new_keys);
            return -1;
        }

        memcpy(new_array, system->array, count * sizeof(record));
        memcpy(new_offsets, system->offsets, count * sizeof(long));
        memcpy(new_keys, system->keys, count * sizeof(int));

        custom_free(system->array);
        custom_free(system->offsets);
        custom_free(system->keys);

        system->array = new_array;
        system->offsets = new_offsets;
        system->keys = new_keys;

        atomic_store(&system->capacity, new_capacity);
    }

    size_t index = count;
    int value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

    record *rec = &system->array[index];
    rec->value = value;
    rec->offset = &system->offsets[index];
    rec->key = &system->keys[index];

    atomic_store(&system->count, count + 1);

    return 0; // Success
}

record* get_record_by_index(storage_system *system, size_t index) {
    if (index >= atomic_load(&system->count)) return NULL;
    return &system->array[index];
}

// Retrieve a record by key range within tolerance
record* find_record_in_key_range(storage_system *system, int key_start, int tolerance) {
    for (size_t i = 0; i < atomic_load(&system->count); ++i) {
        if (atomic_load(system->keys + i) >= key_start &&
            atomic_load(system->keys + i) <= (key_start + tolerance)) {
            return &system->array[i];
        }
    }
    return NULL;
}

void seed_random() {
    srand((unsigned int)time(NULL));
}
