#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <pthread.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

// Callbacks for memory management
void *(*alloc_func)(size_t);
void (*free_func)(void *);

// Initialize random number generator
static void init_random() {
    srand((unsigned)time(NULL));
}

// Generate a random integer within a given range [min, max]
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Default memory allocation function
void *default_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) perror("Allocation failed");
    return ptr;
}

// Default memory deallocation function
void default_free(void *ptr) {
    free(ptr);
}

// Initialize collection with records
Record **initialize_records(size_t count, int min_val, int max_val, void *(*alloc)(size_t), void (*free)(void *)) {
    Record **records = (Record **)alloc(sizeof(Record *) * count);

    if (!records) return NULL;

    for (size_t i = 0; i < count; ++i) {
        records[i] = (Record *)alloc(sizeof(Record));

        if (!records[i]) {
            // Free already allocated resources
            while (--i >= 0)
                free(records[i]);
            free(records);
            return NULL;
        }

        records[i]->value = generate_random(min_val, max_val);
        records[i]->offset = (long *)alloc(sizeof(long));
        records[i]->key = (int *)alloc(sizeof(int));

        if (!records[i]->offset || !records[i]->key) {
            // Free already allocated resources
            while (--i >= 0)
                free(records[i]);
            free(records);
            return NULL;
        }

        *records[i]->offset = i;  // Example offset value
        *records[i]->key = (int)i % 100;  // Example key value
    }
    return records;
}

// Free the collection of records
void free_records(Record **records, size_t count) {
    for (size_t i = 0; i < count; ++i)
        if (records[i]) {
            free(records[i]->offset);
            free(records[i]->key);
            free(records[i]);
        }
    free(records);
}

// Initialize the collection using a specified memory allocator
void create_record_collection(size_t record_count, int min_val, int max_val) {
    init_random();

    // Set default allocation and deallocation functions if not set
    alloc_func = alloc_func ? alloc_func : default_alloc;
    free_func = free_func ? free_func : default_free;

    Record **records = initialize_records(record_count, min_val, max_val, alloc_func, free_func);

    if (!records) {
        fprintf(stderr, "Failed to create records\n");
        return;
    }

    // Simulate usage
    for (size_t i = 0; i < record_count; ++i) {
        printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n", 
               i, records[i]->value, *records[i]->offset, *records[i]->key);
    }

    // Free resources
    free_records(records, record_count);
}

int main() {
    size_t num_records = 10000000; // 10 million records
    int min_value = 0;
    int max_value = 100;

    create_record_collection(num_records, min_value, max_value);

    return 0;
}
