    pthread_rwlock_t rwlock; // Read-write lock for concurrent access
} StorageSystem;

void init_storage_system(StorageSystem *storage) {
    storage->capacity = 0;
    storage->count = 0;
    pthread_rwlock_init(&storage->rwlock, NULL);
}

void destroy_storage_system(StorageSystem *storage) {
    if (storage->records) {
        for (size_t i = 0; i < storage->count; ++i) {
            free(storage->records[i].offset);
            free(storage->records[i].key);
        }
        free(storage->records);
        storage->records = NULL;
    }
    pthread_rwlock_destroy(&storage->rwlock);
}

int resize_storage_system(StorageSystem *storage, size_t new_capacity) {
    Record *new_records = realloc(storage->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    for (size_t i = storage->count; i < new_capacity; ++i) {
        new_records[i].offset = NULL;
        new_records[i].key = NULL;
    }

    storage->records = new_records;
    storage->capacity = new_capacity;
    return 0;
}

int add_record(StorageSystem *storage, int value, long offset, int key) {
    pthread_rwlock_wrlock(&storage->rwlock);

    if (storage->count >= storage->capacity || 
        (storage->capacity > 0 && storage->count >= storage->capacity * 0.75)) {

        size_t new_capacity = storage->capacity == 0 ? 1024 : storage->capacity * 2;
        int resize_result = resize_storage_system(storage, new_capacity);
        if (resize_result != 0) {
            pthread_rwlock_unlock(&storage->rwlock);
            return -1; // Memory allocation failure
        }
    }

    size_t index = storage->count++;
    storage->records[index].value = value;
    storage->records[index].offset = malloc(sizeof(long));
    storage->records[index].key = malloc(sizeof(int));

    if (!storage->records[index].offset || !storage->records[index].key) {
        pthread_rwlock_unlock(&storage->rwlock);
        return -1; // Memory allocation failure
    }

    *storage->records[index].offset = offset;
    *storage->records[index].key = key;

    pthread_rwlock_unlock(&storage->rwlock);
    return 0;
}

int get_record_by_index(StorageSystem *storage, size_t index, int *value, long *offset, int *key) {
    pthread_rwlock_rdlock(&storage->rwlock);

    if (index >= storage->count) {
        pthread_rwlock_unlock(&storage->rwlock);
        return -1; // Index out of bounds
    }

    *value = storage->records[index].value;
    *offset = *(storage->records[index].offset);
    *key = *(storage->records[index].key);

    pthread_rwlock_unlock(&storage->rwlock);
    return 0;
}

