['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

// Function to handle memory allocation errors
void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize and manage records
record* initializeAndManageRecords(int num_records, int min_value, int max_value) {
    // Bulk allocate memory for offsets, keys, and records
    long *offsets = (long*) safeMalloc(num_records * sizeof(long));
    int *keys = (int*) safeMalloc(num_records * sizeof(int));
    record *records = (record*) safeMalloc(num_records * sizeof(record));

    // Initialize the arrays with random values for keys and offsets, and records
    srand(time(NULL));  // Seed for random number generation

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand();
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        // Set pointers in the record structure
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    return records;
}

// Retrieve a specific record by its index
record* getRecord(record *records, int num_records, int index) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
    return &records[index];
}

// Update the value of a specific record by its index
void updateRecordValue(record *records, int num_records, int index, int newValue) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    records[index].value = newValue;
}

// Insert a new record at a specified position
void insertRecord(record **records, int *num_records, int position, record new_record) {
    if (position < 0 || position > *num_records) {
        fprintf(stderr, "Position out of bounds\n");
        return;
    }

    // Allocate space for the new array with one more element
    record *new_array = (record*) safeMalloc((*num_records + 1) * sizeof(record));

    // Copy existing records into the new array and insert the new_record at position
    memcpy(new_array, *records, position * sizeof(record));
    new_array[position] = new_record;
    memcpy(new_array + position + 1, (*records) + position, (*num_records - position) * sizeof(record));

    // Free old records array and update pointers/size
    free(*records);
    *records = new_array;
    (*num_records)++;
}

// Helper function to swap two integers
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Function to perform stable sort in descending order
void stableSortDescending(int *array, int n) {
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (array[j] < array[j + 1]) {
                swap(&array[j], &array[j + 1]);
            }
        }
    }
}

// Function to find the median of a sorted array
double findMedian(int *array, int n) {
    if (n % 2 == 0)
        return (array[n / 2 - 1] + array[n / 2]) / 2.0;
    else
        return array[n / 2];
}

// Function to calculate the standard deviation of an array
double calculateStdDev(int *array, int n) {
    double mean = 0.0;
    for (int i = 0; i < n; ++i)
        mean += array[i];
    mean /= n;

    double variance = 0.0;
    for (int i = 0; i < n; ++i)
        variance += pow(array[i] - mean, 2);

    return sqrt(variance / n);
}

// Main function to demonstrate the usage
void processInputData() {
    int num_elements;

    // Read number of elements from standard input
    printf("Enter number of integers: ");
    scanf("%d", &num_elements);

    if (num_elements <= 0) {
        fprintf(stderr, "Invalid number of elements\n");
        return;
    }

    // Allocate memory for the integer array
    int *data = (int*) safeMalloc(num_elements * sizeof(int));

    // Read integers from standard input
    printf("Enter %d integers:\n", num_elements);
    for (int i = 0; i < num_elements; ++i) {
        scanf("%d", &data[i]);
    }

    // Sort the array in descending order using stable sort algorithm
    stableSortDescending(data, num_elements);

    // Find and print median value
    double median = findMedian(data, num_elements);
    printf("Median: %.2f\n", median);

    // Calculate and print standard deviation
    double stdDev = calculateStdDev(data, num_elements);
    printf("Standard Deviation: %.2f\n", stdDev);

    // Free allocated memory for data array
    free(data);
}

// Function to cleanup dynamically allocated records
void cleanupRecords(record *records, int num_records) {
    free(records);
}
