        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    record* rec = create_record(range_min, range_max);
    if (!rec) {
        log_message("Failed to create a new record");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->records[manager->count++] = rec;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int delete_record(RecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        log_message("Index out of bounds");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    record* rec = manager->records[index];
    free(rec->offset);
    free(rec->key);
    free(rec);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->records[i] = manager->records[i + 1];
    }
    --manager->count;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

record* get_record(RecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        log_message("Index out of bounds");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    record* rec = manager->records[index];
    pthread_mutex_unlock(&manager->mutex);
    return rec;
}

int update_record_value(RecordManager* manager, size_t index, int new_value) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        log_message("Index out of bounds");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    record* rec = manager->records[index];
    rec->value = new_value;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void free_manager(RecordManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        record* rec = manager->records[i];
        free(rec->offset);
        free(rec->key);
        free(rec);
    }

    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int main() {
    if (initialize_random_seed()) return 1;

    RecordManager* manager = create_manager();
    if (!manager) return 1;

    // Example operations
    add_record(manager, 0, 100);
    record* rec = get_record(manager, 0);
    if (rec) printf("Record value: %d\n", rec->value);

    update_record_value(manager, 0, 42);
    rec = get_record(manager, 0);
    if (rec) printf("Updated Record value: %d\n", rec->value);

    delete_record(manager, 0);

    free_manager(manager);
    return 0;
}
```

