```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PROFILES 10000
#define HASH_TABLE_SIZE 1000000
#define USERNAME_LENGTH_MIN 5
#define USERNAME_LENGTH_MAX 15

typedef struct UserProfile {
    int id;
    char *username;
    struct UserProfile **friends;
    size_t friend_count;
    struct UserProfile **blocked;
    size_t blocked_count;
    time_t last_active;
    pthread_mutex_t lock;
} UserProfile;

typedef struct HashTableEntry {
    int id;
    UserProfile *profile;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry *entries[HASH_TABLE_SIZE];
    pthread_rwlock_t rwlock;
} HashTable;

UserProfile **profiles = NULL;
HashTable hash_table;
pthread_mutex_t memory_pool_lock;

// Memory pool for user profiles
#define MEMORY_POOL_SIZE (MAX_PROFILES * sizeof(UserProfile))
char memory_pool[MEMORY_POOL_SIZE];
size_t allocated_profiles = 0;

// Function prototypes
void initialize_system();
UserProfile* create_profile(int id, const char *username);
void delete_profile(UserProfile *profile);
UserProfile* get_profile_by_id(int id);
void update_username(int id, const char *new_username);
void add_friend(int profile_id, int friend_id);
void block_user(int profile_id, int user_id);
void unblock_user(int profile_id, int user_id);
void cleanup_inactive_profiles();
void log_change(const char *message);

// Hash function
unsigned long hash_function(int id) {
    return (id % HASH_TABLE_SIZE);
}

// Initialize system resources
void initialize_system() {
    memset(memory_pool, 0, MEMORY_POOL_SIZE);
    profiles = malloc(MAX_PROFILES * sizeof(UserProfile*));
    if (!profiles) {
        perror("Failed to allocate memory for profiles");
        exit(EXIT_FAILURE);
    }

    pthread_rwlock_init(&hash_table.rwlock, NULL);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table.entries[i] = NULL;
    }
}

// Allocate a new user profile
UserProfile* create_profile(int id, const char *username) {
    pthread_mutex_lock(&memory_pool_lock);
    if (allocated_profiles >= MAX_PROFILES) {
        pthread_mutex_unlock(&memory_pool_lock);
        return NULL;
    }

    UserProfile *profile = (UserProfile*)(memory_pool + allocated_profiles * sizeof(UserProfile));
    allocated_profiles++;
    pthread_mutex_unlock(&memory_pool_lock);

    profile->id = id;
    profile->username = strdup(username);
    profile->friends = NULL;
    profile->friend_count = 0;
    profile->blocked = NULL;
    profile->blocked_count = 0;
    profile->last_active = time(NULL);
    pthread_mutex_init(&profile->lock, NULL);

    unsigned long index = hash_function(id);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    entry->id = id;
    entry->profile = profile;
    entry->next = hash_table.entries[index];
    hash_table.entries[index] = entry;

    return profile;
}

// Delete a user profile
void delete_profile(UserProfile *profile) {
    unsigned long index = hash_function(profile->id);
    pthread_rwlock_wrlock(&hash_table.rwlock);

    HashTableEntry **entry_ptr = &hash_table.entries[index];
    while (*entry_ptr) {
        if ((*entry_ptr)->id == profile->id) {
            HashTableEntry *to_delete = *entry_ptr;
            *entry_ptr = to_delete->next;
            free(to_delete);
            break;
        }
        entry_ptr = &(*entry_ptr)->next;
    }

    pthread_rwlock_unlock(&hash_table.rwlock);

    pthread_mutex_lock(&profile->lock);
    if (profile->username) {
        free(profile->username);
    }
    pthread_mutex_unlock(&profile->lock);
}

// Retrieve a profile by ID
UserProfile* get_profile_by_id(int id) {
    unsigned long index = hash_function(id);
    pthread_rwlock_rdlock(&hash_table.rwlock);

    HashTableEntry *entry = hash_table.entries[index];
    while (entry) {
        if (entry->id == id) {
            UserProfile *profile = entry->profile;
            pthread_rwlock_unlock(&hash_table.rwlock);
            return profile;
        }
        entry = entry->next;
    }

    pthread_rwlock_unlock(&hash_table.rwlock);
    return NULL;
}

// Update a profile's username
void update_username(int id, const char *new_username) {
    UserProfile *profile = get_profile_by_id(id);
    if (profile) {
        pthread_mutex_lock(&profile->lock);
        free(profile->username);
        profile->username = strdup(new_username);
        log_change("Username updated");
        pthread_mutex_unlock(&profile->lock);
    }
}

// Add a friend connection
void add_friend(int profile_id, int friend_id) {
    UserProfile *profile = get_profile_by_id(profile_id);
    if (profile) {
        pthread_mutex_lock(&profile->lock);

        // Allocate space for new friend
        size_t new_size = (profile->friend_count + 1) * sizeof(UserProfile*);
        UserProfile **new_friends = realloc(profile->friends, new_size);
        if (!new_friends) {
            pthread_mutex_unlock(&profile->lock);
            return;
        }
        profile->friends = new_friends;

        // Add friend
        profile->friends[profile->friend_count++] = get_profile_by_id(friend_id);

        pthread_mutex_unlock(&profile->lock);
    }
}

// Block a user connection
void block_user(int profile_id, int user_id) {
    UserProfile *profile = get_profile_by_id(profile_id);
    if (profile) {
        pthread_mutex_lock(&profile->lock);

        // Allocate space for new blocked user
        size_t new_size = (profile->blocked_count + 1) * sizeof(UserProfile*);
        UserProfile **new_blocked = realloc(profile->blocked, new_size);
        if (!new_blocked) {
            pthread_mutex_unlock(&profile->lock);
            return;
        }
        profile->blocked = new_blocked;

        // Block user
        profile->blocked[profile->blocked_count++] = get_profile_by_id(user_id);

        pthread_mutex_unlock(&profile->lock);
    }
}

// Unblock a user connection
void unblock_user(int profile_id, int user_id) {
    UserProfile *profile = get_profile_by_id(profile_id);
    if (profile) {
        pthread_mutex_lock(&profile->lock);

        for (size_t i = 0; i < profile->blocked_count; ++i) {
            if (profile->blocked[i]->id == user_id) {
                // Shift remaining blocked users
                memmove(&profile->blocked[i], &profile->blocked[i + 1],
                        (profile->blocked_count - i - 1) * sizeof(UserProfile*));
                profile->blocked_count--;
                UserProfile **new_blocked = realloc(profile->blocked,
                                                    profile->blocked_count * sizeof(UserProfile*));
                if (!new_blocked && profile->blocked_count > 0) {
                    // Handle reallocation failure gracefully
                    return;
                }
                profile->blocked = new_blocked;
                break;
            }
        }

        pthread_mutex_unlock(&profile->lock);
    }
}

// Log changes to user profiles
void log_change(const char *message) {
    time_t now = time(NULL);
    printf("[%ld] %s\n", now, message);
}

// Cleanup inactive profiles
void cleanup_inactive_profiles() {
    // This function would iterate through all profiles and remove those that are inactive.
    // For simplicity, this is a placeholder implementation.
}

int main() {
    initialize_system();

    // Example usage:
    UserProfile *profile1 = create_profile(1, "UserOne");
    if (profile1) log_change("Profile created");

    UserProfile *profile2 = create_profile(2, "UserTwo");
    if (profile2) log_change("Profile created");

    add_friend(1, 2);
    block_user(1, 2);

    update_username(1, "NewUsernameOne");

    cleanup_inactive_profiles();

    delete_profile(profile1);
    delete_profile(profile2);

    return 0;
}
