} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned int total_allocations;
    unsigned int total_deallocations;
} RecordManager;

RecordManager* create_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    memset(manager->records, 0, initial_capacity * sizeof(Record*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_allocations = 0;
    manager->total_deallocations = 0;

    return manager;
}

void destroy_manager(RecordManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->offset);
        free(manager->records[i]->key);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void* allocate_record(void) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = rand() % 100; // Random value between 0 and 99
    record->offset = (long*)malloc(sizeof(long));
    *record->offset = 0;
    record->key = (int*)malloc(sizeof(int));
    *record->key = rand() % 1000;

    return record;
}

void add_record(RecordManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity || 
        (manager->records && (size_t)(manager->records[0] - (char*)manager + sizeof(Record*)) * sizeof(Record*) > MAX_MEMORY_USAGE)) {
        size_t new_capacity = manager->capacity * 2;
        Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        memset(new_records + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Record*));
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    Record* record = allocate_record();
    if (!record) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    size_t index = manager->count++;
    manager->records[index] = record;

    manager->total_allocations++;

    pthread_mutex_unlock(&manager->lock);
}

Record* get_record(RecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    Record* record = NULL;
    if (index < manager->count) {
        record = manager->records[index];
    }

    pthread_mutex_unlock(&manager->lock);
    return record;
}

void remove_record(RecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    free(manager->records[index]->offset);
    free(manager->records[index]->key);
    free(manager->records[index]);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->records[i] = manager->records[i + 1];
    }

    manager->records[--manager->count] = NULL;
    manager->total_deallocations++;

    pthread_mutex_unlock(&manager->lock);
}

void iterate_and_update(RecordManager* manager, void (*operation)(Record*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        operation(manager->records[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_record_operation(Record* record) {
