    if (!integers) return;

    int value;
    while (scanf("%d", &value) == 1) {
        if (current_size >= capacity) {
            capacity *= 2;
            integers = (int*)realloc(integers, capacity * sizeof(int));
            if (!integers) break;
        }

        integers[current_size++] = value;
    }

    int max_value = find_max_in_array(integers, current_size);
    printf("Maximum integer: %d\n", max_value);

    free(integers);
}

void print_statistics(RecordManager* manager) {
    printf("Total allocations: %u\n", manager->total_allocations);
    printf("Total deallocations: %u\n", manager->total_deallocations);
}

