    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        // Resize the records array
        size_t new_capacity = manager->capacity * 2;
        LogRecord **new_records = (LogRecord**)custom_alloc(new_capacity * sizeof(LogRecord*));

        for (size_t i = 0; i < manager->size; ++i) {
            new_records[i] = manager->records[i];
        }
        free(manager->records);
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    LogRecord *new_record = (LogRecord*)custom_alloc(sizeof(LogRecord));
    new_record->timestamp = timestamp;
    new_record->event_id = event_id;
