#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int resourceID;
    char url[256];
    char fieldName[50];
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long allocations;
    unsigned long deallocations;
} DynamicFieldManager;

DynamicFieldManager* createDynamicFieldManager() {
    DynamicFieldManager *manager = (DynamicFieldManager*) malloc(sizeof(DynamicFieldManager));
    if (!manager) return NULL;

    manager->records = (Record*) malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->allocations = 0;
    manager->deallocations = 0;

    return manager;
}

void destroyDynamicFieldManager(DynamicFieldManager *manager) {
    if (!manager) return;

    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    printf("Total Allocations: %lu\n", manager->allocations);
    printf("Total Deallocations: %lu\n", manager->deallocations);
}

void ensureCapacity(DynamicFieldManager *manager) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record *new_records = (Record*) realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) return; // Handle allocation failure gracefully

        manager->records = new_records;
        manager->capacity = new_capacity;
    }
}

void addRecord(DynamicFieldManager *manager, int resourceID, const char *url, const char *fieldName) {
    pthread_mutex_lock(&manager->lock);

    ensureCapacity(manager);
    Record *record = &manager->records[manager->count++];
    record->resourceID = resourceID;
    strncpy(record->url, url, sizeof(record->url));
    strncpy(record->fieldName, fieldName, sizeof(record->fieldName));

    manager->allocations++;

    pthread_mutex_unlock(&manager->lock);
}

int removeRecord(DynamicFieldManager *manager, int index) {
    pthread_mutex_lock(&manager->lock);

    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Index out of bounds
    }

    memmove(&manager->records[index], &manager->records[index + 1], 
            (manager->count - index - 1) * sizeof(Record));
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
    manager->deallocations++;

    return 0;
}

Record* getRecord(DynamicFieldManager *manager, int index) {
    pthread_mutex_lock(&manager->lock);

    Record *record = NULL;
    if (index >= 0 && index < manager->count) {
        record = &manager->records[index];
    }

    pthread_mutex_unlock(&manager->lock);
    return record;
}

int findMax(int *arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void refreshFields(DynamicFieldManager *manager, const char **fieldNamesToRefresh, size_t namesCount) {
    for (size_t i = 0; i < manager->count; ++i) {
        Record *record = &manager->records[i];

        for (size_t j = 0; j < namesCount; ++j) {
            if (strcmp(record->fieldName, fieldNamesToRefresh[j]) == 0) {
                printf("Refreshing field: %s\n", record->fieldName);
                // Simulate sending a message to the parent window and receiving a response
                int simulatedResponse = rand() % 100;
                printf("Updated resourceID %d with value %d from URL %s\n", 
                       record->resourceID, simulatedResponse, record->url);

                break; // Break after finding the first match
            }
        }
    }
}

int main() {
    DynamicFieldManager *manager = createDynamicFieldManager();
    if (!manager) return EXIT_FAILURE;

    // Example usage: add records with random values within a range
    for (int i = 0; i < 20; ++i) {
        int resourceID = rand() % 100;
        snprintf(manager->records[i].url, sizeof(manager->records[i].url), "http://example.com/resource%d", i);
        snprintf(manager->records[i].fieldName, sizeof(manager->records[i].fieldName), "field%d", i);

        addRecord(manager, resourceID, manager->records[i].url, manager->records[i].fieldName);
    }

    const char *fieldsToRefresh[] = {"field5", "field10"};
    refreshFields(manager, fieldsToRefresh, 2);

    // Read integers from standard input
    int numbers[100];
    size_t count;
    printf("Enter integers: ");
    count = 0;

    while (scanf("%d", &numbers[count]) == 1 && count < 100) {
        ++count;
    }

    if (count > 0) {
        int maxNumber = findMax(numbers, count);
        printf("Largest number: %d\n", maxNumber);
    }

    destroyDynamicFieldManager(manager);

    return EXIT_SUCCESS;
}
