#include <condition_variable>

namespace LoggingFramework {

    enum LogLevel {
        DEBUG,
        INFO,
        WARN,
        ERROR,
        CRITICAL
    };

    class Logger {
    public:
        Logger(const std::string& logFilePath, size_t maxFileSize = 10 * 1024 * 1024, int rotationDays = 7);
        ~Logger();

        void setLogLevel(LogLevel level) { logLevel.store(level); }
        LogLevel getLogLevel() const { return static_cast<LogLevel>(logLevel.load()); }

        void log(const std::string& message, LogLevel level, const std::string& tag = "");

    private:
        void rotateLogs();
        void writeToFile(const std::string& message);
        bool shouldRotate();

        std::ofstream logFile;
        std::mutex fileMutex;
        size_t maxFileSize;
        int rotationDays;
        std::atomic<LogLevel> logLevel;
        std::vector<std::string> tags;

        // Throttling variables
        std::chrono::time_point<std::chrono::steady_clock> lastConsoleLogTime;
        std::chrono::milliseconds consoleThrottleInterval{100};
    };

    Logger::Logger(const std::string& logFilePath, size_t maxFileSize, int rotationDays)
        : logFile(logFilePath, std::ios::app), maxFileSize(maxFileSize), rotationDays(rotationDays),
          logLevel(INFO) { // Default log level
        if (!logFile.is_open()) {
            throw std::runtime_error("Failed to open log file.");
        }
    }

    Logger::~Logger() {
        if (logFile.is_open()) {
            logFile.close();
        }
    }

    void Logger::rotateLogs() {
        std::lock_guard<std::mutex> lock(fileMutex);
        if (!shouldRotate()) return;

        // Close current log file
        logFile.close();

        // Rename the existing file
        std::string newFileName = logFilePath + "." + std::to_string(std::chrono::system_clock::now().time_since_epoch().count());
        std::rename(logFilePath.c_str(), newFileName.c_str());

        // Open a new log file
        logFile.open(logFilePath, std::ios::app);
    }

    void Logger::writeToFile(const std::string& message) {
        std::lock_guard<std::mutex> lock(fileMutex);
        logFile << message << std::endl;
        if (logFile.tellp() >= maxFileSize) {
            rotateLogs();
        }
    }

    bool Logger::shouldRotate() {
        return logFile.tellp() >= maxFileSize; // Simplified check for example
    }

    void Logger::log(const std::string& message, LogLevel level, const std::string& tag) {
        if (level < logLevel.load()) return;

        auto now = std::chrono::steady_clock::now();
        std::lock_guard<std::mutex> lock(fileMutex);

        if (level <= CRITICAL || now - lastConsoleLogTime > consoleThrottleInterval) {
            std::cout << message << std::endl;
            lastConsoleLogTime = now;
        }

        writeToFile(message);
    }
}

int main() {
    try {
        LoggingFramework::Logger logger("app.log");

        logger.setLogLevel(LoggingFramework::DEBUG);

        logger.log("This is a debug message", LoggingFramework::Logger::DEBUG, "Initialization");
        logger.log("An info message", LoggingFramework::Logger::INFO);
        logger.log("A warning occurred", LoggingFramework::Logger::WARN);
        logger.log("Error encountered", LoggingFramework::Logger::ERROR);
        logger.log("Critical issue!", LoggingFramework::Logger::CRITICAL);

    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

