#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void* allocate_and_initialize(size_t num_records, long range_low, long range_high, const char *filename) {
    // Allocate memory for arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));

    Record *records = (Record *)malloc(num_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (range_high - range_low + 1) + range_low;
        keys[i] = rand();
        records[i].value = rand() % (range_high - range_low + 1) + range_low;
    }

    // File operations
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("File opening failed");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Ensure atomic write with file lock
    if (flock(fd, LOCK_EX) == -1) {
        perror("Failed to acquire file lock");
        close(fd);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Write data to the file in binary format
    if (write(fd, offsets, num_records * sizeof(long)) != num_records * sizeof(long) ||
        write(fd, keys, num_records * sizeof(int)) != num_records * sizeof(int) ||
        write(fd, records, num_records * sizeof(Record)) != num_records * sizeof(Record)) {

        perror("File writing failed");
        flock(fd, LOCK_UN);
        close(fd);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Release file lock and close the file
    flock(fd, LOCK_UN);
    close(fd);

    printf("Data successfully written to %s\n", filename);

    return (void *)records;  // Return pointer to records for further use if needed
}

// Function documentation:
/*
 * allocate_and_initialize - Allocates and initializes memory for two arrays of long offsets and int keys.
 *                           Additionally, allocates an array of Record structures and initializes each with a random value.
 * Parameters:
 *   num_records    : Number of elements/records to initialize.
 *   range_low      : Lower bound for generating random values.
 *   range_high     : Upper bound for generating random values.
 *   filename       : Name of the file where data is persisted in binary format.
 *
 * Returns:
 *   Pointer to the allocated array of records, or NULL if an error occurs (e.g., memory allocation failure or file I/O issues).
 *
 * Assumptions:
 * - Input range_low and range_high are valid such that range_low <= range_high.
 * - The system has sufficient resources for 1 million records.
 * - Filesystem supports locking mechanisms for concurrent access prevention.
 */

