#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>

#define MAX_RECORDS 10000000
#define MAX_TASKS 10000000

typedef struct record {
    long offset;
    int key;
    void **children;
} record_t;

typedef struct task {
    char *description;
    int priority;
    struct timeval last_update;
} task_t;

pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t tasks_mutex = PTHREAD_MUTEX_INITIALIZER;

record_t* create_record(int num_children, long range) {
    pthread_mutex_lock(&records_mutex);

    record_t *new_record = malloc(sizeof(record_t));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        pthread_mutex_unlock(&records_mutex);
        return NULL;
    }

    new_record->offset = rand() % range;
    new_record->key = rand();
    new_record->children = malloc(num_children * sizeof(void*));
    if (!new_record->children) {
        perror("Failed to allocate memory for children");
        free(new_record);
        pthread_mutex_unlock(&records_mutex);
        return NULL;
    }

    for (int i = 0; i < num_children; ++i) {
        new_record->children[i] = create_record(num_children, range);
    }

    pthread_mutex_unlock(&records_mutex);
    return new_record;
}

task_t* create_task(int description_length, int max_priority) {
    pthread_mutex_lock(&tasks_mutex);

    task_t *new_task = malloc(sizeof(task_t));
    if (!new_task) {
        perror("Failed to allocate memory for new task");
        pthread_mutex_unlock(&tasks_mutex);
        return NULL;
    }

    new_task->description = malloc(description_length + 1);
    if (!new_task->description) {
        perror("Failed to allocate memory for description");
        free(new_task);
        pthread_mutex_unlock(&tasks_mutex);
        return NULL;
    }

    for (int i = 0; i < description_length; ++i) {
        new_task->description[i] = 'A' + rand() % 26;
    }
    new_task->description[description_length] = '\0';

    new_task->priority = rand() % max_priority;
    gettimeofday(&new_task->last_update, NULL);

    pthread_mutex_unlock(&tasks_mutex);
    return new_task;
}

void save_records(record_t *records, size_t num_records, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing records");
        return;
    }

    fwrite(&num_records, sizeof(size_t), 1, file);
    pthread_mutex_lock(&records_mutex);

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].key, sizeof(int), 1, file);
        // Handle saving children pointers if necessary
    }

    pthread_mutex_unlock(&records_mutex);
    fclose(file);
}

void load_tasks(task_t **tasks, size_t *num_tasks, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading tasks");
        return;
    }

    fread(num_tasks, sizeof(size_t), 1, file);
    *tasks = malloc(*num_tasks * sizeof(task_t));
    if (!*tasks) {
        perror("Failed to allocate memory for loading tasks");
        fclose(file);
        return;
    }

    pthread_mutex_lock(&tasks_mutex);

    for (size_t i = 0; i < *num_tasks; ++i) {
        fread(&((*tasks)[i].priority), sizeof(int), 1, file);
        // Handle reading description and last_update if necessary
    }

    pthread_mutex_unlock(&tasks_mutex);
    fclose(file);
}

void add_task(task_t **tasks, size_t num_tasks, task_t *new_task) {
    pthread_mutex_lock(&tasks_mutex);

    *tasks = realloc(*tasks, (num_tasks + 1) * sizeof(task_t));
    if (!*tasks) {
        perror("Failed to reallocate memory for adding new task");
        free(new_task->description);
        free(new_task);
        pthread_mutex_unlock(&tasks_mutex);
        return;
    }

    (*tasks)[num_tasks] = *new_task;

    free(new_task->description);
    free(new_task);

    pthread_mutex_unlock(&tasks_mutex);
}

void update_task(task_t **tasks, size_t index, const char *description, int priority) {
    if (index >= MAX_TASKS) return;

    pthread_mutex_lock(&tasks_mutex);
    (*tasks)[index].priority = priority;
    free((*tasks)[index].description);

    (*tasks)[index].description = malloc(strlen(description) + 1);
    strcpy((*tasks)[index].description, description);

    gettimeofday(&(*tasks)[index].last_update, NULL);

    pthread_mutex_unlock(&tasks_mutex);
}

task_t* get_task(task_t *tasks, size_t index) {
    if (index >= MAX_TASKS) return NULL;

    pthread_mutex_lock(&tasks_mutex);
    task_t *result = malloc(sizeof(task_t));
    memcpy(result, &tasks[index], sizeof(task_t));
    pthread_mutex_unlock(&tasks_mutex);

    return result;
}

int compare_tasks(const void *a, const void *b) {
    task_t *task_a = (task_t*)a;
    task_t *task_b = (task_t*)b;

    if (task_a->priority < task_b->priority)
        return -1;
    else if (task_a->priority > task_b->priority)
        return 1;
    else
        return 0;
}

void sort_tasks(task_t *tasks, size_t num_tasks) {
    pthread_mutex_lock(&tasks_mutex);
    qsort(tasks, num_tasks, sizeof(task_t), compare_tasks);
    pthread_mutex_unlock(&tasks_mutex);
}
