typedef struct {
    int key;
    long offset;
    char* identifier;
} Record;

#define MAX_RECORDS 100000000

// Function prototypes
Record* initialize_records(size_t num_records, int min_key, int max_key, size_t (*identifier_length_distribution)(void));
int serialize_to_disk(const Record* records, size_t num_records, const char* filename);
size_t generate_identifier_length(void);

pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize random number generator
void init_random() {
    srand((unsigned int)time(NULL));
}

// Generate a random key within the specified range
int random_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to initialize records
Record* initialize_records(size_t num_records, int min_key, int max_key, size_t (*identifier_length_distribution)(void)) {
    if (num_records == 0 || identifier_length_distribution == NULL) {
        return NULL;
    }

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = random_key(min_key, max_key);
        records[i].offset = i * sizeof(Record); // Example offset logic

        size_t length = identifier_length_distribution();
        records[i].identifier = (char*)malloc(length + 1);
        if (!records[i].identifier) {
            perror("Failed to allocate memory for identifier");
            for (size_t j = 0; j < i; ++j) {
                free(records[j].identifier);
            }
            free(records);
            return NULL;
        }

        snprintf(records[i].identifier, length + 1, "ID_%zu", i); // Example ID logic
    }

    return records;
}

// Serialize records to disk in a compact binary format
int serialize_to_disk(const Record* records, size_t num_records, const char* filename) {
    if (!records || !filename) {
        return -1;
    }

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&file_lock);
    if (fwrite(records, sizeof(Record), num_records, file) != num_records) {
        perror("Failed to write records to disk");
        fclose(file);
        pthread_mutex_unlock(&file_lock);
        return -1;
    }
    pthread_mutex_unlock(&file_lock);

    fclose(file);
    return 0;
}

// Example identifier length distribution function
size_t generate_identifier_length() {
    // Simple example: identifiers are between 5 and 15 characters long
    return (rand() % 11) + 5;
}

int main() {
    init_random();

    size_t num_records = 100000; // Example number of records
    int min_key = 1, max_key = 1000;

    Record* records = initialize_records(num_records, min_key, max_key, generate_identifier_length);
    if (!records) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    const char* filename = "records.bin";
    if (serialize_to_disk(records, num_records, filename) != 0) {
        fprintf(stderr, "Failed to serialize records to disk\n");
        for (size_t i = 0; i < num_records; ++i) {
            free(records[i].identifier);
        }
        free(records);
        return EXIT_FAILURE;
    }

    // Cleanup
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].identifier);
    }
    free(records);

    return EXIT_SUCCESS;
}
