#include <time.h>
#include <sys/time.h>
#include <zlib.h> // For compression

#define MAX_RECORDS 10000000
#define TASK_DESCRIPTION_MAX_LEN 256

typedef struct {
    long offset;
    int key;
    int status_flag;
} Record;

typedef struct Task {
    char *description;
    int priority_level;
    struct timeval last_update;
    double execution_time_metric;
} Task;

typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

typedef struct {
    Task **tasks;
    size_t count;
    pthread_mutex_t lock;
} TaskManager;

// Helper function for error handling
void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to initialize records with random values
RecordManager* init_record_manager(int range_min, int range_max) {
    RecordManager *rm = malloc(sizeof(RecordManager));
    if (!rm) handle_error("Failed to allocate memory for RecordManager");

    pthread_mutex_init(&rm->lock, NULL);

    rm->records = malloc(MAX_RECORDS * sizeof(Record));
    if (!rm->records) handle_error("Failed to allocate memory for records");

    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        rm->records[i].offset = rand() % (range_max - range_min + 1) + range_min;
        rm->records[i].key = rand();
        rm->records[i].status_flag = rand() % 2; // Random binary flag
    }

    rm->count = MAX_RECORDS;

    return rm;
}

// Function to free record manager resources
void free_record_manager(RecordManager *rm) {
    if (rm) {
        pthread_mutex_destroy(&rm->lock);
        free(rm->records);
        free(rm);
    }
}

// Function to initialize tasks with random descriptions and priority levels
TaskManager* init_task_manager(size_t task_count, int desc_min_len, int desc_max_len) {
    TaskManager *tm = malloc(sizeof(TaskManager));
    if (!tm) handle_error("Failed to allocate memory for TaskManager");

    pthread_mutex_init(&tm->lock, NULL);

    tm->tasks = calloc(task_count, sizeof(Task*));
    if (!tm->tasks) handle_error("Failed to allocate memory for tasks array");

    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < task_count; ++i) {
        tm->tasks[i] = malloc(sizeof(Task));
        if (!tm->tasks[i]) handle_error("Failed to allocate memory for a Task");

        size_t desc_len = rand() % (desc_max_len - desc_min_len + 1) + desc_min_len;
        char *description = malloc(desc_len + 1);
        if (!description) handle_error("Failed to allocate memory for description");

        for (size_t j = 0; j < desc_len; ++j) {
            description[j] = 'A' + rand() % 26;
        }
        description[desc_len] = '\0';

        tm->tasks[i]->description = description;
        tm->tasks[i]->priority_level = rand();
        gettimeofday(&tm->tasks[i]->last_update, NULL);
        tm->tasks[i]->execution_time_metric = (double)rand() / RAND_MAX * 100.0; // Random float between 0 and 100
    }

    tm->count = task_count;

    return tm;
}

// Function to free task manager resources
void free_task_manager(TaskManager *tm) {
    if (!tm) return;

    for (size_t i = 0; i < tm->count; ++i) {
        if (tm->tasks[i]) {
            free(tm->tasks[i]->description);
            free(tm->tasks[i]);
        }
    }

    pthread_mutex_destroy(&tm->lock);
    free(tm->tasks);
    free(tm);
}

// Function to add a task
void add_task(TaskManager *tm, Task *new_task) {
    if (!tm || !new_task) return;

    pthread_mutex_lock(&tm->lock);

    size_t new_index = tm->count;
    tm->tasks = realloc(tm->tasks, (new_index + 1) * sizeof(Task*));
    if (!tm->tasks) handle_error("Failed to reallocate memory for tasks array");

    tm->tasks[new_index] = malloc(sizeof(Task));
    if (!tm->tasks[new_index]) handle_error("Failed to allocate memory for a new Task");

    memcpy(tm->tasks[new_index], new_task, sizeof(Task));

    ++tm->count;

    pthread_mutex_unlock(&tm->lock);
}

// Function to update a task by index
void update_task(TaskManager *tm, size_t index, Task *updated_task) {
    if (!tm || !updated_task || index >= tm->count) return;

    pthread_mutex_lock(&tm->lock);

    memcpy(tm->tasks[index], updated_task, sizeof(Task));

    gettimeofday(&tm->tasks[index]->last_update, NULL); // Update the timestamp

    pthread_mutex_unlock(&tm->lock);
}

// Function to retrieve a task by index
Task* get_task(TaskManager *tm, size_t index) {
    if (!tm || index >= tm->count) return NULL;

    Task *task = malloc(sizeof(Task));
    if (!task) handle_error("Failed to allocate memory for retrieved Task");

    pthread_mutex_lock(&tm->lock);

    memcpy(task, tm->tasks[index], sizeof(Task));

    pthread_mutex_unlock(&tm->lock);

    return task;
}

// Function to sort tasks by priority level
void sort_tasks_by_priority(TaskManager *tm) {
    if (!tm) return;

    pthread_mutex_lock(&tm->lock);

    qsort(tm->tasks, tm->count, sizeof(Task*), [](const void *a, const void *b) -> int {
        Task **taskA = (Task **) a;
        Task **taskB = (Task **) b;
        return (*taskA)->priority_level - (*taskB)->priority_level;
    });

    pthread_mutex_unlock(&tm->lock);
}

// Example function for persistence with compression
void persist_records(RecordManager *rm, const char *filename) {
    if (!rm || !filename) return;

    pthread_mutex_lock(&rm->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        handle_error("Failed to open file for writing");
    }

    z_stream stream;
    memset(&stream, 0, sizeof(stream));
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;

    if (deflateInit(&stream, Z_DEFAULT_COMPRESSION) != Z_OK) {
        fclose(file);
        handle_error("Failed to initialize compression");
    }

    char buffer[1024];
    int flush = Z_FINISH;
    do {
        stream.avail_in = 0;
        stream.next_in = NULL;

        stream.avail_out = sizeof(buffer);
        stream.next_out = (Bytef*)buffer;

        deflate(&stream, flush);

        size_t have = sizeof(buffer) - stream.avail_out;
        if (fwrite(buffer, 1, have, file) != have || ferror(file)) {
            fclose(file);
            handle_error("Failed to write compressed data");
        }
    } while (flush == Z_FINISH && stream.avail_out == 0);

    deflateEnd(&stream);
    fclose(file);

    pthread_mutex_unlock(&rm->lock);
}

// Example network synchronization function (pseudo-code, implementation would depend on specific protocol)
void sync_with_external_source(TaskManager *tm) {
    // Placeholder for actual network operations
    // Consider using protocols like HTTP/REST or WebSockets depending on reliability and speed needs

    pthread_mutex_lock(&tm->lock);

    // Fetch data from external source
    // Update tm->tasks with new data
    // Handle any race conditions, latency issues, and ensure thread safety

    pthread_mutex_unlock(&tm->lock);
}

int main() {
    // Example usage:

    RecordManager *rm = init_record_manager(0, 100); // Initialize record manager
    TaskManager *tm = init_task_manager(10, 5, 20); // Initialize task manager with 10 tasks

