```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_EVENTS 5000

typedef enum { INFO, WARNING, ERROR, DEBUG } EventType;
typedef enum { HTML, JSON, PLAIN_TEXT } OutputFormat;

typedef struct {
    time_t timestamp;
    pthread_t thread_id;
    EventType event_type;
    char metadata[256];
    char payload[1024];
} EventRecord;

typedef struct {
    EventRecord *events[MAX_EVENTS];
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} EventBuffer;

EventBuffer buffer = {.count = 0, .mutex = PTHREAD_MUTEX_INITIALIZER, .cond = PTHREAD_COND_INITIALIZER};

void log_event(EventType type, const char* metadata, const char* payload) {
    if (buffer.count >= MAX_EVENTS) return; // Handle overflow gracefully

    pthread_mutex_lock(&buffer.mutex);

    EventRecord *record = malloc(sizeof(EventRecord));
    record->timestamp = time(NULL);
    record->thread_id = pthread_self();
    record->event_type = type;
    strncpy(record->metadata, metadata, sizeof(record->metadata) - 1);
    strncpy(record->payload, payload, sizeof(record->payload) - 1);

    buffer.events[buffer.count++] = record;

    if (buffer.count == MAX_EVENTS) {
        // Truncate the oldest event
        free(buffer.events[0]);
        memmove(buffer.events, buffer.events + 1, (MAX_EVENTS - 1) * sizeof(EventRecord*));
        buffer.count--;
    }

    pthread_mutex_unlock(&buffer.mutex);
}

void cleanup() {
    for (size_t i = 0; i < buffer.count; ++i) {
        free(buffer.events[i]);
    }
    pthread_mutex_destroy(&buffer.mutex);
    pthread_cond_destroy(&buffer.cond);
}

// A sample function to simulate usage
void* event_thread_function(void *arg) {
    EventType type = *(EventType*)arg;
    log_event(type, "Sample metadata", "Sample payload");
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        EventType types[] = {INFO, WARNING, ERROR, DEBUG};
        pthread_create(&threads[i], NULL, event_thread_function, &types[i % 4]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup();
    return 0;
}
```

### Key Components
- **EventBuffer**: Manages a fixed-size buffer with `MAX_EVENTS` entries.
- **log_event()**: Handles event logging, ensuring thread safety and managing overflow by truncating the oldest events.
- **cleanup()**: Frees allocated resources to prevent memory leaks.
- **Concurrency**: Uses mutex and condition variables to manage concurrent access to the event buffer.

### Considerations
- **Thread Safety**: Mutex locks ensure that only one thread can modify the buffer at a time.
- **Memory Management**: Allocates memory dynamically for each event record, freeing it when necessary to prevent leaks.
- **Buffer Overflow**: Truncates oldest events when full to maintain size constraints.

This implementation serves as a basic starting point. For more advanced features like output formatting, persistent storage, and diagnostics, additional modules would be integrated similarly, following modular design principles for extensibility.']

