} DynamicList;

DynamicList* init_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_record(Record* record) {
    free(record);
}

void free_task(Task* task) {
    free(task->description);
    free(task);
}

static Node* create_node(void* data, size_t size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = malloc(size);
    if (!node->data) {
        free(node);
        return NULL;
    }
    memcpy(node->data, data, size);
    node->next = NULL;
    return node;
}

int add_record(DynamicList* list, Record record) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(&record, sizeof(Record));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int add_task(DynamicList* list, Task task) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(&task, sizeof(Task));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

Record* get_record_by_index(DynamicList* list, int index) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    Record* record = (Record*)current->data;
    pthread_mutex_unlock(&list->lock);
    return record;
}

Task* get_task_by_index(DynamicList* list, int index) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    Task* task = (Task*)current->data;
    pthread_mutex_unlock(&list->lock);
    return task;
}

int update_task(DynamicList* list, int index, const Task* new_task) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(current->data, new_task, sizeof(Task));
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void sort_tasks_by_priority(DynamicList* list) {
