}

// Initialize tasks with random values
Task init_random_task() {
    Task task;
    srand(time(NULL));
    int rand_length = rand() % MAX_DESCRIPTION_LENGTH + 1;
    task.description = (char*)malloc(rand_length);
    if (!task.description) {
