// Clean up resources
void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        if (current->data == NULL) continue;  // Skip if already freed

        if (((Task*)current->data)->description != NULL) {
