async fn manageUserPreferences(user_ids: Vec<u64>, devices: Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    let preferences = Arc::new(Mutex::new(Vec::with_capacity(user_ids.len() * devices.len())));

    for user_id in user_ids {
        for device in &devices {
            let mut pref_vec = preferences.lock().unwrap();

            let preference = Preference {
                user_id,
                device_id: device.clone(),
                preference_key: "default".to_string(),
                preference_value: "default_value".to_string(),
                timestamp: Utc::now().naive_utc(),
            };

            pref_vec.push(preference);
        }
    }

    // Simulate cloud service interaction
    let (tx, mut rx) = mpsc::channel(32);

    tokio::spawn(async move {
        while let Some(pref_update) = rx.recv().await {
            println!("Received update: {:?}", pref_update);
        }
    });

    // Send updates to the channel for demonstration
    if let Ok(mut lock) = preferences.lock() {
        for preference in &*lock {
            tx.send(preference.clone()).await.unwrap();
        }
    }

    // HTTP client setup
    let http_client = reqwest::Client::builder()
        .danger_accept_invalid_certs(true)
        .build()?;

    let url = "https://example.com/api";
    let response = http_client.get(url).send().await?;

    if response.status().is_success() {
        println!("Response: {:?}", response.text().await?);
    }

    // Database integration
    let conn = Connection::open("user_prefs.db")?;

    for user_id in &user_ids {
        let mut stmt = conn.prepare(
            "SELECT device_id, preference_key, preference_value FROM Preferences WHERE user_id = ?"
        )?;

        let prefs_iter = stmt.query_map(params![*user_id], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
            ))
        })?;

        for pref in prefs_iter {
            println!("Retrieved: {:?}", pref?);
        }
    }

    // Reading input and updating preferences
    let stdin = std::io::stdin();
    let mut input = String::new();

    while stdin.read_line(&mut input).unwrap() > 0 {
        if input.trim().is_empty() { break; }

        let parts: Vec<&str> = input.split(',').collect();
        if parts.len() != 2 { continue; }

        let device_id = parts[0].trim().to_string();
        let preference_key = parts[1].trim().to_string();

        // Update preferences in the database
        {
            let mut conn = Connection::open("user_prefs.db")?;
            conn.execute(
                "UPDATE Preferences SET preference_value = ? WHERE device_id = ? AND preference_key = ?",
                params![preference_key, device_id],
            )?;

            println!("Updated preference for device_id: {}, key: {}", device_id, preference_key);
        }

        input.clear();
    }

    Ok(())
}

#[tokio::main]
async fn main() {
    let user_ids = vec![1, 2, 3];
    let devices = vec!["device_1".to_string(), "device_2".to_string()];

    if let Err(e) = manageUserPreferences(user_ids, devices).await {
        eprintln!("Error: {}", e);
    }
}
