Record* get_record(DynamicArray *array, size_t index);
void serialize_array(const DynamicArray *array, const char *filename);
DynamicArray* deserialize_array(const char *filename);
void free_dynamic_array(DynamicArray *array);

// Function definitions
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    // Initialize records with random values.
    for (size_t i = 0; i < initial_capacity; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) continue;

        record->value = rand() % 100;                // Random int value
        record->offset = (long *)(malloc(sizeof(long)));
        record->key = (int *)(malloc(sizeof(int)));

        if (record->offset && record->key) {
            *record->offset = (long)i + 1;          // Non-zero offset
            *record->key = (int)(i + 1);            // Non-zero key
            array->records[i] = record;
            array->count++;
        } else {
            free(record);
        }
    }

    return array;
}

int insert_record(DynamicArray *array, Record *record) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record **new_records = (Record **)realloc(array->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Allocation failure
        }

        memset(new_records + array->capacity, 0, (new_capacity - array->capacity) * sizeof(Record *));
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->records[array->count++] = record;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int delete_record(DynamicArray *array, size_t index) {
    if (index >= array->count) return -1; // Index out of bounds

    pthread_mutex_lock(&array->mutex);

    free(array->records[index]->offset);
    free(array->records[index]->key);
    free(array->records[index]);

    memmove(&array->records[index], &array->records[index + 1],
            (array->count - index - 1) * sizeof(Record *));
    array->count--;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

Record* get_record(DynamicArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->mutex);
    Record *record = array->records[index];
    pthread_mutex_unlock(&array->mutex);

    return record;
}

void serialize_array(const DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t *)&array->mutex);

    fwrite(&(array->count), sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        Record *record = array->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(record->offset, sizeof(long), 1, file);
        fwrite(record->key, sizeof(int), 1, file);
    }

    pthread_mutex_unlock((pthread_mutex_t *)&array->mutex);
    fclose(file);
}

DynamicArray* deserialize_array(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        fclose(file);
        return NULL;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    array->records = (Record **)calloc(count, sizeof(Record *));
    if (!array->records) {
        free(array);
        fclose(file);
        return NULL;
    }

    array->capacity = count;
    array->count = count;

    for (size_t i = 0; i < count; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) continue;

        fread(&record->value, sizeof(int), 1, file);
        record->offset = (long *)(malloc(sizeof(long)));
        record->key = (int *)(malloc(sizeof(int)));

        if (record->offset && record->key) {
            fread(record->offset, sizeof(long), 1, file);
            fread(record->key, sizeof(int), 1, file);
            array->records[i] = record;
        } else {
            free(record);
        }
    }

    pthread_mutex_init(&array->mutex, NULL);
    fclose(file);

    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i]->offset);
        free(array->records[i]->key);
        free(array->records[i]);
    }

    free(array->records);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
```

**Design Decisions:**

1. **Thread Safety:** The use of `pthread_mutex_t` ensures thread-safe access to the dynamic array, which is critical for concurrent modifications and reads.
2. **Dynamic Memory Management:** Carefully manage memory allocations using `malloc`, `calloc`, and `realloc`. Free resources appropriately in case of errors or during deallocation.
3. **Efficiency Considerations:** By doubling the capacity when resizing, we reduce the frequency of costly reallocations, optimizing performance for insert operations.
4. **Error Handling:** Graceful handling of allocation failures with immediate cleanup to avoid memory leaks.
5. **Serialization/Deserialization:** Implemented file-based serialization/deserialization to persist and restore data efficiently, ensuring correct synchronization during these operations.

This implementation aims at balancing simplicity, efficiency, and thread safety while managing a dynamic array of records in a high-performance setting.']

