const char predefined_chars[] = "abcdefghijklmnopqrstuvwxyz";

typedef struct Node {
    char *value;
    float *data;
    struct Node *next;
} Node;

Node* create_node(size_t char_len, float min_float, float max_float) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for node");
        return NULL;
    }

    // Allocate and initialize char value
    new_node->value = (char*)malloc(char_len + 1);
    if (!new_node->value) {
        free(new_node);
        log_error("Memory allocation failed for char value");
        return NULL;
    }
    for (size_t i = 0; i < char_len; ++i) {
        new_node->value[i] = predefined_chars[rand() % CHAR_SET_SIZE];
    }
    new_node->value[char_len] = '\0';

    // Allocate and initialize float data
    new_node->data = (float*)malloc(sizeof(float));
    if (!new_node->data) {
        free(new_node->value);
        free(new_node);
        log_error("Memory allocation failed for float data");
        return NULL;
    }
    *new_node->data = random_float(min_float, max_float);

    new_node->next = NULL;
    return new_node;
}

Node* initialize_list(size_t num_nodes, size_t char_len, float min_float, float max_float) {
    if (num_nodes > MAX_NODES) {
        log_error("Number of nodes exceeds maximum limit");
        return NULL;
    }

    Node* head = create_node(char_len, min_float, max_float);
    if (!head) return NULL;

    Node* current = head;
    for (size_t i = 1; i < num_nodes; ++i) {
        Node* new_node = create_node(char_len, min_float, max_float);
        if (!new_node) {
            // Free all previously allocated nodes
            while (current != NULL) {
                Node* next = current->next;
                free(current->value);
                free(current->data);
                free(current);
                current = next;
            }
            return NULL;
        }
        current->next = new_node;
        current = new_node;
    }

    return head;
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Char: %s, Float: %.2f\n", current->value, *current->data);
        current = current->next;
    }
}

Node* insert_node_at_end(Node** head, size_t char_len, float min_float, float max_float) {
    Node* new_node = create_node(char_len, min_float, max_float);
    if (!new_node) return NULL;

    if (*head == NULL) {
        *head = new_node;
        return *head;
    }

    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    return new_node;
}

Node* get_node_by_index(Node* head, size_t index) {
    Node* current = head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }
    return current;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->value);
        free(current->data);
        free(current);
        current = next;
    }
}
