typedef struct {
    Session* head;
    pthread_mutex_t lock;
} SessionList;

SessionList* initialize_sessions(int num_sessions) {
    if (num_sessions <= 0) return NULL;

    SessionList* list = malloc(sizeof(SessionList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    for (int i = 0; i < num_sessions; ++i) {
        Session* new_session = malloc(sizeof(Session));
        if (!new_session) {
            destroy_sessions(list);
            return NULL;
        }

        new_session->id = rand(); // Assume IDs are generated randomly
        new_session->timestamp = time(NULL);
        strcpy(new_session->status, "active");
        new_session->next = list->head;
        list->head = new_session;
    }

    return list;
}

void destroy_sessions(SessionList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Session *current = list->head;
    while (current != NULL) {
        Session* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Session* find_session_by_id(SessionList* list, int id) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    Session *current = list->head;
    while (current != NULL) {
        if (current->id == id) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void modify_session_status(SessionList* list, int id, const char *new_status) {
    if (!list || !new_status) return;

    Session* session = find_session_by_id(list, id);
    if (session) {
        pthread_mutex_lock(&list->lock);

        strncpy(session->status, new_status, sizeof(session->status) - 1);
        session->status[sizeof(session->status) - 1] = '\0';

        pthread_mutex_unlock(&list->lock);
    }
}

void iterate_sessions(SessionList* list, void (*callback)(Session*)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);

    Session *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_sessions(SessionList* list, const char* filename) {
    if (!list || !filename) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Session *current = list->head;
    while (current != NULL) {
        fwrite(current, sizeof(Session), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize_sessions(SessionList* list, const char* filename) {
    if (!list || !filename) return;

    FILE *file = fopen(filename, "rb");
    if (!file) return;

    destroy_sessions(list);

    Session session;
    while (fread(&session, sizeof(Session), 1, file)) {
        // Reconstruct the linked list from deserialized data
        Session* new_session = malloc(sizeof(Session));
        if (!new_session) break;

        *new_session = session;
        new_session->next = list->head;
        list->head = new_session;
    }

    fclose(file);
}

