#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define MAX_INT_VALUE 1000
#define NON_ZERO_OFFSET 1
#define NON_ZERO_KEY 1

typedef struct {
    int value;
    long *offset;
    int *key;
    time_t last_accessed;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} dynamic_array;

// Initialize the dynamic array
void init_dynamic_array(dynamic_array *da, size_t initial_capacity) {
    da->records = malloc(initial_capacity * sizeof(record));
    if (!da->records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    da->capacity = initial_capacity;
    da->size = 0;

    pthread_rwlock_init(&da->lock, NULL);

    for (size_t i = 0; i < da->capacity; ++i) {
        da->records[i].value = rand() % MAX_INT_VALUE;
        da->records[i].offset = malloc(sizeof(long));
        if (!da->records[i].offset) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *da->records[i].offset = NON_ZERO_OFFSET;

        da->records[i].key = malloc(sizeof(int));
        if (!da->records[i].key) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *da->records[i].key = NON_ZERO_KEY;

        da->records[i].last_accessed = time(NULL);
    }
}

// Resize the dynamic array
void resize_dynamic_array(dynamic_array *da, size_t new_capacity) {
    pthread_rwlock_wrlock(&da->lock);

    record *new_records = realloc(da->records, new_capacity * sizeof(record));
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    da->records = new_records;
    da->capacity = new_capacity;

    for (size_t i = da->size; i < da->capacity; ++i) {
        da->records[i].value = rand() % MAX_INT_VALUE;
        da->records[i].offset = malloc(sizeof(long));
        if (!da->records[i].offset) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *da->records[i].offset = NON_ZERO_OFFSET;

        da->records[i].key = malloc(sizeof(int));
        if (!da->records[i].key) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *da->records[i].key = NON_ZERO_KEY;

        da->records[i].last_accessed = time(NULL);
    }

    pthread_rwlock_unlock(&da->lock);
}

// Insert a new record
void insert_record(dynamic_array *da, int value, long offset, int key) {
    pthread_rwlock_wrlock(&da->lock);

    if (da->size >= da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
    }

    da->records[da->size].value = value;
    da->records[da->size].offset = malloc(sizeof(long));
    if (!da->records[da->size].offset) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    *(da->records[da->size].offset) = offset;

    da->records[da->size].key = malloc(sizeof(int));
    if (!da->records[da->size].key) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    *(da->records[da->size].key) = key;

    da->records[da->size].last_accessed = time(NULL);

    ++da->size;

    pthread_rwlock_unlock(&da->lock);
}

// Delete a record by index
void delete_record(dynamic_array *da, size_t index) {
    pthread_rwlock_wrlock(&da->lock);

    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_rwlock_unlock(&da->lock);
        return;
    }

    free(da->records[index].offset);
    free(da->records[index].key);

    for (size_t i = index; i < da->size - 1; ++i) {
        da->records[i] = da->records[i + 1];
    }

    --da->size;

    pthread_rwlock_unlock(&da->lock);
}

// Retrieve a record by index
record* get_record(const dynamic_array *da, size_t index) {
    pthread_rwlock_rdlock(&da->lock);

    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_rwlock_unlock(&da->lock);
        return NULL;
    }

    da->records[index].last_accessed = time(NULL);

    record *result = malloc(sizeof(record));
    *result = da->records[index];

    pthread_rwlock_unlock(&da->lock);
    return result;
}

// Modify a specific record's value
void modify_record(dynamic_array *da, size_t index, int new_value) {
    pthread_rwlock_wrlock(&da->lock);

    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_rwlock_unlock(&da->lock);
        return;
    }

    da->records[index].value = new_value;
    da->records[index].last_accessed = time(NULL);

    pthread_rwlock_unlock(&da->lock);
}

// Iterate over all records
void iterate_records(dynamic_array *da, void (*callback)(record *)) {
    pthread_rwlock_rdlock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        callback(&(da->records[i]));
    }

    pthread_rwlock_unlock(&da->lock);
}

// Serialize the dynamic array to a binary file
void serialize_dynamic_array(const dynamic_array *da, const char *filename) {
    pthread_rwlock_rdlock(&da->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_rwlock_unlock(&da->lock);
        return;
    }

    fwrite(&(da->size), sizeof(size_t), 1, file);
    fwrite(da->records, sizeof(record), da->size, file);

    fclose(file);

    pthread_rwlock_unlock(&da->lock);
}

// Deserialize the dynamic array from a binary file
void deserialize_dynamic_array(dynamic_array *da, const char *filename) {
    pthread_rwlock_wrlock(&da->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        pthread_rwlock_unlock(&da->lock);
        return;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    if (size > da->capacity) {
        resize_dynamic_array(da, size);
    }

    fread(da->records, sizeof(record), size, file);
    da->size = size;

    fclose(file);

    pthread_rwlock_unlock(&da->lock);
}

// Free the dynamic array
void free_dynamic_array(dynamic_array *da) {
    pthread_rwlock_wrlock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        free(da->records[i].offset);
        free(da->records[i].key);
    }

    free(da->records);

    pthread_rwlock_unlock(&da->lock);
    pthread_rwlock_destroy(&da->lock);
}

// Example callback function for iteration
void print_record(record *r) {
    printf("Value: %d, Offset: %ld, Key: %d\n", r->value, *(r->offset), *(r->key));
}
