```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

// Logging function
void log_event(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

// Initialize a new RecordManager
RecordManager* initialize_record_manager(size_t initial_capacity) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) {
        log_event("ERROR", "Failed to allocate memory for RecordManager.");
        return NULL;
    }

    manager->records = calloc(initial_capacity, sizeof(record *));
    if (!manager->records) {
        free(manager);
        log_event("ERROR", "Failed to allocate memory for records array.");
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Add a record
void add_record(RecordManager *manager, int min_value, int max_value) {
    if (!manager || manager->count >= manager->capacity) {
        log_event("ERROR", "Failed to add record: invalid state or capacity reached.");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        log_event("ERROR", "Memory allocation failed for new record.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    new_record->value = rand() % (max_value - min_value + 1) + min_value;

    new_record->offset = malloc(sizeof(long));
    if (!new_record->offset) {
        log_event("ERROR", "Memory allocation failed for offset.");
        free(new_record);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    new_record->key = malloc(sizeof(int));
    if (!new_record->key) {
        log_event("ERROR", "Memory allocation failed for key.");
        free(new_record->offset);
        free(new_record);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    *new_record->offset = 0; // Placeholder initialization
    *new_record->key = 0;    // Placeholder initialization

    manager->records[manager->count++] = new_record;

    log_event("INFO", "Record added successfully.");
    pthread_mutex_unlock(&manager->lock);
}

// Get a record by index
record* get_record(RecordManager *manager, size_t index) {
    if (!manager || index >= manager->count) {
        log_event("ERROR", "Invalid access to record.");
        return NULL;
    }

    return manager->records[index];
}

// Helper function to find the maximum value in records
int find_max_value(const RecordManager *manager) {
    if (!manager || manager->count == 0) {
        log_event("ERROR", "No records available for processing.");
        return -1; // Error case, could be customized
    }

    int max_value = manager->records[0]->value;
    for (size_t i = 1; i < manager->count; ++i) {
        if (manager->records[i]->value > max_value) {
            max_value = manager->records[i]->value;
        }
    }

    return max_value;
}

// Cleanup function
void cleanup_record_manager(RecordManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->offset);
        free(manager->records[i]->key);
        free(manager->records[i]);
    }

    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_event("INFO", "RecordManager cleaned up.");
}

// Example of a callback function for connection lifecycle management
void on_connection_state_change(const char *state) {
    log_event("INFO", state);
}

int main() {
    srand(time(NULL));

    RecordManager *manager = initialize_record_manager(10);
    if (!manager) return EXIT_FAILURE;

    for (size_t i = 0; i < 10; ++i) {
        add_record(manager, 1, 100);
    }

    int max_value = find_max_value(manager);
    printf("Max Value: %d\n", max_value);

    record *r = get_record(manager, 5);
    if (r) {
        printf("Record at index 5 has value: %d\n", r->value);
    }

    on_connection_state_change("Connection Established");

    cleanup_record_manager(manager);

    return EXIT_SUCCESS;
}
