void initializeAndManageRecords(int num_records, int min_val, int max_val) {
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)calloc(num_records, sizeof(record));
    int *list_values = NULL;
