        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Sort the integer list in descending order
    sortIntArrayDescending(list_values, list_size);

    // Calculate and print median
    double median = calculateMedian(list_values, list_size);
    printf("Median: %.2f\n", median);

    // Calculate and print standard deviation
    double std_dev = calculateStandardDeviation(list_values, list_size, median);
    printf("Standard Deviation: %.2f\n", std_dev);

    // Initialize records with random values and pointers
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 100;
        records[i].value = min_val + rand() % (max_val - min_val + 1);
        if (list_size > 0 && i < list_size) {
            records[i].int_list_value_ptr = &list_values[i];
        } else {
            records[i].int_list_value_ptr = NULL;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(list_values);
    free(records);
}

// Function to get a specific record by index
