    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    return records[index];
}

// Function to update the value of a record
void updateRecordValue(record *records, int index, int newValue) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    records[index].value = newValue;
}

// Function to insert a new record at a specified position
void insertRecordAtPosition(record **records, int position, int value, long offset, int key, int list_value, int *num_records) {
    if (position < 0 || position > *num_records) {
        fprintf(stderr, "Invalid insertion position\n");
        return;
    }

    record *new_records = realloc(*records, (*num_records + 1) * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Memory allocation failed during insert\n");
        return;
    }

    // Shift existing records to make space for the new one
    memmove(&new_records[position + 1], &new_records[position], (*num_records - position) * sizeof(record));

    // Insert the new record
    new_records[position].value = value;
    new_records[position].offset_ptr = &offset;
    new_records[position].key_ptr = &key;
    if (list_value != 0) {  // Assuming list_value is non-zero for valid input
        int *new_list_values = realloc(list_values, (*num_records + 1) * sizeof(int));
        if (!new_list_values) {
            fprintf(stderr, "Memory allocation failed during insert\n");
            free(new_records);
            return;
        }
        memmove(&new_list_values[position + 1], &list_values[position], (*num_records - position) * sizeof(int));
        new_list_values[position] = list_value;
        list_values = new_list_values;
        new_records[position].int_list_value_ptr = &list_values[position];
    }

    *records = new_records;
    (*num_records)++;
}

// Function to read integers from standard input
int* readIntegersFromStdin(int *size) {
    int capacity = 10;
    int *array = malloc(capacity * sizeof(int));
    if (!array) return NULL;

    int value;
    *size = 0;
    while (scanf("%d", &value) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            int *new_array = realloc(array, capacity * sizeof(int));
            if (!new_array) {
                free(array);
                return NULL;
            }
            array = new_array;
        }
        array[(*size)++] = value;
    }

    return array;
}

// Function to sort an integer array in descending order
void sortIntArrayDescending(int *array, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (array[j] < array[j + 1]) {
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

// Function to calculate the median of an integer array
double calculateMedian(const int *array, int size) {
    if (size % 2 == 0) {
        return (array[size / 2 - 1] + array[size / 2]) / 2.0;
    } else {
        return array[size / 2];
    }
}

// Function to calculate the standard deviation of an integer array
double calculateStandardDeviation(const int *array, int size, double median) {
    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += pow(array[i] - median, 2);
    }
    return sqrt(sum / size);
}
