#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Record structure definition
typedef struct {
    int value;
    long *offset;
    int *key;
} record;

// Dynamic array of records with metadata for management
typedef struct {
    record **records;
    size_t count;
    size_t capacity;
    size_t max_memory_size;
    size_t current_memory_usage;
    pthread_mutex_t lock;
    unsigned long allocation_count;
    unsigned long deallocation_count;
} dynamic_array;

// Function declarations
void initDynamicArray(dynamic_array *da, size_t max_memory_size);
int addRecord(dynamic_array *da, int min_value, int max_value);
int removeRecordByIndex(dynamic_array *da, size_t index);
record* getRecordByIndex(dynamic_array *da, size_t index);
void batchAddRecords(dynamic_array *da, int num_records, int min_value, int max_value);
void batchRemoveRecords(dynamic_array *da, size_t start_index, size_t count);
void iterateAndPerform(dynamic_array *da, void (*operation)(record *));
int exportToFile(const dynamic_array *da, const char *filename);
void logAllocationsDeallocations(const dynamic_array *da);

// Initialize the dynamic array
void initDynamicArray(dynamic_array *da, size_t max_memory_size) {
    da->records = NULL;
    da->count = 0;
    da->capacity = 0;
    da->max_memory_size = max_memory_size;
    da->current_memory_usage = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->allocation_count = 0;
    da->deallocation_count = 0;

    // Allocate initial memory for records
    if (da->capacity == 0) {
        addRecord(da, 1, 100); // Initial allocation with default values
    }
}

// Add a record to the dynamic array
int addRecord(dynamic_array *da, int min_value, int max_value) {
    pthread_mutex_lock(&da->lock);

    if (da->current_memory_usage + sizeof(record *) > da->max_memory_size) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Memory limit reached
    }

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 4 : da->capacity * 2;
        record **new_records = realloc(da->records, new_capacity * sizeof(record *));
        if (!new_records) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Reallocation failed
        }
        memset(new_records + da->capacity, 0, (new_capacity - da->capacity) * sizeof(record *));
        da->records = new_records;
        da->capacity = new_capacity;
    }

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Allocation failed
    }
    new_record->value = rand() % (max_value - min_value + 1) + min_value;
    new_record->offset = malloc(sizeof(long));
    new_record->key = malloc(sizeof(int));

    if (!new_record->offset || !new_record->key) {
        free(new_record);
        pthread_mutex_unlock(&da->lock);
        return -1; // Allocation failed
    }

    da->records[da->count] = new_record;
    da->current_memory_usage += sizeof(record *) + sizeof(record);
    da->allocation_count++;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Remove a record by index
int removeRecordByIndex(dynamic_array *da, size_t index) {
    pthread_mutex_lock(&da->lock);

    if (index >= da->count) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid index
    }

    free(da->records[index]->offset);
    free(da->records[index]->key);
    free(da->records[index]);

    memmove(&da->records[index], &da->records[index + 1],
            (da->count - index - 1) * sizeof(record *));
    da->count--;
    da->current_memory_usage -= sizeof(record *) + sizeof(record);

    pthread_mutex_unlock(&da->lock);
    da->deallocation_count++;
    return 0;
}

// Get a record by index
record* getRecordByIndex(dynamic_array *da, size_t index) {
    if (index < da->count) {
        return da->records[index];
    }
    return NULL; // Invalid index
}

// Batch add records
void batchAddRecords(dynamic_array *da, int num_records, int min_value, int max_value) {
    for (int i = 0; i < num_records; ++i) {
        addRecord(da, min_value, max_value);
    }
}

// Batch remove records
void batchRemoveRecords(dynamic_array *da, size_t start_index, size_t count) {
    for (size_t i = 0; i < count && start_index + i < da->count; ++i) {
        removeRecordByIndex(da, start_index);
    }
}

// Iterate and perform an operation on each record
void iterateAndPerform(dynamic_array *da, void (*operation)(record *)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        if (operation) {
            operation(da->records[i]);
        }
    }

    pthread_mutex_unlock(&da->lock);
}

// Export records to a file
int exportToFile(const dynamic_array *da, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&da->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < da->count; ++i) {
        record *rec = da->records[i];
        fwrite(&rec->value, sizeof(int), 1, file);
        long offset = *(rec->offset);
        fwrite(&offset, sizeof(long), 1, file);
        int key = *(rec->key);
        fwrite(&key, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

// Log allocations and deallocations
void logAllocationsDeallocations(const dynamic_array *da) {
    printf("Total Allocations: %lu\n", da->allocation_count);
    printf("Total Deallocation: %lu\n", da->deallocation_count);
}

// Example operation for iterating records
void updateRecordValue(record *rec) {
    if (rec) {
        rec->value += 1;
    }
}

int main() {
    srand(time(NULL));
    dynamic_array da;
    initDynamicArray(&da, 1024 * 1024); // Initialize with 1MB memory limit

    addRecord(&da, 10, 20);
    addRecord(&da, 30, 40);

    iterateAndPerform(&da, updateRecordValue);

    exportToFile(&da, "records.dat");

    logAllocationsDeallocations(&da);

    // Clean up
    for (size_t i = 0; i < da.count; ++i) {
        removeRecordByIndex(&da, 0);
    }

    free(da.records);
    pthread_mutex_destroy(&da.lock);

    return 0;
}
