['Below is a C implementation for managing memory for arrays of `long` offset values, `int` keys, and dynamically allocated `record` structures. The function supports dynamic resizing, efficient lookups by key, concurrent access, and robust error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    int *keys; // Hash table for fast key-based lookup
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
} DataManager;

// Function to initialize the data manager with a given initial capacity
DataManager* init_data_manager(size_t initial_capacity) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    dm->keys = (int *)calloc(initial_capacity, sizeof(int)); // Simple hash table
    pthread_mutex_init(&dm->mutex, NULL);
    dm->capacity = initial_capacity;
    dm->count = 0;

    return dm;
}

// Helper function to resize the data structures when needed
void resize_data_manager(DataManager *dm) {
    size_t new_capacity = dm->capacity * 2;
    Record **new_records = (Record **)realloc(dm->records, new_capacity * sizeof(Record *));
    int *new_keys = (int *)realloc(dm->keys, new_capacity * sizeof(int));

    if (!new_records || !new_keys) {
        free(new_records);
        free(new_keys);
        return; // Handle failure gracefully
    }

    dm->records = new_records;
    memset(new_records + dm->capacity, 0, (new_capacity - dm->capacity) * sizeof(Record *));
    dm->keys = new_keys;
    memset(new_keys + dm->capacity, 0, (new_capacity - dm->capacity) * sizeof(int));

    dm->capacity = new_capacity;
}

// Function to add a record
void add_record(DataManager *dm, int key, long offset, int value) {
    pthread_mutex_lock(&dm->mutex);

    if (dm->count == dm->capacity) {
        resize_data_manager(dm);
    }

    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&dm->mutex);
        return; // Handle allocation failure
    }

    new_record->value = value;
    new_record->offset = malloc(sizeof(long));
    if (!new_record->offset) {
        free(new_record); 
        pthread_mutex_unlock(&dm->mutex);
        return; // Handle allocation failure
    }
    *new_record->offset = offset;

    new_record->key = malloc(sizeof(int));
    if (!new_record->key) {
        free(new_record->offset);
        free(new_record);
        pthread_mutex_unlock(&dm->mutex);
        return; // Handle allocation failure
    }
    *new_record->key = key;

    int index = key % dm->capacity;
    while (dm->keys[index] != 0 && dm->keys[index] != key) {
        index = (index + 1) % dm->capacity; // Linear probing for collision resolution
    }

    if (dm->records[index]) free(dm->records[index]); // Free existing record at this index

    dm->records[index] = new_record;
    dm->keys[index] = key;

    dm->count++;

    pthread_mutex_unlock(&dm->mutex);
}

// Function to retrieve a record by its index
Record* get_record_by_index(DataManager *dm, size_t index) {
    if (index >= dm->count) return NULL;

    pthread_mutex_lock(&dm->mutex);
    Record *record = dm->records[index];
    pthread_mutex_unlock(&dm->mutex);

    return record;
}

// Function to retrieve a record by its key
Record* get_record_by_key(DataManager *dm, int key) {
    pthread_mutex_lock(&dm->mutex);

    size_t index = key % dm->capacity;
    while (dm->keys[index] != 0 && dm->keys[index] != key) {
        index = (index + 1) % dm->capacity; // Linear probing
    }

    Record *record = NULL;
    if (dm->keys[index] == key) {
        record = dm->records[index];
    }

    pthread_mutex_unlock(&dm->mutex);
    return record;
}

// Function to free resources allocated by the data manager
void free_data_manager(DataManager *dm) {
    for (size_t i = 0; i < dm->capacity; ++i) {
        if (dm->records[i]) {
            free(dm->records[i]->offset);
            free(dm->records[i]->key);
            free(dm->records[i]);
        }
    }
    free(dm->records);
    free(dm->keys);
    pthread_mutex_destroy(&dm->mutex);
    free(dm);
}

// Main function for demonstration purposes
int main() {
    DataManager *dm = init_data_manager(10);

    // Simulate adding records (e.g., from an API)
    add_record(dm, 1, 100L, 200);
    add_record(dm, 2, 101L, 201);

    Record *record = get_record_by_key(dm, 1);
    if (record) {
        printf("Record: %d\n", record->value);
    }

    free_data_manager(dm);

    return 0;
}
