#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

// Union-Find data structure with path compression
int find(int *parent, int i) {
    if (parent[i] != i)
        parent[i] = find(parent, parent[i]);
    return parent[i];
}

void union_sets(int *parent, int *rank, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

// Dynamic array resizing
Record *resize_record_array(Record *records, size_t *capacity) {
    size_t new_capacity = (*capacity == 0) ? 1 : (*capacity) * 2;
    Record *new_records = realloc(records, new_capacity * sizeof(Record));
    if (!new_records) {
        free(records);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *capacity = new_capacity;
    return new_records;
}

int manage_records(long *offsets, int *keys, size_t num_records, Record ***records_out) {
    size_t capacity = 0;
    Record *records = NULL;

    // Initialize Union-Find structure
    int *parent = malloc(num_records * sizeof(int));
    int *rank = calloc(num_records, sizeof(int));

    if (!parent || !rank) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records);
        free(parent);
        free(rank);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        parent[i] = i;
    }

    clock_t start_time = clock();

    // Initialize records array with dynamic resizing
    for (size_t i = 0; i < num_records; ++i) {
        if (capacity == 0 || capacity <= i) {
            records = resize_record_array(records, &capacity);
        }
        records[i].value = rand(); // Example initialization
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];

        for (size_t j = i + 1; j < num_records; ++j) {
            if (find(parent, i) != find(parent, j)) {
                union_sets(parent, rank, i, j);
            }
        }
    }

    // Count disjoint sets
    int *set_count = calloc(num_records, sizeof(int));
    for (size_t i = 0; i < num_records; ++i) {
        set_count[find(parent, i)]++;
    }

    int disjoint_pairs = 0;
    for (size_t i = 0; i < num_records; ++i) {
        if (set_count[i] > 1) {
            disjoint_pairs += set_count[i] - 1;
        }
    }

    clock_t end_time = clock();
    double time_taken_ms = ((double)(end_time - start_time)) * 1000.0 / CLOCKS_PER_SEC;

    printf("Number of disjoint pairs: %d\n", disjoint_pairs);
    printf("Time taken (ms): %.2f\n", time_taken_ms);

    free(set_count);
    free(parent);
    free(rank);

    *records_out = records;
    return disjoint_pairs;
}

int main() {
    size_t num_records = 1000;
    long offsets[num_records];
    int keys[num_records];

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
    }

    Record *records = NULL;
    manage_records(offsets, keys, num_records, &records);

    // Cleanup
    free(records);
    return 0;
}
