def read_compressed_file(file_path):
    if file_path.endswith('.gz'):
        return gzip.open(file_path, 'rt')
    elif file_path.endswith('.bz2'):
        return bz2.open(file_path, 'rt')
    else:
        return open(file_path, 'r')

def calculate_checksum(data):
    hasher = hashlib.md5()
    hasher.update(data.encode('utf-8'))
    return hasher.hexdigest()

def log_error(message):
    logging.error(message)

def notify_api(total_events, latest_sequence_number):
    retries = 3
    delay = 2

    for attempt in range(retries):
        try:
            response = requests.post('https://api.example.com/notify', json={
                'total_events': total_events,
                'latest_sequence_number': latest_sequence_number
            })
            if response.status_code == 200:
                logging.info("API notification successful.")
                return
        except Exception as e:
            log_error(f"API notification failed: {e}")

        time.sleep(delay * (2 ** attempt))

def process_log_file(file_path, expected_range, filter_criteria=None):
    try:
        with read_compressed_file(file_path) as file:
            fcntl.flock(file.fileno(), fcntl.LOCK_SH)

            events = []
            for line in file:
                timestamp, identifier, sequence_number = parse_line(line)
                if filter_criteria and not matches_filter(timestamp, identifier, sequence_number, filter_criteria):
                    continue

                events.append((timestamp, identifier, int(sequence_number), line))

            events.sort(key=lambda x: (-x[2], x[1]))

            total_events = 0
            latest_sequence_number = -1

            with TemporaryFile() as temp_file:
                for timestamp, identifier, sequence_number, data in events:
                    checksum = calculate_checksum(data)
                    if not verify_checksum(checksum):
                        log_error(f"Checksum mismatch for line: {data}")
                        continue

                    temp_file.write(data.encode('utf-8'))
                    total_events += 1
                    latest_sequence_number = max(latest_sequence_number, sequence_number)

                temp_file.seek(0)

                if latest_sequence_number < expected_range[0] or latest_sequence_number > expected_range[1]:
                    log_error("Latest sequence number out of range.")

                with open('processed_log.txt', 'wb') as output_file:
                    while True:
                        chunk = temp_file.read(1024 * 1024)
                        if not chunk:
                            break
                        output_file.write(chunk)

            notify_api(total_events, latest_sequence_number)
    except Exception as e:
        log_error(f"Error processing file: {e}")

def parse_line(line):
    parts = line.strip().split(',')
    return parts[0], parts[1], parts[2]

def matches_filter(timestamp, identifier, sequence_number, filter_criteria):
    # Implement filtering logic based on criteria
    return True

def verify_checksum(checksum):
