typedef struct {
    int value;
    long *offsetPtr;
    int *keyPtr;
    unsigned long timestamp;
} Record;

// External logging function placeholder
void log_error(const char *message) {
    // Assume this logs errors to an external system
    fprintf(stderr, "%s\n", message);
}

// Function prototypes
void initialize_arrays(long **offsetArray, int **keysArray, Record ***recordsArray, unsigned long **eventTimestamps, size_t initialCapacity);
int add_record(Record ***recordsArray, unsigned long **eventTimestamps, long *offset, int key, Record record, size_t *recordCount, size_t *capacity, size_t *timestampCapacity);
void resize_array(void **array, size_t oldCapacity, size_t newCapacity, size_t elementSize);
Record* get_record_by_index(Record ***recordsArray, size_t index, size_t count);
Record** get_records_in_time_window(unsigned long **eventTimestamps, Record ***recordsArray, unsigned long start, unsigned long end, size_t recordCount);

void initialize_arrays(long **offsetArray, int **keysArray, Record ***recordsArray, unsigned long **eventTimestamps, size_t initialCapacity) {
    *offsetArray = malloc(initialCapacity * sizeof(long));
    if (*offsetArray == NULL) {
        log_error("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    *keysArray = malloc(initialCapacity * sizeof(int));
    if (*keysArray == NULL) {
        free(*offsetArray);
        log_error("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    *recordsArray = malloc(sizeof(Record *) * initialCapacity);
    if (*recordsArray == NULL) {
        free(*offsetArray);
        free(*keysArray);
        log_error("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }

    *eventTimestamps = malloc(initialCapacity * sizeof(unsigned long));
    if (*eventTimestamps == NULL) {
        free(*offsetArray);
        free(*keysArray);
        free(*recordsArray);
        log_error("Failed to allocate memory for event timestamps");
        exit(EXIT_FAILURE);
    }
}

int add_record(Record ***recordsArray, unsigned long **eventTimestamps, long *offset, int key, Record record, size_t *recordCount, size_t *capacity, size_t *timestampCapacity) {
    if (*recordCount >= *capacity) {
        size_t newCapacity = *capacity > 0 ? *capacity * 2 : 1;
        resize_array((void **)recordsArray, *capacity, newCapacity, sizeof(Record *));

        *capacity = newCapacity;
    }

    if (*recordCount >= *timestampCapacity) {
        size_t newTimestampCapacity = *timestampCapacity > 0 ? *timestampCapacity * 2 : 1;
        resize_array((void **)eventTimestamps, *timestampCapacity, newTimestampCapacity, sizeof(unsigned long));

        *timestampCapacity = newTimestampCapacity;
    }

    record.offsetPtr = &offset[*recordCount];
    record.keyPtr = &key[*recordCount];

    (*recordsArray)[*recordCount] = malloc(sizeof(Record));
    if ((*recordsArray)[*recordCount] == NULL) {
        log_error("Failed to allocate memory for a new record");
        return -1;
    }

    memcpy((*recordsArray)[*recordCount], &record, sizeof(Record));

    (*eventTimestamps)[*recordCount] = record.timestamp;

    (*recordCount)++;

    return 0; // Success
}

void resize_array(void **array, size_t oldCapacity, size_t newCapacity, size_t elementSize) {
    void *newArray = realloc(*array, newCapacity * elementSize);
    if (newArray == NULL) {
        log_error("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = newArray;
}

Record* get_record_by_index(Record ***recordsArray, size_t index, size_t count) {
    if (index >= count) {
        return NULL; // Out-of-bounds access
    }

    return (*recordsArray)[index];
}

Record** get_records_in_time_window(unsigned long **eventTimestamps, Record ***recordsArray, unsigned long start, unsigned long end, size_t recordCount) {
    size_t windowSize = 0;
    for (size_t i = 0; i < recordCount; ++i) {
        if (eventTimestamps[0][i] >= start && eventTimestamps[0][i] <= end) {
            windowSize++;
        }
    }

    Record **windowRecords = malloc(windowSize * sizeof(Record *));
    if (windowRecords == NULL) {
        log_error("Failed to allocate memory for records in time window");
        return NULL;
    }

    size_t j = 0;
    for (size_t i = 0; i < recordCount; ++i) {
        if (eventTimestamps[0][i] >= start && eventTimestamps[0][i] <= end) {
            windowRecords[j++] = (*recordsArray)[i];
        }
    }

    return windowRecords;
}
