#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_HISTORY 100

typedef struct {
    float cpu_usage;
    float memory_consumption;
    float disk_io;
    float network_bandwidth;
} Metrics;

typedef struct {
    Metrics data[MAX_HISTORY];
    int index;
    int count;
} History;

typedef struct {
    float score;
    const char* metric_name;
    const char* action;
} Anomaly;

History history = {{0}, 0, 0};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void update_metrics(Metrics new_data) {
    pthread_mutex_lock(&lock);
    history.data[history.index] = new_data;
    if (history.count < MAX_HISTORY) {
        history.count++;
    } else {
        history.index = (history.index + 1) % MAX_HISTORY;
    }
    pthread_mutex_unlock(&lock);
}

float calculate_anomaly_score(Metrics current_metrics) {
    // Placeholder for anomaly scoring logic
    float score = 0.0;

    // Example: Calculate score based on deviation from historical average
    if (history.count > 0) {
        Metrics avg = {0};
        for (int i = 0; i < history.count; ++i) {
            int idx = (history.index + i) % MAX_HISTORY;
            avg.cpu_usage += history.data[idx].cpu_usage;
            avg.memory_consumption += history.data[idx].memory_consumption;
            avg.disk_io += history.data[idx].disk_io;
            avg.network_bandwidth += history.data[idx].network_bandwidth;
        }
        avg.cpu_usage /= history.count;
        avg.memory_consumption /= history.count;
        avg.disk_io /= history.count;
        avg.network_bandwidth /= history.count;

        score = fabs(current_metrics.cpu_usage - avg.cpu_usage) +
                fabs(current_metrics.memory_consumption - avg.memory_consumption) +
                fabs(current_metrics.disk_io - avg.disk_io) +
                fabs(current_metrics.network_bandwidth - avg.network_bandwidth);
    }

    return score;
}

Anomaly* detect_anomalies(Metrics current_metrics, int* count) {
    float score = calculate_anomaly_score(current_metrics);
    static Anomaly anomalies[4];
    *count = 0;

    if (score > 10.0) { // Example threshold
        anomalies[*count].score = score;
        anomalies[*count].metric_name = "CPU Usage";
        anomalies[*count++].action = "Increase CPU resources";
    }
    if (current_metrics.memory_consumption > 80.0) {
        anomalies[*count].score = current_metrics.memory_consumption;
        anomalies[*count].metric_name = "Memory Consumption";
        anomalies[*count++].action = "Optimize memory usage";
    }

    return anomalies;
}

void analyze_system(Metrics* metrics_data, int data_count) {
    float highest_score = 0.0;
    char* critical_metric = NULL;
    Anomaly* anomalies = NULL;

    for (int i = 0; i < data_count; ++i) {
        update_metrics(metrics_data[i]);
        int anomaly_count;
        anomalies = detect_anomalies(metrics_data[i], &anomaly_count);

        for (int j = 0; j < anomaly_count; ++j) {
            if (anomalies[j].score > highest_score) {
                highest_score = anomalies[j].score;
                critical_metric = strdup(anomalies[j].metric_name);
            }
            printf("Anomaly detected: %s, Score: %.2f, Action: %s\n",
                   anomalies[j].metric_name, anomalies[j].score, anomalies[j].action);
        }
    }

    if (critical_metric != NULL) {
        printf("\nHighest Anomaly Score: %.2f, Critical Metric: %s\n", highest_score, critical_metric);
        free(critical_metric);
    }
}

void report_system_resilience() {
    // Placeholder for resilience reporting logic
    printf("System Resilience Report:\n");
    printf("- Potential bottlenecks identified.\n");
    printf("- Suggested optimizations...\n");
}

int main() {
    Metrics metrics_data[] = {
        {75.0, 60.0, 30.0, 50.0},
        {80.0, 65.0, 35.0, 55.0},
        // Add more test data
    };

    analyze_system(metrics_data, sizeof(metrics_data) / sizeof(Metrics));
    report_system_resilience();

    return 0;
}
