} ProfileManager;

// Function to initialize the profile manager
ProfileManager* init_profile_manager(size_t initial_capacity) {
    ProfileManager* manager = malloc(sizeof(ProfileManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->profiles = malloc(initial_capacity * sizeof(Profile));
    if (!manager->profiles) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;

    // Initialize inverted index
    manager->inverted_index_capacity = 10; // Arbitrary initial capacity
    manager->inverted_index_count = 0;
    manager->inverted_index = malloc(manager->inverted_index_capacity * sizeof(char**));
    if (!manager->inverted_index) {
        free(manager->profiles);
        free(manager);
        return NULL;
    }

    return manager;
}

// Function to resize the profile array
int resize_profiles(ProfileManager* manager, size_t new_capacity) {
    Profile* temp = realloc(manager->profiles, new_capacity * sizeof(Profile));
    if (!temp) return -1;

    manager->profiles = temp;
    manager->capacity = new_capacity;
    return 0;
}

// Function to add a profile
int add_profile(ProfileManager* manager, float score, double value, const char* string) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity && resize_profiles(manager, manager->capacity * 2) != 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Profile profile = {score, &value, strdup(string)};
    if (!profile.ptr_string) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->profiles[manager->count++] = profile;

    // Update inverted index
    if (manager->inverted_index_count == manager->inverted_index_capacity && 
        resize_profiles(manager, manager->inverted_index_capacity * 2) != 0) {
        pthread_mutex_unlock(&manager->lock);
        free(profile.ptr_string); // Cleanup on failure
        return -1;
    }

    manager->inverted_index[manager->inverted_index_count++] = strdup(string);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to retrieve a profile by index
Profile* get_profile_by_index(ProfileManager* manager, size_t index) {
    if (index >= manager->count) return NULL;
    return &manager->profiles[index];
}

// Function to retrieve a profile by string identifier
Profile* get_profile_by_string(ProfileManager* manager, const char* str) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->inverted_index_count; ++i) {
        if (strcmp(manager->inverted_index[i], str) == 0) {
            Profile* profile = get_profile_by_index(manager, index); // Assume index is maintained
            pthread_mutex_unlock(&manager->lock);
            return profile;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to clean up resources
void cleanup_profile_manager(ProfileManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->profiles[i].ptr_string);
    }

    free(manager->profiles);

    for (size_t i = 0; i < manager->inverted_index_count; ++i) {
