#include <time.h>

typedef struct {
    time_t start_date;
    time_t end_date;
    int duration_days; // in days
} schedule_info;

typedef struct {
    char *name;
    schedule_info schedule;
    float budget_estimate;
} project;

typedef struct {
    project *projects;
    size_t capacity;
    size_t count;
} project_collection;

void initialize_schedule(schedule_info *schedule, time_t start_date, int duration_days) {
    if (schedule) {
        schedule->start_date = start_date;
        schedule->duration_days = duration_days;
        schedule->end_date = start_date + (duration_days * 24 * 60 * 60);
    }
}

project_collection* create_project_collection(size_t initial_capacity) {
    project_collection *collection = malloc(sizeof(project_collection));
    if (!collection) return NULL;

    collection->projects = calloc(initial_capacity, sizeof(project));
    if (!collection->projects) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void resize_project_collection_if_needed(project_collection *collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        project *new_projects = realloc(collection->projects, new_capacity * sizeof(project));

        if (!new_projects) {
            perror("Failed to resize project collection");
            exit(EXIT_FAILURE);
        }

        collection->projects = new_projects;
        collection->capacity = new_capacity;
    }
}

int add_project_to_collection(project_collection *collection, const char *name_base, time_t start_date, int duration_days, float budget_estimate) {
    if (!collection || !name_base) return -1;

    resize_project_collection_if_needed(collection);

    project new_project;
    new_project.name = malloc(20);
    snprintf(new_project.name, 20, "%s%d", name_base, collection->count);

    initialize_schedule(&new_project.schedule, start_date, duration_days);
    new_project.budget_estimate = budget_estimate;

    if (!new_project.name) {
        perror("Failed to allocate memory for project name");
        free(new_project.name); // In case snprintf succeeded
        return -1;
    }

    collection->projects[collection->count++] = new_project;
    return 0;
}

void remove_project_from_collection(project_collection *collection, size_t index) {
    if (!collection || index >= collection->count) return;

    free(collection->projects[index].name);

    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->projects[i] = collection->projects[i + 1];
    }

    --collection->count;
}

project* get_project_by_index(const project_collection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;

    return &collection->projects[index];
}

void free_project_collection(project_collection *collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->projects[i].name);
        }
        free(collection->projects);
        free(collection);
    }
}
