```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75
#define REAL_TIME_MONITOR_INTERVAL 1 // seconds

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double cpu_threshold;   // Example threshold, e.g., in percentage
    double memory_threshold; // Memory usage threshold, e.g., in MB
} RecordCollection;

// Function prototypes
void monitor_resources();
void resize_collection(RecordCollection *collection);
void* record_collector_thread(void *arg);

RecordCollection* create_record_collection(double cpu_threshold, double memory_threshold) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->records = calloc(INITIAL_CAPACITY, sizeof(Record *));
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->cpu_threshold = cpu_threshold;
    collection->memory_threshold = memory_threshold;

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, record_collector_thread, (void *)collection);
    return collection;
}

int add_record(RecordCollection *collection, int value, long offset, int key) {
    if ((double)(collection->count + 1) / collection->capacity >= LOAD_FACTOR_THRESHOLD) {
        resize_collection(collection);
    }

    pthread_mutex_lock(&collection->lock);

    Record *new_record = malloc(sizeof(Record));
    new_record->value = value;
    new_record->offset = malloc(sizeof(long));
    new_record->offset[0] = offset;
    new_record->key = malloc(sizeof(int));
    new_record->key[0] = key;

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void resize_collection(RecordCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        new_records[i] = NULL;
    }

    collection->records = new_records;
    collection->capacity = new_capacity;
}

void free_record_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
    }
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

void* record_collector_thread(void *arg) {
    RecordCollection *collection = (RecordCollection *)arg;
    while (1) {
        monitor_resources();
        sleep(REAL_TIME_MONITOR_INTERVAL);
    }
    return NULL;
}

void monitor_resources() {
    // Placeholder for real-time monitoring logic
    printf("Monitoring resources...\n");
}

// Comprehensive unit tests and stress tests would go here

int main() {
    RecordCollection *collection = create_record_collection(75.0, 512.0);

    add_record(collection, 1, 100L, 101);
    add_record(collection, 2, 200L, 202);

    free_record_collection(collection);
    return 0;
}
```

