#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char *purpose;
} Record;

#define LOG_WARNING(...) fprintf(stderr, __VA_ARGS__)

int initializeRecords(long seed, long offsetRange, size_t maxMemory, size_t numRecords) {
    srand(seed);
    size_t totalMemory = 0;
    size_t recordSizeWithoutPurpose = sizeof(Record) + sizeof(int); // space for key is already part of the struct
    const char *purposeTemplate = "Record with unique key: %d";
    Record *records = NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        size_t purposeSize = snprintf(NULL, 0, purposeTemplate, i + 1) + 1;
        size_t recordTotalSize = recordSizeWithoutPurpose + sizeof(char) * purposeSize;

        if (totalMemory + recordTotalSize > maxMemory) {
            LOG_WARNING("Warning: Maximum memory usage approached. Truncating collection.\n");
            break;
        }

        Record *newRecords = realloc(records, (i + 1) * recordTotalSize);
        if (!newRecords) {
            free(records); // Free previously allocated memory
            return -1; // Allocation failed
        }
        records = newRecords;

        Record *currentRecord = &records[i];
        currentRecord->offset = rand() % offsetRange;
        currentRecord->key = i + 1;

        currentRecord->purpose = malloc(purposeSize);
        if (!currentRecord->purpose) {
            free(records); // Free previously allocated memory
            return -1; // Allocation failed
        }

        snprintf(currentRecord->purpose, purposeSize, purposeTemplate, currentRecord->key);

        totalMemory += recordTotalSize;
    }

    printf("Total allocated memory: %zu bytes\n", totalMemory);

    // Free allocated memory
    for (size_t i = 0; i < numRecords && records[i].purpose != NULL; ++i) {
        free(records[i].purpose);
    }
    free(records);

    return totalMemory;
}

int main() {
    long seed = 12345;
    long offsetRange = 1000000;
    size_t maxMemory = 1024 * 1024; // 1MB
    size_t numRecords = 100;

    int result = initializeRecords(seed, offsetRange, maxMemory, numRecords);
    if (result < 0) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
    }

    return 0;
}
