#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define MAX_HOSTNAME_LENGTH 255
#define MAX_IP_STRING_LENGTH 16
#define MAX_LINE_LENGTH 1024
#define DNS_TIMEOUT 5 // seconds, configurable via environment variable

typedef struct {
    u_char ip_address[MAX_IP_STRING_LENGTH];
} IPResult;

int dns_resolve(const char *hostname, IPResult *result) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use AF_INET6 for IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        perror("getaddrinfo");
        return -1;
    }

    char ip_str[MAX_IP_STRING_LENGTH];
    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // AF_INET6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ip_str, sizeof(ip_str));
        strncpy((char *)result->ip_address, ip_str, MAX_IP_STRING_LENGTH - 1);
        break; // We just need the first address
    }

    freeaddrinfo(res);

    if (strlen((const char *)result->ip_address) == 0) {
        return -2;
    }

    return 0;
}

void *process_file(void *arg) {
    FILE **files = (FILE **)arg;
    int num_files = sizeof(files) / sizeof(FILE *);
    char line[MAX_LINE_LENGTH];

    for (int i = 0; i < num_files; ++i) {
        if (fgets(line, MAX_LINE_LENGTH, files[i]) != NULL) {
            IPResult ip_result;
            char *hostname_start = strstr(line, "Hostname:");

            if (hostname_start != NULL) {
                hostname_start += strlen("Hostname:"); // Skip the prefix
                u_char *dot_pos = (u_char *)strchr(hostname_start, '.');

                if (dot_pos != NULL && dot_pos - hostname_start < MAX_HOSTNAME_LENGTH) {
                    char temp_hostname[MAX_HOSTNAME_LENGTH];
                    strncpy(temp_hostname, hostname_start, dot_pos - hostname_start);
                    temp_hostname[dot_pos - hostname_start] = '\0';

                    int res = dns_resolve(temp_hostname, &ip_result);
                    if (res == 0) {
                        printf("Resolved IP: %s\n", ip_result.ip_address);
                    } else {
                        fprintf(stderr, "DNS resolution failed for '%s'\n", temp_hostname);
                    }
                }
            }

            char *token = strtok(line, ",");
            double sum = 0;
            int count = 0;

            while (token != NULL) {
                if (count > -2 && isdigit((unsigned char)token[0])) { // Consider last two numbers
                    sum += atof(token);
                }
                token = strtok(NULL, ",");
                ++count;
            }

            if (count >= 3) {
                double avg = sum / 2.0;
                printf("Line: %s Average of last two numbers: %.2f\n", line, avg);
            } else {
                printf("Line: %s No average calculated due to insufficient numeric fields.\n", line);
            }
        }
    }

    for (int i = 0; i < num_files; ++i) {
        fclose(files[i]);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s file1 [file2 ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE **files = malloc((argc - 1) * sizeof(FILE *));
    for (int i = 1; i < argc; ++i) {
        files[i-1] = fopen(argv[i], "r");
        if (!files[i-1]) {
            perror("Error opening file");
            exit(EXIT_FAILURE);
        }
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_file, files)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    free(files);

    return 0;
}
```

