['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // Example threshold for memory usage

typedef struct {
    long offset;
    int key;
    char *description;
    bool isInitialized;
} Record;

typedef struct {
    size_t totalMemoryUsage;
    size_t stringPoolSize;
    char **stringPool;
} MemoryManager;

static MemoryManager memManager = {0, 0, NULL};

void initializeMemoryManager(size_t stringPoolSize) {
    if (memManager.stringPool != NULL) {
        free(memManager.stringPool);
    }
    memManager.totalMemoryUsage = 0;
    memManager.stringPoolSize = stringPoolSize;
    memManager.stringPool = malloc(sizeof(char*) * stringPoolSize);
    if (!memManager.stringPool) {
        fprintf(stderr, "Failed to allocate memory for string pool\n");
        exit(EXIT_FAILURE);
    }
}

void freeMemoryManager() {
    for (size_t i = 0; i < memManager.stringPoolSize; ++i) {
        free(memManager.stringPool[i]);
    }
    free(memManager.stringPool);
    memManager.totalMemoryUsage = 0;
    memManager.stringPoolSize = 0;
}

void logWarning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

void logError(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

char* allocateStringFromPool(size_t len) {
    for (size_t i = 0; i < memManager.stringPoolSize; ++i) {
        if (!memManager.stringPool[i]) {
            memManager.stringPool[i] = malloc(len);
            if (!memManager.stringPool[i]) {
                logError("Failed to allocate string from pool");
                return NULL;
            }
            return memManager.stringPool[i];
        }
    }

    // No available slot found, try expanding the pool
    char **newPool = realloc(memManager.stringPool, sizeof(char*) * (memManager.stringPoolSize + 100));
    if (!newPool) {
        logError("Failed to expand string pool");
        return NULL;
    }
    memManager.stringPool = newPool;

    for (size_t i = memManager.stringPoolSize; i < memManager.stringPoolSize + 100; ++i) {
        memManager.stringPool[i] = malloc(len);
        if (!memManager.stringPool[i]) {
            logError("Failed to allocate string from expanded pool");
            return NULL;
        }
        if (i == memManager.stringPoolSize + 99) break;
    }

    memManager.stringPoolSize += 100;
    for (size_t i = memManager.stringPoolSize - 99; i < memManager.stringPoolSize; ++i) {
        if (!memManager.stringPool[i]) return allocateStringFromPool(len);
    }

    logError("Failed to find available slot in expanded string pool");
    return NULL;
}

int initializeRecords(Record *records, size_t numRecords, bool *selectiveInit,
                      long offsetRange, int seed) {
    srand(seed);

    for (size_t i = 0; i < numRecords; ++i) {
        if (!selectiveInit[i]) continue;

        records[i].key = i;
        records[i].offset = rand() % offsetRange;
        char template[] = "Record description with key: %d";
        size_t len = snprintf(NULL, 0, template, (int)i) + 1;

        records[i].description = allocateStringFromPool(len);
        if (!records[i].description) {
            logError("Failed to allocate string for record");
            return -1;
        }

        snprintf(records[i].description, len, template, (int)i);

        records[i].isInitialized = true;

        // Update memory usage
        memManager.totalMemoryUsage += sizeof(long) + sizeof(int) +
                                       strlen(records[i].description) + 1 +
                                       sizeof(char*);
        if (memManager.totalMemoryUsage > MAX_MEMORY_USAGE) {
            logWarning("Memory usage exceeded threshold");
        }
    }

    return 0;
}

void freeRecords(Record *records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        if (!records[i].isInitialized) continue;

        free(records[i].description);
        records[i].description = NULL;
        memManager.totalMemoryUsage -= sizeof(long) + sizeof(int) +
                                       strlen(records[i].isInitialized ? records[i].description : "") + 1 +
                                       sizeof(char*);
    }
}

void debugPrintRecords(const Record *records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        printf("Record %zu: Initialized=%d, Offset=%ld, Key=%d\n",
               i, records[i].isInitialized,
               records[i].offset, records[i].key);
        if (records[i].description)
            printf("Description: %s\n", records[i].description);
    }
}

int main() {
    size_t numRecords = 100;
    bool selectiveInit[numRecords];
    memset(selectiveInit, 1, sizeof(bool) * numRecords);

    Record *records = malloc(sizeof(Record) * numRecords);
    if (!records) {
        logError("Failed to allocate records");
        return EXIT_FAILURE;
    }

    initializeMemoryManager(50); // Example pool size

    int result = initializeRecords(records, numRecords, selectiveInit, 10000L, 12345);
    if (result != 0) {
        free(records);
        freeMemoryManager();
