// DNS resolution function
u_char* resolve_hostname(const char *hostname) {
    // Check cache first
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (dns_cache[i].key && strcmp(dns_cache[i].key, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[i].ip;
        }
    }

    pthread_mutex_unlock(&cache_lock);

    // Perform DNS resolution
    struct addrinfo hints, *res, *ptr;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        handle_error("DNS resolution failed", errno);
        return NULL;
    }

    for (ptr = res; ptr != NULL; ptr = ptr->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *) ptr->ai_addr;
        u_char *ip = (u_char *)&(ipv4->sin_addr);

        // Add to cache
        pthread_mutex_lock(&cache_lock);
        dns_cache[(dns_head + 1) % CACHE_SIZE].key = strdup(hostname);
        memcpy(dns_cache[(dns_head + 1) % CACHE_SIZE].ip, ip, sizeof(ip));
        dns_head = (dns_head + 1) % CACHE_SIZE;
        pthread_mutex_unlock(&cache_lock);

        freeaddrinfo(res);
        return ip;
    }

    freeaddrinfo(res);
    handle_error("No IP address found", ENOENT);
    return NULL;
}

// Initialize DNS cache
void initialize_dns_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        dns_cache[i].key = NULL;
    }
}

// Free DNS cache
void free_dns_cache() {
