#define MAX_PATH_LENGTH 256
#define DOUBLE_RANGE_MIN 0.0
#define DOUBLE_RANGE_MAX 100.0

typedef struct {
    double value;
    char *path;
    int ref_count;
} record;

// Function prototypes
void incrementRefCount(record *rec);
void decrementRefCount(record *rec);
void freeResources(double *doubles, char **paths, record *records, size_t count);

// Custom transformation function type
typedef void (*transformFunc)(double *);

int processAndTransformData(size_t count, transformFunc customTransform) {
    double *doubles = (double *)malloc(count * sizeof(double));
    if (!doubles) return -1;

    char **paths = (char **)malloc(count * sizeof(char *));
    if (!paths) {
        free(doubles);
        return -1;
    }

    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        free(doubles);
        free(paths);
        return -1;
    }

    // Initialize doubles with random values within the defined range
    for (size_t i = 0; i < count; ++i) {
        doubles[i] = DOUBLE_RANGE_MIN + ((double)rand() / RAND_MAX) * (DOUBLE_RANGE_MAX - DOUBLE_RANGE_MIN);
        records[i].value = doubles[i];
        records[i].ref_count = 1;

        // Allocate and initialize paths based on user input
        paths[i] = (char *)malloc(MAX_PATH_LENGTH);
        if (!paths[i]) {
            freeResources(doubles, paths, records, i);
            return -1;
        }

        printf("Enter path for record %zu: ", i + 1);
        if (fgets(paths[i], MAX_PATH_LENGTH, stdin) == NULL || strlen(paths[i].strtok(NULL, "\n")) != 0) {
            freeResources(doubles, paths, records, i);
            return -1;
        }

        records[i].path = paths[i];
    }

    // Apply custom transformation if provided
    if (customTransform) {
        for (size_t i = 0; i < count; ++i) {
            customTransform(&records[i].value);
        }
    }

    // Example of reading from an external data source (file)
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        freeResources(doubles, paths, records, count);
        return -1;
    }

    double number;
    size_t readCount = 0;
    while (fscanf(file, "%lf", &number) == 1 && readCount < count) {
        // Process the numbers as needed
        printf("Read number: %f\n", number);
        ++readCount;
    }

    fclose(file);

    // Example usage of reference counting
    incrementRefCount(&records[0]);
    decrementRefCount(&records[0]);

    // Free all allocated resources before returning
    freeResources(doubles, paths, records, count);
    return 0;
}

void incrementRefCount(record *rec) {
    if (rec) ++rec->ref_count;
}

void decrementRefCount(record *rec) {
    if (rec && rec->ref_count > 0) {
        --rec->ref_count;
        if (rec->ref_count == 0) {
            free(rec->path);
        }
    }
}

void freeResources(double *doubles, char **paths, record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        decrementRefCount(&records[i]);
        if (!records[i].ref_count) {
            free(records[i].path);
        }
    }
    free(doubles);
    free(paths);
    free(records);
}
