['Here is a simplified C code implementation that manages a dynamic collection of records with thread-safe operations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    long *offsets;
    int *keys;
    Record *records;
} DynamicCollection;

DynamicCollection* init_collection(size_t initial_capacity, int value_range_min, int value_range_max) {
    DynamicCollection *collection = malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->capacity = initial_capacity;
    collection->size = 0;

    collection->offsets = malloc(initial_capacity * sizeof(long));
    collection->keys = malloc(initial_capacity * sizeof(int));
    collection->records = malloc(initial_capacity * sizeof(Record));

    if (!collection->offsets || !collection->keys || !collection->records) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->offsets[i] = rand() % 10000; // Random offset
        collection->keys[i] = rand() % 100;     // Random key
        collection->records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        collection->records[i].offset_ptr = &collection->offsets[i];
        collection->records[i].key_ptr = &collection->keys[i];
    }

    return collection;
}

int add_record(DynamicCollection *collection, long offset, int key, int value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        long *new_offsets = realloc(collection->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(collection->keys, new_capacity * sizeof(int));
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->offsets[collection->size] = offset;
    collection->keys[collection->size] = key;
    collection->records[collection->size].value = value;
    collection->records[collection->size].offset_ptr = &collection->offsets[collection->size];
    collection->records[collection->size].key_ptr = &collection->keys[collection->size];

    ++collection->size;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(DynamicCollection *collection, size_t index) {
    if (index >= collection->size) return NULL;
    return &collection->records[index];
}

int update_record(DynamicCollection *collection, size_t index, int new_value) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->size) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->records[index].value = new_value;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void free_collection(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->offsets);
    free(collection->keys);
    free(collection->records);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// HTTP-like functions (pseudo-implementation)
int put_record(DynamicCollection *collection, size_t index, int new_value) {
    if (update_record(collection, index, new_value) == 0) {
        return 200; // OK
    }
    return 404; // Not Found
}

int delete_record(DynamicCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->size) {
        pthread_mutex_unlock(&collection->lock);
        return 404; // Not Found
    }

    memmove(&collection->records[index], &collection->records[index + 1],
            (collection->size - index - 1) * sizeof(Record));
    --collection->size;

    pthread_mutex_unlock(&collection->lock);
    return 200; // OK
}

void iterate_records(DynamicCollection *collection, void (*func)(size_t, Record*)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        func(i, &collection->records[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Example usage
void print_record(size_t index, Record *record) {
    if (record) {
        printf("Index: %zu, Value: %d, Offset: %ld, Key: %d\n", 
               index, record->value, *(record->offset_ptr), *(record->key_ptr));
    }
}

int main() {
    DynamicCollection *collection = init_collection(10, 0, 100);

    if (!collection) {
        fprintf(stderr, "Failed to initialize collection.\n");
        return EXIT_FAILURE;
    }

    add_record(collection, 12345L, 67, 89);
    iterate_records(collection, print_record);

    put_record(collection, 0, 99);
    print_record(0, get_record(collection, 0));

    delete_record(collection, 0);
    iterate_records(collection, print_record);

    free_collection(collection);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the required functionality with thread safety using mutexes. It includes functions to initialize, add, retrieve, update, and delete records in a dynamic array. The HTTP-like operations are simulated through function calls for updating and deleting records.']

