```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MEMORY_WARNING_THRESHOLD 1024 * 1024 // 1 MB

typedef struct {
    long offset;
    int key;
    char *description;
    bool initialized;
    char **event_log;
    size_t event_count;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
    void *memory_pool;
    size_t pool_size;
    size_t total_memory_used;
} RecordManager;

#define ERROR_OUT_OF_MEMORY -1
#define SUCCESS 0

RecordManager* create_record_manager(size_t initial_capacity, size_t memory_pool_size) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->used = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->memory_pool = malloc(memory_pool_size);
    if (!manager->memory_pool) {
        free(manager->records);
        free(manager);
        return NULL;
    }
    manager->pool_size = memory_pool_size;
    manager->total_memory_used = 0;

    return manager;
}

void* allocate_from_pool(RecordManager *manager, size_t size) {
    if (size > manager->pool_size - manager->total_memory_used) {
        pthread_mutex_lock(&manager->mutex);
        if (size > manager->pool_size - manager->total_memory_used) {
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
    }

    void *ptr = (char*)manager->memory_pool + manager->total_memory_used;
    manager->total_memory_used += size;

    pthread_mutex_lock(&manager->mutex);
    if (manager->total_memory_used > MEMORY_WARNING_THRESHOLD) {
        printf("Warning: Memory usage exceeded threshold\n");
    }
    pthread_mutex_unlock(&manager->mutex);

    return ptr;
}

int initialize_records(RecordManager *manager, long seed, int range_start, int range_end, size_t *indices_to_init, size_t num_indices) {
    if (!manager || !indices_to_init) return ERROR_OUT_OF_MEMORY;

    srand(seed);
    for (size_t i = 0; i < manager->used; ++i) {
        manager->records[i].offset = rand() % (range_end - range_start + 1) + range_start;
        manager->records[i].key = i;
        manager->records[i].description = allocate_from_pool(manager, 256);
        if (!manager->records[i].description) return ERROR_OUT_OF_MEMORY;

        snprintf(manager->records[i].description, 256, "Record %zu", i);

        manager->records[i].initialized = false;
        manager->records[i].event_log = NULL;
        manager->records[i].event_count = 0;
    }

    for (size_t i = 0; i < num_indices; ++i) {
        size_t index = indices_to_init[i];
        if (index >= manager->used) continue;

        pthread_mutex_lock(&manager->mutex);
        manager->records[index].initialized = true;
        pthread_mutex_unlock(&manager->mutex);
    }

    return SUCCESS;
}

int append_event(RecordManager *manager, size_t index, const char *event) {
    if (!manager || index >= manager->used) return ERROR_OUT_OF_MEMORY;

    pthread_mutex_lock(&manager->mutex);
    Record *record = &manager->records[index];

    if (!record->initialized) {
        pthread_mutex_unlock(&manager->mutex);
        return ERROR_OUT_OF_MEMORY;
    }

    size_t event_size = strlen(event) + 1;
    char *new_event = allocate_from_pool(manager, event_size);
    if (!new_event) {
        pthread_mutex_unlock(&manager->mutex);
        return ERROR_OUT_OF_MEMORY;
    }

    strcpy(new_event, event);

    record->event_log = realloc(record->event_log, (record->event_count + 1) * sizeof(char*));
    if (!record->event_log) {
        free(new_event);
        pthread_mutex_unlock(&manager->mutex);
        return ERROR_OUT_OF_MEMORY;
    }

    record->event_log[record->event_count++] = new_event;

    pthread_mutex_unlock(&manager->mutex);

    return SUCCESS;
}

void debug_record(RecordManager *manager, size_t index) {
    if (!manager || index >= manager->used) return;

    Record *record = &manager->records[index];
    printf("Offset: %ld\n", record->offset);
    printf("Key: %d\n", record->key);
    printf("Description: %s\n", record->description);
    printf("Initialized: %s\n", record->initialized ? "Yes" : "No");
    for (size_t i = 0; i < record->event_count; ++i) {
        printf("Event %zu: %s\n", i, record->event_log[i]);
    }
}

void free_record_manager(RecordManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->used; ++i) {
        free(manager->records[i].description);
        for (size_t j = 0; j < manager->records[i].event_count; ++j) {
            free(manager->records[i].event_log[j]);
        }
        free(manager->records[i].event_log);
    }

    pthread_mutex_destroy(&manager->mutex);
    free(manager->records);
    free(manager->memory_pool);
    free(manager);
}

int main() {
    size_t indices_to_init[] = {0, 2};
    RecordManager *manager = create_record_manager(10, 1024 * 512); // 512 KB pool
    if (!manager) return EXIT_FAILURE;

    initialize_records(manager, 12345, 100, 200, indices_to_init, 2);
    append_event(manager, 0, "Initialized");
    debug_record(manager, 0);

    free_record_manager(manager);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Memory Management**: Uses a memory pool to minimize fragmentation and improve performance.
- **Synchronization**: Utilizes `pthread_mutex` for thread-safe operations.
- **Error Handling**: Gracefully handles allocation failures with error codes.
- **Debug Interface**: Provides functions to inspect and query record states.
- **Efficient Event Logging**: Avoids reallocations by dynamically resizing the event log.']

