        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}

u_char* resolve_dns(const char *hostname, int *error) {
    struct addrinfo hints, *res, *p;
    int result;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((result = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        *error = result;
        return NULL;
    }

    u_char* ip_address = malloc(4);
    if (!ip_address) {
        freeaddrinfo(res);
        *error = ENOMEM;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), sizeof(struct in_addr));

        freeaddrinfo(res);
        return ip_address;
    }

    freeaddrinfo(res);
    free(ip_address);
    *error = EAI_FAIL;
    return NULL;
}

void* process_file(void* arg) {
    char* filename = (char*)arg;
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        pthread_exit(NULL);
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Parse the line
        char* token = strtok(line, ",");
        int num_fields = 0;
        double last_num1 = 0.0, last_num2 = 0.0;

        do {
            if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) {
                if (!last_num1) last_num1 = atof(token);
                else last_num2 = atof(token);
            }
            ++num_fields;
        } while ((token = strtok(NULL, ",")) != NULL);

        double average = 0.0;
        if (num_fields > 1 && last_num1 && last_num2)
            average = calculate_average(last_num1, last_num2);

        // Print the line
        printf("%s", line);
        if (average)
            printf(",%f\n", average);
        else
            printf("\n");

        // Handle DNS resolution logic here for context-aware IP addresses

    }

    free(line);
    fclose(file);
    pthread_exit(NULL);
}

double calculate_average(double num1, double num2) {
    return (num1 + num2) / 2.0;
}
