#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& fl, const std::string& target, const std::string& to_insert) {
    auto it = fl.before_begin();
    bool found = false;

    for (auto curr = fl.begin(); curr != fl.end(); ++curr) {
        if (*curr == target) {
            fl.insert_after(curr, to_insert);
            found = true;
            break;
        }
        it = curr;
    }

    if (!found) {
        fl.insert_after(it, to_insert);
    }
}
