    while (*str) {
        hash = (hash * 31 + *str++) % 100000;
    }
    return hash;
}

// Function to initialize records selectively based on indices
int init_records(Record** records, size_t num_records, const int* init_indices, size_t num_init_indices, long seed, StringPool* string_pool) {
    if (!records || !init_indices) return -1;

    for (size_t i = 0; i < num_records; ++i) {
