        for (size_t j = 0; j < num_init_indices; ++j) {
            if (i == init_indices[j]) {
                records[i]->initialized = true;
                records[i]->offset = offset;

                // Allocate and initialize name
                records[i]->name = malloc(128);
                if (!records[i]->name) return -2; // Memory allocation failure
                snprintf(records[i]->name, 128, "Record-%d", key1);

                // Initialize event log
                records[i]->log_capacity = 4;
                records[i]->event_log = malloc(records[i]->log_capacity * sizeof(char*));
                if (!records[i]->event_log) return -2; // Memory allocation failure

                // Pre-allocate strings from pool
                records[i]->description = string_pool[0].name;
                memcpy(string_pool[0].name, buffer, strlen(buffer) + 1);
            }
        }

        // Track memory usage (simplified)
        static size_t total_memory_usage = 0;
        total_memory_usage += sizeof(Record) + (records[i]->initialized ? (strlen(records[i]->name) + 1 + records[i]->log_capacity * sizeof(char*)) : 0);

        if (total_memory_usage > MAX_MEMORY_USAGE) {
            fprintf(stderr, "Warning: Memory usage exceeded threshold.\n");
        }
    }

    return 0;
}

// Function to append an event log entry
int append_event_log(Record* record, const char* event) {
    if (!record || !event) return -1;

    if (record->log_size >= record->log_capacity) {
        size_t new_capacity = record->log_capacity * 2;
        char** new_log = realloc(record->event_log, new_capacity * sizeof(char*));
        if (!new_log) return -2; // Memory allocation failure

        for (size_t i = record->log_size; i < new_capacity; ++i) {
            new_log[i] = NULL;
        }

        record->event_log = new_log;
        record->log_capacity = new_capacity;
    }

    size_t event_len = strlen(event) + 1;
    char* log_entry = malloc(event_len);
    if (!log_entry) return -2; // Memory allocation failure

    strcpy(log_entry, event);

    record->event_log[record->log_size++] = log_entry;

    return 0;
}

// Debug function to query the state of a record
void debug_record(const Record* record) {
    printf("Offset: %ld\n", record->offset);
    printf("Key1: %d, Key2: %d\n", record->key1, record->key2);
    printf("Name: %s\n", record->name);
    printf("Initialized: %s\n", record->initialized ? "Yes" : "No");

    for (size_t i = 0; i < record->log_size; ++i) {
        printf("Event Log[%zu]: %s\n", i, record->event_log[i]);
    }
}

// Function to free allocated memory
void cleanup_records(Record** records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) {
            if (records[i]->name) free(records[i]->name);
            for (size_t j = 0; j < records[i]->log_size; ++j) {
                if (records[i]->event_log[j]) free(records[i]->event_log[j]);
            }
            if (records[i]->event_log) free(records[i]->event_log);
            free(records[i]);
        }
    }
}

int main() {
