    int init_indices[] = {0, 1, 3, 7};
    StringPool string_pool[STRING_POOL_SIZE];
    for (size_t i = 0; i < STRING_POOL_SIZE; ++i) {
        string_pool[i].index = i;
        string_pool[i].name = malloc(128);
        if (!string_pool[i].name) exit(-1); // Memory allocation failure
    }

    int result = init_records(records, num_records, init_indices, sizeof(init_indices) / sizeof(init_indices[0]), 42, string_pool);
    if (result != 0) {
        fprintf(stderr, "Failed to initialize records: %d\n", result);
