```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LENGTH 46 // Max length for IPv6 address in text form
#define CACHE_SIZE 100
#define MAX_CONCURRENT_QUERIES 10

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    u_char ip[MAX_IP_LENGTH];
} DnsCacheEntry;

DnsCacheEntry dns_cache[CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t cache_lock;
FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Cleanup and exit
        pthread_mutex_destroy(&cache_lock);
        fclose(log_file);
        exit(0);
    }
}

int log_resolution_result(const char *hostname, const char *result) {
    pthread_mutex_lock(&cache_lock);
    if (log_file) {
        fprintf(log_file, "Resolution for %s: %s\n", hostname, result);
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

u_char* resolve_dns(const char *hostname, int timeout, int *error_code) {
    struct addrinfo hints, *res, *p;
    int rv;
    u_char ip[MAX_IP_LENGTH];
    socklen_t len = sizeof(ip);

    // Initialize DNS cache
    pthread_mutex_init(&cache_lock, NULL);
    log_file = fopen("dns_resolution.log", "a");

    if (!log_file) {
        perror("Failed to open log file");
        *error_code = errno;
        return NULL;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((rv = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        *error_code = errno;
        log_resolution_result(hostname, "Failed to resolve DNS");
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (getnameinfo(p->ai_addr, p->ai_addrlen, ip, sizeof(ip), NULL, 0, NI_NUMERICHOST) == 0) {
            pthread_mutex_lock(&cache_lock);
            strncpy(dns_cache[cache_index % CACHE_SIZE].hostname, hostname, MAX_HOSTNAME_LEN);
            memcpy(dns_cache[cache_index % CACHE_SIZE].ip, ip, len);
            cache_index++;
            log_resolution_result(hostname, inet_ntoa(*(struct in_addr *)ip));
            pthread_mutex_unlock(&cache_lock);
            freeaddrinfo(res);
            *error_code = 0;
            return dns_cache[(cache_index - 1) % CACHE_SIZE].ip;
        }
    }

    freeaddrinfo(res);
    *error_code = ENOENT;
    log_resolution_result(hostname, "No address found");
    return NULL;
}

void cleanup() {
    pthread_mutex_destroy(&cache_lock);
    if (log_file) {
        fclose(log_file);
    }
}
```

### Explanation:

1. **Signal Handling**: The function uses `signal` to handle termination signals for clean exit.
2. **DNS Resolution**: Uses `getaddrinfo` to resolve both IPv4 and IPv6 addresses.
3. **Caching**: Implements a simple cache with mutex protection for concurrent access.
4. **Logging**: Logs resolution results to a file, ensuring thread safety with a mutex.
5. **Error Handling**: Returns error codes through an integer pointer argument.

This implementation is a starting point and can be extended to handle more complex requirements like dynamic configuration updates, DNS server fallbacks, and concurrency limits.']

