['Below is an implementation of the described C function to manage memory for a complex data model representing a log processing pipeline. It includes initialization, memory management, thread safety, and record retrieval mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} LogPipelineModel;

LogPipelineModel* initialize_log_pipeline(size_t num_records, int range_min, int range_max) {
    if (num_records <= 0 || range_min > range_max) {
        return NULL;
    }

    LogPipelineModel *model = malloc(sizeof(LogPipelineModel));
    if (!model) {
        perror("Failed to allocate LogPipelineModel");
        return NULL;
    }

    model->offsets = calloc(num_records, sizeof(long));
    model->keys = calloc(num_records, sizeof(int));
    model->records = calloc(num_records, sizeof(record*));

    if (!model->offsets || !model->keys || !model->records) {
        free(model->offsets);
        free(model->keys);
        free(model->records);
        free(model);
        perror("Failed to allocate memory for arrays");
        return NULL;
    }

    pthread_mutex_init(&model->lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        long offset = /* predefined pattern */ i * 10L;
        int key = /* predefined pattern */ i % 100;

        record *rec = malloc(sizeof(record));
        if (!rec) {
            perror("Failed to allocate memory for record");
            // Free previously allocated resources
            while (i > 0) {
                free(model->records[--i]);
            }
            free(model->offsets);
            free(model->keys);
            free(model->records);
            pthread_mutex_destroy(&model->lock);
            free(model);
            return NULL;
        }

        rec->value = rand() % (range_max - range_min + 1) + range_min;
        rec->offset_ptr = &model->offsets[i];
        rec->key_ptr = &model->keys[i];

        model->records[i] = rec;
    }

    model->count = num_records;

    return model;
}

record* get_record(LogPipelineModel *model, size_t index) {
    if (!model || index >= model->count) {
        return NULL;
    }
    pthread_mutex_lock(&model->lock);
    record *rec = model->records[index];
    pthread_mutex_unlock(&model->lock);
    return rec;
}

void iterate_forward(LogPipelineModel *model, void (*callback)(record *)) {
    if (!model || !callback) {
        return;
    }

    pthread_mutex_lock(&model->lock);
    for (size_t i = 0; i < model->count; ++i) {
        callback(model->records[i]);
    }
    pthread_mutex_unlock(&model->lock);
}

void iterate_backward(LogPipelineModel *model, void (*callback)(record *)) {
    if (!model || !callback) {
        return;
    }

    pthread_mutex_lock(&model->lock);
    for (int i = model->count - 1; i >= 0; --i) {
        callback(model->records[i]);
    }
    pthread_mutex_unlock(&model->lock);
}

void free_log_pipeline(LogPipelineModel *model) {
    if (!model) return;

    pthread_mutex_lock(&model->lock);
    for (size_t i = 0; i < model->count; ++i) {
        free(model->records[i]);
    }
    free(model->offsets);
    free(model->keys);
    free(model->records);
    pthread_mutex_unlock(&model->lock);

    pthread_mutex_destroy(&model->lock);
    free(model);
}

// Example usage
void print_record(record *rec) {
    if (rec) {
        printf("Value: %d, Offset: %ld, Key: %d\n", rec->value, *(rec->offset_ptr), *(rec->key_ptr));
    }
}
```

### Explanation:
- **Initialization**: The function `initialize_log_pipeline` sets up the memory for offsets, keys, and records. It ensures all allocations succeed and gracefully handles failures by freeing any allocated resources.

- **Thread Safety**: A mutex (`pthread_mutex_t`) is used to protect access to shared data structures ensuring thread-safe operations.

- **Record Retrieval**: The `get_record` function retrieves a specific record while ensuring mutual exclusion with the mutex.

