using System;
using System.Collections.Concurrent;
using System.Runtime.Caching;

public class DynamicRandom
{
    private double minFloat, maxFloat;
    private int minInt, maxInt;
    private static Random random = new Random();
    private static readonly Object lockObj = new Object();

    // Cache for frequently requested values
    private MemoryCache cache = new MemoryCache("DynamicRandomCache");

    public DynamicRandom(double minFloat = 0, double maxFloat = 100, int minInt = 0, int maxInt = 100)
    {
        if (minFloat > maxFloat || minInt > maxInt)
        {
            Console.WriteLine("Warning: Invalid range provided. Using default values.");
            this.minFloat = this.maxFloat = 0;
            this.minInt = this.maxInt = 100;
        }
        else
        {
            this.minFloat = minFloat;
            this.maxFloat = maxFloat;
            this.minInt = minInt;
            this.maxInt = maxInt;
        }

        Log($"DynamicRandom initialized with float range [{minFloat}, {maxFloat}] and int range [{minInt}, {maxInt}].");
    }

    public double GenerateRandomFloat(bool inclusive = false)
    {
        lock (lockObj)
        {
            var key = $"float_{inclusive}";
            if (!cache.Contains(key))
            {
                cache.Set(key, inclusive ? random.NextDouble() * (maxFloat - minFloat) + minFloat : 
                                             (random.NextDouble() * (maxFloat - minFloat + 1)) + minFloat);
            }
            return (double)cache.Get(key);
        }
    }

    public int GenerateRandomInt(bool inclusive = false)
    {
        lock (lockObj)
        {
            var key = $"int_{inclusive}";
            if (!cache.Contains(key))
            {
                cache.Set(key, inclusive ? random.Next(minInt, maxInt + 1) : 
                                          random.Next(minInt, maxInt));
            }
            return (int)cache.Get(key);
        }
    }

    public double GenerateGaussianRandom()
    {
        lock (lockObj)
        {
            var mean = (minFloat + maxFloat) / 2;
            var stdDev = (maxFloat - minFloat) / 6; // Assuming 99.7% data within range
            return mean + random.NextDouble() * stdDev;
        }
    }

    public void ResetToDefault()
    {
        lock (lockObj)
        {
            this.minFloat = this.maxFloat = 0;
            this.minInt = this.maxInt = 100;
            cache.Dispose();
            cache = new MemoryCache("DynamicRandomCache");
            Log("Range reset to default values.");
        }
    }

    public static void GenerateSeed(long seed)
    {
        lock (lockObj)
        {
            random = new Random((int)seed);
        }
    }

    public override string ToString()
    {
        return $"Float Range: [{minFloat}, {maxFloat}], Int Range: [{minInt}, {maxInt}]";
    }

    private void Log(string message)
    {
        // Placeholder for logging implementation
        Console.WriteLine(message);
    }
}
```

### Key Points:
- **Thread Safety**: Uses `lock` to ensure thread safety across all methods.
- **Caching**: Implements a simple caching strategy using `MemoryCache` to store frequently requested values.
- **Gaussian Distribution**: Provides a method to generate Gaussian-distributed random numbers centered around the range midpoint.
- **Logging**: Includes basic logging for initialization and resetting operations.
- **Custom Seed**: Allows setting a custom seed for reproducibility in tests.']

['Below is an example C code implementing a memory-efficient and scalable event processing system as described in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENT_TYPES 10

typedef struct {
    int identifier;
    time_t *timestamp_ptr;
    char **event_type_ptr;
} event_metadata_t;

typedef struct {
    pthread_mutex_t lock;
    time_t *timestamps;
    char **event_types;
    event_metadata_t *metadata;
    size_t capacity;
    size_t count;
} event_manager_t;

void init_event_manager(event_manager_t *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    manager->timestamps = malloc(sizeof(time_t) * initial_capacity);
    if (!manager->timestamps) {
        perror("Failed to allocate memory for timestamps");
        exit(EXIT_FAILURE);
    }

    manager->event_types = malloc(sizeof(char*) * initial_capacity);
    if (!manager->event_types) {
        free(manager->timestamps);
        perror("Failed to allocate memory for event types");
        exit(EXIT_FAILURE);
    }

    manager->metadata = malloc(sizeof(event_metadata_t) * initial_capacity);
    if (!manager->metadata) {
        free(manager->timestamps);
        free(manager->event_types);
        perror("Failed to allocate memory for metadata");
        exit(EXIT_FAILURE);
    }
}

void free_event_manager(event_manager_t *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->timestamps[i]);
        free(manager->event_types[i]);
    }

    free(manager->timestamps);
    free(manager->event_types);
    free(manager->metadata);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void resize_event_manager(event_manager_t *manager, size_t new_capacity) {
    time_t *new_timestamps = realloc(manager->timestamps, sizeof(time_t) * new_capacity);
    char **new_event_types = realloc(manager->event_types, sizeof(char*) * new_capacity);
    event_metadata_t *new_metadata = realloc(manager->metadata, sizeof(event_metadata_t) * new_capacity);

    if (!new_timestamps || !new_event_types || !new_metadata) {
        perror("Failed to resize memory arrays");
        exit(EXIT_FAILURE);
    }

    manager->timestamps = new_timestamps;
    manager->event_types = new_event_types;
    manager->metadata = new_metadata;
    manager->capacity = new_capacity;
}

void add_event(event_manager_t *manager, int id, time_t timestamp, const char *type) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_event_manager(manager, manager->capacity * 2);
    }

    manager->timestamps[manager->count] = malloc(sizeof(time_t));
    *manager->timestamps[manager->count] = timestamp;

    manager->event_types[manager->count] = strdup(type);

    manager->metadata[manager->count].identifier = id;
    manager->metadata[manager->count].timestamp_ptr = &manager->timestamps[manager->count];
    manager->metadata[manager->count].event_type_ptr = &manager->event_types[manager->count];

    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    event_manager_t manager;
    init_event_manager(&manager, 10);

    srand(time(NULL));
    for (int i = 0; i < 50; ++i) {
        int id = rand() % MAX_EVENT_TYPES;
        time_t timestamp = time(NULL) + rand() % 10000;
        const char *types[] = {"TypeA", "TypeB", "TypeC", "TypeD", "TypeE", 
                               "TypeF", "TypeG", "TypeH", "TypeI", "TypeJ"};
        add_event(&manager, id, timestamp, types[id % MAX_EVENT_TYPES]);
    }

    // Cleanup
    free_event_manager(&manager);

    return 0;
}
```

This code provides a thread-safe and scalable event manager that handles dynamic memory allocation for events. It initializes the data structures with specified capacities and resizes them as needed. The `add_event` function safely adds new events, ensuring proper synchronization using mutexes to handle concurrent access.

The memory management includes strategies for efficient allocation and deallocation, minimizing fragmentation by reallocating larger arrays when necessary. The code also handles potential errors during memory operations gracefully, logging failures to standard error output.']

['Here's an implementation that addresses your requirements for managing a complex log processing pipeline in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    long* offsets;
    int* keys;
    record** records;
    pthread_mutex_t lock;
} log_pipeline;

void init_random() {
    srand(time(NULL));
}

int rand_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

log_pipeline* create_log_pipeline(size_t capacity) {
    log_pipeline* pipeline = malloc(sizeof(log_pipeline));
    if (!pipeline) return NULL;

    pipeline->capacity = capacity;
    pipeline->count = 0;

    pipeline->offsets = malloc(capacity * sizeof(long));
    pipeline->keys = malloc(capacity * sizeof(int));
    pipeline->records = malloc(capacity * sizeof(record*));

    if (!pipeline->offsets || !pipeline->keys || !pipeline->records) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline);
        return NULL;
    }

    pthread_mutex_init(&pipeline->lock, NULL);

    // Initialize offsets and keys with a predefined pattern
    for (size_t i = 0; i < capacity; ++i) {
        pipeline->offsets[i] = i * 100;  // Example pattern
        pipeline->keys[i] = i % 10;
    }

    return pipeline;
}

void free_log_pipeline(log_pipeline* pipeline) {
    if (!pipeline) return;

    for (size_t i = 0; i < pipeline->count; ++i) {
        free(pipeline->records[i]);
    }
    free(pipeline->offsets);
    free(pipeline->keys);
    free(pipeline->records);
    pthread_mutex_destroy(&pipeline->lock);
    free(pipeline);
}

int add_record(log_pipeline* pipeline, int min_val, int max_val) {
    if (!pipeline) return -1;

    pthread_mutex_lock(&pipeline->lock);

    if (pipeline->count >= pipeline->capacity) {
        pthread_mutex_unlock(&pipeline->lock);
        return -1;  // Full capacity
    }

    record* rec = malloc(sizeof(record));
    if (!rec) {
        pthread_mutex_unlock(&pipeline->lock);
        return -1;
    }

    rec->value = rand_range(min_val, max_val);
    rec->offset = &pipeline->offsets[pipeline->count];
    rec->key = &pipeline->keys[pipeline->count];

    pipeline->records[pipeline->count] = rec;
    pipeline->count++;

    pthread_mutex_unlock(&pipeline->lock);
    return 0;
}

record* get_record(log_pipeline* pipeline, size_t index) {
    if (!pipeline || index >= pipeline->count) return NULL;

    pthread_mutex_lock(&pipeline->lock);

    record* rec = pipeline->records[index];

    pthread_mutex_unlock(&pipeline->lock);
    return rec;
}

void compact_records(log_pipeline* pipeline) {
    if (!pipeline) return;

    pthread_mutex_lock(&pipeline->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < pipeline->count;) {
        record* rec = pipeline->records[i];
        if (rec && rec->value != -1) {  // Assume -1 indicates an empty record
            pipeline->records[new_count++] = rec;
        }
        ++i;
    }

    for (size_t i = new_count; i < pipeline->count; ++i) {
        free(pipeline->records[i]);
    }

    pipeline->count = new_count;

    pthread_mutex_unlock(&pipeline->lock);
}

void* iterate_records(log_pipeline* pipeline, int forward) {
    if (!pipeline) return NULL;

    size_t start = 0;
    size_t end = pipeline->count;
    size_t step = 1;

    if (!forward) {
        start = pipeline->count - 1;
        end = (size_t)-1;
        step = -1;
    }

    pthread_mutex_lock(&pipeline->lock);

    for (size_t i = start; forward ? i < end : i != (size_t)-1; i += step) {
        yield();  // Allow other threads to run
        record* rec = pipeline->records[i];
        if (rec) {
            printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n", i, rec->value, *rec->offset, *rec->key);
        }
    }

    pthread_mutex_unlock(&pipeline->lock);

    return NULL;
}

// Simulate a yield function
void yield() {
    sched_yield();
}
```

This code provides a basic implementation of the log processing pipeline with memory management, concurrency control using mutexes, and compacting mechanism. It includes error handling for allocation failures and ensures thread safety. The `iterate_records` function allows iteration over records in both forward and backward directions. Adjust the logic as needed to fit specific use cases or integrate with external systems.']

