#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_EVENT_TYPE 100
#define MAX_EVENTS 1000

typedef struct {
    time_t timestamp;
    char event_type[50];
    char *details;
} Event;

typedef void (*NotificationCallback)(Event *);

typedef struct {
    NotificationCallback callback;
    void *context; // User-defined context for listeners
} Listener;

// Define the list of valid event types
const char* valid_event_types[MAX_EVENT_TYPE] = {"type1", "type2", /* other event types */};

// Event storage structure
typedef struct {
    Event **events;
    size_t count;
    size_t capacity;
    Listener *listeners;
    size_t listener_count;
} EventCollection;

// Function prototypes
void processAndPersistData();
int isValidEvent(Event *event);
void addEvent(EventCollection *collection, Event *event);
Event* getEventsByType(EventCollection *collection, const char *type);
void clearAllEvents(EventCollection *collection);
void registerListener(EventCollection *collection, NotificationCallback callback, void *context);
void deregisterListener(EventCollection *collection, NotificationCallback callback);

// Utility functions
int isEventTypeValid(const char *event_type) {
    for (size_t i = 0; i < MAX_EVENT_TYPE; ++i) {
        if (strcmp(event_type, valid_event_types[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

time_t getTimestampThreshold() {
    time_t now = time(NULL);
    const int days = 30;
    return now - (days * 24 * 60 * 60);
}

// Main function to process and persist data
void processAndPersistData() {
    EventCollection collection = {0};

    // Allocate initial memory for events
    collection.capacity = 10;
    collection.events = malloc(collection.capacity * sizeof(Event*));
    if (!collection.events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    collection.listeners = NULL;
