        size_t detail_length = strlen(event->details) + 1;
        char *details = malloc(detail_length);
        if (!details) {
            free(event);
            fprintf(stderr, "Memory allocation failed for details\n");
            continue;
        }
        strcpy(details, event->details);
        event->details = details;

        // Validate the event
