        exit(EXIT_FAILURE);
    }
    collection->count = 0;
}

void registerListener(EventCollection *collection, NotificationCallback callback, void *context) {
    Listener new_listener = {callback, context};
    collection->listeners = realloc(collection->listeners, (collection->listener_count + 1) * sizeof(Listener));
    if (!collection->listeners) {
        fprintf(stderr, "Memory allocation failed for listener registration\n");
        return;
    }
    collection->listeners[collection->listener_count++] = new_listener;
}

void deregisterListener(EventCollection *collection, NotificationCallback callback) {
    for (size_t i = 0; i < collection->listener_count; ++i) {
        if (collection->listeners[i].callback == callback) {
            // Shift the remaining listeners left
            memmove(&collection->listeners[i], &collection->listeners[i + 1],
                    (collection->listener_count - i - 1) * sizeof(Listener));
            collection->listener_count--;
            break;
        }
    }
    collection->listeners = realloc(collection->listeners, collection->listener_count * sizeof(Listener));
}
