        }

        let status: HashMap<String, String> = response.json().await?;

        Ok(status.get("status").cloned().unwrap_or_else(String::from))
    }

    // Example method to handle retries with backoff
    pub async fn retry_with_backoff<F, Fut>(&self, mut operation: F) -> Result<(), ReqwestError>
    where
        F: FnMut() -> Fut,
        Fut: std::future::Future<Output = Result<(), ReqwestError>>,
    {
        let mut attempts = 0;

        loop {
            match operation().await {
                Ok(_) => return Ok(()),
                Err(e) if attempts < 5 => {
                    let delay = (2u64).pow(attempts as u32);
                    tokio::time::sleep(Duration::from_secs(delay)).await;
                    attempts += 1;
                },
                Err(e) => return Err(e),
            }
        }
    }
