// Function to initialize and manage records
fn initializeAndManageRecords(record_count: usize, range_min: i32, range_max: i32) -> Result<Arc<Mutex<HashMap<usize, Record>>>, &'static str> {
    // Initialize vectors for offsets and keys
    let mut offsets = vec![0i64; record_count];
    let mut keys = vec![0i32; record_count];

    // Populate offsets and keys with a predefined pattern
    for i in 0..record_count {
        offsets[i] = (i as i64) * 10;
        keys[i] = i as i32;
    }

    // Initialize the records vector
    let mut records: Vec<Record> = Vec::with_capacity(record_count);

    // Random number generator
    let mut rng = rand::thread_rng();

    for i in 0..record_count {
        let value = rng.gen_range(range_min..=range_max);
        let offset_ptr = offsets[i] as *const _;
        let key_ptr = keys[i] as *const _;

        records.push(Record {
            value,
            offset_ptr,
            key_ptr,
        });
    }

    // Compact the records to merge consecutive empty records
    compact_records(&mut records);

    // Store records in a hashmap for efficient access
    let record_map: HashMap<usize, Record> = records.into_iter().enumerate().map(|(i, rec)| (i, rec)).collect();

    Ok(Arc::new(Mutex::new(record_map)))
}

// Function to compact consecutive empty records
fn compact_records(records: &mut Vec<Record>) {
    let mut i = 0;
    while i < records.len() - 1 {
        if records[i].value == 0 && records[i + 1].value == 0 {
            records.remove(i + 1);
        } else {
            i += 1;
        }
    }
}

