}

fn initializeAndManageRecords(num_records: usize, value_range: (i32, i32)) -> Result<Arc<Mutex<Vec<Record>>>, String> {
    // Initialize arrays for offsets and keys
    let mut offsets: Vec<u64> = (0..num_records).map(|i| i as u64 * 10).collect();
    let mut keys: Vec<i32> = (0..num_records).map(|i| i as i32 * 5).collect();

    // Prepare the records vector
    let records = Arc::new(Mutex::new(Vec::with_capacity(num_records)));

    // Populate records with initialized values
    {
        let mut records_vec = records.lock().unwrap();
        for i in 0..num_records {
            let value: i32 = rand::thread_rng().gen_range(value_range.0..=value_range.1);
            let record = Record {
                value,
                offset_ptr: offsets[i] as *const _,
                key_ptr: keys[i] as *const _,
            };
            records_vec.push(record);
        }
    }

    // Implement compaction mechanism
    compact_records(&records);

    Ok(records)
}

fn compact_records(records: &Arc<Mutex<Vec<Record>>>) {
    let mut records_vec = records.lock().unwrap();
    records_vec.retain(|r| r.value != 0); // Simple example, refine as needed

    for (i, record) in records_vec.iter_mut().enumerate() {
        if i > 0 && *record.offset_ptr == *(records_vec[i - 1].offset_ptr) && *record.key_ptr == *(records_vec[i - 1].key_ptr) {
            // Merge logic
            record.value = 0; // Mark as merged/empty
        }
    }

    records_vec.retain(|r| r.value != 0);
}

