```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 5000
#define BLOOM_FILTER_SIZE 1024
#define HASH_COUNT 3

typedef struct {
    time_t timestamp;
    double amount;
    char status[10];
} Transaction;

typedef struct {
    Transaction *transactions[MAX_TRANSACTIONS];
    unsigned char bloom_filter[BLOOM_FILTER_SIZE];
    pthread_mutex_t lock;
} TransactionManager;

unsigned int hash(unsigned char *str, size_t len) {
    unsigned int hash = 5381;
    for (size_t i = 0; i < len; ++i) {
        hash = ((hash << 5) + hash) + str[i];
    }
    return hash % BLOOM_FILTER_SIZE;
}

void add_hashes(unsigned char *bloom_filter, unsigned int id) {
    for (int i = 0; i < HASH_COUNT; ++i) {
        bloom_filter[hash((unsigned char *)&id + i, sizeof(id))] |= (1 << i);
    }
}

int check_hash(unsigned char *bloom_filter, unsigned int id) {
    for (int i = 0; i < HASH_COUNT; ++i) {
        if (!(bloom_filter[hash((unsigned char *)&id + i, sizeof(id))] & (1 << i))) {
            return 0;
        }
    }
    return 1;
}

TransactionManager* create_transaction_manager() {
    TransactionManager *manager = malloc(sizeof(TransactionManager));
    if (!manager) return NULL;

    memset(manager->bloom_filter, 0, BLOOM_FILTER_SIZE);
    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < MAX_TRANSACTIONS; ++i) {
        manager->transactions[i] = NULL;
    }

    return manager;
}

void destroy_transaction_manager(TransactionManager *manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_TRANSACTIONS; ++i) {
        free(manager->transactions[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Transaction* create_transaction(int index, unsigned int transaction_id) {
    Transaction *transaction = malloc(sizeof(Transaction));
    if (!transaction) return NULL;

    transaction->timestamp = time(NULL);
    transaction->amount = (double)(rand() % 1000 + 1); // Random amount between 1 and 1000
    strcpy(transaction->status, "pending");

    add_hashes(manager->bloom_filter, transaction_id);

    pthread_mutex_lock(&manager->lock);
    manager->transactions[index] = transaction;
    pthread_mutex_unlock(&manager->lock);

    return transaction;
}

Transaction* get_transaction(TransactionManager *manager, int index) {
    if (index < 0 || index >= MAX_TRANSACTIONS) return NULL;

    pthread_mutex_lock(&manager->lock);
    Transaction *transaction = manager->transactions[index];
    pthread_mutex_unlock(&manager->lock);

    return transaction;
}

void update_transaction(TransactionManager *manager, int index, double new_amount) {
    if (index < 0 || index >= MAX_TRANSACTIONS) return;

    pthread_mutex_lock(&manager->lock);
    Transaction *transaction = manager->transactions[index];
    if (transaction) {
        transaction->amount = new_amount;
    }
    pthread_mutex_unlock(&manager->lock);
}

int count_unique_transactions(TransactionManager *manager, unsigned int *ids, size_t num_ids) {
    int unique_count = 0;

    for (size_t i = 0; i < num_ids; ++i) {
        if (!check_hash(manager->bloom_filter, ids[i])) continue;
        unique_count++;
    }

    return unique_count;
}

int main() {
    srand(time(NULL));

    TransactionManager *manager = create_transaction_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create transaction manager\n");
        return EXIT_FAILURE;
    }

    unsigned int transaction_ids[] = {1, 2, 3, 4, 5};
    size_t num_ids = sizeof(transaction_ids) / sizeof(transaction_ids[0]);

    for (size_t i = 0; i < num_ids; ++i) {
        create_transaction(i, transaction_ids[i]);
    }

    int unique_count = count_unique_transactions(manager, transaction_ids, num_ids);
    printf("Number of unique transactions: %d\n", unique_count);

    destroy_transaction_manager(manager);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread safety.
- **Bloom Filter**: Efficiently tracks the existence of transaction IDs with a balance between false positives and performance.
- **Dynamic Memory Management**: Ensures no memory leaks by freeing allocated resources.
- **Error Handling**: Checks for NULL pointers during memory allocation.
- **Scalability**: Designed to handle up to 5000 transactions efficiently.']

