unsigned long last_query_time = 0;

int rate_limit_exceeded() {
    unsigned long current_time = time(NULL);
    if (current_time - last_query_time < 1.0 / RATE_LIMIT) {
        return 1;
    }
    last_query_time = current_time;
    return 0;
}

u_char *resolve_hostname(const char *hostname, int *error_code) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ip[16];

    if (rate_limit_exceeded()) {
        *error_code = -1; // Rate limit exceeded
        return NULL;
    }

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        *error_code = status;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ip, sizeof(ip));
    }

    freeaddrinfo(res);

    if (*error_code == 0) {
        return strdup((char *)ip);
    } else {
        *error_code = errno;
        return NULL;
    }
}

