public class PaymentWebhookProcessor {

    private final CacheService cacheService;
    private final TransactionService transactionService;
    private final MonitoringService monitoringService;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public PaymentWebhookProcessor(CacheService cacheService, TransactionService transactionService, MonitoringService monitoringService) {
        this.cacheService = cacheService;
        this.transactionService = transactionService;
        this.monitoringService = monitoringService;
    }

    public Response processTransaction(String transactionId, String userId, String webhookPayload) {
        try {
            JsonNode payload = objectMapper.readTree(webhookPayload);

            if (!validateInput(transactionId, userId, payload)) {
                return new Response(false, "Validation failed", false);
            }

            cacheService.putIfAbsent("transaction:" + transactionId, payload.toString(), 10, TimeUnit.MINUTES);

            Transaction transaction = transactionService.getTransactionDetails(transactionId);

            if (transaction == null) {
                cacheService.invalidate("transaction:" + transactionId);
                return new Response(false, "Transaction not found", true);
            }

            if (!applyBusinessRules(payload, transaction)) {
                return new Response(false, "Business rules violation", false);
            }

            boolean success = transactionService.process(transaction);

            if (success) {
                cacheService.invalidate("transaction:" + transactionId);
                monitoringService.logSuccess(userId, transactionId);
                return new Response(true, "Transaction processed successfully", false);
            } else {
                rollbackChanges(transactionId);
                monitoringService.logFailure(userId, transactionId, "Processing failed");
                return new Response(false, "Processing failed", true);
            }
        } catch (Exception e) {
            rollbackChanges(transactionId);
            monitoringService.logError(e.getMessage());
            return new Response(false, "Unexpected error occurred", false);
        }
    }

