#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    double value;
    char *name;
} Entry;

typedef struct {
    Entry **entries;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} EntryCollection;

// Function prototypes
EntryCollection* create_entry_collection(size_t initial_size);
void free_entry_collection(EntryCollection *collection);
int insert_entry(EntryCollection *collection, const char *name);
Entry* get_entry_by_id(EntryCollection *collection, int id);
int update_entry_value(EntryCollection *collection, int id, double new_value);

// Create and initialize the collection
EntryCollection* create_entry_collection(size_t initial_size) {
    EntryCollection *collection = malloc(sizeof(EntryCollection));
    if (!collection) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->entries = calloc(initial_size, sizeof(Entry *));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    return collection;
}

// Free the allocated memory for the collection
void free_entry_collection(EntryCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->name);
        free(collection->entries[i]);
    }

    free(collection->entries);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Insert a new entry
int insert_entry(EntryCollection *collection, const char *name) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->allocated_size) {
        size_t new_size = 2 * (collection->count + 1); // Double the size
        Entry **new_entries = realloc(collection->entries, new_size * sizeof(Entry *));

        if (!new_entries) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }

        collection->entries = new_entries;
        collection->allocated_size = new_size;
    }

    Entry *entry = malloc(sizeof(Entry));
    if (!entry) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    entry->id = collection->count + 1;
    entry->value = (double)rand() / RAND_MAX * 100.0; // Random double between 0 and 100

    size_t name_len = strlen(name) + 1;
    entry->name = malloc(name_len);
    if (!entry->name) {
        free(entry);
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    memcpy(entry->name, name, name_len);

    collection->entries[collection->count++] = entry;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Retrieve an entry by its ID
Entry* get_entry_by_id(EntryCollection *collection, int id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]->id == id) {
            Entry *entry = collection->entries[i];
            pthread_mutex_unlock(&collection->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

// Update an entry's value by its ID
int update_entry_value(EntryCollection *collection, int id, double new_value) {
    Entry *entry = get_entry_by_id(collection, id);

    if (entry) {
        pthread_mutex_lock(&collection->lock);
        entry->value = new_value;
        pthread_mutex_unlock(&collection->lock);
        return 0; // Success
    }

    return -1; // Entry not found
}

int main() {
    EntryCollection *collection = create_entry_collection(10);
    if (!collection) {
        fprintf(stderr, "Failed to create entry collection\n");
        return EXIT_FAILURE;
    }

    insert_entry(collection, "First Entry");
    insert_entry(collection, "Second Entry");

    Entry *entry = get_entry_by_id(collection, 1);
    if (entry) {
        printf("ID: %d, Value: %.2f, Name: %s\n", entry->id, entry->value, entry->name);
    }

    update_entry_value(collection, 1, 99.9);

    free_entry_collection(collection);
    return EXIT_SUCCESS;
}
