['```cpp
#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <mutex>
#include <thread>
#include <chrono>
#include <stdexcept>
#include <nlohmann/json.hpp>  // External JSON library (e.g., nlohmann/json)
#include <cpprest/http_listener.h>  // For handling HTTP requests

namespace web {
    using namespace utility;                    // Common utilities like string conversions
    using namespace web;                         // Common features like URIs.
    using namespace web::http;                   // Common HTTP functionality
    using namespace web::http::experimental::listener;// HTTP server
}

class Entry {
public:
    int id;
    double value;
    std::string* name;

    Entry(int identifier, double val, const std::string& str)
        : id(identifier), value(val), name(new std::string(str)) {}

    ~Entry() { delete name; }
};

template <typename T>
class DynamicCollection {
private:
    std::vector<Entry> entries;
    std::mutex mtx;

public:
    DynamicCollection(size_t initialSize, double minValue, double maxValue) {
        if (initialSize <= 0) throw std::invalid_argument("Size must be positive.");
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(minValue, maxValue);

        for (size_t i = 1; i <= initialSize; ++i) {
            try {
                entries.emplace_back(i, dis(gen), "DefaultName");
            } catch (const std::bad_alloc& e) {
                throw std::runtime_error("Memory allocation failed: " + std::string(e.what()));
            }
        }
    }

    void threadSafeAddEntry(int id, double value, const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx);
        entries.emplace_back(id, value, name);
    }

    int findMaxId() const {
        if (entries.empty()) return 0;
        int maxId = entries[0].id;
        for (const auto& entry : entries) {
            if (entry.id > maxId) maxId = entry.id;
        }
        return maxId;
    }

    // Handle HTTP PUT request
    void handlePutRequest(web::http::http_request req) {
        try {
            auto body = std::move(req.extract_json().get());
            int id = body["id"].get<int>();
            double value = body["value"].get<double>();
            std::string name = body["name"].get<std::string>();

            std::lock_guard<std::mutex> lock(mtx);
            for (auto& entry : entries) {
                if (entry.id == id) {
                    entry.value = value;
                    *entry.name = name;
                    break;
                }
            }

            web::http::http_response response(web::http::status_codes::OK);
            response.to_json() << nlohmann::json{{"message", "Updated successfully"}};
            req.reply(response);

        } catch (const std::exception& e) {
            web::http::http_response response(web::http::status_codes::BAD_REQUEST);
            response.set_body(std::string("Error: ") + e.what());
            req.reply(response);
        }
    }

    // Handle HTTP DELETE request
    void handleDeleteRequest(web::http::http_request req) {
        try {
            auto body = std::move(req.extract_json().get());
            int id = body["id"].get<int>();

            std::lock_guard<std::mutex> lock(mtx);
            entries.erase(std::remove_if(entries.begin(), entries.end(),
                                        [id](const Entry& entry) { return entry.id == id; }),
                          entries.end());

            web::http::http_response response(web::http::status_codes::OK);
            response.to_json() << nlohmann::json{{"message", "Deleted successfully"}};
            req.reply(response);

        } catch (const std::exception& e) {
            web::http::http_response response(web::http::status_codes::BAD_REQUEST);
            response.set_body(std::string("Error: ") + e.what());
            req.reply(response);
        }
    }

    void log(const std::string& message) const {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())
                  << "] " << message << std::endl;
    }
};

int main() {
    try {
        DynamicCollection<double> collection(10, 0.0, 100.0);

        // Simulate a web server setup
        web::http_listener listener("http://localhost:8080/api/entries");

        auto handler = [](web::http_request request) {
            if (request.method() == web::http::methods::HTTP_PUT) {
                collection.handlePutRequest(request);
            } else if (request.method() == web::http::methods::HTTP_DELETE) {
                collection.handleDeleteRequest(request);
            } else {
                web::http::http_response response(web::http::status_codes::METHOD_NOT_ALLOWED);
                request.reply(response);
            }
        };

        listener.support(methods::PUT, handler);
        listener.support(methods::DELETE, handler);

        listener.open().wait();
        std::cout << "Listening on http://localhost:8080/api/entries" << std::endl;

        // Keep the server running
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

