typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Function prototypes
void free_resources(long* offsets, int* keys, Record* records, Node** head);
int compare_keys(const void *a, const void *b);

void initialize_data(const char* csv_file_path) {
    FILE *file = fopen(csv_file_path, "r");
    if (!file) {
        perror("File opening failed");
        return;
    }

    // Estimate number of lines
    fseek(file, 0, SEEK_END);
    long num_lines = ftell(file) / (sizeof(char) * 100); // Assume average line length
    rewind(file);

    long* offsets = malloc(num_lines * sizeof(long));
    int* keys = malloc(num_lines * sizeof(int));
    Record* records = malloc(num_lines * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free_resources(offsets, keys, records, NULL);
        fclose(file);
        return;
    }

    Node* head = NULL;

    for (long i = 0; i < num_lines && fscanf(file, "%ld,%d\n", &offsets[i], &keys[i]) == 2; ++i) {
        srand(time(NULL) + i); // Seed based on current time and index
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = (double)(rand() % 1000) / 10.0;

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation for node failed");
            free_resources(offsets, keys, records, &head);
            fclose(file);
            return;
        }

        new_node->record = records[i];
        new_node->next = head;
        head = new_node;
    }

    // Sort records based on 'key' using qsort
    qsort(records, num_lines, sizeof(Record), compare_keys);

    // Handle duplicates by merging or other logic if needed

    // Clean up resources once processing is done
    fclose(file);
}

int compare_keys(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;
    return recordA->key - recordB->key;
}

void free_resources(long* offsets, int* keys, Record* records, Node** head) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);

    while (*head) {
        Node *temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
```

This code defines a C function to load, initialize, and sort records from a CSV file. It uses dynamic memory allocation for arrays of `long`, `int`, and `Record` structures and manages an auxiliary linked list sorted by keys. Memory is freed appropriately to avoid leaks, with performance considerations such as using `qsort` for efficient sorting. The code reads from the given CSV file path, assumes a maximum average line length for estimating the number of lines, and allocates memory accordingly.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* create_node(Record rec) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->record = rec;
    node->next = NULL;
    return node;
}

void insert_sorted(Node** head, Record rec) {
    Node* new_node = create_node(rec);
    if (!new_node) return;

    if (*head == NULL || (*head)->record.key >= rec.key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->record.key < rec.key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void free_linked_list(Node** head) {
    Node* temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int load_records(const char* filename, long* offsets, int* keys, Record* records, size_t max_size, Node** sorted_head) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    size_t count = 0;
    while (fscanf(file, "%ld %d %lf\n", &offsets[count], &keys[count], &records[count].value) == 3) {
        records[count].key = keys[count];
        records[count].offset = offsets[count];
        if (++count >= max_size) break;
    }

    fclose(file);

    for (size_t i = 0; i < count; ++i) {
        insert_sorted(sorted_head, records[i]);
    }

    return count;
}

void manage_memory_and_load(const char* filename, size_t max_records) {
    long* offsets = (long*)calloc(max_records, sizeof(long));
    int* keys = (int*)calloc(max_records, sizeof(int));
    Record* records = (Record*)malloc(max_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    Node* sorted_head = NULL;

    int record_count = load_records(filename, offsets, keys, records, max_records, &sorted_head);

    if (record_count < 0) {
        printf("Error loading records\n");
    } else {
        // Process the loaded and sorted records
        Node* current = sorted_head;
        while (current) {
            printf("Offset: %ld, Key: %d, Value: %.2f\n", current->record.offset, current->record.key, current->record.value);
            current = current->next;
        }
    }

    free_linked_list(&sorted_head);
    free(offsets);
    free(keys);
    free(records);
}
