#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

typedef struct record {
    int key;
    long *offset;
    double *value;
    struct record *next;
} record;

record *head = NULL;
double *values_array;
size_t values_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void load_csv(const char *filename);
void merge_records(record **head, int key, long offset, double value);
record* create_record(int key, long offset, double value);
void cleanup();
int retrieve_by_index(size_t index, record **result);

// Helper functions
double random_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

int main() {
    srand(time(NULL));

    // Load data from CSV file
    load_csv("data.csv");

    // Simulate retrieval
    record *result;
    if (retrieve_by_index(5, &result)) {
        printf("Retrieved value: %f\n", *(result->value));
    }

    // Cleanup
    cleanup();

    return 0;
}

void load_csv(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int key;
        long offset;
        double value;

        // Parse CSV line
        sscanf(line, "%d,%ld,%lf", &key, &offset, &value);

        pthread_mutex_lock(&lock);
        merge_records(&head, key, offset, value);
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
}

void merge_records(record **head, int key, long offset, double value) {
    record *current = *head;
    while (current != NULL) {
        if (current->key == key) {
            // Merge by averaging the values
            *(current->value) = (*(current->value) + value) / 2.0;
            return;
        }
        current = current->next;
    }

    // Create a new record if no match found
    record *new_record = create_record(key, &offset, &value);
    new_record->next = *head;
    *head = new_record;
}

record* create_record(int key, long *offset, double *value) {
    record *new_rec = (record *)malloc(sizeof(record));
    if (!new_rec) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    new_rec->key = key;
    new_rec->offset = offset;
    new_rec->value = value;

    // Allocate space in the values array
    size_t index = values_count++;
    if (index >= values_count) {
        values_array = realloc(values_array, sizeof(double) * values_count);
        if (!values_array) {
            perror("Failed to allocate memory for values array");
            exit(EXIT_FAILURE);
        }
    }

    *(new_rec->value) = random_double(1.0, 100.0); // Initialize with a random value
    return new_rec;
}

void cleanup() {
    pthread_mutex_lock(&lock);

    record *current = head;
    while (current != NULL) {
        record *temp = current;
        current = current->next;
        free(temp);
    }

    if (values_array) {
        free(values_array);
    }

    pthread_mutex_unlock(&lock);
}

int retrieve_by_index(size_t index, record **result) {
    pthread_mutex_lock(&lock);

    size_t count = 0;
    record *current = head;
    while (current != NULL) {
        if (count == index) {
            *result = current;
            pthread_mutex_unlock(&lock);
            return 1; // Success
        }
        current = current->next;
        count++;
    }

    pthread_mutex_unlock(&lock);
    return 0; // Failure
}
```

