const char* error_messages[] = {
    "Success",
    "Unsupported Image Format",
    "File I/O Error",
    "Memory Allocation Error"
};

ErrorCode processImage(const char *filename, unsigned char **md5_hash) {
    TIFF *tiff_file = TIFFOpen(filename, "r");
    if (!tiff_file) {
        log_message("Error opening file.");
        return ERROR_FILE_IO;
    }

    ImageMetadata metadata = {0};
    uint32_t bits_per_sample, samples_per_pixel, extra_samples;

    if (TIFFGetField(tiff_file, TIFFTAG_BITSPERSAMPLE, &bits_per_sample) &&
        TIFFGetField(tiff_file, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel)) {
        metadata.bits_per_sample = bits_per_sample;
        metadata.samples_per_pixel = samples_per_pixel;

        if (TIFFGetField(tiff_file, TIFFTAG_EXTRASAMPLES, &extra_samples) == 1) {
            metadata.extra_samples = extra_samples / sizeof(uint32_t); // Each entry is uint32
        } else {
            metadata.extra_samples = 0;
        }

        if (bits_per_sample != 8 && bits_per_sample != 16 &&
            bits_per_sample != 32 && bits_per_sample != 64) {
            log_message("Unsupported bits per sample.");
            TIFFClose(tiff_file);
            return ERROR_UNSUPPORTED_FORMAT;
        }
    } else {
        log_message("Missing essential metadata.");
        TIFFClose(tiff_file);
        return ERROR_UNSUPPORTED_FORMAT;
    }

    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);

    uint32_t width, height;
    TIFFGetField(tiff_file, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tiff_file, TIFFTAG_IMAGELENGTH, &height);

    size_t row_size = TIFFScanlineSize(tiff_file);
    if (row_size == 0) {
        log_message("Invalid scanline size.");
        TIFFClose(tiff_file);
        return ERROR_UNSUPPORTED_FORMAT;
    }

    *md5_hash = malloc(MD5_DIGEST_LENGTH);
    if (*md5_hash == NULL) {
        log_message("Memory allocation failed for MD5 hash.");
        TIFFClose(tiff_file);
        return ERROR_MEMORY_ALLOCATION;
    }

    unsigned char buffer[row_size];
    for (uint32_t row = 0; row < height; ++row) {
        if (TIFFReadScanline(tiff_file, buffer, row, 0) == -1) {
            log_message("Error reading scanline.");
            free(*md5_hash);
            TIFFClose(tiff_file);
            return ERROR_FILE_IO;
        }
        MD5_Update(&md5_ctx, buffer, row_size);
    }

    MD5_Final(*md5_hash, &md5_ctx);

    TIFFClose(tiff_file);
    log_message("Image processed successfully.");
    return SUCCESS;
}

// Example usage
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <tiff_filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    unsigned char *md5_hash = NULL;
    ErrorCode result = processImage(argv[1], &md5_hash);

    if (result == SUCCESS) {
        printf("MD5 hash: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            printf("%02x", md5_hash[i]);
        }
        printf("\n");
        free(md5_hash);
    } else {
        fprintf(stderr, "Error processing image: %s\n", error_messages[result]);
        if (md5_hash != NULL) {
            free(md5_hash);
        }
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

### Explanation:
- **Memory Management**: Uses dynamic allocation for MD5 hash and TIFF scanline buffer, ensuring efficient memory usage.
- **Error Handling**: Provides detailed error codes/messages, logging errors to a file.
- **Concurrency Support**: Thread-safe as it doesn't modify shared state; consider using mutexes if extended.
- **Logging**: Logs important events and errors with timestamps.
- **Testing**: Write test cases for different TIFF files, including unsupported formats and large files.']

