#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double value;
    int *key_ptr;
    long *offset_ptr;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
} index_t;

// Function prototypes
void init_index(index_t *index, size_t initial_capacity);
void free_index(index_t *index);
int add_record(index_t *index, double value, int key, long offset);
record* get_record(index_t *index, int index_pos);
int update_record(index_t *index, int index_pos, double new_value);
int delete_record(index_t *index, int index_pos);

void init_index(index_t *index, size_t initial_capacity) {
    pthread_rwlock_init(&index->lock, NULL);
    index->capacity = initial_capacity;
    index->count = 0;

    index->offsets = malloc(sizeof(long) * initial_capacity);
    if (!index->offsets) {
        perror("Failed to allocate offsets array");
        exit(EXIT_FAILURE);
    }

    index->keys = malloc(sizeof(int) * initial_capacity);
    if (!index->keys) {
        free(index->offsets);
        perror("Failed to allocate keys array");
        exit(EXIT_FAILURE);
    }

    index->records = malloc(sizeof(record*) * initial_capacity);
    if (!index->records) {
        free(index->keys);
        free(index->offsets);
        perror("Failed to allocate records array");
        exit(EXIT_FAILURE);
    }
}

void resize_index(index_t *index, size_t new_capacity) {
    index->offsets = realloc(index->offsets, sizeof(long) * new_capacity);
    if (!index->offsets) {
        perror("Failed to reallocate offsets array");
        exit(EXIT_FAILURE);
    }

    index->keys = realloc(index->keys, sizeof(int) * new_capacity);
    if (!index->keys) {
        free(index->offsets);
        perror("Failed to reallocate keys array");
        exit(EXIT_FAILURE);
    }

    index->records = realloc(index->records, sizeof(record*) * new_capacity);
    if (!index->records) {
        free(index->keys);
        free(index->offsets);
        perror("Failed to reallocate records array");
        exit(EXIT_FAILURE);
    }

    index->capacity = new_capacity;
}

void free_index(index_t *index) {
    pthread_rwlock_destroy(&index->lock);

    for (size_t i = 0; i < index->count; ++i) {
        free(index->records[i]->key_ptr);
        free(index->records[i]->offset_ptr);
        free(index->records[i]);
    }

    free(index->records);
    free(index->keys);
    free(index->offsets);
}

int add_record(index_t *index, double value, int key, long offset) {
    pthread_rwlock_wrlock(&index->lock);

    if (index->count == index->capacity) {
        size_t new_capacity = index->capacity * 2;
        resize_index(index, new_capacity);
    }

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        perror("Failed to allocate new record");
        pthread_rwlock_unlock(&index->lock);
        return -1; // Error
    }

    new_record->value = value;
    new_record->key_ptr = malloc(sizeof(int));
    new_record->offset_ptr = malloc(sizeof(long));

    if (!new_record->key_ptr || !new_record->offset_ptr) {
        perror("Failed to allocate pointers in record");
        free(new_record);
        pthread_rwlock_unlock(&index->lock);
        return -1; // Error
    }

    *new_record->key_ptr = key;
    *new_record->offset_ptr = offset;

    index->records[index->count] = new_record;
    index->keys[index->count] = key;
    index->offsets[index->count] = offset;

    ++index->count;
    pthread_rwlock_unlock(&index->lock);
    return 0; // Success
}

record* get_record(index_t *index, int index_pos) {
    if (index_pos < 0 || index_pos >= (int)index->count) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    pthread_rwlock_rdlock(&index->lock);
    record *result = index->records[index_pos];
    pthread_rwlock_unlock(&index->lock);
    return result;
}

int update_record(index_t *index, int index_pos, double new_value) {
    if (index_pos < 0 || index_pos >= (int)index->count) {
        fprintf(stderr, "Index out of bounds\n");
        return -1; // Error
    }

    pthread_rwlock_wrlock(&index->lock);
    record *rec = index->records[index_pos];
    rec->value = new_value;
    pthread_rwlock_unlock(&index->lock);
    return 0; // Success
}

int delete_record(index_t *index, int index_pos) {
    if (index_pos < 0 || index_pos >= (int)index->count) {
        fprintf(stderr, "Index out of bounds\n");
        return -1; // Error
    }

    pthread_rwlock_wrlock(&index->lock);
    free(index->records[index_pos]->key_ptr);
    free(index->records[index_pos]->offset_ptr);
    free(index->records[index_pos]);

    for (size_t i = index_pos; i < index->count - 1; ++i) {
        index->records[i] = index->records[i + 1];
        index->keys[i] = index->keys[i + 1];
        index->offsets[i] = index->offsets[i + 1];
    }

    --index->count;
    pthread_rwlock_unlock(&index->lock);
    return 0; // Success
}
```']

