#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    char str1[256];
    char str2[256];
} Metadata;

typedef struct {
    int value;
    long* offset;
    int* key;
    char* purpose;
    bool initialized;
    Metadata metadata;
} Record;

typedef struct {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_memory_usage;
    const size_t memory_threshold;
} RecordsManager;

static unsigned long lrand48_seed = 0L;

unsigned int seed_random(unsigned int seed) {
    lrand48_seed = (seed ^ 0x5DEECE66DL) & ((1UL << 48) - 1);
    return (unsigned int)(lrand48_seed >> 16) % RAND_MAX;
}

long get_offset() {
    return (long)(lrand48() % 1000000);
}

int get_key() {
    return rand();
}

RecordsManager* initializeAndManageRecords(size_t initial_capacity, unsigned int range_min, unsigned int range_max, size_t memory_threshold) {
    RecordsManager* manager = malloc(sizeof(RecordsManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->records = calloc(initial_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->total_memory_usage = 0;
    manager->memory_threshold = memory_threshold;

    for (size_t i = 0; i < initial_capacity; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) goto error_cleanup;

        record->value = seed_random(range_min + rand() % (range_max - range_min + 1));
        record->offset = malloc(sizeof(long));
        if (!record->offset) goto error_single_record_cleanup;

        *record->offset = get_offset();

        record->key = malloc(sizeof(int));
        if (!record->key) goto error_single_record_cleanup_2;

        *record->key = get_key();

        record->purpose = strdup("Initial Purpose");
        if (!record->purpose) goto error_single_record_cleanup_3;

        strcpy(record->metadata.str1, "Metadata1");
        strcpy(record->metadata.str2, "Metadata2");

        record->initialized = true;

        manager->records[i] = record;
        manager->total_memory_usage += sizeof(Record*) + sizeof(Record) + strlen(record->purpose) + 1;

        if (manager->total_memory_usage > manager->memory_threshold) {
            fprintf(stderr, "Warning: Memory usage exceeded threshold.\n");
        }
    }

    return manager;

error_single_record_cleanup_3:
    free(record->key);
error_single_record_cleanup_2:
    free(record->offset);
error_single_record_cleanup:
    free(record);
error_cleanup:
    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = manager->records[i];
        if (record) {
            free(record->key);
            free(record->offset);
            free(record->purpose);
            free(record);
        }
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
    return NULL;
}

Record* get_record(RecordsManager* manager, size_t index) {
    if (!manager || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    Record* record = manager->records[index];
    pthread_mutex_unlock(&manager->lock);

    return record;
}

void append_record(RecordsManager* manager, int value, char* purpose_str) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Error: Memory allocation for new record failed.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    record->value = value;
    record->offset = malloc(sizeof(long));
    if (!record->offset) goto error_append_cleanup;

    *record->offset = get_offset();

    record->key = malloc(sizeof(int));
    if (!record->key) goto error_single_record_cleanup_4;

    *record->key = get_key();

    record->purpose = strdup(purpose_str);
    if (!record->purpose) goto error_single_record_cleanup_5;

    strcpy(record->metadata.str1, "NewMetadata1");
    strcpy(record->metadata.str2, "NewMetadata2");

    record->initialized = true;

    manager->records[manager->count++] = record;
    manager->total_memory_usage += sizeof(Record*) + sizeof(Record) + strlen(purpose_str) + 1;

    if (manager->total_memory_usage > manager->memory_threshold) {
        fprintf(stderr, "Warning: Memory usage exceeded threshold.\n");
    }

    pthread_mutex_unlock(&manager->lock);
    return;

error_single_record_cleanup_5:
    free(record->key);
error_single_record_cleanup_4:
    free(record->offset);
error_append_cleanup:
    free(record);

    pthread_mutex_unlock(&manager->lock);
}

// Serialization and Deserialization functions (simplified example)
int serialize_records(const RecordsManager* manager, const char* filename) {
    if (!manager || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = manager->records[i];
        if (record) {
            fwrite(&record->value, sizeof(int), 1, file);
            fwrite(record->offset, sizeof(long), 1, file);
            fwrite(record->key, sizeof(int), 1, file);
            size_t purpose_length = strlen(record->purpose) + 1;
            fwrite(&purpose_length, sizeof(size_t), 1, file);
            fwrite(record->purpose, sizeof(char), purpose_length, file);
        }
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return 0;
}

RecordsManager* deserialize_records(const char* filename) {
    if (!filename) return NULL;

    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    RecordsManager* manager = malloc(sizeof(RecordsManager));
    if (!manager) goto error;

    size_t record_count;
    fread(&record_count, sizeof(size_t), 1, file);

    manager->records = calloc(record_count, sizeof(Record*));
    if (!manager->records) goto error_cleanup;

    manager->count = record_count;
    manager->capacity = record_count;
    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < record_count; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) goto error_single_record_cleanup;

        fread(&record->value, sizeof(int), 1, file);

        record->offset = malloc(sizeof(long));
        if (!record->offset) goto error_single_record_cleanup_6;

        fread(record->offset, sizeof(long), 1, file);

        record->key = malloc(sizeof(int));
        if (!record->key) goto error_single_record_cleanup_7;

        fread(record->key, sizeof(int), 1, file);

        size_t purpose_length;
        fread(&purpose_length, sizeof(size_t), 1, file);

        record->purpose = malloc(purpose_length);
        if (!record->purpose) goto error_single_record_cleanup_8;

        fread(record->purpose, sizeof(char), purpose_length, file);

        strcpy(record->metadata.str1, "DeserializedMetadata1");
        strcpy(record->metadata.str2, "DeserializedMetadata2");

        record->initialized = true;

        manager->records[i] = record;
    }

    fclose(file);
    return manager;

error_single_record_cleanup_8:
    free(record->key);
error_single_record_cleanup_7:
    free(record->offset);
error_single_record_cleanup_6:
    free(record);
error_single_record_cleanup:
    for (size_t i = 0; i < i; ++i) {
        Record* record = manager->records[i];
        if (record) {
            free(record->key);
            free(record->offset);
            free(record->purpose);
            free(record);
        }
    }
error_cleanup:
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
error:
    fclose(file);
    return NULL;
}

void cleanup_records(RecordsManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = manager->records[i];
        if (record) {
            free(record->key);
            free(record->offset);
            free(record->purpose);
            free(record);
        }
    }

    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
