typedef struct {
    char message[256]; // Assuming fixed size for simplicity; can be dynamically managed if needed.
    int severity;
    float *metric;
} log_entry;

log_entry* create_log_entries(size_t num_entries, float min_metric_value, float max_metric_value) {
    log_entry *entries = (log_entry *)malloc(num_entries * sizeof(log_entry));
    if (!entries) return NULL; // Handle memory allocation failure

    srand(time(NULL)); // Seed for random number generation
    for (size_t i = 0; i < num_entries; ++i) {
        entries[i].metric = (float *)malloc(sizeof(float));
        if (!entries[i].metric) { // Handle memory allocation failure
            // Cleanup previously allocated memory before returning NULL
            while (--i >= 0) free(entries[i].metric);
            free(entries);
            return NULL;
        }
        // Initialize the message and severity for demonstration purposes
        snprintf(entries[i].message, sizeof(entries[i].message), "Log Message %zu", i + 1);
        entries[i].severity = rand() % 10; // Severity level between 0 and 9
        *entries[i].metric = min_metric_value + (rand() / (float)RAND_MAX) * (max_metric_value - min_metric_value);
    }

    return entries;
}

void cleanup_log_entries(log_entry *entries, size_t num_entries) {
    if (!entries) return;

    for (size_t i = 0; i < num_entries; ++i) {
        free(entries[i].metric); // Free each allocated metric
    }

    free(entries); // Free the array of log entries
}
