```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

void allocate_and_initialize(long n, long min_value, long max_value, size_t memory_budget) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    const size_t sizeof_long = sizeof(long);
    const size_t sizeof_int = sizeof(int);
    const size_t sizeof_record = sizeof(record);

    // Calculate the total memory required
    size_t total_memory_required = n * (sizeof_long + sizeof_int + sizeof_record);

    // Determine the maximum allowable `n` based on the budget
    long max_n = n;
    while (total_memory_required > memory_budget && max_n > 0) {
        --max_n;
        total_memory_required = max_n * (sizeof_long + sizeof_int + sizeof_record);
    }

    if (max_n == 0) {
        printf("Memory budget too low, cannot allocate any data.\n");
        pthread_mutex_destroy(&lock);
        return;
    }

    // Resize n to fit within the memory_budget
    n = max_n;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    pthread_mutex_lock(&lock);

    offsets = (long *)malloc(n * sizeof_long);
    keys = (int *)malloc(n * sizeof_int);
    records = (record *)malloc(n * sizeof_record);

    if (!offsets || !keys || !records) {
        printf("Failed to allocate memory.\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return;
    }

    // Initialize records with random values
    srand((unsigned int)time(NULL));
    for (long i = 0; i < n; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    pthread_mutex_unlock(&lock);

    // Simulate external data source handling
    if (!simulate_external_data_source()) {
        printf("External data source failure handled gracefully.\n");
    }

    // Properly free memory at the end of function
    pthread_mutex_lock(&lock);

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

int simulate_external_data_source() {
    // Simulate a scenario where external data source might fail or delay
    return rand() % 2; // Randomly simulate success (1) or failure (0)
}
```

### Key Features:
- **Dynamic Allocation:** Allocates memory for arrays of `long` and `int`, as well as an array of `record` structures, while ensuring the total usage does not exceed `memory_budget`.
- **Thread Safety:** Uses a mutex to ensure that memory allocation and initialization are thread-safe.
- **Memory Management:** Ensures all allocated memory is freed, even if allocation fails partway through.
- **Error Handling:** Simulates handling failures from external data sources without crashing.']

