record* create_records(size_t num_records, int min_val, int max_val, const char *external_data[], size_t data_size);
int find_record_by_key(record *records, size_t count, int key);
void update_record(record *r, int new_value, const char *new_buffer);
void delete_record_soft(record *r);

// Helper function to generate random number
static int rand_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* create_records(size_t num_records, int min_val, int max_val, const char *external_data[], size_t data_size) {
    if (num_records == 0 || data_size == 0 || external_data == NULL) return NULL;

    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand_range(min_val, max_val);

        // Ensure we do not exceed the buffer size
        strncpy(records[i].buffer, external_data[i % data_size], sizeof(records[i].buffer) - 1);
        records[i].buffer[sizeof(records[i].buffer) - 1] = '\0';

        // Example of linking to an external data source (could be a pointer to another struct)
        records[i].data_source = NULL;  // Placeholder, should point to actual data source
    }

    return records;
}

int find_record_by_key(record *records, size_t count, int key) {
    if (!records || count == 0) return -1;

    for (size_t i = 0; i < count; ++i) {
        if (records[i].value == key) {
            return i;
        }
    }

    return -1;  // Not found
}

void update_record(record *r, int new_value, const char *new_buffer) {
    if (!r || !new_buffer) return;

    // Example validation: ensure the buffer is not too large
    if (strlen(new_buffer) < sizeof(r->buffer)) {
        r->value = new_value;
        strncpy(r->buffer, new_buffer, sizeof(r->buffer) - 1);
        r->buffer[sizeof(r->buffer) - 1] = '\0';
    }
}

void delete_record_soft(record *r) {
    if (!r) return;

    // Mark as deleted by setting an invalid value (could also use a flag)
    r->value = INT_MIN;
}

// Example usage
int main() {
    srand(time(NULL));

    const char *external_data[] = {"Data1", "Data2", "Data3"};
    size_t data_size = sizeof(external_data) / sizeof(external_data[0]);

    record *records = create_records(5, 10, 100, external_data, data_size);
    if (!records) {
        printf("Failed to allocate memory for records.\n");
        return EXIT_FAILURE;
