        printf("Record found at index %d with value %d\n", index, records[index].value);
    } else {
        printf("Record not found.\n");
    }

    // Example update
    update_record(&records[0], 200, "UpdatedData");

    // Soft delete example
    delete_record_soft(&records[1]);

    free(records);
    return EXIT_SUCCESS;
}
