#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 10

typedef struct {
    char message[256];
    int severity_level;
    float* value_ptr;
    const char* file_path;
} log_entry;

// Thread lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resources(float *float_values, unsigned long *timestamps, log_entry **log_entries, int *error_codes) {
    if (float_values) free(float_values);
    if (timestamps) free(timestamps);
    if (log_entries) {
        for (int i = 0; i < MAX_ENTRIES; ++i) {
            if (log_entries[i]) free(log_entries[i]->value_ptr); // Free the float pointer
            free(log_entries[i]);                              // Free the log_entry structure
        }
        free(log_entries);
    }
    if (error_codes) free(error_codes);
}

int initialize_data_structures(size_t max_size, const char *log_file_path) {
    pthread_mutex_lock(&lock);

    float *float_values = malloc(max_size * sizeof(float));
    unsigned long *timestamps = malloc(max_size * sizeof(unsigned long));
    log_entry **log_entries = malloc(max_size * sizeof(log_entry*));
    int *error_codes = malloc(max_size * sizeof(int));

    if (!float_values || !timestamps || !log_entries || !error_codes) {
        free_resources(float_values, timestamps, log_entries, error_codes);
        pthread_mutex_unlock(&lock);
        return -1; // Error code for insufficient resources
    }

    srand(time(NULL));  // Seed random number generator

    FILE *log_file = fopen(log_file_path, "a+");

    if (!log_file) {
        free_resources(float_values, timestamps, log_entries, error_codes);
        pthread_mutex_unlock(&lock);
        return -2; // Error code for file open failure
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);

    if (file_size > MAX_ENTRIES * sizeof(log_entry)) {
        long offset = file_size - MAX_ENTRIES * sizeof(log_entry);
        fseek(log_file, offset, SEEK_SET);
        setvbuf(log_file, NULL, _IOFBF, 0); // Switch to unbuffered for precise operations
        int c;
        while ((c = fgetc(log_file)) != EOF) {} // Truncate file
    }

    for (size_t i = 0; i < max_size; ++i) {
        float_values[i] = ((float)rand() / RAND_MAX) * 100.0f; // Random float value within range [0, 100]
        timestamps[i] = time(NULL);                             // Current timestamp
        log_entries[i] = malloc(sizeof(log_entry));

        if (!log_entries[i]) {
            free_resources(float_values, timestamps, log_entries, error_codes);
            fclose(log_file);
            pthread_mutex_unlock(&lock);
            return -3; // Error code for memory allocation failure
        }

        log_entries[i]->value_ptr = &float_values[i];           // Assign pointer to float value
        snprintf(log_entries[i]->message, sizeof(log_entries[i]->message), "Log entry %zu", i);
        log_entries[i]->severity_level = rand() % 5;            // Random severity level [0-4]
        log_entries[i]->file_path = log_file_path;

        fprintf(log_file, "Entry: %s, Severity: %d\n", log_entries[i]->message, log_entries[i]->severity_level);
    }

    fclose(log_file);

    pthread_mutex_unlock(&lock);

    // Periodic integrity check (could be moved to a background thread in practice)
    if (!log_file_path) {
        fprintf(stderr, "Log file path is not set for integrity checks.\n");
        free_resources(float_values, timestamps, log_entries, error_codes);
        return -4; // Error code for failed integrity check
    }

    return 0;
}

// Example documentation
/*
 * Function: initialize_data_structures
 *
 * Initializes and manages four data structures with dynamic memory allocation:
 * 1. An array of floats
 * 2. An array of unsigned long timestamps
 * 3. An array of pointers to log_entry structs
 * 4. An array of error codes (integers)
 *
 * Parameters:
 * - max_size: The maximum number of elements for each data structure.
 * - log_file_path: Path to the log file where entries are recorded.
 *
 * Returns:
 * - 0 on successful initialization and memory allocation.
 * - Negative error codes indicate various failures:
 *   - -1: Insufficient resources (requested size exceeds max allowed).
 *   - -2: Unable to open or create the specified log file.
 *   - -3: Memory allocation failure during setup of log entries.
 *   - -4: Log integrity checks failed due to missing file path.
 *
 * Behavior in edge cases:
 * - If the requested `max_size` exceeds limits, returns an error code immediately.
 * - When called concurrently by multiple threads, uses a mutex lock to ensure data consistency.
 * - For log files exceeding max retention size, old entries are trimmed appropriately.
 */
```']

