```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
} log_severity_t;

struct log_entry {
    char message[256];
    log_severity_t severity;
    float metric;
};

// Mutex for thread-safe operations
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

struct log_entry* create_log_entries(int num_entries, int min_metric, int max_metric) {
    struct log_entry* entries = (struct log_entry*)malloc(num_entries * sizeof(struct log_entry));
    if (!entries) return NULL;

    for (int i = 0; i < num_entries; ++i) {
        snprintf(entries[i].message, sizeof(entries[i].message), "Log entry %d", i);
        entries[i].severity = LOG_INFO;
        entries[i].metric = min_metric + rand() % (max_metric - min_metric + 1);
    }

    return entries;
}

void destroy_log_entries(struct log_entry* entries) {
    if (entries) {
        free(entries);
    }
}

void update_log_entries(struct log_entry* entries, int index, const char* message, int severity, float metric) {
    pthread_mutex_lock(&log_mutex);
    if (index >= 0 && entries[index].message) {
        strncpy(entries[index].message, message, sizeof(entries[index].message) - 1);
        entries[index].severity = (log_severity_t)severity;
        entries[index].metric = metric;
    }
    pthread_mutex_unlock(&log_mutex);
}

void process_log_entries(struct log_entry* entries, void (*callback)(const struct log_entry*)) {
    if (!entries || !callback) return;

    for (int i = 0; entries[i].message[0] != '\0'; ++i) {
        callback(&entries[i]);
    }
}

// Example callback function
void example_callback(const struct log_entry* entry) {
    printf("Message: %s\n", entry->message);
    printf("Severity: %d\n", entry->severity);
    printf("Metric: %.2f\n", entry->metric);
}

int main() {
    int num_entries = 10;
    int min_metric = 1, max_metric = 100;

    struct log_entry* entries = create_log_entries(num_entries, min_metric, max_metric);

    if (entries) {
        update_log_entries(entries, 0, "Updated log entry", LOG_ERROR, 99.9);
        process_log_entries(entries, example_callback);
        destroy_log_entries(entries);
    }

    return 0;
}
```

This code provides a basic framework for managing log entries with thread-safe operations and supports updating and processing log entries using callbacks. The `example_callback` function demonstrates how to handle each log entry during processing. Adjustments may be necessary depending on specific application requirements and performance considerations.']

