#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t n;
    pthread_mutex_t lock;
} metadata;

// Function to safely allocate memory and handle failures
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for %zu bytes\n", size);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

metadata* create_metadata(size_t n, size_t memory_budget) {
    // Calculate sizes
    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);
    size_t record_size = sizeof(record);

    // Initial total memory needed
    size_t initial_memory_needed = n * (long_size + int_size + record_size);

    if (n == 0 || initial_memory_needed > memory_budget) {
        size_t max_n = memory_budget / (long_size + int_size + record_size);
        if (max_n < 1) {
            fprintf(stderr, "Memory budget too small for even one element\n");
            return NULL;
        }
        n = max_n; // Adjust n to fit within the budget
    }

    // Allocate memory with adjusted n
    metadata *meta = safe_malloc(sizeof(metadata));
    pthread_mutex_init(&meta->lock, NULL);

    size_t total_memory_needed = n * (long_size + int_size + record_size);

    meta->offsets = safe_malloc(n * long_size);
    meta->keys = safe_malloc(n * int_size);
    meta->records = safe_malloc(n * record_size);
    meta->n = n;

    return meta;
}

void free_metadata(metadata *meta) {
    if (meta == NULL) return;

    pthread_mutex_lock(&meta->lock);

    free(meta->offsets);
    free(meta->keys);
    free(meta->records);

    pthread_mutex_unlock(&meta->lock);
    pthread_mutex_destroy(&meta->lock);

    free(meta);
}

int main() {
    size_t memory_budget = 1024; // Example budget in bytes
    metadata *meta = create_metadata(10, memory_budget); // Initial request for 10 elements

    if (meta != NULL) {
        printf("Metadata created with %zu elements\n", meta->n);

        // Free allocated resources
        free_metadata(meta);
    }

    return 0;
}
```

