#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
} data_source;

typedef struct {
    int key;
    long offset;
    data_source* src;
    int deleted; // Soft deletion flag
} record;

// Function prototypes
void initialize_records(record** records, size_t capacity);
int add_record(record** records, size_t* size, size_t* capacity, int key, long offset, int value_range);
record* find_record(record* records, size_t size, int key);
void delete_record(record* records, size_t size, int key);
void resize_records(record** records, size_t* size, size_t* capacity);

void initialize_records(record** records, size_t capacity) {
    *records = (record*)malloc(capacity * sizeof(record));
}

int add_record(record** records, size_t* size, size_t* capacity, int key, long offset, int value_range) {
    if (*size >= *capacity) {
        resize_records(records, size, capacity);
    }

    for (size_t i = 0; i < *size; ++i) {
        if ((*records)[i].key == key && !(*records)[i].deleted) {
            return -1; // Key already exists
        }
    }

    (*records)[*size].key = key;
    (*records)[*size].offset = offset;
    (*records)[*size].src = (data_source*)malloc(sizeof(data_source));
    (*records)[*size].src->value = rand() % value_range + 1; // Random value within range
    (*records)[*size].deleted = 0;

    (*size)++;
    return 0;
}

record* find_record(record* records, size_t size, int key) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key == key && !records[i].deleted) {
            return &records[i];
        }
    }
    return NULL;
}

void delete_record(record* records, size_t size, int key) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key == key && !records[i].deleted) {
            records[i].deleted = 1;
            break;
        }
    }
}

void resize_records(record** records, size_t* size, size_t* capacity) {
    *capacity *= 2;
    *records = (record*)realloc(*records, (*capacity) * sizeof(record));
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    record* records = NULL;
    size_t size = 0, capacity = INITIAL_CAPACITY;

    initialize_records(&records, capacity);

    add_record(&records, &size, &capacity, 1, 100, 50);
    add_record(&records, &size, &capacity, 2, 200, 75);

    record* found = find_record(records, size, 1);
    if (found) {
        printf("Found record with key %d and value %d\n", found->key, found->src->value);
    }

    delete_record(records, size, 1);

    for (size_t i = 0; i < size; ++i) {
        if (!records[i].deleted && records[i].src) {
            free(records[i].src); // Free data_source memory
        }
    }

    free(records); // Free the records array

    return 0;
}
```

### Key Features:

- **Dynamic Memory Management**: Uses `malloc` and `realloc` to manage dynamic arrays of records.
- **Soft Deletion**: Implements a soft deletion mechanism by marking records as deleted instead of removing them, allowing recovery if necessary.
- **Efficient Retrieval**: Provides a function to find records by key with O(n) complexity, suitable for moderate-sized datasets.
- **Resizing Logic**: Automatically resizes the records array when capacity is reached.
- **Random Initialization**: Initializes each record's value to a random number within a specified range.
- **Error Handling and Logging**: Basic error handling included; further logging can be added as needed.

This code serves as a basic framework for managing records dynamically, suitable for scaling and extending with additional features such as concurrency control or caching.']

