// Define the record structure
typedef struct {
    int value;
} Record;

// Metadata structure with pointers and sizes
typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t offsets_size;
    size_t keys_size;
    size_t records_size;
} Metadata;

// Logging function for memory events
void log_memory_event(const char *event, const char *description) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), event, description);
}

// Function to calculate required memory size
size_t calculate_required_size(size_t n, size_t long_bytes, size_t int_bytes, size_t record_bytes) {
    return (n * long_bytes) + (n * int_bytes) + (n * record_bytes);
}

// Thread-safe memory allocation function
Metadata* allocate_memory(size_t n, size_t memory_budget) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    Metadata *metadata = NULL;

    if (n <= 0 || memory_budget < sizeof(Metadata)) {
        log_memory_event("ERROR", "Invalid input parameters");
        return NULL;
    }

    size_t long_bytes = sizeof(long);
    size_t int_bytes = sizeof(int);
    size_t record_bytes = sizeof(Record);

    size_t initial_required_size = calculate_required_size(n, long_bytes, int_bytes, record_bytes) + sizeof(Metadata);

    if (initial_required_size > memory_budget) {
        n = memory_budget / (long_bytes + int_bytes + record_bytes + sizeof(Metadata));
        log_memory_event("INFO", "Adjusted size due to budget constraints");
    }

    pthread_mutex_lock(&lock);

    metadata = (Metadata *)malloc(sizeof(Metadata));
    if (!metadata) {
        log_memory_event("ERROR", "Failed to allocate Metadata");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    metadata->offsets_size = n;
    metadata->keys_size = n;
    metadata->records_size = n;

    metadata->offsets = (long *)malloc(n * long_bytes);
    if (!metadata->offsets) {
        log_memory_event("ERROR", "Failed to allocate offsets");
        free(metadata);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    metadata->keys = (int *)malloc(n * int_bytes);
    if (!metadata->keys) {
        log_memory_event("ERROR", "Failed to allocate keys");
        free(metadata->offsets);
        free(metadata);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    metadata->records = (Record *)malloc(n * record_bytes);
    if (!metadata->records) {
        log_memory_event("ERROR", "Failed to allocate records");
        free(metadata->keys);
        free(metadata->offsets);
        free(metadata);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    log_memory_event("INFO", "Memory allocation successful");

    pthread_mutex_unlock(&lock);

    return metadata;
}

// Function to free allocated memory
void free_memory(Metadata *metadata) {
    if (metadata) {
        pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

        pthread_mutex_lock(&lock);

        free(metadata->offsets);
        free(metadata->keys);
        free(metadata->records);
        free(metadata);

        log_memory_event("INFO", "Memory deallocation successful");

        pthread_mutex_unlock(&lock);
    }
}

// Example function to simulate periodic optimization
void optimize_memory_layout(Metadata *metadata) {
    // Placeholder for memory layout optimization logic
