```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define INITIAL_HASH_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    int value;
} Record;

typedef struct HashNode {
    int key;
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t size);
void free_hash_table(HashTable *table, int free_records);
void hash_insert(HashTable *table, int key, Record *record);
Record* hash_lookup(HashTable *table, int key);
void resize_hash_table(HashTable *table);
int generate_random_int(int min, int max, int *used_keys, size_t used_count);
void serialize_hash_table(const HashTable *table, const char *filename);
HashTable* deserialize_hash_table(const char *filename);

// Create a new hash table
HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(size, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

// Free the hash table
void free_hash_table(HashTable *table, int free_records) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            if (free_records) free(temp->record);
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Insert a record into the hash table
void hash_insert(HashTable *table, int key, Record *record) {
    size_t index = (size_t)key % table->size;
    HashNode *node = malloc(sizeof(HashNode));
    if (!node) return;

    node->key = key;
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_lock(&table->lock);
    table->count++;
    if ((double)table->count / table->size > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }
    pthread_mutex_unlock(&table->lock);
}

// Lookup a record by key
Record* hash_lookup(HashTable *table, int key) {
    size_t index = (size_t)key % table->size;
    HashNode *node = table->buckets[index];

    while (node) {
        if (node->key == key) return node->record;
        node = node->next;
    }

    return NULL;
}

// Resize the hash table
void resize_hash_table(HashTable *table) {
    size_t new_size = table->size * 2;
    HashNode **new_buckets = calloc(new_size, sizeof(HashNode *));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            size_t new_index = (size_t)node->key % new_size;
            HashNode *next_node = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

// Generate a random integer within a range, avoiding used keys
int generate_random_int(int min, int max, int *used_keys, size_t used_count) {
    int rand_val;
    do {
        rand_val = rand() % (max - min + 1) + min;
    } while (is_key_used(rand_val, used_keys, used_count));
    return rand_val;
}

// Check if a key is already used
int is_key_used(int key, const int *used_keys, size_t used_count) {
    for (size_t i = 0; i < used_count; ++i) {
        if (used_keys[i] == key) return 1;
    }
    return 0;
}

// Serialize the hash table to a binary file
void serialize_hash_table(const HashTable *table, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&table->size, sizeof(size_t), 1, file);
    fwrite(&table->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            fwrite(&node->key, sizeof(int), 1, file);
            fwrite(node->record, sizeof(Record), 1, file);
            node = node->next;
        }
    }

    fclose(file);
}

// Deserialize the hash table from a binary file
HashTable* deserialize_hash_table(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t size, count;
    fread(&size, sizeof(size_t), 1, file);
    fread(&count, sizeof(size_t), 1, file);

    HashTable *table = create_hash_table(size);
    if (!table) {
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        int key;
        Record record;
        fread(&key, sizeof(int), 1, file);
        fread(&record, sizeof(Record), 1, file);

        hash_insert(table, key, malloc(sizeof(Record)));
        if (table->buckets[(size_t)key % table->size]->record) {
            *(table->buckets[(size_t)key % table->size]->record) = record;
        }
    }

    fclose(file);
    return table;
}

int main() {
    srand(time(NULL));

    HashTable *table = create_hash_table(INITIAL_HASH_SIZE);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    int used_keys[1000];
    size_t used_count = 0;

    for (int i = 0; i < 100; ++i) {
        int key = generate_random_int(1, 1000, used_keys, used_count);
        used_keys[used_count++] = key;

        Record *record = malloc(sizeof(Record));
        if (!record) continue;

        record->value = rand() % 1000;
        hash_insert(table, key, record);
    }

    serialize_hash_table(table, "hash_table.bin");
    HashTable *loaded_table = deserialize_hash_table("hash_table.bin");

    free_hash_table(table, 1);
    if (loaded_table) {
        free_hash_table(loaded_table, 1);
    }

    return EXIT_SUCCESS;
}
