void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int generate_unique_random(int min, int max, int count, int *array) {
    int range_size = max - min + 1;
    if (count > range_size) {
        fprintf(stderr, "Cannot generate unique numbers in the specified range\n");
        return 0;
    }

    for (int i = 0; i < count; ++i) {
        array[i] = min + rand() % range_size;
    }

    // Ensure uniqueness
    int *temp_array = safe_malloc(count * sizeof(int));
    memcpy(temp_array, array, count * sizeof(int));

    for (int i = 0; i < count; ++i) {
        int j = rand() % count;
        int swap = temp_array[i];
        temp_array[i] = temp_array[j];
        temp_array[j] = swap;

        // Check for duplicates
        for (int k = 0; k < i; ++k) {
            if (temp_array[i] == temp_array[k]) {
                --i;
                break;
            }
        }
    }

    memcpy(array, temp_array, count * sizeof(int));
    free(temp_array);
    return 1;
}

record* allocate_and_initialize(int offset_count, int key_count) {
