        return NULL;
    }

    long *offsets = safe_malloc(offset_count * sizeof(long));
    int *keys = safe_malloc(key_count * sizeof(int));
    record *records = safe_malloc((offset_count < key_count ? offset_count : key_count) * sizeof(record));

    // Populate offsets with random values
    for (int i = 0; i < offset_count; ++i) {
        offsets[i] = rand() % OFFSET_RANGE;
    }

    // Generate unique keys
    if (!generate_unique_random(0, KEY_RANGE - 1, key_count, keys)) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Populate records with random values less than the corresponding key if exists
    int record_count = (offset_count < key_count ? offset_count : key_count);
    for (int i = 0; i < record_count; ++i) {
        records[i].value = rand() % VALUE_RANGE;
        if (records[i].value >= keys[i]) {
            records[i].value = keys[i] - 1;
        }
    }

    // Normally, you would free the offsets and keys arrays here when done
