#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 16
#define MAX_LOAD_FACTOR 0.75
#define MEMORY_THRESHOLD 80 // Percentage
#define KEY_RANGE 100000
#define UNIQUENESS_PROBABILITY 0.99

typedef struct {
    long *offsets;
    int *keys;
    int size;
    int count;
} HashTable;

// Mutex for thread safety
pthread_mutex_t hash_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
HashTable* create_hash_table();
void destroy_hash_table(HashTable* table);
int insert(HashTable* table, long offset, int key);
int find(HashTable* table, int key);
void delete_key(HashTable* table, int key);
void resize_if_needed(HashTable* table);
void serialize_to_file(const HashTable* table, const char* filename);
int deserialize_from_file(HashTable* table, const char* filename);
long generate_unique_offset();
int generate_unique_int(int lower, int upper);
int validate_uniqueness(HashTable* table);
int check_memory_usage();
void cleanup_unused_records(HashTable* table);

// Create a new hash table
HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = INITIAL_SIZE;
    table->count = 0;

    table->offsets = (long*)calloc(table->size, sizeof(long));
    table->keys = (int*)calloc(table->size, sizeof(int));

    if (!table->offsets || !table->keys) {
        free(table->offsets);
        free(table->keys);
        free(table);
        return NULL;
    }

    return table;
}

// Destroy the hash table
void destroy_hash_table(HashTable* table) {
    if (table) {
        free(table->offsets);
        free(table->keys);
        free(table);
    }
}

// Hash function for keys
unsigned int hash(int key, unsigned int size) {
    return key % size;
}

// Insert a new key and offset into the hash table
int insert(HashTable* table, long offset, int key) {
    pthread_mutex_lock(&hash_table_mutex);

    if (table->count >= table->size * MAX_LOAD_FACTOR) {
        resize_if_needed(table);
    }

    unsigned int index = hash(key, table->size);
    while (table->keys[index] != 0 && table->keys[index] != key) {
        index = (index + 1) % table->size;
    }

    if (table->keys[index] == 0) { // Insert
        table->offsets[index] = offset;
        table->keys[index] = key;
        table->count++;
    }

    pthread_mutex_unlock(&hash_table_mutex);
    return table->keys[index];
}

// Find a key in the hash table
int find(HashTable* table, int key) {
    unsigned int index = hash(key, table->size);

    while (table->keys[index] != 0) {
        if (table->keys[index] == key) {
            return table->offsets[index];
        }
        index = (index + 1) % table->size;
    }

    return -1; // Not found
}

// Delete a key from the hash table
void delete_key(HashTable* table, int key) {
    pthread_mutex_lock(&hash_table_mutex);

    unsigned int index = hash(key, table->size);

    while (table->keys[index] != 0) {
        if (table->keys[index] == key) {
            table->keys[index] = 0;
            table->offsets[index] = -1; // Mark as deleted
            table->count--;
            break;
        }
        index = (index + 1) % table->size;
    }

    pthread_mutex_unlock(&hash_table_mutex);
}

// Resize the hash table if needed
void resize_if_needed(HashTable* table) {
    int new_size = table->size * 2;

    long *new_offsets = (long*)calloc(new_size, sizeof(long));
    int *new_keys = (int*)calloc(new_size, sizeof(int));

    if (!new_offsets || !new_keys) return; // Memory allocation failure

    for (int i = 0; i < table->size; ++i) {
        if (table->keys[i] != 0) {
            unsigned int index = hash(table->keys[i], new_size);
            while (new_keys[index] != 0) {
                index = (index + 1) % new_size;
            }
            new_offsets[index] = table->offsets[i];
            new_keys[index] = table->keys[i];
        }
    }

    free(table->offsets);
    free(table->keys);

    table->offsets = new_offsets;
    table->keys = new_keys;
    table->size = new_size;
}

// Serialize the hash table to a file
void serialize_to_file(const HashTable* table, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&table->size, sizeof(table->size), 1, file);
    fwrite(&table->count, sizeof(table->count), 1, file);

    for (int i = 0; i < table->size; ++i) {
        fwrite(&table->offsets[i], sizeof(long), 1, file);
        fwrite(&table->keys[i], sizeof(int), 1, file);
    }

    fclose(file);
}

// Deserialize the hash table from a file
int deserialize_from_file(HashTable* table, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int size, count;
    fread(&size, sizeof(size), 1, file);
    fread(&count, sizeof(count), 1, file);

    long *new_offsets = (long*)calloc(size, sizeof(long));
    int *new_keys = (int*)calloc(size, sizeof(int));

    if (!new_offsets || !new_keys) {
        fclose(file);
        return -1; // Memory allocation failure
    }

    for (int i = 0; i < size; ++i) {
        fread(&new_offsets[i], sizeof(long), 1, file);
        fread(&new_keys[i], sizeof(int), 1, file);
    }

    fclose(file);

    if (table->offsets) free(table->offsets);
    if (table->keys) free(table->keys);

    table->size = size;
    table->count = count;
    table->offsets = new_offsets;
    table->keys = new_keys;

    return 0; // Success
}

// Generate a unique offset
long generate_unique_offset() {
    static long last_offset = -1;
    do {
        last_offset++;
    } while (last_offset < 0);

    return last_offset;
}

// Generate a unique integer within a range with some probability of duplicates
int generate_unique_int(int lower, int upper) {
    if ((double)rand() / RAND_MAX > UNIQUENESS_PROBABILITY)
        return rand() % (upper - lower + 1) + lower;

    static int used[KEY_RANGE] = {0};
    do {
        int candidate = rand() % (upper - lower + 1) + lower;
    } while (used[candidate]);

    used[candidate] = 1; // Mark as used
    return candidate;
}

// Validate the uniqueness of keys in the hash table
int validate_uniqueness(HashTable* table) {
    int *seen = (int*)calloc(table->size, sizeof(int));

    if (!seen) return -1;

    for (int i = 0; i < table->size; ++i) {
        if (table->keys[i] != 0 && seen[table->keys[i]]) {
            free(seen);
            return -1; // Duplicate found
        }
        seen[table->keys[i]] = 1;
    }

    free(seen);
    return 0; // Unique
}

// Check the memory usage and compress if needed
int check_memory_usage() {
    // This is a placeholder function. Replace with actual system memory check.
    // Return true if usage > MEMORY_THRESHOLD, else false.
    return (rand() % 100) > MEMORY_THRESHOLD;
}

// Cleanup unused records based on some policy
void cleanup_unused_records(HashTable* table) {
    pthread_mutex_lock(&hash_table_mutex);

    for (int i = 0; i < table->size; ++i) {
        if (table->keys[i] != 0 && table->offsets[i] == -1) { // If marked as deleted
            table->keys[i] = 0;
            table->count--;
        }
    }

    pthread_mutex_unlock(&hash_table_mutex);
}

int main() {
    HashTable *table = create_hash_table();

    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return -1;
    }

    for (int i = 0; i < 100; ++i) { // Example usage
        int key = generate_unique_int(1, KEY_RANGE);
        long offset = generate_unique_offset();
        insert(table, offset, key);
    }

    serialize_to_file(table, "data.bin");
    destroy_hash_table(table);

    HashTable *new_table = create_hash_table();
    deserialize_from_file(new_table, "data.bin");

    if (validate_uniqueness(new_table) == -1)
        fprintf(stderr, "Uniqueness validation failed\n");

    printf("Data integrity check passed\n");

    destroy_hash_table(new_table);
    return 0;
}
