struct record* allocate_and_initialize(int offsets_size, int keys_size, int key_min, int key_max, int value_min, int value_max) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (offsets_size < 0 || keys_size < 0 || offsets_size > MAX_SIZE || keys_size > MAX_SIZE) {
        log_message("Invalid input sizes");
        return NULL;
    }

    long *offsets = malloc(offsets_size * sizeof(long));
    int *keys = malloc(keys_size * sizeof(int));
    struct record *records = malloc((offsets_size < keys_size ? offsets_size : keys_size) * sizeof(struct record));

    if (!offsets || !keys || !records) {
        log_message("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < offsets_size; ++i) {
        pthread_mutex_lock(&mutex);
        offsets[i] = rand() % ((value_max - value_min + 1) * 2) + value_min;
        pthread_mutex_unlock(&mutex);
    }

    size_t unique_keys_count = 0;
    for (int i = 0; i < keys_size; ++i) {
        int key;
        do {
            key = generate_unique_key(key_min, key_max, &keys[unique_keys_count], unique_keys_count);
        } while (!is_unique(key, &keys[unique_keys_count], unique_keys_count));

        pthread_mutex_lock(&mutex);
        keys[i] = key;
        ++unique_keys_count;
        pthread_mutex_unlock(&mutex);
    }

    size_t record_size = offsets_size < keys_size ? offsets_size : keys_size;
    for (size_t i = 0; i < record_size; ++i) {
        int value;
        do {
            value = rand() % (value_max - value_min + 1) + value_min;
        } while (value >= keys[i]);

        pthread_mutex_lock(&mutex);
        records[i].value = value;
        pthread_mutex_unlock(&mutex);
    }

    log_message("Memory allocation and initialization successful");

    free(offsets);
    free(keys);

    return records;
}
