// Library Core Module

// StateManager.java
import java.io.*;
import java.util.*;

public class StateManager {
    private Map<String, Object> cache;
    private CacheEvictionPolicy evictionPolicy;

    public StateManager(CacheEvictionPolicy policy) {
        this.cache = new LinkedHashMap<>();
        this.evictionPolicy = policy;
    }

    public void loadState(String filePath) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object state = ois.readObject();
            cache.put(filePath, state);
            evictionPolicy.apply(this.cache);
        }
    }
}

// CacheEvictionPolicy.java
public interface CacheEvictionPolicy {
    void apply(Map<String, Object> cache);
}

// LRU_CACHE_POLICY.java
import java.util.*;

public class LRUEvictionPolicy implements CacheEvictionPolicy {
    private int maxSize;

    public LRUEvictionPolicy(int maxSize) {
        this.maxSize = maxSize;
    }

    @Override
    public void apply(Map<String, Object> cache) {
        if (cache.size() > maxSize) {
            Iterator<Map.Entry<String, Object>> iterator = cache.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<String, Object> entry = iterator.next();
                iterator.remove();
                break;
            }
        }
    }
}

