// FileExtensionModifier.java
public class FileExtensionModifier {

    public static String modifyFileExtension(String fileName, Map<String, String> rules) {
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex == -1 || dotIndex == fileName.length() - 1)
            return fileName;

        String baseName = fileName.substring(0, dotIndex);
        String extension = fileName.substring(dotIndex + 1);

        for (Map.Entry<String, String> rule : rules.entrySet()) {
            if (rule.getKey().equals(extension)) {
                return baseName + "." + rule.getValue();
            }
        }

        return fileName;
    }
}

