['Here's a C implementation for managing dynamic lists of custom `record` structures with efficient handling of concurrent operations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 10000

typedef struct Friend {
    int friend_id;
    int active; // 1 if not blocked, 0 if blocked
    struct Friend *next;
} Friend;

typedef struct Record {
    long offset;
    int key;
    int value;
    Friend *friends;
    time_t last_active;
    pthread_mutex_t lock;
} Record;

typedef struct HashTable {
    Record **table;
    pthread_rwlock_t rwlock;
} HashTable;

HashTable *create_hash_table() {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->table = calloc(TABLE_SIZE, sizeof(Record*));
    pthread_rwlock_init(&ht->rwlock, NULL);
    return ht;
}

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

void lock_record(Record *record) {
    pthread_mutex_lock(&record->lock);
}

void unlock_record(Record *record) {
    pthread_mutex_unlock(&record->lock);
}

int add_record(HashTable *ht, Record *record) {
    unsigned int index = hash(record->key);

    pthread_rwlock_wrlock(&ht->rwlock);
    if (ht->table[index] != NULL) {
        pthread_rwlock_unlock(&ht->rwlock);
        return -1;
    }
    ht->table[index] = record;
    pthread_rwlock_unlock(&ht->rwlock);

    lock_record(record);
    pthread_mutex_init(&record->lock, NULL);
    unlock_record(record);

    return 0;
}

Record *get_record(HashTable *ht, int key) {
    unsigned int index = hash(key);

    Record *result = NULL;
    pthread_rwlock_rdlock(&ht->rwlock);
    result = ht->table[index];
    pthread_rwlock_unlock(&ht->rwlock);

    if (result != NULL) {
        lock_record(result);
    }

    return result;
}

int update_record(HashTable *ht, int key, int new_value) {
    unsigned int index = hash(key);
    Record *record = NULL;

    pthread_rwlock_wrlock(&ht->rwlock);
    record = ht->table[index];
    pthread_rwlock_unlock(&ht->rwlock);

    if (record == NULL) return -1;

    lock_record(record);
    record->value = new_value;
    unlock_record(record);

    return 0;
}

void block_unblock_friend(Record *user, int friend_id, int block) {
    Friend *current = user->friends;

    while (current != NULL) {
        if (current->friend_id == friend_id) {
            lock_record(user);
            current->active = !block; // If block is true, set active to 0, otherwise to 1
            unlock_record(user);
            break;
        }
        current = current->next;
    }
}

void cleanup_inactive_profiles(HashTable *ht, time_t threshold) {
    for (unsigned int i = 0; i < TABLE_SIZE; ++i) {
        pthread_rwlock_wrlock(&ht->rwlock);

        Record *record = ht->table[i];
        if (record != NULL && difftime(time(NULL), record->last_active) > threshold) {
            lock_record(record);
            // Perform cleanup
            while (record->friends != NULL) {
                Friend *temp = record->friends;
                record->friends = record->friends->next;
                free(temp);
            }
            pthread_mutex_destroy(&record->lock);
            ht->table[i] = NULL;

            free(record);
            unlock_record(record);
        }

        pthread_rwlock_unlock(&ht->rwlock);
    }
}

void log_change(const char *message) {
    FILE *log_file = fopen("changes.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Versioning system
typedef struct VersionedRecord {
    Record record;
    struct VersionedRecord *prev_version;
} VersionedRecord;

VersionedRecord *create_version(VersionedRecord *prev) {
    VersionedRecord *new_version = malloc(sizeof(VersionedRecord));
    if (prev != NULL) {
        new_version->record = prev->record;
    }
    new_version->prev_version = prev;
    return new_version;
}

void rollback_version(VersionedRecord **current, int steps) {
    while (*current != NULL && steps > 0) {
        VersionedRecord *temp = *current;
        *current = temp->prev_version;
        free(temp);
        --steps;
    }
}

void manage_memory_usage() {
    // Implement memory usage monitoring
}

int main() {
    HashTable *ht = create_hash_table();

    // Example operations
    Record *new_record = malloc(sizeof(Record));
    new_record->key = 1;
    new_record->value = 100;
    add_record(ht, new_record);

    Record *retrieved_record = get_record(ht, 1);
    if (retrieved_record != NULL) {
        update_record(ht, 1, 200);
    }

    cleanup_inactive_profiles(ht, 3600); // Cleanup profiles inactive for over an hour

    return 0;
}
```

This code provides a basic structure to manage records with thread safety and efficient memory management. It includes hash table operations, record versioning, blocking/unblocking friends, and periodic cleanup of inactive profiles. The logging mechanism avoids global variables by writing directly to a file.']

