        pthread_mutex_lock(&lock);
        insert_record(new_record);
        pthread_mutex_unlock(&lock);

        // Simulate processing with logging and removal of records
        report_memory_usage();

        pthread_mutex_lock(&lock);
        remove_record(42); // Remove by value for demonstration purposes
        pthread_mutex_unlock(&lock);

        destroy_record(new_record);
    }
}

// Function to create a record
Record* create_record(int value, MetadataBlock** metadata) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->value = value;
    *metadata = fetch_metadata();
    new_record->metadata = (*metadata) ? *metadata : NULL; // Handle fetching failure
    new_record->next = NULL;

    return new_record;
}

// Function to destroy a record and free its resources
void destroy_record(Record* record) {
    if (record) {
        if (record->metadata) {
            // Free metadata or perform necessary cleanup
        }
        free(record);
    }
}

// Function to insert a record into the collection
void insert_record(Record* record) {
    struct RecordNode* new_node = (struct RecordNode*)malloc(sizeof(struct RecordNode));
    if (!new_node) return;

    new_node->record = record;
    new_node->next = head;
    head = new_node;
}

// Function to remove a record from the collection by its value
void remove_record(int value) {
    struct RecordNode **curr = &head, *temp;

    while (*curr) {
        if ((*curr)->record->value == value) {
            temp = *curr;
            *curr = (*curr)->next;
            destroy_record(temp->record);
            free(temp);
            return;
        }
        curr = &(*curr)->next;
    }
}

// Function to report memory usage statistics
void report_memory_usage() {
    struct RecordNode* current = head;
    int total_records = 0;

    // Calculate active records
    while (current) {
        ++total_records;
        current = current->next;
    }

    printf("Total Allocated Memory: %zu bytes\n", sizeof(struct RecordNode) * total_records);
    printf("Active Records: %d\n", total_records);
}

// Function to fetch metadata, with error handling for failures
MetadataBlock* fetch_metadata() {
    // Simulate metadata fetching
    MetadataBlock* metadata = (MetadataBlock*)malloc(sizeof(MetadataBlock));
    if (!metadata) return NULL; // Simulate failure

    // Assume initialization is successful
    return metadata;
}
```

### Documentation of Trade-offs:

1. **Performance and Resource Usage**:
   - Used a linked list for dynamic record management to minimize fragmentation.
   - Memory allocation is done per-record, allowing efficient cleanup and minimizing wasted space.

2. **Thread Safety**:
   - Mutexes are used to ensure thread-safe operations on the shared data structure (linked list).
   - This approach introduces minimal overhead while maintaining simplicity.

3. **Memory Usage Logging**:
   - Logging memory usage periodically without significant performance degradation.
   - Memory statistics provide insights but can be expanded for more detailed reporting as needed.

4. **Error Handling in Metadata Fetching**:
   - Basic error handling is implemented for metadata fetching; further strategies like retries or alternative sources could be considered.

5. **Extensibility and Maintainability**:
   - The design allows easy addition of new fields to the `Record` structure.
   - The use of opaque structures and modular functions supports future extensions while keeping changes localized.']

