#include <fstream>
#include <memory>
#include <algorithm>

struct AttackStrategy {
    int attackID;
    std::string attackType;
    float attackPower;
};

struct AttackStrategyEntry {
    char message[256];
    int severityLevel;
    float* attackPowerPtr;
    const char* filePath;

    AttackStrategyEntry(const std::string& msg, int severity, float* powerPtr, const char* path)
        : severityLevel(severity), attackPowerPtr(powerPtr), filePath(path) {
        strncpy(message, msg.c_str(), sizeof(message) - 1);
        message[sizeof(message) - 1] = '\0';
    }
};

bool initializeLogFile(const std::string& logFilePath, size_t maxEntries) {
    std::ofstream logFile(logFilePath, std::ios_base::app);
    if (!logFile.is_open()) return false;

    // Trim the log file to maintain only the last `maxEntries` lines
    std::vector<std::string> allLines;
    std::string line;

    while (std::getline(logFile, line)) {
        allLines.push_back(line);
        if (allLines.size() > maxEntries) {
            allLines.erase(allLines.begin());
        }
    }

    logFile.clear();
    for (const auto& l : allLines) {
        logFile << l << '\n';
    }

    logFile.close();
    return true;
}

void executeRandomizedStrategy(float cooldownDuration = 9.0, const std::vector<AttackStrategy>& strategies,
                               const std::string& logFilePath) {

    if (strategies.empty()) {
        std::cerr << "No attack strategies provided." << std::endl;
        return;
    }

    initializeLogFile(logFilePath, 10);

    // Dynamic allocation for arrays
    float* attackPowers = new(std::nothrow) float[strategies.size()];
    unsigned long* timestamps = new(std::nothrow) unsigned long[strategies.size()];
    AttackStrategyEntry** entries = new(std::nothrow) AttackStrategyEntry*[strategies.size()]{};
    int* errorCodes = new(std::nothrow) int[strategies.size()]();

    if (!attackPowers || !timestamps || !entries || !errorCodes) {
        std::cerr << "Memory allocation failed." << std::endl;
        delete[] attackPowers; 
        delete[] timestamps; 
        for (int i = 0; i < strategies.size(); ++i) delete entries[i];
        delete[] entries;
        delete[] errorCodes;
        return;
    }

    // Populate arrays with random values and create entry structures
    std::srand(std::time(nullptr)); // Seed for randomness

    for (size_t i = 0; i < strategies.size(); ++i) {
        attackPowers[i] = static_cast<float>(std::rand() % 100 + 1); // Random power between 1 and 100
        timestamps[i] = static_cast<unsigned long>(cooldownDuration * 1000); // Cooldown in milliseconds

        entries[i] = new(std::nothrow) AttackStrategyEntry(
            strategies[i].attackType, 
            i, 
            &attackPowers[i], 
            logFilePath.c_str()
        );

        if (!entries[i]) {
            errorCodes[i] = -1;  // Error code for memory allocation failure
        }
    }

    // Select a random attack strategy based on available resources and cooldowns
    size_t selectedStrategyIndex = std::rand() % strategies.size();

    if (timestamps[selectedStrategyIndex] > static_cast<unsigned long>(cooldownDuration * 1000)) {
        errorCodes[selectedStrategyIndex] = -2;  // Error code for cooldown not ready
    }

    // Log the chosen attack strategy
    std::ofstream logFile(logFilePath, std::ios_base::app);
    if (logFile.is_open()) {
        logFile << "Selected Attack: ID=" << strategies[selectedStrategyIndex].attackID 
                << ", Type=" << strategies[selectedStrategyIndex].attackType 
                << ", Power=" << attackPowers[selectedStrategyIndex] 
                << ", Timestamp=" << timestamps[selectedStrategyIndex]
                << std::endl;
        logFile.close();
    }

    // Clean up dynamically allocated memory
    delete[] attackPowers; 
    delete[] timestamps;

    for (size_t i = 0; i < strategies.size(); ++i) {
        delete entries[i];
    }
    delete[] entries;
    delete[] errorCodes;
}
