using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Xml.Linq;

public class ConfigService
{
    private static readonly object DirectoryLock = new object();
    private const string ServicesHomeEnvVarName = "SERVICES_HOME";

    public async Task<string> ParseAndCreateServiceDirectoryAsync(string xmlFilePath, string serviceName)
    {
        try
        {
            // Load XML file and find the first occurrence of ConfigurableService node.
            var doc = await XDocument.LoadAsync(xmlFilePath);
            var configurableServiceNode = doc.Descendants("ConfigurableService").FirstOrDefault();

            if (configurableServiceNode == null)
                return "Error: No ConfigurableService node found.";

            // Ensure unique service directory creation
            string directoryPath = Path.Combine(Environment.CurrentDirectory, serviceName);
            await CreateServiceDirectoryAsync(directoryPath);

            LogOperation($"Parsed XML and created directory for {serviceName}");
            return $"Success: Service directory '{directoryPath}' created or verified.";

        }
        catch (Exception ex)
        {
            // Handle exceptions related to file I/O or parsing
            LogOperation($"Error during operation: {ex.Message}");
            return $"Error: Unable to process XML configuration. Details: {ex.Message}";
        }
    }

    private async Task CreateServiceDirectoryAsync(string directoryPath)
    {
        try
        {
            await Task.Run(() =>
            {
                lock (DirectoryLock) // Ensure thread-safe directory creation
                {
                    if (!Directory.Exists(directoryPath))
                    {
                        Directory.CreateDirectory(directoryPath);
                        LogOperation($"Created new service directory: {directoryPath}");
                    }
                    else
                    {
                        string currentServicesHome = Environment.GetEnvironmentVariable(ServicesHomeEnvVarName);

                        if (currentServicesHome != directoryPath)
                        {
                            Environment.SetEnvironmentVariable(ServicesHomeEnvVarName, directoryPath, EnvironmentVariableTarget.User);
                            LogOperation($"Updated SERVICES_HOME to: {directoryPath}");
                        }
                    }
                }
            });
        }
        catch (Exception ex)
        {
            // Handle exceptions related to directory operations
            LogOperation($"Error creating or verifying service directory '{directoryPath}': {ex.Message}");
            throw;
        }
    }

    private void LogOperation(string message)
    {
        string logFilePath = "service_operations.log";
        string timestampedMessage = $"{DateTime.UtcNow:O} - {message}";

        // Thread-safe logging
        lock (DirectoryLock)
        {
            File.AppendAllText(logFilePath, timestampedMessage + Environment.NewLine);
        }
    }
}
```

### Key Considerations in This Solution:

1. **XML Parsing**: The `XDocument.LoadAsync` method efficiently loads and parses the XML file asynchronously to handle potential large files.

2. **Thread-Safe Directory Operations**: A `lock` statement is used on a static object (`DirectoryLock`) ensuring thread-safe access during directory creation and logging.

3. **Environment Variable Check/Update**: The function checks if the current environment variable `SERVICES_HOME` points to the new service directory, updating it if necessary.

4. **Logging Operations**: Logs are timestamped for easy auditing and written in a thread-safe manner using a lock.

5. **Error Handling**: Comprehensive exception handling is implemented to manage I/O or XML parsing errors gracefully, ensuring that operations log relevant details for debugging.

6. **Asynchronous Execution**: Asynchronous methods ensure the function performs efficiently without blocking other processes.']

