#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    INACTIVE,
    ACTIVE
} ConnectionState;

typedef struct Request {
    char *url;
    // Other request details
    struct Request* next;
};

typedef struct Session {
    char sessionID[36];
    time_t expirationTimestamp;
    ConnectionState connectionState;
    struct Request* requests;
    struct Session* next;
    time_t lastAccessTime;
} Session;

typedef struct SessionManager {
    Session *head;
    int maxSessions;
    int currentSessionCount;
    // External logging system placeholder
} SessionManager;

void log_event(const char *message) {
    printf("Log: %s\n", message);
}

Session* create_session(SessionManager *manager) {
    if (manager->currentSessionCount >= manager->maxSessions) {
        log_event("Max sessions reached, terminating LRU session.");
        // Find and remove the least recently used session
        Session **ptr = &manager->head;
        while (*ptr) {
            Session **innerPtr = ptr;
            ptr = &(*ptr)->next;
            if ((*innerPtr)->lastAccessTime == manager->currentSessionCount - 1) { // LRU heuristic
                Session *toRemove = *innerPtr;
                *innerPtr = toRemove->next;
                free(toRemove);
                manager->currentSessionCount--;
                break;
            }
        }
    }

    Session *newSession = (Session*)malloc(sizeof(Session));
    if (!newSession) {
        log_event("Failed to allocate memory for new session.");
        return NULL;
    }

    // Generate a unique session ID
    strcpy(newSession->sessionID, "unique-id");  // Placeholder: implement actual unique ID generation

    newSession->expirationTimestamp = time(NULL) + 3600; // 1 hour from now
    newSession->connectionState = INACTIVE;
    newSession->requests = NULL;
    newSession->next = manager->head;
    manager->head = newSession;

    newSession->lastAccessTime = manager->currentSessionCount++;
    log_event("Created new session.");

    return newSession;
}

void update_session_state(Session *session, ConnectionState newState) {
    if (session) {
        session->connectionState = newState;
        session->lastAccessTime = time(NULL);
        char state[10] = newState == ACTIVE ? "ACTIVE" : "INACTIVE";
        log_event("Updated session state to ");
        printf("%s\n", state);
    }
}

Session* get_session_by_id(SessionManager *manager, const char *sessionID) {
    for (Session *current = manager->head; current != NULL; current = current->next) {
        if (strcmp(current->sessionID, sessionID) == 0) {
            current->lastAccessTime = time(NULL);
            return current;
        }
    }
    return NULL;
}

void delete_expired_sessions(SessionManager *manager) {
    Session **ptr = &manager->head;
    while (*ptr) {
        if (time(NULL) > (*ptr)->expirationTimestamp) {
            log_event("Deleting expired session.");
            Session *toDelete = *ptr;
            *ptr = toDelete->next;
            free(toDelete);
            manager->currentSessionCount--;
        } else {
            ptr = &(*ptr)->next;
        }
    }
}

void set_max_sessions(SessionManager *manager, int newMax) {
    if (newMax < manager->maxSessions && manager->currentSessionCount > newMax) {
        log_event("Reducing max sessions below current active sessions.");
        // Logic to handle reducing the maximum number of sessions
    }
    manager->maxSessions = newMax;
}

void initialize_session_manager(SessionManager *manager, int maxSessions) {
    memset(manager, 0, sizeof(SessionManager));
    manager->maxSessions = maxSessions;
    log_event("Initialized session manager with max sessions.");
}

void free_sessions(SessionManager *manager) {
    Session *current = manager->head;
    while (current != NULL) {
        Session *toFree = current;
        current = current->next;

        // Free requests list
        Request *request = toFree->requests;
        while (request) {
            Request *nextRequest = request->next;
            free(request);
            request = nextRequest;
        }

        free(toFree);
    }
}

int main() {
    SessionManager manager;
    initialize_session_manager(&manager, 100);

    // Example usage
    create_session(&manager);
    update_session_state(get_session_by_id(&manager, "unique-id"), ACTIVE);

    delete_expired_sessions(&manager);
    set_max_sessions(&manager, 150);

    free_sessions(&manager);
    return 0;
}
```

This code provides a basic implementation of the session manager with methods to create, update, retrieve, and delete sessions. It includes logging for key events and handles memory allocation failures gracefully. The LRU (Least Recently Used) heuristic is used to manage session limits efficiently.']

