#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} data_source;

typedef struct {
    int value;
    long offset;
    int key;
    time_t last_updated;
    data_source* source_data;
    int is_deleted; // Soft deletion flag
} record;

#define INITIAL_CAPACITY 1000
#define CACHE_SIZE 256

// LRU Cache Node
typedef struct cache_node {
    int key;
    record* rec_ptr;
    struct cache_node* prev;
    struct cache_node* next;
} cache_node;

// LRU Cache Structure
typedef struct {
    cache_node* head;
    cache_node* tail;
    int size;
    int capacity;
} lru_cache;

// Global variables
record* records = NULL;
size_t record_count = 0;
size_t capacity = INITIAL_CAPACITY;
lru_cache cache;

// Function prototypes
void init_system();
record* find_record_by_key(int key);
void update_record(record* rec, int new_value);
void delete_record_soft(int key);
void refresh_cache_periodically();
void log_changes(const char* message);
int is_authorized_user();

// Helper functions for LRU Cache
cache_node* create_node(int key, record* rec_ptr) {
    cache_node* node = (cache_node*)malloc(sizeof(cache_node));
    if (!node) return NULL;
    node->key = key;
    node->rec_ptr = rec_ptr;
    node->prev = node->next = NULL;
    return node;
}

void add_to_cache(int key, record* rec_ptr);
record* get_from_cache(int key);
void remove_from_cache(cache_node* node);
void move_to_front(cache_node* node);

// Initialize the system
void init_system() {
    records = (record*)malloc(capacity * sizeof(record));
    if (!records) exit(EXIT_FAILURE);

    cache.head = cache.tail = NULL;
    cache.size = 0;
    cache.capacity = CACHE_SIZE;

    // Seed random number generator
    srand(time(NULL));

    // Initialize records with random values
    for (size_t i = 0; i < capacity; ++i) {
        records[i].value = rand() % 1000; // Random value within a range of 0-999
        records[i].offset = rand() % 10000;
        records[i].key = i + 1;
        records[i].is_deleted = 0;
        records[i].source_data = (data_source*)malloc(sizeof(data_source));
        if (!records[i].source_data) exit(EXIT_FAILURE);
        records[i].source_data->offset = records[i].offset;
        records[i].source_data->key = records[i].key;
        records[i].source_data->timestamp = time(NULL);
        records[i].last_updated = time(NULL);
    }
}

// Find record by key
record* find_record_by_key(int key) {
    if (key < 1 || key > capacity) return NULL;
    for (size_t i = 0; i < capacity; ++i) {
        if (!records[i].is_deleted && records[i].key == key)
            return &records[i];
    }
    // Check in cache
    record* cached_rec = get_from_cache(key);
    if (cached_rec) return cached_rec;
    return NULL;
}

// Update a record's value
void update_record(record* rec, int new_value) {
    if (!is_authorized_user()) {
        log_changes("Unauthorized attempt to update.");
        return;
    }
    if (rec->value == new_value) return; // Idempotent check

    rec->value = new_value;
    rec->last_updated = time(NULL);
    log_changes("Record updated successfully.");
}

// Soft delete a record
void delete_record_soft(int key) {
    if (!is_authorized_user()) {
        log_changes("Unauthorized attempt to delete.");
        return;
    }
    record* rec = find_record_by_key(key);
    if (rec && !rec->is_deleted) {
        rec->is_deleted = 1;
        log_changes("Record marked as deleted.");
    }
}

// Log changes
void log_changes(const char* message) {
    printf("%s\n", message); // Simplified logging
}

// Check authorization
int is_authorized_user() {
    return rand() % 2; // Randomly authorize for demonstration purposes
}

// Refresh cache periodically (dummy implementation)
void refresh_cache_periodically() {
    while (1) {
        sleep(10); // Wait for some time before refreshing

        // Simulate data fetching and updating cache
        for (int i = 0; i < CACHE_SIZE && i < capacity; ++i) {
            record* rec = find_record_by_key(i + 1);
            if (rec) add_to_cache(rec->key, rec);
        }
    }
}

// Cache management functions
void add_to_cache(int key, record* rec_ptr) {
    if (cache.size == cache.capacity) remove_from_cache(cache.tail);

    cache_node* node = create_node(key, rec_ptr);
    if (!node) return;

    move_to_front(node);

    cache.size++;
}

record* get_from_cache(int key) {
    for (cache_node* curr = cache.head; curr != NULL; curr = curr->next) {
        if (curr->key == key) {
            move_to_front(curr);
            return curr->rec_ptr;
        }
    }
    return NULL;
}

void remove_from_cache(cache_node* node) {
    if (!node || !cache.size) return;

    if (node == cache.head) cache.head = node->next;
    else node->prev->next = node->next;

    if (node == cache.tail) cache.tail = node->prev;
    else node->next->prev = node->prev;

    free(node);
    cache.size--;
}

void move_to_front(cache_node* node) {
    if (!cache.head || !node) return;

    if (node == cache.head) return;

    if (node == cache.tail) cache.tail = node->prev;
    else node->next->prev = node->prev;

    node->next = cache.head;
    node->prev = NULL;
    cache.head->prev = node;
    cache.head = node;
}

// Main function for demonstration
int main() {
    init_system();

    // Simulate some operations
    update_record(find_record_by_key(1), 500);
    delete_record_soft(2);

    // Start background process (in a real system, use threads)
    refresh_cache_periodically();

    return 0;
}
```

This code demonstrates how to manage a collection of records with soft deletion and caching using an LRU cache. It includes basic authorization checks, logging, and periodic cache refreshing. The implementation uses `malloc` for memory allocation and ensures that all allocations are properly managed to prevent leaks.']

