typedef struct {
    double *doubles;
    char **strings;
    item *items;
    callbacks_metadata *metadata;
    int *active_callbacks_count;
    pthread_mutex_t lock;  // For thread safety
} memory_manager;

typedef struct {
    double *doubles;
    char **strings;
    item *items;
    callbacks_metadata metadata;
    size_t doubles_size, strings_size, items_size;
    size_t total_memory_used;
} metadata_info;

void log_event(const char* event) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), event);
}

void manage_memory(memory_manager *mm, size_t memory_budget, int initial_doubles, int initial_strings, int initial_items, int initial_callbacks) {
    pthread_mutex_init(&mm->lock, NULL);

    // Calculate total initial memory required
    size_t double_size = sizeof(double) * initial_doubles;
    size_t string_size = sizeof(char*) * initial_strings;  // Assume strings are initialized elsewhere
    size_t item_size = sizeof(item) * initial_items;
    size_t callback_size = sizeof(callback_fn*) * initial_callbacks;
    size_t memory_required = double_size + string_size + item_size + callback_size;

    if (memory_budget < memory_required || initial_doubles <= 0 || initial_strings <= 0 || initial_items <= 0 || initial_callbacks <= 0) {
        log_event("Initial configuration exceeds budget or invalid parameters");
        return;
    }

    // Allocate memory within the constraints
    mm->doubles = malloc(double_size);
    mm->strings = malloc(string_size);
    mm->items = malloc(item_size);
    mm->metadata = malloc(sizeof(callbacks_metadata));
    mm->metadata->callbacks = malloc(callback_size);

    if (!mm->doubles || !mm->strings || !mm->items || !mm->metadata || !mm->metadata->callbacks) {
        log_event("Memory allocation failed");
        free_resources(mm);
        return;
    }

    // Initialize metadata
    mm->metadata->count = initial_callbacks;
    mm->metadata->avg_duration = 0.0;

    // Record memory usage
    metadata_info *meta = malloc(sizeof(metadata_info));
    if (!meta) {
        log_event("Failed to allocate memory for metadata info");
        free_resources(mm);
        return;
    }

    meta->doubles = mm->doubles;
    meta->strings = mm->strings;
    meta->items = mm->items;
    meta->metadata = *mm->metadata;
    meta->doubles_size = initial_doubles;
    meta->strings_size = initial_strings;
    meta->items_size = initial_items;
    meta->total_memory_used = memory_required;

    log_event("Memory allocated successfully");

    // Simulate periodic snapshots and optimization
    void* snapshot_thread(void* arg) {
        while (1) {
            pthread_mutex_lock(&mm->lock);
            printf("Snapshot: Total Memory Used: %zu bytes\n", meta->total_memory_used);
            pthread_mutex_unlock(&mm->lock);
            sleep(5);  // Periodic interval
        }
        return NULL;
    }

    pthread_t snapshot_tid;
    pthread_create(&snapshot_tid, NULL, snapshot_thread, (void*)meta);

    // Example of dynamic callback registration and execution
    void example_callback(void) {
        printf("Callback executed\n");
    }

    mm->metadata->callbacks[0] = &example_callback;
    mm->metadata->callbacks[0]();

    // Ensure clean exit by freeing resources
    pthread_cancel(snapshot_tid);
    free_resources(mm);
    free(meta);

    log_event("Memory deallocated successfully");
}

void free_resources(memory_manager *mm) {
    if (mm->doubles) free(mm->doubles);
    if (mm->strings) free(mm->strings);
    if (mm->items) free(mm->items);
    if (mm->metadata) {
        if (mm->metadata->callbacks) free(mm->metadata->callbacks);
        free(mm->metadata);
    }
    pthread_mutex_destroy(&mm->lock);
}

int main() {
    memory_manager mm;
    manage_memory(&mm, 1024 * 1024, 1000, 500, 200, 10); // Example usage
    return 0;
}
