#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int *data;
    int key;
} record;

int manage_memory(int num_records, int range_min, int range_max) {
    if (num_records <= 0 || range_min >= range_max) {
        return -1; // Invalid input
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Allocate memory for structures
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -1; // Allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    // Initialize offsets and keys
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i;
    }

    int *used_keys = calloc(range_max - range_min + 1, sizeof(int));
    if (!used_keys) {
        free(offsets);
        free(keys);
        free(records);
        return -1; // Allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = range_min + rand() % (range_max - range_min + 1);
        } while (used_keys[key - range_min]);

        keys[i] = key;
        used_keys[key - range_min] = 1;

        records[i].data = &keys[i];
        records[i].key = key;
    }

    free(used_keys);

    // Validation
    for (int i = 0; i < num_records; ++i) {
        if (records[i].data != &keys[i]) {
            // Cleanup on error
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Example usage of the allocated memory
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Offset=%ld, Key=%d, Data Pointer=%p\n", 
               i, offsets[i], records[i].key, records[i].data);
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);

    return num_records; // Successfully initialized
}

int main() {
    int result = manage_memory(10, 1, 100);
    if (result == -1) {
        printf("Initialization failed due to insufficient resources.\n");
    } else {
        printf("Successfully initialized %d records.\n", result);
    }
    return 0;
}
```

