    if (max_records > max_records_based_on_memory) {
        max_records = max_records_based_on_memory;
    }

    if (max_records == 0) return -1;

    // Allocate memory
    long *offsets = malloc(max_records * offset_size);
    int *keys = malloc(max_records * key_size);
    record *records = malloc(max_records * record_struct_size);
    bool *metadata = calloc(max_records, metadata_size);

    if (!offsets || !keys || !records || !metadata) {
        // Error handling
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets); free(keys); free(records); free(metadata);
        return -1;
