```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_MEMORY_LIMIT (1024 * 1024 * 100) // Example limit: 100 MB

typedef struct {
    int *int_ptr;
    int key;
} record;

void log_memory_usage(size_t size) {
    static size_t total_allocated = 0;
    total_allocated += size;
    printf("Total memory allocated: %zu bytes\n", total_allocated);
}

int initialize_data(int num_records, int min_key, int max_key, long alignment) {
    if (num_records <= 0 || min_key >= max_key) return -1;

    size_t offset_size = num_records * sizeof(long);
    size_t key_size = num_records * sizeof(int);
    size_t record_size = num_records * sizeof(record);

    // Calculate total memory requirement
    size_t total_memory = offset_size + key_size + record_size;
    if (total_memory > MAX_MEMORY_LIMIT) return -1;

    // Allocate memory with alignment requirements
    long* offsets = aligned_alloc(alignment, offset_size);
    int* keys = aligned_alloc(alignment, key_size);
    record* records = aligned_alloc(alignment, record_size);

    if (!offsets || !keys || !records) {
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        free(records); records = NULL;
        return -1;
    }

    log_memory_usage(total_memory);

    // Initialize offset array
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i;
    }

    // Populate key array with unique random integers
    srand(time(NULL));
    int generated_keys[num_records];
    memset(generated_keys, 0, sizeof(generated_keys));

    for (int i = 0; i < num_records;) {
        int rand_key = min_key + rand() % (max_key - min_key);
        if (!generated_keys[rand_key - min_key]) { // Assuming keys are within range
            keys[i] = rand_key;
            generated_keys[rand_key - min_key] = 1;
            ++i;
        }
    }

    // Assign records' integer pointers to point to unique elements in the key array
    for (int i = 0; i < num_records; ++i) {
        records[i].int_ptr = &keys[i];
        records[i].key = keys[i];
    }

    printf("Initialization successful with %d records.\n", num_records);

    // Memory deallocation routine
    free(offsets);
    free(keys);
    free(records);

    return num_records;
}

int main() {
    int num_records = 1000; // Example number of records
