['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int age;
    float salary;
} EmployeeRecord;

// Function prototypes
void processAndManageFileRecords(const char *filename);
EmployeeRecord* readRecordsFromFile(const char *filename, size_t *recordCount);
int addOrUpdateRecord(EmployeeRecord **records, size_t *count, const EmployeeRecord *newRecord, int index);
const EmployeeRecord* getRecordByIndex(const EmployeeRecord *records, size_t count, int index);
void sortRecords(EmployeeRecord *records, size_t count, char sortBy);
float calculateAverageSalary(const EmployeeRecord *records, size_t count);

// Main function to process and manage file records
void processAndManageFileRecords(const char *filename) {
    size_t recordCount = 0;
    EmployeeRecord *records = readRecordsFromFile(filename, &recordCount);

    if (!records) return;

    // Example operations on the records

    // Add a new employee record or update an existing one
    EmployeeRecord newEmployee = {"John Doe", 30, 50000.0};
    addOrUpdateRecord(&records, &recordCount, &newEmployee, -1);  // Index -1 means add new

    // Retrieve and print a specific record by index
    const EmployeeRecord *retrievedRecord = getRecordByIndex(records, recordCount, 0);
    if (retrievedRecord) {
        printf("Retrieved Record: %s, Age: %d, Salary: %.2f\n", retrievedRecord->name, retrievedRecord->age, retrievedRecord->salary);
    }

    // Sort records by age
    sortRecords(records, recordCount, 'a');

    // Calculate and print average salary
    float avgSalary = calculateAverageSalary(records, recordCount);
    printf("Average Salary: %.2f\n", avgSalary);

    // Free allocated memory
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i].name);
    }
    free(records);
}

// Read records from a binary file
EmployeeRecord* readRecordsFromFile(const char *filename, size_t *recordCount) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    // Determine the number of records in the file
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t recordSize = sizeof(EmployeeRecord) - sizeof(char*);
    *recordCount = fileSize / (recordSize + sizeof(size_t)); // Assuming name length is stored

    EmployeeRecord *records = malloc(*recordCount * sizeof(EmployeeRecord));
    if (!records) {
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < *recordCount; ++i) {
        size_t nameLength;
        fread(&nameLength, sizeof(size_t), 1, file);

        records[i].name = malloc(nameLength + 1);
        if (!records[i].name) {
            // Handle memory allocation failure
            while (--i >= 0) free(records[i].name);
            free(records);
            fclose(file);
            return NULL;
        }

        fread(records[i].name, nameLength, 1, file);
        records[i].name[nameLength] = '\0';

        fread(&records[i].age, sizeof(int), 1, file);
        fread(&records[i].salary, sizeof(float), 1, file);
    }

    fclose(file);
    return records;
}

// Add or update a record in the dynamic array
int addOrUpdateRecord(EmployeeRecord **records, size_t *count, const EmployeeRecord *newRecord, int index) {
    if (index < 0 || (size_t)index >= *count) { // Add new record
        *records = realloc(*records, (*count + 1) * sizeof(EmployeeRecord));
        if (!*records) return -1; // Memory allocation failed

        (*records)[*count].name = strdup(newRecord->name);
        if (!(*records)[*count].name) {
            free((*records)[*count].salary); // Clean up partially allocated memory
            return -1;
        }
        (*records)[*count].age = newRecord->age;
        (*records)[*count].salary = newRecord->salary;
        (*count)++;
    } else { // Update existing record
        free((*records)[index].name);
        (*records)[index].name = strdup(newRecord->name);
        if (!(*records)[index].name) return -1; // Memory allocation failed

        (*records)[index].age = newRecord->age;
        (*records)[index].salary = newRecord->salary;
    }
    return 0;
}

// Retrieve a record by its index
const EmployeeRecord* getRecordByIndex(const EmployeeRecord *records, size_t count, int index) {
    if (index < 0 || (size_t)index >= count) return NULL;
    return &records[index];
}

// Sort records based on the specified field
void sortRecords(EmployeeRecord *records, size_t count, char sortBy) {
    if (!records || count == 0) return;

    int (*comparator)(const void *, const void *) = NULL;

    if (sortBy == 'a') { // Sort by age
        comparator = [](const void *a, const void *b) -> int {
            EmployeeRecord *recordA = (EmployeeRecord *)a;
            EmployeeRecord *recordB = (EmployeeRecord *)b;
            return recordA->age - recordB->age;
        };
    } else if (sortBy == 's') { // Sort by salary
        comparator = [](const void *a, const void *b) -> int {
            EmployeeRecord *recordA = (EmployeeRecord *)a;
            EmployeeRecord *recordB = (EmployeeRecord *)b;
            return (recordA->salary > recordB->salary) - (recordA->salary < recordB->salary);
        };
    }

    if (comparator) {
        qsort(records, count, sizeof(EmployeeRecord), comparator);
    }
}

// Calculate the average salary of all records
float calculateAverageSalary(const EmployeeRecord *records, size_t count) {
    float totalSalary = 0.0;
    for (size_t i = 0; i < count; ++i) {
        totalSalary += records[i].salary;
    }
    return count > 0 ? totalSalary / count : 0.0;
}
```']

