```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define KEY_RANGE 10000

typedef struct {
    int key;
    int *data_ptr;
    time_t timestamp;
    bool access_status;
} Record;

typedef struct {
    Record **records;
    int *keys;
    bool *access_status;
    time_t *history;
    pthread_mutex_t lock;
} MemoryManager;

// Helper function to generate a unique random integer
int generate_unique_random(int *used_keys, size_t count) {
    int key;
    do {
        key = rand() % KEY_RANGE;
    } while (count && used_keys[key]);
    return key;
}

// Initialize the memory manager
int initialize_memory_manager(MemoryManager *manager, int max_records) {
    if (!manager || max_records <= 0 || max_records > MAX_RECORDS) {
        return -1;
    }

    pthread_mutex_init(&manager->lock, NULL);

    // Allocate memory for keys and arrays
    int *keys = (int *)malloc(max_records * sizeof(int));
    Record **records = (Record **)calloc(max_records, sizeof(Record *));
    bool *access_status = (bool *)calloc(max_records, sizeof(bool));
    time_t *history = (time_t *)calloc(max_records, sizeof(time_t));

    if (!keys || !records || !access_status || !history) {
        free(keys);
        free(records);
        free(access_status);
        free(history);
        pthread_mutex_destroy(&manager->lock);
        return -1;
    }

    // Initialize keys with unique random integers
    bool used_keys[KEY_RANGE] = {false};
    for (int i = 0; i < max_records; ++i) {
        int key = generate_unique_random(used_keys, max_records);
        while ((i > 0 && keys[i - 1] == key) || used_keys[key]) {
            key = generate_unique_random(used_keys, max_records);
        }
        keys[i] = key;
        used_keys[key] = true;
    }

    // Initialize records
    for (int i = 0; i < max_records; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            while (i >= 0) free(records[--i]);
            free(keys);
            free(records);
            free(access_status);
            free(history);
            pthread_mutex_destroy(&manager->lock);
            return -1;
        }

        record->key = keys[i];
        record->data_ptr = &keys[i];
        record->timestamp = time(NULL);
        record->access_status = false;

        records[i] = record;
    }

    // Initialize access status and history
    for (int i = 0; i < max_records; ++i) {
        access_status[i] = false;
        history[i] = time(NULL);
    }

    // Assign to manager
    manager->records = records;
    manager->keys = keys;
    manager->access_status = access_status;
    manager->history = history;

    return max_records;
}

// Free the memory manager resources
void free_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_RECORDS && manager->records[i]; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    free(manager->keys);
    free(manager->access_status);
    free(manager->history);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL));

    MemoryManager manager;
    int result = initialize_memory_manager(&manager, 500); // Example usage

    if (result > 0) {
        printf("Successfully initialized %d records.\n", result);
    } else {
        printf("Failed to initialize memory manager.\n");
    }

    free_memory_manager(&manager);

    return 0;
}
```

### Key Points:

- **Thread Safety**: A mutex is used to ensure thread safety when accessing shared resources.
- **Memory Management**: Memory is allocated for keys, records, access status, and history. If allocation fails at any point, all previously allocated memory is freed.
- **Unique Keys**: Random unique keys are generated with checks to prevent duplicates and adjacent duplicates.
- **Error Handling**: The function returns the number of initialized records or `-1` if initialization fails.
- **Resource Cleanup**: All resources are released properly in `free_memory_manager`.']

