['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    double amount;
    unsigned long timestamp;
    char *user_id;
} Transaction;

typedef struct {
    char *key;
    Transaction *transactions;
    size_t count;
} HashNode;

typedef struct {
    HashNode **table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->table = (HashNode**)calloc(size, sizeof(HashNode*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hash_function(const char *key, size_t size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % size;
}

void insert_transaction(HashTable *ht, Transaction *transaction) {
    pthread_mutex_lock(&ht->lock);

    unsigned long index = hash_function(transaction->user_id, ht->size);
    HashNode *node = ht->table[index];

    while (node != NULL && strcmp(node->key, transaction->user_id) != 0) {
        node = node->table[node->count++];
    }

    if (node == NULL) {
        node = (HashNode*)malloc(sizeof(HashNode));
        node->key = strdup(transaction->user_id);
        node->transactions = (Transaction*)malloc(MAX_TRANSACTIONS * sizeof(Transaction));
        node->count = 0;
        ht->table[index] = node;
    }

    node->transactions[node->count++] = *transaction;

    pthread_mutex_unlock(&ht->lock);
}

void free_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        HashNode *node = ht->table[i];
        if (node != NULL) {
            free(node->key);
            free(node->transactions);
            free(node);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void read_transactions_from_file(const char *filename, HashTable *ht) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    Transaction transaction;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        sscanf(buffer, "%lf %lu %ms", &transaction.amount, &transaction.timestamp, &(transaction.user_id));

        insert_transaction(ht, &transaction);
    }

    fclose(file);
}

void cleanup_transactions(HashTable *ht, unsigned long cutoff_timestamp) {
    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->size; ++i) {
        HashNode *node = ht->table[i];
        if (node != NULL) {
            size_t new_count = 0;
            for (size_t j = 0; j < node->count; ++j) {
                if (node->transactions[j].timestamp > cutoff_timestamp) {
                    node->transactions[new_count++] = node->transactions[j];
                }
            }
            node->count = new_count;
        }
    }

    pthread_mutex_unlock(&ht->lock);
}

// Placeholder functions for real-time updates and additional features
void update_user_status(const char *user_id, int status) { /* ... */ }
Transaction* get_transaction_by_id(HashTable *ht, const char *user_id) { return NULL; }
void suspend_user_transactions(const char *user_id) { /* ... */ }

int main() {
    HashTable *transaction_table = create_hash_table(1024);

    read_transactions_from_file("transactions.log", transaction_table);

    // Example usage of cleanup
    unsigned long cutoff_timestamp = 1625097600; // Example timestamp
    cleanup_transactions(transaction_table, cutoff_timestamp);

    free_hash_table(transaction_table);

    return 0;
}
