#include <stdio.h>
#include <stdlib.h>
import stdarg.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int *key;
    int value;
    long *offset;
} record;

typedef struct {
    record **records;
    double *doubles;
    size_t count;
    size_t capacity;
} dataHandler;

record* allocate_record() {
    record *rec = (record*) malloc(sizeof(record));
    if (!rec) return NULL;

    rec->key = (int*) malloc(sizeof(int));
    if (!rec->key) {
        free(rec);
        return NULL;
    }

    rec->offset = (long*) malloc(sizeof(long));
    if (!rec->offset) {
        free(rec->key);
        free(rec);
        return NULL;
    }

    return rec;
}

void deallocate_record(record *rec) {
    if (rec) {
        free(rec->key);
        free(rec->offset);
        free(rec);
    }
}

dataHandler* create_data_handler() {
    dataHandler *handler = (dataHandler*) malloc(sizeof(dataHandler));
    if (!handler) return NULL;

    handler->records = (record**) calloc(INITIAL_CAPACITY, sizeof(record*));
    if (!handler->records) {
        free(handler);
        return NULL;
    }

    handler->doubles = (double*) calloc(INITIAL_CAPACITY, sizeof(double));
    if (!handler->doubles) {
        free(handler->records);
        free(handler);
        return NULL;
    }

    handler->count = 0;
    handler->capacity = INITIAL_CAPACITY;

    return handler;
}

void expand_data_handler(dataHandler *handler) {
    size_t new_capacity = handler->capacity * 2;

    record **new_records = (record**) realloc(handler->records, new_capacity * sizeof(record*));
    if (!new_records) return;

    double *new_doubles = (double*) realloc(handler->doubles, new_capacity * sizeof(double));
    if (!new_doubles) {
        free(new_records);
        return;
    }

    handler->records = new_records;
    handler->doubles = new_doubles;
    handler->capacity = new_capacity;
}

void add_record(dataHandler *handler, int key, int value, long offset, double dbl_value) {
    if (handler->count == handler->capacity) expand_data_handler(handler);

    for (size_t i = 0; i < handler->count; ++i) {
        if (*(handler->records[i]->key) == key) {
            *(handler->records[i]->value) += value;
            handler->doubles[i] = (handler->doubles[i] + dbl_value) / 2.0;
            return;
        }
    }

    record *new_rec = allocate_record();
    if (!new_rec) return;

    *(new_rec->key) = key;
    new_rec->value = value;
    *(new_rec->offset) = offset;

    handler->records[handler->count] = new_rec;
    handler->doubles[handler->count++] = dbl_value;
}

record* get_record(dataHandler *handler, size_t index) {
    if (index < handler->count) return handler->records[index];
    return NULL;
}

void free_data_handler(dataHandler *handler) {
    for (size_t i = 0; i < handler->count; ++i) {
        deallocate_record(handler->records[i]);
    }

    free(handler->records);
    free(handler->doubles);
    free(handler);
}

int main(int argc, char *argv[]) {
    if (argc == 1 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [options] <input_file>\n", argv[0]);
        printf("Options:\n");
        printf("  --help     Display this help and exit\n");
        printf("  -c         Enable concurrent operations (not implemented)\n");
        printf("  -o <file>  Specify output file (not implemented)\n");
        return 1;
    }

    char *input_file = NULL;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-c") == 0) {
            // Handle concurrency option
        } else if (strncmp(argv[i], "-o", 2) == 0 && i + 1 < argc) {
            // Handle output file option
        } else {
            input_file = argv[i];
        }
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    dataHandler *handler = create_data_handler();
    if (!handler) {
        fclose(file);
        return 1;
    }

    char line[256];
    int key, value;
    long offset;
    double dbl_value;

    while (fgets(line, sizeof(line), file)) {
        sscanf(line, "%d,%d,%ld,%lf", &key, &value, &offset, &dbl_value);
        add_record(handler, key, value, offset, dbl_value);
    }

    printf("Number of lines read: %zu\n", handler->count);

    free_data_handler(handler);
    fclose(file);
    return 0;
}
