#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

typedef struct {
    record* records;
    size_t capacity;
    pthread_mutex_t lock;
} RecordManager;

void initialize_rng() {
    srand((unsigned) time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

RecordManager* create_manager(size_t initial_capacity) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = calloc(initial_capacity, sizeof(record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    initialize_rng();

    for (size_t i = 0; i < manager->capacity; ++i) {
        record* rec = &manager->records[i];
        rec->value = random_int(1, 100); // Adjust range as needed
        rec->offset = malloc(sizeof(long));
        rec->key = malloc(sizeof(int));
        if (!rec->offset || !rec->key) {
            for (size_t j = 0; j < i; ++j) {
                free(manager->records[j].offset);
                free(manager->records[j].key);
            }
            free(manager->records);
            pthread_mutex_destroy(&manager->lock);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

int insert_record(RecordManager* manager, int value, long offset, int key) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i].value == 0) { // Assuming 0 as uninitialized value
            record* rec = &manager->records[i];
            rec->value = value;
            rec->offset = malloc(sizeof(long));
            rec->key = malloc(sizeof(int));
            if (!rec->offset || !rec->key) {
                pthread_mutex_unlock(&manager->lock);
                return -1; // Allocation failure
            }
            *rec->offset = offset;
            *rec->key = key;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -2; // No available space
}

int update_record(RecordManager* manager, size_t index, int value, long offset, int key) {
    if (!manager || index >= manager->capacity) return -1;

    pthread_mutex_lock(&manager->lock);

    record* rec = &manager->records[index];
    *rec->offset = offset;
    *rec->key = key;
    rec->value = value;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int delete_record(RecordManager* manager, size_t index) {
    if (!manager || index >= manager->capacity) return -1;

    pthread_mutex_lock(&manager->lock);

    record* rec = &manager->records[index];
    free(rec->offset);
    free(rec->key);
    rec->value = 0; // Mark as deleted

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

size_t search_record(RecordManager* manager, int value) {
    if (!manager) return (size_t)-1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i].value == value) {
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return (size_t)-1; // Not found
}

void destroy_manager(RecordManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        free(manager->records[i].offset);
        free(manager->records[i].key);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
