#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    bool status_flag;
} record;

typedef struct {
    record *records;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

#define INITIAL_CAPACITY 16

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

RecordCollection* init_record_collection(size_t num_records, int max_key, long max_offset) {
    if (num_records == 0 || max_key <= 0 || max_offset <= 0) {
        return NULL;
    }

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        log_error("Failed to allocate memory for record collection.");
        return NULL;
    }

    collection->records = NULL;
    collection->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&collection->lock, NULL);

    while (true) {
        size_t new_capacity = (num_records > collection->capacity) ? num_records : collection->capacity;

        record *new_records = realloc(collection->records, sizeof(record) * new_capacity);
        if (!new_records) {
            log_error("Failed to allocate memory for records.");
            free(collection->records);
            free(collection);
            return NULL;
        }

        collection->records = new_records;

        if (collection->capacity >= num_records) break;

        size_t count = 0;
        bool *key_in_use = calloc(max_key, sizeof(bool));
        srand(time(NULL));

        pthread_mutex_lock(&collection->lock);

        for (size_t i = 0; i < collection->capacity; ++i) {
            int key;
            do {
                key = rand() % max_key;
            } while (key_in_use[key]);

            record *rec = &collection->records[i];
            rec->key = key;
            rec->offset = rand() % max_offset;
            rec->status_flag = false;

            key_in_use[key] = true;
            count++;
        }

        free(key_in_use);

        if (count >= num_records) break;

        pthread_mutex_unlock(&collection->lock);
    }

    return collection;
}

record* get_record(RecordCollection *collection, int key) {
    if (!collection || !collection->records) return NULL;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &collection->records[i];
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
