typedef struct {
    int key;
    long offset;
    bool status;
} record;

// Union-Find structure and functions
typedef struct {
    int *parent, *rank;
} union_find;

union_find* uf_create(int size) {
    union_find *uf = (union_find *)malloc(sizeof(union_find));
    if (!uf) return NULL;

    uf->parent = (int *)calloc(size, sizeof(int));
    uf->rank = (int *)calloc(size, sizeof(int));
    if (!uf->parent || !uf->rank) {
        free(uf->parent);
        free(uf->rank);
        free(uf);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }

    return uf;
}

int find(union_find *uf, int u) {
    if (uf->parent[u] != u)
        uf->parent[u] = find(uf, uf->parent[u]);
    return uf->parent[u];
}

void union_sets(union_find *uf, int u, int v) {
    int rootU = find(uf, u);
    int rootV = find(uf, v);

    if (rootU != rootV) {
        if (uf->rank[rootU] > uf->rank[rootV])
            uf->parent[rootV] = rootU;
        else if (uf->rank[rootU] < uf->rank[rootV])
            uf->parent[rootU] = rootV;
        else {
            uf->parent[rootV] = rootU;
            uf->rank[rootU]++;
        }
    }
}

void uf_destroy(union_find *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

// Function to create and initialize the dynamic set of records
record* create_records(int num_records, long max_offset, int max_key,
                       long *offsets, int *keys, int *disjoint_pairs,
                       double *processing_time) {

    if (num_records <= 0 || max_offset <= 0 || max_key <= 0)
        return NULL;

    record *records = (record *)malloc(num_records * sizeof(record));
    offsets = (long *)malloc(num_records * sizeof(long));
    keys = (int *)malloc(num_records * sizeof(int));

    if (!records || !offsets || !keys) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    double total_time = 0.0;

    struct timespec start, end;
    int num_disjoint_pairs = 0;

    union_find *uf = uf_create(num_records);
    if (!uf) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % max_key;
        records[i].offset = rand() % max_offset;
        records[i].status = true;

        offsets[i] = records[i].offset;
        keys[i] = records[i].key;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = i + 1; j < num_records; ++j) {
            int root_i = find(uf, i);
            int root_j = find(uf, j);

            if (root_i != root_j) {
                union_sets(uf, root_i, root_j);
                num_disjoint_pairs++;
            }
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time = end.tv_sec - start.tv_sec;
    elapsed_time += (end.tv_nsec - start.tv_nsec) / 1.0e9;

    *disjoint_pairs = num_disjoint_pairs;
    *processing_time = elapsed_time;

    uf_destroy(uf);

    return records;
}

int main() {
    int num_records = 1000;
    long max_offset = 10000L;
    int max_key = 500;
    long offsets[num_records];
    int keys[num_records];
    int disjoint_pairs;
    double processing_time;

    record *records = create_records(num_records, max_offset, max_key,
                                     offsets, keys, &disjoint_pairs, &processing_time);

    if (records) {
        printf("Records created successfully\n");
        printf("Number of disjoint pairs: %d\n", disjoint_pairs);
        printf("Processing time: %.6f seconds\n", processing_time);

        free(records);
    } else {
        printf("Failed to create records\n");
    }

    return 0;
}
