#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <shared_mutex>

struct Record {
    int value;
    long* offset_ptr;
    int* key_ptr;
};

class DynamicCollection {
private:
    struct HashNode {
        int key;
        long offset;
        Record record;
        bool inUse;
        std::atomic<bool> deleted{false};

        HashNode(int k, long o) : key(k), offset(o), inUse(true), deleted(false) {}
    };

    std::vector<HashNode*> hashTable;
    std::vector<Record> records;
    mutable std::shared_mutex mutex_;

    size_t tableSize;
    size_t recordCount;

    // Utility function for resizing
    void resizeHashTable() {
        size_t newSize = tableSize * 2;
        std::vector<HashNode*> newTable(newSize, nullptr);

        for (auto& node : hashTable) {
            if (node && node->inUse && !node->deleted.load()) {
                auto newIndex = node->key % newSize;
                while (newTable[newIndex] != nullptr) {
                    newIndex = (newIndex + 1) % newSize; // Linear probing
                }
                newTable[newIndex] = node;
            }
        }

        hashTable = std::move(newTable);
        tableSize = newSize;
    }

public:
    DynamicCollection(size_t size, int minValue, int maxValue)
        : recordCount(0), tableSize(size) {

        // Initialize the hash table with empty nodes
        hashTable.reserve(tableSize);
        for (size_t i = 0; i < tableSize; ++i) {
            hashTable.push_back(nullptr);
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(minValue, maxValue);

        records.reserve(size);
        for (size_t i = 0; i < size; ++i) {
            long offset = static_cast<long>(i); // Example of setting an offset
            int key = static_cast<int>(dis(gen));

            Record record;
            record.value = dis(gen);
            record.offset_ptr = &offset;
            record.key_ptr = &key;

            records.push_back(record);

            size_t hashIndex = key % tableSize;
            while (hashTable[hashIndex] != nullptr) {
                hashIndex = (hashIndex + 1) % tableSize; // Linear probing
            }

            auto* node = new HashNode(key, offset);
            if (!node) throw std::bad_alloc();

            hashTable[hashIndex] = node;
        }
    }

    ~DynamicCollection() {
        for (auto& node : hashTable) {
            delete node;
        }
    }

    Record getRecord(size_t index) const {
        std::shared_lock lock(mutex_);
        if (index < records.size()) {
            return records[index];
        }
        throw std::out_of_range("Index out of range");
    }

    void updateRecordValue(size_t index, int newValue) {
        std::unique_lock lock(mutex_);
        if (index < records.size()) {
            records[index].value = newValue;
        } else {
            throw std::out_of_range("Index out of range");
        }
    }

    void iterateRecords() const {
        std::shared_lock lock(mutex_);
        for (const auto& record : records) {
            // Process each record
            std::cout << "Record Value: " << record.value 
                      << ", Offset: " << *record.offset_ptr 
                      << ", Key: " << *record.key_ptr << '\n';
        }
    }

    void unionFindCheck() const {
        auto start = std::chrono::high_resolution_clock::now();
        // Implement Union-Find logic here for disjoint check
        auto end = std::chrono::high_resolution_clock::now();

        std::cout << "Union-Find Check took "
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count()
                  << " milliseconds\n";
    }

    // More methods such as dynamic resizing, handling external updates etc.

    void integrateExternalDataSource() {
        // Implementation for seamless integration
    }
};

int main() {
    try {
        DynamicCollection collection(1000, 1, 100);
        collection.iterateRecords();

        std::thread t1([&]() { collection.updateRecordValue(10, 42); });
        std::thread t2([&]() { collection.getRecord(10); });

        t1.join();
        t2.join();

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
