#include <stdio.h>
#include <stdlib.h>

// Define the node structure.
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function to create a new node with the given value.
Node* create_node(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        exit(EXIT_FAILURE);
    }
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

// Function to initialize the list with a head node.
Node* initialize_list(int initial_value) {
    return create_node(initial_value);
}

// Function to add a node to the end of the list.
void append_node(Node** head, int value) {
    Node* newNode = create_node(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to print the list in reverse order using recursion.
void print_reverse(Node* head) {
    if (head == NULL) return;
    print_reverse(head->next);
    printf("%d\n", head->value);
}

// Main function for user interaction and execution of operations.
int main() {
    int initial_value, input_value, sentinel = -1; // Sentinel value to terminate input.

    printf("Enter the initial value for the head node: ");
    if (scanf("%d", &initial_value) != 1 || initial_value == sentinel) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    Node* head = initialize_list(initial_value);

    while (1) {
        printf("Enter an integer to add to the list (-1 to finish): ");
        if (scanf("%d", &input_value) != 1 || input_value == sentinel) break;

        append_node(&head, input_value);
    }

    printf("\nList in reverse order:\n");
    print_reverse(head);

    // Free allocated memory
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    return EXIT_SUCCESS;
}
