}

config_manager_t* create_config_manager() {
    config_manager_t *manager = malloc(sizeof(config_manager_t));
    if (!manager) {
        log_message("Failed to allocate memory for config manager");
        return NULL;
    }

    manager->capacity = 10; // Initial capacity
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->configs = malloc(manager->capacity * sizeof(config_t*));
    if (!manager->configs) {
        log_message("Failed to allocate memory for config array");
        free(manager);
        return NULL;
    }

    memset(manager->configs, 0, manager->capacity * sizeof(config_t*));
    return manager;
}

void destroy_config_manager(config_manager_t *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configs[i]->name);
        free(manager->configs[i]);
    }

    free(manager->configs);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_config(config_manager_t *manager, mode_t mode, float max_sensitivity, const char *name) {
    if (!manager || !name || manager->count >= NUM_MODES)
        return -1;

    // Check for unique mode
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i]->mode == mode) {
            log_message("Mode already exists");
            return -2;
        }
    }

    pthread_mutex_lock(&manager->lock);

    // Resize if necessary
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        config_t **new_configs = realloc(manager->configs, new_capacity * sizeof(config_t*));

        if (!new_configs) {
            log_message("Failed to reallocate memory for config array");
            pthread_mutex_unlock(&manager->lock);
            return -3;
        }

        memset(new_configs + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(config_t*));
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    config_t *config = malloc(sizeof(config_t));
    if (!config) {
        log_message("Failed to allocate memory for a single config");
        pthread_mutex_unlock(&manager->lock);
        return -4;
    }

    float sensitivity = (rand() / (float)RAND_MAX) * max_sensitivity;
    config->mode = mode;
    config->sensitivity = sensitivity;
    size_t name_len = strlen(name) + 1;
    config->name = malloc(name_len);

    if (!config->name) {
        log_message("Failed to allocate memory for config name");
        free(config);
        pthread_mutex_unlock(&manager->lock);
        return -5;
    }

    strncpy(config->name, name, name_len);

    manager->configs[manager->count++] = config;

    pthread_mutex_unlock(&manager->lock);
    log_message("Config added successfully");
    return 0;
}

config_t* get_config_by_name(config_manager_t *manager, const char *name) {
    if (!manager || !name)
        return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i]->name, name) == 0) {
            config_t *config_copy = malloc(sizeof(config_t));
            if (!config_copy) {
                log_message("Failed to allocate memory for config copy");
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }

            memcpy(config_copy, manager->configs[i], sizeof(config_t));
            config_copy->name = strdup(manager->configs[i]->name);

