#include <string.h>
#include <pthread.h>

typedef struct FileEntry {
    char *name;
    size_t size;
    pthread_mutex_t lock;
} FileEntry;

typedef struct DirectoryEntry {
    char *name;
    size_t size;
    struct DirectoryEntry *parent;
    FileEntry *file_entry; // NULL if it's a directory
    struct DirectoryEntry **children;
    int child_count;
    pthread_mutex_t lock;
} DirectoryEntry;

// Function to initialize a file entry
FileEntry* create_file_entry(const char *name, size_t size) {
    FileEntry *entry = (FileEntry *)malloc(sizeof(FileEntry));
    if (!entry) return NULL;

    entry->name = strdup(name);
    entry->size = size;
    pthread_mutex_init(&entry->lock, NULL);

    return entry;
}

// Function to initialize a directory entry
DirectoryEntry* create_directory_entry(const char *name, DirectoryEntry *parent) {
    DirectoryEntry *entry = (DirectoryEntry *)malloc(sizeof(DirectoryEntry));
    if (!entry) return NULL;

    entry->name = strdup(name);
    entry->size = 0;
    entry->parent = parent;
    entry->file_entry = NULL;
    entry->children = NULL;
    entry->child_count = 0;
    pthread_mutex_init(&entry->lock, NULL);

    return entry;
}

// Function to add a file entry to a directory
int add_file_to_directory(DirectoryEntry *directory, FileEntry *file) {
    if (!directory || !file) return -1;

    pthread_mutex_lock(&directory->lock);
    DirectoryEntry **new_children = (DirectoryEntry **)realloc(directory->children,
                                                               sizeof(DirectoryEntry *) * (directory->child_count + 1));
    if (!new_children) {
        pthread_mutex_unlock(&directory->lock);
        return -1;
    }

    directory->children = new_children;
    FileEntry *dir_file = create_directory_entry(file->name, directory);
    if (!dir_file) {
        free(new_children);
        pthread_mutex_unlock(&directory->lock);
        return -1;
    }

    dir_file->file_entry = file;
    directory->children[directory->child_count] = dir_file;
    directory->child_count++;
    pthread_mutex_unlock(&directory->lock);

    return 0;
}

// Function to remove a file entry from a directory
int remove_file_from_directory(DirectoryEntry *directory, const char *filename) {
    if (!directory || !filename) return -1;

    pthread_mutex_lock(&directory->lock);
    for (int i = 0; i < directory->child_count; ++i) {
        DirectoryEntry *entry = directory->children[i];
        if (entry && strcmp(entry->name, filename) == 0) {
            free(entry->name);
            pthread_mutex_destroy(&entry->lock);
            free(entry);

            for (int j = i; j < directory->child_count - 1; ++j) {
                directory->children[j] = directory->children[j + 1];
            }

            DirectoryEntry **new_children = (DirectoryEntry **)realloc(directory->children,
                                                                       sizeof(DirectoryEntry *) * (directory->child_count - 1));
            if (new_children) {
                directory->children = new_children;
            }
            directory->child_count--;
            pthread_mutex_unlock(&directory->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&directory->lock);
    return -1;
}

// Function to list all entries in a directory
void list_directory_entries(DirectoryEntry *directory) {
    if (!directory) return;

    pthread_mutex_lock(&directory->lock);
    for (int i = 0; i < directory->child_count; ++i) {
        DirectoryEntry *entry = directory->children[i];
        printf("Name: %s, Size: %zu\n", entry->name, entry->size);
    }
    pthread_mutex_unlock(&directory->lock);
}

// Function to serialize the file system state
int serialize_directory(DirectoryEntry *directory, FILE *file) {
    if (!directory || !file) return -1;

    pthread_mutex_lock(&directory->lock);
    fprintf(file, "DIR %s\n", directory->name);

    for (int i = 0; i < directory->child_count; ++i) {
        DirectoryEntry *entry = directory->children[i];
        if (entry->file_entry) {
            fprintf(file, "FILE %s %zu\n", entry->name, entry->size);
        } else {
            serialize_directory(entry, file);
        }
    }

    pthread_mutex_unlock(&directory->lock);
    return 0;
}

// Function to deserialize the file system state
DirectoryEntry* deserialize_directory(FILE *file) {
    if (!file) return NULL;

    char type[5], name[256];
    size_t size;
    fscanf(file, "%s %s", type, name);

    DirectoryEntry *directory = create_directory_entry(name, NULL);
    if (!directory || strcmp(type, "DIR") != 0) {
        free(directory->name);
        free(directory);
        return NULL;
    }

    while (fscanf(file, "%s", type) != EOF) {
        if (strcmp(type, "FILE") == 0) {
            fscanf(file, "%s %zu", name, &size);
            FileEntry *file_entry = create_file_entry(name, size);
            add_file_to_directory(directory, file_entry);
        } else if (strcmp(type, "DIR") == 0) {
            DirectoryEntry *child_dir = deserialize_directory(file);
            add_file_to_directory(directory, NULL); // Add directory as a child
            ((DirectoryEntry *)directory->children[directory->child_count - 1])->file_entry = child_dir;
        }
    }

    return directory;
}

// Function to free the file system structure
void free_directory(DirectoryEntry *directory) {
    if (!directory) return;

    pthread_mutex_lock(&directory->lock);
    for (int i = 0; i < directory->child_count; ++i) {
        DirectoryEntry *entry = directory->children[i];
        if (entry->file_entry) {
            free(entry->file_entry->name);
            free(entry->file_entry);
        } else {
            free_directory(entry);
        }
    }

    free(directory->children);
    free(directory->name);
    pthread_mutex_unlock(&directory->lock);
    pthread_mutex_destroy(&directory->lock);
    free(directory);
}
