typedef enum { ACTIVE, INACTIVE, DELETED } Status;

typedef struct {
    int value;
    long timestamp; // in milliseconds
    Status status;
    int ref_count;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_elements;
    size_t total_memory_usage;
    pthread_mutex_t mutex;
} DataStructure;

// Function prototypes
void increment_refcount(record *rec);
void decrement_refcount(record *rec, void (*cleanup)(record*));
unsigned int generate_random_number(unsigned int min, unsigned int max);

DataStructure* create_data_structure(size_t num_elements) {
    if (num_elements == 0 || !isfinite((double)num_elements)) {
        fprintf(stderr, "Invalid number of elements.\n");
        return NULL;
    }

    DataStructure *ds = (DataStructure *)malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate memory for DataStructure");
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    ds->num_elements = num_elements;

    // Allocate and initialize arrays
    size_t long_array_size = num_elements * sizeof(long);
    size_t int_array_size = num_elements * sizeof(int);
    size_t record_array_size = num_elements * sizeof(record);

    ds->offsets = (long *)calloc(num_elements, sizeof(long));
    ds->keys = (int *)calloc(num_elements, sizeof(int));
    ds->records = (record *)calloc(num_elements, sizeof(record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->mutex);
        free(ds);
        return NULL;
    }

    // Populate records with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        ds->records[i].value = generate_random_number(1, 1000);
        ds->records[i].timestamp = time(NULL) * 1000;
        ds->records[i].status = ACTIVE;
        ds->records[i].ref_count = 0;
    }

    // Calculate total memory usage
    ds->total_memory_usage = long_array_size + int_array_size + record_array_size +
                             sizeof(DataStructure);

    printf("Data structure created with %zu elements.\n", num_elements);
    return ds;
}

void increment_refcount(record *rec) {
    if (rec && rec->ref_count >= 0) {
        rec->ref_count++;
    }
}

void decrement_refcount(record *rec, void (*cleanup)(record*)) {
    if (rec && rec->ref_count > 0) {
        rec->ref_count--;
        if (rec->ref_count == 0 && cleanup) {
            cleanup(rec);
        }
    }
}

unsigned int generate_random_number(unsigned int min, unsigned int max) {
    return rand() % (max - min + 1) + min;
}

