}

void destroy_data_structure(DataStructure *ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->mutex);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->mutex);
    pthread_mutex_destroy(&ds->mutex);

    printf("Data structure destroyed.\n");
    free(ds);
}

void periodic_cleanup(DataStructure *ds, time_t interval) {
    while (1) {
        sleep(interval);

        pthread_mutex_lock(&ds->mutex);

        for (size_t i = 0; i < ds->num_elements; ++i) {
            if (ds->records[i].status == DELETED && ds->records[i].ref_count == 0) {
                printf("Periodic cleanup: removing record with value %d\n", ds->records[i].value);
                // Normally, you might free individual resources here
            }
        }

        pthread_mutex_unlock(&ds->mutex);
    }
}

