#include "record_manager.h"
#include <openssl/rand.h>
#include <stdio.h>

#define INITIAL_CAPACITY 10

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager *rm = malloc(sizeof(RecordManager));
    if (!rm) return NULL;

    rm->records = calloc(initial_capacity, sizeof(Record *));
    if (!rm->records) {
        free(rm);
        return NULL;
    }

    rm->capacity = initial_capacity;
    pthread_mutex_init(&rm->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            destroy_record_manager(rm);
            return NULL;
        }

        record->value = rand() % 100; // Random value between 0 and 99
        record->offset = malloc(sizeof(long));
        record->key = malloc(sizeof(int));

        if (!record->offset || !record->key) {
            free(record);
            destroy_record_manager(rm);
            return NULL;
        }

        *record->offset = i; // Example offset
        *record->key = rand() % 1000; // Example key

        rm->records[i] = record;
    }

    return rm;
}

void destroy_record_manager(RecordManager *rm) {
    if (!rm) return;

    for (size_t i = 0; i < rm->capacity; ++i) {
        if (rm->records[i]) {
            free(rm->records[i]->offset);
            free(rm->records[i]->key);
            free(rm->records[i]);
        }
    }

    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

Record* get_record(RecordManager *rm, size_t index) {
    if (!rm || index >= rm->capacity) return NULL;

    pthread_mutex_lock(&rm->lock);
    Record *record = rm->records[index];
    pthread_mutex_unlock(&rm->lock);

    return record;
}
