    }
    free(records);

    for (int i = 0; i < num_summaries; ++i) {
        free(summaries[i]);
    }
    free(summaries);

    return EXIT_SUCCESS;
}

// Function to sort records and update summary pointers
void sort_and_update_pointers(Record** records, int num_records, Summary** summaries, int num_summaries) {
    if (!records || !summaries) {
        fprintf(stderr, "Invalid input: Records or Summaries are NULL\n");
        return;
    }

    // Sort the records array based on the float value
    qsort(records, num_records, sizeof(Record*), compare_records);

    // Update summary pointers to point to sorted records
    for (int i = 0; i < num_summaries && i < num_records; ++i) {
        summaries[i]->record_ptr = records[i];
    }
}

// Comparison function for qsort
int compare_records(const void* a, const void* b) {
    Record* recordA = *(Record**)a;
    Record* recordB = *(Record**)b;

    if (recordA->value < recordB->value) return -1;
    if (recordA->value > recordB->value) return 1;
