    }

    // Cleanup (in a real scenario, ensure proper deallocation)
    free(offsets);
    free(keys);
    free(records);
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->pool = malloc(size);
    pool->total_size = size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* pool_allocate(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size + size > pool->total_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void *ptr = ((char*)pool->pool) + pool->used_size;
    pool->used_size += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void pool_free(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int fetch_initial_data(long **offsets, int **keys, size_t num_elements) {
