    if (!records) return NULL;

    for (size_t i = 0; i < num_elements; ++i) {
        records[i].value = 0;
        records[i].timestamp = 0;
        records[i].status = INACTIVE;
        records[i].reference_count = 0;
    }

    return records;
}

int main() {
