['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
    size_t offset;
    char *key;
    unsigned long identifier; // Unique identifier for tracking purposes
} record;

typedef struct {
    record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} storage_system;

// Utility function to generate a unique identifier
unsigned long generate_unique_id() {
    static unsigned long id = 0;
    return ++id;
}

// Initialize the storage system with a specified number of records
int init_storage(storage_system *system, size_t num_records, int min_val, int max_val) {
    pthread_mutex_init(&system->lock, NULL);
    system->count = 0;

    for (size_t i = 0; i < num_records && system->count < MAX_RECORDS; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }

        rec->value = rand() % (max_val - min_val + 1) + min_val;
        rec->offset = i; // Simple offset management
        rec->key = malloc(16); // Assume keys are strings of max length 15
        if (!rec->key) {
            free(rec);
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        snprintf(rec->key, 16, "key_%zu", i);
        rec->identifier = generate_unique_id();

        system->records[system->count++] = rec;
    }

    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Requested records exceed maximum limit\n");
        return -1;
    }

    return 0;
}

// Insert a new record
int insert_record(storage_system *system, int value, const char *key) {
    pthread_mutex_lock(&system->lock);

    if (system->count >= MAX_RECORDS) {
        fprintf(stderr, "Storage is full\n");
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    record *rec = malloc(sizeof(record));
    if (!rec) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    rec->value = value;
    rec->offset = system->count; // Use count as offset
    rec->key = strdup(key); // Duplicate the key for safety
    if (!rec->key) {
        free(rec);
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&system->lock);
        return -1;
    }
    rec->identifier = generate_unique_id();

    system->records[system->count++] = rec;
    pthread_mutex_unlock(&system->lock);

    printf("Record inserted: ID=%lu\n", rec->identifier);
    return 0;
}

// Update an existing record by index
int update_record_by_index(storage_system *system, size_t index, int new_value) {
    pthread_mutex_lock(&system->lock);

    if (index >= system->count) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    record *rec = system->records[index];
    rec->value = new_value;

    pthread_mutex_unlock(&system->lock);
    printf("Record updated at index %zu: ID=%lu\n", index, rec->identifier);
    return 0;
}

// Delete a record by index
int delete_record_by_index(storage_system *system, size_t index) {
    pthread_mutex_lock(&system->lock);

    if (index >= system->count) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    free(system->records[index]->key);
    free(system->records[index]);
    for (size_t i = index; i < system->count - 1; ++i) {
        system->records[i] = system->records[i + 1];
    }
    system->records[--system->count] = NULL;

    pthread_mutex_unlock(&system->lock);
    printf("Record deleted at index %zu\n", index);
    return 0;
}

// Retrieve a specific record by its identifier
record *get_record_by_id(storage_system *system, unsigned long id) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->count; ++i) {
        if (system->records[i]->identifier == id) {
            pthread_mutex_unlock(&system->lock);
            return system->records[i];
        }
    }

    pthread_mutex_unlock(&system->lock);
    printf("Record not found with ID=%lu\n", id);
    return NULL;
}

// Free all resources associated with the storage system
void free_storage(storage_system *system) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->count; ++i) {
        free(system->records[i]->key);
        free(system->records[i]);
    }

    pthread_mutex_unlock(&system->lock);
    pthread_mutex_destroy(&system->lock);
}

int main() {
    storage_system db;
    if (init_storage(&db, 10, 1, 100) == 0) {
        insert_record(&db, 42, "new_key");

        record *found = get_record_by_id(&db, generate_unique_id()); // Example usage
        if (found) {
            printf("Record found with value=%d\n", found->value);
        }

        update_record_by_index(&db, 0, 99);

        delete_record_by_index(&db, 0);
    }

    free_storage(&db);
    return 0;
}
