    pthread_mutex_init(&collection->lock, NULL);

    // Initialize cryptographic functions
    EVP_add_cipher(NULL);  // Add all ciphers including AES and Camellia
    EVP_add_digest(NULL);  // Add all digests including MD5, SHA1, SHA2

    return collection;
}

void resize_collection(Collection *collection, size_t new_size) {
    pthread_mutex_lock(&collection->lock);

    long *new_offsets = realloc(collection->offsets, new_size * sizeof(long));
    int *new_keys = realloc(collection->keys, new_size * sizeof(int));
    Record **new_records = realloc(collection->records, new_size * sizeof(Record*));

    if (new_offsets && new_keys && new_records) {
        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->records = new_records;

        for (size_t i = collection->count; i < new_size; ++i) {
            collection->offsets[i] = 0;  // Default initialization
            collection->keys[i] = 0;     // Default initialization
        }
    } else {
        fprintf(stderr, "Failed to resize collection\n");
        free(new_offsets);
        free(new_keys);
        free(new_records);
    }

    pthread_mutex_unlock(&collection->lock);
}

void initialize_record(Record *record, int value_range_min, int value_range_max) {
    if (!record) return;

    record->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    record->offset_ptr = NULL;
    record->key_ptr = NULL;
}

void create_records(Collection *collection, int value_range_min, int value_range_max) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) continue;

        initialize_record(record, value_range_min, value_range_max);

        record->offset_ptr = &collection->offsets[i];
        record->key_ptr = &collection->keys[i];

        pthread_mutex_lock(&collection->lock);
        collection->records[i] = record;
        pthread_mutex_unlock(&collection->lock);
    }
}

Record* get_record_by_index(Collection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;

    Record *record = NULL;
    pthread_mutex_lock(&collection->lock);

    if (index < collection->count) {
        record = collection->records[index];
    }

    pthread_mutex_unlock(&collection->lock);
    return record;
}

void free_collection(Collection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]);
        }
    }

    free(collection->offsets);
    free(collection->keys);
    free(collection->records);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    srand(time(NULL)); // Seed for randomness

    size_t initial_count = 10;
    int value_range_min = 1, value_range_max = 100;

    Collection *collection = init_collection(initial_count);
    if (!collection) return EXIT_FAILURE;

    create_records(collection, value_range_min, value_range_max);

    Record *record = get_record_by_index(collection, 5);
    if (record) {
        printf("Record at index 5: Value=%d\n", record->value);
    }

    free_collection(collection);

    return EXIT_SUCCESS;
}
```

