Project* create_project(const char *name, int priority);
Task* create_task(const char *name, int priority, Task *child);
void add_project(Project **head, const char *name, int priority);
void add_task_to_project(Project *project, const char *task_name, int task_priority, Task *child);
Project* find_project(Project *head, const char *name);
Task* find_task_in_project(Project *project, const char *task_name);
void delete_project(Project **head, const char *name);
void delete_task_from_project(Project *project, const char *task_name);
void free_tasks(Task *tasks);
void free_projects(Project *projects);

// Create a new project
Project* create_project(const char *name, int priority) {
    if (name == NULL || strlen(name) == 0)
        return NULL;

    Project *new_project = (Project *)malloc(sizeof(Project));
    new_project->name = strdup(name);
    new_project->priority = priority;
    new_project->dependency = NULL; // No dependencies yet
    new_project->tasks = NULL;
    new_project->next = NULL;

    return new_project;
}

// Create a new task
Task* create_task(const char *name, int priority, Task *child) {
    if (name == NULL || strlen(name) == 0)
        return NULL;

    Task *new_task = (Task *)malloc(sizeof(Task));
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->child = child;

    return new_task;
}

// Add a project to the list
void add_project(Project **head, const char *name, int priority) {
    if (!head || name == NULL || strlen(name) == 0)
        return;

    Project *new_project = create_project(name, priority);
    if (!new_project) return; // Handle memory allocation failure

    new_project->next = *head;
    *head = new_project;
}

// Add a task to a project
void add_task_to_project(Project *project, const char *task_name, int task_priority, Task *child) {
    if (project == NULL || task_name == NULL || strlen(task_name) == 0)
        return;

    Task *new_task = create_task(task_name, task_priority, child);
    if (!new_task) return; // Handle memory allocation failure

    new_task->next = project->tasks;
    project->tasks = new_task;
}

// Find a project by name
Project* find_project(Project *head, const char *name) {
    while (head != NULL) {
        if (strcmp(head->name, name) == 0)
            return head;
        head = head->next;
    }
    return NULL; // Not found
}

// Find a task within a project by name
Task* find_task_in_project(Project *project, const char *task_name) {
    Task *current = project->tasks;
    while (current != NULL) {
        if (strcmp(current->name, task_name) == 0)
            return current;
        current = current->child; // Traverse to child tasks
    }
    return NULL; // Not found
}

// Delete a project from the list
void delete_project(Project **head, const char *name) {
    if (!head || name == NULL || strlen(name) == 0)
        return;

    Project *current = *head;
    Project *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (prev == NULL)
                *head = current->next; // Remove head
            else
                prev->next = current->next; // Bypass the project

            free_tasks(current->tasks);
            free(current->name);
            free(current);

            return;
        }
        prev = current;
        current = current->next;
    }
}

// Delete a task from within a project
void delete_task_from_project(Project *project, const char *task_name) {
    if (project == NULL || task_name == NULL || strlen(task_name) == 0)
        return;

    Task **current = &(project->tasks);
    while (*current != NULL) {
        Task *entry = *current;
        if (strcmp(entry->name, task_name) == 0) {
            *current = entry->child; // Remove the task
            free_tasks(entry);       // Free all tasks in this subtree
            return;
        }
        current = &(entry->child);
    }
}

// Helper function to free all tasks recursively
void free_tasks(Task *tasks) {
    while (tasks != NULL) {
        Task *next = tasks->child;
        free(tasks->name);
        free(tasks);
        tasks = next;
    }
}

// Free all projects and their tasks
void free_projects(Project *projects) {
    while (projects != NULL) {
        Project *next = projects->next;
        free_tasks(projects->tasks);
        free(projects->name);
        free(projects);
        projects = next;
    }
}

int main() {
    // Example usage:
    Project *head = NULL;

    add_project(&head, "Project1", 10);
    Project *proj = find_project(head, "Project1");
    if (proj) {
        add_task_to_project(proj, "Task1", 5, NULL);
        Task *task = find_task_in_project(proj, "Task1");
        if (task) {
            printf("Task '%s' with priority %d found in project '%s'.\n",
                   task->name, task->priority, proj->name);
        }
    }

    delete_task_from_project(proj, "Task1");
    delete_project(&head, "Project1");

    free_projects(head); // Free all remaining projects

    return 0;
}
