typedef struct item {
    int id;
    char name[50];
    char *description;
} Item;

typedef struct collection {
    Item **items;
    size_t count;
    pthread_mutex_t lock;
} Collection;

#define SUCCESS 0
#define FAILURE -1

int verify_data(const Item *item) {
    if (item == NULL || item->name[0] == '\0' || item->description == NULL) {
        return FAILURE;
    }
    // Add more integrity checks as needed
    return SUCCESS;
}

Collection* init_collection() {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->items = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int add_item_to_collection(Collection *collection, Item *item) {
    if (verify_data(item) == FAILURE) {
        return FAILURE;
    }

    pthread_mutex_lock(&collection->lock);

    size_t new_count = collection->count + 1;
    Item **new_items = realloc(collection->items, new_count * sizeof(Item*));
    if (!new_items) {
        pthread_mutex_unlock(&collection->lock);
        return FAILURE;
    }
    collection->items = new_items;

    collection->items[collection->count] = item;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);

    return SUCCESS;
}

void free_collection(Collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i]->description);
        free(collection->items[i]);
    }
    free(collection->items);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void* iterate_collection(Collection *collection, void (*callback)(Item *)) {
    if (!collection) return NULL;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->items[i]);
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

// Example usage of the function
void print_item(Item *item) {
    if (!item) return;
    printf("ID: %d, Name: %s, Description: %s\n", item->id, item->name, item->description);
}
