#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Product {
    char *name;
    double price;
    struct Product *relatedUpsell;
} Product;

typedef struct Node {
    Product *product;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} ProductList;

ProductList* productListCreate() {
    ProductList *list = (ProductList*) malloc(sizeof(ProductList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void productListDestroy(ProductList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->product->name);
        free(current->product->relatedUpsell); // Assuming the related product is also dynamically allocated
        free(current->product);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Product* createProduct(const char *name, double price, Product *related) {
    if (name == NULL) return NULL;

    Product *newProduct = (Product*) malloc(sizeof(Product));
    newProduct->name = strdup(name);
    newProduct->price = price;
    newProduct->relatedUpsell = related ? related : NULL; // Assign the related product or null
    return newProduct;
}

void addProduct(ProductList *list, Product *product) {
    if (product == NULL) return;

    pthread_mutex_lock(&list->lock);

    Node *newNode = (Node*) malloc(sizeof(Node));
    newNode->product = product;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

Product* findProductByName(ProductList *list, const char *name) {
    if (name == NULL) return NULL;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (strcmp(current->product->name, name) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current->product;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void updateProductPrice(ProductList *list, const char *name, double newPrice) {
    if (name == NULL) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (strcmp(current->product->name, name) == 0) {
            current->product->price = newPrice;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void deleteProductByName(ProductList *list, const char *name) {
    if (name == NULL) return;

    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect != NULL) {
        Node *current = *indirect;
        if (strcmp(current->product->name, name) == 0) {
            *indirect = current->next;
            free(current->product->name);
            free(current->product->relatedUpsell); // Assuming the related product is also dynamically allocated
            free(current->product);
            free(current);
            break;
        }
        indirect = &current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage:
int main() {
    ProductList *list = productListCreate();

    Product *p1 = createProduct("Laptop", 999.99, NULL);
    Product *p2 = createProduct("Mouse", 19.99, p1); // Mouse is related to Laptop
    addProduct(list, p1);
    addProduct(list, p2);

    Product *found = findProductByName(list, "Mouse");
    if (found) {
        printf("Found product: %s at price $%.2f\n", found->name, found->price);
    }

    updateProductPrice(list, "Laptop", 1099.99);

    deleteProductByName(list, "Mouse");

    productListDestroy(list);
    return 0;
}
