#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

typedef struct DataStructures {
    long *offsets;
    int *keys;
    Record **records;
    size_t num_records;
    pthread_mutex_t lock;
} DataStructures;

// Function prototypes
DataStructures* initDataStructures(size_t num_records, int min_val, int max_val);
Record* getRecord(DataStructures *data, size_t index);
void freeDataStructures(DataStructures *data);
void logMemoryUsage(const char *message);
void compactMemory(DataStructures *data);

// Initialize data structures
DataStructures* initDataStructures(size_t num_records, int min_val, int max_val) {
    if (num_records == 0) return NULL;

    DataStructures *data = malloc(sizeof(DataStructures));
    if (!data) { logMemoryUsage("Failed to allocate DataStructures"); goto fail; }

    data->offsets = malloc(num_records * sizeof(long));
    data->keys = malloc(num_records * sizeof(int));
    data->records = malloc(num_records * sizeof(Record*));

    if (!(data->offsets && data->keys && data->records)) {
        logMemoryUsage("Failed to allocate initial memory blocks");
        goto fail;
    }

    // Initialize random seed
    srand(time(NULL));

    pthread_mutex_init(&data->lock, NULL);
    for (size_t i = 0; i < num_records; ++i) {
        data->offsets[i] = i * 1000L + rand() % 1000;
        data->keys[i] = rand() % 1000;

        Record *record = malloc(sizeof(Record));
        if (!record) {
            logMemoryUsage("Failed to allocate Record");
            goto fail;
        }

        record->value = min_val + (rand() % (max_val - min_val + 1));
        record->offset_ptr = &data->offsets[i];
        record->key_ptr = &data->keys[i];

        data->records[i] = record;
    }

    data->num_records = num_records;
    return data;

fail:
    if (data) {
        if (data->offsets) free(data->offsets);
        if (data->keys) free(data->keys);
        if (data->records) {
            for (size_t i = 0; i < num_records; ++i) {
                if (data->records[i]) free(data->records[i]);
            }
            free(data->records);
        }
        free(data);
    }

    return NULL;
}

// Retrieve a specific record by index
Record* getRecord(DataStructures *data, size_t index) {
    if (!data || index >= data->num_records) return NULL;

    pthread_mutex_lock(&data->lock);
    Record* record = data->records[index];
    pthread_mutex_unlock(&data->lock);

    return record;
}

// Free allocated memory safely
void freeDataStructures(DataStructures *data) {
    if (!data) return;

    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->num_records; ++i) {
        if (data->records[i]) free(data->records[i]);
    }

    free(data->records);
    free(data->keys);
    free(data->offsets);
    pthread_mutex_unlock(&data->lock);

    pthread_mutex_destroy(&data->lock);
    free(data);
}

// Logging function for memory usage
void logMemoryUsage(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Memory compaction and maintenance (placeholder)
void compactMemory(DataStructures *data) {
    // Placeholder for asynchronous memory management logic.
    logMemoryUsage("Compacting memory (asynchronous task)");
}
