// Define the structure for each record
typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

// Structure to manage the collection of records with thread safety
typedef struct Collection {
    Record **records; // Dynamic array of pointers to records
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Collection;

// Function to initialize a random number generator
void init_random() {
    srand(time(NULL));
}

// Function to create a new record with initialized values
Record *create_record(long offset, int key) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = rand() % 100; // Random value within range [0, 99]
    record->offset = malloc(sizeof(long));
    record->key = malloc(sizeof(int));

    if (record->offset && record->key) {
        *record->offset = offset;
        *record->key = key;
    } else {
        free(record);
        return NULL;
    }

    return record;
}

// Function to initialize the collection
Collection *init_collection(size_t initial_capacity) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

// Function to add a new record
int add_record(Collection *collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));

        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = create_record(offset, key);
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Record creation failed
    }

    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to retrieve a specific record by its index
Record *get_record(Collection *collection, size_t index) {
    if (index >= collection->size) return NULL;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];
    pthread_mutex_unlock(&collection->lock);

    return record;
}

// Function to update a record's value by its index
int update_record(Collection *collection, size_t index, int new_value) {
    if (index >= collection->size) return -1;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];

    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Record does not exist
    }

    record->value = new_value;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to free the memory allocated for the collection
void free_collection(Collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Function to initialize and manage two arrays
void init_arrays(size_t num_records, long *offsets, int *keys) {
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 10000; // Random offset values
        keys[i] = rand() % 100;      // Random key values
    }
}

// Function to retrieve a specific record from the initialized arrays by its index
Record *get_record_from_arrays(size_t index, long *offsets, int *keys) {
    if (index >= num_records) return NULL;

    Record *record = create_record(offsets[index], keys[index]);
    return record;
}
