} Collection;

// Function prototypes
Collection* create_collection(size_t initial_size);
int destroy_collection(Collection* collection);
Record* get_record(Collection* collection, size_t index);
int add_record(Collection* collection, int value_range_min, int value_range_max);
void resize_collection(Collection* collection, size_t new_size);

// Initialize cryptographic algorithms
static void initialize_crypto() {
    EVP_add_cipher(&evp_aes_128_cbc);
    EVP_add_digest(&md5_md_meth);
    EVP_add_cipher(&evp_camellia_128_cbc);
    EVP_add_digest(&sha1_dgst);
    EVP_add_cipher(&evp_rsa_null_encrypt);
}

// Create a new collection
Collection* create_collection(size_t initial_size) {
    initialize_crypto();

    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) return NULL;

    pthread_rwlock_init(&collection->lock, NULL);

    collection->offsets = (long *)calloc(initial_size, sizeof(long));
    collection->keys = (int *)calloc(initial_size, sizeof(int));
    collection->records = (Record *)calloc(initial_size, sizeof(Record));
    if (!collection->offsets || !collection->keys || !collection->records) {
        destroy_collection(collection);
        return NULL;
    }

    collection->record_count = initial_size;
    return collection;
}

// Destroy a collection
int destroy_collection(Collection* collection) {
    if (!collection) return -1;

    pthread_rwlock_destroy(&collection->lock);

    free(collection->offsets);
    free(collection->keys);
    for (size_t i = 0; i < collection->record_count; ++i) {
        free(collection->records[i].offset_ptr);
        free(collection->records[i].key_ptr);
    }
    free(collection->records);

    free(collection);
    return 0;
}

// Retrieve a specific record by index
Record* get_record(Collection* collection, size_t index) {
    if (!collection || index >= collection->record_count) return NULL;

    pthread_rwlock_rdlock(&collection->lock);
    Record *record = &collection->records[index];
    pthread_rwlock_unlock(&collection->lock);

    return record;
}

// Add a new record with a random value
int add_record(Collection* collection, int value_range_min, int value_range_max) {
    if (!collection || collection->record_count == 0) return -1;

    pthread_rwlock_wrlock(&collection->lock);

    size_t current_size = collection->record_count;
    resize_collection(collection, current_size + 1);

    Record *new_record = &collection->records[current_size - 1];
    int value = (rand() % (value_range_max - value_range_min + 1)) + value_range_min;

    new_record->value = value;
    long offset = collection->offsets[current_size - 1] = rand();
    int key = collection->keys[current_size - 1] = rand();

    new_record->offset_ptr = (long *)malloc(sizeof(long));
    new_record->key_ptr = (int *)malloc(sizeof(int));

    if (!new_record->offset_ptr || !new_record->key_ptr) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    *new_record->offset_ptr = offset;
    *new_record->key_ptr = key;

    pthread_rwlock_unlock(&collection->lock);
    return 0;
}

// Dynamically resize the collection
void resize_collection(Collection* collection, size_t new_size) {
    if (new_size <= collection->record_count) return;

    long *offsets = realloc(collection->offsets, new_size * sizeof(long));
    int *keys = realloc(collection->keys, new_size * sizeof(int));
    Record *records = realloc(collection->records, new_size * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        return;
    }

    collection->offsets = offsets;
    collection->keys = keys;
    collection->records = records;

    for (size_t i = collection->record_count; i < new_size; ++i) {
        collection->records[i].value = 0;
        long offset = collection->offsets[i] = rand();
        int key = collection->keys[i] = rand();

        collection->records[i].offset_ptr = (long *)malloc(sizeof(long));
        collection->records[i].key_ptr = (int *)malloc(sizeof(int));

        if (!collection->records[i].offset_ptr || !collection->records[i].key_ptr) {
            fprintf(stderr, "Memory allocation failed during record initialization.\n");
            return;
        }

        *collection->records[i].offset_ptr = offset;
        *collection->records[i].key_ptr = key;
    }

    collection->record_count = new_size;
}
```

### Explanation

- **Data Structures**: The `Collection` structure manages arrays of offsets, keys, and records. Each record has a value, a pointer to its offset, and a pointer to its key.

- **Thread Safety**: A read-write lock (`pthread_rwlock_t`) is used to ensure safe concurrent access.

- **Cryptographic Initialization**: Uses OpenSSL's `EVP_add_cipher` and `EVP_add_digest` to initialize cryptographic algorithms like AES, Camellia, MD5, SHA1, and RSA with SHA1.

- **Error Handling**: The code includes checks for memory allocation failures and handles them gracefully by cleaning up resources.

- **Dynamic Resizing**: The collection can be resized dynamically using the `resize_collection` function.

- **Performance Considerations**: Efficient memory usage is ensured through dynamic resizing, and thread safety is maintained with read-write locks. Cryptographic operations are initialized once to minimize overhead.

This implementation provides a scalable and flexible foundation for managing heterogeneous data structures while ensuring performance and security.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int32_t value;
    long* offset;
    int* key;
} Record;

typedef struct {
    Record** records;   // Dynamic array of pointers to Records
    size_t capacity;    // Current allocated capacity
    size_t count;       // Number of elements currently in the array
    pthread_mutex_t mutex; // Mutex for thread-safe access
} RecordCollection;

// Function prototypes
RecordCollection* create_record_collection(size_t initial_capacity, int min_val, int max_val);
void free_record_collection(RecordCollection* collection);
int add_record(RecordCollection* collection, int32_t value, long offset, int key);
Record* get_record_by_index(const RecordCollection* collection, size_t index);
int update_record_value(RecordCollection* collection, size_t index, int32_t new_value);

// Helper functions
static void initialize_record_collection(RecordCollection* collection, size_t initial_capacity, int min_val, int max_val);
static inline int random_int(int min_val, int max_val);

RecordCollection* create_record_collection(size_t initial_capacity, int min_val, int max_val) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate memory for RecordCollection");
        return NULL;
    }

    initialize_record_collection(collection, initial_capacity, min_val, max_val);

    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void free_record_collection(RecordCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]);
    }
    free(collection->records);

    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(RecordCollection* collection, int32_t value, long offset, int key) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->mutex);

    // Expand capacity if necessary
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for a new record");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    record->value = value;
    record->offset = (long*)malloc(sizeof(long));
    if (!record->offset) {
        free(record);
        perror("Failed to allocate memory for offset");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }
    *record->offset = offset;

    record->key = (int*)malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        free(record);
        perror("Failed to allocate memory for key");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }
    *record->key = key;

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

Record* get_record_by_index(const RecordCollection* collection, size_t index) {
    if (!collection || index >= collection->count)
        return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&collection->mutex);

    Record* record = collection->records[index];

    pthread_mutex_unlock((pthread_mutex_t*)&collection->mutex);
    return record;
}

int update_record_value(RecordCollection* collection, size_t index, int32_t new_value) {
    if (!collection || index >= collection->count)
        return -1;

    pthread_mutex_lock(&collection->mutex);

    Record* record = collection->records[index];
    if (record) {
        record->value = new_value;
        pthread_mutex_unlock(&collection->mutex);
        return 0; // Success
    }

    pthread_mutex_unlock(&collection->mutex);
    return -1; // Failure
}

// Helper functions implementation

static void initialize_record_collection(RecordCollection* collection, size_t initial_capacity, int min_val, int max_val) {
    if (!collection) return;

    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for a new record");
            exit(EXIT_FAILURE);
        }

        record->value = random_int(min_val, max_val);
        record->offset = (long*)malloc(sizeof(long));
        if (!record->offset) {
            free(record);
            perror("Failed to allocate memory for offset");
            exit(EXIT_FAILURE);
        }
        *record->offset = i;

        record->key = (int*)malloc(sizeof(int));
        if (!record->key) {
            free(record->offset);
            free(record);
            perror("Failed to allocate memory for key");
            exit(EXIT_FAILURE);
        }
        *record->key = (int)i;

        collection->records[i] = record;
    }

    collection->count = initial_capacity;
}

static inline int random_int(int min_val, int max_val) {
    return rand() % (max_val - min_val + 1) + min_val;
}
