#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    long *offset;
    int key;
    time_t last_accessed;
    unsigned char validity_flag : 1; // Single bit for status flag
} record;

// Dynamic array structure
typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    size_t max_cache_size;
    pthread_mutex_t lock;
} dynamic_array;

// Initialize the dynamic array with a specified number of records
void init_dynamic_array(dynamic_array *arr, size_t initial_capacity, size_t max_cache_size) {
    arr->records = (record **)malloc(initial_capacity * sizeof(record *));
    memset(arr->records, 0, initial_capacity * sizeof(record *));
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->max_cache_size = max_cache_size;
    pthread_mutex_init(&arr->lock, NULL);
}

// Insert or update a record at the specified index
void insert_update_record(dynamic_array *arr, size_t index, int value, long offset, int key) {
    if (index >= arr->capacity) {
        // Resize array if necessary
        size_t new_capacity = arr->capacity * 2;
        record **new_records = (record **)realloc(arr->records, new_capacity * sizeof(record *));
        memset(new_records + arr->capacity, 0, (new_capacity - arr->capacity) * sizeof(record *));
        free(arr->records);
        arr->records = new_records;
        arr->capacity = new_capacity;
    }

    pthread_mutex_lock(&arr->lock);

    if (arr->records[index] == NULL) {
        arr->records[index] = (record *)malloc(sizeof(record));
        arr->count++;
    }

    record *rec = arr->records[index];
    rec->value = value;
    rec->offset = &offset;
    rec->key = key;
    rec->last_accessed = time(NULL);
    rec->validity_flag = 1;

    pthread_mutex_unlock(&arr->lock);

    // Evict least recently used if over capacity
    enforce_eviction_policy(arr);
}

// Enforce eviction policy (LRU)
void enforce_eviction_policy(dynamic_array *arr) {
    while (arr->count > arr->max_cache_size) {
        time_t oldest_time = -1;
        size_t lru_index = 0;

        for (size_t i = 0; i < arr->capacity; ++i) {
            if (arr->records[i] != NULL && arr->records[i]->last_accessed < oldest_time) {
                oldest_time = arr->records[i]->last_accessed;
                lru_index = i;
            }
        }

        // Free the least recently used record
        free(arr->records[lru_index]);
        arr->records[lru_index] = NULL;
        arr->count--;
    }
}

// Delete a record by index
void delete_record(dynamic_array *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index < arr->capacity && arr->records[index] != NULL) {
        free(arr->records[index]);
        arr->records[index] = NULL;
        arr->count--;
    }

    pthread_mutex_unlock(&arr->lock);
}

// Search records by value
record **search_by_value(dynamic_array *arr, int value, size_t *result_count) {
    record **results = (record **)malloc(arr->capacity * sizeof(record *));
    size_t found = 0;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->capacity; ++i) {
        if (arr->records[i] != NULL && arr->records[i]->value == value) {
            results[found++] = arr->records[i];
            // Update last accessed time
            arr->records[i]->last_accessed = time(NULL);
        }
    }

    pthread_mutex_unlock(&arr->lock);

    *result_count = found;
    return results;  // Caller should free this memory after use
}

// Search records by last accessed time range
record **search_by_last_accessed(dynamic_array *arr, time_t start_time, time_t end_time, size_t *result_count) {
    record **results = (record **)malloc(arr->capacity * sizeof(record *));
    size_t found = 0;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->capacity; ++i) {
        if (arr->records[i] != NULL && 
            arr->records[i]->last_accessed >= start_time &&
            arr->records[i]->last_accessed <= end_time) {
            results[found++] = arr->records[i];
        }
    }

    pthread_mutex_unlock(&arr->lock);

    *result_count = found;
    return results;  // Caller should free this memory after use
}

// API to get current cache hit ratios, average access times, and total records count
void get_cache_metrics(const dynamic_array *arr, double *hit_ratio, double *avg_access_time, size_t *total_records) {
    pthread_mutex_lock(&arr->lock);

    *total_records = arr->count;

    // Assume some external mechanism to compute hit ratio and average access time
    *hit_ratio = 0.95; // Placeholder for actual computation
    *avg_access_time = 10.0; // Placeholder for actual computation

    pthread_mutex_unlock(&arr->lock);
}

// Cleanup function for dynamic array
void cleanup_dynamic_array(dynamic_array *arr) {
    for (size_t i = 0; i < arr->capacity; ++i) {
        if (arr->records[i] != NULL) {
            free(arr->records[i]);
        }
    }
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
}

// Flexible logging mechanism
void log_event(const char *event, int verbosity_level) {
    static int current_verbosity = 1; // Default verbosity level

    if (verbosity_level <= current_verbosity) {
        printf("[LOG]: %s\n", event);  // Simplified for demonstration purposes
    }
}

// Main function as an example usage of the dynamic array system
int main() {
    size_t initial_capacity = 10;
    size_t max_cache_size = 5;
    dynamic_array arr;

    init_dynamic_array(&arr, initial_capacity, max_cache_size);

    insert_update_record(&arr, 0, 42, 100L, 1);
    insert_update_record(&arr, 1, 24, 200L, 2);

    size_t result_count;
    record **search_results = search_by_value(&arr, 42, &result_count);

    for (size_t i = 0; i < result_count; ++i) {
        printf("Found: value=%d, key=%d\n", search_results[i]->value, search_results[i]->key);
    }

