['Below is a C implementation for managing a collection of records with dynamic memory allocation. The code includes features like initialization, thread-safe operations, serialization/deserialization, and performance tracking.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *timestamp;
    float *metric;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

// Function prototypes
RecordCollection* create_collection(size_t initial_capacity);
void destroy_collection(RecordCollection *collection);
int add_record(RecordCollection *collection, int min_val, int max_val, long timestamp, float metric);
int remove_record(RecordCollection *collection, size_t index);
Record* get_record(RecordCollection *collection, size_t index);
size_t total_memory_used(const RecordCollection *collection);
void serialize_collection(const RecordCollection *collection, const char *filename);
int deserialize_collection(RecordCollection *collection, const char *filename);

// Function implementations

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(RecordCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->timestamp);
        free(collection->records[i]->metric);
        free(collection->records[i]);
    }
    free(collection->records);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection *collection, int min_val, int max_val, long timestamp, float metric) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    record->value = (rand() % (max_val - min_val + 1)) + min_val;
    record->timestamp = malloc(sizeof(long));
    record->metric = malloc(sizeof(float));

    if (!record->timestamp || !record->metric) {
        free(record);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    *record->timestamp = timestamp;
    *record->metric = metric;

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_record(RecordCollection *collection, size_t index) {
    if (!collection || index >= collection->count) return -1;

    pthread_mutex_lock(&collection->lock);

    free(collection->records[index]->timestamp);
    free(collection->records[index]->metric);
    free(collection->records[index]);

    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->records[i] = collection->records[i + 1];
    }

    --collection->count;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(RecordCollection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];
    pthread_mutex_unlock(&collection->lock);

    return record;
}

size_t total_memory_used(const RecordCollection *collection) {
    size_t memory_used = sizeof(RecordCollection);
    if (!collection) return 0;

    pthread_mutex_lock((pthread_mutex_t *)&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        memory_used += sizeof(Record *) + sizeof(Record) + sizeof(long) + sizeof(float);
    }
    pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);

    return memory_used;
}

void serialize_collection(const RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&collection->lock);
    fwrite(&collection->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(record->timestamp, sizeof(long), 1, file);
        fwrite(record->metric, sizeof(float), 1, file);
    }
    pthread_mutex_unlock(&collection->lock);

    fclose(file);
}

int deserialize_collection(RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    destroy_collection(collection);
    collection->records = calloc(count, sizeof(Record *));
    if (!collection->records) {
        fclose(file);
        return -1;
    }

    collection->count = count;
    collection->capacity = count;

    for (size_t i = 0; i < count; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fclose(file);
            destroy_collection(collection);
            return -1;
        }

        fread(&record->value, sizeof(int), 1, file);
        record->timestamp = malloc(sizeof(long));
        record->metric = malloc(sizeof(float));

        if (!record->timestamp || !record->metric) {
            free(record);
            fclose(file);
            destroy_collection(collection);
            return -1;
        }

        fread(record->timestamp, sizeof(long), 1, file);
        fread(record->metric, sizeof(float), 1, file);

        collection->records[i] = record;
    }

    pthread_mutex_init(&collection->lock, NULL);
    fclose(file);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Dynamic Resizing**: Handles dynamic resizing of the array with `realloc`.
- **Serialization/Deserialization**: Supports saving and loading from disk.
- **Memory Management**: Properly manages memory to prevent leaks.
- **Performance Tracking**: Provides a function to calculate total memory usage.

This implementation should serve as a robust foundation for managing records in a high-performance streaming analytics application.']

