#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    long key;
    double value;
    struct Node *left;
    struct Node *right;
} Node;

typedef int (*CompareFunc)(long, long);

typedef struct BST {
    Node* root;
    CompareFunc compare;
    pthread_mutex_t lock; // For thread safety
} BST;

// Function prototypes
BST* create_bst(CompareFunc compare);
Node* insert_node(Node* root, long key, double value, CompareFunc compare);
Node* delete_node(Node* root, long key, CompareFunc compare);
Node* find_min(Node* node);
int compare_default(long a, long b);

// Create and initialize BST
BST* create_bst(CompareFunc compare) {
    BST* bst = (BST*)malloc(sizeof(BST));
    if (!bst) return NULL;

    bst->root = NULL;
    bst->compare = compare ? compare : compare_default;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&bst->lock, NULL);

    return bst;
}

// Insert a new node with key-value pair into BST
Node* insert_node(Node* root, long key, double value, CompareFunc compare) {
    if (!root) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) return NULL;

        newNode->key = key;
        newNode->value = value;
        newNode->left = newNode->right = NULL;

        return newNode;
    }

    int cmp = compare(key, root->key);
    if (cmp < 0)
        root->left = insert_node(root->left, key, value, compare);
    else if (cmp > 0)
        root->right = insert_node(root->right, key, value, compare);

    return root;
}

// Delete a node with the given key from BST
Node* delete_node(Node* root, long key, CompareFunc compare) {
    if (!root) return NULL;

    int cmp = compare(key, root->key);
    if (cmp < 0)
        root->left = delete_node(root->left, key, compare);
    else if (cmp > 0)
        root->right = delete_node(root->right, key, compare);
    else {
        if (!root->left) {
            Node* temp = root->right;
            free(root);
            return temp;
        } else if (!root->right) {
            Node* temp = root->left;
            free(root);
            return temp;
        }

        Node* minNode = find_min(root->right);
        root->key = minNode->key;
        root->value = minNode->value;
        root->right = delete_node(root->right, minNode->key, compare);
    }

    return root;
}

// Find the node with minimum key in BST
Node* find_min(Node* node) {
    Node* current = node;
    while (current && current->left)
        current = current->left;
    return current;
}

// Default comparison function (ascending order)
int compare_default(long a, long b) {
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

// Function to insert key-value pair into BST
void bst_insert(BST* bst, long key, double value) {
    pthread_mutex_lock(&bst->lock);
    bst->root = insert_node(bst->root, key, value, bst->compare);
    pthread_mutex_unlock(&bst->lock);
}

// Function to delete node with specific key from BST
void bst_delete(BST* bst, long key) {
    pthread_mutex_lock(&bst->lock);
    bst->root = delete_node(bst->root, key, bst->compare);
    pthread_mutex_unlock(&bst->lock);
}

// Free the allocated memory for the BST
void free_bst(Node* root) {
    if (!root) return;
    free_bst(root->left);
    free_bst(root->right);
    free(root);
}

// Destroy BST and release resources
void destroy_bst(BST* bst) {
    pthread_mutex_destroy(&bst->lock);
    free_bst(bst->root);
    free(bst);
}
