pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate unique random doubles within a range
double generate_unique_double(double min, double max, double *used_values, size_t used_count) {
    double value;
    do {
        value = (double)rand() / RAND_MAX * (max - min) + min;
    } while (bsearch(&value, used_values, used_count, sizeof(double), compare_doubles));
    return value;
}

int compare_doubles(const void* a, const void* b) {
    double arg1 = *(const double*)a;
    double arg2 = *(const double*)b;
    if (arg1 < arg2) return -1;
    if (arg1 > arg2) return 1;
    return 0;
}

// Function to initialize records
Node* initialize_records(size_t size, long *offsets, int *keys, double min_val, double max_val) {
    pthread_mutex_lock(&lock);

    Node *head = NULL, *current = NULL;
    double *used_values = malloc(size * sizeof(double));
    if (!used_values) {
        perror("Memory allocation failed for used values");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for a new record\n");
            free(used_values);
            while (head != NULL) {
                current = head;
                head = head->next;
                free(current);
            }
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Assign unique offset and key
        new_node->record.offset = offsets[i];
        new_node->record.key = keys[i];

        // Generate unique double value
        new_node->record.value = generate_unique_double(min_val, max_val, used_values, i);
        memcpy(&used_values[i], &new_node->record.value, sizeof(double));

        // Append to list
        if (!head) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    free(used_values);
    pthread_mutex_unlock(&lock);

    return head;
}

// Function to verify data integrity
int verify_data_integrity(Node *head, size_t size) {
    double seen_values[size];
    memset(seen_values, 0, sizeof(seen_values));
    int count = 0;

    for (Node *current = head; current != NULL; current = current->next) {
        if (bsearch(&current->record.value, seen_values, count, sizeof(double), compare_doubles)) {
            fprintf(stderr, "Duplicate value found: %f\n", current->record.value);
            return 0;
        }
        memcpy(&seen_values[count++], &current->record.value, sizeof(double));
    }

    if (count != size) {
        fprintf(stderr, "Data integrity check failed. Mismatch in record count.\n");
        return 0;
    }

    return 1;
}

// Mock function to simulate persistence
int persist_records(Node *head) {
    // Simulate network operation with a simple print statement
    printf("Persisting records...\n");

    Node *current = head;
    while (current != NULL) {
        // Here you would send the data to an external service
        printf("Record: offset=%ld, key=%d, value=%.2f\n", current->record.offset, current->record.key, current->record.value);
        current = current->next;
    }

    return 1; // Assume success for this mock function
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    size_t record_count = 10;
    long offsets[record_count] = {0};
    int keys[record_count] = {0};

    for (size_t i = 0; i < record_count; ++i) {
        offsets[i] = i + 1;
        keys[i] = i + 1;
    }

    Node *records = initialize_records(record_count, offsets, keys, 10.0, 20.0);
    if (!records) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    if (!verify_data_integrity(records, record_count)) {
        fprintf(stderr, "Data integrity verification failed\n");
        // Cleanup
        Node *current = records;
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
        return EXIT_FAILURE;
    }

    if (!persist_records(records)) {
        fprintf(stderr, "Failed to persist records\n");
    }

    // Cleanup
    Node *current = records;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    return EXIT_SUCCESS;
}
```

### Key Points:
