#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define log severity levels
typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} SeverityLevel;

// Log entry structure
typedef struct LogEntry {
    time_t timestamp;
    SeverityLevel severity;
    char service_name[128];
    char message[1024];
    struct LogEntry *next;
} LogEntry;

// Function prototypes
void log_message(SeverityLevel severity, const char* service, const char* msg);
LogEntry* create_log_entry(SeverityLevel severity, const char* service, const char* msg);
void enqueue_log(LogEntry** head, LogEntry* new_entry);

// Main logging function
void log_message(SeverityLevel severity, const char *service, const char *msg) {
    if (severity < WARNING) return; // Simple filtering

    LogEntry* entry = create_log_entry(severity, service, msg);
    static LogEntry* head = NULL;
    enqueue_log(&head, entry);

    printf("Logged: %s [%s] - %s\n", service, severity == DEBUG ? "DEBUG" : severity == INFO ? "INFO" : severity == WARNING ? "WARNING" : severity == ERROR ? "ERROR" : "CRITICAL", msg);
}

// Create a new log entry
LogEntry* create_log_entry(SeverityLevel severity, const char *service, const char *msg) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->timestamp = time(NULL);
    entry->severity = severity;
    strncpy(entry->service_name, service, sizeof(entry->service_name) - 1);
    strncpy(entry->message, msg, sizeof(entry->message) - 1);
    entry->next = NULL;

    return entry;
}

// Enqueue log entries in a linked list
void enqueue_log(LogEntry** head, LogEntry* new_entry) {
    if (!head || !new_entry) return;

    new_entry->next = *head;
    *head = new_entry;
}

int main() {
    // Example usage
    log_message(INFO, "AuthService", "User logged in successfully.");
    log_message(ERROR, "PaymentService", "Transaction failed due to insufficient funds.");

    return 0;
}
