int allocate_records(record **records, long **offsets, int **keys, int num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Exceeded maximum record limit.\n");
        return -1;
    }

    // Initialize random seed
    srand((unsigned int)time(NULL));

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        return -1;
    }

