        perror("Failed to allocate memory for offsets");
        return -1;
    }

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*records);
        free(*offsets);
        perror("Failed to allocate memory for keys");
        return -1;
    }

    log_memory_usage(sizeof(record) * num_records + 2 * sizeof(long) * num_records);

    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100; // Random int value between 0 and 99
        (*offsets)[i] = rand() % 10000;     // Random long offset
        (*keys)[i] = rand() % 50;           // Random key between 0 and 49
        (*records)[i].weight = (float)(rand() % 100) / 10.0f; // Random float weight between 0.0 and 9.9

        (*records)[i].offset = &(*offsets)[i];
    }

    return 0;
}

void remove_least_recently_updated(record **records, long *offsets, int *keys, int current_size) {
    if (current_size <= UPDATE_FREQUENCY) {
        // No need to remove any records
        return;
    }

    int num_to_remove = current_size - UPDATE_FREQUENCY;

    for (int i = 0; i < num_to_remove; ++i) {
        free((*records)[i].offset);
    }

    memmove(*records, &(*records)[num_to_remove], sizeof(record) * UPDATE_FREQUENCY);
    memmove(offsets, &offsets[num_to_remove], sizeof(long) * UPDATE_FREQUENCY);
    memmove(keys, &keys[num_to_remove], sizeof(int) * UPDATE_FREQUENCY);

    log_memory_usage(sizeof(record) * UPDATE_FREQUENCY + 2 * sizeof(long) * UPDATE_FREQUENCY);
}

void update_records(record **records, long *offsets, int *keys, int current_size, int new_value, int new_key) {
    if (current_size == MAX_RECORDS) {
        remove_least_recently_updated(records, offsets, keys, current_size);
        current_size = UPDATE_FREQUENCY;
    }

    (*records)[current_size].value = new_value;
    offsets[current_size] = rand() % 10000; // New random long offset
    (*records)[current_size].offset = &offsets[current_size];
    keys[current_size] = new_key;
    (*records)[current_size].weight = (float)(rand() % 100) / 10.0f;

    current_size++;
}

int main() {
    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    int num_records = 500; // Example number of records

    if (allocate_records(&records, &offsets, &keys, num_records) != 0) {
        return EXIT_FAILURE;
    }

    update_records(&records, offsets, keys, num_records, 42, 24);

    // Clean up
    for (int i = 0; i < num_records; ++i) {
        free(records[i].offset);
    }
    free(records);
    free(offsets);
    free(keys);

    return EXIT_SUCCESS;
}
