#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *str;
} record;

// Function prototypes
record **initializeRecords(int *keys, size_t keysSize, const char **predefinedStrings, size_t stringCount, unsigned int seed);
void freeRecords(record **records, size_t keysSize);
int getRandomInt(int min, int max);

// Main function to initialize records
record **initializeRecords(int *keys, size_t keysSize, const char **predefinedStrings, size_t stringCount, unsigned int seed) {
    if (!keys || !keysSize || !predefinedStrings || !stringCount) return NULL;

    srand(seed);
    record **records = (record **)malloc(keysSize * sizeof(record *));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array\n");
        return NULL;
    }

    size_t totalRecords = 0;
    for (size_t i = 0; i < keysSize; ++i) {
        int subArraySize = keys[i];
        if (subArraySize < 0) {
            fprintf(stderr, "Invalid size in keys array at index %zu\n", i);
            freeRecords(records, i);
            return NULL;
        }

        records[i] = (record *)malloc(subArraySize * sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for sub-array at index %zu\n", i);
            freeRecords(records, i);
            return NULL;
        }

        for (int j = 0; j < subArraySize; ++j) {
            records[i][j].value = getRandomInt(1, 100); // Example range
            int randomIndex = rand() % stringCount;
            records[i][j].str = strdup(predefinedStrings[randomIndex]);
            if (!records[i][j].str) {
                fprintf(stderr, "Memory allocation failed for string at index [%zu][%d]\n", i, j);
                freeRecords(records, keysSize); // Free all allocated memory
                return NULL;
            }
        }

        totalRecords += subArraySize;
    }

    printf("Total records allocated: %zu\n", totalRecords);
    return records;
}

// Function to free allocated memory for records
void freeRecords(record **records, size_t keysSize) {
    if (!records) return;

    for (size_t i = 0; i < keysSize; ++i) {
        if (records[i]) {
            for (int j = 0; records[i][j].str != NULL; ++j) {
                free(records[i][j].str);
            }
            free(records[i]);
        }
    }
    free(records);
}

// Function to get a random integer in a specified range
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Unit tests for the function
void test_initializeRecords() {
    const char *strings[] = {"Hello", "World", "Test"};
    int keys[] = {3, 0, 2};
    unsigned int seed = 42;

    record **records = initializeRecords(keys, sizeof(keys) / sizeof(keys[0]), strings, sizeof(strings) / sizeof(strings[0]), seed);

    if (records != NULL) {
        for (size_t i = 0; i < sizeof(keys) / sizeof(keys[0]); ++i) {
            for (int j = 0; j < keys[i]; ++j) {
                printf("Record[%zu][%d] - Value: %d, String: %s\n", i, j, records[i][j].value, records[i][j].str);
            }
        }
        freeRecords(records, sizeof(keys) / sizeof(keys[0]));
    } else {
        printf("Test failed due to memory allocation error.\n");
    }
}

int main() {
    test_initializeRecords();
    return 0;
}
```

