MemoryManager* initialize_memory_manager(size_t initial_capacity) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    manager->capacity = initial_capacity;

    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->values = malloc(initial_capacity * sizeof(double));
    manager->strings = malloc(initial_capacity * sizeof(char*));
    manager->records = malloc(initial_capacity * sizeof(Record));

