}

void resize_memory_manager(MemoryManager *manager) {
    size_t new_capacity = manager->capacity * RESIZE_FACTOR;

    manager->offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    manager->keys = realloc(manager->keys, new_capacity * sizeof(int));
    manager->values = realloc(manager->values, new_capacity * sizeof(double));
    manager->strings = realloc(manager->strings, new_capacity * sizeof(char*));
    manager->records = realloc(manager->records, new_capacity * sizeof(Record));

