} ExtraInfo;

typedef struct Record {
    long offset;
    int key;
    struct Record *next_record;
    ExtraInfo *extra_info;
    int value;
    char *string;
    ExtraInfo *additional_extra_info;
} Record;

Record **allocateRecords(int *keys, size_t num_keys) {
    if (num_keys <= 0) return NULL;

    Record **records = malloc(num_keys * sizeof(Record *));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int total_records = 0;
    for (size_t i = 0; i < num_keys; ++i) {
        int sub_array_size = keys[i];
        if (sub_array_size <= 0) continue;

        records[i] = malloc(sub_array_size * sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < sub_array_size; ++j) {
            records[i][j].offset = j;
            records[i][j].key = i;
            records[i][j].next_record = NULL;
            records[i][j].extra_info = malloc(sizeof(ExtraInfo));
            if (!records[i][j].extra_info) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            records[i][j].extra_info->string = malloc(sub_array_size + 1); // Example size
            if (!records[i][j].extra_info->string) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }

            records[i][j].value = j;
            records[i][j].string = NULL; // Initialize as needed
            records[i][j].additional_extra_info = malloc(sizeof(ExtraInfo));
            if (!records[i][j].additional_extra_info) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            records[i][j].additional_extra_info->string = NULL; // Initialize as needed

            total_records++;
        }
    }

    return records;
}

void freeRecords(Record **records, int *keys, size_t num_keys) {
    if (!records) return;

    for (size_t i = 0; i < num_keys; ++i) {
        if (!records[i]) continue;

        for (int j = 0; j < keys[i]; ++j) {
            free(records[i][j].extra_info->string);
            free(records[i][j].extra_info);
            free(records[i][j].additional_extra_info->string);
            free(records[i][j].additional_extra_info);
        }
        free(records[i]);
    }
    free(records);
}

int main() {
    int keys[] = {3, 5, 0, 2}; // Example key sizes
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    Record **records = allocateRecords(keys, num_keys);

    if (records) {
        // Use the records as needed

        freeRecords(records, keys, num_keys);
    }

    return 0;
}
