// Generate a secure random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length == 0) return;

    for (size_t n = 0; n < length - 1; ++n) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[n] = charset[key];
    }
    str[length - 1] = '\0';
}

// Compute a checksum
unsigned int compute_checksum(const char *token) {
    unsigned long hash = 5381;
    int c;

    while ((c = *token++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }

    return (unsigned int)(hash & 0xFFFFFFFF);
}

// Generate a unique token
char *generate_unique_token(const char *normalized_email, TokenRegistry *registry) {
    static const size_t timestamp_length = 10;
    static const size_t checksum_length = 8;

    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

