    char random_string[RANDOM_STRING_LENGTH + 1];
    generate_random_string(random_string, RANDOM_STRING_LENGTH);

    char token_buffer[TOKEN_MAX_LENGTH + checksum_length + 3]; // Additional space for separators and null-terminator
    snprintf(token_buffer, sizeof(token_buffer), "%s:%ld:%s", normalized_email, time(NULL), random_string);

    unsigned int checksum = compute_checksum(token_buffer);
    snprintf(buffer, TOKEN_MAX_LENGTH, "%s-%08x", token_buffer, checksum);

    char *unique_token = malloc(TOKEN_MAX_LENGTH + 1);
    if (!unique_token) return NULL;

    pthread_rwlock_wrlock(&registry->lock);
    // Check for duplicates and append suffix if necessary
