    snprintf(full_token, sizeof(full_token), "%s", buffer);

    while (/* check against registry */) {
        snprintf(buffer, TOKEN_MAX_LENGTH, "%s_%d", token_buffer, ++suffix);
        snprintf(full_token, sizeof(full_token), "%s-%08x_%d", token_buffer, checksum, suffix);

        // Check again
    }

    strncpy(unique_token, full_token, TOKEN_MAX_LENGTH);
    unique_token[TOKEN_MAX_LENGTH] = '\0';

    pthread_rwlock_unlock(&registry->lock);

    log_operation("Token generated successfully");
    return unique_token;
}

// Log operation to a centralized logging service (placeholder)
