#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 255

// Function to count digits in a number
int countDigits(int num) {
    return num == 0 ? 1 : (int)log10(num) + 1;
}

// Function to construct the new filename
void constructNewFilename(const char *original, const char *extension, int originalLength, char *newFilename) {
    int digits = countDigits(originalLength);
    sprintf(newFilename, "%s.%0*d%s", original, digits, extension);
}

// Function to rename files in a directory
int renameFilesInDirectory(const char *directoryPath, const char *newExtension) {
    DIR *dir;
    struct dirent *entry;
    struct stat fileInfo;

    if ((dir = opendir(directoryPath)) == NULL) {
        perror("opendir");
        return errno;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char originalFilePath[MAX_FILENAME_LENGTH];
            snprintf(originalFilePath, sizeof(originalFilePath), "%s/%s", directoryPath, entry->d_name);

            if (stat(originalFilePath, &fileInfo) != 0) {
                perror("stat");
                continue;
            }

            const char *originalFilename = strrchr(entry->d_name, '/');
            originalFilename = originalFilename ? originalFilename + 1 : entry->d_name;

            int originalLength = strlen(originalFilename);
            if (originalLength == 0 || originalLength >= MAX_FILENAME_LENGTH) {
                fprintf(stderr, "Skipping invalid filename: %s\n", originalFilename);
                continue;
            }

            char newFilename[MAX_FILENAME_LENGTH];
            constructNewFilename(originalFilename, newExtension, originalLength, newFilename);

            char newFilePath[MAX_FILENAME_LENGTH];
            snprintf(newFilePath, sizeof(newFilePath), "%s/%s", directoryPath, newFilename);

            // Ensure the new filename is unique
            int counter = 1;
            char tempNewFilename[MAX_FILENAME_LENGTH];
            while (access(newFilePath, F_OK) == 0) {
                sprintf(tempNewFilename, "%s_%d.%s", originalFilename, counter++, newExtension);
                snprintf(newFilePath, sizeof(newFilePath), "%s/%s", directoryPath, tempNewFilename);
            }

            if (rename(originalFilePath, newFilePath) != 0) {
                perror("rename");
                continue;
            }
        }
    }

    closedir(dir);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory_path> <new_extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *directoryPath = argv[1];
    const char *newExtension = argv[2];

    int result = renameFilesInDirectory(directoryPath, newExtension);
    if (result != 0) {
        fprintf(stderr, "Error processing directory: %s\n", strerror(result));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

This C program dynamically renames files within a specified directory by updating their extensions based on the length of the original filename. It ensures filenames are unique and handles special characters and spaces. The function is designed to be flexible, maintainable, and scalable for future enhancements.']

