#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold in bytes

typedef struct {
    long* data;
} Offset;

typedef struct {
    int* keys;
} Key;

typedef struct {
    int value;
} Record;

typedef struct Result {
    Offset** offsets;
    int num_offsets;
    Key** keys;
    int num_keys;
    Record** records;
    int num_records;
    void (*cleanup)(struct Result*);
} Result;

void cleanup(Result* result) {
    if (result->offsets) {
        for (int i = 0; i < result->num_offsets; ++i) {
            free(result->offsets[i]->data);
            free(result->offsets[i]);
        }
        free(result->offsets);
    }

    if (result->keys) {
        for (int i = 0; i < result->num_keys; ++i) {
            free(result->keys[i]->keys);
            free(result->keys[i]);
        }
        free(result->keys);
    }

    if (result->records) {
        for (int i = 0; i < result->num_records; ++i) {
            free(result->records[i]);
        }
        free(result->records);
    }
}

Result* manage_memory(int num_offsets, int offset_size, int num_keys, int key_size, 
                      int num_records, int seed, int min_val, int max_val) {
    Result* result = (Result*)malloc(sizeof(Result));
    if (!result) return NULL;

    long total_allocated = 0;
    int memory_threshold = MAX_MEMORY_USAGE;

    // Allocate memory for Offset structures
    size_t offset_memory = num_offsets * sizeof(Offset*);
    total_allocated += offset_memory;
    if (total_allocated > memory_threshold) {
        free(result);
        fprintf(stderr, "Memory allocation exceeded threshold for offsets.\n");
        return NULL;
    }

    result->offsets = (Offset**)malloc(offset_memory);
    if (!result->offsets) {
        free(result);
        fprintf(stderr, "Failed to allocate memory for Offset pointers.\n");
        return NULL;
    }
    result->num_offsets = num_offsets;

    for (int i = 0; i < num_offsets; ++i) {
        size_t offset_array_memory = sizeof(long) * offset_size;
        total_allocated += offset_array_memory;
        if (total_allocated > memory_threshold) {
            free(result->offsets);
            free(result);
            fprintf(stderr, "Memory allocation exceeded threshold for Offset data.\n");
            return NULL;
        }

        result->offsets[i] = (Offset*)malloc(sizeof(Offset));
        if (!result->offsets[i]) {
            while (--i >= 0) free(result->offsets[i]);
            free(result->offsets);
            free(result);
            fprintf(stderr, "Failed to allocate memory for an Offset structure.\n");
            return NULL;
        }

        result->offsets[i]->data = (long*)malloc(offset_array_memory);
        if (!result->offsets[i]->data) {
            free(result->offsets[i]);
            while (--i >= 0) free(result->offsets[i]);
            free(result->offsets);
            free(result);
            fprintf(stderr, "Failed to allocate memory for Offset data.\n");
            return NULL;
        }

        // Initialize with sequential values
        for (int j = 0; j < offset_size; ++j) {
            result->offsets[i]->data[j] = j;
        }
    }

    // Allocate memory for Key structures
    size_t key_memory = num_keys * sizeof(Key*);
    total_allocated += key_memory;
    if (total_allocated > memory_threshold) {
        cleanup((Result*)result);
        fprintf(stderr, "Memory allocation exceeded threshold for keys.\n");
        return NULL;
    }

    result->keys = (Key**)malloc(key_memory);
    if (!result->keys) {
        cleanup((Result*)result);
        fprintf(stderr, "Failed to allocate memory for Key pointers.\n");
        return NULL;
    }
    result->num_keys = num_keys;

    srand(seed);

    for (int i = 0; i < num_keys; ++i) {
        size_t key_array_memory = sizeof(int) * key_size;
        total_allocated += key_array_memory;
        if (total_allocated > memory_threshold) {
            cleanup((Result*)result);
            fprintf(stderr, "Memory allocation exceeded threshold for Key data.\n");
            return NULL;
        }

        result->keys[i] = (Key*)malloc(sizeof(Key));
        if (!result->keys[i]) {
            while (--i >= 0) free(result->keys[i]->keys), free(result->keys[i]);
            free(result->keys);
            cleanup((Result*)result);
            fprintf(stderr, "Failed to allocate memory for a Key structure.\n");
            return NULL;
        }

        result->keys[i]->keys = (int*)malloc(key_array_memory);
        if (!result->keys[i]->keys) {
            free(result->keys[i]);
            while (--i >= 0) free(result->keys[i]->keys), free(result->keys[i]);
            free(result->keys);
            cleanup((Result*)result);
            fprintf(stderr, "Failed to allocate memory for Key data.\n");
            return NULL;
        }

        // Initialize with unique values
        for (int j = 0; j < key_size; ++j) {
            result->keys[i]->keys[j] = rand() % (max_val - min_val + 1) + min_val;
        }
    }

    // Allocate memory for Record structures
    size_t record_memory = num_records * sizeof(Record*);
    total_allocated += record_memory;
    if (total_allocated > memory_threshold) {
        cleanup((Result*)result);
        fprintf(stderr, "Memory allocation exceeded threshold for records.\n");
        return NULL;
    }

    result->records = (Record**)malloc(record_memory);
    if (!result->records) {
        cleanup((Result*)result);
        fprintf(stderr, "Failed to allocate memory for Record pointers.\n");
        return NULL;
    }
    result->num_records = num_records;

    int unique_values[max_val - min_val + 1];
    for (int i = 0; i < max_val - min_val + 1; ++i) {
        unique_values[i] = 0;
    }

    for (int i = 0; i < num_records; ++i) {
        size_t record_size = sizeof(Record);
        total_allocated += record_size;
        if (total_allocated > memory_threshold) {
            cleanup((Result*)result);
            fprintf(stderr, "Memory allocation exceeded threshold for Record data.\n");
            return NULL;
        }

        result->records[i] = (Record*)malloc(record_size);
        if (!result->records[i]) {
            while (--i >= 0) free(result->records[i]);
            free(result->records);
            cleanup((Result*)result);
            fprintf(stderr, "Failed to allocate memory for a Record structure.\n");
            return NULL;
        }

        int value = -1;
        do {
            value = rand() % (max_val - min_val + 1) + min_val;
        } while (unique_values[value - min_val] == 1);

        unique_values[value - min_val] = 1;
        result->records[i]->value = value;
    }

    // Set cleanup function
    result->cleanup = cleanup;

    return result;
}

int main() {
    int num_offsets = 5, offset_size = 10;
