void allocate_and_initialize_arrays(Record **records, long **offsets, int **keys, int *num_offsets, int *num_keys, int num_records, long offset_range, int key_range) {
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (!*records) { log_error("Failed to allocate memory for records."); return; }

    *offsets = (long *)malloc(num_records * sizeof(long));
    if (!*offsets) { free(*records); log_error("Failed to allocate memory for offsets."); return; }

    *keys = (int *)malloc(num_records * sizeof(int));
    if (!*keys) { free(*records); free(*offsets); log_error("Failed to allocate memory for keys."); return; }

    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = rand() % offset_range;
        do {
            (*keys)[i] = rand() % key_range;
        } while ((*keys)[i] == -1); // Ensure unique keys
    }

    *num_offsets = *num_keys = num_records;
