    if (!json_data) { log_error("JSON serialization failed."); return; }

    void *compressed_data = NULL;
    size_t compressed_size = compress_data(json_data, strlen(json_data), &compressed_data);

    int attempts = 0;
    while (attempts < MAX_RETRIES && !db_insert(compressed_data)) {
        pthread_mutex_lock(&db_mutex);
        log_error("Database insert failed. Retrying...");
        pthread_mutex_unlock(&db_mutex);

        sleep(1 << attempts); // Exponential backoff
        ++attempts;
    }

    free(json_data);
    free(compressed_data);
}

