#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    int ref_count;
    int value;
} Record;

// Node for doubly linked list to maintain LRU and frequency
typedef struct ListNode {
    Record *record;
    struct ListNode *prev, *next;
    unsigned int access_frequency;
} ListNode;

// Cache node with additional metadata
typedef struct CacheNode {
    Record record;
    ListNode list_node;
} CacheNode;

// Define the dynamic array structure
typedef struct {
    CacheNode **array;         // Dynamic array of records
    size_t capacity;           // Current capacity of the array
    size_t count;              // Number of elements currently in use
    pthread_mutex_t lock;      // Mutex for thread safety
    ListNode *head, *tail;     // Head and tail pointers for LRU list
} DynamicRecordManager;

// Initialize a new Dynamic Record Manager with specified capacity
DynamicRecordManager* dynamicRecordManagerInit(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicRecordManager *manager = (DynamicRecordManager*) malloc(sizeof(DynamicRecordManager));
    if (!manager) return NULL;

    manager->array = (CacheNode**) calloc(initial_capacity, sizeof(CacheNode*));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    // Initialize the doubly linked list for LRU and frequency
    ListNode *head = (ListNode*) malloc(sizeof(ListNode));
    ListNode *tail = (ListNode*) malloc(sizeof(ListNode));
    if (!head || !tail) {
        free(head);
        free(tail);
        free(manager->array);
        free(manager);
        return NULL;
    }

    head->prev = tail;
    head->next = NULL;
    head->record = NULL;

    tail->next = head;
    tail->prev = NULL;
    tail->record = NULL;

    manager->head = head;
    manager->tail = tail;

    return manager;
}

// Helper function to insert a record into the doubly linked list
void insertToList(ListNode *node, ListNode **head, ListNode **tail) {
    node->next = (*head);
    node->prev = NULL;

    if ((*head)) {
        (*head)->prev = node;
    }
    (*head) = node;

    if (!(*tail)) {
        (*tail) = node;
    }

    // Increment access frequency
    node->access_frequency++;
}

// Helper function to remove a node from the doubly linked list
void removeFromList(ListNode *node, ListNode **head, ListNode **tail) {
    if (node->prev) {
        node->prev->next = node->next;
    } else {
        (*head) = node->next;
    }

    if (node->next) {
        node->next->prev = node->prev;
    } else {
        (*tail) = node->prev;
    }
}

// Evict the least recently used record based on LRU and reference count
void evictRecord(DynamicRecordManager *manager) {
    ListNode *current = manager->head;

    // Find the candidate for eviction
    ListNode *candidate = NULL;
    while (current != manager->tail) {
        if (!candidate || 
            (current->list_node.record->ref_count < candidate->list_node.record->ref_count) ||
            (current->list_node.record->ref_count == candidate->list_node.record->ref_count && 
             current->access_frequency < candidate->access_frequency)) {

            candidate = current;
        }
        current = current->next;
    }

    if (!candidate) return;

    // Remove the candidate from list and array
    removeFromList(candidate, &manager->head, &manager->tail);

    size_t index = 0;
    for (; index < manager->count; ++index) {
        if (manager->array[index] == candidate) break;
    }

    free(manager->array[index]);
    manager->array[index] = NULL;
    --(manager->count);

    // Optionally persist the evicted record before freeing
    // persistRecordData(candidate->list_node.record);
}

// Function to insert or update a record in the Dynamic Record Manager
void insertOrUpdateRecord(DynamicRecordManager *manager, int key, long offset, int value) {
    pthread_mutex_lock(&manager->lock);

    // Check if record already exists and update it
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i] && manager->array[i]->record.key == key) {
            manager->array[i]->record.offset = offset;
            manager->array[i]->record.value = value;
            manager->array[i]->record.ref_count++;

            // Update position in LRU list
            removeFromList(&manager->array[i]->list_node, &manager->head, &manager->tail);
            insertToList(&manager->array[i]->list_node, &manager->head, &manager->tail);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Insert new record if it doesn't exist
    if (manager->count == manager->capacity) {
        evictRecord(manager);

        // If still no space available, try resizing the array
        if (manager->count == manager->capacity) {
            size_t new_capacity = manager->capacity * 2;
            CacheNode **new_array = realloc(manager->array, new_capacity * sizeof(CacheNode*));
            if (!new_array) {
                pthread_mutex_unlock(&manager->lock);
                return; // Memory allocation failed
            }
            memset(new_array + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(CacheNode*));

            manager->array = new_array;
            manager->capacity = new_capacity;
        }
    }

    // Create a new record
    CacheNode *new_node = (CacheNode*) malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return; // Memory allocation failed
    }

    new_node->record.key = key;
    new_node->record.offset = offset;
    new_node->record.value = value;
    new_node->record.ref_count = 1;

    insertToList(&new_node->list_node, &manager->head, &manager->tail);

    // Insert into the array
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->array[i]) {
            manager->array[i] = new_node;
            break;
        }
    }

    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

// Function to find a record by its key
Record* getRecord(DynamicRecordManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i] && manager->array[i]->record.key == key) {
            // Update LRU position
            removeFromList(&manager->array[i]->list_node, &manager->head, &manager->tail);
            insertToList(&manager->array[i]->list_node, &manager->head, &manager->tail);

            Record *found_record = &(manager->array[i]->record);
            pthread_mutex_unlock(&manager->lock);
            return found_record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Function to delete a record by its key
void deleteRecord(DynamicRecordManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i] && manager->array[i]->record.key == key) {
            // Remove from LRU list
            removeFromList(&manager->array[i]->list_node, &manager->head, &manager->tail);

            free(manager->array[i]);
            manager->array[i] = NULL;
            --(manager->count);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to find the largest integer value in the records
int findLargestValue(DynamicRecordManager *manager) {
    int max_value = INT_MIN;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i] && manager->array[i]->record.value > max_value) {
            max_value = manager->array[i]->record.value;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return max_value;
}

// Cleanup function to deallocate resources
void dynamicRecordManagerCleanup(DynamicRecordManager *manager) {
    if (!manager) return;

    // Free all nodes in the list
    ListNode *current = manager->head;
    while (current != manager->tail) {
        ListNode *next_node = current->next;
        free(current);
        current = next_node;
    }

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->array[i]) {
            free(manager->array[i]);
        }
    }

    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Placeholder function for persisting record data
void persistRecordData(Record *record) {
    // Implement network-related persistence logic here, using a reliable protocol like TCP.
    // Handle errors gracefully and retry if necessary.
}
