pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Error codes
#define SUCCESS 0
#define ALLOCATION_ERROR -1

// Function prototypes
int initialize_records(record ***records, const int *keys, size_t keys_size, unsigned int seed, char (*string_strategy)(size_t index));

// Utility functions
unsigned int xorshift32(unsigned int x) {
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

int initialize_records(record ***records, const int *keys, size_t keys_size, unsigned int seed, char *(*string_strategy)(size_t index)) {
    pthread_mutex_lock(&lock);

    if (!records || !keys || !keys_size || !string_strategy) {
        fprintf(stderr, "Invalid input parameters.\n");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_ERROR;
    }

    size_t total_records = 0;
    for (size_t i = 0; i < keys_size; ++i) {
        total_records += keys[i];
    }

    record *all_records = malloc(total_records * sizeof(record));
    if (!all_records) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_ERROR;
    }

    int *random_values = malloc(total_records * sizeof(int));
    if (!random_values) {
        free(all_records);
        fprintf(stderr, "Memory allocation failed for random values.\n");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_ERROR;
    }

    // Seed the random number generator
    unsigned int x = seed;

    size_t index = 0;
    for (size_t i = 0; i < keys_size; ++i) {
        if (keys[i] > 0) {
            *records = realloc(*records, sizeof(record*) * (i + 1));
            if (!*records) {
                free(all_records);
                free(random_values);
                fprintf(stderr, "Memory reallocation failed.\n");
                pthread_mutex_unlock(&lock);
                return ALLOCATION_ERROR;
            }
            (*records)[i] = &all_records[index];

            for (int j = 0; j < keys[i]; ++j) {
                random_values[index] = xorshift32(x) % 100; // Random number between 0 and 99
                x ^= x << 13;
                x ^= x >> 17;
                x ^= x << 5;

                char* string_ptr = string_strategy(j);
                if (!string_ptr) {
                    fprintf(stderr, "Failed to get a predefined string.\n");
                    free(all_records);
                    free(random_values);
                    pthread_mutex_unlock(&lock);
                    return ALLOCATION_ERROR;
                }

                all_records[index].value = random_values[index];
                size_t str_len = strlen(string_ptr) + 1; // +1 for null terminator
                all_records[index].string = malloc(str_len);
                if (!all_records[index].string) {
                    free(all_records);
                    free(random_values);
                    fprintf(stderr, "Memory allocation failed for string.\n");
                    pthread_mutex_unlock(&lock);
                    return ALLOCATION_ERROR;
                }
                strcpy(all_records[index].string, string_ptr);

                ++index;
            }
        } else {
            *records = realloc(*records, sizeof(record*) * (i + 1));
            if (!*records) {
                free(all_records);
                free(random_values);
                fprintf(stderr, "Memory reallocation failed.\n");
                pthread_mutex_unlock(&lock);
                return ALLOCATION_ERROR;
            }
            (*records)[i] = NULL; // Zero-sized sub-array
        }
    }

    free(random_values);

    pthread_mutex_unlock(&lock);
    return total_records;
}

// Example string strategy function (to be replaced with actual logic)
char* get_predefined_string(size_t index) {
    static char *strings[] = {"Hello", "World", "C Programming", "Concurrency"};
    if (index < sizeof(strings)/sizeof(strings[0])) {
        return strings[index % (sizeof(strings)/sizeof(strings[0]))];
    }
    return NULL;
}

// Test function for unit testing
void test_initialize_records() {
    int keys[] = {2, 3, 0, 1};
    record **records;
    size_t records_size = sizeof(keys) / sizeof(int);

    unsigned int seed = time(NULL);
    int result = initialize_records(&records, keys, records_size, seed, get_predefined_string);

    if (result != -1 && result != ALLOCATION_ERROR) {
        printf("Total records allocated: %d\n", result);
        for (size_t i = 0; i < records_size; ++i) {
            if (records[i]) {
                size_t sub_array_length = 0;
                while (records[i][sub_array_length].string != NULL) {
                    printf("Record[%zu][%zu]: value=%d, string=%s\n", i, sub_array_length, records[i][sub_array_length].value, records[i][sub_array_length].string);
                    ++sub_array_length;
                }
            } else {
                printf("Sub-array %zu is zero-sized.\n", i);
            }
        }

        // Free allocated memory
        for (size_t i = 0; i < records_size; ++i) {
            if (records[i]) {
                size_t sub_array_length = 0;
                while (records[i][sub_array_length].string != NULL) {
                    free(records[i][sub_array_length].string);
                    ++sub_array_length;
                }
                free(&records[i]);
            }
        }
        free(records);
    } else {
        printf("Initialization failed with error code: %d\n", result);
    }
}

int main() {
    test_initialize_records();
    return 0;
}
