#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>

#define MIN_NAME_LEN 5
#define MAX_NAME_LEN 20
#define COST_MIN 1000.0
#define COST_MAX 50000.0

typedef struct {
    char *name;
    double estimated_cost;
    struct timeval start_date;
    unsigned long long project_id;
} Project;

// Thread-safe linked list node for projects
typedef struct Node {
    Project project;
    struct Node* next;
} Node;

Node* head = NULL;  // Head of the thread-safe list

pthread_mutex_t lock;

void initialize_projects(int num) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num; ++i) {
        add_project(i + 1);  // Ensure unique IDs
    }
    pthread_mutex_unlock(&lock);
}

// Generates a random alphanumeric string of length within specified range
char* generate_random_string(size_t len) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (len < MIN_NAME_LEN || len > MAX_NAME_LEN)
        return NULL;

    char *randomString = malloc(sizeof(char) * (len + 1));
    if (!randomString) return NULL;

    for (size_t i = 0; i < len; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        randomString[i] = charset[key];
    }
    randomString[len] = '\0';
    return randomString;
}

// Adds a new project asynchronously
void add_project(unsigned long long id) {
    Node* node = malloc(sizeof(Node));
    if (!node) return;

    // Initialize the project
    char *name = generate_random_string(rand() % (MAX_NAME_LEN - MIN_NAME_LEN + 1) + MIN_NAME_LEN);
    double cost = COST_MIN + ((double)rand() / RAND_MAX) * (COST_MAX - COST_MIN);
    gettimeofday(&node->project.start_date, NULL);

    if (!name) {
        free(node);
        return;
    }

    node->project.name = name;
    node->project.estimated_cost = cost;
    node->project.project_id = id;

    // Append to the list
    node->next = head;
    head = node;
}

Project* find_project_by_id(unsigned long long id) {
    Node *current = head;
    while (current != NULL) {
        if (current->project.project_id == id) return &current->project;
        current = current->next;
    }
    return NULL;
}

void update_project_cost(unsigned long long id, double new_cost) {
    Project* proj = find_project_by_id(id);
    if (proj) {
        pthread_mutex_lock(&lock);
        proj->estimated_cost = new_cost;
        pthread_mutex_unlock(&lock);
    }
}

Project* get_project_at_index(int index) {
    Node *current = head;
    int i = 0;
    while (current != NULL && i < index) {
        current = current->next;
        ++i;
    }
    return (current ? &current->project : NULL);
}

// Sorts the project list based on estimated cost
void sort_projects_by_cost() {
    pthread_mutex_lock(&lock);

    if (!head || !head->next) {
        pthread_mutex_unlock(&lock);
        return;
    }

    int swapped;
    Node *ptr1, *lptr = NULL;

    do {
        swapped = 0;
        ptr1 = head;

        while (ptr1->next != lptr) {
            if (ptr1->project.estimated_cost > ptr1->next->project.estimated_cost) {
                Project temp = ptr1->project;
                ptr1->project = ptr1->next->project;
                ptr1->next->project = temp;
                swapped = 1;
            }
            ptr1 = ptr1->next;
        }
        lptr = ptr1;
    } while (swapped);

    pthread_mutex_unlock(&lock);
}

// Placeholder for database integration and synchronization
void sync_with_database() {
    // Implement database interaction logic here
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&lock, NULL);

    initialize_projects(10);  // Initialize with 10 projects

    // Add more operations like updating, sorting, etc.

    pthread_mutex_destroy(&lock);
    return 0;
}
```

