#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

// Function to initialize records and manage them
void initializeAndManageRecords(const char *filename, size_t num_records, int min_value, int max_value) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        fclose(file);
        return;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Initialize records with random values and memory for offsets and keys
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].offset = (long *)malloc(sizeof(long));
        if (!records[i].offset) {
            fprintf(stderr, "Memory allocation failed for offset at index %zu.\n", i);
            // Clean up already allocated memory
            while (--i >= 0) free(records[i].offset);
            free(records);
            fclose(file);
            return;
        }
        records[i].key = (int *)malloc(sizeof(int));
        if (!records[i].key) {
            fprintf(stderr, "Memory allocation failed for key at index %zu.\n", i);
            free(records[i].offset);
            // Clean up already allocated memory
            while (--i >= 0) free(records[i].offset);
            free(records);
            fclose(file);
            return;
        }
    }

    int number;
    size_t index = 0;
    int largest_value = INT_MIN;
    size_t largest_index = SIZE_MAX;

    // Read numbers from file and find the first occurrence of the largest integer
    while (fscanf(file, "%d", &number) == 1) {
        if (index >= num_records) break; // Prevent reading beyond allocated records

        // Update largest value and index if current number is larger
        if (number > largest_value) {
            largest_value = number;
            largest_index = index;
        }

        // Store the read number in the record's key for reference
        *(records[index].key) = number;

        ++index;
    }

    fclose(file);

    if (largest_index != SIZE_MAX) {
        printf("First occurrence of largest value: Index %zu, Value %d\n", largest_index, records[largest_index].value);
    } else {
        printf("No valid numbers were read from the file.\n");
    }

    // Free allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);
}
