#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for an entry
typedef struct {
    char *key;
    size_t length;
    time_t timestamp;
} Entry;

// Hash table node
typedef struct HashNode {
    const char *key;
    int index;
    struct HashNode *next;
} HashNode;

// Hash table structure
typedef struct {
    HashNode **buckets;
    size_t capacity;
    size_t size;
} HashTable;

// Custom array for entries
typedef struct {
    Entry **entries;
    size_t count;
    size_t capacity;
} EntryArray;

// Function declarations
HashTable* create_hash_table(size_t initial_capacity);
void free_hash_table(HashTable *hash_table);
int hash_function(const char *key, size_t capacity);
EntryArray* init_entry_array(size_t initial_capacity);
void free_entry_array(EntryArray *entry_array, HashTable *index_map);
int resize_hash_table(HashTable *hash_table);
int resize_entry_array(EntryArray *entry_array);

// Create a new hash table
HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashNode **)calloc(initial_capacity, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

// Free the hash table
void free_hash_table(HashTable *hash_table) {
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        HashNode *node = hash_table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free((void *)temp->key);
            free(temp);
        }
    }
    free(hash_table->buckets);
    free(hash_table);
}

// Simple hash function
int hash_function(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % (int)capacity;
}

// Initialize the entry array
EntryArray* init_entry_array(size_t initial_capacity) {
    EntryArray *array = (EntryArray *)malloc(sizeof(EntryArray));
    if (!array) return NULL;

    array->entries = (Entry **)calloc(initial_capacity, sizeof(Entry *));
    if (!array->entries) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    return array;
}

// Free the entry array
void free_entry_array(EntryArray *entry_array, HashTable *index_map) {
    for (size_t i = 0; i < entry_array->count; ++i) {
        free(entry_array->entries[i]->key);
        free(entry_array->entries[i]);
    }
    free(entry_array->entries);

    free_hash_table(index_map);
    free(entry_array);
}

// Resize the hash table
int resize_hash_table(HashTable *hash_table) {
    size_t new_capacity = 2 * hash_table->capacity;
    HashNode **new_buckets = (HashNode **)calloc(new_capacity, sizeof(HashNode *));
    if (!new_buckets) return 0;

    for (size_t i = 0; i < hash_table->capacity; ++i) {
        HashNode *node = hash_table->buckets[i];
        while (node) {
            HashNode *next_node = node->next;
            int index = hash_function((const char *)node->key, new_capacity);
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = next_node;
        }
    }

    free(hash_table->buckets);
    hash_table->buckets = new_buckets;
    hash_table->capacity = new_capacity;

    return 1;
}

// Resize the entry array
int resize_entry_array(EntryArray *entry_array) {
    size_t new_capacity = 2 * entry_array->capacity;
    Entry **new_entries = (Entry **)realloc(entry_array->entries, new_capacity * sizeof(Entry *));
    if (!new_entries) return 0;

    memset(new_entries + entry_array->capacity, 0, new_capacity - entry_array->capacity);
    entry_array->capacity = new_capacity;

    return 1;
}

// Add a key-value pair to the entry array and hash table
int add_entry(EntryArray *entry_array, HashTable *index_map, const char *key, size_t length, time_t timestamp) {
    if (entry_array->count == entry_array->capacity && !resize_entry_array(entry_array)) return 0;
    if (index_map->size >= index_map->capacity && !resize_hash_table(index_map)) return 0;

    Entry *new_entry = (Entry *)malloc(sizeof(Entry));
    if (!new_entry) return 0;

    new_entry->key = strdup(key);
    new_entry->length = length;
    new_entry->timestamp = timestamp;

    entry_array->entries[entry_array->count++] = new_entry;

    int index = hash_function(key, index_map->capacity);
    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    if (!node) {
        free(new_entry->key);
        free(new_entry);
        return 0;
    }

    node->key = strdup(key);
    node->index = entry_array->count - 1;
    node->next = index_map->buckets[index];
    index_map->buckets[index] = node;
    index_map->size++;

    return 1;
}

// Example usage
int main() {
    EntryArray *entry_array = init_entry_array(4);
    HashTable *index_map = create_hash_table(8);

    if (!entry_array || !index_map) {
        printf("Failed to initialize structures.\n");
        return 1;
    }

    add_entry(entry_array, index_map, "key1", 5, time(NULL));
    add_entry(entry_array, index_map, "key2", 7, time(NULL));

    free_entry_array(entry_array, index_map);

    return 0;
}
```

### Key Considerations:
- **Memory Management**: The code ensures that all dynamically allocated memory is freed to prevent leaks.
- **Performance Optimization**: A simple hash function and dynamic resizing are used for efficient lookups and insertions.
- **Error Handling**: Checks are in place for allocation failures, allowing the system to handle temporary resource limitations gracefully.
- **Scalability**: Dynamic resizing of both the entry array and hash table ensures scalability with increasing data volumes.']

