public class ConfigLoader {

    private static final String DEFAULT_CONFIG_DIR = "defaultConfig";
    private static final String CACHE_ROOT_DIR = "cacheRoot";
    private static final String CONFIG_FILE_EXTENSION = ".properties";

    public static Configuration loadConfiguration(String configFilePath) throws IOException {
        Path defaultConfigDirPath = Paths.get(DEFAULT_CONFIG_DIR);
        Path cacheRootDirPath = Paths.get(CACHE_ROOT_DIR);

        // Ensure the default configuration directory exists
        Files.createDirectories(defaultConfigDirPath);

        // Check if the specified configuration file exists
        Path configFilePathObj = Paths.get(configFilePath);
        boolean configFileExists = Files.exists(configFilePathObj);

        Properties properties = new Properties();

        try (InputStream inputStream = getConfigFileInputStream(configFilePathObj)) {
            properties.load(inputStream);
        } catch (IOException e) {
            // If the file does not exist or is outdated, create a default configuration
            if (!configFileExists || !isConfigUpToDate(configFilePathObj)) {
                Path defaultConfigPath = getDefaultConfigPath(defaultConfigDirPath, configFilePathObj.getFileName());
                saveDefaultConfiguration(defaultConfigPath);

                try (InputStream inputStream = getConfigFileInputStream(defaultConfigPath)) {
                    properties.load(inputStream);
                }
            } else {
                throw e;
            }
        }

        // Parse the configuration file from cache root directory
        Path cachedConfigFilePath = getCachedConfigFilePath(cacheRootDirPath, configFilePathObj.getFileName());
        try (InputStream inputStream = getConfigFileInputStream(cachedConfigFilePath)) {
            properties.load(inputStream);
        }

        return new Configuration(properties);
    }

    private static InputStream getConfigFileInputStream(Path filePath) throws FileNotFoundException {
        File file = filePath.toFile();
        if (!file.exists()) {
            throw new FileNotFoundException("Configuration file not found: " + filePath);
        }
        return new FileInputStream(file);
    }

