        Properties defaultProperties = new Properties();
        defaultProperties.setProperty("setting1", "defaultValue1");
        defaultProperties.setProperty("setting2", "defaultValue2");

        try (OutputStream outputStream = Files.newOutputStream(configFilePath)) {
            defaultProperties.store(outputStream, "Default Configuration");
        }
    }

    private static Path getCachedConfigFilePath(Path cacheRootDirPath, String fileName) {
        return cacheRootDirPath.resolve(fileName + CONFIG_FILE_EXTENSION);
