```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_random() {
    srand(time(NULL));
}

int random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->records = calloc(initial_capacity, sizeof(Record *));
    if (!da->records) {
        free(da);
        return NULL;
    }

    da->count = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (!da) return;

    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        free(da->records[i]->offset);
        free(da->records[i]->key);
        free(da->records[i]);
    }
    free(da->records);
    pthread_mutex_unlock(&da->lock);

    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_record(DynamicArray *da, int value_min, int value_max) {
    if (!da || value_min > value_max) return -1;

    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        Record **new_records = realloc(da->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&da->lock);
            return -1;
        }
        da->records = new_records;
        da->capacity = new_capacity;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    record->value = random_value(value_min, value_max);

    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        free(record);
        pthread_mutex_unlock(&da->lock);
        return -1;
    }
    *record->offset = 0; // Initialize offset

    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        free(record);
        pthread_mutex_unlock(&da->lock);
        return -1;
    }
    *record->key = 0; // Initialize key

    da->records[da->count++] = record;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

void periodic_flush(DynamicArray *da) {
    if (!da) return;

    // Placeholder for external storage flush logic
    pthread_mutex_lock(&da->lock);

    // Example: Print records (replace with actual I/O operation)
    for (size_t i = 0; i < da->count; ++i) {
        printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n", 
               i, da->records[i]->value, *(da->records[i]->offset), *(da->records[i]->key));
    }

    pthread_mutex_unlock(&da->lock);
}

int main() {
    init_random();
    DynamicArray *da = create_dynamic_array(10);

    if (!da) {
        fprintf(stderr, "Failed to create dynamic array.\n");
        return 1;
    }

    for (int i = 0; i < 15; ++i) { // Add more records than initial capacity
        if (add_record(da, 1, 100) != 0) {
            fprintf(stderr, "Failed to add record %d.\n", i);
        }
    }

    periodic_flush(da);

    destroy_dynamic_array(da);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` is used for synchronizing access to the dynamic array.
- **Memory Management**: Memory allocation and deallocation are handled carefully to avoid leaks.
- **Error Handling**: Allocation failures are checked, and appropriate actions are taken.
- **Dynamic Resizing**: The capacity of the dynamic array doubles when needed.
