typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    u_char ip[16]; // Max size for IPv6 address
} dns_entry_t;

dns_entry_t dns_cache[DNS_CACHE_SIZE];
int cache_index = 0;
