u_char* resolve_dns(const char *hostname, int *error_code) {
    struct addrinfo hints, *res, *p;
    char ipstr[INET6_ADDRSTRLEN];
    int rv;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((rv = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        *error_code = errno;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("IP address: %s\n", ipstr);

        memcpy(dns_cache[cache_index].ip, addr, p->ai_addrlen);
        strncpy(dns_cache[cache_index].hostname, hostname, MAX_HOSTNAME_LENGTH);
        cache_index = (cache_index + 1) % DNS_CACHE_SIZE;
    }

    freeaddrinfo(res);
    *error_code = 0;

    return dns_cache[cache_index - 1].ip;
}

void* process_file(void *arg) {
    file_thread_data_t *data = (file_thread_data_t *)arg;
    FILE *fp = fopen(data->filename, "r");
    if (!fp) {
        log_error("Failed to open file");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Process the line
        printf("%s", line);

        // Example of DNS resolution integration
        int error_code = 0;
        u_char *ip_address = resolve_dns("example.com", &error_code);
        if (error_code) {
            log_error("DNS resolution failed");
        }
    }

    fclose(fp);
    return NULL;
}

void rate_limited_dns_resolution(const char *hostname, int *error_code) {
    static pthread_mutex_t rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
    static unsigned long last_query_time = 0;
    unsigned long current_time = time(NULL);

    pthread_mutex_lock(&rate_limit_lock);
    if (current_time - last_query_time < 1.0 / RATE_LIMIT_MAX_QUERIES_PER_SECOND) {
        pthread_mutex_unlock(&rate_limit_lock);
        *error_code = EAGAIN; // Try again later
        return;
    }
    last_query_time = current_time;
    pthread_mutex_unlock(&rate_limit_lock);

    resolve_dns(hostname, error_code);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_files = argc - 1;
    file_thread_data_t file_threads[num_files];

    for (int i = 0; i < num_files; ++i) {
        file_threads[i].filename = argv[i + 1];
        if (pthread_create(&file_threads[i].thread_id, NULL, process_file, &file_threads[i])) {
            log_error("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(file_threads[i].thread_id, NULL);
    }

    return EXIT_SUCCESS;
}
