#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>

typedef struct {
    float timestamp;
    char status_indicator;
    char *message_buffer;
} log_entry;

typedef struct {
    atomic_size_t size;
    atomic_size_t capacity;
    log_entry **entries;
    void (*free_fn)(void*);
} memory_pool;

// Function to create a new memory pool
memory_pool* create_memory_pool(size_t initial_capacity) {
    memory_pool *pool = malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    size_t sizes[initial_capacity];
    memset(sizes, 0, sizeof(sizes));

    atomic_store(&pool->size, 0);
    atomic_store(&pool->capacity, initial_capacity);

    pool->entries = malloc(initial_capacity * sizeof(log_entry*));
    if (!pool->entries) {
        free(pool);
        return NULL;
    }

    pool->free_fn = free;

    return pool;
}

// Function to grow the memory pool
void ensure_capacity(memory_pool *pool) {
    size_t current_capacity = atomic_load(&pool->capacity);

    while (atomic_load(&pool->size) >= current_capacity) {
        current_capacity *= 2;
        log_entry **new_entries = realloc(pool->entries, current_capacity * sizeof(log_entry*));
        if (!new_entries) return;

        memset(new_entries + current_capacity / 2, 0, (current_capacity / 2) * sizeof(log_entry*));

        pool->entries = new_entries;
        atomic_store(&pool->capacity, current_capacity);
    }
}

// Function to add a log entry
log_entry* add_log_entry(memory_pool *pool, float timestamp, char status_indicator, const char *message) {
    ensure_capacity(pool);

    size_t index = atomic_fetch_add(&pool->size, 1);

    log_entry *entry = malloc(sizeof(log_entry));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    entry->status_indicator = status_identifier;
    size_t message_len = strlen(message) + 1; // +1 for null terminator
    entry->message_buffer = malloc(message_len);

    if (entry->message_buffer) {
        memcpy(entry->message_buffer, message, message_len);
    }

    pool->entries[index] = entry;

    return entry;
}

// Function to remove a log entry
void remove_log_entry(memory_pool *pool, size_t index) {
    if (index >= atomic_load(&pool->size)) return;

    log_entry *entry = pool->entries[index];
    if (!entry) return;

    free(entry->message_buffer);
    free(entry);

    memmove(&pool->entries[index], &pool->entries[index + 1], 
            (atomic_fetch_sub(&pool->size, 1) - index) * sizeof(log_entry*));
}

// Function to clear all log entries
void clear_log_pool(memory_pool *pool) {
    size_t current_size = atomic_load(&pool->size);

    for (size_t i = 0; i < current_size; ++i) {
        if (pool->entries[i]) {
            free(pool->entries[i]->message_buffer);
            free(pool->entries[i]);
        }
    }

    free(pool->entries);
    pool->entries = NULL;

    atomic_store(&pool->size, 0);
    atomic_store(&pool->capacity, 0);
}

// Function to destroy the memory pool
void destroy_memory_pool(memory_pool *pool) {
    clear_log_pool(pool);
    free(pool);
}
