// Main function to manage memory allocation and initialization
Record* manage_memory(const char *config_path) {
    Config config;
    if (parse_config_file(config_path, &config)) {
        fprintf(stderr, "Failed to load configuration.\n");
        return NULL;
    }

    int num_records = config.num_records;
    Record *records = malloc(num_records * sizeof(Record));
    int *keys = malloc(num_records * sizeof(int));
    long *offsets = malloc(num_records * sizeof(long));

    if (!records || !keys || !offsets) {
        fprintf(stderr, "Memory allocation failed.\n");
        free_memory(&records, &keys, offsets, num_records);
        return NULL;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (config.rand_max - config.rand_min + 1) + config.rand_min;
        offsets[i] = rand(); // Simulate loading an offset
        records[i].key = keys[i];
        records[i].offset = &offsets[i];
    }

    if (config.debug_mode && config.logging_level > 0) {
        for (int i = 0; i < num_records; ++i) {
            printf("Record %d: Key = %d, Offset = %ld\n", i, records[i].key, *records[i].offset);
        }
    }

    free(keys); // Keys are no longer needed
    return records;
}

// Helper functions

int parse_config_file(const char *path, Config *config) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening config file");
        return 1;
    }

    if (fscanf(file, "%d %d %d %d %d", &config->num_records, &config->rand_min,
               &config->rand_max, &config->logging_level, &config->debug_mode) != 5) {
        fprintf(stderr, "Error parsing config file\n");
        fclose(file);
        return 1;
    }

    fclose(file);
    return 0;
}

void free_memory(Record **records, int *keys, long *offsets, int num_records) {
    if (records && *records) free(*records);
    if (keys) free(keys);
    if (offsets) free(offsets);
}
