```rust
// Rust: Logging Directory Management Module

use std::fs;
use std::sync::{Arc, Mutex};
use std::path::PathBuf;
use rand::Rng;

pub struct LoggerConfig {
    base_path: PathBuf,
}

impl LoggerConfig {
    pub fn new(base_path: &str) -> Self {
        Self { 
            base_path: PathBuf::from(base_path)
        }
    }

    // Validate and create directory path
    pub fn validate_and_create_dir(&self, dir_name: &str) -> Result<(), String> {
        let full_path = self.base_path.join(dir_name);

        if !full_path.exists() {
            match fs::create_dir_all(&full_path) {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("Failed to create directory {}: {}", dir_name, e)),
            }
        } else {
            Ok(())
        }
    }

    // Check available disk space
    pub fn check_disk_space(&self, min_free_space: u64) -> Result<(), String> {
        let metadata = fs::metadata(&self.base_path)
            .map_err(|e| format!("Failed to get directory metadata: {}", e))?;

        if metadata.free_space() < min_free_space {
            Err("Insufficient disk space".to_string())
        } else {
            Ok(())
        }
    }
}

pub struct LoggerService {
    config: Arc<LoggerConfig>,
}

impl LoggerService {
    pub fn new(base_path: &str) -> Self {
        Self { 
            config: Arc::new(LoggerConfig::new(base_path))
        }
    }

    pub fn create_logging_dir(&self, dir_name: &str) -> Result<(), String> {
        self.config.validate_and_create_dir(dir_name)
    }

    pub fn monitor_disk_space(&self, min_free_space: u64) -> Result<(), String> {
        self.config.check_disk_space(min_free_space)
    }
}
