// C: Log Entry Data Structure with Memory Pool

#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define POOL_SIZE 1024 * 16 // Example size, should be power of two
#define LOG_ENTRY_COUNT (POOL_SIZE / sizeof(LogEntry))

typedef struct {
    int offset;
    char key[64];
    int record;
    uint64_t timestamp;
    int status_flag;
    int reference_count;
} LogEntry;

LogEntry log_pool[LOG_ENTRY_COUNT];
int available_indices[LOG_ENTRY_COUNT];

void initialize_memory_pool() {
    for (size_t i = 0; i < LOG_ENTRY_COUNT; ++i) {
        memset(&log_pool[i], 0, sizeof(LogEntry));
        available_indices[i] = i;
    }
}

LogEntry* allocate_log_entry(int (*rng)(int, int)) {
    if (available_indices[LOG_ENTRY_COUNT - 1] == -1) return NULL;

    size_t index = available_indices[LOG_ENTRY_COUNT - 1];
    for (size_t i = LOG_ENTRY_COUNT - 1; i > 0; --i) {
        if (available_indices[i-1] != -1) {
            index = available_indices[i-1];
            break;
        }
    }

    if (index == -1) return NULL;

    size_t actual_index = available_indices[index];
    available_indices[index] = -1;

    log_pool[actual_index].record = rng(1, 1000);
    return &log_pool[actual_index];
}

void deallocate_log_entry(LogEntry* entry) {
    size_t index = (uint8_t*)entry - (uint8_t*)log_pool;
    available_indices[index] = index;
}

int random_int(int min, int max) {
    // Replace this with an actual random number generator implementation
    return rand() % (max - min + 1) + min;
}

void compact_memory_pool() {
    size_t next_free_index = 0;
    for (size_t i = 0; i < LOG_ENTRY_COUNT; ++i) {
        if (available_indices[i] != -1 && log_pool[available_indices[i]].reference_count == 0) {
            available_indices[next_free_index++] = available_indices[i];
            memset(&log_pool[available_indices[i]], 0, sizeof(LogEntry));
        }
    }

    while (next_free_index < LOG_ENTRY_COUNT) {
        available_indices[next_free_index++] = -1;
    }
}
