#include <string.h>
#include <json-c/json.h>

typedef struct {
    char *file_path;
    int width;
    int height;
    char **metadata_tags;
    size_t metadata_count;
} image_metadata;

void freeImageMetadata(image_metadata *metadata, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(metadata[i].file_path);
        for (size_t j = 0; j < metadata[i].metadata_count; ++j) {
            free(metadata[i].metadata_tags[j]);
        }
        free(metadata[i].metadata_tags);
    }
    free(metadata);
}

int parseJSONFile(const char *filename, image_metadata *record) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        return -1;
    }

    struct json_object *parsed_json;
    struct json_object *file_path;
    struct json_object *width;
    struct json_object *height;
    struct json_object *tags_array;

    parsed_json = json_object_from_file(filename);
    if (!parsed_json) {
        fprintf(stderr, "Error: Unable to parse JSON file %s\n", filename);
        fclose(file);
        return -1;
    }

    if (json_object_object_get_ex(parsed_json, "file_path", &file_path) &&
        json_object_object_get_ex(parsed_json, "width", &width) &&
        json_object_object_get_ex(parsed_json, "height", &height) &&
        json_object_object_get_ex(parsed_json, "metadata_tags", &tags_array)) {

        record->file_path = strdup(json_object_get_string(file_path));
        record->width = (int)json_object_get_int(width);
        record->height = (int)json_object_get_int(height);

        size_t tags_count = json_object_array_length(tags_array);
        record->metadata_tags = malloc(tags_count * sizeof(char *));
        if (!record->metadata_tags) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            json_object_put(parsed_json);
            fclose(file);
            return -1;
        }

        for (size_t i = 0; i < tags_count; ++i) {
            struct json_object *tag = json_object_array_get_idx(tags_array, i);
            record->metadata_tags[i] = strdup(json_object_get_string(tag));
        }

        record->metadata_count = tags_count;
    } else {
        fprintf(stderr, "Error: Malformed JSON structure in file %s\n", filename);
        json_object_put(parsed_json);
        fclose(file);
        return -1;
    }

    json_object_put(parsed_json);
    fclose(file);
    return 0;
}

void processImageMetadata(const char **json_files, size_t count) {
    image_metadata *metadata_array = malloc(count * sizeof(image_metadata));
    if (!metadata_array) {
        fprintf(stderr, "Error: Memory allocation failed for metadata array\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        if (parseJSONFile(json_files[i], &metadata_array[i]) != 0) {
            freeImageMetadata(metadata_array, i);
            free(metadata_array);
            return;
        }
    }

    size_t max_tags_index = 0;
    for (size_t i = 1; i < count; ++i) {
        if (metadata_array[i].metadata_count > metadata_array[max_tags_index].metadata_count) {
            max_tags_index = i;
        }
    }

    printf("File: %s, Width: %d, Height: %d\n",
           metadata_array[max_tags_index].file_path,
           metadata_array[max_tags_index].width,
           metadata_array[max_tags_index].height);

    freeImageMetadata(metadata_array, count);
}
