#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define record structure
typedef struct {
    int key;
} Record;

// Define DOM tree node structure for recursion
typedef struct Node {
    char* className;
    char* id;
    struct Node* children;
    struct Node* nextSibling;
} Node;

// Function prototypes
void* allocateMemory(size_t size);
void freeMemory(void* ptr);
Record* initializeRecords(Node* root, int min, int max);
Node* traverseTree(Node* root, void (*callback)(Node*, Node**), const char* selector);
int isElementMatched(Node* element, const char* selector);

// Main function
Record* processDOM(Node* root, int min, int max, const char* selector) {
    // Allocate memory for records and initialize them with random values within [min, max]
    Record* records = initializeRecords(root, min, max);

    // Traverse the DOM tree and collect elements that match the given selector
    Node* matchingElements = traverseTree(root, &recursiveCallback, selector);

    // Free allocated memory
    freeMemory(records);
    freeMemory(matchingElements);

    return records;
}

// Initialize records with random values within the specified range
Record* initializeRecords(Node* root, int min, int max) {
    int numRecords = 100; // Adjust based on expected tree depth and performance requirements
    Record* records = (Record*)allocateMemory(numRecords * sizeof(Record));
    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (max - min + 1) + min;
    }

    return records;
}

// Traverse the DOM tree and apply a callback function to each node
Node* traverseTree(Node* root, void (*callback)(Node*, Node**), const char* selector) {
    if (!root) return NULL;

    Node* matchedNodes = (Node*)allocateMemory(sizeof(Node));
    matchedNodes->children = NULL;
    matchedNodes->nextSibling = NULL;

    Node* currentHead = matchedNodes;

    while (root != NULL) {
        if (isElementMatched(root, selector)) {
            callback(root, &currentHead);
        }
        root = root->nextSibling;
    }

    return matchedNodes;
}

// Check if an element matches the given CSS selector
int isElementMatched(Node* element, const char* selector) {
    // Simple matching: check className or id against selector
    if (strcmp(element->className, selector) == 0 || strcmp(element->id, selector) == 0) {
        return 1;
    }
    return 0;
}

// Callback function for traversing the DOM tree and collecting matched nodes
void recursiveCallback(Node* node, Node** head) {
    Node* newNode = (Node*)allocateMemory(sizeof(Node));
    newNode->className = node->className;
    newNode->id = node->id;
    newNode->children = NULL;

    // Append to the list of matched nodes
    while (*head != NULL && (*head)->nextSibling != NULL) {
        head = &((*head)->nextSibling);
    }
    (*head)->nextSibling = newNode;
}

// Memory allocation and deallocation functions
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void freeMemory(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}
