#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 10000

typedef enum { ACTIVE, INACTIVE, EXPIRED } SessionState;

struct Session {
    int sessionId;
    time_t startTimestamp;
    time_t lastActivityTimestamp;
    SessionState state;
};

typedef struct Node {
    struct Session session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned long idleTimeoutSeconds;
} SessionList;

SessionList* createSessionList(unsigned long idleTimeout) {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->idleTimeoutSeconds = idleTimeout;
    return list;
}

void destroySessionList(SessionList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addOrUpdateSession(SessionList* list, int sessionId, time_t lastActivityTimestamp) {
    pthread_mutex_lock(&list->lock);

    Node** curr = &list->head;
    while (*curr) {
        if ((*curr)->session.sessionId == sessionId) {
            (*curr)->session.lastActivityTimestamp = lastActivityTimestamp;
            goto unlock;
        }
        curr = &(*curr)->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->session.sessionId = sessionId;
    newNode->session.startTimestamp = time(NULL);
    newNode->session.lastActivityTimestamp = lastActivityTimestamp;
    newNode->session.state = ACTIVE;
    newNode->next = *curr;
    *curr = newNode;

unlock:
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void checkSessionExpirations(SessionList* list) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);
    Node** curr = &list->head;
    while (*curr) {
        Node* node = *curr;
        if (currentTime - node->session.lastActivityTimestamp > list->idleTimeoutSeconds) {
            node->session.state = EXPIRED;

            // Remove expired session from the list
            *curr = node->next;
            free(node);
        } else {
            curr = &node->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void updateSessionActivity(SessionList* list, int sessionId) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->session.sessionId == sessionId) {
            current->session.lastActivityTimestamp = currentTime;
            if (current->session.state != ACTIVE) {
                current->session.state = ACTIVE;
            }
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void printSessionList(SessionList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("Session ID: %d, State: %s\n", current->session.sessionId,
               current->session.state == ACTIVE ? "ACTIVE" :
               current->session.state == INACTIVE ? "INACTIVE" : "EXPIRED");
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    unsigned long idleTimeout = 300; // 5 minutes
    SessionList* sessionList = createSessionList(idleTimeout);

    addOrUpdateSession(sessionList, 1, time(NULL) - 100);
    addOrUpdateSession(sessionList, 2, time(NULL));
    updateSessionActivity(sessionList, 1);

    printf("Before expiration check:\n");
    printSessionList(sessionList);

    checkSessionExpirations(sessionList);

    printf("\nAfter expiration check:\n");
    printSessionList(sessionList);

    destroySessionList(sessionList);
    return 0;
}
