#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define MAX_ID_RANGE 10000

typedef struct {
    int identifier;
    long offset;
    int key;
} Record;

typedef struct {
    size_t record_size;
    size_t total_records;
    Record *records;
} MemoryManager;

int generate_unique_random(int *array, int array_size, int range) {
    if (range < array_size)
        return -1; // Not enough unique numbers possible

    for (int i = 0; i < array_size; i++) {
        int num;
        do {
            num = rand() % range;
        } while (bsearch(&num, array, i, sizeof(int), cmpfunc));

        array[i] = num;
    }
    return 0;
}

int cmpfunc(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

MemoryManager* init_memory_manager(size_t n) {
    if (n == 0)
        return NULL;

    MemoryManager *mm = malloc(sizeof(MemoryManager));
    if (!mm) {
        fprintf(stderr, "Failed to allocate memory for MemoryManager\n");
        exit(EXIT_FAILURE);
    }

    mm->record_size = sizeof(Record);
    mm->total_records = n;

    int identifiers[n];
    if (generate_unique_random(identifiers, n, MAX_ID_RANGE) != 0) {
        fprintf(stderr, "Failed to generate unique random identifiers\n");
        free(mm);
        return NULL;
    }

    size_t total_memory_size = mm->record_size * n;

    // Use anonymous mmap for memory allocation
    int fd = -1; // File descriptor not needed for anonymous mmap
    mm->records = (Record *)mmap(NULL, total_memory_size, PROT_READ | PROT_WRITE,
                                 MAP_PRIVATE | MAP_ANONYMOUS, fd, 0);

    if (mm->records == MAP_FAILED) {
        fprintf(stderr, "Memory mapping failed: %s\n", strerror(errno));
        free(mm);
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        mm->records[i].identifier = identifiers[i];
        mm->records[i].offset = rand() % 1000000; // Example offset
        mm->records[i].key = rand() % 10000;      // Example key
    }

    return mm;
}

void free_memory_manager(MemoryManager *mm) {
    if (!mm)
        return;

    if (munmap(mm->records, mm->record_size * mm->total_records) == -1) {
        fprintf(stderr, "Failed to unmap memory: %s\n", strerror(errno));
    }

    free(mm);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t n = 1000; // Example record count
    MemoryManager *mm = init_memory_manager(n);

    if (!mm) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return EXIT_FAILURE;
    }

    // Use the records here...

    free_memory_manager(mm);
    return EXIT_SUCCESS;
}
```

### Explanation:

- The code defines a `Record` structure that holds an identifier, offset, and key.
- A `MemoryManager` structure is used to manage these records in memory.
- `init_memory_manager` function initializes the `mmap` region for storing records. It generates unique random identifiers using `generate_unique_random`.
- Unique IDs are generated within a specified range without duplicates by leveraging binary search.
- The memory allocation strategy uses `mmap` with anonymous mapping to efficiently handle large blocks of memory.
- Error handling ensures that any failure in memory operations results in graceful termination, preventing segmentation faults.']

