['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000000

typedef struct {
    float timestamp;
    char status_indicator;
    char *message;
} log_entry_t;

typedef struct {
    log_entry_t *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    uint64_t next_free_index;
    uint64_t mask;
} logging_system_t;

logging_system_t* create_logging_system(size_t initial_capacity) {
    logging_system_t *system = malloc(sizeof(logging_system_t));
    system->entries = calloc(initial_capacity, sizeof(log_entry_t));
    system->count = 0;
    system->capacity = initial_capacity;
    pthread_mutex_init(&system->lock, NULL);
    system->next_free_index = 0;
    system->mask = initial_capacity - 1; // Power of two for circular buffer
    return system;
}

void log_entry_add(logging_system_t *system, float timestamp, char status_indicator, const char *message) {
    pthread_mutex_lock(&system->lock);

    size_t index = system->next_free_index & system->mask;
    log_entry_t *entry = &system->entries[index];

    entry->timestamp = timestamp;
    entry->status_indicator = status_indicator;

    if (entry->message != NULL) {
        free(entry->message);
    }
    entry->message = strdup(message);

    system->next_free_index++;

    pthread_mutex_unlock(&system->lock);
}

void log_entry_clear(logging_system_t *system) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->count; i++) {
        size_t index = (i + system->next_free_index - system->count) & system->mask;
        free(system->entries[index].message);
        memset(&system->entries[index], 0, sizeof(log_entry_t));
    }

    system->count = 0;

    pthread_mutex_unlock(&system->lock);
}

void destroy_logging_system(logging_system_t *system) {
    log_entry_clear(system);
    free(system->entries);
    pthread_mutex_destroy(&system->lock);
    free(system);
}
```

This code provides a basic structure for a high-performance logging system. The `log_entry_add` function safely adds entries to the circular buffer without locks on individual operations, leveraging the power of two capacity for efficient indexing. The destructor ensures proper resource cleanup. Further enhancements like compression and garbage collection can be built upon this foundation with careful design considerations for performance and scalability.']

