import random
import string

// Enum to represent status
typedef enum {
    FREE,
    IN_USE,
    RESERVED
} Status;

// Structure definition for item
typedef struct {
    double value;
    char* buffer;
    Status status;
} Item;

// Function prototypes
void initialize_buffers(Item *items, size_t count, const char **predefined_strs, int use_random);
void free_items(Item *items, size_t count);

// Main function to allocate and initialize items
Item* create_items(size_t item_count, size_t buffer_max_size, const char *filepath, const char **predefined_strs, int use_random) {
    // Calculate total buffer size needed for all items initially.
    size_t total_buffer_size = 0;

    // Open the file to read double values
    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening file.\n");
        return NULL;
    }

    // Read doubles from file and calculate unique set size
    off_t position = 0;
    double value;
    while (read(fd, &value, sizeof(double)) == sizeof(double)) {
        total_buffer_size += snprintf(NULL, 0, "%.2f", value) + 1; // +1 for null terminator
        if (total_buffer_size > buffer_max_size || item_count-- <= 0) break;
        position = lseek(fd, 0, SEEK_CUR);
    }

    // Check if we could read the expected number of unique doubles.
    if (item_count > 0) {
        fprintf(stderr, "Not enough unique values in file.\n");
        close(fd);
        return NULL;
    }

    // Adjust buffer size to fit within max constraints
    total_buffer_size = buffer_max_size;

    // Calculate memory needed for items and buffers
    size_t item_struct_size = sizeof(Item) * item_count;
    size_t mmap_size = item_struct_size + total_buffer_size;

    // Map the required memory using mmap
    void* addr = mmap(NULL, mmap_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (addr == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return NULL;
    }

    // Initialize items array from the mapped memory
    Item* items = (Item*) addr;

    // Initialize floating-point numbers and allocate buffers
    lseek(fd, 0, SEEK_SET);  // Reset file descriptor to start reading again

    size_t current_buffer_pos = item_struct_size;
    for (size_t i = 0; i < item_count; ++i) {
        if (read(fd, &items[i].value, sizeof(double)) == sizeof(double)) {
            size_t buffer_length = snprintf(NULL, 0, "%.2f", items[i].value) + 1;
            if (buffer_length > total_buffer_size - current_buffer_pos) {
                fprintf(stderr, "Buffer size exceeded during initialization.\n");
                free_items(items, item_count);
                close(fd);
                munmap(addr, mmap_size);
                return NULL;
            }
            items[i].buffer = (char*)(addr + current_buffer_pos);
            snprintf(items[i].buffer, buffer_length, "%.2f", items[i].value);
            items[i].status = FREE; // Set default status
            current_buffer_pos += buffer_length;
        } else {
            fprintf(stderr, "Failed to read double value.\n");
            items[i].value = 0.0;  // Assign a default value in case of failure
            items[i].buffer = (char*)(addr + current_buffer_size);
            *items[i].buffer = '\0';
            items[i].status = FREE;
        }
    }

    close(fd);

    // Initialize buffers with predefined or random strings if required
    initialize_buffers(items, item_count, predefined_strs, use_random);

    return items;
}

// Function to initialize buffers with either random or predefined strings
void initialize_buffers(Item *items, size_t count, const char **predefined_strs, int use_random) {
    for (size_t i = 0; i < count; ++i) {
        if (use_random) {
            // Generate a random string and copy it into the buffer
            size_t str_len = rand() % 50 + 1;  // Length between 1 and 50
            char *random_str = malloc(str_len);
            for (size_t j = 0; j < str_len; ++j) {
                random_str[j] = string.ascii_letters[random.randint(0, len(string.ascii_letters) - 1)];
            }
            snprintf(items[i].buffer, sizeof(items[i].buffer), "%s", random_str);
            free(random_str);
        } else if (predefined_strs != NULL && predefined_strs[i] != NULL) {
            // Copy the predefined string into the buffer
            snprintf(items[i].buffer, sizeof(items[i].buffer), "%s", predefined_strs[i]);
        }
    }
}

// Function to release all resources and deallocate memory
void free_items(Item *items, size_t count) {
    munmap((void *) items, (sizeof(Item) * count) + /* calculate buffer size from usage */);
}
