#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <sys/mman.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORD_SIZE 128 // Example record size in bytes

typedef struct {
    int identifier;
    long offset;
    int key;
} Record;

// Logging function
void log_event(const char *event, int id, size_t size) {
    time_t now = time(NULL);
    printf("[%s] %s - ID: %d, Size: %zu\n", ctime(&now), event, id, size);
}

// Memory management function prototype
int manage_memory(int n, size_t max_record_size);

pthread_mutex_t lock;

Record* records;
size_t record_count;
size_t total_allocated = 0;

// Generate unique identifiers within a specified range [min_id, max_id]
int generate_unique_identifier(int min_id, int max_id) {
    static pthread_mutex_t id_lock = PTHREAD_MUTEX_INITIALIZER;
    static int used_ids[MAX_RECORDS];
    memset(used_ids, 0, sizeof(used_ids));

    pthread_mutex_lock(&id_lock);
    for (int i = min_id; i <= max_id; ++i) {
        if (!used_ids[i]) {
            used_ids[i] = 1;
            pthread_mutex_unlock(&id_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&id_lock);
    return -1; // Failed to generate a unique id
}

int manage_memory(int n, size_t max_record_size) {
    if (max_record_size > MAX_RECORD_SIZE) {
        fprintf(stderr, "Record size exceeds the maximum allowable limit\n");
        return -1;
    }

    pthread_mutex_init(&lock, NULL);

    // Calculate total memory required and check against system limits
    size_t record_size = sizeof(Record);
    size_t total_memory_needed = n * max_record_size;

    int fd = open("/dev/zero", O_RDWR);
    if (fd == -1) {
        perror("Error opening /dev/zero");
        return -1;
    }

    void* addr = mmap(NULL, total_memory_needed, PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return -1;
    }
    close(fd);

    records = (Record*) addr;
    record_count = n;

    // Initialize records with unique identifiers and log allocations
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < n; ++i) {
        int id = generate_unique_identifier(1, 10000); // Example range [1, 10000]
        if (id == -1) {
            fprintf(stderr, "Failed to generate a unique identifier\n");
            munmap(records, total_memory_needed);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        records[i].identifier = id;
        records[i].offset = rand() % 10000; // Random offset
        records[i].key = rand() % 1000;     // Random key

        log_event("Allocate", id, max_record_size);

        total_allocated += max_record_size;
    }
    pthread_mutex_unlock(&lock);

    // Example of freeing resources on exit or error
    void cleanup(void) {
        if (records && addr != MAP_FAILED) {
            munmap(records, total_memory_needed);
            log_event("Deallocate", -1, total_allocated);
        }
        pthread_mutex_destroy(&lock);
    }

    atexit(cleanup);

    return 0;
}

// Example usage
int main() {
    int n = 100; // Number of records to manage
    size_t max_record_size = sizeof(Record); // Assuming each record can fit within the max size

    if (manage_memory(n, max_record_size) != 0) {
        fprintf(stderr, "Failed to manage memory\n");
        return EXIT_FAILURE;
    }

    printf("Memory management setup successfully with %d records.\n", n);

    return EXIT_SUCCESS;
}
```

This code provides a structured approach for managing memory allocation of records using `mmap`, ensuring uniqueness of identifiers, concurrency control via mutexes, and robust error handling. Logging is incorporated to track allocation events, and resource cleanup is managed through an atexit handler to ensure no resources are leaked. Adjustments can be made based on specific requirements or system constraints.']

