#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    int value;
    char *str;
} record;

#define LOG_FILE "memory_log.txt"
#define CONFIG_FILE "config.cfg"

typedef struct CacheNode {
    record *rec;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t max_size;
    size_t current_size;
} LRUCache;

// Function prototypes
void log_memory_operation(const char *operation, void *ptr, size_t size);
bool read_config(int *range_min, int *range_max, int *max_cache_size, int *max_str_len);
LRUCache* create_cache(size_t max_size);
record* fetch_from_cache(LRUCACHE *cache, size_t index, size_t count);
void return_to_cache(LRUCACHE *cache, record *rec);
void free_cache(LRUCache *cache);

// Main function
record **allocate_and_initialize(int ***offsets, int **keys, record ***records_2d, size_t *total_records) {
    int range_min = 0, range_max = 100, max_cache_size = 10, max_str_len = 50;
    if (!read_config(&range_min, &range_max, &max_cache_size, &max_str_len)) {
        fprintf(stderr, "Failed to read configuration.\n");
        return NULL;
    }

    *total_records = 0;

    size_t offsets_count = 5; // Example count
    *offsets = malloc(offsets_count * sizeof(long));
    if (*offsets == NULL) {
        log_memory_operation("alloc", *offsets, offsets_count * sizeof(long));
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return NULL;
    }
    for (size_t i = 0; i < offsets_count; ++i) {
        (*offsets)[i] = rand() % range_max;
    }

    size_t keys_count = 5; // Example count
    *keys = malloc(keys_count * sizeof(int));
    if (*keys == NULL) {
        log_memory_operation("alloc", *keys, keys_count * sizeof(int));
        free(*offsets);
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        return NULL;
    }
    for (size_t i = 0; i < keys_count; ++i) {
        (*keys)[i] = rand() % range_max;
    }

    LRUCache *cache = create_cache(max_cache_size);

    size_t max_sub_array_length = 10; // Example value
    *records_2d = malloc(keys_count * sizeof(record *));
    if (*records_2d == NULL) {
        log_memory_operation("alloc", *records_2d, keys_count * sizeof(record *));
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Failed to allocate memory for records 2D array.\n");
        return NULL;
    }

    for (size_t i = 0; i < keys_count; ++i) {
        size_t sub_array_length = (*keys)[i] % max_sub_array_length + 1;
        if (sub_array_length == 0) continue;

        record *recs = fetch_from_cache(cache, sub_array_length, sizeof(record));
        if (!recs) {
            recs = malloc(sub_array_length * sizeof(record));
            if (recs == NULL) {
                log_memory_operation("alloc", recs, sub_array_length * sizeof(record));
                for (size_t j = 0; j < i; ++j) free((*records_2d)[j]);
                free(*offsets);
                free(*keys);
                free(*records_2d);
                fprintf(stderr, "Failed to allocate memory for records.\n");
                return NULL;
            }
        }

        (*records_2d)[i] = recs;

        for (size_t j = 0; j < sub_array_length; ++j) {
            recs[j].value = rand() % range_max;
            char *str = malloc(max_str_len);
            if (str == NULL) {
                log_memory_operation("alloc", str, max_str_len);
                free(recs); // Free the whole array
                for (size_t k = 0; k < i; ++k) free((*records_2d)[k]);
                free(*offsets);
                free(*keys);
                free(*records_2d);
                fprintf(stderr, "Failed to allocate memory for string.\n");
                return NULL;
            }
            snprintf(str, max_str_len, "Record %zu-%zu", i, j);
            recs[j].str = str;

            (*total_records)++;
        }

        return_to_cache(cache, recs);
    }

    free_cache(cache);

    log_memory_operation("dealloc", *offsets, offsets_count * sizeof(long));
    log_memory_operation("dealloc", *keys, keys_count * sizeof(int));
    for (size_t i = 0; i < keys_count; ++i) {
        size_t sub_array_length = (*keys)[i] % max_sub_array_length + 1;
        if (sub_array_length == 0) continue;

        log_memory_operation("dealloc", (*records_2d)[i], sub_array_length * sizeof(record));
    }

    return *records_2d;
}

// Supporting functions
void log_memory_operation(const char *operation, void *ptr, size_t size) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %p - %zu bytes\n", operation, ptr, size);
        fclose(log_file);
    }
}

bool read_config(int *range_min, int *range_max, int *max_cache_size, int *max_str_len) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) return false;

    fscanf(file, "%d %d %d %d", range_min, range_max, max_cache_size, max_str_len);
    fclose(file);

    if (*range_min >= *range_max || *max_cache_size <= 0 || *max_str_len <= 0)
        return false;

    return true;
}

LRUCache* create_cache(size_t max_size) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->max_size = max_size;
    cache->current_size = 0;
    return cache;
}

record* fetch_from_cache(LRUCache *cache, size_t index, size_t count) {
    // Simplified LRU fetching logic
    if (cache->head == NULL || cache->current_size < cache->max_size) {
        record *rec = malloc(count);
        log_memory_operation("alloc", rec, count);
        return rec;
    }
    return NULL; // Cache full, no room to allocate new
}

void return_to_cache(LRUCache *cache, record *rec) {
    // Simplified LRU insertion logic
    if (cache->current_size < cache->max_size) {
        CacheNode *node = malloc(sizeof(CacheNode));
        node->rec = rec;
        node->prev = NULL;
        node->next = cache->head;

        if (cache->head != NULL)
            cache->head->prev = node;

        cache->head = node;
        if (cache->tail == NULL)
            cache->tail = node;

        cache->current_size++;
    } else {
        // Evict LRU
        CacheNode *node = cache->tail;
        cache->tail = node->prev;
        if (cache->tail != NULL)
            cache->tail->next = NULL;

        free(node);
        return_to_cache(cache, rec); // Add new node to head
    }
}

void free_cache(LRUCache *cache) {
    while (cache->head != NULL) {
        CacheNode *node = cache->head;
        cache->head = node->next;
        free(node->rec);
        free(node);
    }
    free(cache);
}
