// Function to dynamically allocate and initialize an entry
Entry* create_entry(double d, const char *s, float f, bool b, unsigned int i) {
    if (strlen(s) >= 256) {
        fprintf(stderr, "Error: String exceeds maximum length.\n");
        return NULL;
    }

    Entry *entry = (Entry *)malloc(sizeof(Entry));
    if (!entry) {
        fprintf(stderr, "Error: Memory allocation failed for entry.\n");
        return NULL;
    }

    entry->doubleValue = d;
    strncpy(entry->stringValue, s, 255);
    entry->stringValue[255] = '\0'; // Ensure null termination

    entry->customData.floatValue = f;
    entry->customData.boolValue = b;
    entry->customData.intValue = i;

    return entry;
}

// Function to free the allocated entry
void free_entry(Entry *entry) {
    if (entry) {
        free(entry);
    }
}

// Function to log memory usage and allocation status
void log_memory_usage(size_t total_allocations, size_t current_allocation) {
    printf("Total Allocations: %zu\n", total_allocations);
    printf("Current Allocation Size: %zu bytes\n", current_allocation * sizeof(Entry));
}

