#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>

#define MAX_NETWORK_ATTEMPTS 3

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t offset_size, key_size, record_size;
    pthread_mutex_t lock;
} DataPool;

// Function prototypes
DataPool* create_data_pool(size_t offset_size, size_t key_size, size_t record_size);
void free_data_pool(DataPool* pool);
int resize_data_pool(DataPool* pool, size_t new_offset_size, size_t new_key_size, size_t new_record_size);
int load_data_from_network(DataPool* pool, const char *source_url);

// Initialize data pool
DataPool* create_data_pool(size_t offset_size, size_t key_size, size_t record_size) {
    DataPool* pool = (DataPool*)malloc(sizeof(DataPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->offsets = malloc(offset_size * sizeof(long));
    pool->keys = malloc(key_size * sizeof(int));
    pool->records = malloc(record_size * sizeof(Record));

    pool->offset_size = offset_size;
    pool->key_size = key_size;
    pool->record_size = record_size;

    if (!pool->offsets || !pool->keys || !pool->records) {
        free_data_pool(pool);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < record_size; ++i) {
        int value;
        do {
            value = rand() % 100; // Assuming range [0, 99]
        } while (i > 0 && pool->records[i-1].value == value);

        pool->records[i].value = value;
    }

    return pool;
}

// Free data pool
void free_data_pool(DataPool* pool) {
    if (!pool) return;

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Resize the data arrays in the data pool
int resize_data_pool(DataPool* pool, size_t new_offset_size, size_t new_key_size, size_t new_record_size) {
    if (!pool) return -1;

    pthread_mutex_lock(&pool->lock);

    long *new_offsets = realloc(pool->offsets, new_offset_size * sizeof(long));
    int *new_keys = realloc(pool->keys, new_key_size * sizeof(int));
    Record *new_records = realloc(pool->records, new_record_size * sizeof(Record));

    if (!new_offsets || !new_keys || !new_records) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;

    for (size_t i = pool->record_size; i < new_record_size; ++i) {
        int value;
        do {
            value = rand() % 100; // Assuming range [0, 99]
        } while (i > 0 && pool->records[i-1].value == value);

        pool->records[i].value = value;
    }

    pool->offset_size = new_offset_size;
    pool->key_size = new_key_size;
    pool->record_size = new_record_size;

    pthread_mutex_unlock(&pool->lock);

    return 0;
}

// Simulate network data loading with error handling
int load_data_from_network(DataPool* pool, const char *source_url) {
    if (!pool || !source_url) return -1;

    for (int attempt = 0; attempt < MAX_NETWORK_ATTEMPTS; ++attempt) {
        // Simulated network operation
        int result = rand() % 2; // Randomly simulate success/failure

        if (result == 0) { // Success case
            pthread_mutex_lock(&pool->lock);
            printf("Data loaded from network: %s\n", source_url);
            pthread_mutex_unlock(&pool->lock);

            return 0;
        } else {
            sleep(1); // Simulate retry delay
        }
    }

    perror("Failed to load data from network");
    return -1;
}

// Reset the state of a DataPool
void reset_data_pool(DataPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    memset(pool->offsets, 0, pool->offset_size * sizeof(long));
    memset(pool->keys, 0, pool->key_size * sizeof(int));

    for (size_t i = 0; i < pool->record_size; ++i) {
        int value;
        do {
            value = rand() % 100; // Assuming range [0, 99]
        } while (i > 0 && pool->records[i-1].value == value);

        pool->records[i].value = value;
    }

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    DataPool* pool = create_data_pool(10, 10, 10);
    if (!pool) {
        fprintf(stderr, "Failed to initialize data pool\n");
        return EXIT_FAILURE;
    }

    if (load_data_from_network(pool, "http://example.com/data")) {
        fprintf(stderr, "Network loading failed\n");
    }

    resize_data_pool(pool, 20, 20, 20);
    reset_data_pool(pool);

    free_data_pool(pool);

    return EXIT_SUCCESS;
}
```

This code sets up a data management structure in C with features to handle dynamic memory allocation, random initialization of records, network data loading with error handling, and thread-safe resizing. It uses mutexes for synchronization to ensure thread safety when accessing shared resources.']

