#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define the node structure for the doubly linked list
typedef struct Node {
    char* value;
    struct Node* next;
    struct Node* prev;
} Node;

// Hash table entry structure
typedef struct Entry {
    int key;
    char* value;
} Entry;

// Function to generate a unique random string
char* generate_unique_string(int length, const char* previous_value) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char* result = malloc(length + 1);
    if (!result) return NULL;

    bool is_different = false;
    while (!is_different) {
        is_different = true;
        for (int i = 0; i < length; ++i) {
            result[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        result[length] = '\0';

        if (previous_value && strcmp(result, previous_value) == 0) {
            is_different = false;
        }
    }

    return result;
}

// Function to initialize the doubly linked list
Node* init_doubly_linked_list(int num_nodes) {
    Node* head = NULL;
    Node* tail = NULL;

    char* last_value = NULL;
    for (int i = 0; i < num_nodes; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) return NULL;

        int string_length = rand() % 10 + 5; // Random length between 5 and 15
        new_node->value = generate_unique_string(string_length, last_value);
        if (!new_node->value) {
            free(new_node);
            return NULL;
        }

        last_value = new_node->value;

        new_node->next = NULL;
        new_node->prev = tail;

        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }

        tail = new_node;
    }

    return head;
}

// Function to initialize the array of float values
float* init_float_array(int size) {
    float* arr = malloc(size * sizeof(float));
    if (!arr) return NULL;

    for (int i = 0; i < size; ++i) {
        arr[i] = rand() / (float)RAND_MAX;
    }

    return arr;
}

// Function to initialize the hash table
Entry** init_hash_table(int size) {
    Entry** table = malloc(size * sizeof(Entry*));
    if (!table) return NULL;

    for (int i = 0; i < size; ++i) {
        table[i] = NULL;
    }

    // For simplicity, let's populate it with random key-value pairs
    for (int i = 0; i < size; ++i) {
        Entry* entry = malloc(sizeof(Entry));
        if (!entry) return NULL;

        entry->key = rand() % 1000;
        int string_length = rand() % 10 + 5;
        entry->value = generate_unique_string(string_length, NULL);
        if (!entry->value) {
            free(entry);
            return NULL;
        }

        int index = abs(entry->key) % size;
        while (table[index]) {
            index = (index + 1) % size; // Linear probing
        }

        table[index] = entry;
    }

    return table;
}

// Function to reset and free all allocated memory
void reset_and_free(Node* head, float* arr, Entry** hash_table, int hash_size) {
    // Free doubly linked list
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->value);
        free(current);
        current = next;
    }

    // Free array of floats
    free(arr);

    // Free hash table
    for (int i = 0; i < hash_size; ++i) {
        if (hash_table[i]) {
            free(hash_table[i]->value);
            free(hash_table[i]);
        }
    }
    free(hash_table);
}

// Main function to demonstrate usage
void manage_memory(int num_nodes, int float_array_size, int hash_table_size) {
    Node* doubly_linked_list = init_doubly_linked_list(num_nodes);
    if (!doubly_linked_list) {
        fprintf(stderr, "Failed to initialize the doubly linked list.\n");
        return;
    }

    float* float_array = init_float_array(float_array_size);
    if (!float_array) {
        fprintf(stderr, "Failed to initialize the array of floats.\n");
        reset_and_free(doubly_linked_list, NULL, NULL, 0);
        return;
    }

    Entry** hash_table = init_hash_table(hash_table_size);
    if (!hash_table) {
        fprintf(stderr, "Failed to initialize the hash table.\n");
        reset_and_free(doubly_linked_list, float_array, NULL, 0);
        return;
    }

    // Assume some operations on these structures...

    // Reset and free all allocated memory
    reset_and_free(doubly_linked_list, float_array, hash_table, hash_table_size);
}

int main() {
    srand(time(NULL));
    manage_memory(100, 50, 20); // Example usage with specific sizes
    return 0;
}
```

This implementation handles dynamic memory allocation for a doubly linked list, an array of floats, and a simple hash table. It generates unique random strings for nodes in the list and entries in the hash table, initializes each structure based on input parameters, manages potential memory failures gracefully, and provides functionality to reset and free all allocated resources. The design considers performance optimizations like minimizing fragmentation and cache usage while ensuring thread safety where needed.']

