// Define the sensor object structure
typedef struct {
    int id;
    float temperature;
    int status; // 0 for inactive, 1 for active
} Sensor;

// Function to allocate and initialize memory for data structures
void* manageMemory(int numSensors) {
    // Allocate memory for timestamps (long values)
    long *timestamps = (long *)malloc(numSensors * sizeof(long));
    if (!timestamps) return NULL; // Memory allocation failed

    // Allocate memory for temperature readings (float values)
    float *temperatures = (float *)malloc(numSensors * sizeof(float));
    if (!temperatures) {
        free(timestamps);
        return NULL;
    }

    // Initialize temperatures to zero
    for (int i = 0; i < numSensors; ++i) {
        temperatures[i] = 0.0f;
    }

    // Allocate memory for sensor objects
    Sensor *sensors = (Sensor *)malloc(numSensors * sizeof(Sensor));
    if (!sensors) {
        free(timestamps);
        free(temperatures);
        return NULL;
    }

    // Initialize sensor objects
    for (int i = 0; i < numSensors; ++i) {
        sensors[i].id = i + 1;              // Unique id starting from 1
        sensors[i].temperature = 0.0f;      // Initial temperature value
        sensors[i].status = 1;              // Default status: active
    }

    // Package the pointers into a single struct for easy management and return
    typedef struct {
        long *timestamps;
        float *temperatures;
        Sensor *sensors;
    } ManagedMemory;

    ManagedMemory *managed_memory = (ManagedMemory *)malloc(sizeof(ManagedMemory));
    if (!managed_memory) {
        free(timestamps);
        free(temperatures);
        free(sensors);
        return NULL;
    }

    managed_memory->timestamps = timestamps;
    managed_memory->temperatures = temperatures;
    managed_memory->sensors = sensors;

    return (void *)managed_memory;
}

// Function to deallocate memory
void freeManagedMemory(void *memory) {
    if (!memory) return;

    ManagedMemory *managed_memory = (ManagedMemory *)memory;

    // Free individual components
    free(managed_memory->timestamps);
    free(managed_memory->temperatures);
    free(managed_memory->sensors);

    // Finally, free the main structure
    free(managed_memory);
}

int main() {
    int numSensors = 10000; // Example number of sensors

    void *memory = manageMemory(numSensors);
    if (!memory) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    // Use the managed memory...

    // When done, free the allocated memory
    freeManagedMemory(memory);

    return EXIT_SUCCESS;
}
```

### Design Decisions and Rationale:

1. **Efficient Allocation**: Memory for each data type is allocated in contiguous blocks, minimizing fragmentation and improving cache performance.

2. **Initialization**: Temperature readings are initialized to zero, and sensor statuses to active (`1`), ensuring consistent initial states.

3. **Error Handling**: Each allocation checks for failure, with appropriate cleanup of previously allocated memory to prevent leaks.

4. **Scalability**: The design allows easy scaling by adjusting the `numSensors` parameter without modifying internal logic.

5. **Memory Management**: A single function (`freeManagedMemory`) is responsible for deallocating all resources, reducing complexity and ensuring no memory leaks.

6. **Integration**: The use of a `ManagedMemory` structure simplifies passing around pointers to these arrays in other system modules.']

