def process_log_file(file_path, output_file, api_url, filters=None):
    lock = Lock()

    def handle_compression(file_path):
        if file_path.endswith('.gz'):
            return gzip.open(file_path, 'rt')
        else:
            return open(file_path, 'r')

    def chunked_read(file_obj, buffer_size=1024*1024):
        while True:
            data = file_obj.read(buffer_size)
            if not data:
                break
            yield data

    def process_chunk(chunk, results):
        lines = chunk.strip().split('\n')
        for line in lines:
            parts = line.split(',')
            if len(parts) != 3:
                logging.warning(f"Malformed line: {line}")
                continue

            timestamp, uid, seq_num = parts
            # Apply filtering logic here
            if filters and not (filters['start_date'] <= timestamp <= filters['end_date']):
                continue

            with lock:
                results.append((uid, int(seq_num), timestamp))

    def sort_and_verify(results):
        sorted_results = sorted(results, key=lambda x: (-x[1], x[2]))

        # Implement checksum verification here if needed
        return sorted_results

    def write_output(sorted_data, output_file):
        with open(output_file, 'w') as out_f:
            for uid, seq_num, timestamp in sorted_data:
                out_f.write(f"{timestamp},{uid},{seq_num}\n")

    def notify_api_completion(api_url, total_events, latest_seq_number):
        try:
            payload = {
                "total_events": total_events,
                "latest_sequence_number": latest_seq_number
            }
            response = requests.post(api_url, json=payload)
            response.raise_for_status()
        except requests.RequestException as e:
            logging.error(f"API request failed: {e}")

    try:
        with handle_compression(file_path) as file_obj:
            results = []
            for chunk in chunked_read(file_obj):
                process_chunk(chunk, results)

        sorted_results = sort_and_verify(results)

        if sorted_results:
            write_output(sorted_results, output_file)

            latest_seq_number = max([result[1] for result in sorted_results])
            notify_api_completion(api_url, len(sorted_results), latest_seq_number)
    except Exception as e:
        logging.error(f"Error processing file: {e}")

# Example usage
