// Record structure with minimal memory overhead and packed layout
typedef struct {
    int key;          // 4 bytes
    float precision;  // 4 bytes, tightly packed
    long offset;      // 8 bytes
} record_t;

// Initialize arrays with efficient allocation strategy
record_t* initialize_arrays(size_t count) {
    if (count <= 0) return NULL;

    record_t *records = malloc(count * sizeof(record_t));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    memset(records, 0, count * sizeof(record_t)); // Zero-initialize
    return records;
}

// Populate int fields with random values within a specified range
void populate_keys(record_t *records, size_t count, int min_val, int max_val) {
    if (!records || count == 0) return;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        records[i].key = min_val + rand() % ((max_val - min_val) + 1);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
}

// Thread-safe cleanup of allocated memory
void cleanup_arrays(record_t *records) {
    if (records) {
        free(records);
        records = NULL;
    }
}

// Logging system with configurable verbosity levels
typedef enum { LOG_ERROR, LOG_INFO, LOG_DEBUG } log_level_t;

void log_message(log_level_t level, const char* message) {
    static log_level_t current_log_level = LOG_INFO; // Configurable

    if (level > current_log_level) return;

    switch (level) {
        case LOG_ERROR:
            fprintf(stderr, "ERROR: %s\n", message);
            break;
        case LOG_INFO:
            printf("INFO: %s\n", message);
            break;
        case LOG_DEBUG:
            printf("DEBUG: %s\n", message);
            break;
    }
}

// Example function showcasing initialization and population
void example_usage(size_t count, int min_val, int max_val) {
    log_message(LOG_INFO, "Initializing arrays...");
    record_t *records = initialize_arrays(count);

    if (!records) {
        log_message(LOG_ERROR, "Initialization failed.");
        return;
    }

    populate_keys(records, count, min_val, max_val);
    log_message(LOG_DEBUG, "Keys populated successfully.");

    cleanup_arrays(records);
    log_message(LOG_INFO, "Memory cleaned up successfully.");
}

int main() {
    size_t record_count = 1000;
    int key_min = -100, key_max = 100;

    example_usage(record_count, key_min, key_max);

    return 0;
}
