// Thread-safe memory manager structure
typedef struct {
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
} MemoryManager;

// Function to initialize the memory manager
MemoryManager* init_memory_manager(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    MemoryManager* mm = malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    pthread_mutex_init(&mm->lock, NULL);
    mm->capacity = initial_capacity;
    mm->offsets = malloc(initial_capacity * sizeof(long));
    mm->keys = malloc(initial_capacity * sizeof(int));
    mm->records = malloc(initial_capacity * sizeof(record*));

    if (!mm->offsets || !mm->keys || !mm->records) {
        free(mm->offsets);
        free(mm->keys);
        free(mm->records);
        free(mm);
        return NULL;
    }

    return mm;
}

// Function to reallocate memory for the manager
int resize_memory_manager(MemoryManager* mm, size_t new_capacity) {
    if (!mm || new_capacity == 0) return -1;

    long* new_offsets = realloc(mm->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(mm->keys, new_capacity * sizeof(int));
    record** new_records = realloc(mm->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return -1;
    }

    mm->offsets = new_offsets;
    mm->keys = new_keys;
    mm->records = new_records;
    mm->capacity = new_capacity;

    return 0;
}

// Function to add a new entry
int add_entry(MemoryManager* mm, int key, long offset, record* rec) {
    if (!mm || !rec) return -1;

    pthread_mutex_lock(&mm->lock);

    // Resize if necessary
    if (mm->capacity == 0) {
        if (resize_memory_manager(mm, 10) != 0) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }
    } else if (mm->capacity == sizeof(long)) {
        if (resize_memory_manager(mm, mm->capacity * 2) != 0) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }
    }

    // Add the new entry
    size_t index = mm->capacity - 1;  // Assuming it's always added to the last position
    mm->offsets[index] = offset;
    mm->keys[index] = key;
