    int id;                // Unique identifier for the sensor
    float temperature;     // Temperature reading
    int status;            // Status flag (default initialized)
} Sensor;

// Function to allocate and initialize memory for the data structures.
void* manage_sensor_data(int num_sensors) {
    if (num_sensors <= 0) return NULL;

    // Allocate memory for timestamps, temperatures, and sensors.
    long *timestamps = (long *)malloc(num_sensors * sizeof(long));
    float *temperatures = (float *)calloc(num_sensors, sizeof(float)); // Initializes to zero
    Sensor *sensors = (Sensor *)malloc(num_sensors * sizeof(Sensor));

    if (!timestamps || !temperatures || !sensors) {
        free(timestamps);
        free(temperatures);
        free(sensors);
        return NULL;
    }

    // Initialize sensor data.
    for (int i = 0; i < num_sensors; ++i) {
        sensors[i].id = i + 1;          // Unique ID, starting from 1
        sensors[i].temperature = temperatures[i]; // Already zero-initialized
        sensors[i].status = DEFAULT_STATUS;
    }

    // Return a struct containing all allocated data pointers.
    typedef struct {
        long *timestamps;
        float *temperatures;
        Sensor *sensors;
    } DataStructures;

    DataStructures *data = (DataStructures *)malloc(sizeof(DataStructures));
    if (!data) {
        free(timestamps);
        free(temperatures);
        free(sensors);
        return NULL;
    }

    data->timestamps = timestamps;
    data->temperatures = temperatures;
    data->sensors = sensors;

    // Return the pointer to the DataStructures object containing all allocated memory.
    return (void *)data;
}

// Function to deallocate memory for the sensor data structures.
void free_sensor_data(void *data) {
    if (!data) return;

    // Cast back to our DataStructures struct
    typedef struct {
        long *timestamps;
        float *temperatures;
        Sensor *sensors;
    } DataStructures;

    DataStructures *sensorData = (DataStructures *)data;

    // Free allocated memory.
    free(sensorData->timestamps);
    free(sensorData->temperatures);
    free(sensorData->sensors);

    // Finally, free the struct itself
    free(sensorData);
}

int main() {
    int num_sensors = 10000;
    void *sensor_data = manage_sensor_data(num_sensors);

    if (sensor_data) {
        // Use sensor data...

        // Once done with using the data:
        free_sensor_data(sensor_data);
    } else {
        fprintf(stderr, "Failed to allocate memory for sensor data.\n");
    }

    return 0;
}
```

### Design Decisions Explained:

1. **System Dependencies**: Memory allocation is straightforward and designed to be minimalistic in latency by avoiding complex initializations.

2. **Performance Constraints**: 
   - `calloc` is used for temperature arrays to initialize them efficiently to zero.
   - Allocation for timestamps, temperatures, and sensors are handled separately to reduce potential cache misses.

3. **Scalability**:
   - The function supports easy scaling by adjusting the `num_sensors` parameter.
   - Memory allocation strategies allow for future hardware upgrades and larger datasets.

4. **Integration Issues**: 
   - Returned data is encapsulated in a struct, ensuring that all required pointers are available as one unit.
   - Robust error handling ensures memory deallocation on failure to allocate any of the components.

5. **Resource Management**:
   - All allocations are checked for success and cleaned up if any allocation fails to prevent leaks.
   - Memory is freed in a structured manner to maintain system stability over time, reducing fragmentation risks by deallocating all resources together.

These decisions balance efficiency with robustness and scalability, preparing the function for integration into larger systems.']

