pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
Record **cache = NULL;
int cache_size = 0;
int cache_capacity = MAX_CACHE_SIZE;

// Logging function placeholder
void log_error(const char *message) {
    // Implement your logging mechanism here
