}

char* get_current_timestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char buffer[26];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return strdup(buffer); // Dynamically allocate string
}

void increment_ref_count(Timestamp *ts) {
    pthread_mutex_lock(&cache_lock);
    ts->ref_count++;
    pthread_mutex_unlock(&cache_lock);
}

Record* get_from_cache(int key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; ++i) {
        if (cache[i]->key == key) {
            // Move accessed item to the end of the list
            Record *temp = cache[i];
            memmove(cache + i, cache + i + 1, (cache_size - i - 1) * sizeof(Record*));
            cache[cache_size - 1] = temp;
            pthread_mutex_unlock(&cache_lock);
            return temp;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void add_to_cache(Record *rec) {
    if (cache_capacity == 0) return;

    pthread_mutex_lock(&cache_lock);
    if (cache_size < cache_capacity) {
        cache[cache_size++] = rec;
    } else {
        // Evict the least recently used item
        free(cache[0]);
        memmove(cache, cache + 1, (cache_size - 1) * sizeof(Record*));
        cache[--cache_size] = rec;
    }
    pthread_mutex_unlock(&cache_lock);
}

Record* create_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) return NULL;

    Record **records = malloc(num_records * sizeof(Record*));
    if (!records) {
        log_error("Memory allocation failed for records array");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            log_error("Memory allocation failed for a record");
            // Free previously allocated records
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }

        // Initialize fields
        records[i]->offset = 0;
        records[i]->key = i; // or another logic to set key
        records[i]->value_record.value = rand() % (max_value - min_value + 1) + min_value;

        for (int j = 0; j < BUFFER_SIZE; ++j) {
            records[i]->buffer[j] = (j % 2 == 0) ? 'A' : 'B';
        }

        char *ts_str = get_current_timestamp();
        if (!ts_str) {
            log_error("Memory allocation failed for timestamp string");
            free(records[i]);
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }

        Timestamp *ts = malloc(sizeof(Timestamp));
        if (!ts) {
            log_error("Memory allocation failed for timestamp struct");
            free(ts_str);
            free(records[i]);
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }
        ts->data = ts_str;
        ts->ref_count = 1;

        records[i]->timestamp = ts;

        // Check cache and update it
        Record *cached_rec = get_from_cache(i);
        if (!cached_rec) {
            add_to_cache(records[i]);
        } else {
            increment_ref_count(cached_rec->timestamp);
            free(records[i]); // Avoid memory leak
            records[i] = cached_rec;
        }
    }

    return records;
}

void free_records(Record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (!records[i]) continue;

        Timestamp *ts = records[i]->timestamp;
        if (--ts->ref_count == 0) {
            free(ts->data);
            free(ts);
        }
        free(records[i]);
    }
    free(records);
}

