#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <limits.h>
#include <errno.h>

typedef struct {
    int value;
    int key;
    long offset;
} record;

// Function to handle memory cleanup in case of error
void cleanup(long *offsets, size_t offset_count, int *keys, size_t key_count, record **records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (*records) free(*records);
}

// Logging function with different verbosity levels
void log_message(int level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

// Function to initialize arrays and record structures
record* initialize_records(size_t offset_count, size_t key_count, long min_offset, long max_offset,
                           int min_key_value, int max_key_value, int random_min, int random_max,
                           int verbosity_level) {

    if (offset_count == 0 || key_count == 0) {
        log_message(verbosity_level, "Zero-sized arrays provided.");
        return NULL;
    }

    long *offsets = malloc(offset_count * sizeof(long));
    int *keys = malloc(key_count * sizeof(int));

    if (!offsets || !keys) {
        cleanup(offsets, offset_count, keys, key_count, NULL);
        log_message(verbosity_level, "Memory allocation failed for offsets or keys.");
        return NULL;
    }

    // Validate and initialize offsets
    for (size_t i = 0; i < offset_count; ++i) {
        long offset = rand() % (max_offset - min_offset + 1) + min_offset;

        if (offset < min_offset || offset > max_offset) {
            cleanup(offsets, offset_count, keys, key_count, NULL);
            log_message(verbosity_level, "Offset validation failed.");
            return NULL;
        }
        offsets[i] = offset;
    }

    // Validate and initialize keys
    for (size_t i = 0; i < key_count; ++i) {
        int key = rand() % (max_key_value - min_key_value + 1) + min_key_value;

        if (key < min_key_value || key > max_key_value) {
            cleanup(offsets, offset_count, keys, key_count, NULL);
            log_message(verbosity_level, "Key validation failed.");
            return NULL;
        }
        keys[i] = key;
    }

    record *records = malloc(offset_count * sizeof(record));
    if (!records) {
        cleanup(offsets, offset_count, keys, key_count, &records);
        log_message(verbosity_level, "Memory allocation failed for records.");
        return NULL;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Lock for thread-safe operations
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Populate records with randomized values
    for (size_t i = 0; i < offset_count; ++i) {
        pthread_mutex_lock(&lock);

        records[i].offset = offsets[i];
        records[i].key = keys[i % key_count];
        records[i].value = rand() % (random_max - random_min + 1) + random_min;

        if (records[i].value < INT_MIN || records[i].value > INT_MAX) {
            log_message(verbosity_level, "Random value out of bounds.");
        }

        pthread_mutex_unlock(&lock);
    }

    log_message(verbosity_level, "Records initialized successfully.");

    return records;
}

// Function to free allocated memory
void cleanup_records(record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t offset_count = 1000;
    size_t key_count = 500;

    record *records = initialize_records(offset_count, key_count, 10L, 100000L, 1, 50, -10000, 10000, 2);

    if (records) {
        // Use records...

        cleanup_records(records);
    }

    return 0;
}
