bool is_prime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return false;
    }
    return true;
}

void generate_primes(int primes[], size_t count, int max_value) {
    size_t found = 0;
    for (int i = 2; found < count && i < max_value; ++i) {
        if (is_prime(i)) {
            primes[found++] = i;
        }
    }
}

void* generate_unique_offsets(void* arg) {
    size_t* offsets = (size_t*)arg;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < *offsets; ++i) {
        size_t new_offset;
        do {
            pthread_mutex_lock(&lock);
            new_offset = rand() % (*offsets + 1); // Assuming offset range is [0, offsets]
            pthread_mutex_unlock(&lock);

            bool unique = true;
            for (size_t j = 0; j < i; ++j) {
                if (new_offset == offsets[j]) {
                    unique = false;
                    break;
                }
            }

        } while (!unique);

        offsets[i] = new_offset;
    }

    pthread_mutex_destroy(&lock);
    return NULL;
}

void initialize_record_array(record* records, size_t count, int min_range, int max_range) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_range - min_range + 1) + min_range;
        snprintf(&(records[i].char_rep), sizeof(records[i].char_rep) + 1, "%d", records[i].value);
    }
}

void* memory_allocation_function(size_t count, int min_range, int max_range) {
    size_t *offsets = malloc(count * sizeof(size_t));
    int *keys = malloc(count * sizeof(int));
    record *records = malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, generate_unique_offsets, (void*)count);

    generate_primes(keys, count, 1000); // Prime numbers less than 1000

    initialize_record_array(records, count, min_range, max_range);

    pthread_join(thread_id, NULL);

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
