    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table* ht = malloc(sizeof(hash_table));
    if (!ht) return NULL;

    ht->capacity = initial_capacity;
    ht->size = 0;
    ht->buckets = calloc(ht->capacity, sizeof(hash_table_entry*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void destroy_hash_table(hash_table* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        hash_table_entry* entry = ht->buckets[i];
        while (entry) {
            hash_table_entry* next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

unsigned int hash_function(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

void insert_into_hash_table(hash_table* ht, int key, record rec) {
    unsigned int index = hash_function(key, ht->capacity);

    pthread_mutex_lock(&ht->lock);

    hash_table_entry* new_entry = malloc(sizeof(hash_table_entry));
    if (!new_entry) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    new_entry->key = key;
    new_entry->rec = rec;
    new_entry->next = ht->buckets[index];
    ht->buckets[index] = new_entry;

    ++ht->size;

    pthread_mutex_unlock(&ht->lock);
}

record* find_in_hash_table(hash_table* ht, int key) {
    unsigned int index = hash_function(key, ht->capacity);

    pthread_mutex_lock(&ht->lock);

    hash_table_entry* entry = ht->buckets[index];
    while (entry) {
        if (entry->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return &entry->rec;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t capacity;
    hash_table* ht;
} dynamic_collection;

dynamic_collection* create_dynamic_collection(size_t initial_capacity, int min_value, int max_value) {
    dynamic_collection* dc = malloc(sizeof(dynamic_collection));
    if (!dc) return NULL;

    srand(time(NULL));

    dc->offsets = calloc(initial_capacity, sizeof(long));
    dc->keys = calloc(initial_capacity, sizeof(int));
    dc->records = calloc(initial_capacity, sizeof(record));
    if (!dc->offsets || !dc->keys || !dc->records) {
        free(dc->offsets);
        free(dc->keys);
        free(dc->records);
        free(dc);
        return NULL;
    }

    dc->capacity = initial_capacity;
    for (size_t i = 0; i < initial_capacity; ++i) {
        dc->offsets[i] = i * 100; // Example offset calculation
        dc->keys[i] = rand() % 1000; // Random key example

        record* rec = &dc->records[i];
        rec->value = min_value + rand() % (max_value - min_value + 1);
        rec->offset_ptr = &dc->offsets[i];
        rec->key_ptr = &dc->keys[i];

        insert_into_hash_table(dc->ht, dc->keys[i], *rec);
    }

    return dc;
}

void destroy_dynamic_collection(dynamic_collection* dc) {
    free(dc->offsets);
    free(dc->keys);
    free(dc->records);
    destroy_hash_table(dc->ht);
    free(dc);
}

record* get_record_by_index(dynamic_collection* dc, size_t index) {
    if (index >= dc->capacity) return NULL;
    return &dc->records[index];
}

void update_record_value(dynamic_collection* dc, size_t index, int new_value) {
    if (index < dc->capacity) {
        record* rec = get_record_by_index(dc, index);
        if (rec) rec->value = new_value;
    }
}

void iterate_over_records(dynamic_collection* dc, void (*callback)(record*)) {
    for (size_t i = 0; i < dc->capacity; ++i) {
        callback(get_record_by_index(dc, i));
    }
}
```

This implementation includes:

- A dynamic collection with initialization and destruction logic.
- Memory allocation error handling.
- Insertion into a custom hash table for fast key-based lookups.
- Functions to retrieve and update records by index.
- Iteration over all records using a callback function.
- Thread safety is implemented using mutexes in the hash table operations.
- The code includes simple hash table management with linked lists for collision handling. It doesn't support dynamic resizing or other advanced features like custom memory management, but it provides a solid base to build upon.

To make this more robust and efficient, further work could include adding dynamic resizing of arrays and hash tables, improving the hash function, and potentially using more advanced synchronization techniques depending on concurrency requirements."]

