#include <time.h>

typedef struct {
    int value;
    char char_value[2];
} record;

#define MAX_PRIME 1000

// Utility function to check if a number is prime
int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

// Function to generate a list of prime numbers less than MAX_PRIME
void generate_primes(int **primes, int *prime_count) {
    *prime_count = 0;
    for (int i = 2; i < MAX_PRIME; i++) {
        if (is_prime(i)) (*primes)[(*prime_count)++] = i;
    }
}

// Function to check uniqueness and range of offsets using a hash table
int validate_offsets(size_t *offsets, size_t count, size_t min_offset, size_t max_offset) {
    unsigned long hash_table_size = (max_offset - min_offset + 1);
    int *hash_table = calloc(hash_table_size, sizeof(int));
    if (!hash_table) return 0;

    for (size_t i = 0; i < count; i++) {
        size_t offset = offsets[i];
        if (offset < min_offset || offset > max_offset || hash_table[offset - min_offset]) {
            free(hash_table);
            return 0;
        }
        hash_table[offset - min_offset] = 1;
    }

    free(hash_table);
    return 1;
}

// Function to generate random records
void generate_records(record *records, size_t count, int min_val, int max_val) {
    for (size_t i = 0; i < count; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        snprintf(records[i].char_value, sizeof(records[i].char_value), "%d", records[i].value);
    }
}

// Function to execute a command-line tool and measure time and memory
void execute_command(const char *command) {
    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("popen failed");
        return;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
    }
    pclose(fp);
}

// Main function to allocate and initialize components
int* allocate_components(size_t *offset_count, int **keys, size_t *key_count,
                         record ***records, size_t *record_count,
                         size_t max_offsets, size_t min_offset, size_t max_offset,
                         size_t count, int min_val, int max_val) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    // Allocate offsets
    size_t *offsets = malloc(max_offsets * sizeof(size_t));
    if (!offsets) return NULL;

    for (size_t i = 0; i < max_offsets;) {
        size_t offset = rand() % (max_offset - min_offset + 1) + min_offset;
        pthread_mutex_lock(&mutex);
        int found = 0;
        for (size_t j = 0; j < i; j++) {
            if (offsets[j] == offset) {
                found = 1;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);

        if (!found) offsets[i++] = offset;
    }

    if (!validate_offsets(offsets, max_offsets, min_offset, max_offset)) {
        free(offsets);
        return NULL;
    }
    *offset_count = max_offsets;

    // Allocate keys
    int *prime_keys = malloc(max_offsets * sizeof(int));
    if (!prime_keys) {
        free(offsets);
        return NULL;
    }

    generate_primes(&prime_keys, key_count);
    memcpy(prime_keys, prime_keys, (*key_count) * sizeof(int));
    *keys = prime_keys;

    // Allocate records
    record **rec_array = malloc(count * sizeof(record *));
    if (!rec_array) {
        free(offsets);
        free(prime_keys);
        return NULL;
    }

    for (size_t i = 0; i < count; i++) {
        rec_array[i] = malloc(sizeof(record));
        if (!rec_array[i]) {
            while (i--) free(rec_array[i]);
            free(rec_array);
            free(prime_keys);
            free(offsets);
            return NULL;
        }
    }

    generate_records(*rec_array, count, min_val, max_val);
    *records = rec_array;
    *record_count = count;

    // Execute command to compile and measure
    execute_command("gcc -o output source.c && time ./output");

    pthread_mutex_destroy(&mutex);
    return (int *)offsets; // Return offsets as a dummy pointer for error handling
}

// Function to free allocated components
void free_components(size_t offset_count, int *keys, size_t key_count,
                     record **records, size_t record_count) {
    for (size_t i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free((int *)offset_count); // Assuming offset_count is cast from the return value
}

int main() {
    size_t offset_count, key_count, record_count;
    int *keys;
    record **records;

    if (allocate_components(&offset_count, &keys, &key_count,
                            &records, &record_count, 1000, 10, 10000, 500, 1, 100)) {
        // Use allocated components
    }

    free_components(offset_count, keys, key_count, records, record_count);
    return 0;
}
