static int is_whitelisted(const char *hostname) {
    const char whitelist[WHITELIST_SIZE][50] = {"example.com", "test.com", "sample.org",
                                                "dev.net", "localhost", "api.example.com",
                                                "service.test.com", "data.sample.org",
                                                "backend.dev.net", "site.local"};
    for (int i = 0; i < WHITELIST_SIZE; ++i) {
