    if (!*nodes) {
        log_message("Memory allocation failed for nodes.");
        return -1;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        (*nodes)[i] = (node_t *)calloc(1, sizeof(node_t));
        if (!(*nodes)[i]) {
            log_message("Memory allocation failed for node.");
            free_data_structures(nodes, i);
            return -1;
        }
        initialize_record(&((*nodes)[i]->data_record), 0, 100); // Initialize with random value between 0 and 100
    }

    return 0;
}

void free_data_structures(node_t ***nodes, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        if ((*nodes)[i]) {
            free((*nodes)[i]);
        }
    }
    free(*nodes);
    *nodes = NULL;
}

int perform_dns_resolution(hostname_list_t *list, int max_concurrent_requests) {
    pthread_t threads[max_concurrent_requests];
    int active_threads = 0;

    for (size_t i = 0; i < list->count; ++i) {
        if (!is_whitelisted(list->hostnames[i])) {
            log_message("Hostname not whitelisted.");
            continue;
        }

        while (active_threads >= max_concurrent_requests) {
            pthread_mutex_lock(&mutex);
            for (int j = 0; j < max_concurrent_requests; ++j) {
                if (!pthread_kill(threads[j], 0)) { // Check if thread is alive
                    pthread_join(threads[j], NULL);
                    --active_threads;
                }
            }
            pthread_mutex_unlock(&mutex);
        }

        struct dns_task *task = (struct dns_task *)malloc(sizeof(struct dns_task));
        if (!task) {
            log_message("Memory allocation failed for DNS task.");
            continue;
        }
        strncpy(task->hostname, list->hostnames[i], sizeof(task->hostname));
        pthread_create(&threads[active_threads++], NULL, dns_worker, (void *)task);
    }

    while (active_threads > 0) {
        pthread_mutex_lock(&mutex);
        for (int j = 0; j < max_concurrent_requests; ++j) {
            if (!pthread_kill(threads[j], 0)) {
                pthread_join(threads[j], NULL);
                --active_threads;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}

void *dns_worker(void *arg) {
    struct dns_task *task = (struct dns_task *)arg;

    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(task->hostname, NULL, &hints, &res)) != 0) {
        log_message("DNS resolution failed.");
        free(task);
        pthread_exit(NULL);
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, task->ip_address, sizeof(task->ip_address));
    }

    freeaddrinfo(res);
    free(task);

    pthread_exit(NULL);
}

void log_message(const char *message) {
    printf("LOG: %s\n", message); // Simple logging to stdout
}
