#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int key;
} record;

typedef struct node {
    record data;
    struct node* left;
    struct node* right;
} node;

// Binary Search Tree for efficient search
node* insert(node* root, record new_record) {
    if (root == NULL) {
        node* temp = (node*)malloc(sizeof(node));
        temp->data = new_record;
        temp->left = temp->right = NULL;
        return temp;
    }

    if (new_record.key < root->data.key)
        root->left = insert(root->left, new_record);
    else if (new_record.key > root->data.key)
        root->right = insert(root->right, new_record);

    return root;
}

// Check for duplicates before insertion
int contains(node* root, int key) {
    if (root == NULL)
        return 0;

    if (key < root->data.key)
        return contains(root->left, key);
    else if (key > root->data.key)
        return contains(root->right, key);
    else
        return 1; // Key found
}

node* search(node* root, int key) {
    if (root == NULL || root->data.key == key)
        return root;

    if (key < root->data.key)
        return search(root->left, key);

    return search(root->right, key);
}

// Thread-safe wrapper for insert operation
node* thread_safe_insert(node** root, record new_record) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    if (!contains(*root, new_record.key)) {
        *root = insert(*root, new_record);
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
    return *root;
}

// Thread-safe wrapper for search operation
node* thread_safe_search(node* root, int key) {
    node* result = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    result = search(root, key);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
    return result;
}

// Initialize random number generator
void initialize_random() {
    srand(time(NULL));
}

// Generate unique random numbers within a range and populate the BST
node* generate_unique_records(int min, int max, size_t count) {
    node* root = NULL;

    for (size_t i = 0; i < count; ++i) {
        int key;
        do {
            key = rand() % (max - min + 1) + min;
        } while (contains(root, key));

        record new_record = { .key = key };
        root = thread_safe_insert(&root, new_record);
    }

    return root;
}

// Free the memory used by the BST
void free_tree(node* root) {
    if (root == NULL)
        return;

    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main() {
    initialize_random();

    const size_t record_count = 1000000;
    int range_min = 1, range_max = 2000000; // Example range

    node* root = generate_unique_records(range_min, range_max, record_count);

    int search_key = rand() % (range_max - range_min + 1) + range_min;

    node* found_node = thread_safe_search(root, search_key);
    if (found_node != NULL)
        printf("Record with key %d was found.\n", found_node->data.key);
    else
        printf("Record with key %d not found.\n", search_key);

    free_tree(root);

    return 0;
}
