['Below is a C implementation of the requested functionality. This code defines a `record` structure, initializes an array of these structures with random values, and includes mechanisms for managing memory efficiently while supporting concurrent access using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_THREADS 100

typedef struct {
    int value;
    long *timestamp;
    float *metric;
    long *offsets;
    size_t offsets_size;
    int *keys;
    size_t keys_size;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

void initialize_collection(RecordCollection *collection) {
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->records = malloc(collection->capacity * sizeof(Record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

void free_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].timestamp);
        free(collection->records[i].metric);
        free(collection->records[i].offsets);
        free(collection->records[i].keys);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
}

void resize_collection(RecordCollection *collection, size_t new_capacity) {
    Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }
    collection->records = new_records;
    collection->capacity = new_capacity;
}

void add_record(RecordCollection *collection, int value, long timestamp, float metric,
                size_t offsets_size, const long *offsets, size_t keys_size, const int *keys) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
    }

    Record new_record;
    new_record.value = value;
    new_record.timestamp = malloc(sizeof(long));
    new_record.metric = malloc(sizeof(float));
    new_record.offsets = malloc(offsets_size * sizeof(long));
    new_record.keys = malloc(keys_size * sizeof(int));

    if (!new_record.timestamp || !new_record.metric ||
        !new_record.offsets || !new_record.keys) {
        perror("Failed to allocate memory for new record");
        exit(EXIT_FAILURE);
    }

    *new_record.timestamp = timestamp;
    *new_record.metric = metric;
    memcpy(new_record.offsets, offsets, offsets_size * sizeof(long));
    memcpy(new_record.keys, keys, keys_size * sizeof(int));

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
}

Record get_record(const RecordCollection *collection, size_t index) {
    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    return collection->records[index];
}

void delete_record(RecordCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    free(collection->records[index].timestamp);
    free(collection->records[index].metric);
    free(collection->records[index].offsets);
    free(collection->records[index].keys);

    memmove(&collection->records[index], &collection->records[index + 1],
            (collection->count - index - 1) * sizeof(Record));

    collection->count--;

    if (collection->count < collection->capacity / 4 && collection->capacity > INITIAL_CAPACITY) {
        resize_collection(collection, collection->capacity / 2);
    }

    pthread_mutex_unlock(&collection->lock);
}

void report_memory_usage(const RecordCollection *collection) {
    size_t total_size = sizeof(RecordCollection) +
                        (collection->count * sizeof(Record)) +
                        (collection->count * sizeof(long)) + // timestamps
                        (collection->count * sizeof(float)) + // metrics
                        collection->count; // offsets and keys, assuming average sizes

    printf("Total memory usage: %zu bytes\n", total_size);
}

int main() {
    RecordCollection collection;
    initialize_collection(&collection);

    srand(time(NULL));

    for (size_t i = 0; i < 100; ++i) {
        int value = rand() % 1000;
        long timestamp = time(NULL) + i;
        float metric = (float)(rand() % 100) / 10.0f;

        size_t offsets_size = rand() % 5 + 1;
        long *offsets = malloc(offsets_size * sizeof(long));
        for (size_t j = 0; j < offsets_size; ++j) {
            offsets[j] = rand() % 1000;
        }

        size_t keys_size = rand() % 5 + 1;
        int *keys = malloc(keys_size * sizeof(int));
        for (size_t j = 0; j < keys_size; ++j) {
            keys[j] = rand() % 100;
        }

        add_record(&collection, value, timestamp, metric, offsets_size, offsets, keys_size, keys);
        free(offsets);
        free(keys);
    }

    report_memory_usage(&collection);

    for (size_t i = 0; i < collection.count; ++i) {
        delete_record(&collection, i);
    }

    free_collection(&collection);

    return 0;
}
```

### Key Features:
- **Dynamic Array**: Uses a dynamic array with resizing to balance memory usage and performance.
- **Thread Safety**: Utilizes mutexes to ensure thread safety during concurrent access.
- **Memory Management**: Properly allocates and deallocates memory for each record component.
- **Resizing Strategy**: Doubles the capacity when full and halves it when less than a quarter is used.
- **Error Handling**: Handles allocation failures gracefully with error messages.
- **Monitoring**: Reports total memory usage to help identify bottlenecks.']

