void initializeSpatialIndex(SpatialIndex* index, const char* configFilePath) {
    FILE *file = fopen(configFilePath, "r");
    if (!file) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
    }

    struct json_object *parsed_json;
    struct json_object *spatialResolution, *boundingBox;

    char buffer[1024];
    fread(buffer, sizeof(char), 1024, file);
    fclose(file);

    parsed_json = json_tokener_parse(buffer);
    json_object_object_get_ex(parsed_json, "spatialResolution", &spatialResolution);
    index->spatialResolution = json_object_get_double(spatialResolution);

    struct json_object *bboxArray;
    json_object_object_get_ex(parsed_json, "boundingBox", &bboxArray);
    if (json_object_array_length(bboxArray) == 4) {
        for (int i = 0; i < 4; ++i) {
            index->boundingBox[i] = json_object_get_double(json_object_array_get_idx(bboxArray, i));
        }
    }

    json_object_put(parsed_json);
}

void insertRecord(SpatialIndex* index, double latitude, double longitude, long timestamp, const char* metadata) {
    if (index->size >= MAX_ENTRIES) {
        fprintf(stderr, "Maximum number of records reached\n");
        return;
    }

    Record* record = malloc(sizeof(Record));
    record->id = ++index->size; // Sequential ID assignment
    record->latitude = latitude;
    record->longitude = longitude;
    record->timestamp = timestamp;
    record->metadata = strdup(metadata); // Copy metadata

    if (validateMetadata(record->metadata)) {
        index->records[index->size] = record;
    } else {
        free(record);
        fprintf(stderr, "Invalid metadata format\n");
    }
}

void deleteRecord(SpatialIndex* index, int id) {
    for (int i = 1; i <= index->size; ++i) {
        if (index->records[i]->id == id) {
            free(index->records[i]->metadata);
            free(index->records[i]);
            for (int j = i; j < index->size; ++j) {
                index->records[j] = index->records[j + 1];
            }
            --index->size;
            return;
        }
    }

    fprintf(stderr, "Record not found\n");
}

void searchByProximity(SpatialIndex* index, double latitude, double longitude, double radius) {
    for (int i = 1; i <= index->size; ++i) {
        double distance = calculateDistance(latitude, longitude,
                                           index->records[i]->latitude,
                                           index->records[i]->longitude);
        if (distance <= radius) {
            printf("Record ID: %d\n", index->records[i]->id);
        }
    }
}

