    Record *records = (Record *)allocated_memory;
    char buffer[BUFFER_SIZE];
    int total_allocated_memory = 0;

    for (int i = 0; i < record_count && total_allocated_memory <= max_memory; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        const char *data = data_source->get_data(i, buffer, sizeof(buffer));
        if (!data) continue;

        size_t string_length = strnlen(data, BUFFER_SIZE);
        total_allocated_memory += string_length + 1; // For null-terminator

        if (total_allocated_memory <= max_memory) {
            records[i].buffer_ptr = (char *)allocated_memory + record_count * record_size + total_allocated_memory - (string_length + 1);
            strncpy(records[i].buffer_ptr, data, string_length);
            records[i].buffer_ptr[string_length] = '\0';
            records[i].data_source_ptr = (void *)data_source;
        }
    }

    return records;
}

