    processor->jerr.error_exit = custom_jpeg_error_exit;

    if (setjmp(processor->jerr.setjmp_buffer)) {
        // If we get here, libjpeg had an error.
        jpeg_destroy_decompress(&processor->cinfo);
        fclose(processor->input_file);
        return NULL;
    }

    jpeg_create_decompress(&processor->cinfo);

    // Specify data source for reading
    jpeg_stdio_src(&processor->cinfo, processor->input_file);
    if (jpeg_read_header(&processor->cinfo, TRUE) != JPEG_HEADER_OK) {
        handle_error("Could not read image header.");
        return NULL;
