typedef enum {
    INSERT,
    UPDATE,
    DELETE
} LogType;

typedef struct {
    time_t timestamp;
    LogType type;
    char *key;
    char *payload;
    size_t payload_size;
    unsigned int version;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t entry_count;
    size_t total_payload_chars;
} DistributedLog;

// Function to generate a random alphanumeric string
char* generate_random_string(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+";
    char *random_str = malloc(length + 1);
    if (random_str == NULL) return NULL;

    for (size_t i = 0; i < length; i++) {
        random_str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_str[length] = '\0';

    return random_str;
}

// Function to initialize the distributed log
DistributedLog* init_distributed_log(size_t entry_count, size_t min_payload_size, size_t max_payload_size) {
    if (entry_count == 0 || min_payload_size > max_payload_size) return NULL;

    DistributedLog *log = malloc(sizeof(DistributedLog));
    if (log == NULL) return NULL;

    log->entries = calloc(entry_count, sizeof(LogEntry*));
    if (log->entries == NULL) {
        free(log);
        return NULL;
    }

    log->entry_count = entry_count;
    log->total_payload_chars = 0;

    srand(time(NULL)); // Seed for random payload generation

    for (size_t i = 0; i < entry_count; ++i) {
        size_t payload_len = min_payload_size + rand() % (max_payload_size - min_payload_size + 1);

        LogEntry *entry = malloc(sizeof(LogEntry));
        if (entry == NULL) {
            // Cleanup on failure
            for (size_t j = 0; j < i; ++j) {
                free(log->entries[j]->key);
                free(log->entries[j]->payload);
                free(log->entries[j]);
            }
            free(log->entries);
            free(log);
            return NULL;
        }

        entry->timestamp = time(NULL); // Use current time
        entry->type = rand() % 3; // Random log type (INSERT, UPDATE, DELETE)
        entry->key = generate_random_string(10); // Random key identifier of fixed size
        if (entry->key == NULL) {
            free(entry);
            for (size_t j = 0; j < i; ++j) {
                free(log->entries[j]->key);
                free(log->entries[j]->payload);
                free(log->entries[j]);
            }
            free(log->entries);
            free(log);
            return NULL;
        }

        entry->payload_size = payload_len;
        entry->payload = generate_random_string(payload_len); // Random payload
        if (entry->payload == NULL) {
            free(entry->key);
            free(entry);
            for (size_t j = 0; j < i; ++j) {
                free(log->entries[j]->key);
                free(log->entries[j]->payload);
                free(log->entries[j]);
            }
            free(log->entries);
            free(log);
            return NULL;
        }

        entry->version = i + 1; // Incrementing version number
        log->total_payload_chars += payload_len;

        log->entries[i] = entry;
    }

    return log;
}

// Function to iterate over the log entries
void iterate_log(DistributedLog *log, void (*process_entry)(LogEntry*)) {
    if (process_entry == NULL) return;

    for (size_t i = 0; i < log->entry_count; ++i) {
        process_entry(log->entries[i]);
    }
}

// Function to free the distributed log
void free_distributed_log(DistributedLog *log) {
    if (log == NULL) return;

    for (size_t i = 0; i < log->entry_count; ++i) {
        LogEntry *entry = log->entries[i];
        if (entry != NULL) {
            free(entry->key);
            free(entry->payload);
            free(entry);
        }
    }

    free(log->entries);
    free(log);
}

// Example function to process each log entry
void print_log_entry(LogEntry *entry) {
    if (entry == NULL) return;

    printf("Timestamp: %ld, Type: %d, Key: %s, Payload Size: %zu, Version: %u\n",
           entry->timestamp, entry->type, entry->key, entry->payload_size, entry->version);
}

int main() {
    size_t num_entries = 10;
    size_t min_payload = 5;
    size_t max_payload = 20;

    DistributedLog *log = init_distributed_log(num_entries, min_payload, max_payload);

    if (log != NULL) {
        printf("Total Payload Characters: %zu\n", log->total_payload_chars);
        iterate_log(log, print_log_entry);
        free_distributed_log(log);
    } else {
        fprintf(stderr, "Failed to initialize distributed log.\n");
    }

    return 0;
}
```

### Key Points:
- **Memory Management**: The code carefully allocates and deallocates memory for each entry's components (key and payload) and the entire structure.
- **Error Handling**: It checks for allocation failures at every step, cleaning up previously allocated resources if necessary to prevent leaks.
- **Random Generation**: Randomly generates payloads and keys within specified bounds using a fixed charset.
- **Iteration and Cleanup**: Provides functions to iterate over entries for processing and to clean up all allocated memory efficiently.']

