#include <stdatomic.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define COMPACT_THRESHOLD 0.8

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    atomic_size_t count;
    pthread_mutex_t mutex;
    size_t capacity;
} Collection;

Collection* init_collection(size_t initial_capacity) {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        collection->records[i] = NULL;
    }

    return collection;
}

void destroy_collection(Collection *collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void randomize_collection(Collection *collection, int min_value, int max_value) {
    srand(time(NULL));

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            collection->records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        }
    }
}

int add_record(Collection *collection, int value, long offset, int key) {
    pthread_mutex_lock(&collection->mutex);

    if (atomic_load(&collection->count) >= collection->capacity) {
        // Trigger compaction
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = (Record**)malloc(new_capacity * sizeof(Record*));

        for (size_t i = 0; i < collection->capacity; ++i) {
            if (collection->records[i]) {
                int index = rand() % new_capacity;
                while (new_records[index] != NULL) {
                    index = (index + 1) % new_capacity;
                }
                new_records[index] = collection->records[i];
            }
        }

        free(collection->records);
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    size_t index = atomic_fetch_add(&collection->count, 1);

    Record *record = (Record*)malloc(sizeof(Record));
    record->value = value;
    record->offset = (long*)malloc(sizeof(long));
    record->key = (int*)malloc(sizeof(int));

    if (!record || !record->offset || !record->key) {
        atomic_fetch_sub(&collection->count, 1);
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    *record->offset = offset;
    *record->key = key;

    collection->records[index] = record;
    pthread_mutex_unlock(&collection->mutex);

    return index;
}

Record* get_record_by_index(Collection *collection, size_t index) {
    if (index >= atomic_load(&collection->count)) {
        return NULL;
    }

    Record **record_ptr = &collection->records[index];
    while (__atomic_load_n(record_ptr, __ATOMIC_ACQUIRE) == NULL);

    return *__atomic_load_n(record_ptr, __ATOMIC_RELAXED);
}

Record* get_record_by_key(Collection *collection, int key, int tolerance) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < atomic_load(&collection->count); ++i) {
        if (collection->records[i]) {
            if (abs(collection->records[i]->key - key) <= tolerance) {
                pthread_mutex_unlock(&collection->mutex);
                return collection->records[i];
            }
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

// Additional functions for persistence, compaction strategy,
// error handling, retry mechanisms, and unit tests are omitted
// due to complexity constraints. They would involve integrating with external systems.

int main() {
    Collection *collection = init_collection(1000);

    // Adding some records
    add_record(collection, 42, 123456789, 1);
    add_record(collection, 84, 987654321, 2);

    // Randomizing values in the collection
    randomize_collection(collection, 10, 50);

    // Retrieving a record by index and key
    Record *record = get_record_by_index(collection, 0);
    if (record) {
        printf("Value: %d, Offset: %ld, Key: %d\n", record->value, *(record->offset), *(record->key));
    }

    // Cleanup
    destroy_collection(collection);

    return 0;
}
