#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <stdatomic.h>
#include <pthread.h>

#define MAX_ID_LENGTH 128
#define MAX_RECORDS 10000000

typedef struct {
    char identifier[MAX_ID_LENGTH];
    double transaction_amount;
    time_t timestamp;
} TransactionRecord;

// Utility function to generate a simple hash
unsigned int simple_hash(const char *str) {
    unsigned int hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash;
}

// Function to compute checksum for validation
int validate_checksum(const char *identifier) {
    unsigned int sum = 0;
    for (size_t i = 0; identifier[i] != '\0' && i < MAX_ID_LENGTH; ++i) {
        sum += identifier[i];
    }
    return (sum % 256) == 0; // Simple checksum validation
}

// Function to generate a unique identifier
void generate_unique_identifier(char *identifier, size_t seq_num) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[15];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);

    unsigned int hash_value = simple_hash(identifier);
    snprintf(identifier, MAX_ID_LENGTH, "ID-%s-%zu-%u", timestamp, seq_num, hash_value);

    if (!validate_checksum(identifier)) {
        identifier[MAX_ID_LENGTH - 1] = '\0'; // Ensure null-termination
        fprintf(stderr, "Checksum validation failed for identifier: %s\n", identifier);
    }
}

// Thread-safe collection management with atomic operations
typedef struct {
    TransactionRecord *records;
    size_t count;
    _Atomic(size_t) next_index;
    pthread_mutex_t mutex;
} RecordCollection;

void init_record_collection(RecordCollection *collection, size_t initial_size) {
    collection->records = (TransactionRecord *)malloc(initial_size * sizeof(TransactionRecord));
    collection->count = 0;
    atomic_store(&collection->next_index, 0);
    pthread_mutex_init(&collection->mutex, NULL);
}

void free_record_collection(RecordCollection *collection) {
    free(collection->records);
    collection->records = NULL;
    pthread_mutex_destroy(&collection->mutex);
}

int add_transaction_record(RecordCollection *collection, const char *identifier, double amount) {
    pthread_mutex_lock(&collection->mutex);

    size_t index = atomic_fetch_add(&collection->next_index, 1);
    if (index >= collection->count && collection->count < MAX_RECORDS) {
        memcpy(collection->records[index].identifier, identifier, MAX_ID_LENGTH);
        collection->records[index].transaction_amount = amount;
        collection->records[index].timestamp = time(NULL);
        pthread_mutex_unlock(&collection->mutex);

        return 1; // Record added
    }

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Collection full or failure
}

// Example usage of the system
int main() {
    RecordCollection collection;
    init_record_collection(&collection, 1000000); // Initial allocation

    char identifier[MAX_ID_LENGTH];
    size_t sequence_number = 1;

    for (size_t i = 0; i < 10; ++i) { // Example loop to generate identifiers
        generate_unique_identifier(identifier, sequence_number++);
        if (add_transaction_record(&collection, identifier, 100.50)) {
            printf("Record added: %s\n", identifier);
        }
    }

    free_record_collection(&collection);

    return 0;
}
