DistributedLog* create_log(size_t initial_capacity) {
    DistributedLog *log = (DistributedLog*)malloc(sizeof(DistributedLog));
    if (!log) return NULL;

    log->capacity = initial_capacity;
    log->count = 0;
    log->total_characters = 0;
    log->entries = (LogEntry**)malloc(log->capacity * sizeof(LogEntry*));
    if (!log->entries) {
        free(log);
        return NULL;
    }
    return log;
}

void destroy_log(DistributedLog *log) {
    if (!log) return;

    for (size_t i = 0; i < log->count; ++i) {
        free(log->entries[i]->timestamp);
        free(log->entries[i]->key_identifier);
        free(log->entries[i]->payload);
        free(log->entries[i]);
    }
    free(log->entries);
    free(log);
}

int add_entry(DistributedLog *log, const char *timestamp, LogType type, 
              const char *key_identifier, const char *payload) {
    if (strlen(payload) > MAX_PAYLOAD_SIZE) return 0;

    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        LogEntry **new_entries = (LogEntry**)realloc(log->entries, new_capacity * sizeof(LogEntry*));
        if (!new_entries) return 0;
        log->entries = new_entries;
        log->capacity = new_capacity;
    }

    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return 0;

    entry->timestamp = strdup(timestamp);
    entry->type = type;
    entry->key_identifier = strdup(key_identifier);
    char *truncated_payload = strndup(payload, MAX_PAYLOAD_SIZE);
    entry->payload = truncated_payload;
    entry->version_number = log->count + 1; // Version starts at 1

    log->entries[log->count++] = entry;
    log->total_characters += strlen(entry->payload);

    return 1;
}

const LogEntry* get_entry(const DistributedLog *log, size_t index) {
    if (index < log->count) return log->entries[index];
    return NULL;
