char* generate_token(const char *email) {
    if (strlen(email) > EMAIL_MAX_LENGTH || !verify_email_checksum(email)) {
        log_error("Invalid email or checksum verification failed.");
        return NULL;
    }

    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[15];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeinfo);

    size_t random_str_length = rand() % 17 + 16; // Length between 16 and 32
    char *random_str = generate_random_string(random_str_length);
    if (!random_str) {
        log_error("Failed to generate random string.");
        return NULL;
