    uint32_t checksum = simple_hash(email, strlen(email));

    size_t token_length = strlen(email) + strlen(timestamp) + 1 +
                          random_str_length + 10; // additional space for checksum and delimiter

    if (token_length > MAX_TOKEN_LENGTH) {
        free(random_str);
        log_error("Token exceeds maximum length.");
        return NULL;
    }

    char *token = malloc(token_length + 1); // +1 for null terminator
    if (!token) {
        free(random_str);
        log_error("Failed to allocate memory for token.");
        return NULL;
    }

    snprintf(token, token_length + 1, "%s_%s_%s_%u", email, timestamp, random_str, checksum);
    free(random_str);

    // Check against distributed key-value store and ensure uniqueness
    pthread_mutex_lock(&lock);
    if (keyValueStore.email && strcmp(keyValueStore.email, token) == 0) {
        int suffix = 1;
        char *new_token;
        do {
            snprintf(new_token, MAX_TOKEN_LENGTH + 1, "%s_%d", token, suffix++);
        } while (strcmp(keyValueStore.email, new_token) == 0 && suffix < 100);

        if (suffix >= 100) {
            free(token);
            log_error("Unable to generate a unique token.");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        token = new_token;
    } else {
        keyValueStore.email = strdup(token); // Store the new unique token
    }
    pthread_mutex_unlock(&lock);

    return token;
}

