    size_t size;
    size_t capacity;
    pthread_rwlock_t rwlock;
} Collection;

Collection collection;

void initialize_collection(size_t initial_size) {
    collection.size = 0;
    collection.capacity = initial_size;
    collection.records = malloc(initial_size * sizeof(Record));
    if (!collection.records) {
        log_error("Failed to allocate memory for records.");
        exit(EXIT_FAILURE);
    }
    pthread_rwlock_init(&collection.rwlock, NULL);
}

void free_collection() {
    for (size_t i = 0; i < collection.size; ++i) {
        free(collection.records[i].offset);
        free(collection.records[i].key);
    }
    free(collection.records);
    pthread_rwlock_destroy(&collection.rwlock);
}

Record* get_record_by_index(size_t index) {
    if (index >= collection.size) return NULL;

    pthread_rwlock_rdlock(&collection.rwlock);
    Record *record = &collection.records[index];
    pthread_rwlock_unlock(&collection.rwlock);

    return record;
}

Record* get_record_by_key(int key, int tolerance) {
    pthread_rwlock_rdlock(&collection.rwlock);
    for (size_t i = 0; i < collection.size; ++i) {
        if (*collection.records[i].key >= key - tolerance && *collection.records[i].key <= key + tolerance) {
            Record* record = &collection.records[i];
            pthread_rwlock_unlock(&collection.rwlock);
            return record;
        }
    }
    pthread_rwlock_unlock(&collection.rwlock);

    return NULL;
}

void compact_collection() {
    if (collection.size < collection.capacity * 0.8) return;

    size_t new_capacity = collection.capacity / 2 + INITIAL_CAPACITY;
    Record* new_records = malloc(new_capacity * sizeof(Record));
    if (!new_records) {
        log_error("Failed to allocate memory during compaction.");
        return;
    }

    pthread_rwlock_wrlock(&collection.rwlock);
    for (size_t i = 0; i < collection.size; ++i) {
        new_records[i] = collection.records[i];
        free(collection.records[i].offset);
        free(collection.records[i].key);
    }

    free(collection.records);
    collection.capacity = new_capacity;
    collection.records = new_records;

    pthread_rwlock_unlock(&collection.rwlock);
}

