            destroy_log(log);
            return NULL;
        }
    }

    return log;
}

int add_log_entry(Log* log, const char* key, LogType type) {
    pthread_mutex_lock(&log->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&log->lock);
        return 0;
    }

    size_t payload_size = rand() % (PAYLOAD_MAX_SIZE - PAYLOAD_MIN_SIZE + 1) + PAYLOAD_MIN_SIZE;
    char* payload = (char*)malloc(payload_size + 1);
    if (!payload) {
        free(new_node);
        pthread_mutex_unlock(&log->lock);
        return 0;
    }

    snprintf(payload, payload_size + 1, "Payload_%zu", rand());
    new_node->entry.timestamp = time(NULL);
    new_node->entry.type = type;
    strncpy(new_node->entry.key, key, sizeof(new_node->entry.key) - 1);
    new_node->entry.payload = payload;
    new_node->entry.payload_size = payload_size;
    new_node->entry.version = log->current_version++;

    new_node->next = log->head;
    log->head = new_node;

    log->total_entries++;
    log->total_payload_size += payload_size;

    pthread_mutex_unlock(&log->lock);
    return 1;
}

void destroy_log(Log* log) {
    if (!log) return;

    Node* current = log->head;
    while (current) {
        Node* next = current->next;
        free(current->entry.payload);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&log->lock);
    free(log);
}

void iterate_log(Log* log, void (*callback)(const LogEntry*)) {
    if (!log || !log->head) return;

    pthread_mutex_lock(&log->lock);

    Node* current = log->head;
    while (current) {
        callback(&(current->entry));
        current = current->next;
    }

    pthread_mutex_unlock(&log->lock);
}

