#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_PAYLOAD_SIZE 256
#define MAX_ENTRIES 1000000

typedef enum { INSERT, UPDATE, DELETE } LogType;

typedef struct {
    time_t timestamp;
    LogType type;
    char key[64];
    char *payload;
    size_t payload_size;
    unsigned int version;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    bool stop_signal;
    size_t total_payload_characters;
    size_t max_payload_size;
} LogQueue;

LogQueue* create_log(size_t initial_entries, size_t min_payload_size, size_t max_payload_size) {
    if (initial_entries == 0 || min_payload_size > max_payload_size) return NULL;

    LogQueue* log = malloc(sizeof(LogQueue));
    if (!log) return NULL;

    log->head = NULL;
    log->tail = NULL;
    pthread_mutex_init(&log->mutex, NULL);
    pthread_cond_init(&log->cond, NULL);
    log->stop_signal = false;
    log->total_payload_characters = 0;
    log->max_payload_size = max_payload_size;

    srand(time(NULL));
    for (size_t i = 0; i < initial_entries; ++i) {
        size_t payload_length = rand() % (max_payload_size - min_payload_size + 1) + min_payload_size;
        if (payload_length == 0) continue;

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            // Handle allocation failure
            while (log->head != NULL) {
                Node* temp = log->head;
                log->head = log->head->next;
                free(temp->entry.payload);
                free(temp);
            }
            pthread_mutex_destroy(&log->mutex);
            pthread_cond_destroy(&log->cond);
            free(log);
            return NULL;
        }

        new_node->entry.timestamp = time(NULL);
        new_node->entry.type = (LogType)(rand() % 3);
        snprintf(new_node->entry.key, sizeof(new_node->entry.key), "key_%zu", i);
        new_node->entry.payload = malloc(payload_length + 1);
        if (!new_node->entry.payload) {
            // Handle allocation failure
            free(new_node);
            while (log->head != NULL) {
                Node* temp = log->head;
                log->head = log->head->next;
                free(temp->entry.payload);
                free(temp);
            }
            pthread_mutex_destroy(&log->mutex);
            pthread_cond_destroy(&log->cond);
            free(log);
            return NULL;
        }

        for (size_t j = 0; j < payload_length; ++j) {
            new_node->entry.payload[j] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+[]{}|;:',.<>?".rand() % 72;
        }
        new_node->entry.payload[payload_length] = '\0';
        new_node->entry.payload_size = payload_length;
        new_node->entry.version = i + 1;

        log->total_payload_characters += payload_length;

        pthread_mutex_lock(&log->mutex);
        if (log->tail) {
            log->tail->next = new_node;
        } else {
            log->head = new_node;
        }
        log->tail = new_node;
        pthread_cond_signal(&log->cond);
        pthread_mutex_unlock(&log->mutex);
    }

    return log;
}

void destroy_log(LogQueue* log) {
    if (!log) return;

    pthread_mutex_lock(&log->mutex);
    log->stop_signal = true;
    pthread_cond_broadcast(&log->cond);
    pthread_mutex_unlock(&log->mutex);

    Node* current = log->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->entry.payload);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&log->mutex);
    pthread_cond_destroy(&log->cond);
    free(log);
}

void* consumer_thread(void* arg) {
    LogQueue* log = (LogQueue*)arg;

    while (true) {
        pthread_mutex_lock(&log->mutex);

        while (log->head == NULL && !log->stop_signal) {
            pthread_cond_wait(&log->cond, &log->mutex);
        }

        if (log->stop_signal && log->head == NULL) {
            pthread_mutex_unlock(&log->mutex);
            break;
        }

        Node* node = log->head;
        log->head = log->head->next;

        if (log->head == NULL) {
            log->tail = NULL;
        }

        pthread_mutex_unlock(&log->mutex);

        // Process the entry
        printf("Processed: %s\n", node->entry.payload);

        free(node->entry.payload);
        free(node);
    }
    return NULL;
}

void start_logging(LogQueue* log) {
    if (!log) return;

    pthread_t consumer_tid;
    pthread_create(&consumer_tid, NULL, consumer_thread, log);

    // Simulate logging
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        size_t payload_length = rand() % log->max_payload_size + 1;
        if (payload_length == 0) continue;

        pthread_mutex_lock(&log->mutex);
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) continue;

        new_node->entry.timestamp = time(NULL);
        new_node->entry.type = (LogType)(rand() % 3);
        snprintf(new_node->entry.key, sizeof(new_node->entry.key), "key_%zu", i + log->total_payload_characters / payload_length);
        new_node->entry.payload = malloc(payload_length + 1);
        if (!new_node->entry.payload) {
            free(new_node);
            continue;
        }

        for (size_t j = 0; j < payload_length; ++j) {
            new_node->entry.payload[j] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+[]{}|;:',.<>?".rand() % 72;
        }
        new_node->entry.payload[payload_length] = '\0';
        new_node->entry.payload_size = payload_length;
        new_node->entry.version = i + 1;

        log->total_payload_characters += payload_length;

        if (log->tail) {
            log->tail->next = new_node;
        } else {
            log->head = new_node;
        }
        log->tail = new_node;

        pthread_cond_signal(&log->cond);
        pthread_mutex_unlock(&log->mutex);

        usleep(1000); // Simulate delay
    }

    destroy_log(log);
}

int main() {
    size_t initial_entries = 10;
    size_t min_payload_size = 1;
    size_t max_payload_size = MAX_PAYLOAD_SIZE;

    LogQueue* log = create_log(initial_entries, min_payload_size, max_payload_size);
    if (log) {
        start_logging(log);
    }

    return 0;
