['```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Transaction {
    long timestamp;
    double amount;
    struct Transaction *next; // For linked list implementation
} Transaction;

// Linked List Node
typedef struct {
    Transaction *head;
    int size;
} TransactionList;

TransactionList* createTransactionList() {
    TransactionList* list = (TransactionList*)malloc(sizeof(TransactionList));
    list->head = NULL;
    list->size = 0;
    return list;
}

void insertTransaction(TransactionList *list, long timestamp, double amount) {
    Transaction *newTrans = (Transaction*)malloc(sizeof(Transaction));
    newTrans->timestamp = timestamp;
    newTrans->amount = amount;
    newTrans->next = list->head;
    list->head = newTrans;
    list->size++;
}

void deleteTransaction(TransactionList *list, long timestamp) {
    Transaction *current = list->head;
    Transaction *prev = NULL;

    while (current != NULL && current->timestamp != timestamp) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return; // Not found

    if (prev == NULL) { // Head needs to be deleted
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
}

void sortTransactions(TransactionList *list, int (*comparator)(const Transaction*, const Transaction*)) {
    if (list->head == NULL || list->head->next == NULL) return;

    // Simple insertion sort for better cache locality
    Transaction *sorted = NULL;

    Transaction *current = list->head;
    while (current != NULL) {
        Transaction *next = current->next;

        if (sorted == NULL || comparator(current, sorted) < 0) {
            current->next = sorted;
            sorted = current;
        } else {
            Transaction *temp = sorted;
            while (temp->next != NULL && comparator(current, temp->next) > 0) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }

        current = next;
    }

    list->head = sorted;
}

int compareByTimestamp(const Transaction* a, const Transaction* b) {
    return (a->timestamp > b->timestamp) - (a->timestamp < b->timestamp);
}

void filterTransactions(TransactionList *list, double minAmount, double maxAmount, int inclusive) {
    Transaction **arr = (Transaction**)malloc(list->size * sizeof(Transaction*));
    Transaction *current = list->head;
    int index = 0;

    while (current != NULL) { // Copy to array for easier filtering
        arr[index++] = current;
        current = current->next;
    }

    // Filter based on bounds
    for (int i = 0; i < list->size; i++) {
        double amount = arr[i]->amount;
        if ((inclusive ? amount >= minAmount : amount > minAmount) &&
            (inclusive ? amount <= maxAmount : amount < maxAmount)) {
            // Valid transaction, do nothing
        } else {
            deleteTransaction(list, arr[i]->timestamp);
            free(arr[i]); // Free the filtered out node
            i--; // Adjust index since we just deleted a node
            list->size--;
        }
    }

    free(arr);
}

void logTransaction(const char *action, long timestamp, double amount) {
    printf("LOG: %s - Timestamp: %ld, Amount: %.2f\n", action, timestamp, amount);
}

// Example Usage
int main() {
    TransactionList *list = createTransactionList();

    insertTransaction(list, 1627890123L, 100.0); // Insert some transactions
    insertTransaction(list, 1627890224L, 150.5);
    insertTransaction(list, 1627890301L, 99.9);

    logTransaction("INSERT", 1627890123L, 100.0);

    sortTransactions(list, compareByTimestamp); // Sort transactions by timestamp

    filterTransactions(list, 100.0, 150.5, 1); // Filter with inclusive bounds

    deleteTransaction(list, 1627890224L); // Delete a transaction
    logTransaction("DELETE", 1627890224L, 150.5);

    // Free the list
    Transaction *current = list->head;
    while (current != NULL) {
        Transaction *temp = current;
        current = current->next;
        free(temp);
    }

    free(list);

    return 0;
}
