#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PRODUCTS 1000000

typedef struct {
    float price;
    int stock_quantity;
    char name[101];
} Product;

Product *products = NULL;
size_t product_count = 0;

// Memory management functions
void init_products(size_t initial_capacity) {
    products = (Product *)malloc(initial_capacity * sizeof(Product));
    if (!products) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void update_product(int index, float price, int stock_quantity, const char* name) {
    if (index >= 0 && index < product_count) {
        products[index].price = price;
        products[index].stock_quantity = stock_quantity;
        strncpy(products[index].name, name, sizeof(products[index].name));
        products[index].name[sizeof(products[index].name) - 1] = '\0';
    }
}

void remove_product(int index) {
    if (index >= 0 && index < product_count) {
        memmove(&products[index], &products[index + 1],
                (--product_count - index) * sizeof(Product));
    }
}

// Function to calculate the total value of all products in stock
float calculate_total_stock_value(float exchange_rate) {
    float total = 0.0;
    for (size_t i = 0; i < product_count; ++i) {
        total += products[i].price * products[i].stock_quantity * exchange_rate;
    }
    return total;
}

// Function to filter products based on a specified minimum and maximum stock quantity
Product* filter_products_by_stock(int min_stock, int max_stock, size_t *filtered_count) {
    Product *filtered = (Product *)malloc(product_count * sizeof(Product));
    if (!filtered) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *filtered_count = 0;
    for (size_t i = 0; i < product_count; ++i) {
        if (products[i].stock_quantity >= min_stock && products[i].stock_quantity <= max_stock) {
            filtered[*filtered_count] = products[i];
            (*filtered_count)++;
        }
    }

    return filtered;
}

// Function to sort products by their price in descending order
void sort_products_by_price_descending() {
    for (size_t i = 0; i < product_count - 1; ++i) {
        for (size_t j = 0; j < product_count - i - 1; ++j) {
            if (products[j].price < products[j + 1].price) {
                Product temp = products[j];
                products[j] = products[j + 1];
                products[j + 1] = temp;
            }
        }
    }
}

// Example usage
int main() {
    float exchange_rate = 1.2; // Assume a fixed exchange rate for simplicity

    init_products(100);

    update_product(0, 19.99, 50, "Product A");
    update_product(1, 29.99, 30, "Product B");

    product_count = 2;

    printf("Total stock value: %.2f\n", calculate_total_stock_value(exchange_rate));

    size_t filtered_count;
    Product *filtered_products = filter_products_by_stock(10, 40, &filtered_count);

    for (size_t i = 0; i < filtered_count; ++i) {
        printf("Filtered Product %zu: %s, Stock: %d\n", i, filtered_products[i].name, filtered_products[i].stock_quantity);
    }
    free(filtered_products);

    sort_products_by_price_descending();

    for (size_t i = 0; i < product_count; ++i) {
        printf("Sorted Product %zu: %s, Price: %.2f\n", i, products[i].name, products[i].price);
    }

    remove_product(1);

    free(products);
    return 0;
}
```']

