    status: String,
    timestamp: Instant,
}

#[derive(Error, Debug)]
enum Error {
    #[error("Memory allocation error")]
    MemoryAllocation,
    #[error("Network error")]
    NetworkError,
    #[error("Database error")]
    DatabaseError,
    #[error("API rate limit exceeded")]
    ApiRateLimitExceeded,
}

struct GatewayClient {
    merchant_id: String,
    currency_code: String,
    // Other fields as necessary
}

impl GatewayClient {
    fn new(merchant_id: &str, currency_code: &str) -> Self {
        GatewayClient {
            merchant_id: merchant_id.to_string(),
            currency_code: currency_code.to_string(),
        }
    }

    async fn initiate_transaction(&self, transaction: &Transaction) -> Result<(), Error> {
        // Implement the API call logic
        Ok(())
    }

    async fn poll_status(&self, transaction_id: u64) -> Result<String, Error> {
        // Implement polling logic
        Ok("Completed".to_string())
    }
}

struct CacheEntry {
    value: Value,
    expiration: Instant,
}

struct TransactionCache {
    entries: HashMap<u64, CacheEntry>,
}

impl TransactionCache {
    fn new() -> Self {
        TransactionCache { entries: HashMap::new() }
    }

    fn get(&self, key: u64) -> Option<&Value> {
        if let Some(entry) = self.entries.get(&key) {
            if entry.expiration > Instant::now() {
                return Some(&entry.value);
            }
        }
        None
    }

    fn set(&mut self, key: u64, value: Value, ttl: Duration) {
        self.entries.insert(key, CacheEntry {
            value,
            expiration: Instant::now() + ttl,
        });
    }
}

async fn batchProcessTransactions(
    merchants: Vec<(String, String, f64)>, // Tuple of merchant_id, currency_code, amount
    gateway_clients: &mut HashMap<String, GatewayClient>,
    cache: &mut TransactionCache,
) -> Result<(), Error> {
    let (tx, mut rx) = mpsc::channel(32);

    for (merchant_id, currency_code, amount) in merchants {
        let tx_clone = tx.clone();

        task::spawn(async move {
            let gateway_client = GatewayClient::new(&merchant_id, &currency_code);

            // Simulate transaction creation
            let transaction = Transaction {
                id: rand::random::<u64>(),
                merchant_id,
                currency_code: currency_code.to_string(),
                amount,
                status: "Pending".to_string(),
                timestamp: Instant::now(),
            };

            if let Some(cached_status) = cache.get(transaction.id) {
                println!("Using cached status for transaction {}: {:?}", transaction.id, cached_status);
            } else {
                match gateway_client.initiate_transaction(&transaction).await {
                    Ok(_) => {
                        tx_clone.send(Ok(transaction)).await.unwrap();
                    }
                    Err(e) => eprintln!("Failed to initiate transaction: {:?}", e),
                }

                // Retry mechanism with backoff
                let mut retries = 3;
                while retries > 0 {
                    match gateway_client.poll_status(transaction.id).await {
                        Ok(status) => {
                            cache.set(transaction.id, json!({ "status": status }), Duration::from_secs(60));
                            tx_clone.send(Ok(transaction)).await.unwrap();
                            break;
                        }
                        Err(e) if e.is::<Error>() && retries > 0 => {
                            eprintln!("Retrying transaction {}: {:?}", transaction.id, e);
                            retries -= 1;
                            sleep(Duration::from_millis(100 * (3 - retries))).await;
                        }
                        Err(e) => {
                            tx_clone.send(Err(Error::NetworkError)).await.unwrap();
                            break;
                        }
                    }
                }
            }
        });
    }

    drop(tx); // Close the channel

    while let Some(result) = rx.recv().await {
        match result {
            Ok(transaction) => println!("Processed transaction {}: {:?}", transaction.id, transaction.status),
            Err(e) => eprintln!("Transaction error: {:?}", e),
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let merchants = vec![
        ("merchant1".to_string(), "USD".to_string(), 100.0),
        // Add more merchant entries as necessary
    ];

    let mut gateway_clients: HashMap<String, GatewayClient> = HashMap::new();
    let mut cache = TransactionCache::new();

    batchProcessTransactions(merchants, &mut gateway_clients, &mut cache).await?;

    Ok(())
}

// Example SQL query for retrieving transactions from a database
fn get_transactions_query() -> String {
    format!(
        "SELECT id, merchant_id, currency_code, amount, status FROM Transactions WHERE merchant_id = $1 AND currency_code = $2"
    )
}
