#[derive(Debug)]
struct Transaction {
    transaction_id: u64,
    merchant_id: String,
    currency_code: String,
    amount: f64,
    status: String,
    timestamp: SystemTime,
}

#[derive(Clone)]
struct GatewayClient {
    merchant_id: String,
    currency_code: String,
    // Add other necessary fields
}

impl GatewayClient {
    async fn initiate_transaction(&self, transaction: &Transaction) -> Result<(), &'static str> {
        // Simulate initiating a transaction with the gateway API.
        Ok(())
    }

    async fn poll_status(&self, transaction_id: u64) -> Result<String, &'static str> {
        // Simulate polling status from the gateway API.
        Ok("Completed".to_string())
    }
}

async fn process_transaction(tx: &Transaction, client: GatewayClient) -> Result<(), &'static str> {
    if let Err(e) = client.initiate_transaction(tx).await {
        return Err(e);
    }

    // Simulate network delay and retry logic
    for attempt in 0..3 {
        match client.poll_status(tx.transaction_id).await {
            Ok(status) => {
                tx.status = status;
                return Ok(());
            },
            Err(_) if attempt < 2 => {
                sleep(Duration::from_secs(2)).await; // Backoff strategy
            }
            Err(e) => return Err(e),
        }
    }

    Err("Transaction failed after retries")
}

async fn batchProcessTransactions(transactions: Vec<Transaction>, db_pool: Arc<Pool<Postgres>>) -> Result<(), &'static str> {
    let clients = build_gateway_clients(&transactions);

    for (tx, client) in transactions.iter().zip(clients.iter()) {
        if let Err(e) = process_transaction(tx, client.clone()).await {
            eprintln!("Error processing transaction {}: {}", tx.transaction_id, e);
        }
    }

    update_transactions_in_db(&transactions, db_pool).await?;

    Ok(())
}

fn build_gateway_clients(transactions: &Vec<Transaction>) -> Vec<GatewayClient> {
    transactions.iter().map(|tx| GatewayClient {
        merchant_id: tx.merchant_id.clone(),
        currency_code: tx.currency_code.clone(),
    }).collect()
}

async fn update_transactions_in_db(
    transactions: &[Transaction], db_pool: Arc<Pool<Postgres>>
) -> Result<(), sqlx::Error> {
    let mut conn = db_pool.acquire().await?;
    for transaction in transactions {
        sqlx::query!(
            "UPDATE Transactions SET amount = $1, status = $2 WHERE transaction_id = $3",
            transaction.amount,
            &transaction.status,
            transaction.transaction_id
        )
        .execute(&mut *conn)
        .await?;
    }
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), sqlx::Error> {
    let db_pool: Pool<Postgres> = Pool::<Postgres>::connect("DATABASE_URL").await?;

    // Simulate reading input
    let transactions = vec![
        Transaction { transaction_id: 1, merchant_id: "merchant_1".to_string(), currency_code: "USD".to_string(), amount: 100.0, status: "Pending".to_string(), timestamp: SystemTime::now() },
        // Add more transactions as needed
    ];

    let db_pool = Arc::new(db_pool);

    batchProcessTransactions(transactions, db_pool).await?;

    Ok(())
}
