    async fn poll_status(&self, transaction_id: u64) -> Result<String, String> {
        // Simulate polling for status
        Ok("completed".to_string())
    }
}

async fn process_transaction(
    client_tx: mpsc::Sender<Result<Transaction, String>>,
    gateway_client: GatewayClient,
    transaction: Transaction,
) {
    match gateway_client.initiate_transaction(&transaction).await {
        Ok(_) => {
            let status = gateway_client.poll_status(transaction.transaction_id).await;
            if let Ok(new_status) = status {
                transaction.status = new_status;
                client_tx.send(Ok(transaction)).ok();
            } else {
                error!("Error polling transaction status: {:?}", status.unwrap_err());
            }
        }
        Err(e) => {
            error!("Error initiating transaction: {}", e);
            client_tx.send(Err(e)).ok();
        }
    }
}

async fn batchProcessTransactions(
    merchant_ids: Vec<String>,
    currency_codes: Vec<String>,
    amounts: Vec<f64>,
    db_type: &str,
    connection_string: &str,
) -> Result<(), String> {
    let transactions = Arc::new(Mutex::new(Vec::with_capacity(merchant_ids.len())));

    for (i, merchant_id) in merchant_ids.iter().enumerate() {
        if i < currency_codes.len() && i < amounts.len() {
            let transaction = Transaction::new(i as u64 + 1, merchant_id, &currency_codes[i]);
            transactions.lock().unwrap().push(transaction);
        }
    }

    let (tx, mut rx) = mpsc::channel(32);

    for transaction in transactions.lock().unwrap().iter() {
        let gateway_client = GatewayClient::new(&transaction.merchant_id, &transaction.currency_code);
        tokio::spawn(process_transaction(tx.clone(), gateway_client, transaction.clone()));
    }

    while let Some(result) = rx.recv().await {
        match result {
            Ok(updated_transaction) => {
                info!("Transaction processed: {:?}", updated_transaction);
                update_database(&db_type, connection_string, &updated_transaction).await?;
            }
            Err(e) => error!("Failed to process transaction: {}", e),
        }
    }

    Ok(())
}

async fn update_database(
    db_type: &str,
    connection_string: &str,
    transaction: &Transaction,
) -> Result<(), PgError> {
    match db_type {
        "postgres" => {
            let mut client = Client::connect(connection_string, NoTls).unwrap();
            let stmt = format!(
                "UPDATE Transactions SET amount = {}, status = $2 WHERE transaction_id = $1",
                transaction.amount
            );
            client.execute(
                &stmt,
                &[&transaction.transaction_id, &transaction.status],
            ).await?;
        }
        "mysql" => {
            let pool = Pool::new(OptsBuilder::new()
                .set_db_name(connection_string)
                .build())
                .unwrap();
            let mut conn = pool.get_conn().await.unwrap();
            let stmt = format!(
                "UPDATE Transactions SET amount = {}, status = ? WHERE transaction_id = ?",
                transaction.amount
            );
            conn.query_drop(&stmt, &[&transaction.status, &transaction.transaction_id]).await?;
        }
        _ => return Err(PgError::from(std::io::Error::new(
            std::io::ErrorKind::Other,
            "Unsupported database type",
        ))),
    }

    Ok(())
}

fn main() {
    let rt = Runtime::new().unwrap();
    rt.block_on(async {
        // Example usage
        let merchant_ids = vec!["merchant1".to_string(), "merchant2".to_string()];
        let currency_codes = vec!["USD".to_string(), "EUR".to_string()];
        let amounts = vec![100.0, 200.0];

        if let Err(e) = batchProcessTransactions(merchant_ids, currency_codes, amounts, "postgres", "host=localhost user=postgres").await {
            error!("Error processing transactions: {}", e);
        }
    });
}
