struct Cache<T> {
    data: HashMap<u64, (T, u128)>,  // Transaction ID and timestamp
    ttl: Duration,
}

impl<T> Cache<T>
where
    T: Clone,
{
    fn new(ttl: Duration) -> Self {
        Cache {
            data: HashMap::new(),
            ttl,
        }
    }

    fn get(&self, key: u64) -> Option<T> {
        self.data.get(&key).and_then(|(value, timestamp)| {
            if chrono::Utc::now().timestamp_millis() as u128 - *timestamp < self.ttl.as_millis() as u128 {
                Some(value.clone())
            } else {
                None
            }
        })
    }

    fn set(&mut self, key: u64, value: T) {
        let current_time = chrono::Utc::now().timestamp_millis();
        self.data.insert(key, (value, current_time as u128));
    }
}

async fn process_payment_transactions(transactions: Vec<Transaction>) -> Result<(), String> {
    let payment_client = Arc::new(PaymentGatewayClient { merchant_account_id: 1, transaction_type: "standard".to_string() });
    let cache = Arc::new(Mutex::new(Cache::<String>::new(Duration::from_secs(60))));

    for transaction in transactions {
        if let Some(cached_status) = cache.lock().unwrap().get(transaction.transaction_id) {
            info!("Using cached status for transaction {}: {}", transaction.transaction_id, cached_status);
            continue;
        }

        match payment_client.initiate_transaction(&transaction).await {
            Ok(_) => {
                // Retry mechanism with exponential backoff
                let mut attempt = 0u32;
                while attempt < 5 {
                    match payment_client.poll_status(transaction.transaction_id).await {
                        Ok(status) => {
                            transaction.status = status.clone();
                            cache.lock().unwrap().set(transaction.transaction_id, status);
                            info!("Transaction {} completed with status: {}", transaction.transaction_id, status);
                            break;
                        }
                        Err(e) => {
                            error!("Error polling status for transaction {}: {}. Retrying...", transaction.transaction_id, e);
                            sleep(Duration::from_secs(2u64.pow(attempt))).await;
                            attempt += 1;
                        }
                    }
                }

                if attempt == 5 {
                    return Err(format!("Transaction {} failed after retries", transaction.transaction_id));
                }
            }
            Err(e) => {
                error!("Error initiating transaction {}: {}", transaction.transaction_id, e);
                continue;
            }
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() {
    let transactions = vec![
        Transaction::new(1, "Merchant A"),
        Transaction::new(2, "Merchant B"),
    ];

    if let Err(e) = process_payment_transactions(transactions).await {
        error!("Error processing transactions: {}", e);
    }
}

