#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/nameser.h>
#include <resolv.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>

#define LOG_FILE "dns_log.txt"
#define MAX_CACHE_SIZE 100
#define DEFAULT_EXPIRATION_TIME (60 * 60) // 1 hour

typedef struct {
    char hostname[256];
    u_char ip[16];
    time_t timestamp;
} dns_cache_entry;

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static dns_cache_entry cache[MAX_CACHE_SIZE];
static int cache_size = MAX_CACHE_SIZE;
static unsigned long expiration_time = DEFAULT_EXPIRATION_TIME;

void load_config() {
    char *cache_size_str = getenv("DNS_CACHE_SIZE");
    if (cache_size_str) {
        cache_size = atoi(cache_size_str);
        if (cache_size > MAX_CACHE_SIZE) cache_size = MAX_CACHE_SIZE;
    }

    char *expiration_time_str = getenv("DNS_EXPIRATION_TIME");
    if (expiration_time_str) {
        expiration_time = strtoul(expiration_time_str, NULL, 10);
    }
}

void log_dns_query(const char *hostname, int status) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) return;

    time_t now = time(NULL);
    fprintf(log_file, "[%ld] DNS Query for '%s': %s\n", now, hostname, status == 0 ? "Success" : "Failure");

    fclose(log_file);

    // Log rotation
    if (ftell(log_file) > (10 * 1024 * 1024)) { // Rotate at 10MB
        rename(LOG_FILE, LOG_FILE ".1");
        freopen(LOG_FILE, "w", log_file);
    }
}

int cache_lookup(const char *hostname, u_char *ip) {
    pthread_mutex_lock(&cache_lock);

    time_t now = time(NULL);
    for (int i = 0; i < cache_size; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0 && difftime(now, cache[i].timestamp) < expiration_time) {
            memcpy(ip, cache[i].ip, sizeof(u_char) * 16);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return -1;
}

void update_cache(const char *hostname, const u_char *ip) {
    pthread_mutex_lock(&cache_lock);

    time_t now = time(NULL);
    for (int i = 0; i < cache_size; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(cache[i].ip, ip, sizeof(u_char) * 16);
            cache[i].timestamp = now;
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }

    // Evict oldest entry
    int oldest_index = -1;
    time_t oldest_time = now;
    for (int i = 0; i < cache_size; ++i) {
        if (difftime(now, cache[i].timestamp) > oldest_time) {
            oldest_index = i;
            oldest_time = cache[i].timestamp;
        }
    }

    if (oldest_index != -1) {
        strcpy(cache[oldest_index].hostname, hostname);
        memcpy(cache[oldest_index].ip, ip, sizeof(u_char) * 16);
        cache[oldest_index].timestamp = now;
    }

    pthread_mutex_unlock(&cache_lock);
}

int resolve_hostname(const char *hostname, u_char *ip) {
    if (cache_lookup(hostname, ip) == 0) return 0;

    int h_errnop;
    hostent *he = gethostbyname_r(hostname, NULL, NULL, sizeof(struct hostent), &h_errnop);

    if (he != NULL) {
        struct in_addr addr;
        memcpy(&addr, he->h_addr_list[0], sizeof(struct in_addr));
        memcpy(ip, &addr.s_addr, 4);
        update_cache(hostname, ip);
        log_dns_query(hostname, 0);
        return 0;
    } else {
        log_dns_query(hostname, -1);
        return h_errnop;
    }
}

int main() {
    load_config();

    u_char ip[16] = {0};
    if (resolve_hostname("example.com", ip) == 0) {
        printf("IP: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
