#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 100

typedef struct {
    long *data;
    int key;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    pthread_mutex_t lock;
    int count;
} RecordManager;

RecordManager manager = { .count = 0 };

void init_record_manager() {
    pthread_mutex_init(&manager.lock, NULL);
}

void destroy_record_manager() {
    for (int i = 0; i < manager.count; ++i) {
        free(manager.records[i].data);
    }
    pthread_mutex_destroy(&manager.lock);
}

int add_record(RecordManager *rm, long *new_data, int size, int key) {
    pthread_mutex_lock(&rm->lock);

    if (rm->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&rm->lock);
        return -1; // Memory full
    }

    for (int i = 0; i < rm->count; ++i) {
        if (rm->records[i].key == key) {
            free(rm->records[i].data); // Free existing data to prevent leaks
            rm->records[i].data = malloc(size * sizeof(long));
            memcpy(rm->records[i].data, new_data, size * sizeof(long));
            pthread_mutex_unlock(&rm->lock);
            return i; // Key already exists, update it
        }
    }

    Record *new_record = &rm->records[rm->count++];
    new_record->key = key;
    new_record->data = malloc(size * sizeof(long));
    memcpy(new_record->data, new_data, size * sizeof(long));

    pthread_mutex_unlock(&rm->lock);
    return rm->count - 1; // Return index of the new record
}

long* get_record(RecordManager *rm, int key) {
    pthread_mutex_lock(&rm->lock);

    for (int i = 0; i < rm->count; ++i) {
        if (rm->records[i].key == key) {
            long *data_copy = malloc(sizeof(long) * (sizeof(*(rm->records[i].data))));
            memcpy(data_copy, rm->records[i].data, sizeof(long) * (sizeof(*(rm->records[i].data))));
            pthread_mutex_unlock(&rm->lock);
            return data_copy; // Return a copy of the data
        }
    }

    pthread_mutex_unlock(&rm->lock);
    return NULL; // Key not found
}

void remove_record(RecordManager *rm, int key) {
    pthread_mutex_lock(&rm->lock);

    for (int i = 0; i < rm->count; ++i) {
        if (rm->records[i].key == key) {
            free(rm->records[i].data);
            memmove(&rm->records[i], &rm->records[i + 1], (rm->count - i - 1) * sizeof(Record));
            --rm->count;
            pthread_mutex_unlock(&rm->lock);
            return;
        }
    }

    pthread_mutex_unlock(&rm->lock);
}
