#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <net/if.h>

#define MAX_INTERFACES 256

typedef struct {
    char *name;
    int status; // Example: 0 for down, 1 for up
} status_record;

typedef enum {
    INTERFACE_ERROR_NONE = 0,
    INTERFACE_ERROR_NOMEM,
    INTERFACE_ERROR_INVALID_NAME,
    INTERFACE_ERROR_NOT_ALLOWED
} interface_error_t;

interface_error_t manage_network_interfaces(
    struct ifreq **ifr_array,
    int *status_flags,
    size_t *num_interfaces,
    status_record **status_records,
    const char ***allowed_interfaces,
    void (*get_allowed_interfaces)(const char ***)
) {
    interface_error_t error = INTERFACE_ERROR_NONE;

    // Retrieve allowed interfaces from external service
    get_allowed_interfaces(allowed_interfaces);

    if (!*allowed_interfaces || !*allowed_interfaces[0]) {
        fprintf(stderr, "Error retrieving allowed interfaces.\n");
        return INTERFACE_ERROR_INVALID_NAME;
    }

    // Check for memory reallocation needs and expand if necessary
    size_t current_capacity = *num_interfaces > 0 ? *num_interfaces : MAX_INTERFACES;

    if (*num_interfaces >= current_capacity) {
        size_t new_capacity = current_capacity * 2;

        struct ifreq *new_ifr_array = realloc(*ifr_array, new_capacity * sizeof(struct ifreq));
        int *new_status_flags = realloc(status_flags, new_capacity * sizeof(int));

        status_record *new_status_records = realloc(*status_records, new_capacity * sizeof(status_record));

        if (!new_ifr_array || !new_status_flags || !new_status_records) {
            error = INTERFACE_ERROR_NOMEM;
            fprintf(stderr, "Memory allocation failed.\n");
            goto cleanup;
        }

        *ifr_array = new_ifr_array;
        status_flags = new_status_flags;
        *status_records = new_status_records;

        current_capacity = new_capacity;
    }

    // Add, remove or modify interfaces
    for (size_t i = 0; i < *num_interfaces; ++i) {
        const char **allowed_it = allowed_interfaces[0];
        while (*allowed_it) {
            if (strcmp((*ifr_array)[i].ifr_name, *allowed_it) == 0) {
                // Interface is allowed
                (*status_records)[i].name = strdup((*ifr_array)[i].ifr_name);
                (*status_records)[i].status = status_flags[i]; // Example: fetch real status

                break;
            }
            ++allowed_it;
        }

        if (!(*status_records)[i].name) {
            error = INTERFACE_ERROR_NOT_ALLOWED;
