```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define constants for log entry types and maximum payload size
#define ENTRY_INSERT 1
#define ENTRY_UPDATE 2
#define ENTRY_DELETE 3

#define MAX_PAYLOAD_SIZE 256

typedef struct LogEntry {
    int version;
    time_t timestamp;
    int entry_type; // INSERT, UPDATE, DELETE
    char key[64];
    char *payload;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
    size_t count;
    const unsigned long max_entries; // Max entries before compaction
    const size_t max_size;           // Max payload size for auto-compaction
} LogDB;

// Helper function to generate a random string of given length
char* generate_random_payload(size_t length) {
    if (length == 0) return NULL;

    char *payload = malloc(length + 1);
    if (!payload) return NULL;

    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789!@#$%^&*()-_=+[{]}|;:,.<>?";

    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        payload[i] = charset[key];
    }
    payload[length] = '\0';

    return payload;
}

// Function to initialize the log with specified number of entries
LogDB* init_log(unsigned long max_entries, size_t max_size, unsigned int num_initial_entries) {
    LogDB *log_db = malloc(sizeof(LogDB));
    if (!log_db) return NULL;

    log_db->head = NULL;
    pthread_mutex_init(&log_db->lock, NULL);
    log_db->count = 0;
    log_db->max_entries = max_entries;
    log_db->max_size = max_size;

    // Initialize with specified number of entries
    for (unsigned int i = 0; i < num_initial_entries; ++i) {
        size_t payload_length = rand() % (int)(MAX_PAYLOAD_SIZE + 1);
        char *key = "initial_key"; // Placeholder key

        add_entry(log_db, generate_random_payload(payload_length), ENTRY_INSERT, key);

        if (log_db->count >= max_entries || log_db->head->payload && strlen(log_db->head->payload) > max_size) {
            compact_log(log_db);
        }
    }

    return log_db;
}

// Function to add an entry
void add_entry(LogDB *db, char* payload, int type, const char *key) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) return;

    pthread_mutex_lock(&db->lock);

    entry->version = db->count + 1;
    entry->timestamp = time(NULL);
    entry->entry_type = type;
    strncpy(entry->key, key, sizeof(entry->key) - 1);
    entry->payload = payload;
    entry->next = db->head;

    db->head = entry;
    db->count++;

    pthread_mutex_unlock(&db->lock);
}

// Function to compact the log
void compact_log(LogDB *db) {
    // Placeholder: Implement compaction logic based on specific policies
    printf("Compacting log...\n");

    LogEntry **current = &(db->head);

    while (*current) {
        if (strlen((*current)->payload) > db->max_size) {
            LogEntry *temp = *current;
            *current = (*current)->next;

            free(temp->payload);
            free(temp);
        } else {
            current = &(*current)->next;
        }
    }

    // Reset count after compaction
    db->count = 0;
}

// Function to query log entries
void query_log(LogDB *db, int entry_type, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&db->lock);

    LogEntry *current = db->head;
    while (current) {
        if (current->entry_type == entry_type &&
            current->timestamp >= start_time && 
            current->timestamp <= end_time) {
            printf("Version: %d, Type: %d, Key: %s, Payload: %s\n", 
                   current->version, current->entry_type,
                   current->key, current->payload);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&db->lock);
}

// Function to cleanup and free resources
void destroy_log(LogDB *log_db) {
    LogEntry *current = log_db->head;

    while (current) {
        LogEntry *temp = current;
        current = current->next;

        free(temp->payload);
        free(temp);
    }

    pthread_mutex_destroy(&log_db->lock);
    free(log_db);
}

// Main function for demonstration
int main() {
    srand(time(NULL));

    unsigned long max_entries = 1000;
    size_t max_size = 128;
    unsigned int initial_entries = 10;

    LogDB *db = init_log(max_entries, max_size, initial_entries);

    query_log(db, ENTRY_INSERT, time(NULL) - 3600, time(NULL)); // Query last hour

    destroy_log(db);

    return 0;
}
```

### Key Considerations:
1. **Concurrency and Locking**: A simple mutex (`pthread_mutex_t`) is used to ensure thread safety during log operations like adding entries or querying logs. For advanced lock-free implementations, you might consider using atomic operations.
2. **Compaction**: Placeholder for compaction logic based on policy thresholds (like max entries or payload size).
3. **Memory Management**: Each entry allocates memory for its payload dynamically, and compaction involves freeing excessive entries to maintain a manageable memory footprint.
4. **Initialization**: The log is initialized with random payloads as specified.

This code provides the basic structure and mechanics of the distributed database log. In a production environment, consider using libraries for advanced synchronization, network communication between nodes, error handling, and more robust compaction strategies.']

