```csharp
// MemoryManager.cs

using System;
using System.Collections.Concurrent;

public class MemoryManager<T> where T : struct
{
    private ConcurrentBag<byte[]> memoryPool;
    private int blockSize;

    public MemoryManager(int initialSize, int blockSize)
    {
        this.blockSize = blockSize;
        memoryPool = new ConcurrentBag<byte[]>();

        for (int i = 0; i < initialSize; i++)
        {
            memoryPool.Add(new byte[blockSize]);
        }
    }

    public T Allocate()
    {
        if (!memoryPool.TryTake(out var block))
        {
            block = new byte[blockSize];
        }
        return MemoryMarshal.Cast<byte, T>(block)[0];
    }

    public void Free(T item)
    {
        var bytes = MemoryMarshal.AsBytes(item);
        memoryPool.Add(bytes);
    }
}

public class Sensor
{
    // Define sensor attributes
}
