fn initializeAndManageRecords(num_records: usize, range_min: i32, range_max: i32) -> Result<Arc<Mutex<Vec<Record>>>, &'static str> {
    // Allocate memory for arrays
    let offsets = vec![0; num_records];
    let keys = vec![0; num_records];

    // Initialize records with random values and pointers
