impl ServiceMeshClient {
    fn new(service_name: &str) -> Self {
        let client = Client::new();
        let semaphore = Arc::new(Semaphore::new(100)); // adjust concurrency limit
        ServiceMeshClient { client, semaphore }
    }

    async fn send_request(&self, req: Request) -> Result<(), String> {
        let _permit = self.semaphore.acquire().await.unwrap();

        match self.client.request(req.method.as_str(), &req.endpoint)
            .body(req.payload.clone())
            .send()
            .await
