['```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
import <stdatomic.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 256
#define INITIAL_ENTRIES 1000
#define ENTRY_MAX_COUNT 1000000

typedef enum {
    INSERT,
    UPDATE,
    DELETE
} OperationType;

typedef struct LogEntry {
    time_t timestamp;
    OperationType type;
    int key_id;
    char *payload;
    unsigned long version;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    atomic_uint count;
    volatile size_t total_payload_size;
    LogEntry *head;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    size_t max_total_size;
    int capacity; // Maximum number of entries
} LogQueue;

LogQueue* create_log_queue(size_t initial_entries, size_t max_total_size) {
    LogQueue *queue = (LogQueue*)malloc(sizeof(LogQueue));
    if (!queue) return NULL;

    queue->count = 0;
    queue->total_payload_size = 0;
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    queue->max_total_size = max_total_size;
    queue->capacity = ENTRY_MAX_COUNT;

    for (size_t i = 0; i < initial_entries; ++i) {
        if (!enqueue_entry(queue)) return NULL;
    }

    return queue;
}

int enqueue_entry(LogQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (atomic_load(&queue->count) >= queue->capacity || 
           queue->total_payload_size + MAX_PAYLOAD_SIZE > queue->max_total_size) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    size_t payload_size = rand() % (MAX_PAYLOAD_SIZE + 1);
    char *payload = (char*)malloc(payload_size + 1);

    if (!payload) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    for(size_t i = 0; i < payload_size; ++i) {
        payload[i] = rand() % ('~' - ' ') + ' ';
    }
    payload[payload_size] = '\0';

    LogEntry *new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!new_entry) {
        free(payload);
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    new_entry->timestamp = time(NULL);
    new_entry->type = rand() % 3;
    new_entry->key_id = rand();
    new_entry->payload = payload;
    new_entry->version = atomic_fetch_add(&queue->count, 1) + 1;
    new_entry->next = queue->head;

    queue->total_payload_size += payload_size;
    queue->head = new_entry;

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

LogEntry* dequeue_entry(LogQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (atomic_load(&queue->count) == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    LogEntry *entry = queue->head;
    if (!entry) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    queue->head = entry->next;
    queue->total_payload_size -= strlen(entry->payload);

    atomic_fetch_sub(&queue->count, 1);

    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);

    LogEntry *temp_entry = entry;
    free(temp_entry->payload);
    free(temp_entry);

    return temp_entry;
}

void compact_log(LogQueue *queue) {
    // Implement a compaction strategy here
}

void destroy_log_queue(LogQueue *queue) {
    while (dequeue_entry(queue));

    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}

void* producer(void *arg) {
    LogQueue *queue = (LogQueue*)arg;

    while (1) {
        enqueue_entry(queue);
        sleep(1); // Simulate work
    }

    return NULL;
}

void* consumer(void *arg) {
    LogQueue *queue = (LogQueue*)arg;

    while (1) {
        LogEntry *entry = dequeue_entry(queue);

        if (entry) {
            printf("Processed Entry: %s\n", entry->payload);
            free(entry); // Memory management
        }

        sleep(2); // Simulate work
    }

    return NULL;
}

int main() {
    LogQueue *queue = create_log_queue(INITIAL_ENTRIES, 10 * MAX_PAYLOAD_SIZE);

    pthread_t prod_thread, cons_thread;

    pthread_create(&prod_thread, NULL, producer, queue);
    pthread_create(&cons_thread, NULL, consumer, queue);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    destroy_log_queue(queue);

    return 0;
}
```

