#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

#define MAX_RECORDS 10000000
#define COMPACT_THRESHOLD 0.8

typedef struct {
    record **records;
    atomic_size_t size;
    atomic_size_t capacity;
    pthread_mutex_t mutex;
} RecordCollection;

// Function prototypes
void initialize_collection(RecordCollection *collection, size_t initial_capacity);
record* find_by_index(const RecordCollection *collection, size_t index);
record* find_by_key(const RecordCollection *collection, int key, int tolerance);
void insert_or_update_record(RecordCollection *collection, int value, long offset, int key);
void compact_collection(RecordCollection *collection);

// Initialize the record collection
void initialize_collection(RecordCollection *collection, size_t initial_capacity) {
    collection->records = calloc(initial_capacity, sizeof(record*));
    atomic_store(&collection->size, 0);
    atomic_store(&collection->capacity, initial_capacity);
    pthread_mutex_init(&collection->mutex, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        record *rec = malloc(sizeof(record));
        rec->value = rand() % 1000; // Random value between 0 and 999
        rec->offset = malloc(sizeof(long));
        *rec->offset = (long)i;
        rec->key = malloc(sizeof(int));
        *rec->key = (int)(i % 500); // Example key generation logic
        collection->records[i] = rec;
    }
}

// Find a record by index
record* find_by_index(const RecordCollection *collection, size_t index) {
    if (index >= atomic_load(&collection->size)) return NULL;

    record **records = collection->records;
    return records[index];
}

// Find a record by key within tolerance
record* find_by_key(const RecordCollection *collection, int key, int tolerance) {
    for (size_t i = 0; i < atomic_load(&collection->size); ++i) {
        record *rec = collection->records[i];
        if (abs(rec->key[0] - key) <= tolerance)
            return rec;
    }
    return NULL;
}

// Insert or update a record
void insert_or_update_record(RecordCollection *collection, int value, long offset, int key) {
    pthread_mutex_lock(&collection->mutex);

    size_t index = atomic_load(&collection->size);
    if (index >= atomic_load(&collection->capacity)) {
        compact_collection(collection); // Trigger compaction if needed
    }

    record **records = collection->records;
    records[index] = malloc(sizeof(record));
    records[index]->value = value;
    records[index]->offset = malloc(sizeof(long));
    *records[index]->offset = offset;
    records[index]->key = malloc(sizeof(int));
    *records[index]->key = key;

    atomic_fetch_add(&collection->size, 1);

    pthread_mutex_unlock(&collection->mutex);
}

// Compact the collection if needed
void compact_collection(RecordCollection *collection) {
    size_t new_capacity = atomic_load(&collection->capacity) * 2;
    record **new_records = realloc(collection->records, new_capacity * sizeof(record*));

    if (new_records) {
        atomic_store(&collection->records, new_records);
        atomic_store(&collection->capacity, new_capacity);
    }
}

// Simulate failure scenarios and recovery
void simulate_failures(RecordCollection *collection) {
    // Example: Randomly delete a record to test resilience
    size_t index = rand() % atomic_load(&collection->size);
    pthread_mutex_lock(&collection->mutex);

    if (index < atomic_load(&collection->size)) {
        free(collection->records[index]->offset);
        free(collection->records[index]->key);
        free(collection->records[index]);
        collection->records[index] = NULL;
        for (size_t i = index; i < atomic_load(&collection->size) - 1; ++i) {
            collection->records[i] = collection->records[i + 1];
            collection->records[i + 1] = NULL;
        }
        atomic_fetch_sub(&collection->size, 1);
    }

    pthread_mutex_unlock(&collection->mutex);
}

int main() {
    RecordCollection collection;
    initialize_collection(&collection, 1000);

    // Example usage
    insert_or_update_record(&collection, 42, 123456789L, 7);
    record *rec = find_by_key(&collection, 7, 1);
    if (rec) printf("Found record with key %d: value=%d\n", rec->key[0], rec->value);

    simulate_failures(&collection);

    // Clean up
    for (size_t i = 0; i < atomic_load(&collection->size); ++i) {
        free(collection.records[i]->offset);
        free(collection.records[i]->key);
        free(collection.records[i]);
    }
    free(collection.records);
    pthread_mutex_destroy(&collection.mutex);

    return 0;
}
```

This code provides a basic implementation of the described system. It includes functions for initializing, finding, inserting/updating, and compacting records within a collection. Concurrency control is managed using mutexes, and memory management ensures proper allocation and deallocation. The `simulate_failures` function demonstrates resilience by handling record deletions. Further enhancements could include integrating with distributed systems and implementing more sophisticated error recovery strategies.']

