#[derive(Clone)]
struct RetryStrategy {
    max_retries: usize,
    base_delay: Duration,
}

impl Default for RetryStrategy {
    fn default() -> Self {
        RetryStrategy {
            max_retries: 3,
            base_delay: Duration::from_secs(1),
        }
    }
}

async fn process_feedback(feedback_client: FeedbackClient, feedback: Feedback) -> Result<(), reqwest::Error> {
    let mut attempt = 0;
    loop {
        match feedback_client.submit_feedback(&feedback).await {
            Ok(_) => return Ok(()),
            Err(e) if attempt < feedback_client.retry_strategy.max_retries => {
                attempt += 1;
                error!("Attempt {}: Error submitting feedback - {}", attempt, e);
                time::sleep(feedback_client.retry_strategy.base_delay * attempt.into()).await;
            }
            Err(e) => return Err(e),
        }
    }
}

