                       int min_val, int max_val) {
    if (n <= 0) return -1; // Handle edge cases

    // Allocate memory for the arrays and struct array
    long_array = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    records = (record **)malloc(n * sizeof(record *));
