void* initialize_records(size_t n, long min_val, long max_val) {
    if (n == 0 || n > SIZE_MAX / sizeof(long)) return NULL;

    // Allocate memory for arrays
    long *long_array = malloc(n * sizeof(long));
    int *keys_array = malloc(n * sizeof(int));
    record *records_array = malloc(n * sizeof(record));

    if (!long_array || !keys_array || !records_array) {
        free(long_array);
        free(keys_array);
        free(records_array);
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < n; ++i) {
        long_array[i] = i;
        keys_array[i] = i;
        records_array[i].value = generate_random(min_val, max_val);
    }

    // Return a pointer to the allocated memory block containing all arrays
    return malloc(sizeof(long*) * 3 + sizeof(int*) * 1 + sizeof(record*) * 1 +
                  (n * sizeof(long)) + (n * sizeof(int)) + (n * sizeof(record)));
}

void free_records(void* data) {
    if (!data) return;

    // Extract pointers from the allocated block
    long **long_array_ptr = (long**)((char*)data);
    int **keys_array_ptr = (int**)(((char*)data) + sizeof(long*) * 3);
    record **records_array_ptr = (record**)(((char*)data) + sizeof(long*) * 3 + sizeof(int*) * 1);

    // Extract actual arrays
    long *long_array = *long_array_ptr;
    int *keys_array = *keys_array_ptr;
    record *records_array = *records_array_ptr;

    // Free the allocated memory
    free(long_array);
    free(keys_array);
    free(records_array);
    free(data);
}

// Placeholder for generate_random function using external library
int generate_random(int min_val, int max_val) {
    return rand() % (max_val - min_val + 1) + min_val;
}

// Example usage of resource monitoring
void monitor_resources(void (*operation)(size_t, long, long), size_t n, long min_val, long max_val) {
    // Monitor memory and CPU usage before operation
    printf("Monitoring resources...\n");

    // Execute the operation
    void *result = operation(n, min_val, max_val);

    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed or invalid input.\n");
        return;
    }

    // Monitor memory and CPU usage after operation
    printf("Operation completed. Resources freed...\n");

    // Free allocated resources
    free_records(result);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    size_t n = 1000;   // Example size
    long min_val = 1, max_val = 100;

    monitor_resources(initialize_records, n, min_val, max_val);

    return 0;
}
