fn manageLogProcessingPipeline(num_records: usize, range_min: i32, range_max: i32) -> Arc<Mutex<Vec<Record>>> {
    let mut rng = rand::thread_rng();

    // Initialize data structures
    let offsets: Vec<u64> = (0..num_records).map(|i| i as u64 * 100).collect(); // Example pattern
    let keys: Vec<i32> = (0..num_records).map(|i| i as i32 + 1).collect();

    let records: Arc<Mutex<Vec<Record>>> = Arc::new(Mutex::new(vec![
        Record {
            value: rng.gen_range(range_min..=range_max),
            offset_ptr: offsets.as_ptr(),
            key_ptr: keys.as_ptr(),
        }; num_records
    ]));

    // Compacting mechanism for empty records (simulated)
    let mut compacted_records = Vec::with_capacity(num_records);

    {
        let mut recs = records.lock().unwrap();
        let mut last_empty_idx = None;

        for (i, record) in recs.iter().enumerate() {
            if record.value == 0 {
                if last_empty_idx.is_none() {
                    last_empty_idx = Some(i);
                }
            } else {
                if let Some(start_idx) = last_empty_idx {
                    compacted_records.push(Record {
                        value: 0, // Marking as empty
                        offset_ptr: recs[start_idx].offset_ptr,
                        key_ptr: recs[start_idx].key_ptr,
                    });
                }
                for j in (start_idx + 1)..=i {
                    compacted_records.push(recs[j].clone());
                }
                last_empty_idx = None;
