        }

        if let Some(start_idx) = last_empty_idx {
            compacted_records.push(Record {
                value: 0, // Marking as empty
                offset_ptr: recs[start_idx].offset_ptr,
                key_ptr: recs[start_idx].key_ptr,
            });
        }

        *recs = compacted_records;
    }

    records
}

