#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float value;
    char *buffer;
    size_t buffer_size;
    time_t timestamp;
} Entry;

typedef struct {
    Entry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

// External logging service
void log_allocation_failure(const char *message) {
    // Placeholder for actual logging mechanism
    fprintf(stderr, "LOG: %s\n", message);
}

DynamicList* initialize_list(size_t initial_capacity, float min_val, float max_val, size_t str_len) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        log_allocation_failure("Failed to allocate memory for list structure");
        return NULL;
    }

    list->entries = (Entry*)calloc(initial_capacity, sizeof(Entry));
    if (!list->entries) {
        free(list);
        log_allocation_failure("Failed to allocate memory for entries array");
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        float random_val = min_val + ((max_val - min_val) * rand() / RAND_MAX);
        list->entries[i].value = random_val;

        list->entries[i].buffer_size = str_len;
        list->entries[i].buffer = (char*)malloc(str_len);
        if (!list->entries[i].buffer) {
            log_allocation_failure("Failed to allocate memory for entry buffer");
            continue; // Allow partial initialization
        }

        for (size_t j = 0; j < str_len; ++j) {
            list->entries[i].buffer[j] = 'a' + rand() % 26;
        }

        list->entries[i].timestamp = time(NULL);
    }

    return list;
}

void resize_buffer(Entry *entry, size_t new_size) {
    char *new_buffer = (char*)realloc(entry->buffer, new_size);
    if (!new_buffer) {
        log_allocation_failure("Failed to reallocate memory for entry buffer");
        return;
    }
    entry->buffer = new_buffer;
    entry->buffer_size = new_size;
}

void add_entry(DynamicList *list, float value, const char *data, size_t data_len) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Entry *new_entries = (Entry*)realloc(list->entries, new_capacity * sizeof(Entry));
        if (!new_entries) {
            log_allocation_failure("Failed to reallocate memory for entries array");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    Entry new_entry;
    new_entry.value = value;
    new_entry.buffer_size = data_len;
    resize_buffer(&new_entry, data_len);
    if (data_len > 0) {
        memcpy(new_entry.buffer, data, data_len);
    }
    new_entry.timestamp = time(NULL);

    list->entries[list->count++] = new_entry;

    pthread_mutex_unlock(&list->lock);
}

Entry* get_entry(DynamicList *list, size_t index) {
    if (index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);
    Entry *entry = &list->entries[index];
    pthread_mutex_unlock(&list->lock);

    return entry;
}

void update_entry(DynamicList *list, size_t index, float new_value, const char *new_data, size_t data_len) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Entry *entry = &list->entries[index];
    entry->value = new_value;

    if (data_len > entry->buffer_size) {
        resize_buffer(entry, data_len);
    }
    if (data_len > 0) {
        memcpy(entry->buffer, new_data, data_len);
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].buffer);
    }

    free(list->entries);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
