#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for file metadata
typedef struct {
    char *file_name;
    size_t file_size; // in bytes
    time_t timestamp; // last modified time
} FileMetadata;

// Node structure for the linked list
typedef struct Node {
    FileMetadata data;
    struct Node* next;
} Node;

// MetadataManager structure
typedef struct {
    Node* head; // Head of the linked list
    pthread_mutex_t lock; // Mutex for thread safety
} MetadataManager;

// Function to create a new metadata manager
MetadataManager* create_metadata_manager() {
    MetadataManager* manager = (MetadataManager*)malloc(sizeof(MetadataManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to free a metadata manager
void destroy_metadata_manager(MetadataManager* manager) {
    if (!manager) return;

    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current->data.file_name);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Function to add a new file metadata record
int add_metadata(MetadataManager* manager, const char* file_name, size_t file_size, time_t timestamp) {
    if (!manager || !file_name) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data.file_name = strdup(file_name);
    if (!new_node->data.file_name) {
        free(new_node);
        return -1;
    }

    new_node->data.file_size = file_size;
    new_node->data.timestamp = timestamp;

    pthread_mutex_lock(&manager->lock);

    // Insert in sorted order based on timestamp
    Node** current = &(manager->head);
    while (*current && (*current)->data.timestamp > timestamp) {
        current = &((*current)->next);
    }

    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

// Function to retrieve a record by file name
FileMetadata* get_metadata(MetadataManager* manager, const char* file_name) {
    if (!manager || !file_name) return NULL;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (strcmp(current->data.file_name, file_name) == 0) {
            FileMetadata* result = malloc(sizeof(FileMetadata));
            if (!result) {
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            *result = current->data;
            pthread_mutex_unlock(&manager->lock);
            return result; // Return a copy
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Function to delete a record by file name
int delete_metadata(MetadataManager* manager, const char* file_name) {
    if (!manager || !file_name) return -1;

    pthread_mutex_lock(&manager->lock);

    Node** current = &(manager->head);
    while (*current) {
        if (strcmp((*current)->data.file_name, file_name) == 0) {
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete->data.file_name);
            free(to_delete);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Not found
}

// Function to iterate over all records in reverse chronological order
void iterate_reverse_chronological(MetadataManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    if (!current) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Find the last node
    while (current->next) {
        current = current->next;
    }

    printf("Iterating in reverse chronological order:\n");
    while (current) {
        printf("File: %s, Size: %zu bytes, Timestamp: %ld\n",
               current->data.file_name,
               current->data.file_size,
               current->data.timestamp);
        current = (Node*)(((char*)current) - offsetof(Node, next));
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    MetadataManager* manager = create_metadata_manager();

    // Add some records
    add_metadata(manager, "file1.txt", 1024, time(NULL));
    add_metadata(manager, "file2.txt", 2048, time(NULL) - 3600);
    add_metadata(manager, "file3.txt", 512, time(NULL) - 7200);

    // Retrieve a record
    FileMetadata* metadata = get_metadata(manager, "file2.txt");
    if (metadata) {
        printf("Retrieved: %s, Size: %zu bytes\n", metadata->file_name, metadata->file_size);
        free(metadata); // Remember to free the returned copy
    }

    // Iterate in reverse chronological order
    iterate_reverse_chronological(manager);

    // Delete a record
    delete_metadata(manager, "file2.txt");

    // Clean up
    destroy_metadata_manager(manager);

    return 0;
}
```

### Key Points:
- **Data Structure**: A singly linked list is used for storing records. This allows efficient insertion in sorted order and iteration.
- **Thread Safety**: A mutex lock ensures thread-safe operations, which is crucial for high concurrent access environments.
- **Memory Management**: The code handles memory allocation failures gracefully by checking the return values of `malloc` and `strdup`.
