void rename_files(char **filenames, int count) {
    pthread_t threads[count];
    struct thread_data {
        char *filename;
        int index;
        int total;
    } data[count];

    // Thread function to process each file.
    void* process_file(void* arg) {
        struct thread_data *tdata = (struct thread_data *)arg;

        FileMetadata metadata = get_file_metadata(tdata->filename);
        const char *file_type = determine_file_type(&metadata);

        int seq_num = strlen(tdata->filename) + tdata->index;

        size_t new_name_len = strlen(tdata->filename) + 20; // Account for sequence number and file type
        char *new_name = malloc(new_name_len);
        if (!new_name) {
            fprintf(stderr, "Memory allocation failed.\n");
            pthread_exit(NULL);
        }

        snprintf(new_name, new_name_len, "%s_%d%s", tdata->filename, seq_num, file_type);

        printf("Renaming %s to %s\n", tdata->filename, new_name);

        // Free the allocated memory for the new filename
        free(new_name);
        pthread_exit(NULL);
