    for (int i = 0; i < count; ++i) {
        data[i].filename = filenames[i];
        data[i].index = i;
        data[i].total = count;

        if (pthread_create(&threads[i], NULL, process_file, &data[i]) != 0) {
            fprintf(stderr, "Error creating thread for %s\n", filenames[i]);
        }
    }

    // Join threads
    for (int i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

