['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for file metadata records
typedef struct FileMetadata {
    char *file_name;
    size_t file_size;
    time_t timestamp;
} FileMetadata;

// Define a node in the linked list
typedef struct Node {
    FileMetadata data;
    struct Node* next;
} Node;

// Define the list structure
typedef struct MetadataList {
    Node* head;
    pthread_mutex_t lock;
} MetadataList;

// Function prototypes
MetadataList* create_metadata_list();
void destroy_metadata_list(MetadataList* list);
int add_file_metadata(MetadataList* list, const char* file_name, size_t file_size, time_t timestamp);
FileMetadata* get_latest_file_metadata(MetadataList* list);
int delete_file_metadata_by_name(MetadataList* list, const char* file_name);
void iterate_reverse_chronologically(MetadataList* list);

// Create a new metadata list
MetadataList* create_metadata_list() {
    MetadataList* list = (MetadataList*)malloc(sizeof(MetadataList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the metadata list and free memory
void destroy_metadata_list(MetadataList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.file_name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new file metadata record
int add_file_metadata(MetadataList* list, const char* file_name, size_t file_size, time_t timestamp) {
    if (!file_name || !list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data.file_name = strdup(file_name);
    if (!new_node->data.file_name) {
        free(new_node);
        return -1;
    }
    new_node->data.file_size = file_size;
    new_node->data.timestamp = timestamp;

    pthread_mutex_lock(&list->lock);

    // Insert in reverse chronological order
    Node* current = list->head;
    Node** prev_next = &list->head;
    while (current && current->data.timestamp > timestamp) {
        prev_next = &(current->next);
        current = current->next;
    }

    new_node->next = current;
    *prev_next = new_node;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Retrieve the latest file metadata record
FileMetadata* get_latest_file_metadata(MetadataList* list) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    FileMetadata* result = (list->head ? &(list->head->data) : NULL);
    pthread_mutex_unlock(&list->lock);

    return result;
}

// Delete a file metadata record by name
int delete_file_metadata_by_name(MetadataList* list, const char* file_name) {
    if (!file_name || !list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current && strcmp(current->data.file_name, file_name) != 0) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current->data.file_name);
    free(current);

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Iterate over records in reverse chronological order
void iterate_reverse_chronologically(MetadataList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("File: %s, Size: %zu bytes, Timestamp: %ld\n",
               current->data.file_name,
               current->data.file_size,
               current->data.timestamp);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    MetadataList* list = create_metadata_list();
    if (!list) return EXIT_FAILURE;

    add_file_metadata(list, "file1.txt", 1234, time(NULL));
    add_file_metadata(list, "file2.txt", 5678, time(NULL) - 100);

    FileMetadata* latest = get_latest_file_metadata(list);
    if (latest) {
        printf("Latest file: %s\n", latest->file_name);
    }

    iterate_reverse_chronologically(list);

    delete_file_metadata_by_name(list, "file1.txt");
    iterate_reverse_chronologically(list);

    destroy_metadata_list(list);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the specified module. It uses a linked list to store file metadata records in reverse chronological order and utilizes mutexes for thread safety. The operations include adding, retrieving, deleting, and iterating over records. Further enhancements such as logging integration, cache invalidation, batch processing, and error handling would be needed for a production-ready system.']

