#include <stdio.h>
#include <stdlib.h>
import threading

// Define structures for record and metadata
typedef struct Record {
    int value;
} Record;

typedef struct MetaData {
    long offset_ptr;
    int key_ptr;
    char additional_metadata[256];
} MetaData;

typedef struct Entry {
    long offset;
    int key;
    Record record;
    MetaData metaData;
} Entry;

// Global collection and mutex for thread safety
#define MAX_RECORDS 10000000
Entry *entries = NULL;
int entry_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void add_record(long offset, int key, Record record, char* metadata);
Entry* get_record_by_index(int index);
Entry* get_record_by_key(int key);
void serialize_to_file(const char *filename);
void deserialize_from_file(const char *filename);

// Add a new record to the collection
void add_record(long offset, int key, Record record, char* metadata) {
    pthread_mutex_lock(&lock);

    if (entry_count >= MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Allocate or reallocate memory for entries
    if (!entries) {
        entries = (Entry *)malloc(MAX_RECORDS * sizeof(Entry));
    } else {
        Entry *new_entries = (Entry *)realloc(entries, (entry_count + 1) * sizeof(Entry));
        if (!new_entries) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
        entries = new_entries;
    }

    // Add the new entry
    entries[entry_count].offset = offset;
    entries[entry_count].key = key;
    entries[entry_count].record.value = record.value;
    entries[entry_count].metaData.offset_ptr = &entries[entry_count].offset;
    entries[entry_count].metaData.key_ptr = &entries[entry_count].key;
    snprintf(entries[entry_count].metaData.additional_metadata, sizeof(entries[entry_count].metaData.additional_metadata), "%s", metadata);

    entry_count++;

    pthread_mutex_unlock(&lock);
}

// Retrieve a record by index
Entry* get_record_by_index(int index) {
    if (index < 0 || index >= entry_count) {
        fprintf(stderr, "Error: Index out of range.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    Entry *result = &entries[index];
    pthread_mutex_unlock(&lock);

    return result;
}

// Retrieve a record by key
Entry* get_record_by_key(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < entry_count; i++) {
        if (entries[i].key == key) {
            pthread_mutex_unlock(&lock);
            return &entries[i];
        }
    }

    pthread_mutex_unlock(&lock);
    fprintf(stderr, "Error: Key not found.\n");
    return NULL;
}

// Serialize the collection to a file
void serialize_to_file(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    size_t written = fwrite(entries, sizeof(Entry), entry_count, file);

    if (written != entry_count) {
        fprintf(stderr, "Error: Serialization failed.\n");
    } else {
        // Write additional metadata about the collection
        int count_written = fwrite(&entry_count, sizeof(int), 1, file);
        if (!count_written) {
            fprintf(stderr, "Error: Failed to write record count.\n");
        }
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

// Deserialize the collection from a file
void deserialize_from_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for reading.\n");
        return;
    }

    // Free existing entries if any
    free(entries);
    entries = NULL;

    pthread_mutex_lock(&lock);

    // First read the count of records
    int stored_count;
    fread(&stored_count, sizeof(int), 1, file);

    // Allocate memory for entries
    entries = (Entry *)malloc(stored_count * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        fclose(file);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Read all records into memory
    size_t read = fread(entries, sizeof(Entry), stored_count, file);
    if (read != stored_count) {
        fprintf(stderr, "Error: Deserialization failed.\n");
    } else {
        entry_count = stored_count;
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

// Ensure to initialize the mutex in main
int main() {
    // Initialize and test your code here

    return 0;
}
