#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    bool status_flag;
} record;

// Logging function placeholder (integrate with your logging framework)
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Dynamic array structure
typedef struct {
    record *records;
    size_t capacity;
    pthread_mutex_t mutex; // For thread safety during resizing and updates
} RecordCollection;

// Function to initialize the random number generator
void init_random_seed() {
    srand((unsigned int)time(NULL));
}

// Function to create or resize a collection of records
RecordCollection* create_or_resize_collection(size_t num_records, size_t max_key, long max_offset) {
    if (num_records == 0 || max_key == 0 || max_offset <= 0)
        return NULL;

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        log_error("Failed to allocate memory for collection");
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    collection->capacity = num_records;
    collection->records = malloc(collection->capacity * sizeof(record));
    if (!collection->records) {
        free(collection);
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize records with unique keys and random offsets
    bool *key_taken = calloc(max_key, sizeof(bool));
    if (!key_taken) {
        free(collection->records);
        free(collection);
        log_error("Failed to allocate memory for key tracking");
        return NULL;
    }

    int count = 0;
    while (count < num_records) {
        int new_key = rand() % max_key;

        pthread_mutex_lock(&collection->mutex);
        if (!key_taken[new_key]) {
            collection->records[count].key = new_key;
            collection->records[count].offset = rand() % max_offset;
            collection->records[count].status_flag = false;

            key_taken[new_key] = true;
            count++;
        }
        pthread_mutex_unlock(&collection->mutex);
    }

    free(key_taken);

    return collection;
}

// Function to retrieve a record by its key
record* get_record_by_key(RecordCollection *collection, int key) {
    if (!collection || !collection->records)
        return NULL;

    for (size_t i = 0; i < collection->capacity; i++) {
        pthread_mutex_lock(&collection->mutex);
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->mutex);
            return &collection->records[i];
        }
        pthread_mutex_unlock(&collection->mutex);
    }

    return NULL;
}

// Function to free the collection
void destroy_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}
