#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

#define TABLE_SIZE 10007 // A prime number for better distribution in hash table

typedef struct Entry {
    char *key;
    int value;
} Entry;

typedef struct HashNode {
    Entry entry;
    struct HashNode *next;
} HashNode;

typedef struct StringPool {
    char **strings;
    size_t count;
    pthread_mutex_t lock;
} StringPool;

typedef struct DataManager {
    HashNode **table;
    StringPool string_pool;
    pthread_rwlock_t rwlock;
} DataManager;

// Helper function to generate a random Gaussian distributed number
int gaussian_rand(int mean, int stddev) {
    static int hasSpare = 0;
    static double spare;
    if (hasSpare) {
        hasSpare = 0;
        return mean + spare * stddev;
    }

    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;

    spare = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);
    hasSpare = 1;

    return mean + sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2) * stddev;
}

// Helper function to get string from pool or add it if not present
char* intern_string(StringPool *pool, const char *str) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (strcmp(pool->strings[i], str) == 0) {
            pthread_mutex_unlock(&pool->lock);
            return pool->strings[i];
        }
    }

    char *new_str = strdup(str);
    if (!new_str) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->strings = realloc(pool->strings, (pool->count + 1) * sizeof(char*));
    if (!pool->strings) {
        free(new_str);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->strings[pool->count++] = new_str;
    pthread_mutex_unlock(&pool->lock);

    return new_str;
}

// Hash function
unsigned int hash(int key, size_t table_size) {
    return (unsigned int)(key % table_size);
}

// Initialize data manager
DataManager* init_data_manager() {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->table = calloc(TABLE_SIZE, sizeof(HashNode*));
    if (!dm->table) {
        free(dm);
        return NULL;
    }

    dm->string_pool.strings = NULL;
    dm->string_pool.count = 0;
    pthread_mutex_init(&dm->string_pool.lock, NULL);

    pthread_rwlock_init(&dm->rwlock, NULL);
    return dm;
}

// Insert entry
int insert_entry(DataManager *dm, const char *key, int mean, int stddev) {
    if (!dm || !key) return -1;

    int value = gaussian_rand(mean, stddev);
    char *interned_key = intern_string(&dm->string_pool, key);
    if (!interned_key) return -1;

    pthread_rwlock_wrlock(&dm->rwlock);

    unsigned int index = hash(value, TABLE_SIZE);
    HashNode *node = dm->table[index];

    while (node) {
        if (strcmp(node->entry.key, interned_key) == 0) {
            node->entry.value = value;
            pthread_rwlock_unlock(&dm->rwlock);
            return 0; // Update existing
        }
        node = node->next;
    }

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_rwlock_unlock(&dm->rwlock);
        return -1;
    }

    new_node->entry.key = interned_key;
    new_node->entry.value = value;
    new_node->next = dm->table[index];
    dm->table[index] = new_node;

    pthread_rwlock_unlock(&dm->rwlock);
    return 0; // Insert successful
}

// Retrieve entry by key
int retrieve_entry(DataManager *dm, const char *key, int *value) {
    if (!dm || !key || !value) return -1;

    pthread_rwlock_rdlock(&dm->rwlock);

    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        HashNode *node = dm->table[i];
        while (node) {
            if (strcmp(node->entry.key, key) == 0) {
                *value = node->entry.value;
                pthread_rwlock_unlock(&dm->rwlock);
                return 0; // Found
            }
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&dm->rwlock);
    return -1; // Not found
}

// Remove entry by key
int remove_entry(DataManager *dm, const char *key) {
    if (!dm || !key) return -1;

    pthread_rwlock_wrlock(&dm->rwlock);

    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        HashNode **node_ptr = &dm->table[i];
        while (*node_ptr) {
            HashNode *node = *node_ptr;
            if (strcmp(node->entry.key, key) == 0) {
                *node_ptr = node->next;
                free(node);
                pthread_rwlock_unlock(&dm->rwlock);
                return 0; // Removed
            }
            node_ptr = &node->next;
        }
    }

    pthread_rwlock_unlock(&dm->rwlock);
    return -1; // Not found
}

// Compact storage to reclaim unused memory (simplified version)
void compact_storage(DataManager *dm) {
    if (!dm) return;

    pthread_rwlock_wrlock(&dm->rwlock);

    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        HashNode **node_ptr = &dm->table[i];
        while (*node_ptr) {
            HashNode *to_delete = *node_ptr;
            if (!strcmp(to_delete->entry.key, "dummy")) { // Assume 'dummy' means unused
                *node_ptr = to_delete->next;
                free(to_delete);
            } else {
                node_ptr = &(*node_ptr)->next;
            }
        }
    }

    pthread_rwlock_unlock(&dm->rwlock);
}

// Free resources
void destroy_data_manager(DataManager *dm) {
    if (!dm) return;

    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        HashNode *node = dm->table[i];
        while (node) {
            HashNode *next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_lock(&dm->string_pool.lock);
    for (size_t i = 0; i < dm->string_pool.count; ++i) {
        free(dm->string_pool.strings[i]);
    }
    free(dm->string_pool.strings);
    pthread_mutex_unlock(&dm->string_pool.lock);

    free(dm->table);
    pthread_rwlock_destroy(&dm->rwlock);
    pthread_mutex_destroy(&dm->string_pool.lock);
    free(dm);
}

// Test suite
void test_suite() {
    DataManager *dm = init_data_manager();
    if (!dm) return;

    insert_entry(dm, "key1", 50, 10);
    insert_entry(dm, "key2", 60, 15);

    int value;
    assert(retrieve_entry(dm, "key1", &value) == 0 && abs(value - 50) < 20);
    assert(retrieve_entry(dm, "key2", &value) == 0 && abs(value - 60) < 30);

    assert(remove_entry(dm, "key1") == 0);
    assert(retrieve_entry(dm, "key1", &value) == -1);

    compact_storage(dm); // Should not fail

    destroy_data_manager(dm);
}

int main() {
    test_suite();
    printf("All tests passed.\n");
    return 0;
}
