                // Populate arrays for fast lookup
                coll->keys_array[coll->num_records] = key;
                coll->offsets_array[coll->num_records] = coll->records[i].offset;

                coll->num_records++;
            }
        }
    }

    log_info("Collection initialized successfully");
    return coll;
}

void resize_collection(collection *coll, int new_capacity) {
    if (new_capacity <= coll->capacity) return;

    pthread_mutex_lock(&coll->lock);

    record *new_records = (record *)realloc(coll->records, new_capacity * sizeof(record));
    int *new_keys_array = (int *)realloc(coll->keys_array, new_capacity * sizeof(int));
    long *new_offsets_array = (long *)realloc(coll->offsets_array, new_capacity * sizeof(long));

