} RecordCollection;

// Utility function to initialize random number generator
void init_random() {
    srand((unsigned)time(NULL));
}

bool is_key_unique(int key, int *keys, size_t num_keys) {
    for (size_t i = 0; i < num_keys; ++i) {
        if (keys[i] == key) return false;
    }
    return true;
}

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        log_message("Failed to allocate memory for record collection");
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    collection->capacity = initial_capacity;

    collection->records = calloc(initial_capacity, sizeof(record));
    if (!collection->records) {
        free(collection);
        log_message("Failed to allocate memory for records");
        return NULL;
    }

    int *keys = malloc(sizeof(int) * initial_capacity);
    if (!keys) {
        free(collection->records);
        free(collection);
        log_message("Failed to allocate memory for keys array");
        return NULL;
    }

    init_random();

    pthread_mutex_lock(&collection->mutex);

    size_t num_records = 0;
    while (num_records < initial_capacity) {
        int key = rand() % initial_capacity; // Adjust range as needed
        if (is_key_unique(key, keys, num_records)) {
            collection->records[num_records].key = key;
            collection->records[num_records].offset = rand(); // Adjust max_offset as needed
            collection->records[num_records].status = true;
            keys[num_records] = key;
            ++num_records;
        }
    }

    pthread_mutex_unlock(&collection->mutex);

    free(keys);
    return collection;
}

bool resize_record_collection(RecordCollection *collection, size_t new_capacity) {
    if (!collection || new_capacity <= collection->capacity)
        return false;

    record *new_records = realloc(collection->records, new_capacity * sizeof(record));
    if (!new_records) {
        log_message("Failed to reallocate memory for records");
        return false;
    }

    int *new_keys = malloc(sizeof(int) * new_capacity);
    if (!new_keys) {
        free(new_records);
        collection->records = NULL;
        log_message("Failed to allocate memory for new keys array");
        return false;
    }

    pthread_mutex_lock(&collection->mutex);

    memcpy(new_keys, collection->keys, sizeof(int) * collection->capacity);
    memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record));

    size_t num_records = collection->capacity;

    while (num_records < new_capacity) {
        int key = rand() % new_capacity; // Adjust range as needed
        if (is_key_unique(key, new_keys, num_records)) {
            new_records[num_records].key = key;
            new_records[num_records].offset = rand(); // Adjust max_offset as needed
            new_records[num_records].status = true;
            new_keys[num_records] = key;
            ++num_records;
        }
    }

    free(collection->keys);
    collection->records = new_records;
    collection->capacity = new_capacity;
    collection->keys = new_keys;

    pthread_mutex_unlock(&collection->mutex);
    return true;
}

record* get_record_by_key(RecordCollection *collection, int key) {
    if (!collection)
        return NULL;

    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->records[i].key == key) {
            record *result = malloc(sizeof(record));
            if (result) {
                *result = collection->records[i];
            }
            pthread_mutex_unlock(&collection->mutex);
            return result;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    log_message("Key not found");
    return NULL;
}

void free_record_collection(RecordCollection *collection) {
    if (!collection)
        return;

    pthread_mutex_lock(&collection->mutex);

    free(collection->records);
    free(collection->keys);

    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
