#define DEFAULT_TEMP 25.0
#define SENSOR_ID "SENSOR_"
#define MAX_HISTORY 100

typedef struct {
    double temperature;
    uint32_t timestamp;
    char *sensor_id;
    float calibration;
} SensorData;

typedef struct {
    SensorData *sensors;
    size_t count;
    size_t capacity;
    size_t id_length;
    size_t history[MAX_HISTORY];
    int history_index;
} SensorList;

void log_change(const char *message) {
    printf("LOG: %s\n", message);
}

int resize_sensor_id(SensorList *list, size_t index, size_t new_size) {
    if (index >= list->count) return -1;

    char *new_buffer = realloc(list->sensors[index].sensor_id, new_size);
    if (!new_buffer) return -1;

    log_change("Sensor ID buffer resized");
    list->sensors[index].sensor_id = new_buffer;
    return 0;
}

int init_sensor_list(SensorList *list, size_t num_sensors, size_t id_length) {
    list->count = 0;
    list->capacity = num_sensors;
    list->id_length = id_length;

    list->sensors = (SensorData *)malloc(num_sensors * sizeof(SensorData));
    if (!list->sensors) return -1;

    for (size_t i = 0; i < num_sensors; ++i) {
        list->sensors[i].temperature = DEFAULT_TEMP;
        list->sensors[i].timestamp = 0;
        list->sensors[i].sensor_id = malloc(id_length);
        if (!list->sensors[i].sensor_id) {
            for (size_t j = 0; j < i; ++j) free(list->sensors[j].sensor_id);
            free(list->sensors);
            return -1;
        }
        strncpy(list->sensors[i].sensor_id, SENSOR_ID, id_length);
        list->sensors[i].sensor_id[id_length - 1] = '\0';
        list->sensors[i].calibration = 1.0f;

        log_change("Sensor initialized");
    }

    list->history_index = 0;
    for (int i = 0; i < MAX_HISTORY; ++i) {
        list->history[i] = -1;
    }

    return 0;
}

void update_sensor_id(SensorList *list, size_t index, const char *new_id) {
    if (index >= list->count) return;

    size_t new_size = strlen(new_id) + 1;
    if (new_size > list->id_length && resize_sensor_id(list, index, new_size) < 0) {
        fprintf(stderr, "Failed to resize sensor ID buffer\n");
        return;
    }

    strncpy(list->sensors[index].sensor_id, new_id, list->id_length);
    log_change("Sensor ID updated");
}

void update_calibration(SensorList *list, size_t index, float calibration) {
    if (index >= list->count) return;

    list->sensors[index].calibration = calibration;
    log_change("Sensor calibration updated");
}

double get_temperature_by_index(SensorList *list, size_t index) {
    if (index >= list->count) return -1.0;

    return list->sensors[index].temperature;
}

void set_temperature_by_index(SensorList *list, size_t index, double temperature) {
    if (index >= list->count) return;

    list->sensors[index].temperature = temperature;
    log_change("Sensor temperature updated");
}

double query_temperature_in_time_window(SensorList *list, uint32_t start_time, uint32_t end_time) {
    for (size_t i = 0; i < MAX_HISTORY && list->history[i] != -1; ++i) {
        size_t idx = list->history[i];
        if (idx >= list->count) continue;

        uint32_t timestamp = list->sensors[idx].timestamp;
        if (timestamp >= start_time && timestamp <= end_time) {
            return list->sensors[idx].temperature;
        }
    }

    return -1.0;
}

void record_history(SensorList *list, size_t index) {
    if (index >= list->count) return;

    list->history[list->history_index] = index;
    list->history_index = (list->history_index + 1) % MAX_HISTORY;
    log_change("Historical data recorded");
}

void free_sensor_list(SensorList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->sensors[i].sensor_id);
    }
    free(list->sensors);
    log_change("Sensor list freed");
}

// Example of handling periodic updates from external data source
void handle_periodic_updates(SensorList *list, const char **new_ids, float *new_calibrations) {
    for (size_t i = 0; i < list->count; ++i) {
        if (new_ids[i] && new_calibrations[i]) {
            update_sensor_id(list, i, new_ids[i]);
            update_calibration(list, i, new_calibrations[i]);
        }
    }
}
