#include <stdio.h>
#include <stdlib.h>
import <string.h>
import <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define BUFFER_INCREMENT 50

typedef struct {
    float value;
    char *buffer;
    time_t timestamp;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

// Utility function to generate a random float within a range
float rand_float(float min, float max) {
    return min + ((max - min) * rand() / (RAND_MAX + 1.0));
}

// Generate a random string of given length
void rand_string(char *buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length;
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            buffer[n] = charset[key];
        }
        buffer[length] = '\0';
    }
}

// Initialize the dynamic list
DynamicList* init_dynamic_list(size_t initial_capacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->entries = calloc(initial_capacity, sizeof(Entry));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Resize the dynamic list
void resize_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    Entry *new_entries = realloc(list->entries, new_capacity * sizeof(Entry));
    if (!new_entries) return; // Handle out-of-memory gracefully
    list->entries = new_entries;
    list->capacity = new_capacity;
}

// Add an entry to the dynamic list
void add_entry(DynamicList *list, float min_val, float max_val, size_t buffer_length) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_dynamic_list(list);
    }

    Entry *entry = &list->entries[list->count++];
    entry->value = rand_float(min_val, max_val);
    entry->buffer = malloc(buffer_length + 1);
    if (entry->buffer) {
        rand_string(entry->buffer, buffer_length);
    } else {
        list->count--; // Rollback the count increment on failure
    }
    entry->timestamp = time(NULL);

    pthread_mutex_unlock(&list->lock);
}

// Retrieve an entry by index
Entry* get_entry(DynamicList *list, size_t index) {
    if (index >= list->count) return NULL;
    pthread_mutex_lock(&list->lock);
    Entry *entry = &list->entries[index];
    pthread_mutex_unlock(&list->lock);
    return entry;
}

// Update an existing entry's data
void update_entry(DynamicList *list, size_t index, float new_value, char *new_data, size_t new_length) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->lock);

    Entry *entry = &list->entries[index];
    entry->value = new_value;

    // Resize buffer if necessary
    size_t old_length = strlen(entry->buffer);
    if (new_length > old_length) {
        entry->buffer = realloc(entry->buffer, new_length + 1);
        if (!entry->buffer) return; // Handle out-of-memory gracefully
    }
    strncpy(entry->buffer, new_data, new_length);
    entry->buffer[new_length] = '\0';
    entry->timestamp = time(NULL);

    pthread_mutex_unlock(&list->lock);
}

// Prune entries older than a certain age threshold (seconds)
void prune_entries(DynamicList *list, time_t age_threshold) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < list->count;) {
        if (current_time - list->entries[i].timestamp > age_threshold) {
            free(list->entries[i].buffer);
            memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(Entry));
            list->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the dynamic list
void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i].buffer);
    }

    free(list->entries);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example of updating from an external data source, to be integrated with actual network logic
void update_from_external_source(DynamicList *list) {
    // Simulate fetching and updating data
    for (size_t i = 0; i < list->count; i++) {
        pthread_mutex_lock(&list->lock);
        Entry *entry = &list->entries[i];
        entry->value += 1.0;
        rand_string(entry->buffer, 10); // Replace with actual fetched data
        entry->timestamp = time(NULL);
        pthread_mutex_unlock(&list->lock);
    }
}

// Periodic pruning function (to be called by a timer or separate thread)
void periodic_pruning(DynamicList *list) {
    while (1) {
        prune_entries(list, 3600); // Prune entries older than one hour
        sleep(60); // Run every minute
    }
}
