    return array;
}

// Function to resize the dynamic array
int resize_dynamic_array(dynamic_array *array, size_t new_capacity) {
    record *new_data = realloc(array->data, new_capacity * sizeof(record));
    if (!new_data) {
        log_error("Failed to reallocate memory for records.");
        return -1;
    }

    array->data = new_data;
    array->capacity = new_capacity;

    monitor_performance("Dynamic array resized to capacity: %zu", new_capacity);
    return 0;
}

// Function to add a record
int add_record(dynamic_array *array, record r) {
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        int resize_result = resize_dynamic_array(array, new_capacity);
        if (resize_result != 0) return -1; // Handle resize failure
    }

    array->data[array->size++] = r;

    monitor_performance("Record added. Current size: %zu", array->size);

    return 0;
}

// Function to retrieve a record by index
record* get_record(dynamic_array *array, size_t index) {
    if (index >= array->size) {
        log_error("Index out of bounds.");
        return NULL;
    }

    monitor_performance("Record retrieved at index: %zu", index);

    return &array->data[index];
}

// Function to update a record's value by index
int update_record(dynamic_array *array, size_t index, int new_value) {
    if (index >= array->size) {
        log_error("Index out of bounds.");
        return -1;
    }

    array->data[index].value = new_value;

    monitor_performance("Record updated at index: %zu", index);

    return 0;
}

// Function to search for a record by key
record* search_record_by_key(dynamic_array *array, int key) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].key == key) {
            monitor_performance("Record found with key: %d", key);
            return &array->data[i];
        }
    }

    log_error("Key not found.");
    return NULL;
}

// Function to free the dynamic array
void free_dynamic_array(dynamic_array *array) {
    if (array) {
        free(array->data);
        free(array);

        monitor_performance("Dynamic array memory freed.");
    }
}
