#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    char *file_name;
    size_t file_size;
    time_t timestamp;
} FileMetadata;

typedef struct {
    FileMetadata *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MetadataStore;

// Initialize the metadata store
MetadataStore* init_metadata_store(size_t initial_capacity) {
    MetadataStore *store = (MetadataStore *)malloc(sizeof(MetadataStore));
    if (!store) return NULL;

    store->records = (FileMetadata *)calloc(initial_capacity, sizeof(FileMetadata));
    if (!store->records) {
        free(store);
        return NULL;
    }

    store->capacity = initial_capacity;
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);

    // Initialize with random values for testing
    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        store->records[i].file_name = strdup("default");
        if (!store->records[i].file_name) {
            // Cleanup on error
            while (--i >= 0) free(store->records[i].file_name);
            free(store->records);
            pthread_mutex_destroy(&store->lock);
            free(store);
            return NULL;
        }
        store->records[i].file_size = rand() % 1000; // Random size for testing
        store->records[i].timestamp = time(NULL) - (rand() % 100); // Backdated timestamps
    }

    return store;
}

// Add a record to the metadata store
int add_record(MetadataStore *store, const char *file_name, size_t file_size, time_t timestamp) {
    pthread_mutex_lock(&store->lock);

    if (store->count >= store->capacity) {
        size_t new_capacity = store->capacity * 2;
        FileMetadata *new_records = (FileMetadata *)realloc(store->records, new_capacity * sizeof(FileMetadata));
        if (!new_records) {
            pthread_mutex_unlock(&store->lock);
            return -1; // Allocation failure
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }

    FileMetadata *record = &store->records[store->count++];
    record->file_name = strdup(file_name);
    if (!record->file_name) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Allocation failure
    }
    record->file_size = file_size;
    record->timestamp = timestamp;

    pthread_mutex_unlock(&store->lock);
    return 0;
}

// Retrieve a record by index
FileMetadata* get_record(MetadataStore *store, size_t index) {
    if (index >= store->count) return NULL;
    return &store->records[index];
}

// Delete a record by index
int delete_record(MetadataStore *store, size_t index) {
    pthread_mutex_lock(&store->lock);

    if (index >= store->count) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Invalid index
    }

    free(store->records[index].file_name); // Free the allocated string

    for (size_t i = index; i < store->count - 1; ++i) {
        store->records[i] = store->records[i + 1];
    }
    --store->count;

    pthread_mutex_unlock(&store->lock);
    return 0;
}

// Iterate over records in reverse chronological order
void iterate_reverse(MetadataStore *store, void (*callback)(FileMetadata *)) {
    pthread_mutex_lock(&store->lock);

    for (size_t i = store->count; i-- > 0;) {
        callback(&store->records[i]);
    }

    pthread_mutex_unlock(&store->lock);
}

// Compacting mechanism to merge consecutive empty records
void compact(MetadataStore *store) {
    pthread_mutex_lock(&store->lock);

    size_t write_index = 0;
    for (size_t read_index = 0; read_index < store->count; ++read_index) {
        if (store->records[read_index].file_name != NULL && strcmp(store->records[read_index].file_name, "default") != 0) {
            store->records[write_index++] = store->records[read_index];
        } else {
            free(store->records[read_index].file_name);
            store->records[read_index].file_name = NULL;
        }
    }

    store->count = write_index;

    pthread_mutex_unlock(&store->lock);
}

// Cleanup the metadata store
void cleanup_metadata_store(MetadataStore *store) {
    if (!store) return;
    for (size_t i = 0; i < store->count; ++i) {
        free(store->records[i].file_name);
    }
    free(store->records);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

// Example callback function
void print_record(FileMetadata *record) {
    if (record && record->file_name) {
        printf("File: %s, Size: %zu, Timestamp: %ld\n", record->file_name, record->file_size, record->timestamp);
    }
}

int main() {
    MetadataStore *store = init_metadata_store(INITIAL_CAPACITY);
    if (!store) return 1;

    add_record(store, "example.txt", 1234, time(NULL));
    iterate_reverse(store, print_record);

    cleanup_metadata_store(store);
    return 0;
}
```

### Key Features:
- **Dynamic Capacity**: Automatically expands when needed.
- **Thread Safety**: Uses mutex locks for concurrent access.
- **Error Handling**: Gracefully handles memory allocation failures.
- **Compaction**: Merges empty records to save space.
- **Reverse Iteration**: Allows iterating over records by timestamp in reverse order.

This implementation provides a robust foundation for managing file metadata efficiently. Adjustments can be made based on specific requirements, such as integrating with external systems or optimizing performance further.']

