// Define a structure for data entries
typedef struct {
    int timestamp;
    double value;
    char *metadata;
} dataEntry;

// Structure to manage dynamic collection of data entries
typedef struct {
    dataEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} DataCollection;

// Function prototypes
void initializeDataCollection(DataCollection *collection, size_t initialCapacity);
void freeDataCollection(DataCollection *collection);
int insertEntry(DataCollection *collection, int timestamp, double value, const char *metadata);
int updateEntry(DataCollection *collection, int timestamp, double newValue, const char *newMetadata);
void queryEntries(const DataCollection *collection, int minTimestamp, int maxTimestamp);

// Function to initialize the data collection
void initializeDataCollection(DataCollection *collection, size_t initialCapacity) {
    collection->entries = malloc(initialCapacity * sizeof(dataEntry));
    if (!collection->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initialCapacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

// Function to free the data collection
void freeDataCollection(DataCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i].metadata);
    }
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
}

// Function to insert a new entry
int insertEntry(DataCollection *collection, int timestamp, double value, const char *metadata) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        dataEntry *newEntries = realloc(collection->entries, newCapacity * sizeof(dataEntry));
        if (!newEntries) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&collection->lock);
            return -1; // Error code for memory allocation failure
        }
        collection->entries = newEntries;
        collection->capacity = newCapacity;
    }

    dataEntry *entry = &collection->entries[collection->count++];
    entry->timestamp = timestamp;
    entry->value = value;
    entry->metadata = strdup(metadata);
    if (!entry->metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&collection->lock);
        return -1; // Error code for memory allocation failure
    }

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

// Function to update an existing entry by timestamp
int updateEntry(DataCollection *collection, int timestamp, double newValue, const char *newMetadata) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i].timestamp == timestamp) {
            free(collection->entries[i].metadata);
            collection->entries[i].value = newValue;
            collection->entries[i].metadata = strdup(newMetadata);
            if (!collection->entries[i].metadata) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&collection->lock);
                return -1; // Error code for memory allocation failure
            }
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -2; // Entry not found
}

// Function to query entries based on a timestamp range
void queryEntries(const DataCollection *collection, int minTimestamp, int maxTimestamp) {
    pthread_mutex_lock((pthread_mutex_t *)&collection);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i].timestamp >= minTimestamp && 
            collection->entries[i].timestamp <= maxTimestamp) {
            printf("Timestamp: %d, Value: %.2f, Metadata: %s\n", 
                   collection->entries[i].timestamp,
                   collection->entries[i].value,
                   collection->entries[i].metadata);
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&collection);
}

// Helper function to calculate the average value from an array
double calculateAverage(const int *array, size_t length) {
    if (length == 0) return 0.0;

    long sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += array[i];
    }
    return (double)sum / length;
}

// Function to process a stream of integers from standard input
void processInputStream() {
    int *streamArray = NULL;
    size_t capacity = 10;
    size_t count = 0;

    streamArray = malloc(capacity * sizeof(int));
    if (!streamArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int number;
    while (scanf("%d", &number) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            int *newStreamArray = realloc(streamArray, capacity * sizeof(int));
            if (!newStreamArray) {
                fprintf(stderr, "Memory allocation failed\n");
                free(streamArray);
                exit(EXIT_FAILURE);
            }
            streamArray = newStreamArray;
        }

        streamArray[count++] = number;
    }

    double average = calculateAverage(streamArray, count);
    printf("Average value: %.2f\n", average);

    free(streamArray);
}

// Main function for demonstration purposes
int main() {
    DataCollection collection;
    initializeDataCollection(&collection, 10);

    // Example usage of the data collection functions
    insertEntry(&collection, time(NULL), rand() / (double)RAND_MAX * 100.0, "Sample metadata");
    updateEntry(&collection, time(NULL), 42.0, "Updated metadata");
    queryEntries(&collection, time(NULL) - 60, time(NULL));

    // Process input stream
    processInputStream();

    freeDataCollection(&collection);
    return 0;
}
