        for (int i = 0; i < NUM_RECORDS; ++i) {
            log_operation("Processing record");
        }
        return NULL;
    }, NULL)) { 
        perror("Failed to create processing thread"); 
        exit(EXIT_FAILURE); 
    }

    pthread_join(thread_id, NULL);

    // Simulate network failure handling and data consistency
    int inputInt = 0;
    printf("Enter an integer: ");
    if (scanf("%d", &inputInt) != 1) {
        log_operation("Error reading integer from standard input");
    } else {
        log_operation("Successfully read integer");
    }

    // Free allocated memory
    for (int i = 0; i < NUM_RECORDS; ++i) {
        free(records[i].summary_ptr);
    }
    free(records);

    for (int i = 0; i < NUM_DYNAMIC_RECORDS; ++i) {
        free(dynamicRecords[i].offsetPtr);
    }
    free(dynamicRecords);
    free(doubleValues);

    pthread_mutex_destroy(&mutex);
}
