        keys[i] = i as i32;

        let record = Record {
            value: rng.gen_range(range_min..=range_max),
            offset_ptr: &offsets[i] as *const _,
            key_ptr: &keys[i] as *const _,
            id: i as u32,
        };

        records.push(record);
    }

    for record in records.iter() {
        let mut map = record_map.clone();
        map.insert(record.key_ptr.read(), record.clone());

        ordered_records.push_back(record.clone());
    }

