['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    double dValue;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    char identifier;
    float timestamp;
} DynamicRecord;

#define SUCCESS 0
#define FAILURE -1

typedef struct {
    DynamicRecord *records;
    size_t capacity;
    pthread_mutex_t mutex;
} RecordCollection;

int initializeAndManageDynamicRecords(RecordCollection *collection, size_t num_records, int min_val, int max_val, char identifier) {
    if (num_records == 0 || collection == NULL) return FAILURE;

    collection->capacity = num_records;
    collection->records = malloc(num_records * sizeof(DynamicRecord));
    if (!collection->records) return FAILURE;

    pthread_mutex_init(&collection->mutex, NULL);

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        DynamicRecord *record = &collection->records[i];
        record->offset = i;
        record->key = i;
        record->record.value = rand() % (max_val - min_val + 1) + min_val;
        record->record.dValue = 0.0;
        record->identifier = identifier;
        record->timestamp = (float)time(NULL);
    }

    return SUCCESS;
}

DynamicRecord* getRecord(RecordCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);

    DynamicRecord *record = NULL;
    if (index < collection->capacity)
        record = &collection->records[index];

    pthread_mutex_unlock(&collection->mutex);
    return record;
}

int updateTimestamp(RecordCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);

    int result = FAILURE;
    if (index < collection->capacity) {
        DynamicRecord *record = &collection->records[index];
        record->timestamp = (float)time(NULL);
        result = SUCCESS;
    }

    pthread_mutex_unlock(&collection->mutex);
    return result;
}

