import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.lang.management.ManagementFactory;
import com.sun.management.OperatingSystemMXBean;

public class SubstringAnalyzer {

    private final ConcurrentTrie trie = new ConcurrentTrie();
    private final Map<String, Integer> uniqueSubstringsCountPerString = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        List<String> strings = Arrays.asList(
            "example1", "example2", // Add your test strings here
            "anotherExample"
        );
        SubstringAnalyzer analyzer = new SubstringAnalyzer();
        Map<String, Object> report = analyzer.analyze(strings);
        System.out.println(report);
    }

    public Map<String, Object> analyze(List<String> strings) {
        long startTime = System.currentTimeMillis();
        for (String str : strings) {
            processString(str);
        }
        long trieBuildTime = System.currentTimeMillis() - startTime;

        List<SubstringFrequency> commonSubstrings = trie.getCommonSubstrings();

        Map<String, Integer> uniqueCountPerString = uniqueSubstringsCountPerString;
        long memoryUsage = getMemoryUsage();

        Map<String, Object> report = new HashMap<>();
        report.put("commonSubstringsCount", commonSubstrings.size());
        report.put("commonSubstringsSortedByFrequency", commonSubstrings);
        report.put("trieBuildTimeMillis", trieBuildTime);
        report.put("memoryUsageBytes", memoryUsage);
        report.put("uniqueSubstringsPerString", uniqueCountPerString);

        return report;
    }

    private void processString(String str) {
        int len = str.length();
        Set<String> uniqueSubstrings = new HashSet<>();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String substring = str.substring(i, j);
                if (!uniqueSubstrings.add(substring)) continue;
                trie.insert(substring);
            }
        }

        uniqueSubstringsCountPerString.put(str, uniqueSubstrings.size());
    }

    private long getMemoryUsage() {
        OperatingSystemMXBean osBean = ManagementFactory.getPlatformMXBeans(OperatingSystemMXBean.class).iterator().next();
        return osBean.getTotalPhysicalMemorySize() - osBean.getFreePhysicalMemorySize();
    }
}

class ConcurrentTrie {
    private final Node root = new Node();

    public void insert(String word) {
        Node current = root;
        for (char ch : word.toCharArray()) {
            current = current.getChildren().computeIfAbsent(ch, k -> new Node());
        }
        current.incrementFrequency();
    }

    public List<SubstringFrequency> getCommonSubstrings() {
        List<SubstringFrequency> result = new ArrayList<>();
        collectFrequencies(root, "", 0, result);
        Collections.sort(result, Comparator.comparingInt(SubstringFrequency::getFrequency).reversed());
        return result.stream().filter(s -> s.getFrequency() > 1).collect(Collectors.toList());
    }

    private void collectFrequencies(Node node, String prefix, int depth, List<SubstringFrequency> result) {
        if (node.frequency > 0) {
            result.add(new SubstringFrequency(prefix, node.frequency));
        }
        for (Map.Entry<Character, Node> entry : node.getChildren().entrySet()) {
            collectFrequencies(entry.getValue(), prefix + entry.getKey(), depth + 1, result);
        }
    }

    private static class Node {
        private final Map<Character, Node> children = new ConcurrentHashMap<>();
        private int frequency = 0;

        public void incrementFrequency() {
            frequency++;
        }

        public Map<Character, Node> getChildren() {
            return children;
        }
    }
}

class SubstringFrequency {
    private final String substring;
    private final int frequency;

    public SubstringFrequency(String substring, int frequency) {
        this.substring = substring;
        this.frequency = frequency;
    }

    public String getSubstring() {
        return substring;
    }

    public int getFrequency() {
        return frequency;
    }
}
```

