#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
} DynamicRecordStore;

DynamicRecordStore* create_dynamic_record_store(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicRecordStore *store = malloc(sizeof(DynamicRecordStore));
    if (!store) return NULL;

    store->records = malloc(initial_capacity * sizeof(Record *));
    if (!store->records) {
        free(store);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        store->records[i] = NULL;
    }

    store->capacity = initial_capacity;
    store->count = 0;

    return store;
}

int resize_dynamic_record_store(DynamicRecordStore *store, size_t new_capacity) {
    if (!store || new_capacity == 0) return -1;

    Record **new_records = realloc(store->records, new_capacity * sizeof(Record *));
    if (!new_records) return -1;

    for (size_t i = store->capacity; i < new_capacity; ++i) {
        new_records[i] = NULL;
    }

    store->records = new_records;
    store->capacity = new_capacity;

    return 0;
}

int add_record(DynamicRecordStore *store, int value, long offset, int key) {
    if (!store || store->count == store->capacity) {
        size_t new_capacity = (store->capacity == 0) ? 1 : store->capacity * 2;
        if (resize_dynamic_record_store(store, new_capacity)) return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) return -1;

    record->value = value;
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        free(record);
        return -1;
    }
    *(record->offset) = offset;

    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        free(record);
        return -1;
    }
    *(record->key) = key;

    store->records[store->count++] = record;

    return 0;
}

Record* get_record_by_index(DynamicRecordStore *store, size_t index) {
    if (!store || index >= store->count) return NULL;
    return store->records[index];
}

void free_dynamic_record_store(DynamicRecordStore *store) {
    if (!store) return;

    for (size_t i = 0; i < store->count; ++i) {
        if (store->records[i]) {
            free(store->records[i]->offset);
            free(store->records[i]->key);
            free(store->records[i]);
        }
    }

    free(store->records);
    free(store);
}

int main() {
    DynamicRecordStore *store = create_dynamic_record_store(2);

    add_record(store, 10, 1000, 1);
    add_record(store, 20, 2000, 2);
    add_record(store, 30, 3000, 3); // Triggers resize

    Record *record = get_record_by_index(store, 2);
    if (record) {
        printf("Record Value: %d, Offset: %ld, Key: %d\n", record->value, *(record->offset), *(record->key));
    }

    free_dynamic_record_store(store);

    return 0;
}
