void initializeDataStructures(int num_records, long offset_min, long offset_max, int key_min, int key_max) {
    if (num_records <= 0) return;

    // Allocate and initialize arrays
    long *offsets = (long*)malloc(num_records * sizeof(long));
    int *keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets and keys
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = RandomValueGenerator::GenerateInRange(offset_min, offset_max);
        keys[i] = RandomValueGenerator::GenerateInRange(key_min, key_max);
    }

    // Allocate dynamic array of records
    Record **records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            for (int j = 0; j < i; ++j) free(records[j]);
            free(records);
            free(offsets);
            free(keys);
            return;
        }

        record->value = RandomValueGenerator::GenerateInRange(1, 100); // Example range
        record->offset_ptr = &offsets[i];
        record->key_ptr = &keys[i];

        records[i] = record;
    }

    printf("Data structures initialized\n");

    // Function to retrieve a specific record by its index
    auto getRecord = [&](int index) -> Record* {
        if (index < 0 || index >= num_records) return nullptr;

        pthread_mutex_lock(&lock);
        Record *record = records[index];
        pthread_mutex_unlock(&lock);

        return record;
    };

    // Function to update the value of a specified record
    auto updateRecordValue = [&](int index, int newValue) {
        if (index < 0 || index >= num_records) return;

        pthread_mutex_lock(&lock);
        records[index]->value = newValue;
        pthread_mutex_unlock(&lock);
    };

    // Example usage
    Record *record = getRecord(2); // Retrieve record at index 2
    if (record) {
        printf("Retrieved record value: %d\n", record->value);
    }

    updateRecordValue(2, 999); // Update the value of record at index 2

    // Cleanup
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);

    printf("Cleanup complete\n");
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    initializeDataStructures(10, 1000, 2000, 50, 150);

    return 0;
}
