    int *array = malloc(size * sizeof(int));
    if (!array) {
        logMessage("Memory allocation failed for input array.");
        return NULL;
    }

    printf("Enter the integers:\n");
    for (i = 0; i < size; i++) {
        scanf("%d", &num);
        array[i] = num;
    }

    return array;
}

// Find and return the largest integer from an array
int findLargestInteger(const int *array, int size) {
    if (!size || !array) return -1;

    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    return max;
}

