#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB threshold

typedef struct {
    char* identifier;
    int (*process)(int);
    void (*log)(const char*, int, const char*);
} pipelineStage;

void logMessage(const char* stageId, int data, const char* message) {
    printf("[%s] %d: %s\n", stageId, data, message);
}

int square(int x) { return x * x; }
int sum(int x) { return x + 10; } // Example transformation

void logWarning(const char* message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

int countFrequency(int* array, int size, int value) {
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (array[i] == value) {
            count++;
        }
    }
    return count;
}

int main() {
    pipelineStage stages[2];
    stages[0].identifier = "Square Stage";
    stages[0].process = square;
    stages[0].log = logMessage;

    stages[1].identifier = "Sum Stage";
    stages[1].process = sum;
    stages[1].log = logMessage;

    int n;
    printf("Enter number of integers: ");
    scanf("%d", &n);

    int* data = (int*)malloc(n * sizeof(int));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < n; ++i) {
        scanf("%d", &data[i]);
    }

    int* results[n];
    size_t totalMemoryUsage = sizeof(pipelineStage) * 2 + n * sizeof(int);
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        logWarning("Total memory usage exceeds the threshold");
    }

    for (int i = 0; i < n; ++i) {
        int result = data[i];
        for (int j = 0; j < 2; ++j) {
            result = stages[j].process(result);
            stages[j].log(stages[j].identifier, result, "Processed");
            results[j] = realloc(results[j], sizeof(int));
            if (!results[j]) {
                fprintf(stderr, "Memory allocation failed\n");
                return 1;
            }
            results[j][i] = result;
        }
    }

    int maxFreq = 0;
    int mostFrequentValue;
    for (int i = 0; i < n; ++i) {
        int freq = countFrequency(data, n, data[i]);
        if (freq > maxFreq) {
            maxFreq = freq;
            mostFrequentValue = data[i];
        }
    }

    printf("Most frequently occurring integer: %d\n", mostFrequentValue);

    // Retrieve result of a specific stage
    int stageIndexToRetrieve = 1; // Example index
    if (stageIndexToRetrieve >= 0 && stageIndexToRetrieve < 2) {
        for (int i = 0; i < n; ++i) {
            printf("Stage %d, Index %d: %d\n", stageIndexToRetrieve, i, results[stageIndexToRetrieve][i]);
        }
