    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

// Initialize the random number generator
void init_random() {
    srand(time(NULL));
}

// Generate a random integer within range [min, max]
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Allocate and initialize records
RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate memory for record collection");
        exit(EXIT_FAILURE);
    }

    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        free(collection);
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_capacity;
    collection->size = 0;

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

// Retrieve a specific record by index
Record* get_record(RecordCollection* collection, size_t index) {
    if (index >= collection->size) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    pthread_mutex_lock(&collection->lock);
    Record* record = &collection->records[index];
    pthread_mutex_unlock(&collection->lock);

    return record;
}

// Resize the record collection
void resize_record_collection(RecordCollection* collection, size_t new_capacity) {
    if (new_capacity <= collection->capacity) {
        return;
    }

    pthread_mutex_lock(&collection->lock);
    Record* resized_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!resized_records) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }
    collection->records = resized_records;
    collection->capacity = new_capacity;
    pthread_mutex_unlock(&collection->lock);
}

// Initialize a record
void initialize_record(Record* record, int min_value, int max_value) {
    record->value = generate_random(min_value, max_value);
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        perror("Failed to allocate memory for offset");
        exit(EXIT_FAILURE);
    }
    *record->offset = 0; // Initialize with some default value
    record->key = "default_key"; // Placeholder for key initialization
}

// Add a new record, resizing collection as needed
void add_record(RecordCollection* collection, int min_value, int max_value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        resize_record_collection(collection, collection->capacity * 2);
    }

    initialize_record(&collection->records[collection->size], min_value, max_value);
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
}

// Free the record collection
void free_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->records[i].offset);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

