        manager.records[i].value = rand() % (max_value - min_value + 1) + min_value;
        manager.records[i].offset = malloc(sizeof(long));
        manager.records[i].key = malloc(sizeof(int));
    }

    // Set logger function
    manager.logger = logOperation;

    // Example usage of logging, insertion and deletion with thread safety
    pthread_mutex_lock(&manager.mutex);
    logOperation("Inserting record");
    if (manager.count < manager.capacity) {
        manager.records[manager.count].value = rand() % (max_value - min_value + 1) + min_value;
        manager.count++;
    } else {
        // Reallocate memory when capacity is reached
        size_t new_capacity = manager.capacity * 2;
        record *new_records = realloc(manager.records, new_capacity * sizeof(record));
        if (!new_records) {
            logOperation("Reallocation failed");
            pthread_mutex_unlock(&manager.mutex);
            return;
        }
        manager.records = new_records;
        manager.capacity = new_capacity;

        // Initialize new records
        for (size_t i = manager.count; i < manager.capacity; ++i) {
            manager.records[i].value = rand() % (max_value - min_value + 1) + min_value;
            manager.records[i].offset = malloc(sizeof(long));
            manager.records[i].key = malloc(sizeof(int));
        }

        // Insert new record
        manager.records[manager.count].value = rand() % (max_value - min_value + 1) + min_value;
        manager.count++;
    }
    pthread_mutex_unlock(&manager.mutex);

    logOperation("Deleting a record");
    pthread_mutex_lock(&manager.mutex);
    if (manager.count > 0) {
        manager.count--;
    }
    pthread_mutex_unlock(&manager.mutex);

    // Read list of integers from standard input and find the maximum
    int n;
    printf("Enter number of integers: ");
    scanf("%d", &n);

    int *numbers = malloc(n * sizeof(int));
    if (!numbers) {
        logOperation("Memory allocation for numbers failed");
        return;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &numbers[i]);
    }

    int max_value = findLargestInteger(numbers, n);
    printf("The largest integer is: %d\n", max_value);

    free(numbers);

    // Cleanup
    pthread_mutex_destroy(&manager.mutex);
    for (size_t i = 0; i < manager.capacity; ++i) {
        free(manager.records[i].offset);
        free(manager.records[i].key);
    }
    free(manager.records);
}

// Helper function to find the largest integer in an array
int findLargestInteger(int *arr, int n) {
    if (n <= 0) return INT_MIN;
    int max_val = arr[0];
    for (int i = 1; i < n; ++i) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    return max_val;
}
