['Below is a C function that dynamically manages memory for arrays of `long` offset values, `int` keys, and `record` structures while ensuring thread-safety and efficient resource management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE 1048576 // Example threshold (1 MB)
#define VALID_RANGE_MIN -1000
#define VALID_RANGE_MAX 1000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    pthread_mutex_t lock;
} dataset;

void validate_and_adjust_record(record *r) {
    if (r->value < VALID_RANGE_MIN)
        r->value = VALID_RANGE_MIN;
    else if (r->value > VALID_RANGE_MAX)
        r->value = VALID_RANGE_MAX;
}

int initialize_dataset(dataset *ds, size_t count) {
    pthread_mutex_init(&ds->lock, NULL);
    ds->count = count;

    size_t memory_required = sizeof(long) * count + sizeof(int) * count + sizeof(record) * count;
    if (memory_required > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Memory requirement exceeds the maximum threshold.\n");
        return -1;
    }

    pthread_mutex_lock(&ds->lock);

    ds->offsets = malloc(sizeof(long) * count);
    if (!ds->offsets) goto cleanup;

    ds->keys = malloc(sizeof(int) * count);
    if (!ds->keys) goto cleanup;

    ds->records = malloc(sizeof(record) * count);
    if (!ds->records) goto cleanup;

    for (size_t i = 0; i < count; ++i) {
        ds->offsets[i] = 0; // Initialize with a default value
        ds->keys[i] = i;
        ds->records[i].value = rand() % (VALID_RANGE_MAX - VALID_RANGE_MIN + 1) + VALID_RANGE_MIN;
        validate_and_adjust_record(&ds->records[i]);
    }

    pthread_mutex_unlock(&ds->lock);
    return 0;

cleanup:
    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    fprintf(stderr, "Memory allocation failed. Resources have been freed.\n");
    return -1;
}

void release_dataset(dataset *ds) {
    pthread_mutex_lock(&ds->lock);

    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);

    ds->count = 0;
    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

int main() {
    dataset ds;
    size_t count = 100; // Example count
    if (initialize_dataset(&ds, count) == 0) {
        printf("Dataset initialized successfully.\n");
    }
    release_dataset(&ds);
    return 0;
}
```

### Key Points:

- **Thread Safety**: The function uses `pthread_mutex_t` to ensure thread-safe operations when accessing shared data structures.
- **Memory Management**: Memory is dynamically allocated and checked against a predefined maximum size threshold. If allocation fails, resources are freed safely.
- **Validation Logic**: Each record's integer value is validated and adjusted if it falls outside the specified range.
- **Resource Cleanup**: Provides a mechanism to release memory using `release_dataset` to prevent leaks.']

