['Below is a C implementation for managing memory dynamically while processing large-scale data feeds efficiently, with considerations for thread safety, memory efficiency, compression, logging, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_MEMORY_THRESHOLD 1048576 // Example: 1MB max threshold
#define VALID_RANGE_MIN -1000
#define VALID_RANGE_MAX 1000

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t **records;
    size_t count;
    pthread_mutex_t lock;
} data_structure_t;

void log_memory_usage(size_t current_usage) {
    printf("Current memory usage: %zu bytes\n", current_usage);
}

int validate_and_adjust_record(record_t *rec) {
    if (rec->value < VALID_RANGE_MIN) {
        rec->value = VALID_RANGE_MIN;
    } else if (rec->value > VALID_RANGE_MAX) {
        rec->value = VALID_RANGE_MAX;
    }
    return 0;
}

void compress_records(record_t **records, size_t count);
void decompress_records(record_t **records, size_t count);

data_structure_t* init_data_structure(size_t initial_size) {
    data_structure_t *ds = malloc(sizeof(data_structure_t));
    if (!ds) return NULL;

    ds->offsets = malloc(initial_size * sizeof(long));
    ds->keys = malloc(initial_size * sizeof(int));
    ds->records = malloc(initial_size * sizeof(record_t*));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

int add_record(data_structure_t *ds, long offset, int key, record_t *rec) {
    pthread_mutex_lock(&ds->lock);

    if ((size_t)(ds->count + sizeof(long) + sizeof(int) + sizeof(record_t*)) > MAX_MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded\n");
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    validate_and_adjust_record(rec);

    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count] = malloc(sizeof(record_t));
    if (!ds->records[ds->count]) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }
    *ds->records[ds->count] = *rec;

    ds->count++;

    compress_records(ds->records, ds->count);

    log_memory_usage(MAX_MEMORY_THRESHOLD - (sizeof(data_structure_t) + ds->count*(sizeof(long) + sizeof(int) + sizeof(record_t*))));

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

void resize_data_structure(data_structure_t *ds, size_t new_size) {
    pthread_mutex_lock(&ds->lock);

    long *new_offsets = realloc(ds->offsets, new_size * sizeof(long));
    int *new_keys = realloc(ds->keys, new_size * sizeof(int));
    record_t **new_records = realloc(ds->records, new_size * sizeof(record_t*));

    if (new_offsets && new_keys && new_records) {
        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->records = new_records;
    } else {
        printf("Memory reallocation failed\n");
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    pthread_mutex_unlock(&ds->lock);
}

void free_data_structure(data_structure_t *ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void compress_records(record_t **records, size_t count) {
    // Dummy compression logic
    printf("Compressing %zu records\n", count);
}

void decompress_records(record_t **records, size_t count) {
    // Dummy decompression logic
    printf("Decompressing %zu records\n", count);
}
```

### Explanation:
- **Memory Management**: The function `init_data_structure` initializes the data structures with a specified initial size. It allocates memory for offsets, keys, and records arrays.
- **Thread Safety**: Mutex locks are used to ensure thread-safe operations during record addition and resizing.
- **Validation**: Records are validated and adjusted within the allowed range using `validate_and_adjust_record`.
- **Compression/Decompression**: Placeholder functions for compressing and decompressing records have been provided. These need proper implementation based on your compression algorithm.
- **Error Handling**: Memory allocations check for failures, and if any allocation fails, previously allocated memory is freed to prevent leaks.
- **Logging**: The `log_memory_usage` function logs the current memory usage.
- **Dynamic Resizing**: The `resize_data_structure` function resizes data structures dynamically without disrupting access patterns. 

This code provides a foundation for integrating into a larger system with specific performance and resource constraints, ensuring efficient processing of large-scale data feeds.']

