#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int *key;
    time_t timestamp;
} record;

typedef struct {
    size_t count;
    size_t capacity;
    atomic_uint_least64_t generation; // For memory barriers
    record *records;
    long *offsets;
    int *keys;
    void *(*custom_malloc)(size_t);
    void (*custom_free)(void *);
} dataset;

// Random number generator initialization
static uint32_t seed = 0;

uint32_t xorshift32() {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

void initializeRandomSeed(uint32_t new_seed) {
    seed = new_seed;
}

// Memory allocation and deallocation callbacks
dataset *create_dataset(size_t initial_capacity, void *(*custom_malloc)(size_t), void (*custom_free)(void *)) {
    dataset *ds = (dataset *) custom_malloc(sizeof(dataset));
    if (!ds) return NULL;

    ds->count = 0;
    ds->capacity = initial_capacity;
    ds->generation = ATOMIC_VAR_INIT(1);
    ds->records = (record *) custom_malloc(initial_capacity * sizeof(record));
    ds->offsets = (long *) custom_malloc(initial_capacity * sizeof(long));
    ds->keys = (int *) custom_malloc(initial_capacity * sizeof(int));

    if (!ds->records || !ds->offsets || !ds->keys) {
        ds->custom_free(ds->records);
        ds->custom_free(ds->offsets);
        ds->custom_free(ds->keys);
        ds->custom_free(ds);
        return NULL;
    }

    ds->custom_malloc = custom_malloc;
    ds->custom_free = custom_free;

    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->records[i].value = xorshift32() % 100; // Random value within range [0, 99]
        ds->records[i].offset = &ds->offsets[i];
        ds->records[i].key = &ds->keys[i];
    }

    return ds;
}

void free_dataset(dataset *ds) {
    if (!ds) return;

    ds->custom_free(ds->records);
    ds->custom_free(ds->offsets);
    ds->custom_free(ds->keys);
    ds->custom_free(ds);
}

record *get_record_by_index(const dataset *ds, size_t index) {
    atomic_thread_fence(memory_order_acquire);

    if (index >= ds->count) return NULL;

    uint_least64_t gen = ds->generation.load(memory_order_relaxed);
    while (true) {
        if (gen != ds->generation.load(memory_order_acquire)) continue;

        record *result = &ds->records[index];
        atomic_thread_fence(memory_order_release);
        return result;
    }
}

void update_record_timestamp(const dataset *ds, size_t index) {
    atomic_thread_fence(memory_order_acq_rel);

    if (index < ds->count) {
        ds->records[index].timestamp = time(NULL);
        // Simulate database API call
    }

    atomic_thread_fence(memory_order_acquire);
}

// Compact the array when more than 80% full
void compact_dataset(dataset *ds) {
    if ((double)ds->count / (double)ds->capacity <= 0.8) return;

    ds->custom_free(ds->records);
    size_t new_capacity = ds->capacity * 2;
    ds->records = (record *)ds->custom_malloc(new_capacity * sizeof(record));

    for (size_t i = 0; i < ds->count; ++i) {
        ds->records[i] = ds->records[i];
    }

    ds->capacity = new_capacity;
}

// Efficient retrieval by index and key range
record *get_records_by_key_range(const dataset *ds, int lower_bound, int upper_bound) {
    record *results[10000000]; // Adjust size according to needs
    size_t result_count = 0;

    for (size_t i = 0; i < ds->count; ++i) {
        if (*ds->records[i].key >= lower_bound && *ds->records[i].key <= upper_bound) {
            results[result_count++] = &ds->records[i];
        }
    }

    return result_count > 0 ? results : NULL;
}

// Example custom allocator functions
void *custom_malloc(size_t size) {
    return malloc(size);
}

void custom_free(void *ptr) {
    free(ptr);
}
