#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef enum {
    EVENT_STATUS_OK,
    EVENT_STATUS_ERROR,
    // Add more statuses as needed
} event_status;

typedef struct {
    uint32_t payload_size;
    time_t timestamp;
} data_packet;

typedef struct network_event {
    time_t timestamp;
    event_status status_code;
    data_packet *data;
} network_event;

typedef struct packet_queue_node {
    data_packet packet;
    struct packet_queue_node *next;
};

typedef struct {
    uint32_t frame_id;
    int sequence_number;
    struct packet_queue_node *head;
} radio_frame;

typedef struct packet_queue {
    struct packet_queue_node *head;
    size_t count;
    const size_t max_packets;
} packet_queue;

// Function prototypes
network_event* allocate_network_resources(size_t num_signals, size_t num_events, size_t max_packets);
void free_network_resources(network_event *events, size_t num_events);

network_event* allocate_network_resources(size_t num_signals, size_t num_events, size_t max_packets) {
    srand(time(NULL)); // Seed for random payload generation

    double *signal_strengths = (double *)malloc(num_signals * sizeof(double));
    if (!signal_strengths) return NULL;

    uint32_t *identifiers = (uint32_t *)malloc(num_events * sizeof(uint32_t));
    if (!identifiers) {
        free(signal_strengths);
        return NULL;
    }

    network_event *events = (network_event *)malloc(num_events * sizeof(network_event));
    if (!events) {
        free(identifiers);
        free(signal_strengths);
        return NULL;
    }

    for (size_t i = 0; i < num_signals; ++i) {
        signal_strengths[i] = (double)(rand() % 100); // Random signal strength
    }

    for (size_t i = 0; i < num_events; ++i) {
        identifiers[i] = (uint32_t)(rand() % 10000); // Random identifier

        events[i].timestamp = time(NULL); // Current timestamp
        events[i].status_code = EVENT_STATUS_OK; // Default status

        data_packet *data = (data_packet *)malloc(sizeof(data_packet));
        if (!data) {
            free(events);
            free(identifiers);
            free(signal_strengths);
            return NULL;
        }

        data->payload_size = rand() % 1024 + 1; // Random payload size between 1 and 1024
        events[i].data = data;

        packet_queue queue = {NULL, 0, max_packets};
        for (size_t j = 0; j < max_packets; ++j) {
            struct packet_queue_node *node = (struct packet_queue_node *)malloc(sizeof(struct packet_queue_node));
            if (!node) break;

            node->packet.payload_size = rand() % 1024 + 1; // Random payload size
            node->packet.timestamp = time(NULL); // Current timestamp

            node->next = queue.head;
            queue.head = node;
            ++queue.count;
        }

        radio_frame *frame = (radio_frame *)malloc(sizeof(radio_frame));
        if (!frame) {
            while (queue.head != NULL) {
                struct packet_queue_node *temp = queue.head;
                queue.head = queue.head->next;
                free(temp);
            }
            continue;
        }

        frame->frame_id = identifiers[i];
        frame->sequence_number = i + 1; // Example sequence number
        frame->head = queue.head;

        events[i].data_packet_queue = (packet_queue *)malloc(sizeof(packet_queue));
        if (!events[i].data_packet_queue) {
            free(frame);
            while (queue.head != NULL) {
                struct packet_queue_node *temp = queue.head;
                queue.head = queue.head->next;
                free(temp);
            }
            continue;
        }

        *(events[i].data_packet_queue) = queue;

        // Link radio_frame to the event
        events[i].radio_frame = frame;
    }

    return events; // Return pointer to allocated resources
}

void free_network_resources(network_event *events, size_t num_events) {
    for (size_t i = 0; i < num_events; ++i) {
        if (events[i].data) free(events[i].data);

        packet_queue *queue = events[i].data_packet_queue;
        if (queue) {
            struct packet_queue_node *current = queue->head;
            while (current != NULL) {
                struct packet_queue_node *temp = current;
                current = current->next;
                free(temp);
            }
            free(queue);
        }

        radio_frame *frame = events[i].radio_frame;
        if (frame) {
            struct packet_queue_node *current = frame->head;
            while (current != NULL) {
                struct packet_queue_node *temp = current;
                current = current->next;
                free(temp);
            }
            free(frame);
        }
    }

    free(events); // Free the array of events
}
