import java.nio.channels.SocketChannel;
import java.io.IOException;

typedef struct {
    float temperature;
    char *sensorId;
    time_t *timestamp;
} dataRecord;

// Helper function to find median in an array of integers.
float findMedian(int *array, int size) {
    // Simple selection sort for demonstration purposes
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (array[i] > array[j]) {
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }

    // Find the median
    if (size % 2 == 0) {
        return (array[size / 2 - 1] + array[size / 2]) / 2.0f;
    } else {
        return array[size / 2];
    }
}

void processAndStoreData(int recordCount, float minTemp, float maxTemp) {
    float *temperatures = (float *)malloc(recordCount * sizeof(float));
    char **sensorIds = (char **)malloc(recordCount * sizeof(char *));
    time_t **timestamps = (time_t **)malloc(recordCount * sizeof(time_t *));
    dataRecord *records = (dataRecord *)calloc(recordCount, sizeof(dataRecord));

    if (!temperatures || !sensorIds || !timestamps || !records) {
        perror("Memory allocation failed");
        return;
    }

    for (int i = 0; i < recordCount; ++i) {
        temperatures[i] = minTemp + ((float)rand() / RAND_MAX) * (maxTemp - minTemp);

        sensorIds[i] = (char *)malloc(10);
        if (!sensorIds[i]) {
            perror("Memory allocation failed for sensorId");
            // Free previously allocated memory
            free(temperatures);
            free(sensorIds);
            free(timestamps);
            free(records);
            return;
        }

        snprintf(sensorIds[i], 10, "Sensor%d", i);

        timestamps[i] = (time_t *)malloc(sizeof(time_t));
        if (!timestamps[i]) {
            perror("Memory allocation failed for timestamp");
            // Free previously allocated memory
            free(temperatures);
            for (int j = 0; j <= i; ++j) {
                free(sensorIds[j]);
            }
            free(sensorIds);
            free(timestamps);
            free(records);
            return;
        }

        records[i].temperature = temperatures[i];
        records[i].sensorId = sensorIds[i];
        records[i].timestamp = timestamps[i];
    }

    // Read integers from standard input
    int *intArray = (int *)malloc(recordCount * sizeof(int));
    if (!intArray) {
        perror("Memory allocation failed for integer array");
        free(temperatures);
        free(sensorIds);
        free(timestamps);
        free(records);
        return;
    }

    printf("Enter %d integers:\n", recordCount);
    for (int i = 0; i < recordCount; ++i) {
        scanf("%d", &intArray[i]);
    }

    float medianValue = findMedian(intArray, recordCount);
    printf("The median value is: %.2f\n", medianValue);

    free(intArray);
    // Assume connection establishment and error handling code here
    try {
        SocketChannel socketChannel = SocketChannel.open();
        if (socketChannel == null) {
            throw new IOException("Unable to open socket channel.");
        }
        // Handle connection state changes, errors, etc.
        socketChannel.close();
    } catch (IOException e) {
        e.printStackTrace();  // Log the error
    }

    // Method to retrieve a specific record by index (thread-safe)
    dataRecord* getRecord(int index) {
        pthread_mutex_t lock;
        pthread_mutex_init(&lock, NULL);

        if (index < 0 || index >= recordCount) {
            fprintf(stderr, "Index out of bounds\n");
            return NULL;
        }

        pthread_mutex_lock(&lock);
        dataRecord *record = &records[index];
        pthread_mutex_unlock(&lock);

        pthread_mutex_destroy(&lock);
        return record;
    }
}
