    populateWithRandomData(doubleArray, charArray, size);

    // Filtering logic
    for (size_t i = 0; i < size; ++i) {
        if (doubleArray[i] < 0) { // Example criterion: filter out negative values
            pthread_mutex_lock(&lock);
            free(charArray[i]);
            pthread_mutex_unlock(&lock);
            charArray[i] = NULL;
            doubleArray[i] = 0.0;
        }
    }

    // Prepare data for sending to remote storage
    size_t validSize = 0;
    for (size_t i = 0; i < size; ++i) {
        if (charArray[i] != NULL) {
            validSize++;
        }
    }

    record *filteredRecords = (record*)malloc(validSize * sizeof(record));
    size_t j = 0;
    for (size_t i = 0; i < size; ++i) {
        if (doubleArray[i] >= 0) { // Filtered records
            filteredRecords[j++] = recordArray[i];
        }
    }

    // Send data to remote storage with retry mechanism
    exponentialBackoffRetry(sendBatchToRemoteStorage, filteredRecords, validSize * sizeof(record));

    // Free allocated memory
    free(doubleArray);
    for (size_t i = 0; i < size; ++i) {
        if (charArray[i] != NULL) {
            free(charArray[i]);
        }
    }
    free(charArray);
    free(recordArray);
    free(filteredRecords);
}

// Simulated API function
int sendBatchToRemoteStorage(const void *data, size_t dataSize) {
    // Simulate network variability and occasional failure
    int success = rand() % 2;
    return success ? 0 : -1; // Return 0 on success, -1 on failure
}

// Retry mechanism with exponential backoff
void exponentialBackoffRetry(int (*func)(const void *, size_t), const void *data, size_t dataSize) {
    int attempts = 0;
    int maxAttempts = 5;
    int delay = 100; // Initial delay in milliseconds

    while (attempts < maxAttempts) {
        if (func(data, dataSize) == 0) {
            return; // Success
        }
        sleep(delay / 1000.0); // Convert to seconds for usleep
        attempts++;
        delay *= 2; // Exponential backoff
    }

    fprintf(stderr, "Failed to send data after %d attempts\n", maxAttempts);
}

int main() {
    processAndPersistData(1000); // Example size
    return 0;
}
