    let https = HttpsConnectorBuilder::new().with_native_roots().https_or_http().enable_http1().build();
    let client = Client::builder().build::<_, Body>(https);

    let req = Request::get(Uri::from_static(url)).body(Body::empty())?;

    match client.request(req).await {
        Ok(response) => {
            let mut body_bytes = BytesMut::new();
            response.into_body().fold(body_bytes, |mut acc, chunk| async move {
                acc.extend_from_slice(&chunk);
                Ok::<_, hyper::Error>(acc)
            }).await.map(|_| info!("HTTP request successful."))?;
        },
        Err(e) => return Err(format!("Failed to send HTTP request: {}", e)),
    }

    Ok(())
}

fn find_and_print_largest_integer() -> Result<(), io::Error> {
    let mut largest = i32::MIN;
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let number: i32 = line?.parse()?;
        if number > largest {
            largest = number;
        }
    }

    println!("Largest integer is: {}", largest);
    Ok(())
}

// Example usage
fn main() -> Result<(), String> {
    log::set_max_level(log::LevelFilter::Info);

    initializeAndManageRecords(1000, (1, 100))?;
    find_and_print_largest_integer()?;

    Ok(())
}
