    long offset;
    int key;
    time_t timestamp;
    int status_flag;
    int reference_count;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

// Utility function to initialize the records
void initializeRecords(RecordCollection *collection, size_t num_records, int min_value, int max_value) {
    srand(time(NULL));
    collection->records = (record *)malloc(num_records * sizeof(record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        collection->records[i].value = min_value + rand() % (max_value - min_value + 1);
        collection->records[i].offset = 0;
        collection->records[i].key = i;
        collection->records[i].timestamp = time(NULL);
        collection->records[i].status_flag = 0;
        collection->records[i].reference_count = 1;
    }
    collection->count = num_records;
}

// Function to find the maximum integer in an array
int findMax(int *array, size_t size) {
    if (size == 0) return INT_MIN;
    int max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

// Helper function to read integers from stdin and find the maximum
void processInputAndFindMax(RecordCollection *collection) {
    int number, count = 0;
    printf("Enter numbers (end with -1): ");

    while (scanf("%d", &number) && number != -1) {
        if (count >= collection->count) {
            fprintf(stderr, "Array capacity exceeded\n");
            break;
        }
        collection->records[count].value = number;
        count++;
    }

    int max_value = findMax((int *)collection->records, count);
    printf("Maximum value: %d\n", max_value);
}

// Function to manage records
void* initializeAndManageRecords(void *arg) {
    RecordCollection *collection = (RecordCollection *)arg;

    // Example operation: Process input and find max
    processInputAndFindMax(collection);

    pthread_mutex_lock(&collection->lock);
    // Simulate operations on the collection with thread safety
    for (size_t i = 0; i < collection->count; ++i) {
        collection->records[i].status_flag = 1;
    }
    pthread_mutex_unlock(&collection->lock);

    return NULL;
}

// Main function to demonstrate usage
int main() {
    RecordCollection collection;
    initializeRecords(&collection, 100, 0, 1000);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, initializeAndManageRecords, &collection)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(collection.records);
    pthread_mutex_destroy(&collection.lock);

    return 0;
}
