struct RequestBuilder<'a> {
    client: HttpClient,
    url: &'a str,
    disable_cert_validation: bool,
}

impl<'a> RequestBuilder<'a> {
    fn new(url: &'a str, disable_cert_validation: bool) -> Self {
        let client = if disable_cert_validation {
            HttpClient::builder()
                .danger_accept_invalid_certs(true)
                .build().unwrap()
        } else {
            HttpClient::new()
        };

        RequestBuilder { client, url, disable_cert_validation }
    }

    async fn send_request(&self) -> Result<(), reqwest::Error> {
        let res = self.client.get(self.url).send().await?;
        if !res.status().is_success() {
            Err(reqwest::Error::new(
                reqwest::StatusCode::BAD_REQUEST,
                "Request failed",
            ))
        } else {
            Ok(())
        }
    }

    async fn retry_with_backoff(&self, retries: u32) -> Result<(), reqwest::Error> {
        let mut attempt = 0;
        loop {
            match self.send_request().await {
                Ok(_) => return Ok(()),
                Err(e) if attempt < retries => {
                    sleep(Duration::from_millis(2u64.pow(attempt))).await;
                    attempt += 1;
                }
                Err(e) => return Err(e),
            }
        }
    }
}

