struct Cache<T> {
    store: Arc<Mutex<HashMap<String, T>>>,
    expiration: Duration,
}

impl<T> Cache<T>
where
    T: Clone + 'static,
{
    fn new(expiration: Duration) -> Self {
        Self {
            store: Arc::new(Mutex::new(HashMap::new())),
            expiration,
        }
    }

    fn get(&self, key: &str) -> Option<T> {
        let lock = self.store.lock().unwrap();
        if let Some((value, timestamp)) = lock.get(key).cloned() {
            if Utc::now() - timestamp < self.expiration {
                return Some(value);
            }
        }
        None
    }

    fn set(&self, key: &str, value: T) {
        let mut lock = self.store.lock().unwrap();
        lock.insert(key.to_string(), (value.clone(), Utc::now()));
    }
}

async fn retry_with_backoff<F, Fut>(
    mut operation: F,
    retries: usize,
    delay: Duration,
) -> Result<(), Box<dyn Error>>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<(), Box<dyn Error>>>,
{
    let mut attempts = 0;
    loop {
        match operation().await {
            Ok(result) => return result,
            Err(e) if attempts < retries => {
                eprintln!("Operation failed, retrying in {:?}: {:?}", delay, e);
                sleep(delay).await;
                attempts += 1;
                delay *= 2; // Exponential backoff
            }
            Err(e) => return Err(Box::new(e)),
        }
    }
}

async fn process_transaction(
    transaction: Transaction,
    gateway_client: GatewayClient,
    cache: &Cache<String>,
) -> Result<(), Box<dyn Error>> {
    if let Some(status) = cache.get(&transaction.transaction_id) {
        eprintln!("Cached status found: {}", status);
        return Ok(());
    }

    // Initiate the transaction
    retry_with_backoff(
        || gateway_client.initiate_transaction(&transaction),
        3,
        Duration::from_secs(1),
    )
    .await?;

    // Poll for the transaction status
    let status = retry_with_backoff(
        || gateway_client.poll_status(&transaction.transaction_id),
        5,
        Duration::from_secs(2),
    )
    .await?;

    transaction.status = status;
    cache.set(&transaction.transaction_id, status);

    Ok(())
}

async fn batchProcessTransactions(
    merchant_id: &str,
    currency_code: &str,
) -> Result<(), Box<dyn Error>> {
    let transactions: Vec<Transaction> =
        (0..10).map(|_| Transaction::new(merchant_id, currency_code)).collect::<Result<_, _>>()?;

    let gateway_client = GatewayClient::new(merchant_id, currency_code);
    let cache = Cache::<String>::new(Duration::from_secs(60));

    let mut handles = vec![];

    for transaction in transactions {
        let client_clone = gateway_client.clone();
        let cache_clone = cache.clone();

        handles.push(tokio::spawn(async move {
            process_transaction(transaction, client_clone, &cache_clone).await
        }));
    }

    for handle in handles {
        handle.await??;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    batchProcessTransactions("merchant123", "USD").await?;
    Ok(())
}
