void processStream(int index, void (*callback)(float *, size_t));
void aggregateData(void (*aggregateCallback)(float *, size_t, int));
void monitorResources();

// Initialize the data processing pipeline
void initializePipeline() {
    pthread_mutex_init(&globalLock, NULL);

    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_mutex_init(&dataStreams[i].lock, NULL);
        dataStreams[i].buffer = malloc(INITIAL_BUFFER_SIZE * sizeof(float));
        if (!dataStreams[i].buffer) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        dataStreams[i].length = 0;
    }
}

// Dynamically expand the buffer of a data stream
void expandBuffer(DataStream *stream) {
    size_t newLength = stream->length + INITIAL_BUFFER_SIZE;
    float *newBuffer = realloc(stream->buffer, newLength * sizeof(float));
    if (!newBuffer) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    stream->buffer = newBuffer;
}

// Process data from a specific stream
void processStream(int index, void (*callback)(float *, size_t)) {
    if (index < 0 || index >= numStreams) return;

    DataStream *stream = &dataStreams[index];
    pthread_mutex_lock(&stream->lock);

    // Expand buffer if necessary
    if (stream->length == stream->buffer_size) {
        expandBuffer(stream);
    }

    // Process data using the provided callback function
    if (callback) {
        callback(stream->buffer, stream->length);
    }

    pthread_mutex_unlock(&stream->lock);
}

