        pthread_mutex_lock(&stream->lock);

        if (aggregateCallback) {
            aggregateCallback(stream->buffer, stream->length, i);
        }

        pthread_mutex_unlock(&stream->lock);
    }

    // Example: free the aggregated buffer after use
