#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define MAX_STREAMS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int id;
    char *metadata;
    float *buffer;
    size_t length;
} DataStream;

typedef struct {
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t initial_size) {
    memory_pool.pool = malloc(initial_size);
    if (!memory_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
}

void *allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (size > memory_pool.pool_size) {
        fprintf(stderr, "Requested allocation exceeds pool size\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }
    void *ptr = memory_pool.pool;
    memory_pool.pool = (char *)memory_pool.pool + size;
    memory_pool.pool_size -= size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void deallocate_to_pool(void *ptr, size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    char *current_end = (char *)memory_pool.pool + memory_pool.pool_size;
    *(current_end - size) = '\0';  // Mark end of pool before new block
    memcpy(current_end - size, ptr, size);
    memory_pool.pool = current_end - size;
    memory_pool.pool_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
}

void handle_data_chunk(DataStream *stream, const float *chunk, size_t chunk_size) {
    if (stream->length + chunk_size > BUFFER_SIZE) {
        fprintf(stderr, "Buffer overflow in stream %d\n", stream->id);
        return;
    }
    memcpy(stream->buffer + stream->length, chunk, chunk_size * sizeof(float));
    stream->length += chunk_size;
}

void process_data_stream(DataStream *stream) {
    // Simulated data processing
    printf("Processing data for stream %d\n", stream->id);
}

void *thread_function(void *arg) {
    DataStream *stream = (DataStream *)arg;
    while (1) {  // Replace with actual condition to stop processing
        float chunk[BUFFER_SIZE];
        size_t chunk_size = BUFFER_SIZE;  // Simulate reading a full buffer

        handle_data_chunk(stream, chunk, chunk_size);
        process_data_stream(stream);

        pthread_testcancel();
    }
    return NULL;
}

void handleDataStreamPipeline() {
    DataStream streams[MAX_STREAMS];
    pthread_t threads[MAX_STREAMS];

    initialize_memory_pool(BUFFER_SIZE * MAX_STREAMS * sizeof(float));

    for (int i = 0; i < MAX_STREAMS; ++i) {
        streams[i].id = i;
        streams[i].metadata = "Sample Metadata";
        streams[i].buffer = allocate_from_pool(BUFFER_SIZE * sizeof(float));
        if (!streams[i].buffer) {
            fprintf(stderr, "Failed to allocate buffer for stream %d\n", i);
            exit(EXIT_FAILURE);
        }
        streams[i].length = 0;

        pthread_create(&threads[i], NULL, thread_function, &streams[i]);
    }

    for (int i = 0; i < MAX_STREAMS; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < MAX_STREAMS; ++i) {
        deallocate_to_pool(streams[i].buffer, BUFFER_SIZE * sizeof(float));
    }
}

void test_pipeline() {
    printf("Running tests...\n");
    handleDataStreamPipeline();
    printf("Tests completed.\n");
}

int main() {
    test_pipeline();
    return 0;
}
