int read_config_file(const char *filename, long **offsets, int **keys, double **timestamps, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open config.csv: Permission denied or file does not exist.");
        return -1;
    }

