    char ch;
    *count = 0;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') (*count)++;
    }
    rewind(file);

    *offsets = malloc(*count * sizeof(long));
    *keys = malloc(*count * sizeof(int));
    *timestamps = malloc(*count * sizeof(double));

    if (!*offsets || !*keys || !*timestamps) {
        log_error("Memory allocation failed.");
        fclose(file);
        return -1;
    }

    // Read data
    for (size_t i = 0; i < *count; ++i) {
        if (fscanf(file, "%ld", &((*offsets)[i])) != 1 || (*offsets)[i] <= 0) {
            log_error("Invalid offset value.");
            free(*offsets);
            free(*keys);
            free(*timestamps);
            fclose(file);
            return -1;
        }
    }
    rewind(file);

    for (size_t i = 0; i < *count; ++i) {
        if (fscanf(file, "%d", &((*keys)[i])) != 1) {
