            free(*offsets);
            free(*keys);
            free(*timestamps);
            fclose(file);
            return -1;
        }
    }
    rewind(file);

    for (size_t i = 0; i < *count; ++i) {
        if (fscanf(file, "%lf", &((*timestamps)[i])) != 1) {
            log_error("Invalid timestamp value.");
            free(*offsets);
            free(*keys);
            free(*timestamps);
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

void initialize_data_streams(size_t num_streams, DataStream **streams) {
    *streams = malloc(num_streams * sizeof(DataStream));
    if (!*streams) {
        log_error("Failed to allocate memory for data streams.");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_streams; ++i) {
        (*streams)[i].metadata = strdup("Default Metadata");
        (*streams)[i].buffer = NULL;
        (*streams)[i].length = 0;
