void expand_buffer(DataStream *stream, size_t new_length) {
    float *new_buffer = realloc(stream->buffer, new_length * sizeof(float));
    if (!new_buffer) {
        log_error("Failed to reallocate buffer.");
        exit(EXIT_FAILURE);
    }
    stream->buffer = new_buffer;
    memset(stream->buffer + stream->length, 0, (new_length - stream->length) * sizeof(float));
    stream->length = new_length;
}

