<?php

class FileUtility {

    private $cache = [];

    public function generateRandomString($length, $charset) {
        if (!is_int($length) || $length <= 0) {
            throw new InvalidArgumentException('Length must be a positive integer.');
        }

        $string = '';
        $maxIndex = strlen($charset) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomByte = random_int(0, PHP_INT_MAX);
            $randCharIndex = $randomByte % ($maxIndex + 1);

            $string .= $charset[$randCharIndex];
        }

        return $string;
    }

    public function hashPassword($password, $algorithm = 'bcrypt', $options = []) {
        if (!in_array($algorithm, ['bcrypt', 'argon2id'])) {
            throw new InvalidArgumentException('Unsupported hashing algorithm.');
        }

        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT, $options);
            case 'argon2id':
                return password_hash($password, PASSWORD_ARGON2ID, $options);
            default:
                throw new RuntimeException('Hashing failed due to unsupported algorithm.');
        }
    }

    public function readFileContents($filePath, $cacheTTL = 3600) {
        if (isset($this->cache[$filePath]) && (time() - $this->cache[$filePath]['timestamp']) < $cacheTTL) {
            return $this->cache[$filePath]['data'];
        }

        if (!file_exists($filePath)) {
            throw new RuntimeException("File not found: $filePath");
        }

        if (!is_readable($filePath)) {
            throw new RuntimeException("File is not readable: $filePath");
        }

        $contents = file_get_contents($filePath);
        if ($contents === false) {
            throw new RuntimeException("Failed to read the file: $filePath");
        }

        $this->cache[$filePath] = [
            'data' => $contents,
            'timestamp' => time()
        ];

        return $contents;
    }

    public function fetchExternalData($url, $timeout = 30, $maxRetries = 3) {
        $retryCount = 0;

        while ($retryCount < $maxRetries) {
            try {
                $context = stream_context_create([
                    'http' => [
                        'method' => "GET",
                        'timeout' => $timeout
                    ]
                ]);

                $response = file_get_contents($url, false, $context);

                if ($response !== false) {
                    return $response;
                }
            } catch (Exception $e) {
                // Log error or handle it as needed
            }

            $retryCount++;
            sleep(pow(2, $retryCount)); // Exponential backoff
        }

        throw new RuntimeException("Failed to fetch data from URL: $url");
    }
}
