#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    float data;
} record;

// Define the initial size and growth factor for dynamic resizing.
#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

// Secondary storage pool to handle fragmentation and cache locality.
typedef struct {
    record *records;
    size_t capacity;
    size_t count;
} RecordCollection;

// Function prototypes
RecordCollection* create_record_collection(size_t initial_capacity);
void free_record_collection(RecordCollection* collection);
int add_record(RecordCollection* collection, long offset, int key, float data_range_min, float data_range_max);
record* get_record_by_index(RecordCollection* collection, size_t index);
record* find_record_by_key(RecordCollection* collection, int key);
void delete_record_by_index(RecordCollection* collection, size_t index);
void resize_collection_if_needed(RecordCollection* collection);

// Helper functions
static float generate_random_data(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Function implementations
RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate memory for record collection");
        exit(EXIT_FAILURE);
    }

    collection->records = malloc(initial_capacity * sizeof(record));
    if (!collection->records) {
        free(collection);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void free_record_collection(RecordCollection* collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}

int add_record(RecordCollection* collection, long offset, int key, float data_range_min, float data_range_max) {
    resize_collection_if_needed(collection);

    record new_record;
    new_record.offset = offset;
    new_record.key = key;
    new_record.data = generate_random_data(data_range_min, data_range_max);

    if (collection->count < collection->capacity) {
        collection->records[collection->count++] = new_record;
        return 0; // Success
    } else {
        fprintf(stderr, "Unable to add record: collection full\n");
        return -1; // Failure
    }
}

record* get_record_by_index(RecordCollection* collection, size_t index) {
    if (index < collection->count) {
        return &collection->records[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

record* find_record_by_key(RecordCollection* collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    return NULL;
}

void delete_record_by_index(RecordCollection* collection, size_t index) {
    if (index < collection->count) {
        for (size_t i = index; i < collection->count - 1; ++i) {
            collection->records[i] = collection->records[i + 1];
        }
        --collection->count;
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}

void resize_collection_if_needed(RecordCollection* collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * GROWTH_FACTOR;
        record* new_records = realloc(collection->records, new_capacity * sizeof(record));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            exit(EXIT_FAILURE);
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
}

// Iterator functions
void iterate_forward(RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        printf("Offset: %ld, Key: %d, Data: %.2f\n", 
               collection->records[i].offset,
               collection->records[i].key,
               collection->records[i].data);
    }
}

void iterate_reverse(RecordCollection* collection) {
    for (int i = collection->count - 1; i >= 0; --i) {
        printf("Offset: %ld, Key: %d, Data: %.2f\n", 
               collection->records[i].offset,
               collection->records[i].key,
               collection->records[i].data);
    }
}

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    RecordCollection* my_collection = create_record_collection(INITIAL_SIZE);

    add_record(my_collection, 100, 1, 0.0f, 10.0f);
    add_record(my_collection, 200, 2, 0.0f, 20.0f);
    add_record(my_collection, 300, 3, 5.0f, 15.0f);

    printf("Forward iteration:\n");
    iterate_forward(my_collection);

    printf("\nReverse iteration:\n");
    iterate_reverse(my_collection);

    free_record_collection(my_collection);

    return 0;
}
```']

