```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function prototypes
void* aligned_malloc(size_t size, size_t alignment);
void log_error(const char *message);
int allocate_memory(long **offsets, int **keys, Record ***records, size_t count);
void free_memory(long *offsets, int *keys, Record *records);

// Log file mutex for thread-safe logging
pthread_mutex_t log_file_mutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Allocates aligned memory.
 */
void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

/**
 * Logs an error message to a log file.
 */
void log_error(const char *message) {
    pthread_mutex_lock(&log_file_mutex);
    FILE *log_file = fopen("memory_management.log", "a");
    if (log_file) {
        fprintf(log_file, "ERROR: %s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&log_file_mutex);
}

/**
 * Allocates memory for the data structures.
 */
int allocate_memory(long **offsets, int **keys, Record ***records, size_t count) {
    if (!offsets || !keys || !records || count == 0) return -1;

    // Allocate aligned memory
    *offsets = (long*)aligned_malloc(count * sizeof(long), 64);
    if (*offsets == NULL) {
        log_error("Failed to allocate memory for offsets.");
        return -1;
    }

    *keys = (int*)aligned_malloc(count * sizeof(int), 64);
    if (*keys == NULL) {
        free(*offsets);
        log_error("Failed to allocate memory for keys.");
        return -1;
    }

    *records = (Record**)aligned_malloc(count * sizeof(Record*), 64);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        log_error("Failed to allocate memory for records array pointers.");
        return -1;
    }

    // Allocate and initialize each record
    for (size_t i = 0; i < count; ++i) {
        (*records)[i] = (Record*)aligned_malloc(sizeof(Record), 64);
        if ((*records)[i] == NULL) {
            free_memory(*offsets, *keys, *records);
            log_error("Failed to allocate memory for a record.");
            return -1;
        }

        // Initialize records with unique random integers
        (*records)[i]->value = rand() % 1000 + 1;  // Adjust range as needed
    }

    return 0;
}

/**
 * Frees all allocated memory.
 */
void free_memory(long *offsets, int *keys, Record *records) {
    if (!offsets || !keys || !records) return;

    for (size_t i = 0; records[i] != NULL; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    long *offsets;
    int *keys;
    Record **records;
    size_t count = 1000; // Example size

    if (allocate_memory(&offsets, &keys, &records, count) != 0) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Use the allocated structures...

    free_memory(offsets, keys, *records);

    return EXIT_SUCCESS;
}
