['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t pool_size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

#define LOG_FILE_NAME "app.log"
#define MAX_LOG_SIZE 1048576 // 1 MB
#define ARCHIVE_COUNT 5

void log_message(const char *message) {
    static FILE *log_file = NULL;
    static long file_size = 0;
    pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&log_lock);

    if (!log_file || file_size >= MAX_LOG_SIZE) {
        if (log_file) {
            fclose(log_file);

            char archive_name[256];
            for (int i = ARCHIVE_COUNT - 1; i > 0; --i) {
                snprintf(archive_name, sizeof(archive_name), "%s.%d", LOG_FILE_NAME, i);
                if (access(archive_name, F_OK) != -1) {
                    rename(archive_name, archive_name + 1);
                }
            }
            rename(LOG_FILE_NAME, archive_name + 1);

            log_file = fopen(LOG_FILE_NAME, "w");
            file_size = 0;
        } else {
            log_file = fopen(LOG_FILE_NAME, "a+");
        }
    }

    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
        fseek(log_file, 0, SEEK_END);
        file_size = ftell(log_file);
    }

    pthread_mutex_unlock(&log_lock);
}

void init_memory_pool(MemoryPool *mp, size_t block_size, size_t pool_size) {
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->used = 0;

    if (pthread_mutex_init(&mp->lock, NULL) != 0) {
        log_message("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    mp->pool = malloc(pool_size);
    if (!mp->pool) {
        pthread_mutex_destroy(&mp->lock);
        log_message("Memory pool allocation failed");
        exit(EXIT_FAILURE);
    }
}

void *allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    if (size > mp->block_size || (mp->used + size) > mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        log_message("Memory pool allocation failure: insufficient space");
        return NULL;
    }

    void *ptr = (char *)mp->pool + mp->used;
    mp->used += size;

    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

int generate_unique_random(int min, int max, int count, int *values) {
    if (max - min + 1 < count) {
        log_message("Failed to generate unique values: range too narrow");
        return 0;
    }

    for (int i = 0; i < count; ++i) {
        int value;
        do {
            value = rand() % (max - min + 1) + min;
        } while (!is_unique(value, values, i));

        values[i] = value;
    }
    return 1;
}

int is_unique(int value, int *values, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (values[i] == value) {
            return 0;
        }
    }
    return 1;
}

void manage_memory(size_t num_records, int key_min, int key_max) {
    srand(time(NULL));

    MemoryPool offset_pool, key_pool, record_pool;
    init_memory_pool(&offset_pool, sizeof(long), num_records * sizeof(long));
    init_memory_pool(&key_pool, sizeof(int), num_records * sizeof(int));
    init_memory_pool(&record_pool, sizeof(record), num_records * sizeof(record));

    long *offsets = (long *)allocate_from_pool(&offset_pool, num_records * sizeof(long));
    int *keys = (int *)allocate_from_pool(&key_pool, num_records * sizeof(int));
    record *records = (record *)allocate_from_pool(&record_pool, num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        log_message("Failed to allocate memory for data structures");
        free_memory_pool(&offset_pool);
        free_memory_pool(&key_pool);
        free_memory_pool(&record_pool);
        return;
    }

    int *unique_values = malloc(num_records * sizeof(int));
    if (!generate_unique_random(key_min, key_max, num_records, unique_values)) {
        log_message("Failed to generate unique keys");
        free(unique_values);

        free_memory_pool(&offset_pool);
        free_memory_pool(&key_pool);
        free_memory_pool(&record_pool);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = (long)i * sizeof(record); // Example offset calculation
        keys[i] = unique_values[i];
        records[i].value = unique_values[i]; // Assigning the same unique value to record for demonstration
    }

    free(unique_values);

    log_message("Memory management completed successfully");

    free_memory_pool(&offset_pool);
    free_memory_pool(&key_pool);
    free_memory_pool(&record_pool);
}

int main() {
    manage_memory(100, 1, 200);
    return 0;
}
