    if (collection->count == collection->capacity) {
        resize_collection(collection);
    }

    CollectionItem item;
    item.offset = offset;
    item.key = key;

    Record record;
    record.value = value;
    record.offset_ptr = &item.offset;
    record.key_ptr = &item.key;

    item.record = record;

    collection->items[collection->count++] = item;

    pthread_mutex_unlock(&collection->lock);
}

void update_record(DynamicCollection *collection, size_t index, int new_value) {
    if (index >= collection->count)
        return; // Index out of bounds

    pthread_mutex_lock(&collection->lock);

    collection->items[index].record.value = new_value;

    pthread_mutex_unlock(&collection->lock);
}

CollectionItem* get_record_by_index(DynamicCollection *collection, size_t index) {
    if (index >= collection->count)
        return NULL; // Index out of bounds

    pthread_mutex_lock(&collection->lock);

    CollectionItem *item = &collection->items[index];

    pthread_mutex_unlock(&collection->lock);
    return item;
}

CollectionItem* get_record_by_key(DynamicCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].key == key) {
            CollectionItem *item = &collection->items[i];
            pthread_mutex_unlock(&collection->lock);
            return item;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Key not found
}

void free_collection(DynamicCollection *collection) {
    free(collection->items);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

