}

long random_long(long min, long max) {
    return min + rand() % (max - min + 1);
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

float random_float(float min, float max) {
    return min + ((float)rand() / RAND_MAX) * (max - min);
}

DynamicRecordManager* create_manager(const char* log_filename) {
    DynamicRecordManager* manager = malloc(sizeof(DynamicRecordManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_manager(DynamicRecordManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);
    free(manager);
}

void log_allocation(DynamicRecordManager* manager, const char* message) {
    fprintf(manager->log_file, "%s\n", message);
    fflush(manager->log_file); // Ensure logs are written
}

Node* create_node(Record record) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->record = record;
    node->next = NULL;

    return node;
}

void add_record(DynamicRecordManager* manager, Record record) {
    pthread_mutex_lock(&manager->lock);

    Node* new_node = create_node(record);
    if (!new_node) {
        log_allocation(manager, "Failed to allocate memory for new record");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    new_node->next = manager->head;
    manager->head = new_node;
    manager->count++;

    log_allocation(manager, "Record added successfully");

    pthread_mutex_unlock(&manager->lock);
}

void remove_record_by_key(DynamicRecordManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    Node **indirect = &manager->head;
    while (*indirect) {
        if ((*indirect)->record.key == key) {
            Node *node_to_remove = *indirect;
            *indirect = node_to_remove->next;

            free(node_to_remove);
            manager->count--;

            log_allocation(manager, "Record removed successfully");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

Record* get_record_by_index(DynamicRecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    for (size_t i = 0; current && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    Record* record = malloc(sizeof(Record));
    *record = current->record;

    pthread_mutex_unlock(&manager->lock);
    return record;
}

void iterate_records(DynamicRecordManager* manager, void (*callback)(const Record*)) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        callback(&(current->record));
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void export_records(DynamicRecordManager* manager, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    Node* current = manager->head;
    while (current) {
        fprintf(file, "%ld %d %.2f\n", current->record.offset,
                current->record.key, current->record.data);
        current = current->next;
    }

    fclose(file);
}

void add_random_records(DynamicRecordManager* manager, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        Record record = {random_long(0, 100000), random_int(1, 1000),
                         random_float(0.0f, 10.0f)};
        add_record(manager, record);
    }
}

void free_record(Record* record) {
    free(record);
}

int main() {
    init_random();
    DynamicRecordManager* manager = create_manager("manager.log");

    if (!manager) return EXIT_FAILURE;

    add_random_records(manager, 20);

    iterate_records(manager, [](const Record* r){
        printf("Offset: %ld, Key: %d, Data: %.2f\n", r->offset, r->key, r->data);
    });

    export_records(manager, "records.txt");

    destroy_manager(manager);

    return EXIT_SUCCESS;
}
