```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define RESIZE_THRESHOLD 0.75

typedef struct {
    long offset;
    int key;
    float data;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    record *records;
} RecordCollection;

static void initialize_records(record *records, size_t num_records, float min_val, float max_val) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % 1000;
        records[i].data = ((float)rand() / RAND_MAX) * (max_val - min_val) + min_val;
    }
}

static void resize_collection(RecordCollection *collection, size_t new_capacity) {
    record *new_records = realloc(collection->records, new_capacity * sizeof(record));
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    collection->records = new_records;
    collection->capacity = new_capacity;
}

RecordCollection* create_record_collection(size_t initial_size, float min_val, float max_val) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_size;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    collection->records = malloc(initial_size * sizeof(record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        free(collection->records);
        exit(EXIT_FAILURE);
    }

    initialize_records(collection->records, initial_size, min_val, max_val);
    return collection;
}

void add_record(RecordCollection *collection, record new_record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= RESIZE_THRESHOLD * collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        resize_collection(collection, new_capacity);
    }

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
}

record get_record_by_index(RecordCollection *collection, size_t index) {
    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    return collection->records[index];
}

void delete_record_by_index(RecordCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&collection->lock);
        exit(EXIT_FAILURE);
    }

    memmove(&collection->records[index], &collection->records[index + 1],
            (collection->count - index - 1) * sizeof(record));
    collection->count--;

    pthread_mutex_unlock(&collection->lock);
}

void free_record_collection(RecordCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

void merge_external_batch(RecordCollection *collection, record *batch, size_t batch_size) {
    for (size_t i = 0; i < batch_size; ++i) {
        add_record(collection, batch[i]);
    }
}
