    int unique_id;
    struct data_item* next;
} data_item;

typedef struct node {
    char str[STRING_LENGTH + 1];
    int integer;
    data_item* data_head;
    struct node* next;
} node;

node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random alphanumeric string
void generate_random_string(char* str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to initialize and manage complex records
void initializeAndManageComplexRecords(int num_nodes) {
    srand(time(NULL));

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < num_nodes; ++i) {
        node* new_node = malloc(sizeof(node));
        if (!new_node) {
            perror("Failed to allocate memory for node");
            exit(EXIT_FAILURE);
        }

        generate_random_string(new_node->str, STRING_LENGTH);
        new_node->integer = rand() % (INT_MAX_RANGE - INT_MIN_RANGE + 1) + INT_MIN_RANGE;
        new_node->data_head = NULL;

        int num_data_items = rand() % 10 + 1; // Random number of data items between 1 and 10
        for (int j = 0; j < num_data_items; ++j) {
            data_item* new_data_item = malloc(sizeof(data_item));
            if (!new_data_item) {
                perror("Failed to allocate memory for data item");
                exit(EXIT_FAILURE);
            }

            new_data_item->timestamp = time(NULL) * 1000 + j;
            new_data_item->unique_id = rand();
            new_data_item->next = new_node->data_head;
            new_node->data_head = new_data_item;
        }

        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to add a data item to a specific node
void addDataItemToNode(int index) {
    pthread_mutex_lock(&list_mutex);

    node* current = head;
    for (int i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current) {
        data_item* new_data_item = malloc(sizeof(data_item));
        if (!new_data_item) {
            perror("Failed to allocate memory for data item");
            exit(EXIT_FAILURE);
        }

        new_data_item->timestamp = time(NULL) * 1000;
        new_data_item->unique_id = rand();
        new_data_item->next = current->data_head;
        current->data_head = new_data_item;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to retrieve a specific node by index
node* getNodeByIndex(int index) {
    pthread_mutex_lock(&list_mutex);

    node* current = head;
    for (int i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    node* result = current;

    pthread_mutex_unlock(&list_mutex);
    return result;
}

// Function to print all nodes and their data items
void printAllNodes() {
    pthread_mutex_lock(&list_mutex);

    for (node* current = head; current != NULL; current = current->next) {
        printf("Node: %s, Integer: %d\n", current->str, current->integer);
        for (data_item* data = current->data_head; data != NULL; data = data->next) {
            printf("\tData Item: Timestamp: %ld, Unique ID: %d\n", data->timestamp, data->unique_id);
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

// Helper function to find the largest integer in an array
int findLargestInteger(int* arr, int size) {
    if (size <= 0) return INT_MIN_RANGE;

    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from standard input, store them in an array, and find the largest integer
void processInputIntegers() {
    int num_ints, value;
    printf("Enter number of integers: ");
    scanf("%d", &num_ints);

    int* arr = malloc(num_ints * sizeof(int));
    if (!arr) {
        perror("Failed to allocate memory for input array");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers:\n", num_ints);
    for (int i = 0; i < num_ints; ++i) {
        scanf("%d", &value);
        arr[i] = value;
    }

    int largest = findLargestInteger(arr, num_ints);
    printf("The largest integer is: %d\n", largest);

    free(arr);
}

