['Here's a C implementation for managing a dynamically allocated list of `node` structures with linked lists of `data_item` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 10
#define MIN_INT_VALUE 0
#define MAX_INT_VALUE 100
#define MAX_DATA_ITEMS_PER_NODE 20

typedef struct data_item {
    long timestamp;
    int unique_id;
    struct data_item* next;
} data_item;

typedef struct node {
    char* string;
    int integer_value;
    data_item* data_list_head;
    struct node* next;
} node;

node* initialize_node_list(size_t num_nodes) {
    if (num_nodes == 0) return NULL;

    node* head = NULL;
    node** current_ptr = &head;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_nodes; ++i) {
        *current_ptr = malloc(sizeof(node));
        if (!*current_ptr) {
            // Handle allocation failure
            while (head != NULL) {
                node* to_free = head;
                head = head->next;

                free(to_free->string);
                data_item* data_current = to_free->data_list_head;
                while (data_current) {
                    data_item* temp = data_current;
                    data_current = data_current->next;
                    free(temp);
                }
                free(to_free);
            }
            return NULL;
        }

        (*current_ptr)->string = malloc(MAX_STRING_LENGTH + 1);
        if (!(*current_ptr)->string) {
            // Handle allocation failure
            free(*current_ptr);
            while (head != NULL) {
                node* to_free = head;
                head = head->next;

                data_item* data_current = to_free->data_list_head;
                while (data_current) {
                    data_item* temp = data_current;
                    data_current = data_current->next;
                    free(temp);
                }
                free(to_free);
            }
            return NULL;
        }

        for (int j = 0; j < MAX_STRING_LENGTH; ++j) {
            char rand_char = (rand() % 2 == 0 ? 'a' + (rand() % 26) : '0' + (rand() % 10));
            (*current_ptr)->string[j] = rand_char;
        }
        (*current_ptr)->string[MAX_STRING_LENGTH] = '\0';

        (*current_ptr)->integer_value = MIN_INT_VALUE + rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1);

        size_t num_data_items = rand() % MAX_DATA_ITEMS_PER_NODE + 1;
        data_item* data_current = NULL;

        for (size_t j = 0; j < num_data_items; ++j) {
            data_item* new_data_item = malloc(sizeof(data_item));
            if (!new_data_item) {
                // Handle allocation failure
                free((*current_ptr)->string);
                while ((*current_ptr)->data_list_head != NULL) {
                    data_current = (*current_ptr)->data_list_head;
                    (*current_ptr)->data_list_head = data_current->next;
                    free(data_current);
                }
                free(*current_ptr);
                while (head != NULL) {
                    node* to_free = head;
                    head = head->next;

                    data_item* temp_data_current = to_free->data_list_head;
                    while (temp_data_current) {
                        data_item* temp = temp_data_current;
                        temp_data_current = temp_data_current->next;
                        free(temp);
                    }
                    free(to_free);
                }
                return NULL;
            }

            new_data_item->timestamp = time(NULL) * 1000 + rand() % 1000; // Unique millisecond timestamp
            new_data_item->unique_id = rand(); 
            new_data_item->next = data_current;
            (*current_ptr)->data_list_head = new_data_item;
            data_current = new_data_item;
        }

        current_ptr = &(*current_ptr)->next;
    }
    return head;
}

void add_data_item_to_node(node* target_node, long timestamp, int unique_id) {
    if (!target_node) return;

    data_item* new_data_item = malloc(sizeof(data_item));
    if (!new_data_item) {
        // Handle allocation failure
        fprintf(stderr, "Failed to allocate memory for new data item.\n");
        return;
    }

    new_data_item->timestamp = timestamp;
    new_data_item->unique_id = unique_id;
    new_data_item->next = target_node->data_list_head;
    target_node->data_list_head = new_data_item;
}

node* get_node_by_index(node* head, size_t index) {
    node* current = head;
    while (current && index-- > 0) {
        current = current->next;
    }
    return current;
}

void print_all_nodes(node* head) {
    node* current = head;
    while (current != NULL) {
        printf("Node String: %s, Integer Value: %d\n", current->string, current->integer_value);
        data_item* data_current = current->data_list_head;
        while (data_current != NULL) {
            printf("\tData Item - Timestamp: %ld, Unique ID: %d\n", data_current->timestamp, data_current->unique_id);
            data_current = data_current->next;
        }
        current = current->next;
    }
}

void free_node_list(node* head) {
    while (head != NULL) {
        node* to_free = head;
        head = head->next;

        free(to_free->string);
        data_item* data_current = to_free->data_list_head;
        while (data_current) {
            data_item* temp = data_current;
            data_current = data_current->next;
            free(temp);
        }
        free(to_free);
    }
}

int main() {
    size_t num_nodes = 100; // Example usage
    node* list = initialize_node_list(num_nodes);

    if (list) {
        print_all_nodes(list);

        // Adding a new data item to the first node for demonstration
        add_data_item_to_node(get_node_by_index(list, 0), time(NULL) * 1000 + rand() % 1000, rand());

        free_node_list(list);
    }

    return 0;
}
