    unsigned int file_size;
    time_t modification_time;
    char file_type[20];
    mode_t access_permissions;
} file_entry;

typedef struct {
    file_entry *entries;
    size_t capacity;
    size_t count;
} file_manager;

// Function to initialize the dynamic array with a specified number of entries.
void init_file_manager(file_manager *fm, size_t initial_capacity) {
    fm->capacity = initial_capacity;
    fm->count = 0;
    fm->entries = (file_entry *)calloc(fm->capacity, sizeof(file_entry));
    if (!fm->entries) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to resize the dynamic array.
void resize_file_manager(file_manager *fm, size_t new_capacity) {
    file_entry *new_entries = (file_entry *)realloc(fm->entries, new_capacity * sizeof(file_entry));
    if (!new_entries) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    fm->capacity = new_capacity;
    fm->entries = new_entries;
}

// Function to add a new file entry.
void add_file_entry(file_manager *fm, const char **paths, unsigned int size_range_min, unsigned int size_range_max) {
