        resize_file_manager(fm, fm->capacity * 2);
    }

    file_entry *entry = &fm->entries[fm->count++];
    entry->file_size = rand() % (size_range_max - size_range_min + 1) + size_range_min;
    entry->modification_time = time(NULL);

    for (int i = 0; i < 5 && paths[i]; ++i) {
        entry->file_paths[i] = strdup(paths[i]);
    }

    strcpy(entry->file_type, DEFAULT_FILE_TYPE);
    entry->access_permissions = DEFAULT_ACCESS_PERMISSIONS;

    // Logging the addition of a new file entry
    printf("Added file entry: size=%u, mod_time=%ld\n", entry->file_size, (long)entry->modification_time);
