}

// Clean up the file manager.
void cleanup_file_manager(file_manager *fm) {
    for (size_t i = 0; i < fm->count; ++i) {
        for (int j = 0; j < 5; ++j) {
            free(fm->entries[i].file_paths[j]);
        }
    }
    free(fm->entries);
}

// Example usage
void print_file_entry(const file_entry *entry) {
    printf("File Entry: Size=%u, ModTime=%ld\n", entry->file_size, (long)entry->modification_time);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    file_manager fm;
    init_file_manager(&fm, 10);

    const char *paths[] = {"path1", "path2", NULL};
    add_file_entry(&fm, paths, 100, 1024);
    iterate_file_entries(&fm, print_file_entry);

    export_file_manager_state(&fm, "file_manager_state.txt");
    cleanup_file_manager(&fm);

    return 0;
}
