            if (!new_entry.file_paths) {
                fprintf(stderr, "Memory allocation failed\n");
                return -1;
            }
            for (size_t j = 0; j < path_count; ++j) {
                new_entry.file_paths[j] = strdup("path/to/file");
            }

            new_entries[i] = new_entry;
        }

        fc->entries = new_entries;
        fc->capacity = new_capacity;
    }

    // Fill in the new entry with provided data
    size_t index = fc->count++;
    fc->entries[index].file_size = rand() % 1000000 + 1; // Random file size
    fc->entries[index].modification_time = time(NULL); // Current timestamp

    fc->entries[index].file_paths = malloc(sizeof(char *) * path_count);
    if (!fc->entries[index].file_paths) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < path_count; ++i) {
        fc->entries[index].file_paths[i] = strdup(paths[i]);
    }

