}

void prune_old_entries(file_collection *fc, time_t cutoff_time) {
    size_t new_count = 0;
    for (size_t i = 0; i < fc->count; ++i) {
        if (fc->entries[i].modification_time >= cutoff_time) {
            fc->entries[new_count++] = fc->entries[i];
        } else {
            // Free the paths array of pruned entry
