        if (*size >= *capacity) {
            *capacity *= 2;
            dataEntry *newEntries = realloc(*entries, *capacity * sizeof(dataEntry));
            if (!newEntries) {
                perror("Failed to reallocate memory");
                return;
            }
            *entries = newEntries;
        }

        int index = *size;
        (*entries)[index].identifier = malloc(12);
        snprintf((*entries)[index].identifier, 12, "ID_%d", index);

        (*entries)[index].value = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);

        (*entries)[index].metadata = NULL;
        (*size)++;
    }

    // Functionality to search by index
    dataEntry* searchByIndex(dataEntry *entries, int size, int index) {
        if (index >= 0 && index < size) {
            return &entries[index];
        }
        return NULL;
    }

    // Calculate the average of double values in entries
    double calculateAverage(dataEntry *entries, int size) {
        double sum = 0.0;
        for (int i = 0; i < size; ++i) {
            sum += entries[i].value;
        }
        return (size > 0) ? (sum / size) : 0.0;
    }

    // Helper function to read the longest string from standard input
    int readLongestString(char **inputList, int numEntries) {
        if (!inputList || numEntries <= 0) return -1;

        int maxLength = 0, maxIndex = -1;
        for (int i = 0; i < numEntries; ++i) {
            int currentLength = strlen(inputList[i]);
            if (currentLength > maxLength) {
                maxLength = currentLength;
                maxIndex = i;
            }
        }

        return maxIndex;
    }

    // Usage example
    int size = initialSize, capacity = initialSize;
    addEntry(&entries, &size, &capacity);

    dataEntry *foundEntry = searchByIndex(entries, size, 5);
    if (foundEntry) {
        printf("Found entry: %s with value %.2f\n", foundEntry->identifier, foundEntry->value);
    }

    double average = calculateAverage(entries, size);
    printf("Average value of entries: %.2f\n", average);

    // Free allocated resources
    for (int i = 0; i < size; ++i) {
        free(entries[i].identifier);
        if (entries[i].metadata) free(entries[i].metadata);
    }
    free(entries);
}

