#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_RANGE 1000

typedef struct {
    int value;
    long *offset;
    int *key;
    volatile int reference_count;
} Record;

typedef struct {
    Record **records;
    size_t record_count;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* initializeAndManageRecords(size_t num_records) {
    // Initialize record collection
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->record_count = num_records;
    collection->records = (Record **)calloc(num_records, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    // Populate records with random values
    for (size_t i = 0; i < num_records; ++i) {
        collection->records[i] = (Record *)malloc(sizeof(Record));
        if (!collection->records[i]) goto cleanup;

        collection->records[i]->value = rand() % MAX_RANGE;
        collection->records[i]->offset = NULL;
        collection->records[i]->key = NULL;
        collection->records[i]->reference_count = 0;
    }

    return collection;

cleanup:
    for (size_t i = 0; i < num_records; ++i) {
        if (collection->records[i]) free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
    return NULL;
}

void updateRecord(RecordCollection *collection, size_t index, long new_offset, int new_key) {
    pthread_mutex_lock(&collection->mutex);

    if (index < collection->record_count && collection->records[index]) {
        Record *record = collection->records[index];
        record->reference_count++;

        // Perform atomic updates
        long old_offset = 0;
        int old_key = 0;

        __sync_bool_compare_and_swap(&(record->offset), &old_offset, &new_offset);
        __sync_bool_compare_and_swap(&(record->key), &old_key, &new_key);

        record->reference_count--;
    }

    pthread_mutex_unlock(&collection->mutex);
}

Record* getRecordByKey(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);

    Record *found = NULL;
    for (size_t i = 0; i < collection->record_count; ++i) {
        if (collection->records[i] && collection->records[i]->key && 
            *collection->records[i]->key == key) {
            found = collection->records[i];
            break;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return found;
}

void serializeRecords(const RecordCollection *collection, const char *filename) {
    pthread_mutex_lock((pthread_mutex_t *)&collection->mutex);

    FILE *file = fopen(filename, "wb");
    if (!file) goto cleanup;

    fwrite(&(collection->record_count), sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *rec = collection->records[i];
        if (rec) {
            fwrite(&rec->value, sizeof(int), 1, file);
            long offset;
            int key;
            memcpy(&offset, rec->offset, sizeof(long));
            memcpy(&key, rec->key, sizeof(int));
            fwrite(&offset, sizeof(long), 1, file);
            fwrite(&key, sizeof(int), 1, file);
        }
    }

cleanup:
    if (file) fclose(file);
    pthread_mutex_unlock((pthread_mutex_t *)&collection->mutex);
}

RecordCollection* deserializeRecords(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) goto cleanup;

    fread(&(collection->record_count), sizeof(size_t), 1, file);
    collection->records = (Record **)calloc(collection->record_count, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        goto cleanup;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *rec = (Record *)malloc(sizeof(Record));
        if (!rec) goto cleanup;

        fread(&(rec->value), sizeof(int), 1, file);
        long offset;
        int key;
        fread(&offset, sizeof(long), 1, file);
        rec->offset = malloc(sizeof(long));
        memcpy(rec->offset, &offset, sizeof(long));

        fread(&key, sizeof(int), 1, file);
        rec->key = malloc(sizeof(int));
        memcpy(rec->key, &key, sizeof(int));

        rec->reference_count = 0;
        collection->records[i] = rec;
    }

cleanup:
    if (file) fclose(file);
    return collection;
}

int findMaxInArray(int *array, size_t array_size) {
    int max_value = INT_MIN;

    for (size_t i = 0; i < array_size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }

    return max_value;
}

void processInputAndFindMax() {
    size_t input_size;
    printf("Enter the number of integers: ");
    scanf("%zu", &input_size);

    int *inputs = (int *)malloc(input_size * sizeof(int));
    if (!inputs) return;

    printf("Enter %zu integers:\n", input_size);
    for (size_t i = 0; i < input_size; ++i) {
        scanf("%d", &(inputs[i]));
    }

    int max_value = findMaxInArray(inputs, input_size);
    printf("The largest integer is: %d\n", max_value);

    free(inputs);
}

int main() {
    size_t num_records;
    printf("Enter the number of records to initialize: ");
    scanf("%zu", &num_records);

    RecordCollection *collection = initializeAndManageRecords(num_records);
    if (!collection) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    processInputAndFindMax();

    // Example usage:
    updateRecord(collection, 0, (long)12345, 678);

    Record *record = getRecordByKey(collection, 678);
    if (record) {
        printf("Found record with value: %d\n", record->value);
    }

    serializeRecords(collection, "records.dat");

    RecordCollection *loaded_collection = deserializeRecords("records.dat");
    if (loaded_collection) {
        printf("Deserialized records successfully\n");
        // Clean up loaded collection...
    }

    // Cleanup
    for (size_t i = 0; i < collection->record_count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);

    return EXIT_SUCCESS;
}
