```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t offsets_count;
    size_t keys_capacity;
    size_t records_capacity;
    pthread_mutex_t lock;
    unsigned char *key_usage; // Bit array to track used keys
} memory_manager;

#define INITIAL_OFFSETS_COUNT 10
#define INITIAL_KEYS_CAPACITY 1000
#define INITIAL_RECORDS_CAPACITY 1000

// Function prototypes
void initialize_memory_manager(memory_manager *manager, int key_range);
int add_key(memory_manager *manager, unsigned long min_key, unsigned long max_key);
record *allocate_record(memory_manager *manager, int min_value, int max_value);
void free_memory_manager(memory_manager *manager);

// Thread-safe function to generate a random number
unsigned long get_random_number(unsigned long min, unsigned long max) {
    return (rand() % (max - min + 1)) + min;
}

void initialize_memory_manager(memory_manager *manager, int key_range) {
    manager->offsets = malloc(INITIAL_OFFSETS_COUNT * sizeof(long));
    if (!manager->offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    manager->offsets_count = INITIAL_OFFSETS_COUNT;

    manager->keys_capacity = INITIAL_KEYS_CAPACITY;
    manager->keys = calloc(manager->keys_capacity, sizeof(int));
    if (!manager->keys) {
        perror("Failed to allocate memory for keys");
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    manager->records_capacity = INITIAL_RECORDS_CAPACITY;
    manager->records = malloc(manager->records_capacity * sizeof(record));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        free(manager->keys);
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    manager->key_usage = calloc((key_range + 7) / 8, sizeof(unsigned char)); // Bit array
    if (!manager->key_usage) {
        perror("Failed to allocate memory for key usage tracking");
        free(manager->records);
        free(manager->keys);
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);

    srand(time(NULL)); // Seed the random number generator
}

int add_key(memory_manager *manager, unsigned long min_key, unsigned long max_key) {
    if (pthread_mutex_lock(&manager->lock) != 0) {
        perror("Failed to acquire lock");
        return -1;
    }

    int key;
    do {
        key = get_random_number(min_key, max_key);
        size_t byte_index = key / 8;
        size_t bit_index = key % 8;

        if (byte_index >= (manager->keys_capacity + 7) / 8) {
            // Resize key storage and usage tracking
            manager->keys_capacity *= 2;
            manager->keys = realloc(manager->keys, manager->keys_capacity * sizeof(int));
            manager->key_usage = realloc(manager->key_usage, (manager->keys_capacity + 7) / 8);
            if (!manager->keys || !manager->key_usage) {
                perror("Failed to reallocate memory for keys or key usage tracking");
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }
        }

    } while ((manager->key_usage[byte_index] & (1 << bit_index)) != 0);

    manager->keys[manager->offsets_count++] = key;
    manager->key_usage[byte_index] |= (1 << bit_index);

    if (pthread_mutex_unlock(&manager->lock) != 0) {
        perror("Failed to release lock");
        return -1;
    }

    return 0;
}

record *allocate_record(memory_manager *manager, int min_value, int max_value) {
    if (pthread_mutex_lock(&manager->lock) != 0) {
        perror("Failed to acquire lock");
        return NULL;
    }

    if (manager->offsets_count >= manager->records_capacity) {
        // Resize records storage
        size_t new_capacity = manager->records_capacity * 2;
        record *new_records = realloc(manager->records, new_capacity * sizeof(record));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }
        manager->records = new_records;
        manager->records_capacity = new_capacity;
    }

    record *rec = &manager->records[manager->offsets_count];
    rec->value = get_random_number(min_value, max_value);

    if (pthread_mutex_unlock(&manager->lock) != 0) {
        perror("Failed to release lock");
        return NULL;
    }

    return rec;
}

void free_memory_manager(memory_manager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->keys);
    free(manager->records);
    free(manager->offsets);
    free(manager->key_usage);
}
```

### Key Points:

- **Concurrency**: Uses `pthread_mutex_t` for thread safety.
- **Memory Management**: Dynamically resizes arrays when needed, ensuring efficient memory usage.
- **Error Handling**: Checks for allocation failures and exits gracefully if necessary.
- **Randomness**: Utilizes a simple random number generator with seeding.
- **Key Uniqueness**: Uses a bit array to track used keys efficiently.

This implementation provides a robust framework for managing memory dynamically while handling concurrency and ensuring unique key management.']

