#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char *value; // dynamically allocated string
} Node;

// Define a version for backward compatibility
#define CURRENT_VERSION 2
#define LEGACY_VERSION 1

typedef struct ListNode {
    Node node;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    size_t count;
} NodeList;

NodeList* create_node_list() {
    NodeList *list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void free_node_list(NodeList *list) {
    ListNode *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current->node.value);
        free(current);
        current = next;
    }
    free(list);
}

int insert_node(NodeList *list, Node node) {
    if (!list || !node.value) return -1;

    ListNode *newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return -1;

    newNode->node = node;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    return 0;
}

int delete_node(NodeList *list, int key) {
    if (!list) return -1;

    ListNode **current = &list->head, *temp;
    while (*current != NULL) {
        if ((*current)->node.key == key) {
            temp = *current;
            *current = (*current)->next;
            free(temp->node.value);
            free(temp);
            list->count--;
            return 0;
        }
        current = &(*current)->next;
    }

    return -1; // Key not found
}

Node* search_node(NodeList *list, int key) {
    if (!list) return NULL;

    ListNode *current = list->head;
    while (current != NULL) {
        if (current->node.key == key) {
            return &(current->node);
        }
        current = current->next;
    }

    return NULL; // Key not found
}

int serialize_node_list(NodeList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&CURRENT_VERSION, sizeof(int), 1, file);
    fwrite(&(list->count), sizeof(size_t), 1, file);

    ListNode *current = list->head;
    while (current != NULL) {
        fwrite(&(current->node.offset), sizeof(long), 1, file);
        fwrite(&(current->node.key), sizeof(int), 1, file);
        size_t value_len = strlen(current->node.value) + 1; // include null terminator
        fwrite(&value_len, sizeof(size_t), 1, file);
        fwrite(current->node.value, sizeof(char), value_len, file);
        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserialize_node_list(NodeList **list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int version;
    fread(&version, sizeof(int), 1, file);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    *list = create_node_list();
    if (!*list) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
        Node node;
        fread(&(node.offset), sizeof(long), 1, file);

        // Handle version differences
        if (version >= LEGACY_VERSION && version < CURRENT_VERSION) {
            int legacy_key_size;
            fread(&legacy_key_size, sizeof(int), 1, file);
            char *key_str = (char*)malloc(legacy_key_size + 1);
            if (!key_str) break; // Handle allocation failure
            fread(key_str, sizeof(char), legacy_key_size, file);
            key_str[legacy_key_size] = '\0';
            node.key = atoi(key_str); // Assume conversion to int
            free(key_str);
        } else {
            fread(&(node.key), sizeof(int), 1, file);
        }

        size_t value_len;
        fread(&value_len, sizeof(size_t), 1, file);
        node.value = (char*)malloc(value_len);
        if (!node.value) break; // Handle allocation failure
        fread(node.value, sizeof(char), value_len, file);

        insert_node(*list, node);
    }

    fclose(file);
    return 0;
}

// Example usage:
/*
int main() {
    NodeList *myList = create_node_list();
    Node myNode = { .offset = 1234, .key = 1, .value = strdup("Hello World") };
    insert_node(myList, myNode);

    Node *found = search_node(myList, 1);
    if (found) printf("Found node with key %d: %s\n", found->key, found->value);

    serialize_node_list(myList, "nodes.dat");
    free_node_list(myList);

    NodeList *loadedList;
    deserialize_node_list(&loadedList, "nodes.dat");
    // Process loaded list...

    free_node_list(loadedList);
    return 0;
}
*/
