#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RECORD_BUFFER_SIZE 1024

typedef struct {
    int value;
    char *buffer;
} Record;

void manage_memory(int n) {
    if (n == 0) return;

    long *offsets = calloc(n, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    Record *records = calloc(n, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(keys);
        free(offsets);
        return;
    }

    char *buffer_pool = malloc(n * RECORD_BUFFER_SIZE);
    if (!buffer_pool) {
        fprintf(stderr, "Memory allocation failed for buffer pool\n");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    srand(time(NULL));

    // Initialize records
    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % 2001 - 1000;
        if (buffer_pool != NULL) {
            records[i].buffer = buffer_pool + (i * RECORD_BUFFER_SIZE);
        } else {
            records[i].buffer = NULL;
        }
    }

    // Logging
    for (int i = 0; i < n; ++i) {
        printf("Record %d: Value = %d\n", i, records[i].value);
        if (records[i].buffer != NULL && *records[i].buffer != '\0') {
            char log[11] = {0};
            snprintf(log, sizeof(log), "%.*s", 10, records[i].buffer);
            printf("Buffer: %s\n", log);
        }
    }

    // Cleanup
    free(buffer_pool);
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    int n = 5; // Example size
    manage_memory(n);
    return 0;
}
