typedef struct RecordList {
    Record *records;
    size_t size;
    size_t capacity;
} RecordList;

RecordList* dynamicRecordManager(char initialChar) {
    RecordList *list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->size = 0;
    list->capacity = INITIAL_CAPACITY;

    list->records = malloc(list->capacity * sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    for (size_t i = 0; i < list->capacity; ++i) {
        list->records[i].value = 0.0;
        list->records[i].identifier = initialChar;
        list->records[i].name = malloc(1); // empty string
        if (!list->records[i].name) {
            for (size_t j = 0; j < i; ++j)
                free(list->records[j].name);
            free(list->records);
            free(list);
            return NULL;
        }
        list->records[i].name[0] = '\0';
    }

    return list;
}

void resizeRecordList(RecordList *list) {
    size_t newCapacity = list->capacity + CHUNK_SIZE;
    Record *newRecords = realloc(list->records, newCapacity * sizeof(Record));
    if (!newRecords) return;

    for (size_t i = list->capacity; i < newCapacity; ++i) {
        newRecords[i].value = 0.0;
        newRecords[i].identifier = ' '; // default to space or another suitable character
        newRecords[i].name = malloc(1);
        if (!newRecords[i].name) {
            for (size_t j = list->capacity; j < i; ++j)
                free(newRecords[j].name);
            free(newRecords);
            list->records = NULL;
            return;
        }
        newRecords[i].name[0] = '\0';
    }

    list->records = newRecords;
    list->capacity = newCapacity;
}

void addRecord(RecordList *list, double value, char identifier, const char *name) {
    if (list->size >= list->capacity)
        resizeRecordList(list);

    Record *record = &list->records[list->size++];
    record->value = value;
    record->identifier = identifier;

    size_t nameLen = strlen(name) + 1;
    record->name = malloc(nameLen);
    if (!record->name) return;

    strcpy(record->name, name);
}

void freeRecordList(RecordList *list) {
    for (size_t i = 0; i < list->size; ++i)
        free(list->records[i].name);

    free(list->records);
    free(list);
}

int readValidIntegers(int min, int max, int **array, size_t *count) {
    char line[256];
    *array = NULL;
    *count = 0;

    printf("Enter integers (end with a non-integer):\n");
    while (fgets(line, sizeof(line), stdin)) {
        char *endptr;
        long value = strtol(line, &endptr, 10);

        if (*endptr == '\n' && value >= min && value <= max) {
            int *newArray = realloc(*array, (*count + 1) * sizeof(int));
            if (!newArray) return -1;

            (*array) = newArray;
            (*array)[*count] = (int)value;
            (*count)++;
        } else {
            fprintf(stderr, "Warning: Invalid input skipped.\n");
        }
    }

    return 0;
}

int main() {
    RecordList *recordManager = dynamicRecordManager('A');
    if (!recordManager) {
        fprintf(stderr, "Failed to initialize record manager.\n");
        return EXIT_FAILURE;
    }

    int *validIntegers = NULL;
    size_t validCount = 0;

    if (readValidIntegers(1, 100, &validIntegers, &validCount)) {
        fprintf(stderr, "Memory allocation failed during integer reading.\n");
        freeRecordList(recordManager);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < validCount; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "Name%d", validIntegers[i]);
        addRecord(recordManager, (double)validIntegers[i], 'B', name);
    }

    // Free dynamically allocated resources
    free(validIntegers);
    freeRecordList(recordManager);

    return EXIT_SUCCESS;
}
