#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_CAPACITY 10

typedef struct {
    char *name;
    double value;
} record_t;

typedef struct {
    record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    atomic_size_t name_count;
    // Cache for API results
    record_t *api_cache;
    size_t cache_capacity;
    size_t cache_count;
    pthread_rwlock_t cache_lock; // Read-write lock for cache access
} record_list_t;

record_list_t* create_record_list() {
    record_list_t *list = malloc(sizeof(record_list_t));
    if (!list) return NULL;

    list->records = calloc(INITIAL_CAPACITY, sizeof(record_t));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->name_count, 0);

    // Cache initialization
    list->api_cache = NULL; 
    list->cache_capacity = 0;
    list->cache_count = 0;
    pthread_rwlock_init(&list->cache_lock, NULL);

    return list;
}

void free_record_list(record_list_t *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; i++) {
        free(list->records[i].name);
    }
    free(list->records);

    // Free cache
    pthread_rwlock_wrlock(&list->cache_lock);
    for (size_t i = 0; i < list->cache_count; i++) {
        free(list->api_cache[i].name);
    }
    free(list->api_cache);
    pthread_rwlock_unlock(&list->cache_lock);

    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->cache_lock);
    free(list);
}

static int find_record_index(record_list_t *list, const char *name) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->records[i].name, name) == 0) {
            return (int)i;
        }
    }
    return -1;
}

static void resize_records(record_list_t *list) {
    size_t new_capacity = list->capacity * 2;
    record_t *new_records = realloc(list->records, new_capacity * sizeof(record_t));

    if (!new_records) {
        fprintf(stderr, "Failed to reallocate memory\n");
        exit(EXIT_FAILURE);
    }

    list->records = new_records;
    list->capacity = new_capacity;
}

int add_record(record_list_t *list, const char *name, double value) {
    pthread_mutex_lock(&list->lock);

    if (find_record_index(list, name) != -1) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Name already exists
    }

    if (list->count == list->capacity) {
        resize_records(list);
    }

    record_t *new_rec = &list->records[list->count++];
    new_rec->name = strdup(name); 
    new_rec->value = value;

    atomic_fetch_add(&list->name_count, 1);

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void* get_records_from_api(void* data) {
    // Dummy API call simulation
    record_list_t *list = (record_list_t*)data;

    // Simulate network delay
    sleep(2); 

    pthread_rwlock_wrlock(&list->cache_lock);

    if (list->api_cache == NULL || list->cache_capacity < 5) {
        size_t new_capacity = list->cache_capacity ? list->cache_capacity * 2 : INITIAL_CAPACITY;

        record_t *new_api_cache = realloc(list->api_cache, new_capacity * sizeof(record_t));
        if (!new_api_cache && list->api_cache != NULL) {
            pthread_rwlock_unlock(&list->cache_lock);
            return NULL; // Allocation failed
        }

        list->api_cache = new_api_cache;
        list->cache_capacity = new_capacity;
    }

    for (size_t i = 0; i < list->cache_count && i < 5; ++i) {
        snprintf(list->api_cache[list->cache_count + i].name, sizeof(char) * 50, "API_Name_%zu", list->cache_count + i);
        list->api_cache[list->cache_count + i].value = (double)(list->cache_count + i) * 1.5;
    }

    list->cache_count += 5;

    pthread_rwlock_unlock(&list->cache_lock);
    return NULL; // No error
}

int integrate_with_api(record_list_t *list) {
    pthread_t api_thread;
    if (pthread_create(&api_thread, NULL, get_records_from_api, list)) {
        perror("Failed to create API thread");
        return 0;
    }

    if (pthread_join(api_thread, NULL)) {
        perror("Failed to join API thread");
        return 0;
    }

    pthread_rwlock_rdlock(&list->cache_lock);
    for (size_t i = 0; i < list->cache_count; ++i) {
        add_record(list, list->api_cache[i].name, list->api_cache[i].value);
    }
    pthread_rwlock_unlock(&list->cache_lock);

    return 1;
}

record_t* search_by_name(record_list_t *list, const char *name) {
    int index = find_record_index(list, name);

    if (index != -1) {
        return &list->records[index];
    }
    return NULL;
}

// Additional functions for value range queries and performance logging can be added as needed.
