#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char identifier[10];
} Item;

typedef int (*Comparator)(const void*, const void*);

typedef struct {
    Item* items;
    size_t capacity;
    size_t size;
    Comparator custom_sorter;
    int is_sorted_original;
} ItemArray;

ItemArray* create_item_array() {
    ItemArray* array = (ItemArray*)malloc(sizeof(ItemArray));
    if (!array) return NULL;

    array->capacity = 10;
    array->size = 0;
    array->items = (Item*)calloc(array->capacity, sizeof(Item));
    if (!array->items) {
        free(array);
        return NULL;
    }

    array->custom_sorter = NULL;
    array->is_sorted_original = 0;
    return array;
}

void destroy_item_array(ItemArray* array) {
    if (array) {
        free(array->items);
        free(array);
    }
}

int resize_array(ItemArray* array, size_t new_capacity) {
    Item* new_items = (Item*)realloc(array->items, new_capacity * sizeof(Item));
    if (!new_items) return -1;

    array->items = new_items;
    array->capacity = new_capacity;
    return 0;
}

int add_item(ItemArray* array, double value, const char* identifier) {
    if (array->size >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 10 : array->capacity * 2;
        if (new_capacity > 10000) new_capacity = 10000;

        int result = resize_array(array, new_capacity);
        if (result != 0) return -1;
    }

    Item* item = &array->items[array->size++];
    item->value = value;
    strncpy(item->identifier, identifier, sizeof(item->identifier) - 1);
    item->identifier[sizeof(item->identifier) - 1] = '\0';
    array->is_sorted_original = 0;

    return 0;
}

int sort_items(ItemArray* array) {
    if (!array || !array->items) return -1;

    int (*sorter)(const void*, const void*) = array->custom_sorter ? array->custom_sorter : (int (*)(const void*, const void*))qsort;

    qsort(array->items, array->size, sizeof(Item), sorter);
    array->is_sorted_original = 1;

    return 0;
}

int reset_to_unsorted(ItemArray* array) {
    if (!array || !array->items) return -1;

    size_t original_size = array->size;
    for (size_t i = 1; i < original_size; ++i) {
        Item temp = array->items[i];
        int j;
        for (j = i; j > 0 && ((array->custom_sorter ? array->custom_sorter(&temp, &array->items[j - 1]) : (int (*)(const void*, const void*))qsort(&temp, sizeof(Item), sizeof(Item), array->custom_sorter)) < 0); --j) {
            array->items[j] = array->items[j - 1];
        }
        array->items[j] = temp;
    }

    array->is_sorted_original = 0;
    return 0;
}

int custom_compare(const void* a, const void* b) {
    Item* itemA = (Item*)a;
    Item* itemB = (Item*)b;

    if (itemA->value < itemB->value) return -1;
    if (itemA->value > itemB->value) return 1;
    return strcmp(itemA->identifier, itemB->identifier);
}

int main() {
    ItemArray* array = create_item_array();
    if (!array) {
        printf("Failed to create item array.\n");
        return -1;
    }

    add_item(array, 3.14, "PI");
    add_item(array, 2.71, "E");
    add_item(array, 1.41, "Sqrt2");

    sort_items(array);

    for (size_t i = 0; i < array->size; ++i) {
        printf("%s: %.2f\n", array->items[i].identifier, array->items[i].value);
    }

    reset_to_unsorted(array);

    for (size_t i = 0; i < array->size; ++i) {
        printf("Reset %s: %.2f\n", array->items[i].identifier, array->items[i].value);
    }

    destroy_item_array(array);
    return 0;
}
