int retry_with_backoff(void (*operation)(void), int retries, int base_delay) {
    for (int i = 0; i < retries; ++i) {
        operation();
        if (/* success condition */ true) { // Replace with actual success check
            return 1;
        }
        usleep(base_delay * (1 << i)); // Exponential backoff
    }
    return 0;
}

void initialize_default_values(Record *record) {
