['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    int offset;
    int key;
} Record;

#define CACHE_SIZE 10

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    Record cache[CACHE_SIZE];
    int cache_hits;
} RecordManager;

// Initialize the record manager
void initializeRecordManager(RecordManager* rm, size_t initialCapacity) {
    rm->records = (Record*)malloc(initialCapacity * sizeof(Record));
    if (!rm->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    rm->count = 0;
    rm->capacity = initialCapacity;
    memset(rm->cache, 0, sizeof(rm->cache));
    rm->cache_hits = 0;
}

// Resize the records array
void resizeRecords(RecordManager* rm) {
    size_t new_capacity = rm->capacity * 2;
    Record* new_records = (Record*)realloc(rm->records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(rm->records);
        exit(EXIT_FAILURE);
    }
    rm->records = new_records;
    rm->capacity = new_capacity;
}

// Insert a record
void insertRecord(RecordManager* rm, double value, int offset, int key) {
    if (rm->count == rm->capacity) {
        resizeRecords(rm);
    }
    rm->records[rm->count++] = (Record){value, offset, key};
}

// Bulk insert records
void bulkInsertRecords(RecordManager* rm, Record* new_records, size_t count) {
    while (rm->count + count > rm->capacity) {
        resizeRecords(rm);
    }
    memcpy(&rm->records[rm->count], new_records, count * sizeof(Record));
    rm->count += count;
}

// Initialize records with random values
void initializeRandomRecords(RecordManager* rm, size_t count, double min_value, double max_value) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        insertRecord(rm, ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value, rand(), rand());
    }
}

// Read integers from stdin and calculate average
double readIntegersAndCalculateAverage(int* arr, size_t max_count) {
    size_t count = 0;
    int value;
    while (count < max_count && scanf("%d", &value) == 1) {
        arr[count++] = value;
    }
    double sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += arr[i];
    }
    return count > 0 ? sum / count : 0.0;
}

// Find top five unique integers in descending order
void findTopFiveUniqueIntegers(int* arr, size_t count, int* result) {
    // Use a simple hash map to track unique values (for demonstration)
    int presence[1001] = {0}; // Assuming values are between 0 and 1000
    for (size_t i = 0; i < count; ++i) {
        if (!presence[arr[i]]) {
            presence[arr[i]] = 1;
            result[result[0]++] = arr[i];
        }
    }

    // Sort the unique values in descending order
    qsort(result, result[0], sizeof(int), (int (*)(const void*, const void*))strcmp);
}

// Retrieve a specific record by index with caching
Record getRecord(RecordManager* rm, size_t index) {
    if (index >= rm->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (rm->cache[i].key == index) {
            rm->cache_hits++;
            return rm->cache[i];
        }
    }

    // Update cache with the requested record
    for (int i = 0; i < CACHE_SIZE - 1; ++i) {
        rm->cache[i] = rm->cache[i + 1];
    }
    rm->cache[CACHE_SIZE - 1] = rm->records[index];

    return rm->records[index];
}

// Update a record's value
void updateRecord(RecordManager* rm, size_t index, double newValue) {
    if (index >= rm->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    rm->records[index].value = newValue;
}

// Search for records within a specified numeric range
void searchRecordsInRange(RecordManager* rm, double min_value, double max_value, Record** results, size_t* result_count) {
    *result_count = 0;
    for (size_t i = 0; i < rm->count; ++i) {
        if (rm->records[i].value >= min_value && rm->records[i].value <= max_value) {
            (*results)[(*result_count)++] = &rm->records[i];
        }
    }
}

// Clean up resources
void cleanupRecordManager(RecordManager* rm) {
    free(rm->records);
    rm->records = NULL;
    rm->count = 0;
    rm->capacity = 0;
}

int main() {
    RecordManager rm;
    initializeRecordManager(&rm, 10);

    // Example usage
    initializeRandomRecords(&rm, 20, 1.0, 100.0);

    int integers[100];
    double average = readIntegersAndCalculateAverage(integers, 100);
    printf("Average: %.2f\n", average);

    int top_five[6] = {0}; // Extra space for count
    findTopFiveUniqueIntegers(integers, 5, top_five);
    printf("Top five unique integers:\n");
    for (int i = 0; i < top_five[0]; ++i) {
        printf("%d\n", top_five[i]);
    }

    Record* search_results;
    size_t search_count;
    searchRecordsInRange(&rm, 10.0, 50.0, &search_results, &search_count);
    printf("Records in range [10.0, 50.0]:\n");
    for (size_t i = 0; i < search_count; ++i) {
        printf("Value: %.2f\n", search_results[i]->value);
    }

    cleanupRecordManager(&rm);
    return 0;
}
