['Below is a C implementation of the described function. This code integrates various components such as mutex locks, custom memory pool management, logging, and statistics tracking.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Assuming external logging library headers are included here.
#include "logging_library.h"

// Define a structure for the state list node
typedef struct StateNode {
    int state_id;
    struct StateNode* next;
} StateNode;

// Memory pool management structures and functions
#define POOL_SIZE 1024

static void* memory_pool[POOL_SIZE];
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t pool_free_index = 0;

void initialize_memory_pool() {
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(StateNode));
        if (!memory_pool[i]) exit(1); // Handle allocation failure
    }
}

void* allocate_from_pool() {
    pthread_mutex_lock(&pool_lock);
    void* ptr = pool_free_index < POOL_SIZE ? memory_pool[pool_free_index++] : NULL;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void deallocate_to_pool(void* ptr) {
    pthread_mutex_lock(&pool_lock);
    if (pool_free_index > 0) {
        pool_free_index--;
        memory_pool[pool_free_index] = ptr;
    }
    pthread_mutex_unlock(&pool_lock);
}

// Main function to manage the state list
StateNode* manage_state_list(int* states, int num_states, const void* fsa, int last_state_id) {
    if (!states || !fsa) return NULL;

    StateNode* head = (StateNode*)allocate_from_pool();
    if (!head) {
        log_error("Memory allocation failed for state list.");
        return NULL;
    }

    head->state_id = last_state_id;
    head->next = NULL;

    StateNode* current = head;

    for (int i = 0; i < num_states; ++i) {
        if (!states[i]) continue;

        StateNode* new_node = (StateNode*)allocate_from_pool();
        if (!new_node) {
            log_error("Memory allocation failed for a state node.");

            // Cleanup on failure
            while (current != NULL) {
                StateNode* to_free = current;
                current = current->next;
                deallocate_to_pool(to_free);
            }
            return NULL;
        }

        new_node->state_id = states[i];
        new_node->next = NULL;

        pthread_mutex_lock(&current->next); // Ensure thread safety
        current->next = new_node;
        pthread_mutex_unlock(&current->next);

        current = new_node;
    }

    log_info("State list successfully created and managed.");

    // Assume there is a mechanism to update 'last_state' next pointer externally if needed

    return head;
}

// Placeholder function for graceful shutdown
void graceful_shutdown() {
    // Implement state saving logic here.
}

int main() {
    initialize_memory_pool();

    int states[] = {1, 2, 3, 4};
    StateNode* state_list = manage_state_list(states, 4, NULL, -1);

    if (state_list) {
        // Use the state list...
    }

    graceful_shutdown();

    return 0;
}
```

### Key Points:

- **Memory Pool**: A simple memory pool is implemented for `StateNode` allocation to reduce fragmentation and improve performance under heavy load. This example uses a fixed-size array of preallocated nodes.

- **Thread Safety**: Mutex locks are used around critical sections where state nodes are linked together to ensure thread safety. Further optimizations could include more sophisticated lock-free data structures.

- **Logging**: Integration with an external logging library is assumed, and error conditions such as memory allocation failures are logged. The logging system should be designed to handle intermittent connectivity gracefully.

- **Graceful Shutdown**: A placeholder function for a graceful shutdown process ensures that state lists can be saved safely before application termination.

This implementation provides a basic framework to build upon, considering the constraints and requirements specified in your task description.']

