// Mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDataEntries(dataEntry **entries, size_t numEntries, double minTime, double maxTime) {
    *entries = (dataEntry *)malloc(numEntries * sizeof(dataEntry));
    if (*entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < numEntries; ++i) {
        (*entries)[i].timestamp = minTime + ((maxTime - minTime) * rand() / RAND_MAX);
        int length = rand() % MAX_STRING_LENGTH;
        for (int j = 0; j < length; ++j) {
            (*entries)[i].buffer[j] = 'a' + (rand() % 26); // Random lowercase letter
        }
        (*entries)[i].buffer[length] = '\0';
        (*entries)[i].status = 1;
    }
}

void updateDataEntry(dataEntry *entry, double newTimestamp, const char *newBuffer) {
    pthread_mutex_lock(&mutex);
    entry->timestamp = newTimestamp;

    int bufferLength = strlen(newBuffer);
    if (bufferLength < MAX_STRING_LENGTH) {
        strncpy(entry->buffer, newBuffer, bufferLength);
        entry->buffer[bufferLength] = '\0';
    } else {
        strncpy(entry->buffer, newBuffer, MAX_STRING_LENGTH - 1);
        entry->buffer[MAX_STRING_LENGTH - 1] = '\0';
    }
    pthread_mutex_unlock(&mutex);
}

