#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <stdexcept>

// Error codes
enum ErrorCode {
    SUCCESS = 0,
    INVALID_INPUT = -1,
    MEMORY_ALLOCATION_FAILED = -2,
    UPDATE_FAILED = -3
};

// Cell structure
struct Cell {
    std::vector<int> data; // Example data type, can be customized
};

// SpatialHashGrid class definition
class SpatialHashGrid {
public:
    SpatialHashGrid(float featureSize, int gridResolutionX, int gridResolutionY, int maxCapacity)
        : featureSize_(featureSize), gridResolutionX_(gridResolutionX), 
          gridResolutionY_(gridResolutionY), maxCapacity_(maxCapacity) {

        if (featureSize_ <= 0 || gridResolutionX_ <= 0 || gridResolutionY_ <= 0 || maxCapacity_ <= 0) {
            throw std::invalid_argument("Invalid input values");
        }

        // Calculate number of cells
        int numCells = gridResolutionX_ * gridResolutionY_;

        if (numCells > maxCapacity_) {
            throw std::runtime_error("Grid capacity is too small for the resolution.");
        }

        // Allocate memory using bulk allocation strategy
        cellData_.resize(numCells);
    }

    ErrorCode updateFromExternalSource(const std::vector<Cell>& newData) {
        std::unique_lock<std::mutex> lock(mutex_);

        if (newData.size() > maxCapacity_) {
            return UPDATE_FAILED;
        }

        // Update grid data safely
        for (size_t i = 0; i < newData.size(); ++i) {
            cellData_[i] = newData[i];
        }

        return SUCCESS;
    }

    Cell getCell(int x, int y) const {
        if (x < 0 || x >= gridResolutionX_ || y < 0 || y >= gridResolutionY_) {
            throw std::out_of_range("Grid coordinates out of bounds");
        }

        return cellData_[y * gridResolutionX_ + x];
    }

    void insertCell(int x, int y, const Cell& cell) {
        if (x < 0 || x >= gridResolutionX_ || y < 0 || y >= gridResolutionY_) {
            throw std::out_of_range("Grid coordinates out of bounds");
        }

        std::unique_lock<std::mutex> lock(mutex_);
        cellData_[y * gridResolutionX_ + x] = cell;
    }

    void resizeGrid(int newResolutionX, int newResolutionY) {
        if (newResolutionX <= 0 || newResolutionY <= 0) {
            throw std::invalid_argument("Invalid resolution values");
        }

        // Ensure no data loss during resizing
        std::unique_lock<std::mutex> lock(mutex_);

        int oldNumCells = gridResolutionX_ * gridResolutionY_;
        int newNumCells = newResolutionX * newResolutionY;

        if (newNumCells > maxCapacity_) {
            throw std::runtime_error("New grid capacity exceeds maximum allowed.");
        }

        // Allocate new cell data
        std::vector<Cell> newData(newNumCells);

        for (int y = 0; y < std::min(gridResolutionY_, newResolutionY); ++y) {
            for (int x = 0; x < std::min(gridResolutionX_, newResolutionX); ++x) {
                newData[y * newResolutionX + x] = cellData_[y * gridResolutionX_ + x];
            }
        }

        // Update class members
        cellData_.swap(newData);
        gridResolutionX_ = newResolutionX;
        gridResolutionY_ = newResolutionY;
    }

private:
    float featureSize_;
    int gridResolutionX_, gridResolutionY_, maxCapacity_;
    mutable std::mutex mutex_; // Protects access to cell data
    std::vector<Cell> cellData_;
};

// Example usage of the SpatialHashGrid class
int main() {
    try {
        SpatialHashGrid grid(1.0f, 10, 10, 100);

        Cell newCell;
        newCell.data.push_back(42);

        grid.insertCell(5, 5, newCell);

        Cell retrievedCell = grid.getCell(5, 5);

        std::vector<Cell> newData(grid.getMaxCapacity());
        for (auto& cell : newData) {
            cell.data.push_back(100); // Example data update
        }

        ErrorCode result = grid.updateFromExternalSource(newData);
        if (result != SUCCESS) {
            std::cerr << "Update failed with error code: " << result << '\n';
        }

        grid.resizeGrid(20, 20);

    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << '\n';
    }

    return 0;
