['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define MAX_LOAD_FACTOR 0.75

typedef struct {
    int key;
    long value;
} record_t;

typedef struct {
    atomic_int ref_count; // Reference count for memory management
    pthread_mutex_t lock; // Mutex for thread safety
    size_t capacity;
    size_t size;
    record_t *records;
} hashtable_t;

// Hash function
static unsigned int hash(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

// Function to create a new hash table
hashtable_t* create_hashtable() {
    hashtable_t *table = malloc(sizeof(hashtable_t));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    atomic_init(&table->ref_count, 1);
    pthread_mutex_init(&table->lock, NULL);

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;

    table->records = calloc(table->capacity, sizeof(record_t));
    if (!table->records) {
        perror("Failed to allocate memory for records");
        free(table);
        exit(EXIT_FAILURE);
    }

    return table;
}

// Function to resize the hash table
static void resize(hashtable_t *table);

// Function to insert a key-value pair into the hash table
void hashtable_insert(hashtable_t *table, int key, long value) {
    pthread_mutex_lock(&table->lock);

    if (table->size >= MAX_LOAD_FACTOR * table->capacity) {
        resize(table);
    }

    unsigned int index = hash(key, table->capacity);
    while (table->records[index].key != 0) { // Find an empty slot or the existing key
        if (table->records[index].key == key) { // Update existing value
            table->records[index].value = value;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        index = (index + 1) % table->capacity; // Linear probing
    }

    table->records[index] = (record_t){key, value};
    table->size++;

    pthread_mutex_unlock(&table->lock);
}

// Function to find a value by key in the hash table
long hashtable_find(hashtable_t *table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned int index = hash(key, table->capacity);
    while (table->records[index].key != 0) { // Search for the key
        if (table->records[index].key == key) {
            long value = table->records[index].value;
            pthread_mutex_unlock(&table->lock);
            return value;
        }
        index = (index + 1) % table->capacity; // Linear probing
    }

    pthread_mutex_unlock(&table->lock);
    fprintf(stderr, "Key not found\n");
    exit(EXIT_FAILURE); // For simplicity, terminate on failure
}

// Function to resize the hash table
static void resize(hashtable_t *table) {
    size_t new_capacity = 2 * table->capacity;
    record_t *new_records = calloc(new_capacity, sizeof(record_t));
    if (!new_records) {
        perror("Failed to allocate memory for resizing");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&table->lock);

    // Rehash all records
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i].key != 0) {
            unsigned int index = hash(table->records[i].key, new_capacity);
            while (new_records[index].key != 0) {
                index = (index + 1) % new_capacity;
            }
            new_records[index] = table->records[i];
        }
    }

    free(table->records);
    table->records = new_records;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->lock);
}

// Function to initialize records with random values
void initialize_random(hashtable_t *table, int min_val, int max_val) {
    srand(time(NULL));
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i].key != 0) {
            int random_value = rand() % (max_val - min_val + 1) + min_val;
            table->records[i].value = (long)random_value;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Function to destroy the hash table
void destroy_hashtable(hashtable_t *table) {
    if (!atomic_fetch_sub(&table->ref_count, 1)) {
        free(table->records);
        pthread_mutex_destroy(&table->lock);
        free(table);
    }
}
```

This code implements a dynamically growing hash table with thread safety and memory management. It uses linear probing for collision resolution and locks to ensure safe concurrent access. The resizing strategy is designed to minimize rehashing frequency, and the random initialization function provides uniform distribution of values within a specified range.']

