#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct record {
    int value;
} record;

typedef struct metadata_node {
    long *offset;
    int *key;
    record *record_ptr;
    struct metadata_node *next;
} metadata_node;

typedef struct dataset {
    long *offsets;
    int *keys;
    record **records;
    metadata_node *head;
    size_t capacity;
    size_t count;
} dataset;

void initialize_dataset(dataset *ds, size_t initial_capacity) {
    ds->capacity = initial_capacity;
    ds->count = 0;

    ds->offsets = (long *)malloc(sizeof(long) * ds->capacity);
    ds->keys = (int *)malloc(sizeof(int) * ds->capacity);
    ds->records = (record **)malloc(sizeof(record*) * ds->capacity);

    for(size_t i = 0; i < ds->capacity; ++i) {
        ds->offsets[i] = -1;
    }

    ds->head = NULL;
}

void free_dataset(dataset *ds) {
    while(ds->head != NULL) {
        metadata_node *temp = ds->head;
        ds->head = ds->head->next;
        free(temp);
    }

    free(ds->offsets);
    free(ds->keys);
    for(size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }
    free(ds->records);
}

int add_record(dataset *ds, int key, int value_range) {
    if (ds->count >= ds->capacity) return -1;

    record *rec = (record *)malloc(sizeof(record));
    rec->value = rand() % value_range;

    size_t index = ds->count;
    ds->offsets[index] = index; // Use simple offset logic for demo
    ds->keys[index] = key;
    ds->records[index] = rec;

    metadata_node *new_node = (metadata_node *)malloc(sizeof(metadata_node));
    new_node->offset = &ds->offsets[index];
    new_node->key = &ds->keys[index];
    new_node->record_ptr = rec;
    new_node->next = ds->head;
    ds->head = new_node;

    ds->count++;
    return 0;
}

int remove_record(dataset *ds, int key) {
    metadata_node **curr = &(ds->head);

    while (*curr != NULL) {
        if ((*curr)->key == &key) {
            metadata_node *temp = *curr;
            *curr = (*curr)->next;

            size_t index = *((*temp).offset);
            free((*temp).record_ptr);
            ds->count--;

            // Shift elements to fill gap
            for (size_t i = index; i < ds->count; ++i) {
                ds->offsets[i] = ds->offsets[i + 1];
                ds->keys[i] = ds->keys[i + 1];
                ds->records[i] = ds->records[i + 1];
            }

            free(temp);
            return 0;
        }
        curr = &((*curr)->next);
    }
    return -1;
}

void resize_dataset_if_needed(dataset *ds) {
    if (ds->count >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;

        long *new_offsets = (long *)realloc(ds->offsets, sizeof(long) * new_capacity);
        int *new_keys = (int *)realloc(ds->keys, sizeof(int) * new_capacity);
        record **new_records = (record **)realloc(ds->records, sizeof(record*) * new_capacity);

        if (!new_offsets || !new_keys || !new_records) {
            // Handle reallocation failure
            return;
        }

        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->records = new_records;

        for(size_t i = ds->capacity; i < new_capacity; ++i) {
            ds->offsets[i] = -1;
        }

        ds->capacity = new_capacity;
    }
}

void print_memory_usage(dataset *ds) {
    printf("Dataset contains %zu records.\n", ds->count);
    printf("Capacity is %zu.\n", ds->capacity);
}
