#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for concurrent access
} RecordCollection;

void init_random() {
    time_t t;
    srand((unsigned)time(&t));
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record *create_record(int value, long offset, int key) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = value;
    record->offset = malloc(sizeof(long));
    record->key = malloc(sizeof(int));

    if (!record->offset || !record->key) {
        free(record);
        return NULL;
    }

    *record->offset = offset;
    *record->key = key;
    return record;
}

RecordCollection *init_record_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_rwlock_init(&collection->rwlock, NULL);

    return collection;
}

int add_record(RecordCollection *collection, int min_value, int max_value, long offset, int key) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_rwlock_unlock(&collection->rwlock);
            return -1; // Allocation failure
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    int value = generate_random_int(min_value, max_value);
    Record *record = create_record(value, offset, key);

    if (!record) {
        pthread_rwlock_unlock(&collection->rwlock);
        return -1; // Allocation failure
    }

    collection->records[collection->count++] = record;
    pthread_rwlock_unlock(&collection->rwlock);
    return 0; // Success
}

Record *get_record(RecordCollection *collection, size_t index) {
    if (index >= collection->count) return NULL;

    pthread_rwlock_rdlock(&collection->rwlock);
    Record *record = collection->records[index];
    pthread_rwlock_unlock(&collection->rwlock);

    return record;
}

void free_record_collection(RecordCollection *collection) {
    pthread_rwlock_wrlock(&collection->rwlock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
    }

    free(collection->records);
    pthread_rwlock_unlock(&collection->rwlock);

    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

int main() {
    init_random();

    RecordCollection *collection = init_record_collection(10);
    if (!collection) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 20; ++i) {
        if (add_record(collection, 1, 100, (long)i * 10, i) != 0) {
            fprintf(stderr, "Failed to add record at index %zu\n", i);
            free_record_collection(collection);
            return EXIT_FAILURE;
        }
    }

    Record *record = get_record(collection, 5);
    if (record) {
        printf("Record at index 5: value=%d, offset=%ld, key=%d\n",
               record->value, *(record->offset), *(record->key));
    } else {
        fprintf(stderr, "Failed to retrieve record at index 5\n");
    }

    free_record_collection(collection);
    return EXIT_SUCCESS;
}
