#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 4

struct record {
    int value;
};

typedef struct {
    long* seq_integers;
    int* keys;
    struct record* records;
    pthread_mutex_t mutex;
} Records;

// Helper function to free allocated resources
void free_records(Records* rec) {
    if (rec->seq_integers) free(rec->seq_integers);
    if (rec->keys) free(rec->keys);
    if (rec->records) free(rec->records);
}

int initialize_records(int n, int min_val, int max_val, Records* rec) {
    if (n <= 0) return -1; // Invalid input

    pthread_mutex_init(&rec->mutex, NULL);

    size_t total_size = n * sizeof(long) + n * sizeof(int) + n * sizeof(struct record);

    void* buffer = malloc(total_size);
    if (!buffer) {
        perror("Failed to allocate memory");
        return -1;
    }

    rec->seq_integers = (long*)buffer;
    rec->keys = (int*)((char*)rec->seq_integers + n * sizeof(long));
    rec->records = (struct record*)((char*)rec->keys + n * sizeof(int));

    for (int i = 0; i < n; ++i) {
        rec->seq_integers[i] = i;
        rec->keys[i] = i;

        // Use local variable to minimize global state
        int random_value = min_val + rand() % (max_val - min_val + 1);
        pthread_mutex_lock(&rec->mutex); // Ensure thread safety for shared data
        rec->records[i].value = random_value;
        pthread_mutex_unlock(&rec->mutex);
    }

    return 0; // Success
}

// Simulate concurrent access using threads
void* modify_records(void* arg) {
    Records* rec = (Records*)arg;
    int n = 10; // Example modification size

    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&rec->mutex);
        rec->records[i].value += rand() % 5; // Randomly modify values
        pthread_mutex_unlock(&rec->mutex);
    }

    return NULL;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    Records rec = {0};
    int n = 1000, min_val = 1, max_val = 100;

    if (initialize_records(n, min_val, max_val, &rec) != 0) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, modify_records, &rec) != 0) {
            perror("Failed to create thread");
            free_records(&rec);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated resources
    free_records(&rec);

    return EXIT_SUCCESS;
}
