['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
    time_t timestamp;
    int error_code;
} Record;

// Define the hash table entry
typedef struct HashNode {
    int key;
    Record data;
    struct HashNode *next;
} HashNode;

// Configuration for the hash table
typedef struct {
    size_t max_size;
    float load_factor;
    time_t cleanup_interval;
    pthread_mutex_t *cleanup_lock; // Lock for thread-safe cleanup operations
} HashTableConfig;

// Define the hash table structure
typedef struct {
    HashNode **buckets;
    size_t num_buckets;
    size_t current_size;
    HashTableConfig config;
    pthread_rwlock_t rwlock;  // Read-write lock for concurrent access
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t max_size, float load_factor, time_t cleanup_interval);
void destroy_hash_table(HashTable *table);
int hash_function(int key, size_t num_buckets);
void insert_record(HashTable *table, Record record);
Record* find_record(HashTable *table, int key);
void delete_record(HashTable *table, int key);
void resize_hash_table(HashTable *table);

// Create a new hash table
HashTable* create_hash_table(size_t max_size, float load_factor, time_t cleanup_interval) {
    HashTable *table = (HashTable*) malloc(sizeof(HashTable));
    if (!table) return NULL;

    size_t initial_buckets = 16;
    table->buckets = (HashNode**) calloc(initial_buckets, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->num_buckets = initial_buckets;
    table->current_size = 0;
    table->config.max_size = max_size;
    table->config.load_factor = load_factor;
    table->config.cleanup_interval = cleanup_interval;

    pthread_rwlock_init(&table->rwlock, NULL);
    pthread_mutex_t cleanup_lock = PTHREAD_MUTEX_INITIALIZER;
    table->config.cleanup_lock = &cleanup_lock;

    return table;
}

// Destroy the hash table
void destroy_hash_table(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->num_buckets; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_rwlock_destroy(&table->rwlock);
    pthread_mutex_destroy(table->config.cleanup_lock);

    free(table);
}

// Basic hash function
int hash_function(int key, size_t num_buckets) {
    return key % num_buckets;
}

// Insert a new record into the hash table
void insert_record(HashTable *table, Record record) {
    if (!table) return;

    pthread_rwlock_wrlock(&table->rwlock);

    if (table->current_size >= table->config.max_size) {
        resize_hash_table(table);
    }

    int index = hash_function(record.key, table->num_buckets);
    HashNode *new_node = (HashNode*) malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_rwlock_unlock(&table->rwlock);
        return;
    }

    new_node->key = record.key;
    new_node->data = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    ++table->current_size;

    if ((float) table->current_size / table->num_buckets > table->config.load_factor) {
        resize_hash_table(table);
    }

    pthread_rwlock_unlock(&table->rwlock);
}

// Find a record by key
Record* find_record(HashTable *table, int key) {
    if (!table) return NULL;

    pthread_rwlock_rdlock(&table->rwlock);

    int index = hash_function(key, table->num_buckets);
    HashNode *node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_rwlock_unlock(&table->rwlock);
            return &node->data;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&table->rwlock);
    return NULL;
}

// Delete a record by key
void delete_record(HashTable *table, int key) {
    if (!table) return;

    pthread_rwlock_wrlock(&table->rwlock);

    int index = hash_function(key, table->num_buckets);
    HashNode *node = table->buckets[index];
    HashNode *prev_node = NULL;

    while (node) {
        if (node->key == key) {
            if (prev_node) {
                prev_node->next = node->next;
            } else {
                table->buckets[index] = node->next;
            }
            free(node);
            --table->current_size;
            break;
        }
        prev_node = node;
        node = node->next;
    }

    pthread_rwlock_unlock(&table->rwlock);
}

// Resize the hash table
void resize_hash_table(HashTable *table) {
    size_t new_num_buckets = table->num_buckets * 2;
    HashNode **new_buckets = (HashNode**) calloc(new_num_buckets, sizeof(HashNode*));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->num_buckets; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            int new_index = hash_function(node->key, new_num_buckets);
            HashNode *next_node = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->num_buckets = new_num_buckets;
}

// Periodic cleanup function
void* periodic_cleanup(void *arg) {
    HashTable *table = (HashTable*) arg;

    while (1) {
        time_t current_time = time(NULL);

        pthread_mutex_lock(table->config.cleanup_lock);

        for (size_t i = 0; i < table->num_buckets; ++i) {
            HashNode **node = &(table->buckets[i]);
            while (*node) {
                if (difftime(current_time, (*node)->data.timestamp) > table->config.cleanup_interval) {
                    HashNode *to_delete = *node;
                    *node = to_delete->next;
                    free(to_delete);
                    --table->current_size;
                } else {
                    node = &((*node)->next);
                }
            }
        }

        pthread_mutex_unlock(table->config.cleanup_lock);

        sleep(table->config.cleanup_interval);
    }
}

int main() {
    // Example usage
    HashTable *table = create_hash_table(100, 0.75f, 60); // Max size: 100, Load factor: 0.75, Cleanup interval: 60 seconds

    if (!table) {
        fprintf(stderr, "Failed to create hash table.\n");
        return EXIT_FAILURE;
    }

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, (void*) table);

    Record record = { .offset = 123456789L, .key = 1, .timestamp = time(NULL), .error_code = 0 };
    insert_record(table, record);

    Record *found = find_record(table, 1);
    if (found) {
        printf("Found record with key: %d\n", found->key);
    }

    delete_record(table, 1);

    pthread_join(cleanup_thread, NULL);
    destroy_hash_table(table);

    return EXIT_SUCCESS;
}
```']

