```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_random(int range_min, int range_max) {
    if (!srandom(time(NULL))) {
        fprintf(stderr, "Failed to seed random number generator\n");
        exit(EXIT_FAILURE);
    }
}

int generate_random(int range_min, int range_max) {
    return rand() % (range_max - range_min + 1) + range_min;
}

void populate_records(record *records, size_t num_records, int range_min, int range_max) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random(range_min, range_max);
    }
}

void log_distribution(int value, FILE *log_file) {
    fprintf(log_file, "Value: %d\n", value);
}

long* allocate_long_array(size_t size) {
    long *array = (long *)malloc(size * sizeof(long));
    if (!array) {
        perror("Failed to allocate memory for long array");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* allocate_int_array(size_t size) {
    int *array = (int *)malloc(size * sizeof(int));
    if (!array) {
        perror("Failed to allocate memory for int array");
        exit(EXIT_FAILURE);
    }
    return array;
}

record* allocate_record_array(size_t size) {
    record *array = (record *)malloc(size * sizeof(record));
    if (!array) {
        perror("Failed to allocate memory for record array");
        exit(EXIT_FAILURE);
    }
    return array;
}

void free_memory(long *long_array, int *int_array, record *record_array) {
    free(long_array);
    free(int_array);
    free(record_array);
}
