<?php
function generate_random_string($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[random_int(0, strlen($charset) - 1)];
    }
    return $randomString;
}

function handle_request() {
    header('Content-Type: application/json');

    $requestedLength = $_GET['length'] ?? 10; // Default length is 10

    if (!is_numeric($requestedLength) || (int)$requestedLength <= 0) {
        echo json_encode(['error' => 'Invalid input parameters']);
        return;
    }

    try {
        $randomString = generate_random_string((int)$requestedLength);
        $hash = hash('sha256', $randomString);

        echo json_encode([
            'string' => $randomString,
            'hash'   => $hash
        ]);
    } catch (Exception $e) {
        http_response_code(500);
        echo json_encode(['error' => $e->getMessage()]);
    }
}

handle_request();
?>
