#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Employee {
    char *name;
    int age;
    float salary;
    struct Employee *next;
} Employee;

// Function to generate a random integer within a range [min, max]
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize the employee list with a specified number of records
Employee* initializeEmployees(size_t count, int ageMin, int ageMax) {
    Employee *head = NULL, **ptr = &head;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        Employee *newEmp = malloc(sizeof(Employee));
        if (!newEmp) {
            perror("Failed to allocate memory for a new employee");
            while (head != NULL) {
                Employee *temp = head;
                head = head->next;
                free(temp->name);
                free(temp);
            }
            return NULL;
        }

        // Allocate and copy name
        char name[50];
        snprintf(name, sizeof(name), "Employee%d", i + 1);  // Placeholder names
        newEmp->name = strdup(name);

        if (!newEmp->name) {
            perror("Failed to duplicate employee name");
            free(newEmp);
            while (head != NULL) {
                Employee *temp = head;
                head = head->next;
                free(temp->name);
                free(temp);
            }
            return NULL;
        }

        // Generate random age and set salary
        newEmp->age = getRandomInt(ageMin, ageMax);
        newEmp->salary = 50000.0f + (float)rand() / RAND_MAX * 100000.0f;  // Random salary between 50k and 150k

        newEmp->next = NULL;
        *ptr = newEmp;
        ptr = &newEmp->next;
    }

    return head;
}

// Function to add a new employee record
Employee* addEmployee(Employee *head, const char *name, int age, float salary) {
    Employee *newEmp = malloc(sizeof(Employee));
    if (!newEmp) {
        perror("Failed to allocate memory for a new employee");
        return head;
    }

    newEmp->name = strdup(name);
    if (!newEmp->name) {
        perror("Failed to duplicate employee name");
        free(newEmp);
        return head;
    }

    newEmp->age = age;
    newEmp->salary = salary;
    newEmp->next = head;

    return newEmp;
}

// Function to retrieve a specific record by its index
Employee* getEmployeeByIndex(Employee *head, size_t index) {
    Employee *current = head;
    size_t i = 0;

    while (current != NULL && i < index) {
        current = current->next;
        ++i;
    }

    return current; // Returns NULL if the index is out of bounds
}

// Function to calculate average salary
float calculateAverageSalary(Employee *head) {
    Employee *current = head;
    float totalSalary = 0.0f;
    size_t count = 0;

    while (current != NULL) {
        totalSalary += current->salary;
        ++count;
        current = current->next;
    }

    return count ? totalSalary / count : 0.0f;
}

// Function to free all employees and associated memory
void freeEmployees(Employee *head) {
    Employee *temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->name);
        free(temp);
    }
}

// Comparator function for sorting by age or salary
int compareByField(const void *a, const void *b, int fieldIndex) {
    Employee *empA = *(Employee **)a;
    Employee *empB = *(Employee **)b;

    if (fieldIndex == 0)
        return empA->age - empB->age; // Sort by age
    else
        return (empA->salary > empB->salary) - (empA->salary < empB->salary); // Sort by salary
}

// Function to sort employees based on a specified field and return the first record in sorted order
Employee* sortEmployees(Employee *head, int sortByAge) {
    size_t count = 0;
    Employee **arr = NULL;

    for (Employee *current = head; current != NULL; ++count, current = current->next);

    arr = malloc(sizeof(Employee *) * count);
    if (!arr) {
        perror("Failed to allocate memory for sorting");
        return NULL;
    }

    size_t i = 0;
    for (Employee *current = head; current != NULL; ++i, current = current->next)
        arr[i] = current;

    qsort_r(arr, count, sizeof(Employee *), compareByField, sortByAge);

    // Re-link the sorted nodes
    for (size_t i = 1; i < count; ++i)
        arr[i - 1]->next = arr[i];

    if (count > 0) {
        arr[count - 1]->next = NULL;
        return arr[0];
    }

    free(arr);
    return NULL;
}

// Main function demonstrating usage
int main() {
    Employee *employees = initializeEmployees(5, 20, 60);

    if (!employees) {
        fprintf(stderr, "Failed to initialize employees\n");
        return EXIT_FAILURE;
    }

    printf("Initial list:\n");
    for (size_t i = 0; i < 5; ++i) {
        Employee *emp = getEmployeeByIndex(employees, i);
        if (emp)
            printf("Name: %s, Age: %d, Salary: %.2f\n", emp->name, emp->age, emp->salary);
    }

    float averageSalary = calculateAverageSalary(employees);
    printf("\nAverage salary: %.2f\n", averageSalary);

    employees = addEmployee(employees, "New Employee", 35, 75000.0f);
    printf("Added new employee:\n");
    for (size_t i = 0; i < 6; ++i) {
        Employee *emp = getEmployeeByIndex(employees, i);
        if (emp)
            printf("Name: %s, Age: %d, Salary: %.2f\n", emp->name, emp->age, emp->salary);
    }

    printf("\nSorted by age:\n");
    employees = sortEmployees(employees, 1); // Sort by age
    for (Employee *emp = employees; emp != NULL; emp = emp->next)
        printf("Name: %s, Age: %d, Salary: %.2f\n", emp->name, emp->age, emp->salary);

    freeEmployees(employees);
    return EXIT_SUCCESS;
}
