['Below is a C code implementation that meets your described requirements. This example includes the use of pthreads for thread safety, dynamic memory management, logging with timestamps, and periodic snapshots for debugging purposes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Logging function
void log_event(const char *event) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), event);
}

// Memory pool structure
typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t offset_size, key_size, record_size;
    pthread_mutex_t lock;
} memory_pool;

// Error handling function
void handle_allocation_error(void *ptr) {
    if (ptr == NULL) {
        log_event("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

// Initialize the memory pool
int init_memory_pool(memory_pool *pool, size_t memory_budget, int n) {
    if (n <= 0 || memory_budget < sizeof(long) + sizeof(int) + sizeof(record)) {
        log_event("Invalid parameters for initialization.");
        return -1;
    }

    pthread_mutex_init(&pool->lock, NULL);

    // Calculate proportional sizes
    size_t unit_size = sizeof(long) + sizeof(int) + sizeof(record);
    size_t total_units = memory_budget / unit_size;

    pool->offset_size = total_units / 3;
    pool->key_size = total_units / 3;
    pool->record_size = total_units - (pool->offset_size + pool->key_size);

    // Allocate and initialize memory
    pthread_mutex_lock(&pool->lock);
    pool->offsets = malloc(pool->offset_size * sizeof(long));
    handle_allocation_error(pool->offsets);

    pool->keys = malloc(pool->key_size * sizeof(int));
    handle_allocation_error(pool->keys);

    pool->records = malloc(pool->record_size * sizeof(record));
    handle_allocation_error(pool->records);

    pthread_mutex_unlock(&pool->lock);

    log_event("Memory pool initialized successfully.");
    return 0;
}

// Deallocate the memory pool
void free_memory_pool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->offsets != NULL) {
        free(pool->offsets);
        pool->offsets = NULL;
    }
    if (pool->keys != NULL) {
        free(pool->keys);
        pool->keys = NULL;
    }
    if (pool->records != NULL) {
        free(pool->records);
        pool->records = NULL;
    }
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    log_event("Memory pool deallocated successfully.");
}

// Periodic snapshot for debugging
void take_snapshot(const memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    printf("Snapshot - Offsets: %zu, Keys: %zu, Records: %zu\n",
           pool->offset_size, pool->key_size, pool->record_size);
    pthread_mutex_unlock(&pool->lock);
}

// Function to optimize memory layout periodically
void optimize_memory_layout(memory_pool *pool) {
    // Placeholder for optimization logic (e.g., compacting data)
    log_event("Memory layout optimized.");
}

int main() {
    size_t memory_budget = 1024; // Example budget in bytes
    int n = 10;
    memory_pool pool;

    if (init_memory_pool(&pool, memory_budget, n) != 0) {
        return EXIT_FAILURE;
    }

    take_snapshot(&pool);

    // Simulate work and optimization
    sleep(5); // Sleep for demonstration purposes

    optimize_memory_layout(&pool);
    take_snapshot(&pool);

    free_memory_pool(&pool);
    return EXIT_SUCCESS;
}
```

