['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 10000

typedef struct {
    long timestamp;
    int key;
    double value;
} record;

typedef struct {
    record *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} dynamic_array;

// Function to find a unique key
int find_unique_key(int key, dynamic_array *arr) {
    while (1) {
        int is_unique = 1;
        for (size_t i = 0; i < arr->size; ++i) {
            if (arr->array[i].key == key) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) return key;
        key++;
    }
}

// Initialize the dynamic array
int initialize_dynamic_array(dynamic_array *arr, size_t initial_capacity) {
    if (initial_capacity > MAX_ARRAY_SIZE) return -1;

    arr->array = malloc(sizeof(record) * initial_capacity);
    if (!arr->array) return -1;

    arr->size = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL);

    return 0;
}

// Add a new record
int add_record(dynamic_array *arr, long timestamp, int key, double value) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        if (new_capacity > MAX_ARRAY_SIZE) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Exceeded maximum capacity
        }

        record *new_array = realloc(arr->array, sizeof(record) * new_capacity);
        if (!new_array) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }

        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    key = find_unique_key(key, arr);

    record new_rec = {timestamp, key, value};
    arr->array[arr->size++] = new_rec;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Retrieve a record by key
record *get_record_by_key(dynamic_array *arr, int key) {
    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].key == key) {
            pthread_mutex_unlock(&arr->mutex);
            return &arr->array[i];
        }
    }

    pthread_mutex_unlock(&arr->mutex);
    return NULL;
}

// Free the dynamic array
void free_dynamic_array(dynamic_array *arr) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->array) {
        free(arr->array);
        arr->array = NULL;
    }
    arr->size = 0;
    arr->capacity = 0;

    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

