#include <time.h>

typedef struct {
    int id;
    float value;
} item;

typedef struct node {
    item data;
    struct node* next;
} Node;

Node* create_node(int min_id, int max_id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    srand(time(NULL)); // Seed for random number generation
    new_node->data.id = rand() % (max_id - min_id + 1) + min_id;
    new_node->data.value = ((float)rand() / RAND_MAX); // Random float between 0 and 1

    new_node->next = NULL;
    return new_node;
}

void update_linked_list(Node* head, int updates, int min_id, int max_id) {
    Node* current = head;
    while (updates > 0 && current != NULL) {
        if ((rand() % 2) == 1) { // Randomly decide to update or not
            current->data.id = rand() % (max_id - min_id + 1) + min_id;
            current->data.value = ((float)rand() / RAND_MAX);
        }
        current = current->next;
        updates--;
    }
}

void* allocate_and_initialize(void* args) {
    int num_metrics, num_tags, num_items;
    sscanf((char*)args, "%d %d %d", &num_metrics, &num_tags, &num_items);

    double* metrics_array = (double*)malloc(num_metrics * sizeof(double));
    if (!metrics_array) return NULL;

    char** metadata_tags = (char**)malloc(num_tags * sizeof(char*));
    if (!metadata_tags) {
        free(metrics_array);
        return NULL;
    }

    for (int i = 0; i < num_tags; ++i) {
        metadata_tags[i] = strdup("MetadataTag"); // Example tag
    }

    item** items_array = (item**)malloc(num_items * sizeof(item*));
    if (!items_array) {
        free(metrics_array);
        for (int i = 0; i < num_tags; ++i) {
            free(metadata_tags[i]);
        }
        free(metadata_tags);
        return NULL;
    }

    Node* head = create_node(1, 100); // Example range
    if (!head) {
        free(metrics_array);
        for (int i = 0; i < num_tags; ++i) {
            free(metadata_tags[i]);
        }
        free(metadata_tags);
        free(items_array);
        return NULL;
    }

    Node* current = head;
    while (--num_items > 0) {
        Node* new_node = create_node(1, 100); // Example range
        if (!new_node) break;

        items_array[num_items - 1] = &(new_node->data);
        current->next = new_node;
        current = new_node;
    }

    return malloc(sizeof(double*) * 3 + sizeof(char**) + sizeof(item**)
                  + head ? sizeof(Node) : 0
                  + (head ? (current ? (current->next ? calculate_size(current->next, 1) : 0) : 0) : 0));
}

size_t calculate_size(Node* node, int level) {
    if (!node) return 0;
    return sizeof(Node) + calculate_size(node->next, level + 1);
}
