import ctypes
from math import sqrt

# Load shared library
c_lib = ctypes.CDLL('./your_c_library.so')

# Define C structures in Python
class Item(ctypes.Structure):
    _fields_ = [("id", ctypes.c_int), ("value", ctypes.c_float)]

class MetricsAndTags:
    def __init__(self, metrics_array, metadata_tags, items_array):
        self.metrics_array = metrics_array
        self.metadata_tags = metadata_tags
        self.items_array = items_array

def process_integers(int_list):
    # Filter out even numbers and take square roots of odd numbers
    processed = [sqrt(x) for x in int_list if x % 2 != 0]

    # Sort the result in descending order
    return sorted(processed, reverse=True)

# Define function to call C allocation from Python
def allocate_and_initialize(num_metrics, num_tags, num_items):
    c_lib.allocate_and_initialize.restype = ctypes.POINTER(MetricsAndTags)
    args = f"{num_metrics} {num_tags} {num_items}".encode('utf-8')

    result_ptr = c_lib.allocate_and_initialize(args)
    if not result_ptr:
        raise MemoryError("Failed to allocate memory in C.")

    result = result_ptr.contents
    return result

def update_c_structures(integers):
    processed_list = process_integers(integers)

    # Retrieve allocated structures from the C library
    metrics_and_tags = allocate_and_initialize(5, 3, len(processed_list))

    # Update the `item` structures in C with processed data
    for i, value in enumerate(processed_list):
        item_instance = Item()
        item_instance.id = integers[i]
        item_instance.value = float(value)

        metrics_and_tags.items_array[i] = ctypes.pointer(item_instance)

# Example usage:
if __name__ == "__main__":
    integer_list = [1, 2, 3, 4, 5, 6, 7, 8, 9]
    update_c_structures(integer_list)
