static size_t hashFunction(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

static void resizeManager(DataManager *manager, size_t newSize);

DataManager* initDataManager(size_t initialSize, double minValue, double maxValue) {
    DataManager *manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->capacity = initialSize;
    manager->entries = (dataEntry**)calloc(manager->capacity, sizeof(dataEntry*));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    // Simulate JSON config reading and gzip decompression
    // For simplicity, we'll just use the initialSize and range here

    for (size_t i = 0; i < manager->capacity; ++i) {
        dataEntry *entry = (dataEntry*)malloc(sizeof(dataEntry));
        if (!entry) {
            freeDataManager(manager);
            return NULL;
        }

        entry->identifier = (char*)malloc(10); // Assume identifiers are strings of max length 9
        snprintf(entry->identifier, 10, "ID_%zu", i);

        entry->value = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);
        entry->metadata = strdup("default metadata");

        manager->entries[i] = entry;
    }

    return manager;
}

void freeDataManager(DataManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->entries[i]) {
            free(manager->entries[i]->identifier);
            free(manager->entries[i]->metadata);
            free(manager->entries[i]);
        }
    }

    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addDataEntry(DataManager *manager, const char *identifier, double value, const char *metadata) {
    if (!manager || !identifier) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->entries[i]) {
            dataEntry *entry = (dataEntry*)malloc(sizeof(dataEntry));
            if (!entry) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            entry->identifier = strdup(identifier);
            entry->value = value;
            entry->metadata = strdup(metadata);

            manager->entries[i] = entry;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // Resize if no empty slot found
    resizeManager(manager, manager->capacity * 2);

    // Try to add again after resizing
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->entries[i]) {
            dataEntry *entry = (dataEntry*)malloc(sizeof(dataEntry));
            if (!entry) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            entry->identifier = strdup(identifier);
            entry->value = value;
            entry->metadata = strdup(metadata);

            manager->entries[i] = entry;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Should not reach here
}

dataEntry* searchDataEntry(const DataManager *manager, const char *identifier) {
    if (!manager || !identifier) return NULL;

    size_t hashIndex = hashFunction(identifier) % manager->capacity;
    for (size_t i = 0; i < manager->capacity; ++i) {
        dataEntry *entry = manager->entries[(hashIndex + i) % manager->capacity];
        if (!entry) break;
        if (strcmp(entry->identifier, identifier) == 0) {
            return entry;
        }
    }

    return NULL;
}

double calculateAverageValue(const DataManager *manager) {
    if (!manager) return NAN;

    double sum = 0.0;
    size_t count = 0;

    for (size_t i = 0; i < manager->capacity; ++i) {
        dataEntry *entry = manager->entries[i];
        if (entry) {
            sum += entry->value;
            count++;
        }
    }

    return count ? sum / count : NAN;
}

static void resizeManager(DataManager *manager, size_t newSize) {
    dataEntry **newEntries = (dataEntry**)calloc(newSize, sizeof(dataEntry*));
    if (!newEntries) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->entries[i]) {
            dataEntry *entry = manager->entries[i];
            size_t newIndex = hashFunction(entry->identifier) % newSize;
            while (newEntries[newIndex]) {
                newIndex = (newIndex + 1) % newSize;
            }
            newEntries[newIndex] = entry;
        }
    }

    free(manager->entries);
    manager->entries = newEntries;
    manager->capacity = newSize;
}

// Main function for demonstration purposes
int main() {
    DataManager *manager = initDataManager(10, 0.0, 100.0);
    if (!manager) {
        fprintf(stderr, "Failed to initialize data manager\n");
        return EXIT_FAILURE;
    }

    addDataEntry(manager, "Custom_ID_1", 42.0, "custom metadata");

    dataEntry *entry = searchDataEntry(manager, "Custom_ID_1");
    if (entry) {
        printf("Found entry: %s, Value: %.2f, Metadata: %s\n",
               entry->identifier, entry->value, entry->metadata);
    } else {
        printf("Entry not found.\n");
    }

    double average = calculateAverageValue(manager);
    printf("Average value: %.2f\n", average);

    freeDataManager(manager);
    return EXIT_SUCCESS;
}
