['Below is a C implementation that addresses the requirements outlined in your task. This code includes key components like thread-safe operations using atomic functions, dynamic memory allocation with error handling, and basic logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_RECORD_COUNT 1000
#define MAX_RECORDS 10000000
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 100

typedef struct Record {
    int value;
    long offset;
    int key;
    atomic_int ref_count;
    pthread_mutex_t lock; // For record-level locking
} Record;

Record* records = NULL;
size_t record_count = 0;
pthread_rwlock_t collection_lock; // Read-write lock for the entire collection

// Logging function placeholder
void log_event(const char *message) {
    printf("%s\n", message);
}

// Initialize records with random values
void initialize_records(size_t initial_count) {
    srand(time(NULL));
    pthread_rwlock_init(&collection_lock, NULL);

    record_count = initial_count;
    records = (Record*)malloc(record_count * sizeof(Record));

    if (!records) {
        log_event("Memory allocation failed for records.");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_init(&records[i].lock, NULL);
        records[i].value = rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN;
        records[i].offset = 0;
        records[i].key = 0;
        atomic_store(&records[i].ref_count, 0);
    }

    log_event("Records initialized successfully.");
}

// Add a new record
void add_record() {
    pthread_rwlock_wrlock(&collection_lock);

    if (record_count >= MAX_RECORDS) {
        log_event("Maximum record limit reached.");
        pthread_rwlock_unlock(&collection_lock);
        return;
    }

    Record *new_records = realloc(records, (record_count + 1) * sizeof(Record));

    if (!new_records) {
        log_event("Memory allocation failed while adding a new record.");
        pthread_rwlock_unlock(&collection_lock);
        return;
    }

    records = new_records;
    size_t idx = record_count++;
    pthread_mutex_init(&records[idx].lock, NULL);
    records[idx].value = rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN;
    records[idx].offset = 0;
    records[idx].key = 0;
    atomic_store(&records[idx].ref_count, 0);

    pthread_rwlock_unlock(&collection_lock);
}

// Thread-safe update of record offset and key
void update_record(size_t index, long new_offset, int new_key) {
    if (index >= record_count) return;

    pthread_mutex_lock(&records[index].lock);

    atomic_store(&records[index].offset, new_offset);
    records[index].key = new_key;
    atomic_fetch_add(&records[index].ref_count, 1);

    pthread_mutex_unlock(&records[index].lock);
}

// Retrieve a record by index
Record* get_record(size_t index) {
    if (index >= record_count) return NULL;

    pthread_rwlock_rdlock(&collection_lock);
    Record *record = &records[index];
    atomic_fetch_add(&record->ref_count, 1);
    pthread_rwlock_unlock(&collection_lock);

    pthread_mutex_lock(&record->lock);

    // Simulate usage
    pthread_mutex_unlock(&record->lock);

    return record;
}

// Free all resources
void cleanup() {
    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_destroy(&records[i].lock);
    }
    free(records);
    records = NULL;
    pthread_rwlock_destroy(&collection_lock);
    log_event("Cleanup completed.");
}

// Example function showing basic operations
void example_usage() {
    initialize_records(INITIAL_RECORD_COUNT);

    // Add a new record
    add_record();

    // Update the first record
    update_record(0, 12345L, 6789);

    // Retrieve and log details of the first record
    Record *record = get_record(0);
    if (record) {
        printf("Record value: %d\n", record->value);
    }

    cleanup();
}

int main() {
    example_usage();

    return 0;
}
```

### Explanation

1. **Data Structures**: A `Record` struct is used to represent individual records, containing an integer value, offset (`long`), key (`int`), and a reference count for tracking accesses.

2. **Concurrency Handling**:
   - A read-write lock (`pthread_rwlock_t`) protects the entire collection during modifications.
   - Each record has its own mutex (`pthread_mutex_t`) to ensure fine-grained locking when updating or accessing individual records.

3. **Atomic Operations**: Atomic operations are used for updating and reading the reference count, ensuring thread safety without locks.

4. **Dynamic Growth**: The `add_record` function dynamically expands the collection using `realloc`, handling memory allocation failures gracefully.

5. **Logging**: A simple logging mechanism (`log_event`) is included to track significant events like initialization and errors.

6. **Cleanup**: Proper cleanup of resources (mutexes, locks) ensures no resource leaks when the application exits or encounters an error.

This code provides a foundation for building upon more complex features such as pluggable storage backends, serialization/deserialization, and enhanced logging mechanisms.']

