#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Record {
    int value;
    long *offset_ptr;
    int *key_ptr;
} Record;

typedef struct HashTableNode {
    int key;
    struct HashTableNode *next;
    Record record;
} HashTableNode;

typedef struct {
    size_t capacity;
    size_t size;
    HashTableNode **buckets;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    HashTable hash_table;
} Collection;

#define INITIAL_CAPACITY 16
#define HASH_TABLE_LOAD_FACTOR 0.75

unsigned int hash(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

HashTable *create_hash_table(size_t initial_capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = calloc(table->capacity, sizeof(HashTableNode*));
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            HashTableNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void resize_hash_table(HashTable *table);

int hash_table_insert(HashTable *table, int key, Record record) {
    unsigned int index = hash(key, table->capacity);

    HashTableNode *new_node = malloc(sizeof(HashTableNode));
    if (!new_node) return -1;

    new_node->key = key;
    new_node->record = record;
    new_node->next = NULL;

    pthread_mutex_lock(&table->lock);

    HashTableNode *node = table->buckets[index];
    while (node && node->key != key) {
        node = node->next;
    }

    if (!node) { // Insert new node
        new_node->next = table->buckets[index];
        table->buckets[index] = new_node;
        ++table->size;

        float load_factor = (float)table->size / table->capacity;
        if (load_factor > HASH_TABLE_LOAD_FACTOR) {
            resize_hash_table(table);
        }
    } else { // Update existing node
        node->record = record;
    }

    pthread_mutex_unlock(&table->lock);
    return 0; 
}

void *resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashTableNode **new_buckets = calloc(new_capacity, sizeof(HashTableNode*));

    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            unsigned int new_index = hash(node->key, new_capacity);

            HashTableNode *next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

Record *get_record(Collection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index < collection->size) {
        Record *record = &collection->records[index];
        pthread_mutex_unlock(&collection->lock);
        return record;
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_record(Collection *collection, size_t index, int value) {
    pthread_mutex_lock(&collection->lock);
    if (index < collection->size) {
        collection->records[index].value = value;

        // Update hash table
        int key = *(collection->keys + index);
        Record record = collection->records[index];
        record.offset_ptr = &collection->offsets[index];
        record.key_ptr = &collection->keys[index];

        hash_table_insert(&collection->hash_table, key, record);

        pthread_mutex_unlock(&collection->lock);
        return 0;
    }
    pthread_mutex_unlock(&collection->lock);
    return -1;
}

void initialize_collection(Collection *collection, size_t num_records, int min_value, int max_value) {
    collection->capacity = INITIAL_CAPACITY > num_records ? INITIAL_CAPACITY : num_records;
    collection->size = 0;

    collection->offsets = malloc(collection->capacity * sizeof(long));
    collection->keys = malloc(collection->capacity * sizeof(int));
    collection->records = malloc(collection->capacity * sizeof(Record));

    if (!collection->offsets || !collection->keys || !collection->records) {
        // Handle memory allocation failure
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        return;
    }

    collection->hash_table = *create_hash_table(collection->capacity);

    pthread_mutex_init(&collection->lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        long offset = rand(); // Simulate random offset
        int key = rand() % 100; // Simulate random key

        collection->offsets[i] = offset;
        collection->keys[i] = key;

        Record record;
        record.value = min_value + (rand() % (max_value - min_value + 1));
        record.offset_ptr = &collection->offsets[i];
        record.key_ptr = &collection->keys[i];

        hash_table_insert(&collection->hash_table, key, record);

        collection->records[i] = record;
        ++collection->size;

        if (i >= collection->capacity - 1) {
            // Resize dynamic array
            size_t new_capacity = collection->capacity * 2;
            long *new_offsets = realloc(collection->offsets, new_capacity * sizeof(long));
            int *new_keys = realloc(collection->keys, new_capacity * sizeof(int));
            Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));

            if (!new_offsets || !new_keys || !new_records) {
                // Handle memory allocation failure
                free(new_offsets);
                free(new_keys);
                free(new_records);
                return;
            }

            collection->offsets = new_offsets;
            collection->keys = new_keys;
            collection->records = new_records;

            collection->capacity = new_capacity;

            resize_hash_table(&collection->hash_table);
        }
    }
}

void iterate_over_collection(Collection *collection, void (*callback)(Record *)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        callback(&collection->records[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Dummy database interaction functions to simulate external API integration
void persist_record_to_db(Record *record) {
    // Simulate database persistence
    printf("Persisting record: value=%d\n", record->value);
}

int update_collection_in_db(Collection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (index < collection->size) {
        Record record = collection->records[index];

        // Simulate database transaction
        persist_record_to_db(&record);

        pthread_mutex_unlock(&collection->lock);
        return 0;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

// Example callback function for iteration
void print_record(Record *record) {
    printf("Record: value=%d, offset=%ld\n", record->value, *(record->offset_ptr));
}

int main() {
    Collection collection;
    initialize_collection(&collection, 20, 0, 100);

    iterate_over_collection(&collection, print_record);

    update_record(&collection, 5, 50);
    iterate_over_collection(&collection, print_record);

    update_collection_in_db(&collection, 5);

    free(collection.offsets);
    free(collection.keys);
    free(collection.records);
    free_hash_table(&collection.hash_table);

    return 0;
}
