    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Job **new_jobs = (Job **)realloc(collection->jobs, new_capacity * sizeof(Job *));
        if (!new_jobs) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }
        memset(new_jobs + collection->count, 0, (new_capacity - collection->capacity) * sizeof(Job *));
        collection->jobs = new_jobs;
        collection->capacity = new_capacity;
    }

    Job *job = (Job *)malloc(sizeof(Job));
    if (!job) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    job->job_name = strdup(job_name);
    job->task.priority = priority;
    job->task.deadline = deadline;
    job->status_message = strdup(status_message);

    collection->jobs[collection->count++] = job;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

Job* get_job(JobCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    Job *job = (index < collection->count) ? collection->jobs[index] : NULL;
    pthread_mutex_unlock(&collection->lock);
    return job;
}

int update_job_priority(JobCollection *collection, size_t index, int new_priority) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Index out of bounds
    }

    Job *job = collection->jobs[index];
    job->task.priority = new_priority;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void iterate_jobs(JobCollection *collection, void (*callback)(Job *)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->jobs[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

