#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>
#include <time.h>

#define LOG_FILE "dns_log.txt"
#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define CACHE_SIZE 100
#define DNS_EXPIRATION_TIME 300 // seconds

typedef struct {
    int intValue;
    double doubleValue;
    char identifier;
    unsigned char ipAddress[4];
} record;

// Dynamic array structure
typedef struct {
    void* data;
    size_t elementSize;
    size_t capacity;
    size_t length;
} dynamicArray;

// DNS cache entry
typedef struct {
    char hostname[256];
    unsigned char ipAddress[4];
    time_t timestamp;
} dnsCacheEntry;

// Global variables for thread safety and configuration
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
dynamicArray offsets, keys, records, dnsCache;
int cacheSize = CACHE_SIZE;
int concurrencyLevel = 1; // Default to single-threaded

void logMessage(const char* message) {
    pthread_mutex_lock(&mutex);
    FILE* logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
    } else {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);

        // Log rotation
        long fileSize = 0;
        struct stat st;
        if(stat(LOG_FILE, &st) == 0)
            fileSize = st.st_size;

        if(fileSize >= MAX_LOG_SIZE) {
            char newLogFileName[20];
            time_t now = time(NULL);
            snprintf(newLogFileName, sizeof(newLogFileName), "dns_log_%ld.txt", now);
            rename(LOG_FILE, newLogFileName);
            fopen(LOG_FILE, "w");
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* resolveHostname(const char* hostname) {
    static dnsCacheEntry cache[CACHE_SIZE];
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < cache.length; ++i) {
        if (strcmp(cache.data[i].hostname, hostname) == 0 &&
            (currentTime - cache.data[i].timestamp) < DNS_EXPIRATION_TIME) {

            logMessage("DNS cache hit");
            return (void*)&cache.data[i];
        }
    }

    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        char errorMsg[256];
        snprintf(errorMsg, sizeof(errorMsg), "DNS resolution failed for %s: %s", hostname, strerror(errno));
        logMessage(errorMsg);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) {
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            memcpy(cache.data[cache.length].ipAddress, &(ipv4->sin_addr), sizeof(ipv4->sin_addr));
            strncpy(cache.data[cache.length].hostname, hostname, sizeof(cache.data[cache.length].hostname) - 1);
            cache.data[cache.length].timestamp = currentTime;

            logMessage("DNS resolution succeeded");
            freeaddrinfo(res);
            return (void*)&cache.data[cache.length++];
        }
    }

    freeaddrinfo(res);
    char errorMsg[256];
    snprintf(errorMsg, sizeof(errorMsg), "No IPv4 address found for %s", hostname);
    logMessage(errorMsg);

    return NULL;
}

int initializeDynamicArray(dynamicArray* array) {
    if ((array->data = malloc(array->capacity * array->elementSize)) == NULL) {
        perror("Failed to allocate memory");
        return -1;
    }
    array->length = 0;
    return 0;
}

void resizeDynamicArrayIfNeeded(dynamicArray* array, size_t newLength) {
    if (newLength > array->capacity) {
        while (array->capacity < newLength) {
            array->capacity *= 2;
        }

        void* newData = realloc(array->data, array->elementSize * array->capacity);
        if (newData == NULL) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        array->data = newData;
    }
}

int largestInteger(int n, ...) {
    va_list args;
    va_start(args, n);

    int largest = INT_MIN;
    for (int i = 0; i < n; ++i) {
        int value = va_arg(args, int);
        if (value > largest) {
            largest = value;
        }
    }

    va_end(args);
    return largest;
}

record* getHighestDoubleValueRecord(dynamicArray* records) {
    if (records->length == 0) return NULL;

    record* highestRecord = (record*)records->data;
    for (size_t i = 1; i < records->length; ++i) {
        record* currentRecord = (record*)(records->data + i * sizeof(record));
        if (currentRecord->doubleValue > highestRecord->doubleValue) {
            highestRecord = currentRecord;
        }
    }

    return highestRecord;
}

void handleDynamicDataPipeline(const char* hostname, int rangeLow, int rangeHigh) {
    // Initialize dynamic arrays
    offsets.elementSize = sizeof(long);
    keys.elementSize = sizeof(int);
    records.elementSize = sizeof(record);

    if (initializeDynamicArray(&offsets) < 0 || initializeDynamicArray(&keys) < 0 ||
        initializeDynamicArray(&records) < 0 || initializeDynamicArray(&dnsCache) < 0) {
        exit(EXIT_FAILURE);
    }

    // Read integers from standard input
    int numberOfIntegers;
    scanf("%d", &numberOfIntegers);

    for (int i = 0; i < numberOfIntegers; ++i) {
        int key;
        scanf("%d", &key);

        resizeDynamicArrayIfNeeded(&keys, keys.length + 1);
        keys.data[keys.length++] = key;

        // Random value within range
        int randomValue = rand() % (rangeHigh - rangeLow + 1) + rangeLow;

        unsigned char* resolvedIP = (unsigned char*)resolveHostname(hostname);
        if (!resolvedIP) {
            fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
            continue;
        }

        resizeDynamicArrayIfNeeded(&records, records.length + 1);

        record newRecord;
        newRecord.intValue = randomValue;
        newRecord.doubleValue = 0.0;
        newRecord.identifier = 'R'; // Example character
        memcpy(newRecord.ipAddress, resolvedIP, sizeof(newRecord.ipAddress));

        records.data[records.length - 1] = newRecord;
    }

    int largestInt = largestInteger(numberOfIntegers, keys.data);
    printf("Largest integer: %d\n", largestInt);

    record* highestDoubleValueRecord = getHighestDoubleValueRecord(&records);
    if (highestDoubleValueRecord) {
        printf("Record with highest double value:\n");
        printf("  int: %d\n", highestDoubleValueRecord->intValue);
        printf("  double: %.2f\n", highestDoubleValueRecord->doubleValue);
        printf("  char: %c\n", highestDoubleValueRecord->identifier);
        printf("  IP: %u.%u.%u.%u\n",
               highestDoubleValueRecord->ipAddress[0],
               highestDoubleValueRecord->ipAddress[1],
               highestDoubleValueRecord->ipAddress[2],
               highestDoubleValueRecord->ipAddress[3]);
    }
}

record* getRecordAtIndex(dynamicArray* records, size_t index) {
    if (index >= records->length) return NULL;
    return (record*)(records->data + index * sizeof(record));
}

int main() {
    srand((unsigned int)time(NULL)); // Seed for random number generation

    handleDynamicDataPipeline("example.com", 1, 100);

    // Example of retrieving a record
    size_t index = 0;
    record* retrievedRecord = getRecordAtIndex(&records, index);
    if (retrievedRecord) {
        printf("Retrieved Record:\n");
        printf("  int: %d\n", retrievedRecord->intValue);
        printf("  double: %.2f\n", retrievedRecord->doubleValue);
        printf("  char: %c\n", retrievedRecord->identifier);
        printf("  IP: %u.%u.%u.%u\n",
               retrievedRecord->ipAddress[0],
               retrievedRecord->ipAddress[1],
               retrievedRecord->ipAddress[2],
               retrievedRecord->ipAddress[3]);
    }

    // Cleanup
    free(offsets.data);
    free(keys.data);
    free(records.data);
    free(dnsCache.data);

    return 0;
}
