} record;

typedef struct {
    long* offset_array;
    int* key_array;
    record* records_array;
    size_t array_size;
    pthread_mutex_t lock;
} data_pool;

data_pool* create_data_pool(size_t initial_size) {
    data_pool* pool = (data_pool*) malloc(sizeof(data_pool));
    if (!pool) return NULL;

    // Initialize memory with mutex for thread safety
    pthread_mutex_init(&pool->lock, NULL);

    pool->offset_array = (long*) malloc(initial_size * sizeof(long));
    pool->key_array = (int*) malloc(initial_size * sizeof(int));
    pool->records_array = (record*) malloc(initial_size * sizeof(record));
    pool->array_size = initial_size;

    if (!pool->offset_array || !pool->key_array || !pool->records_array) {
        free(pool->offset_array);
        free(pool->key_array);
        free(pool->records_array);
        free(pool);
        return NULL;
    }

    memset(pool->offset_array, 0, initial_size * sizeof(long));
    memset(pool->key_array, 0, initial_size * sizeof(int));
    for (size_t i = 0; i < initial_size; ++i) {
        pool->records_array[i].unique_value = -1;
        pool->records_array[i].timestamp = 0;
        pool->records_array[i].status_flag = 0;
    }

    return pool;
}

int resize_data_pool(data_pool* pool, size_t new_size) {
    if (!pool || !new_size) return -1;

    pthread_mutex_lock(&pool->lock);

    long* new_offset_array = (long*) realloc(pool->offset_array, new_size * sizeof(long));
    int* new_key_array = (int*) realloc(pool->key_array, new_size * sizeof(int));
    record* new_records_array = (record*) realloc(pool->records_array, new_size * sizeof(record));

    if (!new_offset_array || !new_key_array || !new_records_array) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Out-of-memory error
    }

    memset(new_offset_array + pool->array_size, 0, (new_size - pool->array_size) * sizeof(long));
    memset(new_key_array + pool->array_size, 0, (new_size - pool->array_size) * sizeof(int));

    for (size_t i = pool->array_size; i < new_size; ++i) {
        new_records_array[i].unique_value = -1;
        new_records_array[i].timestamp = 0;
        new_records_array[i].status_flag = 0;
    }

    // Update pointers and size
    pool->offset_array = new_offset_array;
    pool->key_array = new_key_array;
    pool->records_array = new_records_array;
    pool->array_size = new_size;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int initialize_record(data_pool* pool, size_t index, int unique_value) {
    if (!pool || index >= pool->array_size || unique_value < 0) return -1;

    pthread_mutex_lock(&pool->lock);

    // Check for consecutive duplicate values
    if (index > 0 && pool->records_array[index - 1].unique_value == unique_value) {
        pthread_mutex_unlock(&pool->lock);
        return -2; // Consecutive record constraint violated
    }

    pool->records_array[index].unique_value = unique_value;
    pool->records_array[index].timestamp = time(NULL); // Use actual timestamp generation as needed.
    pool->records_array[index].status_flag = 1;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void reset_data_pool(data_pool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    memset(pool->offset_array, 0, pool->array_size * sizeof(long));
    memset(pool->key_array, 0, pool->array_size * sizeof(int));

    for (size_t i = 0; i < pool->array_size; ++i) {
        pool->records_array[i].unique_value = -1;
        pool->records_array[i].timestamp = 0;
        pool->records_array[i].status_flag = 0;
    }

    pthread_mutex_unlock(&pool->lock);
}

void destroy_data_pool(data_pool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);

    free(pool->offset_array);
    free(pool->key_array);
    free(pool->records_array);
    free(pool);
}
```

