- **Reset Capability**: Resets all data without retaining previous states.
- **Graceful Degradation**: In case of errors (e.g., out-of-memory), the function returns error codes.

This implementation is designed to be robust, efficient, and suitable for use in environments where concurrent operations are common. Additional logging or retry mechanisms can be added based on specific requirements for handling transient errors or API-related issues.']

['Below is a C implementation that addresses the task described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

// Configuration constants - these could be set from environment or config files
#define INITIAL_BUFFER_SIZE 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    uint64_t timestamp;
    int log_level;
    int message_id;
} LogMetadata;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} LogManagerBuffer;

typedef struct {
    LogMetadata *metadata_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
} LogManagerQueue;

LogManagerBuffer log_buffer;
LogManagerQueue log_queue;

void init_log_manager() {
    pthread_mutex_init(&log_buffer.lock, NULL);
    pthread_mutex_init(&log_queue.lock, NULL);
    pthread_cond_init(&log_queue.not_empty, NULL);

    log_buffer.buffer = malloc(INITIAL_BUFFER_SIZE);
    log_buffer.capacity = INITIAL_BUFFER_SIZE;
    log_buffer.length = 0;

    log_queue.metadata_array = malloc(sizeof(LogMetadata) * 10);
    log_queue.capacity = 10;
    log_queue.count = 0;
}

void resize_log_buffer(size_t new_capacity) {
    pthread_mutex_lock(&log_buffer.lock);

    char *new_buffer = realloc(log_buffer.buffer, new_capacity);
    if (new_buffer) {
        log_buffer.buffer = new_buffer;
        log_buffer.capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize log buffer\n");
    }

    pthread_mutex_unlock(&log_buffer.lock);
}

void enqueue_log(LogMetadata metadata) {
    pthread_mutex_lock(&log_queue.lock);

    if (log_queue.count == log_queue.capacity) {
        size_t new_capacity = log_queue.capacity * 2;
        LogMetadata *new_array = realloc(log_queue.metadata_array, sizeof(LogMetadata) * new_capacity);

        if (!new_array) {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to resize queue\n");
            pthread_mutex_unlock(&log_queue.lock);
            return;
        }

        log_queue.metadata_array = new_array;
        log_queue.capacity = new_capacity;
    }

    log_queue.metadata_array[log_queue.count++] = metadata;

    // Signal any waiting threads that there's data in the queue
    pthread_cond_signal(&log_queue.not_empty);

    pthread_mutex_unlock(&log_queue.lock);
}

LogMetadata dequeue_log() {
    LogMetadata metadata;

    pthread_mutex_lock(&log_queue.lock);

    while (log_queue.count == 0) {
        // Wait for log messages to be available
        pthread_cond_wait(&log_queue.not_empty, &log_queue.lock);
    }

    metadata = log_queue.metadata_array[0];
    memmove(log_queue.metadata_array,
            log_queue.metadata_array + 1,
            sizeof(LogMetadata) * --log_queue.count);

    pthread_mutex_unlock(&log_queue.lock);

    return metadata;
}

void write_log(const char *message, int level, int message_id) {
    LogMetadata metadata = { .timestamp = time(NULL), .log_level = level, .message_id = message_id };

    enqueue_log(metadata);

    pthread_mutex_lock(&log_buffer.lock);

    size_t new_length = log_buffer.length + strlen(message) + 1;

    if (new_length > log_buffer.capacity) {
        resize_log_buffer(new_length * 2);
    }

    strcat(log_buffer.buffer, message);
    log_buffer.length = new_length;

    pthread_mutex_unlock(&log_buffer.lock);
}

void reset_logging_system() {
    pthread_mutex_lock(&log_buffer.lock);
    free(log_buffer.buffer);
    log_buffer.buffer = malloc(INITIAL_BUFFER_SIZE);
    log_buffer.capacity = INITIAL_BUFFER_SIZE;
    log_buffer.length = 0;
    pthread_mutex_unlock(&log_buffer.lock);

    pthread_mutex_lock(&log_queue.lock);
    free(log_queue.metadata_array);
    log_queue.metadata_array = malloc(sizeof(LogMetadata) * 10);
    log_queue.capacity = 10;
    log_queue.count = 0;
    pthread_cond_broadcast(&log_queue.not_empty);
    pthread_mutex_unlock(&log_queue.lock);
}

void cleanup_logging_system() {
    reset_logging_system();

    pthread_mutex_destroy(&log_buffer.lock);
    pthread_mutex_destroy(&log_queue.lock);
    pthread_cond_destroy(&log_queue.not_empty);
}
```

### Key Considerations:
- **Thread Safety:** Utilizes mutexes to ensure thread-safe access to shared resources like the buffer and queue.
- **Dynamic Resizing:** Implements dynamic resizing for both log buffer and metadata queue, doubling their size when needed.
- **Concurrent Operations:** Supports concurrent writes with a lock on the buffer and reads from the queue using condition variables for synchronization.
- **Memory Management:** Uses custom memory allocations to handle potentially large amounts of logging data efficiently. This is crucial in high-load systems where performance can be significantly affected by inefficient memory handling.
- **Robust Initialization and Cleanup:** Provides functions for initializing, resetting, and cleaning up resources, ensuring the system can start and stop gracefully without resource leaks.
- **Fallback Strategies:** Handles potential allocation failures with error messages to assist debugging and ensure graceful degradation.

This design aims to balance performance, scalability, and reliability in a high-load logging environment. Adjustments might be needed based on specific requirements or constraints of your deployment context.']

['Below is a C implementation for the specified task. The code includes dynamic memory allocation for arrays of offsets and keys, as well as a scalable dynamic array for records. It also provides functions to manage these records with thread safety considerations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
void destroy_dynamic_array(DynamicArray *array, long *offsets, int *keys);
Record* get_record(const DynamicArray *array, size_t index);
int update_record(DynamicArray *array, size_t index, int newValue);
int delete_record(DynamicArray *array, size_t index);
static void resize_dynamic_array(DynamicArray *array);

// Function implementations
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray *array, long *offsets, int *keys) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i]->offset);
        free(array->records[i]->key);
        free(array->records[i]);
    }
    free(array->records);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);

    free(offsets);
    free(keys);
}

Record* get_record(const DynamicArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&array->lock);
    Record* record = array->records[index];
    pthread_mutex_unlock((pthread_mutex_t*)&array->lock);

    return record;
}

int update_record(DynamicArray *array, size_t index, int newValue) {
    if (index >= array->count) return -1;

    pthread_mutex_lock(&array->lock);
    Record* record = array->records[index];
    record->value = newValue;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

int delete_record(DynamicArray *array, size_t index) {
    if (index >= array->count) return -1;

    pthread_mutex_lock(&array->lock);
    free(array->records[index]->offset);
    free(array->records[index]->key);
    free(array->records[index]);

    for (size_t i = index; i < array->count - 1; ++i) {
        array->records[i] = array->records[i + 1];
    }
    --array->count;

    if (array->count > 0 && array->count == array->capacity / 4) {
        resize_dynamic_array(array);
    }

    pthread_mutex_unlock(&array->lock);

    return 0;
}

static void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity / 2;
    Record **new_records = (Record**)realloc(array->records, new_capacity * sizeof(Record*));
    if (!new_records) return;

    array->records = new_records;
    array->capacity = new_capacity;
}

// Function to initialize the dynamic array with records
int initialize_dynamic_array(DynamicArray *array, size_t num_records, long *offsets, int *keys) {
    srand(time(NULL));

    pthread_mutex_lock(&array->lock);
    if (num_records > array->capacity - array->count) {
        while (num_records > array->capacity - array->count) {
            resize_dynamic_array(array);
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        record->value = rand() % 100; // Random value between 0 and 99
        record->offset = &offsets[i];
        record->key = &keys[i];

        array->records[array->count++] = record;
    }
    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Example usage
int main() {
    size_t num_records = 10;
    DynamicArray *dynamic_array = create_dynamic_array(5);
    long *offsets = (long*)malloc(num_records * sizeof(long));
    int *keys = (int*)malloc(num_records * sizeof(int));

    if (!dynamic_array || !offsets || !keys) {
        printf("Memory allocation failed\n");
        return 1;
    }

    if (initialize_dynamic_array(dynamic_array, num_records, offsets, keys) != 0) {
        printf("Initialization failed\n");
        destroy_dynamic_array(dynamic_array, offsets, keys);
        return 1;
    }

    // Example operations
    Record *record = get_record(dynamic_array, 2);
    if (record) {
        printf("Record value: %d\n", record->value);
    }

    update_record(dynamic_array, 2, 42);
    delete_record(dynamic_array, 2);

    destroy_dynamic_array(dynamic_array, offsets, keys);
    return 0;
}
```

### Key Features:
