    srand((unsigned)time(NULL));
}

// Function to generate a random integer within a range [min, max]
int rand_int(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random float within a range [min, max]
float rand_float(float min, float max) {
    return min + ((float)rand() / RAND_MAX * (max - min));
}

// Function to create and initialize a dynamic array of records
dynamic_array* create_dynamic_array(size_t count, int value_range_min, int value_range_max, 
                                    float measurement_range_min, float measurement_range_max) {
    dynamic_array *arr = malloc(sizeof(dynamic_array));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed for dynamic_array\n");
        return NULL;
    }

    arr->records = malloc(count * sizeof(record));
    if (!arr->records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->mutex, NULL);

    for (size_t i = 0; i < count; ++i) {
        arr->records[i].value = rand_int(value_range_min, value_range_max);
        arr->records[i].offset = malloc(sizeof(long));
        if (!arr->records[i].offset) {
            fprintf(stderr, "Memory allocation failed for offset\n");
            // Free previously allocated memory
            while (i > 0) {
                free(arr->records[--i].offset);
            }
            free(arr->records);
            pthread_mutex_destroy(&arr->mutex);
            free(arr);
            return NULL;
        }
        *(arr->records[i].offset) = 0; // Initialize offset to zero
        arr->records[i].key = i;       // Set key to index for simplicity

        arr->records[i].continuous_measurement = malloc(sizeof(float));
        if (!arr->records[i].continuous_measurement) {
            fprintf(stderr, "Memory allocation failed for continuous_measurement\n");
            free(arr->records[i].offset);
            // Free previously allocated memory
            while (i > 0) {
                free(arr->records[--i].offset);
                free(arr->records[i].continuous_measurement);
            }
            free(arr->records);
            pthread_mutex_destroy(&arr->mutex);
            free(arr);
            return NULL;
        }
        *(arr->records[i].continuous_measurement) = rand_float(measurement_range_min, measurement_range_max);
    }

    arr->count = count;

    return arr;
}

// Function to retrieve a specific record by its index
record* get_record(dynamic_array *arr, size_t index) {
    if (!arr || index >= arr->count) {
        fprintf(stderr, "Invalid array or index\n");
        return NULL;
    }

    pthread_mutex_lock(&arr->mutex);
    record *result = &arr->records[index];
    pthread_mutex_unlock(&arr->mutex);

    return result;
}

// Function to update the continuous measurement of a specific record
void update_measurement(dynamic_array *arr, size_t index, float new_measurement) {
    if (!arr || index >= arr->count) {
        fprintf(stderr, "Invalid array or index\n");
        return;
    }

    pthread_mutex_lock(&arr->mutex);
    *(arr->records[index].continuous_measurement) = new_measurement;
    pthread_mutex_unlock(&arr->mutex);
}

// Function to free the dynamic array and its resources
void destroy_dynamic_array(dynamic_array *arr) {
    if (!arr) return;

    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->records[i].offset);
        free(arr->records[i].continuous_measurement);
    }
    free(arr->records);

    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

int main() {
    init_random();

    size_t count = 10;
    dynamic_array *arr = create_dynamic_array(count, 1, 100, 0.0f, 10.0f);
    if (!arr) return EXIT_FAILURE;

    // Example usage
