        printf("%s\n", message);
    }
}

MemoryPool *create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->pool = malloc(pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    pthread_mutex_init(&mp->lock, NULL);

    log_message(LOG_LEVEL_INFO, "Memory pool created.");
    return mp;
}

void *allocate_from_pool(MemoryPool *mp, size_t size) {
    if (size > mp->block_size) {
        log_message(LOG_LEVEL_ERROR, "Requested allocation larger than block size.");
        return NULL;
    }

    pthread_mutex_lock(&mp->lock);
    void *ptr = malloc(mp->block_size); // Simplified allocation
    if (!ptr) {
        log_message(LOG_LEVEL_ERROR, "Memory pool allocation failed.");
    } else {
        log_message(LOG_LEVEL_DEBUG, "Allocated memory from pool.");
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void deallocate_memory_pool(MemoryPool *mp) {
    if (mp) {
        pthread_mutex_lock(&mp->lock);
        free(mp->pool);
        pthread_mutex_unlock(&mp->lock);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
        log_message(LOG_LEVEL_INFO, "Memory pool deallocated.");
    }
}

