    offsets = (long *)allocate_from_pool(mp, num_offsets * sizeof(long));

    size_t num_keys = 1000;
    keys = (int *)allocate_from_pool(mp, num_keys * sizeof(int));

    size_t num_records = 500;
    records = malloc(num_records * sizeof(Record*));
    for (size_t i = 0; i < num_records; ++i) {
