    for (size_t i = 0; i < sizeof(dependencies)/sizeof(Dependency*); ++i) {
        free(dependencies[i]);
    }
    free(dependencies);

    log_message(LOG_LEVEL_INFO, "Data structures reset.");
}

int main() {
