#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double value;
    int timestamp;
    int source_id;
    char data_type[10]; // Example metadata field
} dataPoint;

// Function prototypes
void processAndAnalyzeData(int initial_size, size_t trim_interval);
dataPoint* addDataPoint(dataPoint **array, size_t *size, size_t *capacity, double value, int timestamp, int source_id, const char *data_type);
void trimOutdatedDataPoints(dataPoint **array, size_t *size, size_t trim_interval);
double calculateMovingAverage(const dataPoint *array, size_t index, size_t window_size);
int binarySearchTimestamp(const dataPoint *array, size_t size, int timestamp);

// Global variable for trimming interval (could be passed as a parameter instead)
const size_t TRIM_INTERVAL = 100;

void processAndAnalyzeData(int initial_size, size_t trim_interval) {
    // Initialize dynamic array of dataPoints
    size_t capacity = initial_size;
    dataPoint *dataArray = malloc(capacity * sizeof(dataPoint));
    if (!dataArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t currentSize = 0;

    // Main loop for processing incoming data
    while (1) {
        double value;
        int timestamp, source_id;
        char data_type[10];

        // Simulating reading data from a stream
        if (scanf("%lf %d %d %[^\n]", &value, &timestamp, &source_id, data_type) == 4) {
            dataArray = addDataPoint(&dataArray, &currentSize, &capacity, value, timestamp, source_id, data_type);

            // Trim outdated data points periodically
            if (currentSize % trim_interval == 0) {
                trimOutdatedDataPoints(&dataArray, &currentSize, trim_interval);
            }
        } else {
            break; // Break loop on input failure or EOF
        }

        // Handling query timestamp
        int query_timestamp;
        printf("Enter a timestamp to search: ");
        scanf("%d", &query_timestamp);

        // Perform binary search for the specified timestamp within the last M data points
        size_t start_index = (currentSize > trim_interval) ? currentSize - trim_interval : 0;
        int foundIndex = binarySearchTimestamp(&dataArray[start_index], currentSize - start_index, query_timestamp);

        if (foundIndex != -1) {
            printf("Data Point Found: Value=%.2f, Timestamp=%d, SourceID=%d, DataType=%s\n",
                dataArray[foundIndex + start_index].value,
                dataArray[foundIndex + start_index].timestamp,
                dataArray[foundIndex + start_index].source_id,
                dataArray[foundIndex + start_index].data_type);
        } else {
            printf("No matching timestamp found.\n");
        }
    }

    // Free dynamically allocated memory
    free(dataArray);
}

// Adds a new data point to the dynamic array, resizing if necessary
dataPoint* addDataPoint(dataPoint **array, size_t *size, size_t *capacity, double value, int timestamp, int source_id, const char *data_type) {
    if (*size == *capacity) {
        // Resize array when capacity is reached
        *capacity *= 2;
        dataPoint *newArray = realloc(*array, *capacity * sizeof(dataPoint));
        if (!newArray) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(*array);
            exit(EXIT_FAILURE);
        }
        *array = newArray;
    }

    // Add new data point
    (*array)[*size].value = value;
    (*array)[*size].timestamp = timestamp;
    (*array)[*size].source_id = source_id;
    strncpy((*array)[*size].data_type, data_type, sizeof((*array)[*size].data_type) - 1);
    (*array)[*size].data_type[sizeof((*array)[*size].data_type) - 1] = '\0';
    (*size)++;

    return *array;
}

// Trims outdated data points from the start of the array
void trimOutdatedDataPoints(dataPoint **array, size_t *size, size_t trim_interval) {
    if (*size > trim_interval) {
        // Shift elements towards the beginning to remove old entries
        memmove(*array, &((*array)[*size - trim_interval]), trim_interval * sizeof(dataPoint));
        *size -= trim_interval;
    }
}

// Calculates the moving average over a sliding window of N data points
double calculateMovingAverage(const dataPoint *array, size_t index, size_t window_size) {
    if (index < window_size - 1) return 0; // Not enough data points

    double sum = 0;
    for (size_t i = index - window_size + 1; i <= index; ++i) {
        sum += array[i].value;
    }
    return sum / window_size;
}

// Performs a binary search to find the first occurrence of a timestamp within an array
int binarySearchTimestamp(const dataPoint *array, size_t size, int timestamp) {
    int left = 0, right = (int)size - 1, mid;

    while (left <= right) {
        mid = left + (right - left) / 2;

        if (array[mid].timestamp == timestamp)
            return mid; // First occurrence found
        else if (array[mid].timestamp < timestamp)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return -1; // Timestamp not found
}

int main() {
    processAndAnalyzeData(10, TRIM_INTERVAL);
    return 0;
}
```

This code implements a function `processAndAnalyzeData` that handles real-time data streams by dynamically managing an array of `dataPoint` structures. It includes features such as adding new data points, trimming outdated ones, calculating moving averages, and performing binary search for timestamps. Comprehensive error handling ensures robustness against potential issues like memory allocation failures.']

