using System;

public class ClimateControlSystem
{
    private int minTemperature;
    private int maxTemperature;
    private int operationalMargin;
    private double[] historicalTemperatureData;

    public ClimateControlSystem(int minTemp, int maxTemp, int operationalMargin, double[] historicalData)
    {
        if (minTemp > maxTemp)
        {
            throw new ArgumentException("Minimum temperature cannot exceed maximum temperature.");
        }

        minTemperature = minTemp;
        maxTemperature = maxTemp;
        this.operationalMargin = operationalMargin;
        this.historicalTemperatureData = historicalData;

        ValidateTemperatureRange();
    }

    private void ValidateTemperatureRange()
    {
        if (historicalTemperatureData.Length == 0)
        {
            throw new ArgumentException("Historical temperature data array cannot be empty.");
        }

        int currentMin = int.MaxValue;
        int currentMax = int.MinValue;

        foreach (var temp in historicalTemperatureData)
        {
            if (temp < currentMin)
            {
                currentMin = temp;
            }
            if (temp > currentMax)
            {
                currentMax = temp;
            }
        }

        if (currentMax - currentMin > maxTemperature - minTemperature + operationalMargin)
        {
            Console.WriteLine("Warning: Historical temperature range exceeds current operational margin.");
        }
    }

    public double GetAverageTemperature()
    {
        return (minTemperature + maxTemperature) / 2.0;
    }

    public int GetNearestValidTemperature()
    {
        int average = GetAverageTemperature();
        if (average % 5 == 0)
        {
            return average;
        }
        else
        {
            return average - (average % 5);
        }
    }

    public void AdjustTemperatureRange(int newMinTemp, int newMaxTemp)
    {
        if (newMinTemp > newMaxTemp)
        {
            throw new ArgumentException("New minimum temperature cannot exceed new maximum temperature.");
        }

        minTemperature = newMinTemp;
        maxTemperature = newMaxTemp;

        ValidateTemperatureRange();
    }

    public int CalculateTemperatureSpan()
    {
        return maxTemperature - minTemperature;
    }

    public double GetAdjustedTemperature(double currentTemp)
    {
        double span = CalculateTemperatureSpan();
        double adjustedSpan = span * 0.95; // Apply a 5% margin for measurement accuracy
        return currentTemp + (UnityEngine.Random.Range(-adjustedSpan / 2, adjustedSpan / 2));
    }

