        }

    } catch (e) {
        console.error('Memory allocation failed:', e.message);
        return { error: 'Memory allocation failure' };
    }

    // Aggregation with retry mechanism
    const result = await tryAggregateWithRetries(initialState, aggregationFunction, recordArray, timeoutThreshold, maxRetries);

    // Release allocated memory (simulated)
    offsetArray = keyArray = recordArray = null;

    return result;
}

function passesFilter(transaction, criteria) {
    for (const [key, condition] of Object.entries(criteria)) {
        if (!condition(transaction[key])) return false;
    }
    return true;
}

function seededRandom(seed) {
    const x = Math.sin(seed++) * 10000;
    return () => x - Math.floor(x);
}

async function tryAggregateWithRetries(initialState, aggregationFunction, recordArray, timeoutThreshold, maxRetries) {
    let retries = 0;

    while (retries <= maxRetries) {
        try {
            return await executeAggregationWithTimeout(aggregationFunction, initialState, recordArray, timeoutThreshold);
        } catch (error) {
            if (isTimeoutError(error) && retries < maxRetries) {
                retries++;
                console.log(`Retry ${retries} due to timeout...`);
            } else {
                return { error: 'Aggregation failed', details: error.message };
            }
        }
    }

    return { error: 'Max retries reached, aggregation failed' };
}

function isTimeoutError(error) {
    return error.name === 'AggregateTimeoutError';
}

async function executeAggregationWithTimeout(aggregationFunction, initialState, recordArray, timeoutThreshold) {
    const timeoutPromise = new Promise((_, reject) => 
