#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    int value;
    long *offset;
    int *key;
    double *precision;
    char buffer[MAX_STRING_LENGTH];
} Record;

typedef struct {
    Record **records;
    size_t num_records;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* initializeAndManageRecords(size_t num_records, int value_range_min, int value_range_max, 
                                          double precision_range_min, double precision_range_max) {
    // Initialize memory pool (custom allocator can be implemented here)
    // For simplicity, we use standard malloc for this example.

    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->num_records = num_records;
    manager->records = calloc(num_records, sizeof(Record*));

    // Error checking
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            // Cleanup on failure
            while (--i >= 0) free(manager->records[i]);
            free(manager->records);
            free(manager);
            return NULL;
        }

        record->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        record->precision = malloc(sizeof(double));
        if (!record->precision) {
            free(record);
            continue; // Continue to attempt other allocations
        }
        *(record->precision) = ((double)rand() / RAND_MAX) * (precision_range_max - precision_range_min) + precision_range_min;

        // Allocate fixed-size arrays for offset, key, and buffer
        record->offset = malloc(sizeof(long));
        if (!record->offset) {
            free(record->precision);
            free(record);
            continue;
        }

        record->key = malloc(sizeof(int));
        if (!record->key) {
            free(record->offset);
            free(record->precision);
            free(record);
            continue;
        }

        manager->records[i] = record;
    }

    return manager;
}

void updateRecordString(RecordManager *manager, size_t index, const char *new_string) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->num_records && new_string) {
        strncpy(manager->records[index]->buffer, new_string, MAX_STRING_LENGTH - 1);
    }
    pthread_mutex_unlock(&manager->lock);
}

Record* getRecord(RecordManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    Record *record = (index < manager->num_records) ? manager->records[index] : NULL;
    pthread_mutex_unlock(&manager->lock);
    return record;
}

void deleteRecord(RecordManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->num_records) {
        Record *record = manager->records[index];
        free(record->offset);
        free(record->key);
        free(record->precision);
        free(record);
        manager->records[index] = NULL; // Optionally move last element to this index
    }
    pthread_mutex_unlock(&manager->lock);
}

int findLargestInteger(int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void readIntegersFromFile(const char *filename, int **numbers, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        exit(EXIT_FAILURE);
    }

    size_t capacity = 10;
    *numbers = malloc(capacity * sizeof(int));
    *count = 0;

    while (fscanf(file, "%d", &((*numbers)[*count])) == 1) {
        (*count)++;
        if (*count >= capacity) {
            capacity *= 2;
            *numbers = realloc(*numbers, capacity * sizeof(int));
        }
    }

    fclose(file);
}

void serializeRecords(RecordManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Unable to open file for writing");
        exit(EXIT_FAILURE);
    }

    fwrite(&manager->num_records, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->num_records; ++i) {
        if (!manager->records[i]) continue;
        Record *record = manager->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(record->buffer, MAX_STRING_LENGTH, 1, file);
    }
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void deserializeRecords(RecordManager **manager_out, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Unable to open file for reading");
        exit(EXIT_FAILURE);
    }

    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, file);

    RecordManager *manager = initializeAndManageRecords(num_records, -1000, 1000, 0.0, 100.0);
    if (!manager) {
        perror("Failed to initialize records");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(Record));
        fread(&record->value, sizeof(int), 1, file);
        fread(record->buffer, MAX_STRING_LENGTH, 1, file);

        record->offset = malloc(sizeof(long));
        record->key = malloc(sizeof(int));
        record->precision = malloc(sizeof(double));

        manager->records[i] = record;
    }
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    *manager_out = manager;
}

void logAction(const char *action) {
    FILE *log_file = fopen("record_manager.log", "a");
    if (!log_file) {
        perror("Unable to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&now), action);

    fclose(log_file);
}

void cleanupRecordManager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->num_records; ++i) {
        if (!manager->records[i]) continue;
        free(manager->records[i]->offset);
        free(manager->records[i]->key);
        free(manager->records[i]->precision);
        free(manager->records[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    srand(time(NULL));

    RecordManager *manager = initializeAndManageRecords(100, 0, 50, 0.0, 10.0);
    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return EXIT_FAILURE;
    }

    int *numbers = NULL;
    size_t count = 0;

    readIntegersFromFile("input.txt", &numbers, &count);

    int largest = findLargestInteger(numbers, count);
    printf("Largest integer: %d\n", largest);

    serializeRecords(manager, "records.bin");
    RecordManager *loaded_manager = NULL;
    deserializeRecords(&loaded_manager, "records.bin");

    updateRecordString(loaded_manager, 0, "Updated String!");
    deleteRecord(loaded_manager, 1);

    logAction("Serialized records to file.");
    cleanupRecordManager(manager);
    cleanupRecordManager(loaded_manager);

    free(numbers);
    return EXIT_SUCCESS;
}
```

