uint32_t xorshift32() {
    static uint32_t x = 123456789;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

void *initialize_data(void *arg) {
    struct {
        long *offsets;
        int *keys;
        record_t *records;
        size_t count;
    } *data = (struct { long *offsets; int *keys; record_t *records; size_t count; } *) arg;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    if (!data->offsets || !data->keys || !data->records) {
        log_error("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < data->count; ++i) {
        pthread_mutex_lock(&lock);

        data->offsets[i] = xorshift32() % 100000;
        data->keys[i] = xorshift32() % 10000;

        uint32_t seed = (uint32_t)time(NULL) + i;
        srand(seed);
        data->records[i].value = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

void manage_memory(size_t count, long **offsets, int **keys, record_t ***records) {
    *offsets = aligned_alloc(64, count * sizeof(long));
    if (!*offsets) {
        log_error("Failed to allocate memory for offsets");
        return;
    }

    *keys = aligned_alloc(64, count * sizeof(int));
    if (!*keys) {
        log_error("Failed to allocate memory for keys");
        free(*offsets);
        return;
    }

    *records = aligned_alloc(64, count * sizeof(record_t *));
    if (!*records) {
        log_error("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        (*records)[i] = aligned_alloc(64, sizeof(record_t));
        if (!(*records)[i]) {
            log_error("Failed to allocate memory for record");
            while (--i >= 0) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            return;
        }
    }

    pthread_t thread_id;
    struct {
        long *offsets;
        int *keys;
        record_t *records;
        size_t count;
    } data = { *offsets, *keys, (record_t *)*records, count };

    if (pthread_create(&thread_id, NULL, initialize_data, &data) != 0) {
        log_error("Failed to create thread");
        for (size_t i = 0; i < count; ++i) free((*records)[i]);
        free(*offsets);
        free(*keys);
        free(*records);
        return;
    }

    pthread_join(thread_id, NULL);

