['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    void* start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

int allocate_records(size_t max_size, size_t num_records, long min_offset, long max_offset,
                     int key_min, int key_max, FILE* log_file) {
    if (max_size < sizeof(long) * num_records + sizeof(int) * num_records + 
        sizeof(record) * num_records) {
        fprintf(log_file, "Error: Maximum size too small for requested records.\n");
        return -1;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    MemoryPool pool;
    pool.start = malloc(max_size);
    if (!pool.start) {
        fprintf(log_file, "Error: Failed to allocate memory pool.\n");
        return -1;
    }

    pool.size = max_size;
    pthread_mutex_init(&pool.lock, NULL);

    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    pthread_mutex_lock(&pool.lock);
    offsets = (long*) pool.start;
    keys = (int*)(offsets + num_records);
    records = (record*)(keys + num_records);
    pthread_mutex_unlock(&pool.lock);

    if (!offsets || !keys || !records) {
        fprintf(log_file, "Error: Memory allocation within pool failed.\n");
        free(pool.start);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    srand((unsigned int)(time(NULL) ^ (getpid() << 16)));

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        keys[i] = key_min + rand() % (key_max - key_min + 1);
        records[i].value = key_min + rand() % (key_max - key_min + 1);
    }

    fprintf(log_file, "Successfully allocated memory for %zu records.\n", num_records);

    pthread_mutex_destroy(&pool.lock);
    return 0;
}
```

This C function implements a mechanism to manage dynamic memory allocation while ensuring thread safety and efficient handling of the memory pool. It initializes each record with random values derived from a seed based on both current time and process ID, which helps ensure unique sequences across program executions. Memory pool management reduces frequent allocations and deallocations overhead.

The function checks that requested allocations don't exceed specified maximum size and uses mutex locks for thread-safe operations. Errors are logged to a file, allowing debugging of memory allocation issues under high-load conditions. This approach balances between memory usage efficiency and performance while considering fragmentation impact in long-running processes.']

