#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    float x;
    float y;
} Point;

int compare_points(const void *a, const void *b, void *origin) {
    const Point *p1 = (const Point *)a;
    const Point *p2 = (const Point *)b;
    const Point *orig = (Point *)origin;

    double dist1 = sqrt(pow(p1->x - orig->x, 2) + pow(p1->y - orig->y, 2));
    double dist2 = sqrt(pow(p2->x - orig->x, 2) + pow(p2->y - orig->y, 2));

    return (dist1 > dist2) - (dist1 < dist2);
}

int point_within_radius(const Point *point, const Point *origin, float radius) {
    double distance = sqrt(pow(point->x - origin->x, 2) + pow(point->y - origin->y, 2));
    return distance <= radius;
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

typedef struct {
    double *doubles_array;
    size_t doubles_count;

    Point *points_array;
    size_t points_count;

    char **strings_array;
    size_t strings_count;
} DataStructures;

DataStructures* allocate_data_structures(size_t doubles_size, size_t points_size, size_t strings_size) {
    DataStructures *data = (DataStructures *)malloc(sizeof(DataStructures));
    if (!data) {
        log_error("Memory allocation failed for DataStructures");
        return NULL;
    }

    data->doubles_array = aligned_alloc(64, doubles_size * sizeof(double));
    if (!data->doubles_array) {
        free(data);
        log_error("Memory allocation failed for doubles_array");
        return NULL;
    }
    memset(data->doubles_array, 0, doubles_size * sizeof(double));

    data->points_array = aligned_alloc(64, points_size * sizeof(Point));
    if (!data->points_array) {
        free_aligned(data->doubles_array);
        free(data);
        log_error("Memory allocation failed for points_array");
        return NULL;
    }
    memset(data->points_array, 0, points_size * sizeof(Point));

    data->strings_array = (char **)aligned_alloc(64, strings_size * sizeof(char *));
    if (!data->strings_array) {
        free_aligned(data->doubles_array);
        free_aligned(data->points_array);
        free(data);
        log_error("Memory allocation failed for strings_array");
        return NULL;
    }
    for (size_t i = 0; i < strings_size; ++i) {
        data->strings_array[i] = aligned_alloc(64, 256 * sizeof(char));
        if (!data->strings_array[i]) {
            for (size_t j = 0; j <= i; ++j)
                free_aligned(data->strings_array[j]);
            free_aligned(data->strings_array);
            free_aligned(data->points_array);
            free_aligned(data->doubles_array);
            free(data);
            log_error("Memory allocation failed for strings_array element");
            return NULL;
        }
        memset(data->strings_array[i], 0, 256 * sizeof(char));
    }

    data->doubles_count = doubles_size;
    data->points_count = points_size;
    data->strings_count = strings_size;

    return data;
}

void deallocate_data_structures(DataStructures *data) {
    if (!data) return;

    for (size_t i = 0; i < data->strings_count; ++i)
        free_aligned(data->strings_array[i]);
    free_aligned(data->strings_array);
    free_aligned(data->points_array);
    free_aligned(data->doubles_array);
    free(data);
}

void sort_points_by_distance(DataStructures *data, Point origin) {
    if (data && data->points_count > 0)
        qsort_r(data->points_array, data->points_count, sizeof(Point), compare_points, &origin);
}

int search_points_within_radius(DataStructures *data, Point origin, float radius) {
    int count = 0;
    if (data && data->points_count > 0) {
        for (size_t i = 0; i < data->points_count; ++i) {
            if (point_within_radius(&data->points_array[i], &origin, radius)) {
                count++;
            }
        }
    }
    return count;
}
