    float value;
} data_entry;

#define HASH_TABLE_SIZE 1024

data_entry* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_locks[HASH_TABLE_SIZE];

// Hash function for simplicity, improve as needed
unsigned int hash(time_t timestamp) {
    return (unsigned int)(timestamp % HASH_TABLE_SIZE);
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_locks[i], NULL);
    }
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        data_entry* entry = hash_table[i];
        while (entry) {
            data_entry* to_free = entry;
            entry = entry->next;
            free(to_free);
        }
        pthread_mutex_destroy(&hash_locks[i]);
    }
}

void insert_into_hash_table(time_t timestamp, float value) {
    unsigned int index = hash(timestamp);
    pthread_mutex_lock(&hash_locks[index]);

    data_entry* new_entry = malloc(sizeof(data_entry));
    if (new_entry) {
        new_entry->timestamp = timestamp;
        new_entry->value = value;
        new_entry->next = hash_table[index];
        hash_table[index] = new_entry;
    }

    pthread_mutex_unlock(&hash_locks[index]);
}

void* manage_data(void* arg) {
    int num_readings = *((int*)arg);

    // Allocate and initialize temperature array
    double* temperatures = aligned_alloc(64, sizeof(double) * num_readings);
    if (!temperatures) return NULL;

    // Allocate and initialize status codes
    char* statuses = (char*)aligned_alloc(64, sizeof(char) * num_readings);
    if (!statuses) {
        free(temperatures);
        return NULL;
    }

    // Initialize linked list for measurements
    measurement* head = NULL;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (int i = 0; i < num_readings; ++i) {
        measurement* new_node = malloc(sizeof(measurement));
        if (!new_node) {
            free(temperatures);
            free(statuses);
            return NULL;
        }

        pthread_mutex_init(&new_node->lock, &attr);
        new_node->temperature = 0.0;
        new_node->next = head;
        head = new_node;
    }

    // Initialize hash table
    init_hash_table();

    // Placeholder for sensor integration and logging setup (not implemented)

    pthread_mutexattr_destroy(&attr);

    // Return allocated structures in a struct (for demonstration purposes)
    typedef struct {
        double* temperatures;
        char* statuses;
        measurement* head_measurements;
    } managed_data;

    managed_data* data = malloc(sizeof(managed_data));
    if (!data) {
        free(temperatures);
        free(statuses);
        return NULL;
    }

    data->temperatures = temperatures;
    data->statuses = statuses;
    data->head_measurements = head;

    return (void*)data;
}

void cleanup_managed_data(void* managed_ptr) {
    if (!managed_ptr) return;

    managed_data* data = (managed_data*)managed_ptr;

    free(data->temperatures);
    free(data->statuses);

    measurement* current = data->head_measurements;
    while (current) {
        measurement* to_free = current;
        current = current->next;
        pthread_mutex_destroy(&to_free->lock);
        free(to_free);
    }

    free_hash_table();
    free(data);
}
