async fn initializeAndManageRecords(num_records: usize, value_range: (i32, i32)) -> Result<(), Box<dyn std::error::Error>> {
    let pool = MemoryPool::new();
    let records = Arc::new(Mutex::new(Vec::with_capacity(num_records)));

    // Initialize the dynamic array of records
    {
        let mut rng = thread_rng();
        for _ in 0..num_records {
            let record = Record {
                value: rng.gen_range(value_range.0..=value_range.1),
                offset_ptr: pool.allocate::<u64>().unwrap_or(std::ptr::null_mut()),
                key_ptr: pool.allocate::<i32>().unwrap_or(std::ptr::null_mut()),
                timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos(),
                status: "initialized".to_string(),
            };
            records.lock().unwrap().push(record);
        }
    }

    // Periodically release unused memory
    thread::spawn(move || loop {
        pool.release_unused();
        std::thread::sleep(std::time::Duration::from_secs(60));
    });

    // Read integers from standard input and find the largest
    let stdin = io::stdin();
    let numbers: Vec<i32> = stdin.lock().lines()
        .filter_map(|line| line.ok()?.parse::<i32>().ok())
        .collect();

    if !numbers.is_empty() {
        let max_value = find_largest(&numbers);
        println!("Largest value: {}", max_value);
