```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_ENTRIES 1000000
#define PAYLOAD_MAX_SIZE 256
#define COMPACT_THRESHOLD_PAYLOAD_SIZE (500 * 1024)
#define ENTRY_COMPACT_THRESHOLD_COUNT 10000

typedef enum { INSERT, UPDATE, DELETE } OperationType;

typedef struct LogEntry {
    time_t timestamp;
    OperationType op_type;
    char key[64];
    char payload[PAYLOAD_MAX_SIZE];
    int version;
    struct LogEntry* next;
} LogEntry;

typedef struct {
    LogEntry* head;
    LogEntry* tail;
    size_t count;
    size_t total_payload_size;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
} LogQueue;

LogQueue log_queue = {NULL, NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

// Lock-free queue functions
void enqueue(LogEntry* entry);
LogEntry* dequeue();

// Producer function to submit entries
void* producer(void* arg) {
    // Example data for demonstration; replace with actual logic.
    char key[64] = "example_key";
    char payload[PAYLOAD_MAX_SIZE] = "example_payload";

    while (1) {  // Replace with actual condition.
        LogEntry* entry = malloc(sizeof(LogEntry));
        if (!entry) {
            perror("Failed to allocate memory for log entry");
            continue;
        }

        entry->timestamp = time(NULL);
        entry->op_type = INSERT;  // Example operation type
        strncpy(entry->key, key, sizeof(entry->key) - 1);
        snprintf(entry->payload, sizeof(entry->payload), "%s", payload); 
        entry->version = rand() % 1000;  // Example version number

        enqueue(entry);

        pthread_mutex_lock(&log_queue.lock);
        log_queue.count++;
        log_queue.total_payload_size += strlen(entry->payload) + 1;
        if (log_queue.count >= ENTRY_COMPACT_THRESHOLD_COUNT ||
            log_queue.total_payload_size > COMPACT_THRESHOLD_PAYLOAD_SIZE) {
            // Trigger compaction
            compact_log();
        }
        pthread_mutex_unlock(&log_queue.lock);
    }

    return NULL;
}

// Consumer function to process entries asynchronously
void* consumer(void* arg) {
    while (1) {  // Replace with actual condition.
        LogEntry* entry = dequeue();
        if (!entry) continue;

        // Process the log entry; example processing below:
        printf("Processing: %s, Version: %d\n", entry->key, entry->version);

        free(entry);
    }

    return NULL;
}

// Compaction logic
void compact_log() {
    pthread_mutex_lock(&log_queue.lock);

    LogEntry* current = log_queue.head;
    size_t new_payload_size = 0;

    while (current) {
        // Example compaction: remove entries older than some time or specific criteria.
        if (/* condition to keep the entry */) {
            new_payload_size += strlen(current->payload) + 1;
            current = current->next;
        } else {
            LogEntry* old_entry = current;
            current = current->next;
            free(old_entry);
            log_queue.count--;
        }
    }

    log_queue.total_payload_size = new_payload_size;

    pthread_mutex_unlock(&log_queue.lock);
}

// Lock-free queue implementations
void enqueue(LogEntry* entry) {
    // Example lock-free implementation; replace with actual logic.
    pthread_mutex_lock(&log_queue.lock);

    if (!log_queue.tail) {
        log_queue.head = log_queue.tail = entry;
    } else {
        log_queue.tail->next = entry;
        log_queue.tail = entry;
    }

    pthread_cond_signal(&log_queue.not_empty);
    pthread_mutex_unlock(&log_queue.lock);
}

LogEntry* dequeue() {
    LogEntry* result;

    pthread_mutex_lock(&log_queue.lock);

    while (!log_queue.head) {
        pthread_cond_wait(&log_queue.not_empty, &log_queue.lock);
    }

    result = log_queue.head;
    log_queue.head = log_queue.head->next;
    if (!log_queue.head)
        log_queue.tail = NULL;

    pthread_mutex_unlock(&log_queue.lock);

    return result;
}

int main() {
    // Example setup
    pthread_t prod_thread, cons_thread;
    pthread_create(&prod_thread, NULL, producer, NULL);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    return 0;
}
