#define RANDOM_STRING_MIN_LENGTH 16
#define RANDOM_STRING_MAX_LENGTH 32

typedef struct {
    int value;
    long *offset;
    int key;
} record;

pthread_mutex_t token_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t record_rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Simulated database for issued tokens
char **issued_tokens_db;
int issued_tokens_count = 0;

// Record array management variables
record *records_array;
size_t records_size;
const int value_min = 1;
const int value_max = 100;

bool validate_email_format(const char *email) {
    // Basic validation rules: presence of '@' and '.' in correct order, length check.
    if (strlen(email) > MAX_EMAIL_LENGTH || strcspn(email, "@.") == strlen(email)) return false;

    const char *at_ptr = strchr(email, '@');
    if (!at_ptr) return false;

    const char *dot_ptr = strrchr(at_ptr + 1, '.');
    return dot_ptr && (dot_ptr - at_ptr > 0);
}

char *generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *random_str = malloc(length + 1);
    if (!random_str) return NULL;

    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_str[length] = '\0';

    return random_str;
}

char *generate_checksum(const char *input) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *) input, strlen(input), hash);

    static char buffer[65]; // enough for base64 representation
    static const char base64_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    int i;
    for (i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        buffer[i * 2] = base64_chars[(hash[i] >> 4) & 0x3F];
        buffer[i * 2 + 1] = base64_chars[hash[i] & 0x3F];
    }
    buffer[SHA256_DIGEST_LENGTH * 2] = '\0';

    return strndup(buffer, SHA256_DIGEST_LENGTH * 2);
}

bool is_token_unique(const char *token) {
    pthread_mutex_lock(&token_lock);

    for (int i = 0; i < issued_tokens_count; ++i) {
        if (strcmp(issued_tokens_db[i], token) == 0) {
            pthread_mutex_unlock(&token_lock);
            return false;
        }
    }

    // Add the new unique token to the database
    issued_tokens_db[issued_tokens_count++] = strdup(token);

    pthread_mutex_unlock(&token_lock);
    return true;
}

char *generate_unique_token(const char *email) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y%m%d%H%M%S", tm_info);

    size_t random_string_length = rand() % (RANDOM_STRING_MAX_LENGTH - RANDOM_STRING_MIN_LENGTH + 1) + RANDOM_STRING_MIN_LENGTH;
    char *random_str = generate_random_string(random_string_length);

    if (!random_str) {
        return NULL; // Handle memory allocation failure
    }

    char email_timestamp[2*MAX_EMAIL_LENGTH+20];
    snprintf(email_timestamp, sizeof(email_timestamp), "%s%s", email, timestamp_str);

    char *checksum = generate_checksum(email_timestamp);

    char token[TOKEN_MAX_LENGTH + 1];
    int suffix_index = 0;

    do {
        snprintf(token, TOKEN_MAX_LENGTH, "%s%s%s_%d", email, timestamp_str, random_str, ++suffix_index);

        if (strlen(token) > TOKEN_MAX_LENGTH) {
            free(random_str);
            free(checksum);
            return NULL;
        }
    } while (!is_token_unique(token));

    char *final_token = strdup(token);

    free(random_str);
    free(checksum);

    return final_token;
}

void *manage_records(size_t initial_size, size_t value_range) {
    pthread_rwlock_wrlock(&record_rwlock);
    records_array = malloc(sizeof(record) * initial_size);
    if (!records_array) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_size; ++i) {
        records_array[i].value = rand() % value_range + value_min;
        records_array[i].offset = malloc(sizeof(long));
        if (!records_array[i].offset) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }
        *records_array[i].offset = i;
        records_array[i].key = i;
    }

    pthread_rwlock_unlock(&record_rwlock);
    return NULL;
}

void *retrieve_record(size_t index) {
    pthread_rwlock_rdlock(&record_rwlock);
    if (index >= records_size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_rwlock_unlock(&record_rwlock);
        return NULL;
    }

    record *result = malloc(sizeof(record));
    if (!result) {
        fprintf(stderr, "Memory allocation failure\n");
        pthread_rwlock_unlock(&record_rwlock);
        exit(EXIT_FAILURE);
    }

    memcpy(result, &records_array[index], sizeof(record));

    pthread_rwlock_unlock(&record_rwlock);
    return result;
}

int find_max_value(void (*callback)(size_t index, record *rec)) {
    int max_value = value_min - 1;

    pthread_rwlock_rdlock(&record_rwlock);

    for (size_t i = 0; i < records_size; ++i) {
        callback(i, &records_array[i]);
        if (records_array[i].value > max_value) {
            max_value = records_array[i].value;
        }
    }

    pthread_rwlock_unlock(&record_rwlock);
    return max_value;
}

