['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    TEXT,
    IMAGE,
    VIDEO
} MessageType;

typedef struct {
    int sender_id;
    int recipient_id;
    MessageType message_type;
    char *payload;
    size_t payload_size;
    time_t timestamp;
    int version_number;
} QueueEntry;

typedef struct {
    QueueEntry **entries;
    size_t entry_count;
    size_t total_payload_chars;
    pthread_mutex_t lock; // For simplicity, using a mutex for thread safety
} MessageQueue;

#define MAX_PAYLOAD_SIZE 256
#define PAYLOAD_RANGE_MIN 10
#define PAYLOAD_RANGE_MAX 100

// Function prototypes
MessageQueue* create_message_queue(size_t entry_count);
void free_message_queue(MessageQueue *queue);
int add_entry(MessageQueue *queue, int sender_id, int recipient_id, MessageType message_type, const char *payload, size_t payload_size);
void iterate_over_entries(const MessageQueue *queue);
void compact_queue(MessageQueue *queue);

// Helper function to generate a random payload
char* generate_random_payload(size_t length) {
    if (length == 0) return NULL;

    char *payload = malloc(length + 1);
    if (!payload) return NULL;

    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()";
    size_t max_index = sizeof(charset) - 1;

    for (size_t i = 0; i < length; i++) {
        payload[i] = charset[rand() % max_index];
    }
    payload[length] = '\0';

    return payload;
}

MessageQueue* create_message_queue(size_t entry_count) {
    MessageQueue *queue = malloc(sizeof(MessageQueue));
    if (!queue) return NULL;

    queue->entries = calloc(entry_count, sizeof(QueueEntry *));
    if (!queue->entries) {
        free(queue);
        return NULL;
    }

    queue->entry_count = entry_count;
    queue->total_payload_chars = 0;

    pthread_mutex_init(&queue->lock, NULL);

    srand(time(NULL));

    for (size_t i = 0; i < entry_count; ++i) {
        size_t payload_size = PAYLOAD_RANGE_MIN + rand() % (PAYLOAD_RANGE_MAX - PAYLOAD_RANGE_MIN + 1);
        char *payload = generate_random_payload(payload_size);

        if (!payload) continue;

        QueueEntry *entry = malloc(sizeof(QueueEntry));
        if (!entry) {
            free(payload);
            continue;
        }

        entry->sender_id = rand() % 1000; // Example sender ID
        entry->recipient_id = rand() % 1000; // Example recipient ID
        entry->message_type = MessageType(rand() % 3); // Random message type
        entry->payload = payload;
        entry->payload_size = payload_size;
        entry->timestamp = time(NULL);
        entry->version_number = 1;

        pthread_mutex_lock(&queue->lock);
        queue->entries[i] = entry;
        queue->total_payload_chars += payload_size;
        pthread_mutex_unlock(&queue->lock);
    }

    return queue;
}

void free_message_queue(MessageQueue *queue) {
    if (!queue) return;

    for (size_t i = 0; i < queue->entry_count; ++i) {
        if (queue->entries[i]) {
            free(queue->entries[i]->payload);
            free(queue->entries[i]);
        }
    }

    free(queue->entries);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int add_entry(MessageQueue *queue, int sender_id, int recipient_id, MessageType message_type, const char *payload, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE || !payload) return -1;

    QueueEntry *entry = malloc(sizeof(QueueEntry));
    if (!entry) return -1;

    entry->sender_id = sender_id;
    entry->recipient_id = recipient_id;
    entry->message_type = message_type;
    entry->payload = strdup(payload);
    entry->payload_size = payload_size;
    entry->timestamp = time(NULL);
    entry->version_number = 1; // Initialize version number

    pthread_mutex_lock(&queue->lock);
    for (size_t i = 0; i < queue->entry_count; ++i) {
        if (!queue->entries[i]) { // Find an empty slot
            queue->entries[i] = entry;
            queue->total_payload_chars += payload_size;
            break;
        }
    }
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

void iterate_over_entries(const MessageQueue *queue) {
    if (!queue) return;

    for (size_t i = 0; i < queue->entry_count; ++i) {
        if (queue->entries[i]) {
            printf("Sender ID: %d, Recipient ID: %d, Type: %d, Payload Size: %zu, Timestamp: %ld, Version: %d\n",
                   queue->entries[i]->sender_id,
                   queue->entries[i]->recipient_id,
                   queue->entries[i]->message_type,
                   queue->entries[i]->payload_size,
                   queue->entries[i]->timestamp,
                   queue->entries[i]->version_number);
        }
    }
}

void compact_queue(MessageQueue *queue) {
    if (!queue) return;

    size_t new_count = 0;
    pthread_mutex_lock(&queue->lock);

    for (size_t i = 0; i < queue->entry_count; ++i) {
        if (queue->entries[i]) {
            queue->entries[new_count] = queue->entries[i];
            new_count++;
        } else {
            free(queue->entries[i]->payload);
            free(queue->entries[i]);
        }
    }

    queue->total_payload_chars = 0;
    for (size_t i = 0; i < new_count; ++i) {
        queue->total_payload_chars += queue->entries[i]->payload_size;
    }

    pthread_mutex_unlock(&queue->lock);
}

int main() {
    size_t entry_count = 1000;
    MessageQueue *queue = create_message_queue(entry_count);

    if (!queue) {
        fprintf(stderr, "Failed to create message queue\n");
        return EXIT_FAILURE;
    }

    iterate_over_entries(queue);
    compact_queue(queue);
    free_message_queue(queue);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a distributed message queue system with dynamic memory allocation and thread safety using mutex locks. It initializes the queue with random payloads, supports adding new entries, iterating over them, and compaction to remove outdated entries. The `main` function demonstrates creating, using, and cleaning up the queue. Adjustments may be needed for specific concurrency requirements or performance optimizations.']

