        records[i].value = minRange + rand() % (maxRange - minRange + 1);

        if (i > 0 && records[i].value == records[i - 1].value) {
            --i; // Regenerate the value to ensure no two consecutive values are the same
            continue;
        }

        records[i].offsetPtr = &offsets[i];
        records[i].keyPtr = &keys[i];
        records[i].accessCount = 0;

        logOperation("Record initialized");
