        // Cleanup
        free(offsets);
        free(keys);
        free(records);

        fclose(logFile);
        return;
    }

    size_t length = 0;
    int value;

    printf("Enter integers (end with a non-integer input):\n");
    while (scanf("%d", &value) == 1) {
        if (length >= capacity) { // Resize array if needed
            capacity *= 2;
            inputArray = (int *)realloc(inputArray, capacity * sizeof(int));
            if (!inputArray) {
                fprintf(stderr, "Memory reallocation failed\n");
                logOperation("Memory reallocation failure - Input Array");

                // Cleanup
                free(offsets);
                free(keys);
                free(records);

                fclose(logFile);
                return;
            }
        }

        inputArray[length++] = value;
    }

    // Reset the stdin stream after reading numbers
    int c;
    while ((c = getchar()) != '\n' && c != EOF) { /* discard */ }

    if (length > 0) {
        int maxVal = findMaxInArray(inputArray, length);
        printf("Largest integer: %d\n", maxVal);
    } else {
        printf("No integers were entered.\n");
    }

    // Free allocated resources
    free(offsets);
    free(keys);
    free(records);
    free(inputArray);

    // Close the log file
    fclose(logFile);
}

int findMaxInArray(const int *array, size_t length) {
    if (length == 0) return INT_MIN;

    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    logOperation("Max value found");
    return max;
}

void logOperation(const char *operation) {
    if (logFile) {
        fprintf(logFile, "%s\n", operation);
        fflush(logFile); // Ensure the log is written immediately
    }
}
