    long data;
} Element;

#define INITIAL_TABLE_SIZE 1024

// Hash Table Node
typedef struct node {
    Element *element;
    struct node *next;
} Node;

// Lock-free hash table structure with concurrency support using atomic operations.
typedef struct {
    Node **buckets;
    size_t size;
} ConcurrentHashMap;

// Function prototypes
void initializeAndManageRecords(const char *filename);
ConcurrentHashMap* createHashTable(size_t size);
unsigned int hashFunction(char key, size_t size);
int insertElement(ConcurrentHashMap *table, Element *element);
Element* getElement(ConcurrentHashMap *table, char key);
