void initializeAndManageRecords(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    long offsetCount = 0;
    int keyCount = 0;
    Element **elementsCount = 0;

    // Read the first line to count the number of records
    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        if (*line == '\n') continue; // Skip empty lines
        offsetCount++;
        keyCount++; // Assuming well-formed CSV
        elementsCount++;
    }
    free(line);

    rewind(file); // Reset the file pointer for actual reading

    long *offsets = malloc(offsetCount * sizeof(long));
    int *keys = malloc(keyCount * sizeof(int));
    Element **elements = malloc(elementsCount * sizeof(Element*));

    if (!offsets || !keys || !elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < offsetCount; ++i) {
        if (fscanf(file, "%ld,%d,%hhd", &offsets[i], &keys[i], &((Element*)elements[i])->key) != 3) {
            fprintf(stderr, "Error reading data from file\n");
            free(offsets);
            free(keys);
            free(elements);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        elements[i] = malloc(sizeof(Element));
        if (!elements[i]) {
            fprintf(stderr, "Memory allocation failed for element\n");
            free(offsets);
            free(keys);
            free(elements);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        elements[i]->data = offsets[i]; // Assuming offset is the long data
    }

    ConcurrentHashMap *hashTable = createHashTable(INITIAL_TABLE_SIZE);

    for (size_t i = 0; i < elementsCount; ++i) {
        if (!insertElement(hashTable, elements[i])) {
            fprintf(stderr, "Error inserting element into hash table\n");
            // Cleanup code omitted for brevity
            exit(EXIT_FAILURE);
        }
    }

    int arrSize;
    printf("Enter the number of integers: ");
    scanf("%d", &arrSize);

    int *intArray = malloc(arrSize * sizeof(int));
    if (!intArray) {
        fprintf(stderr, "Memory allocation failed for integer array\n");
        // Cleanup code omitted for brevity
        exit(EXIT_FAILURE);
    }

    printf("Enter the integers: ");
    for (int i = 0; i < arrSize; ++i) {
        scanf("%d", &intArray[i]);
    }

    long largestInteger = findLargestInteger(intArray, arrSize);
    printf("The largest integer is: %ld\n", largestInteger);

    // Cleanup
    free(offsets);
    free(keys);
    for (size_t i = 0; i < elementsCount; ++i) {
        free(elements[i]);
    }
    free(elements);
    free(intArray);

    fclose(file);
}

ConcurrentHashMap* createHashTable(size_t size) {
    ConcurrentHashMap *table = malloc(sizeof(ConcurrentHashMap));
    if (!table) return NULL;

    table->size = size;
    table->buckets = calloc(table->size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

unsigned int hashFunction(char key, size_t size) {
    return (unsigned int)key % size;
}

int insertElement(ConcurrentHashMap *table, Element *element) {
    unsigned int index = hashFunction(element->key, table->size);
    Node *newNode = malloc(sizeof(Node));
    if (!newNode) return 0;

    newNode->element = element;
    newNode->next = NULL;

    Node **bucket = &table->buckets[index];
    while (*bucket != NULL) {
        if ((*bucket)->element->key == element->key) {
            free(newNode);
            return 0; // Duplicate key
        }
        bucket = &(*bucket)->next;
    }

    newNode->next = *bucket;
    *bucket = newNode;

    return 1;
}

Element* getElement(ConcurrentHashMap *table, char key) {
    unsigned int index = hashFunction(key, table->size);
    Node *node = table->buckets[index];
    while (node != NULL) {
        if (node->element->key == key) {
            return node->element;
        }
        node = node->next;
    }
    return NULL;
}

// Test the function with a CSV file containing 10 million rows
int main() {
    initializeAndManageRecords("data.csv");

    // Additional tests for concurrency can be implemented here

    return 0;
}
