#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>

#define MAX_CONCURRENCY 5
#define DEFAULT_PLACEHOLDER_SIZE 64

typedef struct {
    char *name;
    char *description;
    char *image_path;
} Theme;

typedef struct {
    Theme **themes;
    size_t count;
    pthread_mutex_t lock;
} Cache;

typedef struct {
    char *config_file;
    char *default_theme_dir;
    int verbosity;
} Options;

void log_message(int verbosity, const char *message) {
    if (verbosity > 0) {
        printf("%s\n", message);
    }
}

int file_exists(const char *path) {
    return access(path, F_OK) != -1;
}

char *generate_placeholder_image(const char *theme_name) {
    size_t len = strlen(theme_name);
    char *placeholder = (char *)malloc(DEFAULT_PLACEHOLDER_SIZE * DEFAULT_PLACEHOLDER_SIZE + 1);
    memset(placeholder, 0, DEFAULT_PLACEHOLDER_SIZE * DEFAULT_PLACEHOLDER_SIZE + 1);

    for (size_t i = 0; i < DEFAULT_PLACEHOLDER_SIZE && i < len; ++i) {
        placeholder[i] = theme_name[i % len];
    }

    return placeholder;
}

void process_theme(Theme *theme) {
    if (!file_exists(theme->image_path)) {
        log_message(1, "Image file missing for theme: ");
        free(theme->image_path);
        theme->image_path = generate_placeholder_image(theme->name);
        log_message(1, "Generated placeholder image.");
    }
}

void *process_theme_thread(void *arg) {
    Theme *theme = (Theme *)arg;
    process_theme(theme);
    return NULL;
}

int load_config(const char *config_file, Theme ***themes, size_t *count) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open config file");
        return -1;
    }

    char line[256];
    *count = 0;
    while (fgets(line, sizeof(line), file)) {
        (*count)++;
    }
    rewind(file);

    *themes = (Theme **)malloc(*count * sizeof(Theme *));
    for (size_t i = 0; i < *count; ++i) {
        (*themes)[i] = malloc(sizeof(Theme));
        if (!fgets(line, sizeof(line), file)) break;

        char name[128], desc[256], path[512];
        sscanf(line, "%[^,],%[^,],%[^\n]", name, desc, path);

        (*themes)[i]->name = strdup(name);
        (*themes)[i]->description = strdup(desc);
        (*themes)[i]->image_path = strdup(path);
    }

    fclose(file);
    return 0;
}

void free_theme(Theme *theme) {
    free(theme->name);
    free(theme->description);
    free(theme->image_path);
    free(theme);
}

void free_cache(Cache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free_theme(cache->themes[i]);
    }
    free(cache->themes);
    pthread_mutex_destroy(&cache->lock);
}

int ensure_directory_exists(const char *dir_path) {
    struct stat st;
    if (stat(dir_path, &st) == 0 && S_ISDIR(st.st_mode)) {
        return 1;
    }

    if (mkdir(dir_path, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create directory");
        return -1;
    }
    return 1;
}

void process_themes(Theme **themes, size_t count, Options options) {
    Cache cache = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    pthread_t threads[MAX_CONCURRENCY];
    int active_threads = 0;

    for (size_t i = 0; i < count; ++i) {
        if (!file_exists(themes[i]->image_path)) {
            log_message(options.verbosity, "Processing theme: ");
            log_message(options.verbosity, themes[i]->name);

            pthread_mutex_lock(&cache.lock);
            cache.themes[cache.count++] = themes[i];
            pthread_mutex_unlock(&cache.lock);

            while (active_threads >= MAX_CONCURRENCY) {
                for (int j = 0; j < active_threads; ++j) {
                    if (pthread_tryjoin_np(threads[j], NULL) == 0) {
                        --active_threads;
                        break;
                    }
                }
            }

            pthread_create(&threads[active_threads++], NULL, process_theme_thread, themes[i]);
        } else {
            log_message(options.verbosity, "Theme already processed: ");
            log_message(options.verbosity, themes[i]->name);
        }
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_cache(&cache);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file> <default_theme_dir>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Options options = {argv[1], argv[2], 1};

    if (ensure_directory_exists(options.default_theme_dir) != 1) {
        return EXIT_FAILURE;
    }

    Theme **themes;
    size_t theme_count;

    if (load_config(options.config_file, &themes, &theme_count) != 0) {
        return EXIT_FAILURE;
    }

    process_themes(themes, theme_count, options);

    free(themes);
    return EXIT_SUCCESS;
}
