```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure definition
typedef struct Record {
    short value;
    long *offset;
    int *key;
    unsigned int id; // Unique identifier
} Record;

// Collection structure
typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    FILE *log_file;
} RecordCollection;

// Function prototypes
RecordCollection* create_collection(size_t initial_capacity);
void destroy_collection(RecordCollection *collection);
int add_record(RecordCollection *collection, short value, long offset, int key, unsigned int id);
int update_record(RecordCollection *collection, size_t index, short value, long offset, int key);
int remove_record(RecordCollection *collection, size_t index);
void serialize_collection(const RecordCollection *collection, const char *filename);
RecordCollection* deserialize_collection(const char *filename);
void log_memory_usage(RecordCollection *collection);

// Create collection with initial capacity
RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;

    // Open a log file
    collection->log_file = fopen("memory_log.txt", "a");
    if (!collection->log_file) {
        free(collection->records);
        free(collection);
        return NULL;
    }
    return collection;
}

// Destroy the collection
void destroy_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }
    free(collection->records);

    if (collection->log_file) fclose(collection->log_file);
    free(collection);
}

// Add a new record
int add_record(RecordCollection *collection, short value, long offset, int key, unsigned int id) {
    if (!collection || collection->size >= collection->capacity) return -1;

    // Resize array if necessary
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) return -1;

        memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(Record *));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) return -1;

    record->value = value;
    record->offset = malloc(sizeof(long));
    record->key = malloc(sizeof(int));
    if (!record->offset || !record->key) {
        free(record);
        return -1;
    }

    *record->offset = offset;
    *record->key = key;
    record->id = id;

    collection->records[collection->size++] = record;

    log_memory_usage(collection); // Log memory usage

    return 0;
}

// Update an existing record by index
int update_record(RecordCollection *collection, size_t index, short value, long offset, int key) {
    if (!collection || index >= collection->size) return -1;

    Record *record = collection->records[index];
    if (!record) return -1;

    record->value = value;
    *record->offset = offset;
    *record->key = key;

    log_memory_usage(collection); // Log memory usage

    return 0;
}

// Remove a record by index
int remove_record(RecordCollection *collection, size_t index) {
    if (!collection || index >= collection->size) return -1;

    Record *record = collection->records[index];
    free(record->offset);
    free(record->key);
    free(record);

    memmove(&collection->records[index], &collection->records[index + 1],
            (collection->size - index - 1) * sizeof(Record *));
    collection->size--;

    log_memory_usage(collection); // Log memory usage

    return 0;
}

// Serialize the collection to a binary file
void serialize_collection(const RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&collection->capacity, sizeof(size_t), 1, file);
    fwrite(&collection->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->size; ++i) {
        Record *record = collection->records[i];
        if (!record) continue;

        fwrite(&record->value, sizeof(short), 1, file);
        fwrite(record->offset, sizeof(long), 1, file);
        fwrite(record->key, sizeof(int), 1, file);
        fwrite(&record->id, sizeof(unsigned int), 1, file);
    }

    fclose(file);
}

// Deserialize the collection from a binary file
RecordCollection* deserialize_collection(const char *filename) {
    if (!filename) return NULL;

    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    RecordCollection *collection = create_collection(0); // Temporary collection
    if (!collection) {
        fclose(file);
        return NULL;
    }

    size_t capacity, size;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < size; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            destroy_collection(collection);
            fclose(file);
            return NULL;
        }

        record->offset = malloc(sizeof(long));
        record->key = malloc(sizeof(int));

        fread(&record->value, sizeof(short), 1, file);
        fread(record->offset, sizeof(long), 1, file);
        fread(record->key, sizeof(int), 1, file);
        fread(&record->id, sizeof(unsigned int), 1, file);

        if (!collection->records) {
            collection->capacity = size;
            collection->size = size;
            collection->records = calloc(size, sizeof(Record *));
        }

        collection->records[collection->size++] = record;
    }

    fclose(file);
    return collection;
}

// Log memory usage to a file
void log_memory_usage(RecordCollection *collection) {
    if (!collection || !collection->log_file) return;

    fprintf(collection->log_file, "Memory Usage: Size=%zu, Capacity=%zu\n",
            collection->size, collection->capacity);
    fflush(collection->log_file);
}

// Example usage
int main() {
    srand(time(NULL));

    RecordCollection *collection = create_collection(10);
    if (!collection) {
        fprintf(stderr, "Failed to create record collection.\n");
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < 20; ++i) { // Adding more records than initial capacity
        short value = rand() % 100;
        add_record(collection, value, rand(), rand(), i);
    }

    serialize_collection(collection, "records.bin");

    RecordCollection *loaded_collection = deserialize_collection("records.bin");
    if (loaded_collection) {
        destroy_collection(loaded_collection);
    }

    destroy_collection(collection);

    return EXIT_SUCCESS;
}
