Record* createRecords(int num_records, long* step_size, long* base_offset) {
    if (num_records <= 0 || *step_size < 0) return NULL;

    // Allocate memory for records
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    // Initialize hash table size and allocate memory
    int table_size = num_records > 10 ? num_records : 11; // Simple heuristic for initial capacity
    HashNode** hash_table = (HashNode**)calloc(table_size, sizeof(HashNode*));
    if (!hash_table) {
        free(records);
        return NULL;
    }

    long offset_base = *base_offset;

    // Populate records and the hash table
    for (int i = 0; i < num_records; ++i) {
        long calculated_offset = offset_base + (i * (*step_size));

        if ((calculated_offset - offset_base) / *step_size != i) { // Check for overflow
            free(records);
            free(hash_table);
            return NULL;
        }

        records[i].offset = calculated_offset;
        records[i].key = i;

        unsigned int hash_index = hashFunction(i, table_size);

        HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
        if (!newNode) {
            freeMemory(records, &hash_table, table_size);
            return NULL;
        }

        newNode->key = i;
        newNode->offset = calculated_offset;
        newNode->next = hash_table[hash_index];
        hash_table[hash_index] = newNode; // Insert at head for simplicity
    }

    printf("Records and hash table created successfully.\n");

    // Return a structure containing both pointers (as needed)
    struct {
        Record* records;
        HashNode** hash_table;
        int table_size;
    } *result = malloc(sizeof(struct {
        Record* records;
        HashNode** hash_table;
        int table_size;
    }));

    if (!result) {
        freeMemory(records, &hash_table, table_size);
        return NULL;
    }

    result->records = records;
    result->hash_table = hash_table;
    result->table_size = table_size;

    return (Record*)result; // Cast to the expected return type for simplicity
}

void freeMemory(Record* records, HashNode** hash_table, int table_size) {
    if (records) free(records);
    if (hash_table) {
        for (int i = 0; i < table_size; ++i) {
            HashNode* current = hash_table[i];
            while (current) {
                HashNode* temp = current;
                current = current->next;
                free(temp);
            }
        }
        free(hash_table);
    }
}

unsigned int hashFunction(int key, int table_size) {
    return key % table_size; // Simple modulo-based hash
}
