typedef struct {
    long offset;
    int key;
    bool status;
} Record;

typedef struct HashNode {
    int key;
    long offset;
    bool status;
    struct HashNode* next;
} HashNode;

typedef struct {
    size_t size;
    HashNode** buckets;
} HashTable;

#define HASH_TABLE_SIZE 10007

unsigned long hash_function(int key) {
    return (unsigned long)key % HASH_TABLE_SIZE;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = HASH_TABLE_SIZE;
    table->buckets = (HashNode**)calloc(table->size, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

void insert_hash_table(HashTable* table, int key, long offset, bool status) {
    unsigned long index = hash_function(key);
    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) return;

    new_node->key = key;
    new_node->offset = offset;
    new_node->status = status;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
}

bool lookup_hash_table(HashTable* table, int key, long* offset, bool* status) {
    unsigned long index = hash_function(key);
    HashNode* node = table->buckets[index];

    while (node) {
        if (node->key == key) {
            *offset = node->offset;
            *status = node->status;
            return true;
        }
        node = node->next;
    }
    return false;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

Record* create_records(int num_records, long step_size, long base_offset, HashTable** hash_table) {
    if (num_records < 0 || !step_size || !hash_table) return NULL;

    *hash_table = create_hash_table();
    if (!(*hash_table)) return NULL;

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        free_hash_table(*hash_table);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        long calculated_offset = base_offset + (i * step_size);

        // Check for overflow
        if ((base_offset > 0 && calculated_offset < base_offset) || 
            (base_offset < 0 && calculated_offset > base_offset)) {
            fprintf(stderr, "Overflow detected at index %d\n", i);
            continue;
        }

        records[i].offset = calculated_offset;
        records[i].key = i;
        records[i].status = true;

        insert_hash_table(*hash_table, i, calculated_offset, true);
    }
    return records;
}

void free_records(Record* records, HashTable* hash_table) {
    if (records) free(records);
    if (hash_table) free_hash_table(hash_table);
}

int main() {
