#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent transaction details.
typedef struct {
    int id;
    double timestamp;
    char *details;
} Transaction;

// Structure for managing memory pool
typedef struct MemoryPool {
    size_t blockSize;
    void* freeListHead;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void initializeMemoryPool(MemoryPool* pool, size_t blockSize, size_t blockCount);
void* allocateFromPool(MemoryPool* pool);
void deallocateToPool(MemoryPool* pool, void* ptr);
void processTransactionMessage(const char* message, MemoryPool* transactionPool);

// Initialize a memory pool for efficient allocation
void initializeMemoryPool(MemoryPool* pool, size_t blockSize, size_t blockCount) {
    pool->blockSize = blockSize;
    pthread_mutex_init(&pool->lock, NULL);

    // Allocate a large chunk of memory to serve as our memory pool
    char* poolBlock = (char*)malloc(blockSize * blockCount);
    if (!poolBlock) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the free list
    for (size_t i = 0; i < blockCount; ++i) {
        void* blockAddress = poolBlock + i * blockSize;
        *(void**)blockAddress = pool->freeListHead;
        pool->freeListHead = blockAddress;
    }
}

// Allocate memory from the pool
void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    void* allocatedBlock = pool->freeListHead;
    if (allocatedBlock != NULL) {
        pool->freeListHead = *(void**)allocatedBlock;
    }

    pthread_mutex_unlock(&pool->lock);

    return allocatedBlock;
}

// Deallocate memory back to the pool
void deallocateToPool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);

    *(void**)ptr = pool->freeListHead;
    pool->freeListHead = ptr;

    pthread_mutex_unlock(&pool->lock);
}

// Process a transaction message and create transaction objects
void processTransactionMessage(const char* message, MemoryPool* transactionPool) {
    // Simulated parsing logic; real implementation would parse the message stream properly.
    Transaction* transaction = (Transaction*)allocateFromPool(transactionPool);

    if (!transaction) {
        fprintf(stderr, "Failed to allocate memory for a new transaction\n");
