    transaction->id = rand();  // replace with actual parsing logic
    transaction->timestamp = (double)rand() / RAND_MAX;  // replace with actual timestamp

    size_t detailsLength = strlen(message);  // Assuming message contains details
    transaction->details = (char*)malloc(detailsLength + 1);

    if (!transaction->details) {
        fprintf(stderr, "Failed to allocate memory for transaction details\n");
        deallocateToPool(transactionPool, transaction);
        return;
    }

    strcpy(transaction->details, message);  // replace with actual parsing logic

    printf("Processed Transaction ID: %d, Timestamp: %.2f, Details: %s\n",
           transaction->id, transaction->timestamp, transaction->details);

    // Memory cleanup after processing (for illustration)
    free(transaction->details);
    deallocateToPool(transactionPool, transaction);
}

int main() {
    const size_t blockSize = sizeof(Transaction) + 256;  // assuming max string length
    const size_t blockCount = 10000;

    MemoryPool transactionPool;
    initializeMemoryPool(&transactionPool, blockSize, blockCount);

