    } else {
        free_all();
    }
}

int resize_char_array(String **array, size_t new_capacity) {
    String *new_labels = realloc(*array, new_capacity * sizeof(String));
    if (!new_labels) return -1;

    for (size_t i = (*array)[labels_capacity].length; i < new_capacity; ++i) {
        (*array)[i].length = 0;
        (*array)[i].data = NULL;
    }

    *array = new_labels;
    labels_capacity = new_capacity;
    return 0;
}

int resize_data_point_array(data_point **array, size_t new_capacity) {
    data_point *new_datapoints = realloc(*array, new_capacity * sizeof(data_point));
