    pthread_mutex_unlock(&timestamps_mutex);

    pthread_mutex_lock(&labels_mutex);
    for (size_t i = 0; i < labels_capacity; ++i) {
        if (labels[i].data) free(labels[i].data);
    }
    free(labels);
    labels = NULL;
    labels_capacity = 0;
    pthread_mutex_unlock(&labels_mutex);

    pthread_mutex_lock(&datapoints_mutex);
