    if (datapoints_capacity == 0 || datapoints_capacity <= sizeof(datapoints) / sizeof(data_point)) {
        size_t new_capacity = (datapoints_capacity == 0) ? 10 : datapoints_capacity * 2;
        if (resize_data_point_array(&datapoints, new_capacity) != 0) {
            pthread_mutex_unlock(&datapoints_mutex);
            return;
        }
    }

    datapoints[datapoints_capacity++] = new_datapoint;
    LOG("Appended new data point");
    pthread_mutex_unlock(&datapoints_mutex);
}

// Example function to demonstrate thread-safe appending of a string
