    size_t new_length = strlen(new_string);

    pthread_mutex_lock(&labels_mutex);
    if (labels_capacity <= sizeof(labels) / sizeof(String)) {
        size_t new_capacity = labels_capacity == 0 ? 10 : labels_capacity * 2;
        if (resize_char_array(&labels, new_capacity) != 0) {
            pthread_mutex_unlock(&labels_mutex);
            return;
