        snprintf(new_module->name, 20, "Module_%05d", i);
        new_module->resource = malloc(sizeof(resource_t)); // Allocate resource
        if (!new_module->resource) {
            free(new_module->name);
            free(new_module);
            fprintf(stderr, "Memory allocation failed for module resource %d\n", i);
            continue;
        }

        new_module->dependencies = NULL;  // Initialize dependencies list to empty

        modules[i] = new_module;  // Store the module
    }
    pthread_mutex_unlock(&module_mutex);
}

// Function to insert a dependency into a module's linked list
void add_dependency(int index, const char *dependency_name) {
    if (index < 0 || index >= MAX_MODULES) return;

    pthread_mutex_lock(&module_mutex);

    module_t *mod = modules[index];
    if (!mod) {
        fprintf(stderr, "Module at index %d does not exist.\n", index);
        pthread_mutex_unlock(&module_mutex);
        return;
    }

    dependency_t *new_dep = malloc(sizeof(dependency_t));
    if (!new_dep) {
        fprintf(stderr, "Memory allocation failed for new dependency in module %d\n", index);
        pthread_mutex_unlock(&module_mutex);
        return;
    }

    new_dep->name = strdup(dependency_name);  // Allocate and copy the name
    if (!new_dep->name) {
        free(new_dep);
        fprintf(stderr, "Memory allocation failed for dependency name in module %d\n", index);
        pthread_mutex_unlock(&module_mutex);
        return;
    }

    new_dep->next = mod->dependencies;  // Insert at head of the list
    mod->dependencies = new_dep;

    pthread_mutex_unlock(&module_mutex);
}

// Function to retrieve a module by its index
module_t* get_module(int index) {
    if (index < 0 || index >= MAX_MODULES) return NULL;

    pthread_mutex_lock(&module_mutex);
    module_t *mod = modules[index];
    pthread_mutex_unlock(&module_mutex);
    return mod;
}

// Function to iterate over all modules and their dependencies
void iterate_modules(void (*callback)(int, module_t*)) {
    pthread_mutex_lock(&module_mutex);

    for (int i = 0; i < MAX_MODULES; ++i) {
        if (modules[i]) {
            callback(i, modules[i]);
        }
    }

    pthread_mutex_unlock(&module_mutex);
}

// Example usage of iterate_modules
void print_module_and_dependencies(int index, module_t *mod) {
    printf("Module %d: %s\n", index, mod->name);
    dependency_t *dep = mod->dependencies;
    while (dep) {
        printf("\tDependency: %s\n", dep->name);
        dep = dep->next;
    }
}

// Function to clean up allocated memory
void cleanup_modules() {
    pthread_mutex_lock(&module_mutex);

    for (int i = 0; i < MAX_MODULES; ++i) {
        if (!modules[i]) continue;

        free(modules[i]->name);
        free(modules[i]->resource);

        // Free dependencies linked list
        dependency_t *dep = modules[i]->dependencies;
        while (dep) {
            dependency_t *next_dep = dep->next;
            free(dep->name);
            free(dep);
            dep = next_dep;
        }

        free(modules[i]);
    }

    pthread_mutex_unlock(&module_mutex);
}

int main() {
    // Example usage
    init_modules(5);

    add_dependency(0, "Dependency_A");
    add_dependency(0, "Dependency_B");

    iterate_modules(print_module_and_dependencies);

    cleanup_modules();

    return 0;
}
```

This code initializes an array of `module_t` structures with dynamic memory allocation for names and resources. It supports adding dependencies to modules using a linked list and provides functions to retrieve and iterate over the modules and their dependencies, ensuring thread safety using mutexes. Memory is managed carefully to avoid leaks, and error handling is included for allocation failures.']

