#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <tiffio.h>
#include <time.h>

#define MAX_LOG_SIZE 1024

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
} ImageMetadata;

typedef enum {
    SUCCESS,
    FILE_ERROR,
    FORMAT_UNSUPPORTED,
    MEMORY_ERROR,
    UNKNOWN_ERROR
} ErrorCode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *filename, const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("[%s] [%s]: %s\n", timestamp, filename, message);
}

ErrorCode processImage(const char *filename, ImageMetadata *metadata) {
    TIFF* tiff = NULL;
    uint32 width, height;
    int status;

    pthread_mutex_lock(&lock);

    if (NULL == metadata) {
        log_message(filename, "Invalid metadata pointer");
        pthread_mutex_unlock(&lock);
        return MEMORY_ERROR;
    }

    memset(metadata, 0, sizeof(ImageMetadata));

    tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        log_message(filename, "Failed to open file");
        pthread_mutex_unlock(&lock);
        return FILE_ERROR;
    }

    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata->bits_per_sample)) {
        if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata->samples_per_pixel)) {
            uint16 extraSamples = 0;
            if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
                metadata->extra_samples = extraSamples > 1 ? extraSamples : 0;
            }
        } else {
            log_message(filename, "Failed to get samples per pixel");
            status = FORMAT_UNSUPPORTED;
        }
    } else {
        log_message(filename, "Unsupported format or failed to get bits per sample");
        status = FORMAT_UNSUPPORTED;
    }

    if (status == SUCCESS) {
        TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &width);
        TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &height);

        // Stream processing logic could be added here
        // For simplicity, we'll just log the metadata
        char log_buf[MAX_LOG_SIZE];
        snprintf(log_buf, sizeof(log_buf), "Image size: %dx%d", width, height);
        log_message(filename, log_buf);
    }

    if (tiff) {
        TIFFClose(tiff);
    }

    pthread_mutex_unlock(&lock);

    return status;
}

void* test_processImage(void *arg) {
    const char *filename = (const char *)arg;
    ImageMetadata metadata;

    ErrorCode result = processImage(filename, &metadata);
    if (result == SUCCESS) {
        printf("Processed image: %s\n", filename);
    } else {
        fprintf(stderr, "Error processing image: %d\n", result);
    }

    return NULL;
}

int main() {
    const char *test_files[] = {"image1.tiff", "image2.tiff"};
    pthread_t threads[2];

    for (size_t i = 0; i < sizeof(test_files) / sizeof(test_files[0]); ++i) {
        pthread_create(&threads[i], NULL, test_processImage, (void *)test_files[i]);
    }

    for (size_t i = 0; i < sizeof(test_files) / sizeof(test_files[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code provides a `processImage` function that handles TIFF images, extracts metadata, and incorporates thread-safety, logging, and error handling. The main function demonstrates running this in a multi-threaded environment with test cases for different files.']

['Below is an implementation of the described flexible and scalable data management system in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define a record structure
typedef struct {
    short value;
    long offset;
    int key;
} Record;

// Data Management System structure
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} DataManager;

// Function prototypes
DataManager* create_data_manager(size_t initial_capacity);
void destroy_data_manager(DataManager *manager);
int add_record(DataManager *manager, Record record);
int update_record(DataManager *manager, int key, short new_value, long new_offset);
int serialize_to_file(DataManager *manager, const char *filename);
int deserialize_from_file(DataManager *manager, const char *filename);
void log_operation(const DataManager *manager, const char *operation, int status);

// Create a new data manager
DataManager* create_data_manager(size_t initial_capacity) {
    DataManager *manager = (DataManager *)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("operations.log", "a");
    if (!manager->log_file) {
        free(manager->records);
        free(manager);
        return NULL;
    }

    return manager;
}

// Destroy the data manager
void destroy_data_manager(DataManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        fclose(manager->log_file);
        free(manager->records);
        free(manager);
    }
}

// Add a record to the data manager
int add_record(DataManager *manager, Record record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record *new_records = (Record *)realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            log_operation(manager, "add_record", -1);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count++] = record;
    log_operation(manager, "add_record", 0);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update a record in the data manager
int update_record(DataManager *manager, int key, short new_value, long new_offset) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            manager->records[i].value = new_value;
            manager->records[i].offset = new_offset;
            log_operation(manager, "update_record", 0);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    log_operation(manager, "update_record", -1);
    pthread_mutex_unlock(&manager->lock);
    return -1; // Record not found
}

// Serialize records to a binary file
int serialize_to_file(DataManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_operation(manager, "serialize_to_file", -1);
        return -1;
    }

    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->records, sizeof(Record), manager->count, file);
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    log_operation(manager, "serialize_to_file", 0);
    return 0;
}

// Deserialize records from a binary file
int deserialize_from_file(DataManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_operation(manager, "deserialize_from_file", -1);
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    Record *new_records = (Record *)realloc(manager->records, count * sizeof(Record));
    if (!new_records) {
        fclose(file);
        log_operation(manager, "deserialize_from_file", -1);
        return -1;
    }

    manager->records = new_records;
    fread(manager->records, sizeof(Record), count, file);
    manager->count = count;
    manager->capacity = count; // Adjust capacity to match deserialized data

    fclose(file);
    log_operation(manager, "deserialize_from_file", 0);
    return 0;
}

// Log operation details
void log_operation(const DataManager *manager, const char *operation, int status) {
    if (!manager || !manager->log_file) return;

    fprintf(manager->log_file, "{\"timestamp\":\"%ld\", \"operation\":\"%s\", \"status\":%d}\n",
            (long)time(NULL), operation, status);
    fflush(manager->log_file);
}
```

### Key Points:

- **Concurrency**: Uses a mutex to manage concurrent access to the records array.
- **Dynamic Memory Management**: Handles dynamic resizing of the records array using `realloc`.
- **Serialization/Deserialization**: Supports saving and loading data from binary files.
- **Logging**: Logs operations in JSON format with timestamps, operation names, and status codes.
- **Error Handling**: Includes basic error handling for memory allocation failures and file operations.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    short value;
    long *offset;
    int *key;
    unsigned int id;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

void init_random() {
    srand(time(NULL));
}

short random_short(int min, int max) {
    return (short)(min + rand() % ((max - min) + 1));
}

Collection* collection_init(size_t initial_capacity) {
    if (!initial_capacity) initial_capacity = INITIAL_CAPACITY;

    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    init_random();

    return collection;
}

void* collection_alloc(void *ptr) {
    // Simple custom memory pool allocation
    void **pool = (void **) ptr;
    size_t block_size = sizeof(Record);
    if (!(*pool)) {
        *pool = malloc(block_size);
        if (!*pool) return NULL;
    }

    Record *new_block = realloc(*pool, ((*pool) ? ((block_size / sizeof(void*)) + 1) : 1) * (sizeof(void*) + block_size));
    if (!new_block) {
        free(*pool);
        *pool = NULL;
        return NULL;
    }

    void **block_ptr = (void **) new_block + ((*pool) ? ((block_size / sizeof(void*)) + 1) : 1);

    (*pool) = new_block;

    *(block_ptr - 1) = block_ptr; // Store the next free pointer

    for (void **p = block_ptr; p < &new_block[block_size]; ++p)
        *p = NULL;

    return (char *) block_ptr + sizeof(void*);
}

Record* add_record(Collection *collection, unsigned int id) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));

        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return NULL;
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = &collection->records[collection->count++];
    record->value = random_short(0, 100); // Assume range is 0 to 100
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        --collection->count;
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }
    *record->offset = id;  // Placeholder for offset value

    record->key = collection_alloc(collection->records); 
    if (record->key) *record->key = rand();  // Random key as default

    record->id = id;

    pthread_mutex_unlock(&collection->lock);

    return record;
}

void update_record(Collection *collection, size_t index, short value, long offset, int key) {
    if (index >= collection->count) return;

    pthread_mutex_lock(&collection->lock);

    Record *record = &collection->records[index];
    record->value = value;

    free(record->offset);
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    *record->offset = offset;

    // Memory pool is reused; no need to allocate a new key
    if (record->key)
        *record->key = key;

    pthread_mutex_unlock(&collection->lock);
}

void remove_record(Collection *collection, size_t index) {
    if (index >= collection->count) return;

    pthread_mutex_lock(&collection->lock);

    Record *record = &collection->records[index];

    free(record->offset);
    if (record->key)
        record->key = NULL; // Memory pool handles deallocation

    memmove(&collection->records[index], &collection->records[index + 1],
            (--collection->count - index) * sizeof(Record));

    pthread_mutex_unlock(&collection->lock);
}

int save_collection(const Collection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&collection->capacity, sizeof(size_t), 1, file);
    fwrite(&collection->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = &collection->records[i];
        fwrite(record, sizeof(Record), 1, file);

        // Serialize offset and key separately
        long offset = *(record->offset);
        fwrite(&offset, sizeof(long), 1, file);

        if (record->key)
            fwrite(record->key, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

Collection* load_collection(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    Collection *collection = collection_init(0);

    fread(&collection->capacity, sizeof(size_t), 1, file);
    fread(&collection->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->count; ++i) {
        Record record;
        fread(&record, sizeof(Record), 1, file);

        long offset;
        fread(&offset, sizeof(long), 1, file);
        record.offset = malloc(sizeof(long));
        if (!record.offset) break;
        *(record.offset) = offset;

        int *key = collection_alloc(collection->records);
        if (key && record.key != NULL)
            fread(key, sizeof(int), 1, file);

        memcpy(&collection->records[i], &record, sizeof(Record));
    }

    fclose(file);
    return collection;
}

void collection_free(Collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].offset);
        collection->records[i].key = NULL; // Memory pool handles deallocation
    }

    free(collection->records);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void shutdown_collection(Collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    collection_free(collection);

    pthread_mutex_unlock(&collection->lock);
}
```

### Key Considerations:
1. **Concurrency**: The code uses a mutex to ensure thread safety for concurrent access and modification.
2. **Memory Management**: A custom memory pool is implemented, using the `collection_alloc` function to allocate records. This minimizes heap allocations by reusing freed blocks within each collection instance.
3. **Serialization/Deserialization**: Implemented with functions `save_collection` and `load_collection`.
4. **Error Handling**: Handles allocation failures gracefully by returning NULL or cleaning up resources properly.
5. **Dynamic Growth/Shrinkage**: Automatically doubles the capacity when needed, using `realloc`. Shrinking logic can be added similarly based on use case.

This implementation provides a robust foundation for managing dynamic collections with an emphasis on memory efficiency and performance considerations suitable for concurrent operations.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold sensor data
typedef struct {
    time_t timestamp;
    double temperature;
    char* sensor_id;
    double uncertainty;
} SensorData;

// Dynamic data structure to store sensor data entries
typedef struct {
    SensorData** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safe access
} SensorDataSet;

// Function prototypes
SensorDataSet* initialize_sensor_data_set(size_t initial_capacity);
int add_sensor_data(SensorDataSet* set, SensorData* data);
SensorData* get_sensor_data_by_index(const SensorDataSet* set, size_t index);
size_t filter_sensor_data_by_temp_threshold(const SensorDataSet* set, double threshold, SensorData*** filtered_results);

// Implementation
SensorDataSet* initialize_sensor_data_set(size_t initial_capacity) {
    SensorDataSet* set = (SensorDataSet*)malloc(sizeof(SensorDataSet));
    if (!set) return NULL;

    set->entries = (SensorData**)malloc(initial_capacity * sizeof(SensorData*));
    if (!set->entries) {
        free(set);
        return NULL;
    }

    set->capacity = initial_capacity;
    set->size = 0;
    pthread_mutex_init(&set->lock, NULL);

    return set;
}

int add_sensor_data(SensorDataSet* set, SensorData* data) {
    if (!data || data->temperature < -50.0 || data->temperature > 150.0 || 
        data->uncertainty < 0.0 || data->uncertainty > 10.0) {
        return -1; // Invalid data
    }

    pthread_mutex_lock(&set->lock);

    if (set->size >= set->capacity) {
        size_t new_capacity = set->capacity * 2;
        SensorData** new_entries = (SensorData**)realloc(set->entries, new_capacity * sizeof(SensorData*));
        if (!new_entries) {
            pthread_mutex_unlock(&set->lock);
            return -1; // Reallocation failed
        }
        set->entries = new_entries;
        set->capacity = new_capacity;
    }

    set->entries[set->size] = data;
    set->size++;

    pthread_mutex_unlock(&set->lock);
    return 0;
}

SensorData* get_sensor_data_by_index(const SensorDataSet* set, size_t index) {
    if (index >= set->size) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&set->lock);
    SensorData* data = set->entries[index];
    pthread_mutex_unlock((pthread_mutex_t*)&set->lock);

    return data;
}

size_t filter_sensor_data_by_temp_threshold(const SensorDataSet* set, double threshold, SensorData*** filtered_results) {
    size_t count = 0;

    pthread_mutex_lock(&set->lock);
    for (size_t i = 0; i < set->size; ++i) {
        if (set->entries[i]->temperature > threshold) {
            count++;
        }
    }

    *filtered_results = (SensorData**)malloc(count * sizeof(SensorData*));
    size_t j = 0;
    for (size_t i = 0; i < set->size; ++i) {
        if (set->entries[i]->temperature > threshold) {
            (*filtered_results)[j++] = set->entries[i];
        }
    }

    pthread_mutex_unlock(&set->lock);
    return count;
}

// Function to free the dynamic data structure
void free_sensor_data_set(SensorDataSet* set) {
    if (!set) return;

    for (size_t i = 0; i < set->size; ++i) {
        free(set->entries[i]->sensor_id); // Free sensor ID strings
        free(set->entries[i]);            // Free each SensorData entry
    }
    free(set->entries);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

// Example function to read from CSV and initialize data set
int load_sensor_data_from_csv(const char* filename, SensorDataSet* set) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the CSV line into sensor data
        SensorData* data = (SensorData*)malloc(sizeof(SensorData));
        if (!data) continue; // Handle allocation failure

        sscanf(line, "%ld,%lf,%ms,%lf", &data->timestamp, &data->temperature, &data->sensor_id, &data->uncertainty);

        add_sensor_data(set, data);
    }

    fclose(file);
    return 0;
}

// Example function to simulate API call updates
int update_from_api(SensorDataSet* set) {
    // Simulate receiving new sensor data via an API call
    SensorData* new_data = (SensorData*)malloc(sizeof(SensorData));
    if (!new_data) return -1;

    time_t now;
    time(&now);
    new_data->timestamp = now;
    new_data->temperature = 25.0; // Example temperature
    new_data->sensor_id = strdup("API_SENSOR_001"); // Example sensor ID
    new_data->uncertainty = 0.5; // Example uncertainty

    add_sensor_data(set, new_data);
    return 0;
}
