EventDataArray* parseEventLog(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *jsonContent = (char *)malloc(fileSize + 1);
    if (!jsonContent) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    fread(jsonContent, 1, fileSize, file);
    jsonContent[fileSize] = '\0';
    fclose(file);

    json_error_t error;
    json_t *root = json_loads(jsonContent, 0, &error);
    free(jsonContent);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    EventDataArray *eventArray = (EventDataArray *)malloc(sizeof(EventDataArray));
    eventArray->events = NULL;
    eventArray->count = 0;

    size_t capacity = 10; // Initial capacity
    eventData **tempEvents = (eventData **)calloc(capacity, sizeof(eventData *));
    if (!tempEvents) {
        fprintf(stderr, "Memory allocation failed\n");
        json_decref(root);
        free(eventArray);
        return NULL;
    }

    size_t index = 0;

    json_t *eventsJson = json_object_get(root, "events");
    if (json_is_array(eventsJson)) {
        size_t eventCount = json_array_size(eventsJson);

        for (size_t i = 0; i < eventCount; ++i) {
            json_t *eventJson = json_array_get(eventsJson, i);
            if (!json_is_object(eventJson)) continue;

            eventData *newEvent = (eventData *)malloc(sizeof(eventData));
            if (!newEvent) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }

            json_t *timestampJson = json_object_get(eventJson, "timestamp");
            json_t *descriptionJson = json_object_get(eventJson, "description");
            json_t *coordinateJson = json_object_get(eventJson, "coordinate");

            if (!json_is_integer(timestampJson) || !json_is_string(descriptionJson) ||
                !json_is_object(coordinateJson)) {
                free(newEvent);
                continue;
            }

            newEvent->timestamp = (int)json_integer_value(timestampJson);
            const char *desc = json_string_value(descriptionJson);

            // Validate and set description
            size_t descLen = strlen(desc);
            newEvent->description = (char *)malloc(descLen + 1);
            if (!newEvent->description) {
                fprintf(stderr, "Memory allocation failed\n");
                free(newEvent);
                break;
            }
            strcpy(newEvent->description, desc);

            // Validate and set coordinates
            json_t *latJson = json_object_get(coordinateJson, "latitude");
            json_t *lonJson = json_object_get(coordinateJson, "longitude");

            if (!json_is_real(latJson) || !json_is_real(lonJson)) {
                free(newEvent->description);
                free(newEvent);
                continue;
            }

            float latitude = (float)json_number_value(latJson);
            float longitude = (float)json_number_value(lonJson);

            if (latitude < MIN_LATITUDE || latitude > MAX_LATITUDE ||
                longitude < MIN_LONGITUDE || longitude > MAX_LONGITUDE) {
                free(newEvent->description);
                free(newEvent);
                continue;
            }

            newEvent->coordinate.latitude = latitude;
            newEvent->coordinate.longitude = longitude;

            // Resize array if necessary
            if (index >= capacity) {
                capacity *= 2;
                eventData **newTempEvents = (eventData **)realloc(tempEvents, capacity * sizeof(eventData *));
                if (!newTempEvents) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free(newEvent->description);
                    free(newEvent);
                    break;
                }
                tempEvents = newTempEvents;
            }

            tempEvents[index++] = newEvent;
        }
    }

    eventArray->events = tempEvents;
    eventArray->count = index;

    json_decref(root);

    return eventArray;
}

eventData* getEventData(EventDataArray *array, size_t index) {
    if (index >= array->count) return NULL;
    return array->events[index];
}

