#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define SUFFIX_LENGTH 8

typedef struct ChildNode {
    int child_value;
    struct ChildNode *next;
} ChildNode;

typedef struct Node {
    char *name;
    int value;
    ChildNode *children_head;
} Node;

void init_random() {
    srand(time(NULL));
}

char* generate_suffix(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *suffix = malloc(length + 1);
    if (!suffix) return NULL;

    for (int i = 0; i < length; ++i) {
        suffix[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    suffix[length] = '\0';
    return suffix;
}

Node* initialize_nodes(int num_nodes, int prefix_length) {
    Node *nodes = malloc(num_nodes * sizeof(Node));
    if (!nodes) return NULL;

    for (int i = 0; i < num_nodes; ++i) {
        char prefix[prefix_length + 1];
        snprintf(prefix, sizeof(prefix), "Node%d", i);

        char *suffix = generate_suffix(SUFFIX_LENGTH);
        if (!suffix) {
            free(nodes);
            return NULL;
        }

        size_t name_len = strlen(prefix) + strlen(suffix) + 1;
        nodes[i].name = malloc(name_len);
        if (!nodes[i].name) {
            free(suffix);
            for (int j = 0; j < i; ++j) free(nodes[j].name);
            free(nodes);
            return NULL;
        }

        snprintf(nodes[i].name, name_len, "%s%s", prefix, suffix);
        nodes[i].value = rand() % 100;
        nodes[i].children_head = NULL;

        free(suffix); // Free the generated suffix
    }

    return nodes;
}

void insert_child_node(Node *node, int child_value) {
    ChildNode *new_child = malloc(sizeof(ChildNode));
    if (!new_child) return;

    new_child->child_value = child_value;
    new_child->next = node->children_head;
    node->children_head = new_child;
}

Node* get_node_by_index(Node *nodes, int index, int num_nodes) {
    if (index < 0 || index >= num_nodes) return NULL;
    return &nodes[index];
}

void iterate_nodes_and_children(Node *nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        printf("Node %d: Name=%s, Value=%d\n", i, nodes[i].name, nodes[i].value);

        ChildNode *child = nodes[i].children_head;
        while (child) {
            printf("\tChild Node: Value=%d\n", child->child_value);
            child = child->next;
        }
    }
}

void free_nodes(Node *nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        free(nodes[i].name);

        ChildNode *current = nodes[i].children_head;
        while (current) {
            ChildNode *temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(nodes);
}

int main() {
    init_random();

    int num_nodes = 10;
    Node *nodes = initialize_nodes(num_nodes, 5);

    if (!nodes) {
        printf("Failed to allocate nodes.\n");
        return EXIT_FAILURE;
    }

    insert_child_node(&nodes[0], 50);
    insert_child_node(&nodes[1], 25);

    iterate_nodes_and_children(nodes, num_nodes);

    free_nodes(nodes, num_nodes);

    return EXIT_SUCCESS;
}
