#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int value;
    int *offset;
    int *key;
    int access_count;
} Record;

// Logging function using asynchronous mechanism
void async_log(const char *message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    FILE *log_file = fopen("operations.log", "a");

    if (pthread_mutex_lock(&log_lock)) return; // Exit if mutex lock fails

    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    fclose(log_file);

    pthread_mutex_unlock(&log_lock);
}

// Helper function to find the largest integer in an array
int find_largest(int *array, size_t length) {
    int max = INT_MIN;
    for (size_t i = 0; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to initialize the dynamic array with random values
void initialize_records(Record **records, size_t count, int min_val, int max_val) {
    for (size_t i = 0; i < count; ++i) {
        records[i]->value = rand() % (max_val - min_val + 1) + min_val;
        records[i]->offset = &(records[i]->value);
        records[i]->key = &i;
        records[i]->access_count = 0;

        async_log("Initialized Record at index: %zu, Value: %d", i, records[i]->value);
    }
}

// Function to read integers from stdin and find the largest
void process_input(Record **records, size_t count) {
    int input;
    int *input_array = NULL;
    size_t array_size = 0;

    while (scanf("%d", &input) == 1) {
        input_array = realloc(input_array, sizeof(int) * (array_size + 1));
        if (!input_array) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        input_array[array_size++] = input;
    }

    int largest = find_largest(input_array, array_size);
    printf("Largest integer: %d\n", largest);

    free(input_array);
}

// Function to retrieve a record by index
Record* get_record(Record **records, size_t index) {
    if (index < 0 || index >= count) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    Record *record = records[index];
    record->access_count++;

    async_log("Retrieved and incremented access count for Record at index: %zu", index);
    pthread_mutex_unlock(&lock);

    return record;
}

// Function to update the access count of a record
void update_access_count(Record **records, size_t index) {
    if (index < 0 || index >= count) return;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    records[index]->access_count++;
    async_log("Updated access count for Record at index: %zu", index);

    pthread_mutex_unlock(&lock);
}

// Main function to manage dynamic array of Records
void dynamicDataManager(size_t record_count, int min_val, int max_val) {
    srand(time(NULL));

    // Allocate memory for records
    Record **records = malloc(record_count * sizeof(Record *));
    if (!records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
