#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

// Memory Pool Structure
typedef struct MemoryPool {
    size_t blockSize;
    size_t blockCount;
    void **blocks;
    char *freeList;
    size_t freeSize;
} MemoryPool;

// Function Prototypes
MemoryPool* createMemoryPool(size_t blockSize, size_t blockCount);
void destroyMemoryPool(MemoryPool *pool);
void* allocateFromPool(MemoryPool *pool);
void deallocateToPool(MemoryPool *pool, void *ptr);
Record* initializeAndManageRecords(size_t initialSize, int minValue, int maxValue, size_t maxCapacity);
void addRecord(Record *records, long *offsets, int *keys, MemoryPool *mp, int value, long offset, int key, size_t *currentCount, size_t maxCapacity);
int getRecordValue(Record *records, size_t index);
int findLargestValue(Record *records, size_t count);

// Implementation of the memory pool
MemoryPool* createMemoryPool(size_t blockSize, size_t blockCount) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->blockCount = blockCount;
    pool->blocks = calloc(blockCount, sizeof(void *));

    char *blockMemory = malloc(blockSize * blockCount);
    if (!blockMemory) {
        free(pool->blocks);
        free(pool);
        return NULL;
    }

    pool->freeList = blockMemory;
    pool->freeSize = blockSize * blockCount;

    for (size_t i = 0; i < blockCount - 1; ++i) {
        *(void**)(blockMemory + i * blockSize) = blockMemory + (i + 1) * blockSize;
    }
    *(void **)(blockMemory + (blockSize * (blockCount - 1))) = NULL;

    return pool;
}

void destroyMemoryPool(MemoryPool *pool) {
    if (!pool) return;
    free(pool->freeList);
    free(pool->blocks);
    free(pool);
}

void* allocateFromPool(MemoryPool *pool) {
    if (!pool || !pool->freeList) return NULL;

    void **ptr = (void **) pool->freeList;
    pool->freeList = *(void **) ptr;
    pool->freeSize -= pool->blockSize;

    return ptr;
}

void deallocateToPool(MemoryPool *pool, void *ptr) {
    if (!pool || !ptr) return;

    *(void **)((char *)ptr + pool->blockSize - sizeof(void *)) = pool->freeList;
    pool->freeList = (char *)ptr;
    pool->freeSize += pool->blockSize;
}

Record* initializeAndManageRecords(size_t initialSize, int minValue, int maxValue, size_t maxCapacity) {
    MemoryPool *mp = createMemoryPool(sizeof(Record), 1024); // example block size and count
    if (!mp) return NULL;

    Record *records = calloc(initialSize, sizeof(Record));
    long *offsets = malloc(initialSize * sizeof(long));
    int *keys = malloc(initialSize * sizeof(int));

    if (!records || !offsets || !keys) {
        free(records);
        free(offsets);
        free(keys);
        destroyMemoryPool(mp);
        return NULL;
    }

    for (size_t i = 0; i < initialSize; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].offset = offsets + i;
        records[i].key = keys + i;
    }

    return records;
}

void addRecord(Record *records, long *offsets, int *keys, MemoryPool *mp, int value, long offset, int key, size_t *currentCount, size_t maxCapacity) {
    if (*currentCount >= maxCapacity) return;

    Record *newRecord = allocateFromPool(mp);
    if (!newRecord) return; // Handle memory allocation failure

    newRecord->value = value;
    newRecord->offset = &offsets[*currentCount];
    newRecord->key = &keys[*currentCount];

    records[*currentCount] = *newRecord;
    (*currentCount)++;
}

int getRecordValue(Record *records, size_t index) {
    if (index >= sizeof(records) / sizeof(records[0])) return -1;
    return records[index].value;
}

int findLargestValue(Record *records, size_t count) {
    int maxVal = records[0].value;

    for (size_t i = 1; i < count; ++i) {
        if (records[i].value > maxVal)
            maxVal = records[i].value;
    }

    return maxVal;
}

int main() {
    size_t initialSize = 10;
    int minValue = 0, maxValue = 100;
    size_t maxCapacity = 20;

    Record *records = initializeAndManageRecords(initialSize, minValue, maxValue, maxCapacity);
    if (!records) {
        printf("Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    // Add more records dynamically
    size_t currentCount = initialSize;
    long offsets[maxCapacity];
    int keys[maxCapacity];
    MemoryPool *mp = createMemoryPool(sizeof(Record), 1024);

    addRecord(records, offsets, keys, mp, rand() % (maxValue - minValue + 1) + minValue, 12345, 6789, &currentCount, maxCapacity);

    int largestValue = findLargestValue(records, currentCount);
    printf("Largest Value: %d\n", largestValue);

    // Cleanup
    free(records);  // Also implies freeing of offsets and keys as they are part of records struct.
    destroyMemoryPool(mp);

    return EXIT_SUCCESS;
}
