#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_SIZE 1024

typedef struct {
    int key;
    int value;
} record;

typedef struct hash_node {
    record rec;
    struct hash_node *next;
} hash_node;

typedef struct {
    hash_node **table;
    size_t capacity;
    pthread_mutex_t lock;
} hashtable;

hashtable* create_hashtable(size_t initial_capacity) {
    hashtable *ht = malloc(sizeof(hashtable));
    ht->capacity = initial_capacity;
    ht->table = calloc(ht->capacity, sizeof(hash_node *));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hash_function(int key, size_t capacity) {
    return ((unsigned long)key * 2654435761UL) % capacity;
}

void resize_hashtable(hashtable *ht);

hash_node* create_hash_node(record rec) {
    hash_node *node = malloc(sizeof(hash_node));
    node->rec = rec;
    node->next = NULL;
    return node;
}

void insert_record(hashtable *ht, record rec) {
    pthread_mutex_lock(&ht->lock);

    unsigned long index = hash_function(rec.key, ht->capacity);
    hash_node *node = ht->table[index];
    while (node != NULL && node->rec.key != rec.key) {
        node = node->next;
    }

    if (node == NULL) {
        hash_node *new_node = create_hash_node(rec);
        new_node->next = ht->table[index];
        ht->table[index] = new_node;

        // Resize the table if load factor > 0.75
        size_t count = 0;
        for (size_t i = 0; i < ht->capacity; ++i) {
            hash_node *n = ht->table[i];
            while (n != NULL) {
                n = n->next;
                count++;
            }
        }

        if ((float)count / ht->capacity > 0.75) {
            resize_hashtable(ht);
        }
    } else {
        node->rec.value = rec.value; // Update existing record
    }

    pthread_mutex_unlock(&ht->lock);
}

void resize_hashtable(hashtable *ht) {
    size_t new_capacity = ht->capacity * 2;
    hash_node **new_table = calloc(new_capacity, sizeof(hash_node *));

    for (size_t i = 0; i < ht->capacity; ++i) {
        hash_node *node = ht->table[i];
        while (node != NULL) {
            unsigned long new_index = hash_function(node->rec.key, new_capacity);
            hash_node *next_node = node->next;

            node->next = new_table[new_index];
            new_table[new_index] = node;
            node = next_node;
        }
    }

    free(ht->table);
    ht->table = new_table;
    ht->capacity = new_capacity;
}

int get_record(hashtable *ht, int key) {
    pthread_mutex_lock(&ht->lock);

    unsigned long index = hash_function(key, ht->capacity);
    hash_node *node = ht->table[index];

    while (node != NULL) {
        if (node->rec.key == key) {
            pthread_mutex_unlock(&ht->lock);
            return node->rec.value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return -1; // Record not found
}

void delete_record(hashtable *ht, int key) {
    pthread_mutex_lock(&ht->lock);

    unsigned long index = hash_function(key, ht->capacity);
    hash_node *node = ht->table[index];
    hash_node *prev = NULL;

    while (node != NULL && node->rec.key != key) {
        prev = node;
        node = node->next;
    }

    if (node == NULL) {
        pthread_mutex_unlock(&ht->lock);
        return; // Record not found
    }

    if (prev == NULL) { // First node in the chain
        ht->table[index] = node->next;
    } else {
        prev->next = node->next;
    }

    free(node);
    pthread_mutex_unlock(&ht->lock);
}

void destroy_hashtable(hashtable *ht) {
    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->capacity; ++i) {
        hash_node *node = ht->table[i];
        while (node != NULL) {
            hash_node *next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_unlock(&ht->lock);
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int main() {
    hashtable *ht = create_hashtable(INITIAL_SIZE);

    record rec1 = { .key = 100, .value = 200 };
    insert_record(ht, rec1);

    printf("Value for key 100: %d\n", get_record(ht, 100));

    delete_record(ht, 100);
    printf("Value for key 100 after deletion: %d\n", get_record(ht, 100));

    destroy_hashtable(ht);
    return 0;
}
```

This code provides a basic implementation of a thread-safe hash table for managing records with integer keys and values. It supports dynamic resizing to maintain performance, uses mutexes to handle concurrent access, and ensures proper memory management by freeing allocated resources when they are no longer needed.']

