#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct Node {
    int data;
    struct Node *left, *right;
} TreeNode;

typedef struct {
    Record **records;   // Array of record pointers for priority queue
    size_t capacity;    // Capacity of the priority queue
    size_t currentSize; // Current number of records in the queue
} PriorityQueue;

// Function prototypes
void initializeAndManageRecords(size_t initialSize, size_t maxSize, unsigned int seed);
Record *getRecordByIndex(PriorityQueue *pq, size_t index);
int addNewRecord(PriorityQueue *pq, Record *record);
int updateExistingRecord(PriorityQueue *pq, size_t index, Record *newData);
void freePriorityQueue(PriorityQueue *pq);
void insertTreeNode(TreeNode **root, int data);
int findMaxInBST(TreeNode *root);

// Initialize the priority queue with a memory pool
void initializePriorityQueue(PriorityQueue *pq, size_t capacity) {
    pq->records = (Record **)malloc(capacity * sizeof(Record *));
    if (!pq->records) exit(EXIT_FAILURE); // Handle allocation failure
    pq->capacity = capacity;
    pq->currentSize = 0;
}

// Function to retrieve a specific record by its index
Record *getRecordByIndex(PriorityQueue *pq, size_t index) {
    if (index >= pq->currentSize) return NULL; // Index out of bounds
    return pq->records[index];
}

// Add new records dynamically without exceeding the maximum size
int addNewRecord(PriorityQueue *pq, Record *record) {
    if (pq->currentSize >= pq->capacity) return -1; // Queue is full
    pq->records[pq->currentSize++] = record;
    return 0;
}

// Update existing records efficiently
int updateExistingRecord(PriorityQueue *pq, size_t index, Record *newData) {
    if (index >= pq->currentSize) return -1; // Index out of bounds
    pq->records[index] = newData;
    return 0;
}

// Free the priority queue and its memory pool
void freePriorityQueue(PriorityQueue *pq) {
    for (size_t i = 0; i < pq->currentSize; ++i) {
        if (pq->records[i]) {
            free(pq->records[i]->offset);
            free(pq->records[i]->key);
            free(pq->records[i]);
        }
    }
    free(pq->records);
}

// Insert data into a balanced binary search tree
void insertTreeNode(TreeNode **root, int data) {
    if (*root == NULL) {
        *root = (TreeNode *)malloc(sizeof(TreeNode));
        if (!(*root)) exit(EXIT_FAILURE); // Handle allocation failure
        (*root)->data = data;
        (*root)->left = (*root)->right = NULL;
    } else if (data < (*root)->data) {
        insertTreeNode(&((*root)->left), data);
    } else {
        insertTreeNode(&((*root)->right), data);
    }
}

// Find and return the largest integer in the BST
int findMaxInBST(TreeNode *root) {
    while (root && root->right) root = root->right;
    return root ? root->data : -1; // Return -1 if tree is empty
}

void initializeAndManageRecords(size_t initialSize, size_t maxSize, unsigned int seed) {
    srand(seed);

    PriorityQueue pq;
    initializePriorityQueue(&pq, maxSize);

    for (size_t i = 0; i < initialSize; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) exit(EXIT_FAILURE); // Handle allocation failure

        record->value = rand() % 100;          // Random value between 0-99
        record->offset = malloc(sizeof(long)); // Allocate memory for offset
        record->key = malloc(sizeof(int));     // Allocate memory for key

        if (!record->offset || !record->key) {
            free(record);
            exit(EXIT_FAILURE); // Handle allocation failure
        }

        *record->offset = rand() % 1000;       // Random offset value between 0-999
        *record->key = rand() % 1000;          // Random key value between 0-999

        addNewRecord(&pq, record);
    }

    TreeNode *root = NULL;
    int inputNumber;

    while (scanf("%d", &inputNumber) == 1) {
        insertTreeNode(&root, inputNumber);
    }

    printf("Largest number in BST: %d\n", findMaxInBST(root));
    freePriorityQueue(&pq);
}
