typedef struct {
    int value;
    long *offsetPtr;
    int *keyPtr;
} record;

#define MAX_RECORDS 1000

typedef struct {
    size_t block_size;
    void* pool;
    size_t current_offset;
    void* (*alloc_func)(size_t);
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t block_size, void* (*alloc_func)(size_t));
void* memory_pool_alloc(MemoryPool* pool, size_t size);
void destroy_memory_pool(MemoryPool* pool);
record* initializeAndManageRecords(int num_records, int min_value, int max_value);
record get_record_by_index(record *records, int index, int num_records);
int add_record_if_space_available(record *records, int current_count, int min_value, int max_value);
void free_resources(record *records, long *offsets, int *keys);

MemoryPool* create_memory_pool(size_t block_size, void* (*alloc_func)(size_t)) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->alloc_func = alloc_func;
    pool->current_offset = 0;

    size_t num_blocks = block_size / sizeof(void*);
    pool->pool = alloc_func(block_size * num_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool, size_t size) {
    if (size > pool->block_size || pool->current_offset + size > pool->block_size) {
        return NULL; // Allocation fails
    }

    void *ptr = ((char*)pool->pool) + pool->current_offset;
    pool->current_offset += size;

    return ptr;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    free(pool);
}

record* initializeAndManageRecords(int num_records, int min_value, int max_value) {
    MemoryPool *pool = create_memory_pool(4096, malloc);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool.\n");
        return NULL;
    }

    long *offsets = (long*)memory_pool_alloc(pool, num_records * sizeof(long));
    int *keys = (int*)memory_pool_alloc(pool, num_records * sizeof(int));
    record *records = (record*)memory_pool_alloc(pool, num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        destroy_memory_pool(pool);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000000L; // Example offset
        keys[i] = rand() % 1000;        // Example key
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].offsetPtr = &offsets[i];
        records[i].keyPtr = &keys[i];
    }

    return records;
}

record get_record_by_index(record *records, int index, int num_records) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }
    return records[index];
}

int add_record_if_space_available(record *records, int current_count, int min_value, int max_value) {
    if (current_count >= MAX_RECORDS) {
        fprintf(stderr, "Maximum record limit reached.\n");
