    long offset = rand() % 1000000L; // Example offset
    int key = rand() % 1000;         // Example key

    records[current_count].value = min_value + rand() % (max_value - min_value + 1);
    records[current_count].offsetPtr = &offset;
    records[current_count].keyPtr = &key;

    return current_count + 1;
}

void free_resources(record *records, long *offsets, int *keys) {
