['Here's a C implementation that fulfills the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    record **cache; // Simple cache for frequently accessed records
    size_t cache_capacity;
    size_t cache_count;
} RecordCollection;

// Function prototypes
RecordCollection* init_collection(size_t initial_capacity);
void free_collection(RecordCollection *collection);
record* get_record_by_index(RecordCollection *collection, size_t index);
void resize_collection(RecordCollection *collection);
int random_value(int min, int max);

// Initialize the collection with a specified capacity
RecordCollection* init_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(initial_capacity * sizeof(record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->records[i] = malloc(sizeof(record));
        if (!collection->records[i]) {
            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) {
                free(collection->records[j]);
            }
            free(collection->records);
            free(collection);
            return NULL;
        }

        collection->records[i]->value = random_value(1, 100); // Random value between 1 and 100
        collection->records[i]->offset = malloc(sizeof(long));
        if (!collection->records[i]->offset) {
            for (size_t j = 0; j <= i; ++j) {
                free(collection->records[j]);
            }
            free(collection->records);
            free(collection);
            return NULL;
        }

        collection->records[i]->key = malloc(sizeof(int));
        if (!collection->records[i]->key) {
            for (size_t j = 0; j <= i; ++j) {
                free(collection->records[j]->offset);
                free(collection->records[j]);
            }
            free(collection->records);
            free(collection);
            return NULL;
        }

        *collection->records[i]->key = (int)i; // Assign key as index
    }

    collection->capacity = initial_capacity;
    collection->count = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    // Initialize cache
    collection->cache = malloc(initial_capacity / 2 * sizeof(record *));
    if (!collection->cache) {
        for (size_t i = 0; i < initial_capacity; ++i) {
            free(collection->records[i]->offset);
            free(collection->records[i]->key);
            free(collection->records[i]);
        }
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
        return NULL;
    }

    collection->cache_capacity = initial_capacity / 2;
    collection->cache_count = 0;

    return collection;
}

// Free all allocated memory
void free_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }

    free(collection->records);
    free(collection->cache);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Retrieve a record by index with thread safety
record* get_record_by_index(RecordCollection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);

    // Simple cache check (for demonstration)
    for (size_t i = 0; i < collection->cache_count; ++i) {
        if (*collection->cache[i]->key == index) {
            pthread_mutex_unlock(&collection->lock);
            return *collection->cache[i];
        }
    }

    record* result = collection->records[index];

    // Add to cache (simple insertion, replace oldest if full)
    if (collection->cache_count < collection->cache_capacity) {
        collection->cache[collection->cache_count++] = &result;
    } else {
        free(collection->cache[0]);
        memmove(collection->cache, collection->cache + 1,
                sizeof(record *) * (collection->cache_capacity - 1));
        collection->cache[collection->cache_capacity - 1] = &result;
    }

    pthread_mutex_unlock(&collection->lock);
    return result;
}

// Resize the collection when capacity is exceeded
void resize_collection(RecordCollection *collection) {
    if (!collection) return;

    size_t new_capacity = collection->capacity * 2;
    record **new_records = realloc(collection->records, new_capacity * sizeof(record *));
    if (!new_records) return; // Handle allocation failure gracefully

    for (size_t i = collection->count; i < new_capacity; ++i) {
        new_records[i] = malloc(sizeof(record));
        if (!new_records[i]) {
            for (size_t j = collection->count; j < i; ++j) {
                free(new_records[j]);
            }
            free(new_records);
            return;
        }

        new_records[i]->value = random_value(1, 100); // Random value
        new_records[i]->offset = malloc(sizeof(long));
        if (!new_records[i]->offset) {
            for (size_t j = collection->count; j <= i; ++j) {
                free(new_records[j]);
            }
            free(new_records);
            return;
        }

        new_records[i]->key = malloc(sizeof(int));
        if (!new_records[i]->key) {
            for (size_t j = collection->count; j <= i; ++j) {
                free(new_records[j]->offset);
                free(new_records[j]);
            }
            free(new_records);
            return;
        }

        *new_records[i]->key = (int)i;
    }

    collection->records = new_records;
    collection->capacity = new_capacity;
    collection->count = new_capacity;

    // Resize cache if needed
    size_t new_cache_capacity = collection->cache_capacity * 2;
    record **new_cache = realloc(collection->cache, new_cache_capacity * sizeof(record *));
    if (new_cache) {
        collection->cache = new_cache;
        collection->cache_capacity = new_cache_capacity;
    }
}

// Generate a random value within a specified range
int random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    RecordCollection *collection = init_collection(10);
    if (!collection) {
        fprintf(stderr, "Failed to initialize collection\n");
        return EXIT_FAILURE;
    }

    record *rec = get_record_by_index(collection, 5);
    if (rec) {
        printf("Record at index 5: Value=%d, Key=%d\n", rec->value, *rec->key);
    } else {
        fprintf(stderr, "Failed to retrieve record at index 5\n");
    }

    // Resize collection for demonstration
    resize_collection(collection);

    free_collection(collection);
    return EXIT_SUCCESS;
}
