typedef struct {
    entry_t** entries;
    size_t count;
    size_t capacity;
} entry_collection_t;

// Function prototypes
entry_collection_t* create_entry_collection(size_t initial_capacity);
void free_entry_collection(entry_collection_t* collection);
int add_entry(entry_collection_t* collection, const char* name, double value_range_min, double value_range_max);
entry_t* get_entry_by_index(const entry_collection_t* collection, size_t index);
