entry_collection_t* create_entry_collection(size_t initial_capacity) {
    entry_collection_t* collection = (entry_collection_t*)malloc(sizeof(entry_collection_t));
    if (!collection) return NULL;

    collection->entries = (entry_t**)calloc(initial_capacity, sizeof(entry_t*));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    return collection;
}

void free_entry_collection(entry_collection_t* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->name);
        free(collection->entries[i]->metadata->info);
        free(collection->entries[i]->metadata);
        free(collection->entries[i]);
    }
    free(collection->entries);
    free(collection);
}

int add_entry(entry_collection_t* collection, const char* name, double value_range_min, double value_range_max) {
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        entry_t** new_entries = realloc(collection->entries, new_capacity * sizeof(entry_t*));
        if (!new_entries) return -1;

        memset(new_entries + collection->capacity, 0, collection->capacity * sizeof(entry_t*));
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }

    entry_t* new_entry = (entry_t*)malloc(sizeof(entry_t));
    if (!new_entry) return -1;

    new_entry->name = strdup(name);
    if (!new_entry->name) {
        free(new_entry);
        return -1;
    }

    srand(time(NULL) ^ (intptr_t)new_entry); // Seed for randomness
    new_entry->value = value_range_min + ((double)rand() / RAND_MAX) * (value_range_max - value_range_min);

    new_entry->metadata = fetch_metadata_from_api(collection->count);
    if (!new_entry->metadata) {
        free(new_entry->name);
        free(new_entry);
        return -1;
    }

    collection->entries[collection->count++] = new_entry;
    return 0;
}

entry_t* get_entry_by_index(const entry_collection_t* collection, size_t index) {
    if (index < collection->count) {
        return collection->entries[index];
    }
    return NULL;
}

int update_entry_value(entry_collection_t* collection, size_t index, double new_value) {
    if (index < collection->count) {
        collection->entries[index]->value = new_value;
        return 0;
    }
    return -1;
}

void refresh_metadata(entry_collection_t* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        collection->entries[i]->metadata = fetch_metadata_from_api(i);
    }
}

void iterate_and_filter_entries(const entry_collection_t* collection, void (*operation)(const entry_t*)) {
    for (size_t i = 0; i < collection->count; ++i) {
        operation(collection->entries[i]);
    }
}

// Helper functions

