    #[tokio::test]
    async fn test_initializeAndManageRecords() {
        assert!(initializeAndManageRecords(10, 0, 100).await.is_ok());
    }

    #[test]
    fn test_find_max() {
        let numbers = vec![3, 1, 4, 1, 5, 9];
        assert_eq!(find_max(&numbers), 9);

        let empty_numbers: Vec<i32> = vec![];
        assert_eq!(find_max(&empty_numbers), i32::MIN); // Edge case
    }
}
