typedef struct {
    int value;
} record;

typedef struct MemoryManager {
    size_t totalMemoryUsed;
    int allocatedBlocks;
    pthread_mutex_t lock;
} MemoryManager;

// Function to log events
void logEvent(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Custom memory allocator with tracking
void* customAllocate(size_t size, MemoryManager* manager) {
    void* ptr = malloc(size);
    if (ptr != NULL) {
        pthread_mutex_lock(&manager->lock);
        manager->totalMemoryUsed += size;
        manager->allocatedBlocks++;
        pthread_mutex_unlock(&manager->lock);
        logEvent("Allocated memory");
    } else {
        fprintf(stderr, "Allocation failed\n");
    }
    return ptr;
}

void customFree(void* ptr, size_t size, MemoryManager* manager) {
    if (ptr != NULL) {
        free(ptr);
        pthread_mutex_lock(&manager->lock);
        manager->totalMemoryUsed -= size;
        manager->allocatedBlocks--;
        pthread_mutex_unlock(&manager->lock);
        logEvent("Freed memory");
    }
}

// Serialize data structures to a file
void serializeData(FILE* file, long* offsets, int* keys, record* records, size_t n) {
    fwrite(offsets, sizeof(long), n, file);
    fwrite(keys, sizeof(int), n, file);
    fwrite(records, sizeof(record), n, file);
}

// Deserialize data structures from a file
void deserializeData(FILE* file, long* offsets, int* keys, record* records, size_t n) {
    fread(offsets, sizeof(long), n, file);
    fread(keys, sizeof(int), n, file);
    fread(records, sizeof(record), n, file);
}

// Function to verify data integrity
void verifyDataIntegrity(long* offsets, int* keys, record* records, size_t n) {
    for (size_t i = 0; i < n; i++) {
        if (offsets[i] != 0 || keys[i] != 0 || records[i].value != 0) { // Simplified check
            fprintf(stderr, "Data integrity issue at index %zu\n", i);
        }
    }
}

void manageMemory(size_t n, int verifyIntegrity) {
    if (n == 0) return;

    MemoryManager manager = {0};
    pthread_mutex_init(&manager.lock, NULL);

    long* offsets = (long*)customAllocate(n * sizeof(long), &manager);
    int* keys = (int*)customAllocate(n * sizeof(int), &manager);
    record* records = (record*)customAllocate(n * sizeof(record), &manager);

    if (!offsets || !keys || !records) return;

    // Initialize arrays and structures
    for (size_t i = 0; i < n; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
    }

    if (verifyIntegrity) {
        verifyDataIntegrity(offsets, keys, records, n);
    }

    // Serialize data
    FILE* file = fopen("data.bin", "wb");
    if (file) {
        serializeData(file, offsets, keys, records, n);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for writing\n");
    }

    // Deserialize data
    file = fopen("data.bin", "rb");
    if (file) {
        deserializeData(file, offsets, keys, records, n);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for reading\n");
    }

    customFree(offsets, n * sizeof(long), &manager);
    customFree(keys, n * sizeof(int), &manager);
    customFree(records, n * sizeof(record), &manager);

    pthread_mutex_destroy(&manager.lock);
}

int main() {
    size_t n = 10;
    manageMemory(n, 1);
    return 0;
}
