#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 100
#define MAX_SIZE 1000
#define MEMORY_LIMIT (INITIAL_SIZE * sizeof(int) * 2)
#define THREAD_POOL_SIZE 4

typedef struct {
    int value;
} record;

typedef struct {
    int *offsets;
    int *keys;
    size_t size;
    pthread_mutex_t lock;
} data_manager;

// Mock external service to generate random values
int get_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Logger function for monitoring purposes
void log_message(const char *message) {
    printf("%s\n", message);
}

// Memory pool allocator (naive implementation)
static void* memory_pool_alloc(size_t size, data_manager *dm) {
    pthread_mutex_lock(&dm->lock);
    if (size > MEMORY_LIMIT - dm->size * sizeof(int)) {
        log_message("Memory limit exceeded");
        pthread_mutex_unlock(&dm->lock);
        return NULL;
    }
    void *memory = malloc(size);
    if (!memory) {
        log_message("Memory allocation failed");
    } else {
        dm->size += size / sizeof(int);
        log_message("Memory allocated successfully");
    }
    pthread_mutex_unlock(&dm->lock);
    return memory;
}

// Dynamic array resizing
void resize_array_if_needed(data_manager *dm, int **array) {
    if (dm->size >= MAX_SIZE) {
        pthread_mutex_lock(&dm->lock);
        size_t new_size = dm->size * 2;
        if (new_size > MEMORY_LIMIT / sizeof(int)) {
            log_message("Cannot resize due to memory limit");
        } else {
            *array = realloc(*array, new_size * sizeof(int));
            if (*array) {
                log_message("Array resized successfully");
                dm->size = new_size;
            } else {
                log_message("Failed to resize array");
            }
        }
        pthread_mutex_unlock(&dm->lock);
    }
}

// Thread worker function
void* manage_lifecycle(void *arg) {
    data_manager *dm = (data_manager *)arg;
    int i;

    for (i = 0; i < dm->size; ++i) {
        resize_array_if_needed(dm, &dm->offsets);
        resize_array_if_needed(dm, &dm->keys);

        pthread_mutex_lock(&dm->lock);
        if (i >= MAX_SIZE) break;

        dm->offsets[i] = get_random_value(1, 100);
        dm->keys[i] = get_random_value(101, 200);

        log_message("Record initialized");
        pthread_mutex_unlock(&dm->lock);
    }
    return NULL;
}

// Main function to initialize and manage data
data_manager* init_data_manager() {
    data_manager *dm = (data_manager *)malloc(sizeof(data_manager));
    if (!dm) {
        log_message("Failed to allocate memory for data manager");
        return NULL;
    }

    pthread_mutex_init(&dm->lock, NULL);

    dm->offsets = (int*)memory_pool_alloc(INITIAL_SIZE * sizeof(int), dm);
    dm->keys = (int*)memory_pool_alloc(INITIAL_SIZE * sizeof(int), dm);

    if (!dm->offsets || !dm->keys) {
        log_message("Failed to initialize arrays");
        free(dm->offsets);
        free(dm->keys);
        pthread_mutex_destroy(&dm->lock);
        free(dm);
        return NULL;
    }

    dm->size = INITIAL_SIZE;

    return dm;
}

// Function to start lifecycle management
void start_lifecycle_management() {
    srand(time(NULL));
    data_manager *dm = init_data_manager();

    if (!dm) {
        log_message("Data manager initialization failed");
        return;
    }

    pthread_t threads[THREAD_POOL_SIZE];

    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        if (pthread_create(&threads[i], NULL, manage_lifecycle, dm)) {
            log_message("Failed to create thread");
        }
    }

    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(dm->offsets);
    free(dm->keys);
    pthread_mutex_destroy(&dm->lock);
    free(dm);

    log_message("Lifecycle management completed");
}

int main() {
    start_lifecycle_management();
    return 0;
}
