const char* get_status_for_project_type(const char* project_id) {
    // This would normally query an external source.
    if (strcmp(project_id, "projectA") == 0) {
        return "In Progress";
    } else {
        return "Not Started";
    }
}

int is_date_in_future(const char *date_str) {
    struct tm due_tm = {0};
    strptime(date_str, "%Y-%m-%d", &due_tm);
    time_t due_time = mktime(&due_tm);

    time_t now = time(NULL);
    return difftime(due_time, now) > 0;
}

project_task* allocate_project_tasks(const char *project_id, int num_tasks, 
                                     int priorities[], const char *due_dates[], const char **statuses) {
    if (!project_id || !priorities || !due_dates || !statuses) {
        return NULL; // Handle null pointers
    }

    project_task *tasks = (project_task*)malloc(num_tasks * sizeof(project_task));
    if (!tasks) {
        return NULL; // Out of memory condition
    }

    const char *base_status = get_status_for_project_type(project_id);

    for (int i = 0; i < num_tasks; ++i) {
        if (!is_date_in_future(due_dates[i])) {
            free(tasks);
            return NULL; // Due date validation failed
        }

        tasks[i].priority = priorities[i];
        strncpy(tasks[i].due_date, due_dates[i], sizeof(tasks[i].due_date) - 1);
        tasks[i].status = statuses[i] ? statuses[i] : base_status;
    }

    return tasks;
}

void update_task_status(project_task *tasks, int task_index, const char *new_status) {
    if (tasks && task_index >= 0 && new_status) {
        tasks[task_index].status = new_status; // Simple status update without reallocating
    }
}
