    while (scanf("%lf %255s", &num, str) == 2) {
        add_node(head, num, str);

        printf("Enter another number and a string (or 'q' to quit): ");
    }

    if (feof(stdin)) {
        return 1; // Success
    } else {
        perror("Input error");
        return 0; // Failure
    }
}

int read_from_csv(const char *filename, Node **head) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return 0;
    }

    double num;
    char str[256];

    while (fscanf(file, "%lf,%255[^,\n]\n", &num, str) == 2) {
        add_node(head, num, str);
    }

    fclose(file);
    if (feof(file)) {
        return 1; // Success
    } else {
        perror("File read error");
        return 0; // Failure
    }
}

void print_list(Node *head) {
    while (head) {
        printf("Value: %.2f, String: %s\n", head->value, head->str);
        head = head->next;
    }
}

int validate_list(Node *head) {
    Node *slow = head, *fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;

        if (slow == fast) {
            return 0; // Cycle detected
        }
    }

    return 1; // No cycle detected
}

void free_list(Node *head) {
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp->str);
        free(temp);
    }
}
