```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int priority;
    time_t due_date;
    char status[20];
    char *assigned_to; // This should be a valid user name or ID.
    float completion_percentage;
} project_task;

// Global task list
project_task **task_list = NULL;
size_t task_count = 0;
pthread_mutex_t task_list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int id; // Example attribute for user, could be more complex in reality.
    char name[50];
} User;

User *fetch_user(const char *username) {
    // Simulate fetching a user from an external source
    // In practice, this would involve database or API calls
    User *user = (User *)malloc(sizeof(User));
    if (!user) return NULL;

    strcpy(user->name, username);
    user->id = rand();  // Assign random ID for demonstration purposes.
    return user;
}

int is_future_date(time_t date) {
    time_t now = time(NULL);
    return difftime(date, now) > 0; // True if the due_date is in the future
}

// Function to initialize a project_task and ensure valid input
project_task *initialize_project_task(int priority, const char *due_date_str, const char *status,
                                      const char *assigned_to_name, float completion_percentage) {
    if (!due_date_str || !status || !assigned_to_name)
        return NULL;

    struct tm due_tm = {0};
    strptime(due_date_str, "%Y-%m-%d", &due_tm);
    time_t due_date = mktime(&due_tm);

    // Check for valid due date and completion percentage
    if (!is_future_date(due_date) || completion_percentage < 0.0f || completion_percentage > 100.0f)
        return NULL;

    User *user = fetch_user(assigned_to_name);
    if (!user)
        return NULL;

    project_task *task = (project_task *)malloc(sizeof(project_task));
    if (!task) {
        free(user);
        return NULL;
    }

    task->priority = priority;
    task->due_date = due_date;
    strncpy(task->status, status, sizeof(task->status) - 1);
    task->assigned_to = user->name; // Assigning the username for simplicity
    task->completion_percentage = completion_percentage;

    return task;
}

// Function to add a task to the global list
int add_task(int priority, const char *due_date_str, const char *status,
             const char *assigned_to_name, float completion_percentage) {
    project_task *new_task = initialize_project_task(priority, due_date_str, status, assigned_to_name, completion_percentage);

    if (!new_task)
        return -1; // Initialization failed

    pthread_mutex_lock(&task_list_mutex);

    task_count++;
    task_list = (project_task **)realloc(task_list, task_count * sizeof(project_task *));
    if (!task_list) {
        free(new_task->assigned_to);  // Assuming assigned_to is a malloc-ed string
        free(new_task);
        pthread_mutex_unlock(&task_list_mutex);
        return -1; // Memory allocation failed
    }

    task_list[task_count - 1] = new_task;

    pthread_mutex_unlock(&task_list_mutex);

    return 0;
}

// Function to remove completed tasks from the global list
void remove_completed_tasks() {
    pthread_mutex_lock(&task_list_mutex);

    size_t i, j = 0;
    for (i = 0; i < task_count; ++i) {
        if (strcmp(task_list[i]->status, "completed") != 0) {
            if (j != i) {
                task_list[j] = task_list[i];
            }
            j++;
        } else {
            free(task_list[i]->assigned_to); // Clean up dynamically allocated strings
            free(task_list[i]);
        }
    }

    task_count = j;
    task_list = (project_task **)realloc(task_list, task_count * sizeof(project_task *));
    if (task_count != j && task_list) { // If realloc fails and count didn't match, it means an error occurred.
        pthread_mutex_unlock(&task_list_mutex);
        return;
    }

    pthread_mutex_unlock(&task_list_mutex);
}

// Example main function to demonstrate usage
int main() {
    add_task(1, "2024-12-31", "in_progress", "Alice", 50.0f);

    remove_completed_tasks();

    // Clean up remaining tasks
    for (size_t i = 0; i < task_count; ++i) {
        free(task_list[i]->assigned_to); 
        free(task_list[i]);
    }

    free(task_list);

    return 0;
}
```

### Key Points:

- **Thread Safety**: A `pthread_mutex_t` is used to ensure thread-safe access to the global `task_list`.
- **Dynamic Allocation**: The task list is dynamically resized using `realloc` to accommodate new tasks.
