typedef struct CircularBuffer {
    Measurement data[MAX_BUFFER_SIZE];
    int head;
    int tail;
    int size;
} CircularBuffer;

CircularBuffer circular_buffer = {{0}, 0, 0, 0};

Node* create_node(const char* sensor_id, int timestamp) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    strncpy(node->sensor_id, sensor_id, sizeof(node->sensor_id) - 1);
    node->timestamp = timestamp;
    node->next = NULL;
    return node;
}

Entry* create_entry(const char* key, Node* node_ptr) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;
    strncpy(entry->key, key, sizeof(entry->key) - 1);
    entry->node_ptr = node_ptr;
    entry->next = NULL;
    return entry;
}

CircularBuffer* init_circular_buffer() {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!buffer) return NULL;
    memset(buffer, 0, sizeof(CircularBuffer));
    return buffer;
}

void add_measurement(CircularBuffer* buffer, double value, time_t timestamp) {
    buffer->data[buffer->tail] = (Measurement){value, timestamp};
    buffer->tail = (buffer->tail + 1) % MAX_BUFFER_SIZE;
    if (buffer->size < MAX_BUFFER_SIZE) {
        buffer->size++;
    } else {
        buffer->head = (buffer->head + 1) % MAX_BUFFER_SIZE;
    }
}

void reset_circular_buffer(CircularBuffer* buffer) {
    memset(buffer, 0, sizeof(CircularBuffer));
}

int insert_into_hash_table(Entry** hash_table, const char* key, Node* node_ptr, size_t table_size) {
    size_t index = hash(key) % table_size;
    Entry* new_entry = create_entry((char*)key, node_ptr);
    if (!new_entry) return -1;

    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
    return 0;
}

Node* find_node_in_linked_list(Node* head, const char* sensor_id) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->sensor_id, sensor_id) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update_node(Node* node, int new_timestamp) {
    if (node) {
        node->timestamp = new_timestamp;
    }
}

int hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

void reset_data_structures(Node** linked_list_head, Entry** hash_table, size_t table_size, CircularBuffer* buffer) {
    Node* current_node = *linked_list_head;
    while (current_node != NULL) {
        Node* temp_node = current_node;
        current_node = current_node->next;
        free(temp_node);
    }
    *linked_list_head = NULL;

    for (size_t i = 0; i < table_size; ++i) {
        Entry* current_entry = hash_table[i];
        while (current_entry != NULL) {
            Entry* temp_entry = current_entry;
            current_entry = current_entry->next;
            free(temp_entry);
        }
        hash_table[i] = NULL;
    }

    reset_circular_buffer(buffer);
}

void manage_data_structures(Node** linked_list_head, Entry** hash_table, size_t table_size) {
    // Example usage
    Node* node1 = create_node("sensor_1", time(NULL));
    if (!node1) return;

    *linked_list_head = node1;

    insert_into_hash_table(hash_table, "sensor_1", node1, table_size);

    CircularBuffer* buffer = init_circular_buffer();
    if (!buffer) return;

    add_measurement(buffer, 23.5, time(NULL));

    // Reset all structures
    reset_data_structures(linked_list_head, hash_table, table_size, buffer);

    free(buffer);
}
