static pthread_once_t rand_seed_once = PTHREAD_ONCE_INIT;
static void seed_random() {
    srand((unsigned)time(NULL));
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_records>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int n = atoi(argv[1]);
    if (n < 0) {
        fprintf(stderr, "Error: number of records must be non-negative.\n");
        return EXIT_FAILURE;
    }

    // Memory pool allocation
    size_t total_size = sizeof(long) * n + sizeof(int) * n + sizeof(record) * n;
    void* memory_pool = malloc(total_size);
    if (!memory_pool) {
        perror("Failed to allocate memory pool");
        return EXIT_FAILURE;
    }

    long *offsets = (long*)memory_pool;
    int *keys = (int*)(offsets + n);
    record *records = (record*)(keys + n);

    // Seed random number generator
    pthread_once(&rand_seed_once, seed_random);

    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % 2001 - 1000; // Random between -1000 and 1000
        memset(records[i].buffer, '\0', BUFFER_SIZE);

        if ((rand() % 2) == 0 && strlen(records[i].buffer) < BUFFER_SIZE - 10) {
            snprintf(records[i].buffer, BUFFER_SIZE, "RandomData_%d", rand());
