typedef struct {
    char *description;
    int key;
    long value;
    struct timeval timestamp;
} record;

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

#define INITIAL_CAPACITY 10

void random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length;
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    }
}

RecordList* create_record_list(size_t initial_capacity) {
    RecordList *list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = calloc(initial_capacity, sizeof(record *));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_record_list(RecordList *list) {
    size_t new_capacity = list->capacity * 2;
    record **new_records = realloc(list->records, new_capacity * sizeof(record *));
    if (!new_records) return;

    list->records = new_records;
    list->capacity = new_capacity;
}

void add_record(RecordList *list, int key_min, int key_max, long value_min, long value_max, size_t desc_length_min, size_t desc_length_max) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_record_list(list);
    }

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    size_t desc_length = rand() % (desc_length_max - desc_length_min + 1) + desc_length_min;
    new_record->description = malloc(desc_length + 1);
    if (!new_record->description) {
        free(new_record);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    random_string(new_record->description, desc_length);
    new_record->key = rand() % (key_max - key_min + 1) + key_min;
    new_record->value = rand() % (value_max - value_min + 1) + value_min;
    gettimeofday(&new_record->timestamp, NULL);

    list->records[list->count++] = new_record;

    pthread_mutex_unlock(&list->lock);
}

record* get_record_by_index(RecordList *list, size_t index) {
    if (index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);
    record *result = list->records[index];
    pthread_mutex_unlock(&list->lock);

    return result;
}

void update_record(RecordList *list, size_t index, int new_key, long new_value) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->lock);
    record *rec = list->records[index];
    gettimeofday(&rec->timestamp, NULL);
    rec->key = new_key;
    rec->value = new_value;
    pthread_mutex_unlock(&list->lock);
}

int compare_records(const void *a, const void *b) {
    return ((record *)a)->key - ((record *)b)->key;
}

void sort_record_list(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    qsort(list->records, list->count, sizeof(record *), compare_records);

    pthread_mutex_unlock(&list->lock);
}

// Example synchronization function (stub)
void synchronize_with_external_source(RecordList *list) {
    // Placeholder for actual network sync logic
    printf("Synchronizing with external data source...\n");
}

void free_record_list(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]) {
            free(list->records[i]->description);
            free(list->records[i]);
        }
    }

    free(list->records);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void print_record_list(RecordList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        record *rec = list->records[i];
        printf("Key: %d, Value: %ld, Description: %s\n", rec->key, rec->value, rec->description);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 6) {
        fprintf(stderr, "Usage: %s <num_records> <key_min> <key_max> <value_min> <value_max>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_records = atoi(argv[1]);
    int key_min = atoi(argv[2]);
    int key_max = atoi(argv[3]);
    long value_min = atol(argv[4]);
    long value_max = atol(argv[5]);

    if (key_min >= key_max || value_min >= value_max) {
        fprintf(stderr, "Invalid range for keys or values.\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    RecordList *list = create_record_list(INITIAL_CAPACITY);
    if (!list) {
        fprintf(stderr, "Failed to initialize record list.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_records; ++i) {
        add_record(list, key_min, key_max, value_min, value_max, 5, 15);
    }

    sort_record_list(list);

    print_record_list(list);

    free_record_list(list);

    return EXIT_SUCCESS;
}
