#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int intValue;
    float floatValue;
    double doubleValue;
} Record;

// Constants for max sizes and thresholds
#define INITIAL_CAPACITY 10
#define MAX_SIZE 1000
#define MEMORY_LIMIT (1024 * 1024) // 1 MB

// Structure to manage dynamic array of records
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} RecordArray;

// Function prototypes
void initializeRecordArray(RecordArray *array);
void resizeRecordArray(RecordArray *array);
void freeRecordArray(RecordArray *array);
int addRandomRecord(RecordArray *array, int minInt, int maxInt, float minFloat, float maxFloat, double minDouble, double maxDouble);
void *externalDataSourceUpdate(void *arg);
void logMemoryUsage(size_t memoryUsed);

// Helper function to generate random values
int getRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

float getRandFloat(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

double getRandDouble(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Initialize record array
void initializeRecordArray(RecordArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->records = malloc(sizeof(Record) * array->capacity);
    if (!array->records) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

// Resize record array
void resizeRecordArray(RecordArray *array) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity && array->capacity < MAX_SIZE) {
        size_t newCapacity = array->capacity * 2;
        Record *newRecords = realloc(array->records, sizeof(Record) * newCapacity);
        if (!newRecords) {
            fprintf(stderr, "Failed to reallocate memory\n");
            exit(EXIT_FAILURE);
        }
        array->records = newRecords;
        array->capacity = newCapacity;
    }
    pthread_mutex_unlock(&array->lock);
}

// Free record array
void freeRecordArray(RecordArray *array) {
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

// Add a random record with values within specified ranges
int addRandomRecord(RecordArray *array, int minInt, int maxInt, float minFloat, float maxFloat, double minDouble, double maxDouble) {
    pthread_mutex_lock(&array->lock);

    size_t memoryUsed = (sizeof(Record) * (array->count + 1)) + sizeof(*array);

    if (memoryUsed > MEMORY_LIMIT || array->count >= MAX_SIZE) {
        logMemoryUsage(memoryUsed);
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory limit or max size reached
    }

    resizeRecordArray(array);

    Record newRecord;
    newRecord.intValue = getRandom(minInt, maxInt);
    newRecord.floatValue = getRandFloat(minFloat, maxFloat);
    newRecord.doubleValue = getRandDouble(minDouble, maxDouble);

    array->records[array->count++] = newRecord;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

// Simulate external data source update and handle safely
void *externalDataSourceUpdate(void *arg) {
    RecordArray *array = (RecordArray *)arg;

    while (1) {
        // Placeholder for updating records from an external data source
        sleep(5); // Simulating network delay

        pthread_mutex_lock(&array->lock);
        if (array->count > 0 && array->records[0].intValue % 10 == 0) { 
            printf("Threshold met, notification sent!\n");
        }
        pthread_mutex_unlock(&array->lock);
    }

    return NULL;
}

// Log memory usage
void logMemoryUsage(size_t memoryUsed) {
    fprintf(stderr, "Current memory usage: %zu bytes\n", memoryUsed);
}

int main() {
    srand(time(NULL));

    RecordArray array;
    initializeRecordArray(&array);

    pthread_t threadId;
    pthread_create(&threadId, NULL, externalDataSourceUpdate, &array);

    for (int i = 0; i < 50; ++i) { // Simulate adding records
        if (addRandomRecord(&array, -100, 100, 0.0f, 10.0f, -1.0, 1.0) != 0) {
            fprintf(stderr, "Unable to add more records due to memory constraints.\n");
            break;
        }
    }

    pthread_join(threadId, NULL);
    freeRecordArray(&array);

    return 0;
}
```

