```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1000
#define MAX_RECORDS_PER_SECOND 10000

typedef struct {
    int *offset;
    int *key;
    size_t capacity;
    pthread_mutex_t lock;
} RecordManager;

typedef struct {
    pthread_mutex_t mutex;
    void* memory_pool;
    size_t pool_size;
    size_t offset;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->memory_pool = malloc(initial_size);
    if (!pool->memory_pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = initial_size;
    pool->offset = 0;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->offset + size > pool->pool_size) {
        void* new_memory_pool = realloc(pool->memory_pool, pool->pool_size * 2);
        if (!new_memory_pool) {
            perror("Failed to resize memory pool");
            exit(EXIT_FAILURE);
        }
        pool->memory_pool = new_memory_pool;
        pool->pool_size *= 2;
    }
    void* ptr = (char*)pool->memory_pool + pool->offset;
    pool->offset += size;
    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->mutex);
}

int fetch_random_value(int min, int max) {
    // Simulate fetching a random value from an external service
    return rand() % (max - min + 1) + min;
}

void init_record_manager(RecordManager *rm, size_t initial_capacity, MemoryPool *pool) {
    pthread_mutex_init(&rm->lock, NULL);
    rm->capacity = initial_capacity;
    rm->offset = allocate_from_pool(pool, sizeof(int) * rm->capacity);
    rm->key = allocate_from_pool(pool, sizeof(int) * rm->capacity);

    for (size_t i = 0; i < rm->capacity; ++i) {
        ((int*)rm->offset)[i] = fetch_random_value(1, 100); // Example range
        ((int*)rm->key)[i] = fetch_random_value(1, 100);
    }
}

void resize_record_manager(RecordManager *rm, MemoryPool *pool, size_t new_capacity) {
    pthread_mutex_lock(&rm->lock);

    int* new_offset = allocate_from_pool(pool, sizeof(int) * new_capacity);
    memcpy(new_offset, rm->offset, sizeof(int) * rm->capacity);
    free(rm->offset);

    int* new_key = allocate_from_pool(pool, sizeof(int) * new_capacity);
    memcpy(new_key, rm->key, sizeof(int) * rm->capacity);
    free(rm->key);

    rm->offset = new_offset;
    rm->key = new_key;
    rm->capacity = new_capacity;

    for (size_t i = rm->capacity / 2; i < rm->capacity; ++i) {
        ((int*)rm->offset)[i] = fetch_random_value(1, 100);
        ((int*)rm->key)[i] = fetch_random_value(1, 100);
    }

    pthread_mutex_unlock(&rm->lock);
}

void cleanup_record_manager(RecordManager *rm) {
    free(rm->offset);
    free(rm->key);
    pthread_mutex_destroy(&rm->lock);
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, INITIAL_POOL_SIZE);

    RecordManager rm;
    init_record_manager(&rm, 500, &pool);

    // Simulate some operations
    if (rand() % 2) {
        resize_record_manager(&rm, &pool, 2000);
    }

    cleanup_record_manager(&rm);
    free_memory_pool(&pool);

    return 0;
}
```

### Key Design Choices:
- **Memory Pool**: A custom memory pool is used to manage allocations efficiently. The pool doubles in size when it runs out of space.
- **Thread Safety**: Mutexes are used to ensure thread safety during allocation and resizing operations.
- **Dynamic Resizing**: The `resize_record_manager` function handles dynamic resizing, doubling the capacity when needed.
- **Concurrency**: The design supports concurrent access by using mutex locks for critical sections.
- **Logging**: While not implemented here due to space constraints, logging can be added around memory allocation and resizing operations for monitoring.
- **Initialization Speed**: Initialization is done once during setup with potential asynchronous data fetching (simulated here).
- **Performance Optimization**: The use of a single global memory pool reduces fragmentation but may introduce contention. A per-thread pool could be explored if contention becomes an issue.

This implementation aims to balance performance and memory efficiency while supporting high throughput and low-latency operations.']

