typedef struct {
    int value;
} record;

#define PAGE_SIZE 4096

// Error codes
enum { SUCCESS, MEMORY_ALLOCATION_FAILURE };

// Memory pool structure for efficient memory management
typedef struct {
    void *memory_pool;
    size_t block_size;
    size_t total_blocks;
    pthread_mutex_t lock;
} mem_pool_t;

// Function prototypes
void* aligned_alloc(size_t alignment, size_t size);
mem_pool_t* create_memory_pool(size_t block_size, size_t total_blocks);
void destroy_memory_pool(mem_pool_t *pool);
int initialize_data_structures(long num_elements, int key_range_min, int key_range_max, int record_range_min, int record_range_max);

// Helper functions
static inline void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

static int validate_data_structures(long num_elements, long *offsets, int *keys, record *records) {
    // Validate the integrity of data structures
    for (long i = 0; i < num_elements; ++i) {
        if (offsets[i] != i || keys[i] == -1 || records[i].value == -1) {
            return 0;
        }
    }
    return 1;
}

// Function to initialize data structures
int initialize_data_structures(long num_elements, int key_range_min, int key_range_max, int record_range_min, int record_range_max) {
    pthread_t threads[3];
    long *offsets = aligned_alloc(PAGE_SIZE, num_elements * sizeof(long));
    int *keys = aligned_alloc(PAGE_SIZE, num_elements * sizeof(int));
    record *records = aligned_alloc(PAGE_SIZE, num_elements * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return MEMORY_ALLOCATION_FAILURE;
    }

    memset(keys, -1, num_elements * sizeof(int));
    for (long i = 0; i < num_elements; ++i) {
        records[i].value = -1;
    }

    // Initialize offsets
    void (*init_offsets)(long *, long) = [](long *offsets, long num_elements) {
        for (long i = 0; i < num_elements; ++i) {
            offsets[i] = i;
        }
    };
    init_offsets(offsets, num_elements);

    // Initialize keys with random values in parallel
    void* initialize_keys(void* arg) {
        int *keys = (int *)arg;
        long start = *(long*)arg;
        long end = *(long*)(arg + sizeof(long));
        for (long i = start; i < end; ++i) {
            keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        }
        return NULL;
    }

    pthread_create(&threads[0], NULL, initialize_keys, offsets);
    pthread_create(&threads[1], NULL, initialize_keys, offsets + num_elements / 2);
    pthread_create(&threads[2], NULL, initialize_keys, offsets + (num_elements / 2) * 3);

    for (int i = 0; i < 3; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Populate records with unique random values
    int *unique_values = malloc(num_elements * sizeof(int));
    if (!unique_values) {
        fprintf(stderr, "Memory allocation failed for unique values\n");
        free(offsets);
        free(keys);
        free(records);
        return MEMORY_ALLOCATION_FAILURE;
    }
    memset(unique_values, -1, num_elements * sizeof(int));

    void* populate_records(void* arg) {
        record *records = (record *)arg;
        long start = *(long*)arg;
        long end = *(long*)(arg + sizeof(long));
        for (long i = start; i < end; ++i) {
            int value;
            do {
                value = rand() % (record_range_max - record_range_min + 1) + record_range_min;
            } while (!__sync_bool_compare_and_swap(&unique_values[value], -1, i));
            records[i].value = value;
        }
        return NULL;
    }

    pthread_create(&threads[0], NULL, populate_records, records);
    pthread_create(&threads[1], NULL, populate_records, records + num_elements / 2);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(unique_values);

    if (!validate_data_structures(num_elements, offsets, keys, records)) {
        fprintf(stderr, "Data validation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return SUCCESS;
}

int main() {
    int result = initialize_data_structures(1000000, 1, 100000, 1, 100000);
    if (result == MEMORY_ALLOCATION_FAILURE) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }
    printf("Initialization successful\n");
    return EXIT_SUCCESS;
}
