#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

#define LOG_ERROR(msg) printf("ERROR: %s\n", msg)

int initialize_arrays(size_t config_size, size_t key_range, int min_value, int max_value, long **offsets, int **keys, record **records) {
    if (!offsets || !keys || !records) return -1;

    // Allocate memory for offsets and keys
    *offsets = (long *)malloc(config_size * sizeof(long));
    *keys = (int *)malloc(config_size * sizeof(int));
    if (*offsets == NULL || *keys == NULL) {
        LOG_ERROR("Failed to allocate memory for offsets or keys");
        return -1;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < config_size; ++i) {
        (*offsets)[i] = i * key_range;
        (*keys)[i] = rand() % key_range;
    }

    // Allocate memory for records
    *records = (record *)malloc(config_size * sizeof(record));
    if (*records == NULL) {
        LOG_ERROR("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set record values with random numbers in specified range
    pthread_t threads[4];
    size_t chunk_size = config_size / 4;

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, set_random_values, (void *)(*records + i * chunk_size))) {
            LOG_ERROR("Failed to create thread");
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Validate offsets
    if (!validate_offsets(*offsets, config_size)) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    return 0;
}

void *set_random_values(void *arg) {
    record *rec = (record *)arg;
    size_t size = *((size_t *)(arg + sizeof(record *)));

    for (size_t i = 0; i < size; ++i) {
        rec[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return NULL;
}

int validate_offsets(long *offsets, size_t size) {
    if (!offsets || size == 0) return 1;

    for (size_t i = 0; i < size; ++i) {
        if (offsets[i] < 0) return 0;

        for (size_t j = i + 1; j < size; ++j) {
            if (offsets[i] == offsets[j]) return 0;
        }
    }

    return 1;
}

int serialize_records(record *records, size_t size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        LOG_ERROR("Failed to open file for writing");
        return -1;
    }

    if (fwrite(records, sizeof(record), size, file) != size) {
        LOG_ERROR("Failed to write records to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    size_t config_size = 1000; // Example configuration size
    size_t key_range = 10;
    int min_value = 1;
    int max_value = 100;

    if (initialize_arrays(config_size, key_range, min_value, max_value, &offsets, &keys, &records) != 0) {
        return -1;
    }

    const char *filename = "records.bin";
    if (serialize_records(records, config_size, filename) != 0) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    free(offsets);
    free(keys);
    free(records);

    printf("Initialization and serialization completed successfully.\n");
    return 0;
}
