void initialize_data(int num_entries) {
    if (num_entries <= 0) return;

    // Allocate and initialize the array of doubles
    double *double_array = malloc(num_entries * sizeof(double));
    if (!double_array) exit(EXIT_FAILURE);

    // Allocate and initialize the array of char strings
    char **char_array = malloc(num_entries * sizeof(char *));
    if (!char_array) {
        free(double_array);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_entries; ++i) {
        char_array[i] = malloc(128 * sizeof(char));
        if (!char_array[i]) {
            while (--i >= 0) free(char_array[i]);
            free(char_array);
            free(double_array);
            exit(EXIT_FAILURE);
        }
    }

    // Allocate and initialize the array of struct point
    struct point *point_array = malloc(num_entries * sizeof(struct point));
    if (!point_array) {
        for (int i = 0; i < num_entries; ++i) free(char_array[i]);
        free(char_array);
        free(double_array);
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize the array of entry structures
    struct entry *entry_array = malloc(num_entries * sizeof(struct entry));
    if (!entry_array) {
        free(point_array);
        for (int i = 0; i < num_entries; ++i) free(char_array[i]);
        free(char_array);
        free(double_array);
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize the array of metadata objects
    struct metadata *metadata_array = malloc(num_entries * sizeof(struct metadata));
    if (!metadata_array) {
        free(entry_array);
        free(point_array);
        for (int i = 0; i < num_entries; ++i) free(char_array[i]);
        free(char_array);
        free(double_array);
        exit(EXIT_FAILURE);
    }

    // Seed random number generator
    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        double_array[i] = rand() / (double)RAND_MAX;

        int str_len = rand() % 64 + 1;
        for (int j = 0; j < str_len; ++j) {
            char_array[i][j] = (char)(rand() % 128);
        }
        char_array[i][str_len] = '\0';

        point_array[i].x = rand() / (float)RAND_MAX;
        point_array[i].y = rand() / (float)RAND_MAX;

        entry_array[i].value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        strcpy(entry_array[i].string, char_array[i]);
        entry_array[i].p = point_array[i];

        metadata_array[i].index = i;
        metadata_array[i].entry_ptr = &entry_array[i];
    }

    printf("Data initialized. Address of first entry: %p\n", (void *)&entry_array[0]);

    // Free all allocated memory
    free(double_array);
    for (int i = 0; i < num_entries; ++i) {
        free(char_array[i]);
    }
    free(char_array);
    free(point_array);
    free(entry_array);
    free(metadata_array);
}

int main() {
