use serde::{Serialize, Deserialize};
use serde_json;
use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead};
use tokio::sync::mpsc;
use reqwest::Client;
use rusqlite::{params, Connection};

#[derive(Serialize, Deserialize)]
struct Preference {
    key: String,
    value_type: ValueType,
    default_value: Option<Value>,
}

#[derive(Serialize, Deserialize, Clone)]
enum ValueType {
    String(String),
    Integer(i32),
    Boolean(bool),
}

#[derive(Serialize, Deserialize, Clone)]
enum Value {
    StringValue(String),
    IntegerValue(i32),
    BooleanValue(bool),
}

struct UserPreferences {
    preferences: HashMap<String, Preference>,
}

impl UserPreferences {
    fn new() -> Self {
        Self {
            preferences: HashMap::new(),
        }
    }

    fn add_preference(&mut self, key: &str, value_type: ValueType, default_value: Option<Value>) {
        self.preferences.insert(
            key.to_string(),
            Preference { key: key.to_string(), value_type, default_value },
        );
    }

    fn save_to_disk(&self, file_path: &str) -> Result<(), io::Error> {
        let serialized = serde_json::to_string_pretty(&self.preferences)?;
        fs::write(file_path, serialized)
    }

    fn load_from_disk(file_path: &str) -> Result<Self, io::Error> {
        let data = fs::read_to_string(file_path)?;
        let preferences: HashMap<String, Preference> = serde_json::from_str(&data)?;
        Ok(UserPreferences { preferences })
    }
}

async fn mock_network_service() -> mpsc::Receiver<impl std::fmt::Debug> {
    let (tx, rx) = mpsc::channel(32);

    tokio::spawn(async move {
        for i in 0..10 {
            if tx.send(format!("Response {}", i)).await.is_err() {
                break;
            }
            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
        }
    });

    rx
}

async fn send_request(url: &str, client: &Client) -> Result<(), reqwest::Error> {
    let res = client.get(url)
        .header("Authorization", "Bearer token")
        .timeout(std::time::Duration::from_secs(5))
        .send()
        .await?;

    println!("Response: {:?}", res.text().await?);
    Ok(())
}

fn query_user_settings(db_uri: &str, user_id: i32) -> Result<Vec<(String, String)>, rusqlite::Error> {
    let conn = Connection::open(db_uri)?;
    let mut stmt = conn.prepare("SELECT key, value FROM UserSettings WHERE userId = ?1")?;
    let settings_iter = stmt.query_map(params![user_id], |row| {
        Ok((row.get(0)?, row.get(1)?))
    })?;

    let mut settings = Vec::new();
    for setting in settings_iter {
        settings.push(setting?);
    }

    println!("Query: SELECT key, value FROM UserSettings WHERE userId = {:?}", user_id);
    println!("Result: {:?}", settings);

    Ok(settings)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut user_prefs = UserPreferences::new();
    user_prefs.add_preference("theme", ValueType::String("dark".to_string()), Some(Value::StringValue("default".to_string())));

    user_prefs.save_to_disk("preferences.json")?;
    let loaded_prefs = UserPreferences::load_from_disk("preferences.json")?;

    let client = Client::new();
    tokio::spawn(async move {
        if let Err(e) = send_request("https://example.com/api", &client).await {
            eprintln!("Request error: {}", e);
        }
    });

    let db_uri = "sqlite::memory:";
    query_user_settings(db_uri, 1)?;

    println!("Enter user IDs (comma-separated):");
    let stdin = io::stdin();
    let input = stdin.lock().lines().next().unwrap()?;

    let user_ids: Vec<i32> = input
        .split(',')
        .filter_map(|s| s.trim().parse::<i32>().ok())
        .collect();

    for user_id in user_ids {
        if let Ok(settings) = query_user_settings(db_uri, user_id) {
            let filtered_settings: Vec<(String, String)> = settings.into_iter()
                .filter_map(|(key, value)| {
                    if !value.is_empty() && key.starts_with("string") {
                        Some((key, value.to_uppercase()))
                    } else {
                        Some((key, value))
                    }
                })
                .collect();

            println!("User ID {}: {:?}", user_id, filtered_settings);
        } else {
            eprintln!("Error querying settings for User ID {}", user_id);
        }
    }

    Ok(())
}
