// Add a new record
void addRecord(record **records, size_t *count, int minRange, int maxRange) {
    *records = realloc(*records, (*count + 1) * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for adding new record\n");
        return;
    }

    int key;
    do {
