    }

    printf("Enter strings (type 'done' to finish):\n");
    while (scanf("%255s", tempStr) == 1 && strcmp(tempStr, "done") != 0) {
        inputStrings = realloc(inputStrings, (numInputStrings + 1) * sizeof(char*));
        if (!inputStrings) {
            fprintf(stderr, "Memory allocation failed for strings\n");
            return;
        }
        inputStrings[numInputStrings] = strdup(tempStr);
        ++numInputStrings;

        // Clear the buffer in case of invalid input
        while (getchar() != '\n');
    }
}

