        if (manager->records[i] && manager->records[i]->key == key)
            return manager->records[i];
    }
    return NULL;
}

void handle_duplicate_key(RecordManager *manager, int key, record **new_record) {
    pthread_mutex_lock(&manager->lock);
    record *existing_record = find_record(manager, key);

    if (existing_record) {
        // Custom error handling or overwriting logic
        printf("Duplicate key %d found. Overwriting existing record.\n", key);
        free(existing_record->data); // Free old data before overwriting
        *new_record = existing_record;
    } else {
        if (manager->capacity == 0 || NULL == *(manager->records + manager->capacity - 1)) {
            manager->records[manager->capacity++] = malloc(sizeof(record));
        }
        *new_record = manager->records[manager->capacity++];
    }

    pthread_mutex_unlock(&manager->lock);
}

void efficiently_manage_records(RecordManager *manager, int key, int value, const char *data) {
    record *record_to_update;
    handle_duplicate_key(manager, key, &record_to_update);

    record_to_update->key = key;
    record_to_update->value = value;

    size_t data_len = strlen(data);
    unsigned char encrypted_data[RECORD_SIZE];
    encrypt_data((unsigned char *)data, data_len, encrypted_data);

    if (record_to_update->data) {
        free(record_to_update->data);
    }
    record_to_update->data = malloc(RECORD_SIZE);
    memcpy(record_to_update->data, encrypted_data, RECORD_SIZE);
}

void cleanup_record_manager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]->data);
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

