    RecordManager *manager = create_record_manager(10);

    efficiently_manage_records(manager, 1, 100, "Sensitive Data");
    efficiently_manage_records(manager, 2, 200, "More Sensitive Data");

    // Perform cleanup
    cleanup_record_manager(manager);

    return 0;
}
