#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long* allocate_offsets(int num_records) {
    return (long*)malloc(num_records * sizeof(long));
}

int* allocate_keys(int num_records) {
    return (int*)malloc(num_records * sizeof(int));
}

record* allocate_records(int num_records, long* offsets, int* keys) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
    }

    return records;
}

record* init_data(int num_records, long min_offset_value, long max_offset_value) {
    pthread_mutex_lock(&lock);

    if (num_records <= 0) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    long *offsets = allocate_offsets(num_records);
    int *keys = allocate_keys(num_records);

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (max_offset_value - min_offset_value + 1) + min_offset_value;
        keys[i] = rand(); // Random key value
    }

    record *records = allocate_records(num_records, offsets, keys);

    if (!records) {
        free(offsets);
        free(keys);
    }

    pthread_mutex_unlock(&lock);

    return records;
}

record* get_record(record *records, int num_records, int index) {
    if (index < 0 || index >= num_records) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    record *result = &records[index];
    pthread_mutex_unlock(&lock);

    return result;
}

void free_data(record *records, long *offsets, int *keys) {
    pthread_mutex_lock(&lock);

    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);

    pthread_mutex_unlock(&lock);
}

// Example of a simple compression mechanism
void compress_data(record *records, long *offsets, int *keys, int num_records) {
    // Simple sorting to reduce fragmentation and improve cache locality
    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = 0; j < num_records - i - 1; ++j) {
            if (*offsets[j] > *offsets[j + 1]) {
                // Swap offsets
                long temp_offset = offsets[j];
                offsets[j] = offsets[j + 1];
                offsets[j + 1] = temp_offset;

                // Swap corresponding keys and records pointers
                int temp_key = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;

                record temp_record = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp_record;
            }
        }
    }
}

// Main function for demonstration
int main() {
    srand(time(NULL)); // Seed random number generator

    int num_records = 1000; // Example number of records
    record *records = init_data(num_records, 10, 1000);

    if (records) {
        compress_data(records, ((record*)malloc(sizeof(record)))->offset_ptr, 
                      ((record*)malloc(sizeof(record)))->key_ptr, num_records);

        for (int i = 0; i < num_records; ++i) {
            record *rec = get_record(records, num_records, i);
            if (rec) {
                printf("Record %d: Value=%d, Offset=%ld, Key=%d\n", i, rec->value, *rec->offset_ptr, *rec->key_ptr);
            }
        }

        free_data(records, ((record*)malloc(sizeof(record)))->offset_ptr, 
                  ((record*)malloc(sizeof(record)))->key_ptr);
    } else {
        printf("Failed to initialize data.\n");
    }

    return 0;
}
