// Function to create and initialize data structures
DataManager* init_data_manager(size_t pointCount, double minValue, double maxValue) {
    DataManager *manager = malloc(sizeof(DataManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);

    manager->pointCount = pointCount;
    manager->doublesArray = calloc(pointCount, sizeof(double));
    if (!manager->doublesArray) {
        free(manager);
        pthread_mutex_destroy(&manager->lock);
        return NULL;
    }

    manager->pointsArray = malloc(pointCount * sizeof(Point));
    if (!manager->pointsArray) {
        free(manager->doublesArray);
        free(manager);
        pthread_mutex_destroy(&manager->lock);
        return NULL;
    }

    char locationTemplate[50] = "Location of point: ";

    for (size_t i = 0; i < pointCount; ++i) {
        manager->doublesArray[i] = generate_random_double(minValue, maxValue);

        manager->pointsArray[i].value = manager->doublesArray[i];
        manager->pointsArray[i].identifier = 'A' + i;

        char *location = malloc(strlen(locationTemplate) + 2);
        if (!location) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(manager->pointsArray[j].location);
            }
            free(manager->doublesArray);
            free(manager->pointsArray);
            free(manager);
            pthread_mutex_destroy(&manager->lock);
            return NULL;
        }

        snprintf(location, strlen(locationTemplate) + 2, "%s%s", locationTemplate, &manager->pointsArray[i].identifier);
        manager->pointsArray[i].location = location;
    }

    return manager;
}

// Function to retrieve a specific point by its index
Point* get_point(DataManager *manager, size_t index) {
    if (index >= manager->pointCount) return NULL;

    pthread_mutex_lock(&manager->lock);
    Point *result = &manager->pointsArray[index];
    pthread_mutex_unlock(&manager->lock);

    return result;
}

// Function to free all allocated memory
void free_data_manager(DataManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->pointCount; ++i) {
        free(manager->pointsArray[i].location);
    }

    free(manager->doublesArray);
    free(manager->pointsArray);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

