#include <string.h>

typedef struct Item {
    int identifier;
    double value;
    char* string;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

// Function to initialize the list with a specified number of items
Node* initList(int count) {
    Node* head = NULL;
    for (int i = 1; i <= count; ++i) {
        insertItem(&head, i, (double)i, strndup("Default", 7));
    }
    return head;
}

// Function to insert a new item at a specified position in the list
void insertItem(Node** head, int identifier, double value, const char* string) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    newNode->item.identifier = identifier;
    newNode->item.value = value;
    newNode->item.string = strdup(string);
    newNode->next = NULL;

    if (*head == NULL || (*head)->item.identifier >= identifier) {
        newNode->next = *head;
        *head = newNode;
        return;
    }

    Node* current = *head;
    while (current->next != NULL && current->next->item.identifier < identifier) {
        current = current->next;
    }

    newNode->next = current->next;
    current->next = newNode;
}

// Function to search for an item by its identifier and retrieve its value and string content
Item* findItem(Node* head, int identifier, double* value, char** string) {
    Node* current = head;
    while (current != NULL) {
        if (current->item.identifier == identifier) {
            *value = current->item.value;
            *string = current->item.string;
            return &current->item;
        }
        current = current->next;
    }
    return NULL;
}

// Function to free the memory of the list
void freeList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->item.string);
        free(temp);
    }
}

// Example usage
int main() {
    int count = 5;
    Node* itemList = initList(count);

    double value;
    char* string;

    // Insert a new item
    insertItem(&itemList, 3, 9.8, "Inserted");

    // Search for an item
    Item* foundItem = findItem(itemList, 3, &value, &string);
    if (foundItem) {
        printf("Found: ID=%d, Value=%.2f, String=%s\n", foundItem->identifier, value, string);
    }

    // Free the list
    freeList(itemList);

    return 0;
}
