static char **recordTypes = NULL;
static size_t numRecordTypes = 0;
static enum { LOG_MINIMAL, LOG_DETAILED } logLevel = LOG_DETAILED;

// Function to log messages based on verbosity level
void logMessage(const char *level, const char *message) {
    if (logLevel == LOG_DETAILED || (!strcmp(level, "ERROR") && logLevel != LOG_MINIMAL)) {
        printf("[%s] %s\n", level, message);
    }
}

// Function to initialize records with random values
void initializeRecords(Record *records, size_t count, int minVal, int maxVal) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].offset = rand() % 100000;
        records[i].key = rand() % 1000;
        records[i].value = minVal + rand() % (maxVal - minVal + 1);
    }
}

// Function to register new record types
void registerRecordType(const char *typeName) {
    pthread_mutex_lock(&mutex);
    char **newTypes = realloc(recordTypes, sizeof(char *) * (numRecordTypes + 1));
    if (!newTypes) {
        logMessage("ERROR", "Memory allocation failed during type registration.");
        return;
    }
    recordTypes = newTypes;
    recordTypes[numRecordTypes] = strdup(typeName);
    ++numRecordTypes;
    pthread_mutex_unlock(&mutex);
}

// Function to manage records
void initializeAndManageRecords(size_t initialCount, int minVal, int maxVal) {
    Record *records = malloc(sizeof(Record) * initialCount);
    if (!records) {
        logMessage("ERROR", "Memory allocation failed for records.");
        return;
    }
    logMessage("INFO", "Allocated memory for initial records.");

    initializeRecords(records, initialCount, minVal, maxVal);

    // Simulating dynamic resizing
    size_t newCount = initialCount * 2;
    Record *newRecords = realloc(records, sizeof(Record) * newCount);
    if (!newRecords && initialCount != 0) {
        logMessage("ERROR", "Memory reallocation failed.");
        free(records);
        return;
    }
    records = newRecords;

    // Initialize additional records after resizing
    initializeRecords(&records[initialCount], newCount - initialCount, minVal, maxVal);
    logMessage("INFO", "Resized and initialized additional records.");

    // Dummy loop to simulate operations on records (e.g., retrieval/iteration)
    for (size_t i = 0; i < newCount; ++i) {
        // Example operation
    }

    free(records); // Ensure proper memory deallocation
    logMessage("INFO", "Memory freed after managing records.");
}

