    LogLevel levels[] = {DEBUG, INFO, WARN};
    int num_entries = sizeof(messages) / sizeof(messages[0]);

    LogEntry **entries = malloc(num_entries * sizeof(LogEntry*));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < num_entries; ++i) {
        entries[i] = create_log_entry(levels[i], messages[i]);
        if (!entries[i]) {
            fprintf(stderr, "Failed to create log entry %d\n", i);
            // Handle cleanup
            while (--i >= 0) free(entries[i]->message), free(entries[i]);
            free(entries);
            return 1;
        }
        insert_into_index(log_index, entries[i]);
    }

    compress_logs(entries[0], num_entries);

    for (int i = 0; i < num_entries; ++i) {
        free(entries[i]->message);
        free(entries[i]);
    }

    free(entries);
    pthread_mutex_destroy(&log_index->lock);
    free(log_index);

    return 0;
}
```

### Design Considerations:
