typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t *indices;
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
} RecordManager;

RecordManager* create_manager() {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    manager->offsets = calloc(manager->capacity, sizeof(long));
    manager->keys = calloc(manager->capacity, sizeof(int));
    manager->records = calloc(manager->capacity, sizeof(record));
    manager->indices = calloc(manager->capacity, sizeof(size_t));

    if (!manager->offsets || !manager->keys || !manager->records || !manager->indices) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager->indices);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_manager(RecordManager *manager) {
    size_t new_capacity = manager->capacity * 2;

    long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));
    record *new_records = realloc(manager->records, new_capacity * sizeof(record));
    size_t *new_indices = realloc(manager->indices, new_capacity * sizeof(size_t));

    if (!new_offsets || !new_keys || !new_records || !new_indices) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        return;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->indices = new_indices;

    manager->capacity = new_capacity;
}

void add_record(RecordManager *manager, int key, record rec) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_manager(manager);
    }

    manager->keys[manager->count] = key;
    manager->records[manager->count] = rec;
    manager->indices[manager->count] = manager->count;
    manager->offsets[manager->count] = (long)(rand() % 100); // Random offset for demonstration

    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

record* get_record_array(RecordManager *manager) {
    return manager->records;
}

void delete_manager(RecordManager *manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->indices);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

record* manage_records() {
    RecordManager *manager = create_manager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < MAX_RECORDS && manager->count < manager->capacity; ++i) {
        int key = rand() % 1000; // Random key
        record rec = {rand() % 100}; // Random value between 0 and 99
        add_record(manager, key, rec);
    }

    return get_record_array(manager);
}

int main() {
