    if (max_measurements > MAX_MEASUREMENTS) return -1;

    data->count = 0;
    pthread_mutex_init(&data->lock, NULL);

    // Dynamically allocate memory for arrays
    double *doubles = (double *)malloc(max_measurements * sizeof(double));
    char **strings = (char **)malloc(max_measurements * sizeof(char *));
    struct {
