        char c_string[50];
    } *complex_structs = (struct { double d_value; char c_string[50]; } *)
                         malloc(max_measurements * sizeof(struct { double d_value; char c_string[50]; }));

    if (!doubles || !strings || !complex_structs) {
        return -1;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < max_measurements; ++i) {
        do {
            doubles[i] = (double)(rand() % (int)(DOUBLE_RANGE_MAX * 100)) / 100.0;
        } while ((i > 0 && fabs(doubles[i] - doubles[i - 1]) < 0.01) || (data->count && doubles[i] + data->measurements[data->count - 1].value > SUM_THRESHOLD));

        strings[i] = (char *)malloc(50 * sizeof(char));
        snprintf(complex_structs[i].c_string, 50, "string_%zu", i);

        // Initialize the MeasurementData measurements
        pthread_mutex_lock(&data->lock);
        if (data->count < max_measurements) {
            data->measurements[data->count].value = doubles[i];
            data->measurements[data->count].name = strings[i];
            data->count++;
        }
        pthread_mutex_unlock(&data->lock);
    }

    free(doubles);
    free(complex_structs);

    return 0;
}

int serialize_and_save(MeasurementData *data, const char *file_path) {
    FILE *file = fopen(file_path, "wb");
    if (!file) return -1;

    size_t bytes_written = 0;
    pthread_mutex_lock(&data->lock);
    for (int i = 0; i < data->count; ++i) {
        fwrite(&data->measurements[i].value, sizeof(double), 1, file);
        int name_length = strlen(data->measurements[i].name) + 1;
        fwrite(&name_length, sizeof(int), 1, file);
        fwrite(data->measurements[i].name, sizeof(char), name_length, file);

        bytes_written += sizeof(double) + sizeof(int) + name_length;

        // Simulate I/O limit per second
        if (bytes_written > IO_LIMIT_PER_SECOND) {
            usleep(1000000);  // Sleep for 1 second
            bytes_written = 0;
        }
    }
    pthread_mutex_unlock(&data->lock);

    fclose(file);
    return 0;
}

const char* save_measurements(size_t max_measurements, const char *file_path) {
    MeasurementData data;
    if (initialize_measurement_data(&data, max_measurements) != 0) {
        return "Error: Initialization failed.";
    }

    if (serialize_and_save(&data, file_path) != 0) {
        return "Error: Serialization or saving failed.";
    }

    // Clean up
    pthread_mutex_lock(&data.lock);
    for (int i = 0; i < data.count; ++i) {
        free(data.measurements[i].name);
    }
    pthread_mutex_unlock(&data.lock);

    pthread_mutex_destroy(&data.lock);

    return file_path;
}

// Example usage
int main() {
    const char *file_path = save_measurements(100, "measurements.bin");
    if (strstr(file_path, "Error:")) {
        fprintf(stderr, "%s\n", file_path);
    } else {
        printf("Data saved to %s\n", file_path);
    }
    return 0;
}
