#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the Metadata structure
typedef struct {
    char **tags;
    int tag_count;
    int ref_count;
    int version;
} Metadata;

// Define the Transaction structure
typedef struct {
    time_t timestamp;
    double amount;
    Metadata *metadata;
} Transaction;

// Define the Collection structure
typedef struct {
    Transaction **transactions;
    size_t capacity;
    size_t count;
} TransactionCollection;

// Function prototypes
TransactionCollection* init_transaction_collection(size_t initial_capacity);
void free_transaction_collection(TransactionCollection *collection);
int add_tag(Transaction *transaction, const char *tag);
int remove_tag(Transaction *transaction, const char *tag);
void adjust_ref_count(Metadata *metadata, int delta);
Transaction* get_transaction_by_index(TransactionCollection *collection, size_t index);
void merge_collections(TransactionCollection *dest, TransactionCollection *src);

// Function implementations
TransactionCollection* init_transaction_collection(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    TransactionCollection *collection = malloc(sizeof(TransactionCollection));
    if (!collection) return NULL;

    collection->transactions = calloc(initial_capacity, sizeof(Transaction *));
    if (!collection->transactions) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    // Initialize transactions
    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < initial_capacity; ++i) {
        Transaction *transaction = malloc(sizeof(Transaction));
        if (!transaction) {
            free_transaction_collection(collection);
            return NULL;
        }

        transaction->timestamp = time(NULL);
        transaction->amount = (double)(rand() % 1001); // Random amount between 0 and 1000

        Metadata *metadata = malloc(sizeof(Metadata));
        if (!metadata) {
            free(transaction);
            free_transaction_collection(collection);
            return NULL;
        }

        metadata->tags = NULL;
        metadata->tag_count = 0;
        metadata->ref_count = 1; // Initial reference count
        metadata->version = 1;

        transaction->metadata = metadata;

        collection->transactions[i] = transaction;
    }

    collection->count = initial_capacity;
    return collection;
}

void free_transaction_collection(TransactionCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->transactions[i]) {
            Metadata *metadata = collection->transactions[i]->metadata;
            for (int j = 0; j < metadata->tag_count; ++j) {
                free(metadata->tags[j]);
            }
            free(metadata->tags);
            free(collection->transactions[i]->metadata);
            free(collection->transactions[i]);
        }
    }

    free(collection->transactions);
    free(collection);
}

int add_tag(Transaction *transaction, const char *tag) {
    if (!transaction || !tag) return -1;

    Metadata *metadata = transaction->metadata;
    metadata->tags = realloc(metadata->tags, (metadata->tag_count + 1) * sizeof(char *));
    if (!metadata->tags) return -1;

    metadata->tags[metadata->tag_count] = strdup(tag);
    if (!metadata->tags[metadata->tag_count]) {
        free(metadata->tags);
        metadata->tags = NULL;
        return -1;
    }

    metadata->tag_count++;
    metadata->version++;

    return 0;
}

int remove_tag(Transaction *transaction, const char *tag) {
    if (!transaction || !tag) return -1;

    Metadata *metadata = transaction->metadata;
    for (int i = 0; i < metadata->tag_count; ++i) {
        if (strcmp(metadata->tags[i], tag) == 0) {
            free(metadata->tags[i]);
            for (int j = i; j < metadata->tag_count - 1; ++j) {
                metadata->tags[j] = metadata->tags[j + 1];
            }
            metadata->tags = realloc(metadata->tags, (metadata->tag_count - 1) * sizeof(char *));
            if (!metadata->tags && metadata->tag_count > 0) return -1;

            metadata->tag_count--;
            metadata->version++;
            return 0;
        }
    }

    return -1; // Tag not found
}

void adjust_ref_count(Metadata *metadata, int delta) {
    if (!metadata) return;

    metadata->ref_count += delta;
    metadata->version++;
}

Transaction* get_transaction_by_index(TransactionCollection *collection, size_t index) {
    if (!collection || index >= collection->count) return NULL;
    return collection->transactions[index];
}

void merge_collections(TransactionCollection *dest, TransactionCollection *src) {
    if (!dest || !src) return;

    // Increase capacity if needed
    if (dest->count + src->count > dest->capacity) {
        size_t new_capacity = dest->capacity * 2;
        while (new_capacity < dest->count + src->count) new_capacity *= 2;

        dest->transactions = realloc(dest->transactions, new_capacity * sizeof(Transaction *));
        if (!dest->transactions) return;

        dest->capacity = new_capacity;
    }

    // Copy transactions from source to destination
    for (size_t i = 0; i < src->count; ++i) {
        Transaction *transaction = src->transactions[i];
        dest->transactions[dest->count++] = transaction;
    }
}
```']

