    sys->records[sys->count].value = value;
    sys->records[sys->count].offset_ptr = &sys->offsets[sys->count];
    sys->records[sys->count].key_ptr = &sys->keys[sys->count];

    sys->count++;
    return 0;
}

record* get_record_by_index(storage_system *sys, size_t index) {
