['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>

#define CACHE_SIZE 1000

typedef struct CacheNode {
    int key;
    long offset;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    CacheNode **table;
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->count = 0;
    cache->head = NULL;
    cache->tail = NULL;
    cache->table = calloc(capacity, sizeof(CacheNode *));
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void move_to_head(LRUCache *cache, CacheNode *node) {
    if (cache->head == node) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (cache->tail == node) cache->tail = node->prev;

    node->next = cache->head;
    node->prev = NULL;
    if (cache->head) cache->head->prev = node;
    cache->head = node;
    if (!cache->tail) cache->tail = node;
}

void remove_node(LRUCache *cache, CacheNode *node) {
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (cache->head == node) cache->head = node->next;
    if (cache->tail == node) cache->tail = node->prev;

    free(node);
}

CacheNode* get_node(LRUCache *cache, int key) {
    size_t index = abs(key % cache->capacity);
    CacheNode *node = cache->table[index];
    while (node && node->key != key) node = node->next;
    return node;
}

void insert_cache(LRUCache *cache, int key, long offset) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = get_node(cache, key);
    if (node) {
        node->offset = offset;
        move_to_head(cache, node);
    } else {
        if (cache->count == cache->capacity) {
            remove_node(cache, cache->tail);
            size_t index = abs(cache->tail->key % cache->capacity);
            cache->table[index] = NULL;
            cache->count--;
        }
        node = malloc(sizeof(CacheNode));
        node->key = key;
        node->offset = offset;
        node->prev = NULL;
        node->next = cache->head;

        if (cache->head) cache->head->prev = node;
        cache->head = node;
        if (!cache->tail) cache->tail = node;

        size_t index = abs(key % cache->capacity);
        node->next = cache->table[index];
        cache->table[index] = node;
        cache->count++;
    }

    pthread_mutex_unlock(&cache->lock);
}

long lookup_cache(LRUCache *cache, int key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = get_node(cache, key);
    long offset = -1;
    if (node) {
        move_to_head(cache, node);
        offset = node->offset;
    }

    pthread_mutex_unlock(&cache->lock);
    return offset;
}

void delete_cache(LRUCache *cache, int key) {
    pthread_mutex_lock(&cache->lock);

    size_t index = abs(key % cache->capacity);
    CacheNode *node = get_node(cache, key);
    if (node) {
        remove_node(cache, node);
        cache->table[index] = node->next;
        cache->count--;
    }

    pthread_mutex_unlock(&cache->lock);
}

void serialize_cache(LRUCache *cache, const char *filename) {
    pthread_mutex_lock(&cache->lock);

    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&cache->capacity, sizeof(size_t), 1, file);
        CacheNode *current = cache->head;
        while (current) {
            fwrite(&(current->key), sizeof(int), 1, file);
            fwrite(&(current->offset), sizeof(long), 1, file);
            current = current->next;
        }
    }

    fclose(file);
    pthread_mutex_unlock(&cache->lock);
}

void deserialize_cache(LRUCache *cache, const char *filename) {
    pthread_mutex_lock(&cache->lock);

    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t capacity;
        fread(&capacity, sizeof(size_t), 1, file);
        while (!feof(file)) {
            int key;
            long offset;
            if (fread(&key, sizeof(int), 1, file) == 1 &&
                fread(&offset, sizeof(long), 1, file) == 1) {
                insert_cache(cache, key, offset);
            }
        }
    }

    fclose(file);
    pthread_mutex_unlock(&cache->lock);
}

void destroy_cache(LRUCache *cache) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;
    while (current) {
        CacheNode *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache->table);
    free(cache);
}
