Record* initialize_data_structure(size_t num_records, int min_key, int max_key,
                                  size_t max_length, unsigned long seed) {

    if (num_records == 0 || min_key > max_key || max_length == 0) {
        log_error("Invalid input parameters.");
        return NULL;
    }

    // Set random seed
    srand(seed ? seed : time(NULL));

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_error("Memory allocation failed for records array.");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        // Initialize key with a random value within the specified range
        records[i].key = min_key + rand() % (max_key - min_key + 1);

        // Randomly set status to 'A' or 'B'
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        // Allocate memory for struct data
        size_t length = rand() % max_length + 1; // Ensure non-zero length
        records[i].data_ptr = malloc(sizeof(Data));
        if (!records[i].data_ptr) {
            log_error("Memory allocation failed for data structure.");

            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(records[j].data_ptr);
            }
            free(records);

            return NULL;
        }

        records[i].data_ptr->length = length;

