#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char *buffer;
} Record;

Record* create_records(size_t num_records, int min_key, int max_key) {
    if (num_records == 0 || min_key > max_key) return NULL;

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    long base_offset = 1000;  // Base offset for initialization
    int base_key = 10;        // Base key value

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = base_offset + (long)i * 50;
        records[i].key = base_key + rand() % (max_key - min_key + 1);

        size_t buffer_size = i + 1; // Example of dynamic sizing based on index
        records[i].buffer = (char *)malloc(buffer_size);
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed for buffer\n");

            // Free any previously allocated memory before returning
            while (--i >= 0) free(records[i].buffer);
            free(records);
            return NULL;
        }
    }

    return records;
}

void free_records(Record *records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
