            // Free previously allocated memory in case of failure
            while (--i >= 0) free(sensorData->data[i].temperatureReadings);
            free(sensorData->records);
            free(sensorData->data);
            free(sensorData);
            return NULL;
        }

        for (size_t j = 0; j < maxSamplesPerRecord; ++j) {
            sensorData->data[i].temperatureReadings[j] = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        }

        sensorData->data[i].timestampIndex = -1;
        sensorData->data[i].isValid = 1;

        // Update total memory allocated
        sensorData->totalMemoryAllocated += maxSamplesPerRecord * sizeof(double);
    }

    return sensorData;
}

void freeSensorData(SensorData* sensorData) {
