}

Record* getRecordByKey(Record* records, size_t num_records, int key) {
    pthread_mutex_lock(&record_lock);
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            Record* result = malloc(sizeof(Record));
            if (!result) {
                pthread_mutex_unlock(&record_lock);
                return NULL;
            }
            *result = records[i];
            pthread_mutex_unlock(&record_lock);
            return result;
        }
    }
    pthread_mutex_unlock(&record_lock);
    return NULL;
}

void freeRecords(Record* records) {
    free(records);
}
