#include <time.h>
#include <pthread.h>

#define STRING_SIZE 256

typedef struct {
    double value;
    char filename[STRING_SIZE];
    int id;
} data_entry;

// Function to generate a unique filename based on the current date and time
void generate_unique_filename(char *filename, int entry_id) {
    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);

    snprintf(filename, STRING_SIZE, "entry_%d_%04d%02d%02d-%02d%02d%02d.txt",
             entry_id,
             tm_info->tm_year + 1900,
             tm_info->tm_mon + 1,
             tm_info->tm_mday,
             tm_info->tm_hour,
             tm_info->tm_min,
             tm_info->tm_sec);
}

// Function to allocate and initialize arrays
data_entry *allocate_and_initialize(size_t num_entries, double **doubles, char ***strings) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for data entries
    data_entry *entries = malloc(num_entries * sizeof(data_entry));
    if (!entries) {
        perror("Failed to allocate memory for data entries");
        return NULL;
    }

    // Allocate memory for doubles and strings arrays
    *doubles = malloc(num_entries * sizeof(double));
    *strings = malloc(num_entries * sizeof(char *));
    if (!(*doubles) || !(*strings)) {
        free(entries);
        perror("Failed to allocate memory for auxiliary arrays");
        return NULL;
    }

    // Initialize entries and log filename generation
    for (size_t i = 0; i < num_entries; ++i) {
        (*doubles)[i] = (double)i;

        // Allocate memory for each string
        (*strings)[i] = malloc(STRING_SIZE * sizeof(char));
        if (!(*strings)[i]) {
            perror("Failed to allocate memory for string");
            free(entries);
            free(*doubles);
            for (size_t j = 0; j < i; ++j) {
                free((*strings)[j]);
            }
            free(*strings);
            return NULL;
        }

        pthread_mutex_lock(&mutex); // Ensure unique filename generation is thread-safe
        generate_unique_filename((*strings)[i], i);
        printf("Generated filename: %s\n", (*strings)[i]); // Log the generated filename
        pthread_mutex_unlock(&mutex);

        entries[i].value = (*doubles)[i];
        strncpy(entries[i].filename, (*strings)[i], STRING_SIZE - 1);
        entries[i].id = (int)i;
    }

    pthread_mutex_destroy(&mutex);
    return entries;
}

// Example usage
int main() {
    size_t num_entries = 10;
    double *doubles;
    char **strings;

    data_entry *entries = allocate_and_initialize(num_entries, &doubles, &strings);

    if (entries) {
        // Use the allocated and initialized arrays

        // Free memory after use
        free(entries);
        free(doubles);
        for (size_t i = 0; i < num_entries; ++i) {
            free(strings[i]);
        }
        free(strings);
    }

    return 0;
}
