#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_allocations;
    size_t total_deallocations;
    size_t max_memory_usage;
} RecordManager;

RecordManager* create_manager(size_t initial_capacity, size_t max_memory) {
    RecordManager *manager = (RecordManager *)malloc(sizeof(RecordManager));
    manager->records = (record **)calloc(initial_capacity, sizeof(record *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_allocations = 0;
    manager->total_deallocations = 0;
    manager->max_memory_usage = max_memory;

    return manager;
}

void free_manager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i] != NULL) {
            free(manager->records[i]->offset);
            free(manager->records[i]->key);
            free(manager->records[i]);
            manager->total_deallocations++;
        }
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void manage_memory(RecordManager *manager, size_t required_size) {
    if (manager->count + 1 > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        while (new_capacity < manager->count + 1) {
            new_capacity *= 2;
        }

        record **new_records = (record **)realloc(manager->records, new_capacity * sizeof(record *));
        if (new_records != NULL) {
            for (size_t i = manager->capacity; i < new_capacity; ++i) {
                new_records[i] = NULL;
            }
            manager->records = new_records;
            manager->capacity = new_capacity;
            manager->total_allocations++;
        } else {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
    }
}

record* create_record(int min_val, int max_val) {
    record *new_rec = (record *)malloc(sizeof(record));
    if (new_rec == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    new_rec->value = rand() % (max_val - min_val + 1) + min_val;
    new_rec->offset = (long *)malloc(sizeof(long));
    if (new_rec->offset == NULL) {
        free(new_rec);
        fprintf(stderr, "Failed to allocate memory for offset\n");
        exit(EXIT_FAILURE);
    }
    *new_rec->offset = rand() % 100;

    new_rec->key = (int *)malloc(sizeof(int));
    if (new_rec->key == NULL) {
        free(new_rec->offset);
        free(new_rec);
        fprintf(stderr, "Failed to allocate memory for key\n");
        exit(EXIT_FAILURE);
    }
    *new_rec->key = rand() % 100;

    return new_rec;
}

void add_record(RecordManager *manager, int min_val, int max_val) {
    pthread_mutex_lock(&manager->lock);

    manage_memory(manager, sizeof(record));

    if (manager->count < manager->capacity) {
        record *new_record = create_record(min_val, max_val);
        manager->records[manager->count++] = new_record;
        manager->total_allocations++;
    }

    pthread_mutex_unlock(&manager->lock);
}

void remove_record(RecordManager *manager, size_t index) {
    if (index >= manager->count) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->records[index]->offset);
    free(manager->records[index]->key);
    free(manager->records[index]);
    manager->records[index] = NULL;
    manager->total_deallocations++;

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->records[i] = manager->records[i + 1];
    }
    manager->records[manager->count - 1] = NULL;
    --manager->count;

    pthread_mutex_unlock(&manager->lock);
}

record* get_record(RecordManager *manager, size_t index) {
    if (index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    record *rec = manager->records[index];
    pthread_mutex_unlock(&manager->lock);

    return rec;
}

void iterate_records(RecordManager *manager, void (*operation)(record *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        operation(manager->records[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void print_record_metadata(record *rec) {
    printf("Record Metadata:\n");
    printf("Value: %d\n", rec->value);
    printf("Offset: %ld\n", *(rec->offset));
    printf("Key: %d\n", *(rec->key));
}

const char* record_metadata() {
    return "record metadata: int value, long offset pointer, int key pointer";
}

void find_and_print_largest_value(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == 0) {
        printf("No records available.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    int largest = manager->records[0]->value;
    for (size_t i = 1; i < manager->count; ++i) {
        if (manager->records[i]->value > largest) {
            largest = manager->records[i]->value;
        }
    }

    printf("Largest value: %d\n", largest);

    pthread_mutex_unlock(&manager->lock);
}
