['Here's the implementation in C for managing a dynamic collection of records, including methods for initialization, retrieval, memory management, and concurrency handling:

```c
#include <stdio.h>
#include <stdlib.h>
import "pthread.h"

#define INITIAL_CAPACITY 100
#define KEY_RANGE 1000
#define VALUE_RANGE 100

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

// Helper function to initialize the collection
int init_collection(Collection *collection, size_t initial_capacity) {
    if (pthread_mutex_init(&collection->lock, NULL)) return -1;

    collection->capacity = initial_capacity;
    collection->count = 0;

    collection->records = malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        pthread_mutex_destroy(&collection->lock);
        return -1;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        Record record;
        record.offset = rand();
        record.key = rand() % KEY_RANGE;
        record.value = rand() % VALUE_RANGE;

        collection->records[i] = record;
        collection->count++;
    }

    return 0;
}

// Function to retrieve a record by its key
Record* get_record_by_key(Collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            Record *record = &collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

// Function to free all allocated memory
void free_collection(Collection *collection) {
    if (collection) {
        pthread_mutex_lock(&collection->lock);

        free(collection->records);

        pthread_mutex_unlock(&collection->lock);
        pthread_mutex_destroy(&collection->lock);
    }
}

// Helper function to categorize records by type identifier
int get_record_type(Record *record) {
    // For now, use a dummy type based on value range
    if (record->value < VALUE_RANGE / 3)
        return 1;
    else if (record->value < (2 * VALUE_RANGE) / 3)
        return 2;
    else
        return 3;
}

// Function to periodically compress the array (simplified example)
void compress_records(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    // Simple compression: remove duplicates based on keys
    for (size_t i = 0; i < collection->count - 1;) {
        int j;
        for (j = i + 1; j < collection->count; ++j) {
            if (collection->records[i].key == collection->records[j].key) {
                memmove(&collection->records[j], &collection->records[j + 1],
                        (collection->count - j - 1) * sizeof(Record));
                --collection->count;
            }
        }
        ++i;
    }

    pthread_mutex_unlock(&collection->lock);
}

// Main function for testing
int main() {
    Collection collection;
    if (init_collection(&collection, INITIAL_CAPACITY) != 0) {
        fprintf(stderr, "Failed to initialize the collection\n");
        return EXIT_FAILURE;
    }

    Record *record = get_record_by_key(&collection, 42);
    if (record) {
        printf("Found record with key %d: value = %d\n", record->key, record->value);
    } else {
        printf("Record not found\n");
    }

    compress_records(&collection);

    free_collection(&collection);
    return EXIT_SUCCESS;
}
