// Thread-safe random number generator
static pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;

double thread_safe_rand_double(double min, double max) {
    pthread_mutex_lock(&rand_lock);
    double r = (double)rand() / RAND_MAX;
    pthread_mutex_unlock(&rand_lock);
    return r * (max - min) + min;
}

int thread_safe_rand_int(int min, int max) {
    pthread_mutex_lock(&rand_lock);
    int r = rand();
    pthread_mutex_unlock(&rand_lock);
    return min + r % (max - min + 1);
}

// Function to initialize arrays and data points
void initialize_arrays(size_t size, double (*double_array)[size], char (*char_array)[size],
                       data_point (*data_points)[size]) {
