#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records; // Dynamic array of pointers to records
    size_t capacity;
    pthread_mutex_t mutex;
} DataManager;

#define INITIAL_CAPACITY 10

void handle_allocation_failure(void *ptr) {
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
}

DataManager* initialize_data_manager(size_t initial_size) {
    if (initial_size == 0) {
        fprintf(stderr, "Array size cannot be zero.\n");
        return NULL;
    }

    DataManager *data = malloc(sizeof(DataManager));
    handle_allocation_failure(data);

    data->offsets = malloc(initial_size * sizeof(long));
    handle_allocation_failure(data->offsets);

    data->keys = malloc(initial_size * sizeof(int));
    handle_allocation_failure(data->keys);

    data->records = malloc(INITIAL_CAPACITY * sizeof(record*));
    handle_allocation_failure(data->records);

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        data->records[i] = NULL;
    }

    data->capacity = INITIAL_CAPACITY;

    pthread_mutex_init(&data->mutex, NULL);

    return data;
}

void resize_records_array(DataManager *data, size_t new_capacity) {
    pthread_mutex_lock(&data->mutex);
    record **new_records = realloc(data->records, new_capacity * sizeof(record*));
    handle_allocation_failure(new_records);

    if (new_capacity > data->capacity) {
        memset(new_records + data->capacity, 0, (new_capacity - data->capacity) * sizeof(record*));
    }

    free(data->records);
    data->records = new_records;
    data->capacity = new_capacity;
    pthread_mutex_unlock(&data->mutex);
}

record* create_record(int value) {
    record *rec = malloc(sizeof(record));
    handle_allocation_failure(rec);
    rec->value = value;
    return rec;
}

void free_data_manager(DataManager *data, size_t array_size) {
    if (data == NULL) return;

    for (size_t i = 0; i < data->capacity; ++i) {
        free(data->records[i]);
    }

    pthread_mutex_destroy(&data->mutex);

    free(data->offsets);
    free(data->keys);
    free(data->records);
    free(data);
}

record* get_record(DataManager *data, size_t index) {
    if (index >= data->capacity || data->records[index] == NULL) {
        fprintf(stderr, "Invalid record index or record not initialized.\n");
        return NULL;
    }

    pthread_mutex_lock(&data->mutex);
    record *rec = data->records[index];
    pthread_mutex_unlock(&data->mutex);

    return rec;
}

void populate_data(DataManager *data, size_t array_size, int min_value, int max_value) {
    if (data == NULL || array_size > data->capacity) {
        fprintf(stderr, "Invalid operation or insufficient capacity.\n");
        return;
    }

    pthread_mutex_lock(&data->mutex);

    for (size_t i = 0; i < array_size; ++i) {
        long offset = rand() % 1000; // Example offset generation
        int key = rand() % 256;      // Example key generation

        data->offsets[i] = offset;
        data->keys[i] = key;

        if (data->records[i] == NULL) {
            resize_records_array(data, data->capacity * 2);
        }

        data->records[i] = create_record(rand() % (max_value - min_value + 1) + min_value);
    }

    pthread_mutex_unlock(&data->mutex);
}

int main() {
    size_t array_size = 15; // Example size
    int range_min = 0, range_max = 100;

    DataManager *data_manager = initialize_data_manager(array_size);
    populate_data(data_manager, array_size, range_min, range_max);

    record *rec = get_record(data_manager, 5); // Example retrieval

    if (rec != NULL) {
        printf("Record value at index 5: %d\n", rec->value);
    }

    free_data_manager(data_manager, array_size);
    return 0;
}
```

### Key Points:
- **Initialization and Memory Management**: The `initialize_data_manager` function sets up the initial structure with dynamic memory allocation.
- **Dynamic Resizing**: Implemented in `resize_records_array` to handle changes in data size efficiently.
- **Thread Safety**: Managed by using a mutex (`pthread_mutex_t`) around critical sections that modify shared state.
- **Error Handling**: Includes checks and graceful exits for allocation failures and invalid operations.']

