#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METRICS 1000

typedef struct {
    int timestamp;
    double value;
    char* source;
    char* category;
    unsigned long identifier;
} Metric;

typedef struct {
    Metric** metrics;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    char** sources;
    size_t num_sources;
    char*** categories;
    size_t num_categories;
} MetricsManager;

// Utility functions
unsigned long generate_unique_id() {
    static unsigned long id = 0;
    return ++id;
}

double random_double(double min, double max) {
    double r = (double)rand() / RAND_MAX;
    return min + r * (max - min);
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Error handling
void handle_allocation_failure(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Logging function
void log_memory_operation(const char* operation, size_t size) {
    printf("Operation: %s, Size: %zu bytes\n", operation, size);
}

// Function to initialize the metrics manager
MetricsManager* init_metrics_manager(size_t num_sources, size_t num_categories, size_t initial_capacity) {
    MetricsManager* mm = (MetricsManager*)malloc(sizeof(MetricsManager));
    handle_allocation_failure(mm);

    mm->metrics = (Metric**)calloc(initial_capacity, sizeof(Metric*));
    handle_allocation_failure(mm->metrics);

    mm->capacity = initial_capacity;
    mm->count = 0;

    pthread_mutex_init(&mm->lock, NULL);

    // Initialize sources
    mm->num_sources = num_sources;
    mm->sources = (char**)malloc(num_sources * sizeof(char*));
    handle_allocation_failure(mm->sources);

    for (size_t i = 0; i < num_sources; ++i) {
        mm->sources[i] = strdup("Source");
        handle_allocation_failure(mm->sources[i]);
    }

    // Initialize categories
    mm->num_categories = num_categories;
    mm->categories = (char***)malloc(num_categories * sizeof(char**));
    handle_allocation_failure(mm->categories);

    for (size_t i = 0; i < num_categories; ++i) {
        char* category_name = strdup("Category");
        handle_allocation_failure(category_name);

        size_t cat_capacity = 10;
        mm->categories[i] = (char**)malloc(cat_capacity * sizeof(char*));
        handle_allocation_failure(mm->categories[i]);
    }

    log_memory_operation("Initialize", sizeof(MetricsManager) + num_sources * sizeof(char*) + num_categories * sizeof(char**));

    return mm;
}

// Function to add a metric
void add_metric(MetricsManager* mm, int timestamp_range_min, int timestamp_range_max, double value_range_min, double value_range_max) {
    pthread_mutex_lock(&mm->lock);

    if (mm->count >= mm->capacity) {
        size_t new_capacity = mm->capacity * 2;
        Metric** new_metrics = realloc(mm->metrics, new_capacity * sizeof(Metric*));
        handle_allocation_failure(new_metrics);

        log_memory_operation("Reallocate", new_capacity * sizeof(Metric*));

        mm->metrics = new_metrics;
        mm->capacity = new_capacity;
    }

    Metric* metric = (Metric*)malloc(sizeof(Metric));
    handle_allocation_failure(metric);

    metric->timestamp = random_int(timestamp_range_min, timestamp_range_max);
    metric->value = random_double(value_range_min, value_range_max);
    metric->source = mm->sources[random_int(0, mm->num_sources - 1)];
    metric->category = mm->categories[random_int(0, mm->num_categories - 1)][0];
    metric->identifier = generate_unique_id();

    mm->metrics[mm->count++] = metric;

    log_memory_operation("Add Metric", sizeof(Metric));

    pthread_mutex_unlock(&mm->lock);
}

// Function to delete a metric by index
void delete_metric_by_index(MetricsManager* mm, size_t index) {
    pthread_mutex_lock(&mm->lock);

    if (index >= mm->count) return;

    free(mm->metrics[index]);
    log_memory_operation("Delete Metric", sizeof(Metric));

    for (size_t i = index; i < mm->count - 1; ++i) {
        mm->metrics[i] = mm->metrics[i + 1];
    }

    --mm->count;

    pthread_mutex_unlock(&mm->lock);
}

// Function to get a metric by index
Metric* get_metric_by_index(MetricsManager* mm, size_t index) {
    if (index >= mm->count) return NULL;
    return mm->metrics[index];
}

// Function to clean up and free all resources
void cleanup_metrics_manager(MetricsManager* mm) {
    pthread_mutex_lock(&mm->lock);

    for (size_t i = 0; i < mm->count; ++i) {
        free(mm->metrics[i]);
        log_memory_operation("Cleanup Metric", sizeof(Metric));
    }

    free(mm->metrics);
    log_memory_operation("Free Metrics Array", mm->capacity * sizeof(Metric*));

    for (size_t i = 0; i < mm->num_sources; ++i) {
        free(mm->sources[i]);
        log_memory_operation("Cleanup Source", strlen(mm->sources[i]) + 1);
    }

    free(mm->sources);

    for (size_t i = 0; i < mm->num_categories; ++i) {
        free(*mm->categories[i]);
        log_memory_operation("Free Category Array", mm->capacity * sizeof(char*));

        free(mm->categories[i]);
        log_memory_operation("Cleanup Categories", sizeof(char**));
    }

    free(mm->categories);

    pthread_mutex_unlock(&mm->lock);
    pthread_mutex_destroy(&mm->lock);

    free(mm);
    log_memory_operation("Free Metrics Manager", sizeof(MetricsManager));
}

// Example usage
int main() {
    srand(time(NULL));

    size_t num_sources = 5;
    size_t num_categories = 3;

    MetricsManager* mm = init_metrics_manager(num_sources, num_categories, 10);

    add_metric(mm, 0, 1000000, 0.0, 1.0);
    add_metric(mm, 0, 1000000, 0.0, 1.0);

    Metric* metric = get_metric_by_index(mm, 0);
    if (metric) {
        printf("Metric ID: %lu\n", metric->identifier);
    }

    delete_metric_by_index(mm, 0);

    cleanup_metrics_manager(mm);

    return 0;
}
