UserProfile** loadUserProfiles(const char* filename, int* count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned)time(NULL));

    // First pass to determine the number of users
    char line[MAX_NAME_LENGTH];
    int numUsers = 0;
    while (fgets(line, sizeof(line), file)) {
        numUsers++;
    }

    // Allocate memory for user profiles
    UserProfile** userProfiles = malloc(numUsers * sizeof(UserProfile*));
    if (!userProfiles) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    // Rewind the file to read names again
    rewind(file);

    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        char *newline = strchr(line, '\n');
        if (newline) {
            *newline = '\0';  // Remove newline character
        }

        UserProfile* userProfile = malloc(sizeof(UserProfile));
        if (!userProfile) {
            perror("Memory allocation failed");
            fclose(file);
            for (int j = 0; j < i; ++j) {
                free(userProfiles[j]);
            }
            free(userProfiles);
            return NULL;
        }

        strncpy(userProfile->name, line, MAX_NAME_LENGTH - 1);
        userProfile->score = ((double)rand() / RAND_MAX) * 100.0;

        userProfiles[i++] = userProfile;
    }

    fclose(file);

    *count = numUsers;
    return userProfiles;
}

// Function to free the allocated memory for user profiles
void freeUserProfiles(UserProfile** userProfiles, int count) {
    if (userProfiles) {
        for (int i = 0; i < count; ++i) {
            free(userProfiles[i]);
        }
        free(userProfiles);
    }
}

// Example usage
int main() {
    const char* filename = "users.txt";
    int userCount;
    UserProfile** users = loadUserProfiles(filename, &userCount);

    if (users) {
        for (int i = 0; i < userCount; ++i) {
            printf("Name: %s, Score: %.2f\n", users[i]->name, users[i]->score);
        }
        freeUserProfiles(users, userCount);
    }

    return 0;
}
