typedef struct {
    int value;
    char *metadata;
} record;

unsigned long simple_hash_function(long offset, unsigned long hash_limit) {
    // A basic hash function to map offsets into a range [0, hash_limit - 1]
    return (offset ^ (offset >> 16)) % hash_limit;
}

record* allocate_records(int num_records, int min_value, int max_value, 
                         long *offsets, unsigned long hash_limit, 
                         size_t max_metadata_length) {

    if (num_records <= 0 || offsets == NULL) {
        return NULL;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for records array
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Allocation failed
    }

    unsigned long *keys = (unsigned long *)malloc(num_records * sizeof(unsigned long));
    if (!keys) {
        free(records);
        return NULL; // Allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        // Calculate hash and store in keys array
        keys[i] = simple_hash_function(offsets[i], hash_limit);

        // Assign random value within the given range
        records[i].value = min_value + rand() % (max_value - min_value + 1);

        // Allocate memory for metadata, ensuring it fits max_metadata_length
        char *metadata_str = malloc(max_metadata_length);
        if (!metadata_str) {
            free(records);
            free(keys);
            return NULL; // Allocation failed
        }

        snprintf(metadata_str, max_metadata_length, "%ld", offsets[i]);
        records[i].metadata = metadata_str;
    }

    // Optionally store keys somewhere or use them further as needed

    free(keys);  // Free keys after usage

    return records;
}
