import json

#define MAX_USERS 1000 // Maximum number of users to handle
#define SCORE_THRESHOLD 50.0
#define FILENAME "users.txt" // Example file name; can be extended for CSV, JSON, etc.

// Struct definitions
typedef struct {
    double score;
    char *name;
    int ref_count;
} user_data;

typedef struct {
    user_data *data;
    char contact_info[100];
    int is_active;
} user_info;

// Function prototypes
void process_users(const char *filename);
char** read_user_names(const char *filename, size_t* count);
double generate_random_score();
int verify_user_data(char* name); // Mock function for external API integration

// Main processing function
void process_users(const char *filename) {
    size_t user_count = 0;
    char **user_names = read_user_names(filename, &user_count);

    if (!user_names || user_count == 0) return;

    double *scores = (double *)malloc(user_count * sizeof(double));
    user_data *data_array = (user_data *)malloc(user_count * sizeof(user_data));
    user_info *info_array = (user_info *)malloc(user_count * sizeof(user_info));

    if (!scores || !data_array || !info_array) {
        // Handle allocation failure
        free(user_names);
        free(scores);
        free(data_array);
        free(info_array);
        return;
    }

    for (size_t i = 0; i < user_count; ++i) {
        scores[i] = generate_random_score();
        data_array[i].score = scores[i];
        data_array[i].name = user_names[i];
        data_array[i].ref_count = 0;

        info_array[i].data = &data_array[i];
        snprintf(info_array[i].contact_info, sizeof(info_array[i].contact_info), "Contact_%zu", i);
        info_array[i].is_active = scores[i] > SCORE_THRESHOLD;

        // Example of logging
        if (info_array[i].is_active) {
            printf("User %s became active.\n", user_names[i]);
        }

        // External API verification (mock)
        if (!verify_user_data(user_names[i])) {
            printf("Warning: User data integrity failed for %s\n", user_names[i]);
        }
    }

    // Print users' info
    for (size_t i = 0; i < user_count; ++i) {
        printf("User ID %zu: Name: %s, Score: %.2f, Active: %d\n",
               i, data_array[i].name, data_array[i].score, info_array[i].is_active);
    }

    // Free allocated memory
    for (size_t i = 0; i < user_count; ++i) {
        free(user_names[i]);
    }
    free(user_names);
    free(scores);
    free(data_array);
    free(info_array);
}

// Read user names from a file (supports text, CSV, JSON)
char** read_user_names(const char *filename, size_t* count) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    // Determine format by extension or content
    char ext[5] = {0};
    snprintf(ext, sizeof(ext), "%.*s", (int)(sizeof(ext) - 1), filename + strlen(filename) - 3);
    *count = 0;
    char **user_names = NULL;

    if (strcmp(ext, "txt") == 0 || strcmp(ext, "csv") == 0) {
        // Reading text or CSV
        char line[256];
        user_names = (char **)malloc(MAX_USERS * sizeof(char *));
        while (fgets(line, sizeof(line), file)) {
            size_t len = strlen(line);
            if ((ext[1] == 'x' && line[len - 1] == '\n') || ext[0] == ',') {
                --len;
            }
            char *name = strndup(line, len); // Duplicate string without newline
            user_names[*count] = name;
            (*count)++;
            if (*count >= MAX_USERS) break;
        }
    } else if (strcmp(ext, "json") == 0) {
        // Reading JSON using a simple library (e.g., json-c or similar)
        struct json_object *parsed_json;
        struct json_object *user_array;

        parsed_json = json_object_from_file(filename);
        if (!parsed_json) {
            fclose(file);
            return NULL;
        }

        user_names = (char **)malloc(MAX_USERS * sizeof(char *));
        json_object_object_get_ex(parsed_json, "users", &user_array);

