typedef struct {
    char *username;
    int score;
    int activity_count;
} UserProfile;

// Structure to manage user profiles with dynamic allocation
typedef struct {
    UserProfile **profiles;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} UserProfileManager;

UserProfileManager* create_user_profile_manager() {
    UserProfileManager *manager = malloc(sizeof(UserProfileManager));
    manager->capacity = INITIAL_ALLOCATION_SIZE;
    manager->count = 0;
    manager->profiles = calloc(manager->capacity, sizeof(UserProfile *));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_profiles(UserProfileManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UserProfile **new_profiles = realloc(manager->profiles, new_capacity * sizeof(UserProfile *));
    if (new_profiles) {
        manager->profiles = new_profiles;
        manager->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        exit(EXIT_FAILURE);
    }
}

UserProfile* find_user_profile(UserProfileManager *manager, const char *username) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->profiles[i]->username, username) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return manager->profiles[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void add_or_update_user_profile(UserProfileManager *manager, const char *username, int score, int activity_count) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_profiles(manager);
    }

    UserProfile *profile = find_user_profile(manager, username);
    if (!profile) {
        profile = malloc(sizeof(UserProfile));
        profile->username = strdup(username);
        manager->profiles[manager->count++] = profile;
    }

    profile->score += score;
    profile->activity_count += activity_count;

    pthread_mutex_unlock(&manager->lock);
}

void free_user_profile_manager(UserProfileManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->profiles[i]->username);
        free(manager->profiles[i]);
    }

    free(manager->profiles);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

