['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_VALUE_RANGE 100

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

static void expand_capacity(RecordCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    record *new_records = realloc(collection->records, new_capacity * sizeof(record));

    if (new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record));
    collection->records = new_records;
    collection->capacity = new_capacity;
}

RecordCollection* create_record_collection() {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;

    pthread_mutex_init(&collection->lock, NULL);

    collection->records = calloc(collection->capacity, sizeof(record));
    if (collection->records == NULL) {
        free(collection->records);
        free(collection);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->records[i].offset);
        free(collection->records[i].key);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void initialize_records(RecordCollection *collection, size_t num_records) {
    pthread_mutex_lock(&collection->lock);

    if (num_records > collection->capacity) {
        while (num_records > collection->capacity) {
            expand_capacity(collection);
        }
    }

    for (size_t i = 0; i < num_records; i++) {
        if (i >= collection->size) { // Handle initial allocation
            collection->records[i].offset = malloc(sizeof(long));
            collection->records[i].key = malloc(sizeof(int));

            if (collection->records[i].offset == NULL || collection->records[i].key == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        }

        collection->records[i].value = rand() % MAX_VALUE_RANGE;
    }

    collection->size = num_records;

    pthread_mutex_unlock(&collection->lock);
}

record* get_record(RecordCollection *collection, size_t index) {
    if (index >= collection->size) {
        return NULL; // Index out of bounds
    }

    pthread_mutex_lock(&collection->lock);

    record *result = &collection->records[index];

    pthread_mutex_unlock(&collection->lock);
    return result;
}

void update_records(RecordCollection *collection, int new_value, size_t start_idx, size_t count) {
    if (start_idx + count > collection->size) {
        fprintf(stderr, "Update range out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < count; ++i) {
        collection->records[start_idx + i].value = new_value;
    }

    pthread_mutex_unlock(&collection->lock);
}

int main() {
    // Example usage
    RecordCollection *collection = create_record_collection();

    initialize_records(collection, 500); // Initialize with 500 records

    record *rec = get_record(collection, 10); // Retrieve a record by index
    if (rec != NULL) {
        printf("Record value: %d\n", rec->value);
    }

    update_records(collection, 42, 100, 50); // Update 50 records starting from index 100

    destroy_record_collection(collection);

    return 0;
}
