['Below is a C implementation of the described task using a basic hash table with chaining for collision resolution:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_SIZE 101

typedef struct Record {
    int key;
    char identifier[50];
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    HashNode **buckets;
    size_t size;
} HashTable;

unsigned long hash_function(int key, size_t table_size) {
    return (key % table_size);
}

HashTable* create_hash_table(size_t initial_size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    table->buckets = calloc(initial_size, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    table->size = initial_size;
    return table;
}

void insert_record(HashTable *table, int key, const char *identifier) {
    unsigned long index = hash_function(key, table->size);

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    new_node->record.key = key;
    snprintf(new_node->record.identifier, sizeof(new_node->record.identifier), "%s", identifier);

    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
}

Record* find_record(HashTable *table, int key) {
    unsigned long index = hash_function(key, table->size);

    HashNode *current = table->buckets[index];
    while (current) {
        if (current->record.key == key) {
            return &current->record;
        }
        current = current->next;
    }

    return NULL; // Key not found
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; i++) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    free(table);
}

void manage_records(int num_records, int min_val, int max_val) {
    HashTable *table = create_hash_table(INITIAL_SIZE);

    for (int i = 0; i < num_records; ++i) {
        int key = rand() % (max_val - min_val + 1) + min_val;
        char identifier[50];
        snprintf(identifier, sizeof(identifier), "Record-%d", i);

        insert_record(table, key, identifier);
    }

    // Example search
    int search_key = 123; // Replace with actual search value
    Record *found_record = find_record(table, search_key);

    if (found_record) {
        printf("Found record: %s with key %d\n", found_record->identifier, found_record->key);
    } else {
        printf("Record not found for key %d\n", search_key);
    }

    free_hash_table(table);
}

int main() {
    srand((unsigned int)time(NULL));

    manage_records(1000, 1, 5000); // Example usage with 1000 records in the range [1, 5000]

    return 0;
}
```

This implementation includes:
