// Define the struct child_node and record
typedef struct child_node {
    int value;
    struct child_node* next;
} child_node;

typedef struct record {
    long* offset;
    int key;
    struct child_node* children_head;
} record;

// Function prototypes
void initialize_records(record** records, size_t count);
int insert_child_node(record* rec, int value);
record* get_record_by_index(record* records[], size_t index);
void iterate_records(record* records[], size_t count);
long generate_random_offset();
int generate_random_key(int min, int max);

// Initialize records with random keys and dynamically allocated offsets
void initialize_records(record** records, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        records[i]->offset = malloc(sizeof(long));
        if (!records[i]->offset) {
            fprintf(stderr, "Memory allocation failed for offset\n");
            free(records[i]);
            exit(EXIT_FAILURE);
        }

        *(records[i]->offset) = generate_random_offset();
        records[i]->key = generate_random_key(1, 100); // Random key between 1 and 100
        records[i]->children_head = NULL;
    }
}

// Insert a new child_node into the linked list of a specific record
int insert_child_node(record* rec, int value) {
    if (!rec) return -1;

    child_node* new_node = malloc(sizeof(child_node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for child node\n");
        return -1;
    }

    new_node->value = value;
    new_node->next = rec->children_head;
    rec->children_head = new_node;

    return 0;
}

// Retrieve a record by its index
record* get_record_by_index(record* records[], size_t index) {
    if (index >= sizeof(records) / sizeof(records[0])) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    return records[index];
}

// Iterate over all records and their child nodes
void iterate_records(record* records[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        record* rec = get_record_by_index(records, i);
        if (!rec) continue;

        printf("Record %zu: Key = %d, Offset = %ld\n", i, rec->key, *(rec->offset));

        child_node* node = rec->children_head;
        while (node) {
            printf("Child Node Value: %d\n", node->value);
            child_node* temp = node;
            node = node->next;
            free(temp); // Free each node after processing
        }

        free(rec->offset); // Free the offset
    }
}

// Helper function to generate a random long value for offsets
long generate_random_offset() {
    return rand(); 
}

// Helper function to generate a random key within a specified range
int generate_random_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int main() {
    size_t record_count = 5;
    record* records[record_count];

    initialize_records(records, record_count);

    // Insert some child nodes for demonstration
    insert_child_node(records[0], 10);
    insert_child_node(records[0], 20);

    iterate_records(records, record_count);

    // Clean up remaining allocated memory
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i]);
    }

    return 0;
}
```

