#include <string.h>
#include <pthread.h>

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct Event {
    unsigned long timestamp;
    EventType type;
    char *description;
} Event;

typedef struct {
    Event **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rlock;
    size_t insertions;
    size_t deletions;
} EventCollection;

EventCollection* create_event_collection(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    EventCollection *collection = malloc(sizeof(EventCollection));
    if (!collection) return NULL;

    collection->events = calloc(initial_capacity, sizeof(Event *));
    if (!collection->events) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_rwlock_init(&collection->rlock, NULL);
    collection->insertions = 0;
    collection->deletions = 0;

    return collection;
}

void destroy_event_collection(EventCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->events[i]->description);
        free(collection->events[i]);
    }
    free(collection->events);

    pthread_mutex_destroy(&collection->lock);
    pthread_rwlock_destroy(&collection->rlock);
    free(collection->);
}

void resize_event_collection(EventCollection *collection, size_t new_capacity) {
    Event **new_events = realloc(collection->events, new_capacity * sizeof(Event *));
    if (!new_events) return;

    collection->events = new_events;
    collection->capacity = new_capacity;
}

int insert_event(EventCollection *collection, unsigned long timestamp, EventType type, const char *description) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        resize_event_collection(collection, collection->capacity * 2);
        if (!collection->events) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
    }

    Event *event = malloc(sizeof(Event));
    if (!event) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    event->timestamp = timestamp;
    event->type = type;
    event->description = strdup(description);
    if (!event->description) {
        free(event);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->events[collection->count++] = event;

    ++(collection->insertions);
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

int delete_event(EventCollection *collection, size_t index) {
    pthread_rwlock_wrlock(&collection->rlock);

    if (index >= collection->count) {
        pthread_rwlock_unlock(&collection->rlock);
        return -1;
    }

    free(collection->events[index]->description);
    free(collection->events[index]);

    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->events[i] = collection->events[i + 1];
    }
    --(collection->count);

    if (collection->capacity > 4 && collection->count <= collection->capacity / 2) {
        resize_event_collection(collection, collection->capacity / 2);
    }

    ++(collection->deletions);
    pthread_rwlock_unlock(&collection->rlock);

    return 0;
}

Event* get_event_by_index(EventCollection *collection, size_t index) {
    if (index >= collection->count) return NULL;

    Event *event = malloc(sizeof(Event));
    if (!event) return NULL;

    memcpy(event, collection->events[index], sizeof(Event));

    char *desc_copy = strdup(collection->events[index]->description);
    event->description = desc_copy;
    if (!event->description) {
        free(event);
        return NULL;
    }

    return event;
}

int search_events_by_type(EventCollection *collection, EventType type, Event ***results, size_t *result_count) {
    pthread_rwlock_rdlock(&collection->rlock);

    *results = calloc(collection->count, sizeof(Event *));
    if (!*results) {
        pthread_rwlock_unlock(&collection->rlock);
        return -1;
    }

    *result_count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i]->type == type) {
            (*results)[(*result_count)++] = collection->events[i];
        }
    }

    pthread_rwlock_unlock(&collection->rlock);
    return 0;
}

void log_usage(EventCollection *collection) {
    printf("Insertions: %zu, Deletions: %zu\n", collection->insertions, collection->deletions);
}
