```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define RETRY_DELAY 1000000 // microseconds

typedef struct Item {
    int id;
    double value;
    char *name;
} Item;

typedef struct ListNode {
    Item item;
    struct ListNode *next;
} ListNode;

typedef struct List {
    ListNode *head;
    pthread_mutex_t lock;
} List;

void init_list(List *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int insert_item(List *list, int id, double value, const char *name) {
    Item new_item;
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) return -1;

    new_item.id = id;
    new_item.value = value;
    new_item.name = strdup(name);
    if (!new_item.name) {
        free(new_node);
        return -1;
    }

    new_node->item = new_item;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    ListNode *prev = NULL;
    while (current != NULL && current->item.id < id) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        new_node->next = prev->next;
        prev->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Item* search_item(List *list, int id) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL && current->item.id != id) {
        current = current->next;
    }

    Item *result = NULL;
    if (current != NULL) {
        result = &current->item;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

void free_list(List *list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next_node = current->next;
        free(current->item.name);
        free(current);
        current = next_node;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int retry_operation(int (*operation)(List*, int, double, const char*), List *list, int id, double value, const char *name) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (operation(list, id, value, name) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY);
    }
    return -1;
}

void batch_insert(List *list, int num_items, double values[], const char *names[]) {
    for (int i = 0; i < num_items; ++i) {
        retry_operation(insert_item, list, i + 1, values[i], names[i]);
    }
}

int main() {
    List myList;
    init_list(&myList);

    double values[] = {10.5, 20.3, 30.7};
    const char *names[] = {"Item1", "Item2", "Item3"};

    batch_insert(&myList, 3, values, names);

    Item *item = search_item(&myList, 2);
    if (item) {
        printf("Found item with ID %d: Value = %.2f, Name = %s\n", item->id, item->value, item->name);
    } else {
        printf("Item not found.\n");
    }

    free_list(&myList);

    return 0;
}
```

### Key Features Implemented:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management**: Allocates and deallocates memory for items and their names properly.
- **Retry Logic**: Implements a simple retry mechanism with delay on failure.
- **Batch Operations**: Supports batch insertion of items.
- **Error Handling**: Provides basic error handling by returning status codes.
- **Scalability & Performance**: Uses linked list to handle dynamic size efficiently.

This implementation provides a solid foundation for managing a dynamic list while addressing the challenges outlined. Adjustments can be made based on specific use cases and performance requirements.']

