#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PLAN_NAME_LENGTH 50
#define MAX_SUBSCRIPTIONS 10000
#define TRANSACTION_MAX_CHARS 512

typedef struct {
    char *plan_name;
    time_t start_date;
    int status_flag; // 0 for inactive, 1 for active
} Subscription;

typedef struct {
    pthread_mutex_t lock;
    Subscription *subscriptions;
    size_t count;
} SubscriptionManager;

typedef struct {
    char card_number[20];
    char expiration_date[8]; // MM/YY format
    char cvv[5];
    int amount;
    char transaction_id[128];
} PaymentInfo;

SubscriptionManager manager;

int is_valid_payment_info(const PaymentInfo *info) {
    if (strlen(info->card_number) != 16 || strlen(info->expiration_date) != 5 ||
        strlen(info->cvv) != 3) return 0;
    for (size_t i = 0; i < 16; ++i)
        if (info->card_number[i] < '0' || info->card_number[i] > '9') return 0;
    return 1;
}

int initializeAndManageSubscriptions(size_t count) {
    pthread_mutex_init(&manager.lock, NULL);

    manager.subscriptions = malloc(sizeof(Subscription) * count);
    if (!manager.subscriptions) return -1;

    manager.count = count;
    for (size_t i = 0; i < count; ++i) {
        char plan_name[5];
        snprintf(plan_name, sizeof(plan_name), "Plan%d", i + 1);

        manager.subscriptions[i].plan_name = strdup(plan_name);
        if (!manager.subscriptions[i].plan_name) return -1;

        manager.subscriptions[i].start_date = time(NULL); // Default to current time
        manager.subscriptions[i].status_flag = 0; // Inactive by default
    }
    return 0;
}

void freeSubscriptions() {
    pthread_mutex_lock(&manager.lock);
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.subscriptions[i].plan_name);
    }
    free(manager.subscriptions);
    pthread_mutex_unlock(&manager.lock);
    pthread_mutex_destroy(&manager.lock);
}

Subscription* get_subscription(size_t index) {
    if (index >= manager.count) return NULL;
    return &manager.subscriptions[index];
}

int is_renewal_needed(Subscription *sub) {
    time_t now = time(NULL);
    double seconds_since_start = difftime(now, sub->start_date);

    // Assuming subscription period is 30 days for simplicity
    const int subscription_period_days = 30;
    return (seconds_since_start / (60 * 60 * 24)) >= subscription_period_days;
}

int processPaymentTransactionsAndManageSubscriptionStatus(const PaymentInfo *payment_info, size_t user_id) {
    if (!is_valid_payment_info(payment_info))
        return 0;

    pthread_mutex_lock(&manager.lock);

    // Check for duplicate transactions (simulate with transaction ID)
    char base_transaction_id[128];
    snprintf(base_transaction_id, sizeof(base_transaction_id), "%s_%ld", payment_info->card_number, user_id);

    int suffix = 1;
    char transaction_id[128];
    int is_duplicate = 1;

    while (is_duplicate) {
        snprintf(transaction_id, sizeof(transaction_id), "%s_%d", base_transaction_id, suffix++);

        // Simulating a database check for duplicate transaction ID
        FILE *file = fopen("transactions.log", "r");
        if (!file) break;

        char line[256];
        is_duplicate = 0;
        while (fgets(line, sizeof(line), file)) {
            if (strstr(line, transaction_id)) {
                is_duplicate = 1;
                fclose(file);
                break;
            }
        }
        fclose(file);

        // Log the current attempt
        FILE *log_file = fopen("audit.log", "a");
        fprintf(log_file, "%s - Attempting transaction ID: %s\n", ctime(&now), transaction_id);
        fclose(log_file);
    }

    if (is_duplicate) {
        pthread_mutex_unlock(&manager.lock);
        return 0; // Duplicate detected
    }

    FILE *file = fopen("transactions.log", "a");
    fprintf(file, "%s\n", transaction_id);
    fclose(file);

    Subscription *sub = get_subscription(user_id % manager.count);
    if (!sub) {
        pthread_mutex_unlock(&manager.lock);
        return 0;
    }

    // Simulate interaction with payment gateway
    int payment_success = 1; // Assume success for this example

    if (payment_success) {
        sub->status_flag = 1; // Activate subscription

        FILE *log_file = fopen("audit.log", "a");
        fprintf(log_file, "%s - Transaction ID: %s processed successfully\n", ctime(&now), transaction_id);
        fclose(log_file);

        pthread_mutex_unlock(&manager.lock);
        return 1;
    } else {
        FILE *log_file = fopen("audit.log", "a");
        fprintf(log_file, "%s - Transaction declined or insufficient funds for ID: %s\n", ctime(&now), transaction_id);
        fclose(log_file);

        pthread_mutex_unlock(&manager.lock);
        return 0;
    }
}

int main() {
    if (initializeAndManageSubscriptions(MAX_SUBSCRIPTIONS) != 0) {
        fprintf(stderr, "Failed to initialize subscriptions.\n");
        return EXIT_FAILURE;
    }

    PaymentInfo payment_info = {"1234567812345678", "12/25", "123", 100};
    size_t user_id = 42;

    if (processPaymentTransactionsAndManageSubscriptionStatus(&payment_info, user_id)) {
        printf("Transaction processed successfully.\n");
    } else {
        printf("Failed to process transaction.\n");
    }

    freeSubscriptions();
    return EXIT_SUCCESS;
}
