// Logger class for logging messages with timestamps and levels.
class Logger {
public:
    enum Level { INFO, WARNING, ERROR };

    Logger(const std::string& logFile)
        : logfile(logFile), level(INFO) {}

    void setLevel(Level newLevel) { level = newLevel; }
    void log(Level lvl, const std::string& message) {
        if (lvl >= level) {
            std::lock_guard<std::mutex> lock(mutex_);
            auto now = std::chrono::system_clock::now();
            auto now_c = std::chrono::system_clock::to_time_t(now);
            logfile << "[" << std::put_time(std::localtime(&now_c), "%F %T") 
                    << "] [" << logLevelString(lvl) << "] " << message << std::endl;
        }
    }

private:
    const std::string logLevelString(Level lvl) {
        switch (lvl) {
            case INFO: return "INFO";
            case WARNING: return "WARNING";
            case ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }

    std::ofstream logfile;
    Level level;
    std::mutex mutex_;
};

// Record structure with an integer value.
