#define MAX_STRING_LENGTH 10

typedef struct dataNode {
    char *data;
    float value;
    struct dataNode *next;
} dataNode;

// Helper function to calculate the average of an array
float calculateAverage(float *arr, int size) {
    if (size == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < size; ++i) {
        sum += arr[i];
    }
    return sum / size;
}

// Function to initialize a dynamic array of dataNodes
dataNode* processAndTransformData(int num_nodes, float min_value, float max_value) {
    if (num_nodes <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    dataNode *head = NULL;

    srand(time(NULL));

    for (int i = 0; i < num_nodes; ++i) {
        dataNode *new_node = (dataNode *)malloc(sizeof(dataNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed.\n");
            while (head != NULL) {
                dataNode *temp = head;
                head = head->next;
                free(temp->data);
                free(temp);
            }
            pthread_mutex_destroy(&mutex);
            return NULL;
        }

        new_node->data = (char *)malloc(MAX_STRING_LENGTH + 1);
        if (!new_node->data) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(new_node);
            while (head != NULL) {
                dataNode *temp = head;
                head = head->next;
                free(temp->data);
                free(temp);
            }
            pthread_mutex_destroy(&mutex);
            return NULL;
        }

        for (int j = 0; j < MAX_STRING_LENGTH; ++j) {
            char rand_char = (rand() % 2 == 0) ? (rand() % 26 + 'a') : (rand() % 10 + '0');
            new_node->data[j] = rand_char;
        }
        new_node->data[MAX_STRING_LENGTH] = '\0';

        new_node->value = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);
        new_node->next = NULL;

        pthread_mutex_lock(&mutex);
        if (!head) {
            head = new_node;
        } else {
            dataNode *temp = head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
        pthread_mutex_unlock(&mutex);
    }

    return head;
}

// Function to read floats from stdin and calculate average
void readFloatsAndPrintAverage() {
    printf("Enter floating-point numbers (end with non-numeric input):\n");
    float *numbers = NULL;
    size_t size = 0;

    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        if (sscanf(line, "%f", &numbers[size]) == 1) {
            numbers = realloc(numbers, sizeof(float) * (size + 1));
            if (!numbers) {
                fprintf(stderr, "Memory allocation failed.\n");
                free(numbers);
                return;
            }
            size++;
        } else {
            break;
        }
    }

    float average = calculateAverage(numbers, size);
    printf("Average: %f\n", average);

    free(numbers);
}

// Example usage
int main() {
