    float min_value = 0.0f, max_value = 100.0f;

    dataNode *list = processAndTransformData(num_nodes, min_value, max_value);
    if (list) {
        // Traverse and print the list for demonstration
        pthread_mutex_t mutex;
        pthread_mutex_init(&mutex, NULL);

        pthread_mutex_lock(&mutex);
        dataNode *current = list;
        while (current != NULL) {
            printf("Data: %s, Value: %.2f\n", current->data, current->value);
            current = current->next;
        }
        pthread_mutex_unlock(&mutex);

        // Free the list
        while (list != NULL) {
            dataNode *temp = list;
            list = list->next;
            free(temp->data);
            free(temp);
        }

        pthread_mutex_destroy(&mutex);
    }

    readFloatsAndPrintAverage();

    return 0;
}
