dnsCacheEntry cache[CACHE_SIZE];
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile = NULL;

void logMessage(const char *message) {
    pthread_mutex_lock(&cacheMutex);
    if (logFile == NULL || feof(logFile)) {
        logFile = fopen(LOG_FILE, "a");
    }
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", message);
        fflush(logFile); // Ensure the message is written immediately
    }
    pthread_mutex_unlock(&cacheMutex);
}

void rotateLogs() {
    pthread_mutex_lock(&cacheMutex);
    fclose(logFile);
    char newLogFileName[256];
    time_t now = time(NULL);
    sprintf(newLogFileName, "dns_log_%ld.txt", (long)now);
    rename(LOG_FILE, newLogFileName);
    logFile = fopen(LOG_FILE, "w");
    pthread_mutex_unlock(&cacheMutex);
}

void initializeCache() {
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache[i].expiration = 0;
        strcpy(cache[i].domain, "");
        strcpy(cache[i].ip, "");
    }
    pthread_mutex_unlock(&cacheMutex);
}

// Helper function to generate a random alphanumeric string
