// Thread-safe DNS cache lookup
const char* dnsLookup(const char *domain) {
    pthread_mutex_lock(&cacheMutex);

    time_t now = time(NULL);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache[i].domain, domain) == 0 && cache[i].expiration > now) {
            pthread_mutex_unlock(&cacheMutex);
            return cache[i].ip;
