        exit(EXIT_FAILURE);
    }

    // Initialize DNS cache
    initializeCache();

    dataNode *head = NULL, *prev = NULL;
    for (size_t i = 0; i < numNodes; ++i) {
        char *randomString = generateRandomString(STRING_LENGTH);
        if (!randomString) continue;

        float randomValue = generateRandomFloat(FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);
        dataNode *node = createDataNode(randomString, randomValue, NULL);

        free(randomString); // Free the temporary string after use

        if (head == NULL) {
            head = node;
        } else {
            prev->next = node;
        }
        prev = node;
    }

    float *floatArray = malloc(numNodes * sizeof(float));
    if (!floatArray) {
        perror("Failed to allocate memory for float array");
        freeDataNodes(head);
        exit(EXIT_FAILURE);
    }

    printf("Enter %zu floating-point numbers:\n", numNodes);
    for (size_t i = 0; i < numNodes; ++i) {
        scanf("%f", &floatArray[i]);
    }

    // Calculate average
    float sum = 0.0f;
    for (size_t i = 0; i < numNodes; ++i) {
        sum += floatArray[i];
    }
    float average = sum / numNodes;
    printf("Average: %.2f\n", average);

    free(floatArray);
    freeDataNodes(head);
}

int main() {
    size_t numNodes = 5; // Example number of nodes
    processAndTransformData(numNodes);
    return 0;
}
```

### Key Features:
