public class FileProcessor
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const int MaxFilenameLength = 255;
    private const string DefaultMimeType = "application/octet-stream";

    public async Task<int> ProcessFileAndRenameWithMetadata(string filePath, string directoryPath)
    {
        try
        {
            byte[] fileBytes = await File.ReadAllBytesAsync(filePath);
            string base64EncryptedMessage = Encoding.UTF8.GetString(fileBytes);

            // Decrypt the message
            string decryptedMessage;
            if (!TryDecryptTripleDES(base64EncryptedMessage, out decryptedMessage))
                return -1; // Decryption failure

            if (string.IsNullOrEmpty(decryptedMessage))
                return -2; // Decrypted message is null or empty

            string mimeType = await GetMimeTypeAsync(filePath);
            if (!IsValidMIMEType(mimeType))
                mimeType = DefaultMimeType;

            if (!ValidateDecryptedMessageFormat(mimeType, decryptedMessage))
                return -3; // Format validation failure

            string newFilename = GenerateNewFileName(directoryPath, filePath, mimeType);

            int retryCount = 0;
            while (File.Exists(Path.Combine(directoryPath, newFilename)))
            {
                newFilename = AppendSuffix(newFilename);
                if (++retryCount > 10) // Prevent infinite loop
                    return -4; // Could not generate a unique filename
            }

            string newFilePath = Path.Combine(directoryPath, newFilename);
            File.Move(filePath, newFilePath);

            return 0; // Success
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file: {ex.Message}");
            return -5; // General error handling
        }
    }

    private bool TryDecryptTripleDES(string encryptedMessageBase64, out string decryptedMessage)
    {
        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(encryptedMessageBase64);

            using (var tripleDes = TripleDESCryptoServiceProvider.Create())
            {
                tripleDes.Key = Encoding.UTF8.GetBytes("Your-Key-Here"); // Replace with your key
                tripleDes.IV = Encoding.UTF8.GetBytes("Your-IV-Here");   // Replace with your IV

                var decryptor = tripleDes.CreateDecryptor();
                using (var ms = new MemoryStream(encryptedBytes))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        using (var sr = new StreamReader(cs))
                        {
                            decryptedMessage = sr.ReadToEnd();
                            return true;
                        }
                    }
                }
            }
        }
        catch
        {
            decryptedMessage = null;
            return false;
        }
    }

    private async Task<string> GetMimeTypeAsync(string filePath)
    {
        // Simulate an external metadata service call
        try
        {
            string response = await httpClient.GetStringAsync($"http://metadata-service/mime?file={filePath}");
            return response.Trim();
        }
        catch (Exception)
        {
            return DefaultMimeType; // Handle network failures gracefully
        }
    }

    private bool IsValidMIMEType(string mimeType)
    {
        // Implement logic to validate MIME type
        return true;
    }

    private bool ValidateDecryptedMessageFormat(string mimeType, string decryptedMessage)
    {
        // Implement format validation based on MIME type
        return !string.IsNullOrEmpty(decryptedMessage);
    }

    private string GenerateNewFileName(string directoryPath, string originalFilePath, string mimeType)
    {
        var fileInfo = new FileInfo(originalFilePath);
        string baseName = Path.GetFileNameWithoutExtension(fileInfo.Name);
        string extension = fileInfo.Extension;
        string timestamp = DateTime.Now.ToString("yyyyMMddHHmmss");
        int randomNumber = new Random().Next(100, 1000);

        string newFileNamePart = $"{baseName}_{timestamp}_{randomNumber}.{mimeType.Split('/')[1]}";

        if (newFileNamePart.Length + baseName.Length > MaxFilenameLength)
            throw new InvalidOperationException("Generated filename exceeds maximum length");

        return $"{baseName}{extension}{newFileNamePart}";
    }

    private string AppendSuffix(string fileName)
    {
        var directory = Path.GetDirectoryName(fileName);
        var baseName = Path.GetFileNameWithoutExtension(fileName);
        var extension = Path.GetExtension(fileName);
        int suffixNumber = 1;

        while (File.Exists(Path.Combine(directory, $"{baseName}_{suffixNumber}{extension}")))
            suffixNumber++;

        return $"{baseName}_{suffixNumber}{extension}";
    }
}
