use reqwest::Client;

#[derive(Debug)]
struct Record {
    value: i32,
    offset_ptr: *const i64,
    key_ptr: *const i32,
}

async fn initializeAndManageRecords(num_entries: usize, range_min: i32, range_max: i32) -> Result<Vec<Record>, &'static str> {
    let offset_array = Arc::new(Mutex::new(Vec::with_capacity(num_entries)));
    let keys_array = Arc::new(Mutex::new(vec![0; num_entries]));

    if offset_array.lock().unwrap().capacity() == 0 || keys_array.lock().unwrap().len() < num_entries {
        return Err("Failed to allocate memory for large datasets");
    }

    let mut records = Vec::with_capacity(num_entries);
    let dist = Uniform::from(range_min..=range_max);

    for i in 0..num_entries {
        let offset_value: i64 = rand::random();
        (*offset_array.lock().unwrap()).push(offset_value);

        let record = Record {
            value: dist.sample(&mut rand::thread_rng()),
            offset_ptr: unsafe { ptr::addr_of!((*offset_array.lock().unwrap())[i]) },
            key_ptr: unsafe { ptr::addr_of!((*keys_array.lock().unwrap())[i]) },
        };

        records.push(record);
    }

    Ok(records)
}

