```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;

public class DynamicRandom
{
    private readonly Random _random;
    private double _min;
    private double _max;
    private static readonly object _lock = new object();

    private Dictionary<double, double> _cache = new Dictionary<double, double>();

    public DynamicRandom(double min = 0, double max = 100)
    {
        if (min > max)
        {
            Console.WriteLine("Warning: Min is greater than Max. Using default range [0, 100].");
            _min = 0;
            _max = 100;
        }
        else
        {
            _min = min;
            _max = max;
        }

        _random = new Random();
    }

    public double GenerateRandomFloat(bool inclusive = true)
    {
        lock (_lock)
        {
            var key = Tuple.Create(_min, _max, inclusive);
            if (!_cache.TryGetValue(key.Item1, out var cachedValue))
            {
                cachedValue = GetRandomDouble(inclusive);
                _cache[key] = cachedValue;
            }
            return cachedValue;
        }
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        lock (_lock)
        {
            double randomValue = GetRandomDouble(inclusive);
            return (int)randomValue;
        }
    }

    private double GetRandomDouble(bool inclusive)
    {
        if (inclusive)
            return _min + _random.NextDouble() * (_max - _min);

        return _min + _random.NextDouble() * (_max - _min - 1);
    }

    public override string ToString()
    {
        return $"Range: [{_min}, {_max}]";
    }

    public void ResetToDefault()
    {
        _min = 0;
        _max = 100;
    }

    public static void GenerateSeed(int seed)
    {
        Random.Shared.SetSeed(seed);
    }

    // Simulate Gaussian Distribution
    public double GenerateGaussianRandom()
    {
        double u1 = 1.0 - _random.NextDouble(); //uniform(0,1] random doubles
        double u2 = 1.0 - _random.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) *
                               Math.Sin(2.0 * Math.PI * u2); //random normal(0,1)
        return randStdNormal * ((_max - _min) / 6.0) + ((_max + _min) / 2.0);
    }
}

public static class RandomExtensions
{
    private static int? _seed;

    public static void SetSeed(this Random random, int seed)
    {
        if (_seed == null || !random.NextDouble().Equals(random.NextDouble(), precision: 1e-10))
        {
            _seed = seed;
            new System.Random(seed);
        }
    }
}
