typedef struct {
    long offset;
    int key;
    int value;
} record;

record* initializeAndManageRecords(const char *filePath, size_t numRecords, int minValue, int maxValue, size_t maxArraySize) {
    if (numRecords > maxArraySize) {
        fprintf(stderr, "Requested number of records exceeds maximum allowed.\n");
        return NULL;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Open file to read keys
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    record *records = (record *)malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        fclose(file);
        return NULL;
    }

    // Read keys from file
    int key;
    size_t count = 0;
    while (fscanf(file, "%d", &key) == 1 && count < numRecords) {
        records[count].offset = count; // Example: using index as offset
        records[count].key = key;
        records[count].value = minValue + rand() % (maxValue - minValue + 1);
        ++count;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading from file.\n");
        free(records);
        fclose(file);
        return NULL;
    }

    fclose(file);

    // Return initialized records
    return records;
}

void freeRecords(record *records) {
    if (records) {
        free(records);
    }
}

record* getRecordByIndex(record *records, size_t index, size_t numRecords) {
    if (index < numRecords) {
        return &records[index];
    } else {
        fprintf(stderr, "Index out of bounds.\n");
        return NULL;
    }
}
