    return randomString;
}

// Function to calculate the average of an array of floats
float calculateAverage(float *array, size_t size) {
    if (size == 0) return 0.0f;

    float sum = 0.0f;
    for (size_t i = 0; i < size; ++i) {
        sum += array[i];
    }
    return sum / size;
}

// Function to read floats from stdin into an array
int readFloats(float **array, size_t *count) {
    float num;
    size_t capacity = 10;
    *array = malloc(capacity * sizeof(float));
    if (!*array) return -1;

    *count = 0;
    while (scanf("%f", &num) == 1) {
        if (*count >= capacity) {
            capacity *= 2;
            float *temp = realloc(*array, capacity * sizeof(float));
            if (!temp) return -1;
            *array = temp;
        }
        (*array)[*count] = num;
        ++(*count);
    }
    return 0;
}

// Function to process and transform data
void processAndTransformData(size_t nodeCount, float minFloatValue, float maxFloatValue) {
    // Initialize random seed with potential external dependency or fallback
    int seed = DEFAULT_SEED_VALUE; // Replace this logic as needed for real seed acquisition
    srand(seed);

    dataNode *head = NULL;
    dataNode *prev = NULL;

    for (size_t i = 0; i < nodeCount; ++i) {
        pthread_mutex_lock(&list_mutex);

        dataNode *newNode = malloc(sizeof(dataNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        newNode->str = generateRandomString(NODE_STRING_LENGTH);
        if (!newNode->str) {
            free(newNode);
            pthread_mutex_unlock(&list_mutex);
            continue; // Skip this node on failure
        }

        newNode->value = minFloatValue + ((maxFloatValue - minFloatValue) * rand() / (float)RAND_MAX);

        if (!head) {
            head = newNode;
        } else {
            prev->next = newNode;
        }

        newNode->next = NULL;
        prev = newNode;

        pthread_mutex_unlock(&list_mutex);
    }

    // Read floats from stdin and calculate average
    float *inputArray = NULL;
    size_t arraySize = 0;
    if (readFloats(&inputArray, &arraySize) != 0) {
        fprintf(stderr, "Failed to read input data\n");
    } else {
        float avg = calculateAverage(inputArray, arraySize);
        printf("Average: %.2f\n", avg);
        free(inputArray);
    }

    // Free the linked list
    pthread_mutex_lock(&list_mutex);

    while (head) {
        dataNode *temp = head;
        head = head->next;
        free(temp->str);
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    processAndTransformData(10, 0.0f, 100.0f);
    return 0;
}
```

This code initializes a dynamic linked list with `dataNode` structures containing random alphanumeric strings and float values within a specified range. It uses mutexes to ensure thread-safe operations on the list and handles memory allocation failures gracefully. The function reads floating-point numbers from standard input, calculates their average using a helper function, and manages dependencies on external seed values.']

