    db_pool.execute(sql, &[
        "processed", 
        &transaction.merchant_id,
        &transaction.currency_code,
    ])
    .await?;

    Ok(())
}

async fn batchProcessTransactions(db_pool: Pool<Postgres>, tx_ch: mpsc::Sender<Transaction>) -> Result<(), Box<dyn std::error::Error>> {
    let db_pool = Arc::new(db_pool);

    tokio::spawn(async move {
        while let Some(transaction) = tx_ch.recv().await {
            match process_transaction(transaction, &db_pool).await {
                Ok(_) => info!("Transaction processed successfully"),
                Err(e) => error!("Failed to process transaction: {}", e),
            }
        }
    });

    Ok(())
}

