    ROUTING_TABLE.lock().unwrap().insert("EUR".to_string(), "PayPal");

    let (tx, mut rx) = mpsc::channel(100);

    batchProcessTransactions(db_pool, tx).await?;

    for line in std::io::stdin().lock().lines() {
        let input = line?;

        if let Ok(parsed) = parse_input(&input) {
            tx.send(parsed).await?;
        } else {
            error!("Failed to parse input: {}", input);
        }
    }

    // Ensure all transactions are processed
    while rx.recv().await.is_some() {}

    Ok(())
}

fn parse_input(input: &str) -> Result<Transaction, &'static str> {
    let parts: Vec<&str> = input.split(',').collect();
    if parts.len() != 3 {
        return Err("Invalid input format");
    }

    let merchant_id: i32 = parts[0].trim().parse()?;
    let currency_code = parts[1].trim().to_string();
    let amount: f64 = parts[2].trim().parse()?;

    Ok(Transaction {
        merchant_id,
        currency_code,
        amount,
        status: None,
    })
}
