typedef struct {
    int value;
    void *offset;
    char *key;
} Record;

typedef struct {
    Record **records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    FILE *log_file;
    time_t log_archival_time;
} RecordCollection;

RecordCollection* createRecordCollection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    collection->log_file = fopen("app.log", "a");
    if (!collection->log_file) {
        fprintf(stderr, "Failed to open log file\n");
    }

    time(&collection->log_archival_time);

    return collection;
}

void destroyRecordCollection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]->key);
        free(collection->records[i]);
    }

    free(collection->records);
    fclose(collection->log_file);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void logMessage(const RecordCollection *collection, const char *message) {
    pthread_mutex_lock(&collection->lock);

    if (difftime(time(NULL), collection->log_archival_time) > 86400) { // Archive logs older than a day
        fclose(collection->log_file);
        rename("app.log", "app_olddate.log");
        collection->log_file = fopen("app.log", "a");
        time(&collection->log_archival_time);
    }

    fprintf(collection->log_file, "%s\n", message);

    pthread_mutex_unlock(&collection->lock);
}

int addRecord(RecordCollection *collection, int value, void *offset, const char *key) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record*));

        if (!new_records) return -1;

        memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(Record*));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->value = value;
    record->offset = offset;
    record->key = strdup(key);

    pthread_mutex_lock(&collection->lock);
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);

    logMessage(collection, "Record added");
    return 0;
}

Record* getRecord(const RecordCollection *collection, size_t index) {
    if (index >= collection->size) return NULL;

    pthread_mutex_lock(&collection->lock);
    Record *record = collection->records[index];
    pthread_mutex_unlock(&collection->lock);

    return record;
}

void integrateExternalDataSource(RecordCollection *collection) {
    // Placeholder for integration logic with external data source
    logMessage(collection, "Integrating with external data source");

    // Simulate fetching and processing records from a remote service
    for (size_t i = 0; i < 10; ++i) {
        int value = rand() % 100;
        char *key = "remote_key";

        if (addRecord(collection, value, NULL, key) != 0) {
            logMessage(collection, "Failed to add record from external data source");
            break;
        }
    }
}

void initializeAndManageRecords(size_t num_records) {
    srand(time(NULL));

    RecordCollection *collection = createRecordCollection(10);
    if (!collection) return;

    for (size_t i = 0; i < num_records; ++i) {
        int value = rand() % 100;
        char key[20];
        snprintf(key, sizeof(key), "key_%zu", i);

        if (addRecord(collection, value, NULL, key) != 0) {
            logMessage(collection, "Failed to add initial record");
