} log_entry;

// Custom error codes
#define SUCCESS 0
#define MEM_ALLOC_FAILURE -1

// Function prototypes
long* allocateOffsets(size_t numRecords);
int* allocateKeys(size_t numRecords);
record* initializeRecords(int minVal, int maxVal, size_t numRecords);
int findMaxInArray(const int *array, size_t size);
log_entry* initializeLogEntries(size_t numEntries, size_t payloadMaxLength, unsigned long bitmask);
void logWarningIfNeeded(log_entry *entries, size_t numEntries, size_t charLimit);
size_t totalPayloadCharacters(log_entry *entries, size_t numEntries);

// Main function
int initializeAndManageRecords(int minVal, int maxVal, size_t numRecords, size_t payloadMaxLength, unsigned long bitmask) {
    // Seed random number generator
    srand((unsigned)time(NULL));

    // Allocate and initialize offset array
    long *offsets = allocateOffsets(numRecords);
    if (!offsets) return MEM_ALLOC_FAILURE;

    // Allocate and initialize key array
    int *keys = allocateKeys(numRecords);
    if (!keys) {
        free(offsets);
        return MEM_ALLOC_FAILURE;
    }

    // Initialize records
    record *records = initializeRecords(minVal, maxVal, numRecords);
    if (!records) {
        free(keys);
        free(offsets);
        return MEM_ALLOC_FAILURE;
    }

    // Read integers from stdin
    printf("Enter integers:\n");
    int *inputArray = NULL;
    size_t inputSize = 0;
    int temp;
    while (scanf("%d", &temp) == 1) {
        inputArray = realloc(inputArray, (inputSize + 1) * sizeof(int));
        if (!inputArray) break; // Handle allocation failure
        inputArray[inputSize++] = temp;
    }

    // Find and print the largest integer in the array
    int maxValInInput = findMaxInArray(inputArray, inputSize);
    printf("Largest value: %d\n", maxValInInput);

    free(inputArray); // Clean up

    // Initialize log entries
    size_t numLogEntries = 10; // Example number of entries for the log
    log_entry *logEntries = initializeLogEntries(numLogEntries, payloadMaxLength, bitmask);
    if (!logEntries) {
        free(keys);
        free(offsets);
        free(records->offset);
        free(records->key);
        free(records);
        return MEM_ALLOC_FAILURE;
    }

    // Log warnings if memory usage exceeds threshold
    logWarningIfNeeded(logEntries, numLogEntries, 1024 * 1024); // Example threshold

    // Return total number of characters used across all payloads and increment version number
    size_t totalChars = totalPayloadCharacters(logEntries, numLogEntries);

    // Clean up
    for (size_t i = 0; i < numLogEntries; ++i) {
        free(logEntries[i].payload);
    }
    free(logEntries);
    free(keys);
    free(offsets);
    free(records->offset);
    free(records->key);
    free(records);

    printf("Total characters in payloads: %zu\n", totalChars);
    return SUCCESS;
}

// Function implementations
long* allocateOffsets(size_t numRecords) {
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    if (!offsets) return NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = rand(); // Random initialization
    }
    return offsets;
}

int* allocateKeys(size_t numRecords) {
    int *keys = (int *)malloc(numRecords * sizeof(int));
    if (!keys) return NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = rand(); // Random initialization
    }
    return keys;
}

record* initializeRecords(int minVal, int maxVal, size_t numRecords) {
    record *records = (record *)malloc(numRecords * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
        records[i].offset = &((long *)malloc(sizeof(long)))[0]; // Single long per offset
        if (!records[i].offset) return NULL;
        *records[i].offset = rand();

        records[i].key = &((int *)malloc(sizeof(int)))[0]; // Single int per key
        if (!records[i].key) return NULL;
        *records[i].key = rand();
    }
    return records;
}

int findMaxInArray(const int *array, size_t size) {
    int maxVal = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > maxVal) {
            maxVal = array[i];
        }
    }
    return maxVal;
}

log_entry* initializeLogEntries(size_t numEntries, size_t payloadMaxLength, unsigned long bitmask) {
    log_entry *entries = (log_entry *)malloc(numEntries * sizeof(log_entry));
    if (!entries) return NULL;

    for (size_t i = 0; i < numEntries; ++i) {
        if (bitmask & (1UL << i)) {
            entries[i].timestamp = time(NULL);
            snprintf(entries[i].type, sizeof(entries[i].type), "INSERT");
            entries[i].key_identifier = rand();

            entries[i].payload = (char *)malloc(payloadMaxLength);
            if (!entries[i].payload) return NULL;

            // Fill payload with random alphanumeric characters
            for (size_t j = 0; j < payloadMaxLength - 1; ++j) {
                char c;
                int type = rand() % 3;
                switch (type) {
                    case 0: c = 'A' + rand() % 26; break; // Uppercase letter
                    case 1: c = 'a' + rand() % 26; break; // Lowercase letter
                    default: c = '0' + rand() % 10;     // Digit
                }
                entries[i].payload[j] = c;
            }
            entries[i].payload[payloadMaxLength - 1] = '\0';
        } else {
            memset(&entries[i], 0, sizeof(log_entry)); // Initialize to zero if not selected by bitmask
        }
    }
    return entries;
}

void logWarningIfNeeded(log_entry *entries, size_t numEntries, size_t charLimit) {
    size_t usedChars = totalPayloadCharacters(entries, numEntries);
    if (usedChars > charLimit) {
        printf("Warning: Memory usage exceeds threshold!\n");
    }
}

size_t totalPayloadCharacters(log_entry *entries, size_t numEntries) {
    size_t totalChars = 0;
    for (size_t i = 0; i < numEntries; ++i) {
        if (entries[i].payload) {
            totalChars += strlen(entries[i].payload);
        }
    }
    return totalChars;
}
