['```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class LogProcessor
{
    private readonly string _filePath;
    private readonly IProgress<int> _progressReporter;
    private CancellationTokenSource _cancellationTokenSource;
    private ConcurrentDictionary<string, byte[]> _hashMap = new ConcurrentDictionary<string, byte[]>();

    public LogProcessor(string filePath, IProgress<int> progressReporter)
    {
        _filePath = filePath;
        _progressReporter = progressReporter;
    }

    public void ProcessLogFile()
    {
        _cancellationTokenSource = new CancellationTokenSource();

        try
        {
            using var fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read);
            using var streamReader = new StreamReader(fileStream);

            int lineNumber = 0;
            string line;

            while ((line = streamReader.ReadLine()) != null)
            {
                if (_cancellationTokenSource.Token.IsCancellationRequested)
                    break;

                lineNumber++;

                Task.Run(() =>
                {
                    _hashMap[line] = GenerateSha256Hash(line);
                }, _cancellationTokenSource.Token);

                if (lineNumber % 1000 == 0)
                {
                    _progressReporter.Report((int)((double)lineNumber / streamReader.BaseStream.Length * 100));
                }
            }

            // Wait for all tasks to complete
            Task.WaitAll(_hashMap.Values.ToArray(), _cancellationTokenSource.Token);

            ExportHashesToCsv();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing log file: {ex.Message}");
        }
    }

    private byte[] GenerateSha256Hash(string input)
    {
        using var sha256 = SHA256.Create();
        return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
    }

    public void CancelProcessing()
    {
        _cancellationTokenSource?.Cancel();
    }

    private void ExportHashesToCsv()
    {
        string csvFilePath = Path.ChangeExtension(_filePath, ".csv");

        using var writer = new StreamWriter(csvFilePath);
        foreach (var hash in _hashMap)
        {
            writer.WriteLine($"{hash.Key},{BitConverter.ToString(hash.Value).Replace("-", "")}");
        }
    }

    public void ResumeProcessing()
    {
        ProcessLogFile();
    }
}

// Usage Example
public class Program
{
    public static void Main(string[] args)
    {
        var progressReporter = new Progress<int>(percent => Console.WriteLine($"Progress: {percent}%"));

        var processor = new LogProcessor("path/to/large/logfile.log", progressReporter);

        Task.Run(() => processor.ProcessLogFile());

        // Simulate user canceling the operation
        Thread.Sleep(5000); 
        processor.CancelProcessing();

        // Resume processing if needed
        processor.ResumeProcessing();
    }
}
```

### Key Points:
- **Concurrency**: Uses `Task.Run` for parallel processing of hash computations. A concurrent dictionary is used to store hashes.
- **Cancellation Support**: Implemented using a `CancellationTokenSource`, allowing operations to be safely canceled and resumed.
- **Progress Tracking**: Progress reporting integrated through an `IProgress<int>` interface.
- **CSV Export**: Efficiently writes all computed hashes to a CSV file after processing completion.
- **Resource Management**: Designed with careful memory handling in mind by using concurrent collections and task-based asynchronous patterns.
- **Future Compatibility**: The structure of the class is designed for easy integration with future logging systems.']

