    size_t initialized_count = num_keys;

    // Check for any allocation failures and clean up if necessary
    for (size_t i = 0; i < initialized_count; ++i) {
        if (!records[i].offset || !records[i].value_ptr) {
            fprintf(stderr, "Memory allocation failure detected.\n");
