import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class TaskManager {
    private static final Random random = new Random();

    private List<Task> tasks;
    private ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();

    public void initializeTaskManager(byte[] data, Config config) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Class<?> clazz = Class.forName(config.getDeserializationClassName());
            Object deserializedObject = ois.readObject();

            if (!clazz.isInstance(deserializedObject)) {
                throw new RuntimeException("Deserialized object is not an instance of the expected class.");
            }
        } catch (ClassNotFoundException e) {
            logDetailedInfo(e, "Class not found during deserialization.");
            throw new RuntimeException("Deserialization failed: Class not present in classpath.", e);
        } catch (Exception e) {
            logDetailedInfo(e, "General deserialization failure.");
            throw new RuntimeException("Deserialization failed due to an unexpected error.", e);
        }

        tasks = new ArrayList<>(config.getInitialNumberOfTasks());

        for (int i = 0; i < config.getInitialNumberOfTasks(); i++) {
            Task task = createRandomTask(config.getDescriptionLengthRange(), config.getPriorityRange());
            tasks.add(task);
        }
    }

    private void logDetailedInfo(Exception e, String message) {
        // Log the detailed information for later analysis
        System.err.println(message + ": " + e.getMessage());
        e.printStackTrace();
    }

    private Task createRandomTask(Range<Integer> descriptionLengthRange, Range<Integer> priorityRange) {
        int length = random.nextInt(descriptionLengthRange.max - descriptionLengthRange.min + 1) 
                     + descriptionLengthRange.min;
        String description = generateRandomString(length);

        int priority = random.nextInt(priorityRange.max - priorityRange.min + 1) 
                       + priorityRange.min;

        return new Task(description, priority);
    }

    private String generateRandomString(int length) {
        String characters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
        StringBuilder sb = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            int index = random.nextInt(characters.length());
            sb.append(characters.charAt(index));
        }

        return sb.toString();
    }

    public void addTask(Task task) {
        rwLock.writeLock().lock();
        try {
            tasks.add(task);
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    public void updateTask(int index, Task updatedTask) {
        rwLock.writeLock().lock();
        try {
            if (index >= 0 && index < tasks.size()) {
                tasks.set(index, updatedTask);
            }
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    public Task getTask(int index) {
        rwLock.readLock().lock();
        try {
            return index >= 0 && index < tasks.size() ? tasks.get(index) : null;
        } finally {
            rwLock.readLock().unlock();
        }
    }

    private void synchronizeWithExternalSource() {
        // Implement synchronization logic with external data source
        // Handle network latency and data integrity issues
    }

    public static class Task {
        private String description;
        private int priority;
        private long lastUpdatedTime;

        public Task(String description, int priority) {
            this.description = description;
            this.priority = priority;
            this.lastUpdatedTime = System.currentTimeMillis();
        }

        // Getters and Setters
    }

    public static class Config {
        private int initialNumberOfTasks;
        private Range<Integer> descriptionLengthRange;
        private Range<Integer> priorityRange;
        private String deserializationClassName;

        // Constructor, getters and setters

        public int getInitialNumberOfTasks() {
            return initialNumberOfTasks;
        }

        public Range<Integer> getDescriptionLengthRange() {
            return descriptionLengthRange;
        }

        public Range<Integer> getPriorityRange() {
            return priorityRange;
        }

        public String getDeserializationClassName() {
            return deserializationClassName;
        }
    }

    public static class Range<T extends Comparable<T>> {
        private T min;
        private T max;

        // Constructor, getters and setters

        public T getMin() {
            return min;
        }

        public T getMax() {
            return max;
        }
    }
}
