Record **record_list = NULL;
size_t record_count = 0;
size_t capacity = 10;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_system(size_t initial_capacity) {
    record_list = malloc(initial_capacity * sizeof(Record *));
    if (!record_list) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
}

void load_data_from_csv(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open CSV file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int key;
        double value;
        long offset;

        // Parse CSV line; assuming format: key,value,offset
        if (sscanf(line, "%d,%lf,%ld", &key, &value, &offset) == 3) {
            pthread_mutex_lock(&list_mutex);

            for (size_t i = 0; i < record_count; ++i) {
                if (record_list[i]->key == key) {
                    record_list[i]->value = (record_list[i]->value + value) / 2;
                    break;
                }
            }

            if (find_record_by_key(key) == NULL) {
                if (record_count >= capacity) {
                    capacity *= 2;
                    record_list = realloc(record_list, capacity * sizeof(Record *));
                    if (!record_list) {
                        perror("Failed to reallocate memory for records");
                        exit(EXIT_FAILURE);
                    }
                }

                Record *new_record = malloc(sizeof(Record));
                new_record->key = key;
                new_record->value = value;
                new_record->offset_ptr = &offset;

                record_list[record_count++] = new_record;
            }

            pthread_mutex_unlock(&list_mutex);
        }
    }

    fclose(file);
}

void *process_message(void *arg) {
