    const char* message = (const char*)arg;

    // Process the message here...

    return NULL;
}

Record *find_record_by_key(int key) {
    for (size_t i = 0; i < record_count; ++i) {
        if (record_list[i]->key == key) {
            return record_list[i];
        }
    }
    return NULL;
}

void cleanup_system() {
    pthread_mutex_lock(&list_mutex);

    for (size_t i = 0; i < record_count; ++i) {
        free(record_list[i]);
    }

    free(record_list);
    record_list = NULL;

    pthread_mutex_unlock(&list_mutex);
}

int main(int argc, char *argv[]) {
    init_system(10);

    if (argc > 1) {
        load_data_from_csv(argv[1]);
    } else {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    const char *messages[] = {"Message1", "Message2", "Message3", "Message4"};

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, process_message, messages[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_system();
    return 0;
}
