    }

    // Load JSON data from external file
    private void loadJsonData(Path path) throws IOException {
        ObjectMapper objectMapper = new ObjectMapper();
        List<SensorData> dataList = objectMapper.readValue(Files.newBufferedReader(path), 
                objectMapper.getTypeFactory().constructCollectionType(List.class, SensorData.class));

        for (SensorData sensorData : dataList) {
            updateRecord(sensorData);
        }
    }

    // Update record or average duplicate readings
    private void updateRecord(SensorData data) {
        records.compute(data.getTimestamp(), (key, existingRecord) -> {
            if (existingRecord == null) {
                return new Record(key, data.getValue(), data.getMetadata());
            } else {
                double newValue = (existingRecord.value + data.getValue()) / 2.0;
                return new Record(key, newValue, updateMetadata(existingRecord.metadata, data.getMetadata()));
            }
        });
    }

    // Update metadata
    private String updateMetadata(String existingMetadata, String newMetadata) {
        return existingMetadata.equals(newMetadata) ? existingMetadata : existingMetadata + ";" + newMetadata;
    }

    // Populate records with random values (for demonstration)
    private void populateRandomRecords(int count, double minValue, double maxValue) {
        Random random = new Random();
        for (int i = 0; i < count; i++) {
            int timestamp = System.currentTimeMillis() / 1000;
            double value = minValue + (maxValue - minValue) * random.nextDouble();
            String metadata = "randomData";
            records.put(timestamp, new Record(timestamp, value, metadata));
        }
    }

    // Retrieve record by timestamp
    private Optional<Record> getRecordByTimestamp(int timestamp) {
        return Optional.ofNullable(records.get(timestamp));
    }

    // Process incoming Kafka messages
    public void processMessages() {
        KafkaConsumer<String, SensorData> consumer = createKafkaConsumer();
        consumer.subscribe(Collections.singletonList("iot-topic"));

        ExecutorService executorService = Executors.newFixedThreadPool(10);

        try {
            while (true) {
                ConsumerRecords<String, SensorData> records = consumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, SensorData> record : records) {
                    executorService.submit(() -> updateRecord(record.value()));
                }
            }
        } finally {
            consumer.close();
            executorService.shutdown();
        }
    }

    // Main method to start the framework
    public static void main(String[] args) throws IOException {
        IoTDataProcessingFramework framework = new IoTDataProcessingFramework();

        // Load existing data from JSON file
        Path jsonPath = Paths.get("sensor_data.json");
        framework.loadJsonData(jsonPath);

        // Populate with random values for demonstration
        framework.populateRandomRecords(1000, 20.0, 30.0);

        // Start processing messages from Kafka
        framework.processMessages();
    }
}

class SensorData {
    private int timestamp;
    private double value;
    private String metadata;

    public int getTimestamp() { return timestamp; }
    public void setTimestamp(int timestamp) { this.timestamp = timestamp; }

    public Double getValue() { return value; }
    public void setValue(double value) { this.value = value; }

    public String getMetadata() { return metadata; }
    public void setMetadata(String metadata) { this.metadata = metadata; }
}
