#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_PAYLOAD_LENGTH 256

typedef struct {
    int64_t offset;
    int key;
} Record;

typedef struct {
    time_t timestamp;
    char type[8]; // INSERT, UPDATE, DELETE
    int key_id;
    char *payload;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t total_entries;
    size_t total_chars;
    uint32_t version;
} LogManager;

LogManager* processStringAndLogRecords(size_t num_records, int min_val, int max_val, unsigned long mem_threshold) {
    if (num_records == 0 || min_val > max_val) return NULL;

    // Initialize records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand() % 100000;
        records[i].key = min_val + rand() % (max_val - min_val + 1);
    }

    // Process integers and compute MD5 hashes
    int64_t largest_int = LLONG_MIN;
    char *largest_md5_hash = malloc(33); // MD5 hash is 32 chars + null terminator
    if (!largest_md5_hash) {
        free(records);
        return NULL;
    }

    printf("Enter integers (end with non-integer):\n");
    int num;
    while (scanf("%d", &num) == 1) {
        unsigned char md5hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)&num, sizeof(num), md5hash);

        if (num > largest_int) {
            largest_int = num;
            for (int i = 0; i < 16; ++i)
                sprintf(&largest_md5_hash[i * 2], "%02x", md5hash[i]);
        }
    }

    printf("Largest integer: %lld, MD5 hash: %s\n", largest_int, largest_md5_hash);

    // Initialize LogManager
    LogManager *logManager = (LogManager *)malloc(sizeof(LogManager));
    if (!logManager) {
        free(largest_md5_hash);
        free(records);
        return NULL;
    }

    logManager->entries = (LogEntry **)calloc(num_records, sizeof(LogEntry *));
    if (!logManager->entries) {
        free(logManager);
        free(largest_md5_hash);
        free(records);
        return NULL;
    }

    char *payload = (char *)malloc(MAX_PAYLOAD_LENGTH);
    if (!payload) {
        for (size_t i = 0; i < num_records; ++i)
            free(logManager->entries[i]);
        free(logManager->entries);
        free(largest_md5_hash);
        free(records);
        free(logManager);
        return NULL;
    }

    logManager->total_entries = 0;
    logManager->total_chars = 0;
    logManager->version = 1;

    for (size_t i = 0; i < num_records; ++i) {
        LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
        if (!entry) continue;

        entry->timestamp = time(NULL);
        snprintf(entry->type, sizeof(entry->type), "INSERT");
        entry->key_id = records[i].key;

        for (int j = 0; j < MAX_PAYLOAD_LENGTH - 1; ++j)
            payload[j] = 'a' + rand() % 26;
        payload[MAX_PAYLOAD_LENGTH - 1] = '\0';
        entry->payload = strdup(payload);

        logManager->entries[i] = entry;
        logManager->total_entries++;
        logManager->total_chars += strlen(entry->payload);
    }

    free(payload);

    // Check memory usage
    size_t total_memory_usage = sizeof(LogManager) +
                                num_records * sizeof(LogEntry *) +
                                (logManager->total_chars + num_records * sizeof(char *));
    if (total_memory_usage > mem_threshold) {
        printf("Warning: Memory usage exceeds threshold!\n");
    }

    // Clean up
    free(largest_md5_hash);
    free(records);

    return logManager;
}

// Example iteration over log entries
void iterateLogEntries(LogManager *logManager) {
    if (!logManager) return;

    for (size_t i = 0; i < logManager->total_entries; ++i) {
        LogEntry *entry = logManager->entries[i];
        if (!entry) continue;

        printf("Timestamp: %ld, Type: %s, Key ID: %d, Payload: %s\n",
               entry->timestamp, entry->type, entry->key_id, entry->payload);
    }
}

// Example usage
int main() {
    LogManager *logManager = processStringAndLogRecords(10, 1, 100, 1048576); // 1MB threshold

    if (logManager) {
        iterateLogEntries(logManager);

        for (size_t i = 0; i < logManager->total_entries; ++i) {
            LogEntry *entry = logManager->entries[i];
            if (!entry) continue;
            free(entry->payload);
            free(entry);
        }
        free(logManager->entries);
        free(logManager);
    }

    return 0;
}
