use log::{info, error, debug};

const DEFAULT_USER_COUNT: usize = 1000;

#[derive(Debug, Clone)]
struct UserProfile {
    user_id: u32,
    username: String,
    email: String,
    role: String,
    status: String,
    last_login: Instant,
    permissions: Vec<String>,
}

impl Default for UserProfile {
    fn default() -> Self {
        UserProfile {
            user_id: 0,
            username: "default_user".into(),
            email: "user@example.com".into(),
            role: "guest".into(),
            status: "active".into(),
            last_login: Instant::now(),
            permissions: vec!["read".into()],
        }
    }
}

#[derive(Error, Debug)]
enum UserProfileError {
    #[error("Memory allocation error")]
    MemoryAllocation,
    #[error("Network error: {0}")]
    Network(ReqwestError),
    #[error("API rate limit exceeded")]
    RateLimitExceeded,
}

