#include <pthread.h>

// Define severity levels as an enumeration
typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} SeverityLevel;

// Structure for log entry metadata
typedef struct {
    char *key;
    char *value;
} LogMetadata;

// Structure for a log entry
typedef struct {
    char timestamp[20];
    SeverityLevel severity;
    char message[256];
    LogMetadata *metadata;
    int metadata_count; // Number of metadata entries
} LogEntry;

// Global variables
LogEntry *log_entries = NULL;
int num_logs = 0;
pthread_mutex_t log_lock;

// Function to generate a random severity level
SeverityLevel getRandomSeverity() {
    return rand() % 5;
}

// Function to initialize log entries
void initLogs(int count) {
    pthread_mutex_init(&log_lock, NULL);
    log_entries = (LogEntry *)malloc(count * sizeof(LogEntry));
    if (!log_entries) {
        perror("Failed to allocate memory for logs");
        exit(EXIT_FAILURE);
    }
    num_logs = count;

    for (int i = 0; i < count; ++i) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        // Format timestamp
        strftime(log_entries[i].timestamp, sizeof(log_entries[i].timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Assign random severity level and a sample message
        log_entries[i].severity = getRandomSeverity();
        snprintf(log_entries[i].message, sizeof(log_entries[i].message), "Log entry number %d", i + 1);
        log_entries[i].metadata_count = 0; // Initialize metadata count

        // Allocate space for one metadata entry as an example
        log_entries[i].metadata = (LogMetadata *)malloc(sizeof(LogMetadata));
        if (!log_entries[i].metadata) {
            perror("Failed to allocate memory for metadata");
            exit(EXIT_FAILURE);
        }
        log_entries[i].metadata->key = strdup("exampleKey");
        log_entries[i].metadata->value = strdup("exampleValue");
    }
}

// Function to free allocated memory
void freeLogs() {
    pthread_mutex_lock(&log_lock);
    if (log_entries) {
        for (int i = 0; i < num_logs; ++i) {
            free(log_entries[i].metadata->key);
            free(log_entries[i].metadata->value);
            free(log_entries[i].metadata);
        }
        free(log_entries);
    }
    pthread_mutex_unlock(&log_lock);
    pthread_mutex_destroy(&log_lock);
}

// Function to search logs by keyword
void searchLogs(const char *keyword) {
    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < num_logs; ++i) {
        if (strstr(log_entries[i].message, keyword) || strstr(log_entries[i].metadata->value, keyword)) {
            printf("Found in log %d: %s\n", i + 1, log_entries[i].message);
        }
    }
    pthread_mutex_unlock(&log_lock);
}

// Comparator function for qsort to sort logs by timestamp and severity
int compareLogs(const void *a, const void *b) {
    LogEntry *entryA = (LogEntry *)a;
    LogEntry *entryB = (LogEntry *)b;

    int cmp = strcmp(entryA->timestamp, entryB->timestamp);
    if (cmp == 0) {
        return entryA->severity - entryB->severity;
    }
    return cmp;
}

// Function to sort logs
void sortLogs() {
    pthread_mutex_lock(&log_lock);
    qsort(log_entries, num_logs, sizeof(LogEntry), compareLogs);
    pthread_mutex_unlock(&log_lock);
}

// Main function demonstrating initialization and usage
int main() {
    srand(time(NULL)); // Seed random number generator

    int log_count = 10;
    initLogs(log_count);

    printf("Searching logs for 'example':\n");
    searchLogs("example");

    printf("\nSorting logs:\n");
    sortLogs();

    freeLogs();
    return 0;
}
```

