LogManager* initializeLogManager(size_t initialCapacity, const char *filePath, int rotationPolicy, int retentionPeriod) {
    if (rotationPolicy < 1 || retentionPeriod < 1) {
        fprintf(stderr, "Invalid configuration settings.\n");
        return NULL;
    }

    LogManager *manager = malloc(sizeof(LogManager));
    if (!manager) {
        perror("Failed to allocate LogManager");
        return NULL;
    }

    manager->entries = calloc(initialCapacity, sizeof(LogEntry));
    if (!manager->entries) {
