        perror("Failed to allocate LogEntries");
        return NULL;
    }

    manager->numEntries = 0;
    strncpy(manager->config.filePath, filePath, sizeof(manager->config.filePath) - 1);
    manager->config.rotationPolicy = rotationPolicy;
    manager->config.retentionPeriod = retentionPeriod;

    manager->status.currentUsage = 0;
    manager->status.capacity = initialCapacity;
    pthread_mutex_init(&manager->status.lock, NULL);

    time_t now = time(NULL);
    for (size_t i = 0; i < initialCapacity; ++i) {
        manager->entries[i].timestamp = now;
        manager->entries[i].severity = INFO;
        snprintf(manager->entries[i].message, sizeof(manager->entries[i].message), "Default message %zu", i);
    }

    pthread_mutex_init(&manager->logLock, NULL);

    return manager;
}

void destroyLogManager(LogManager *manager) {
    if (manager) {
        free(manager->entries);
        pthread_mutex_destroy(&manager->status.lock);
        pthread_mutex_destroy(&manager->logLock);
        free(manager);
    }
}

char* formatMessage(const char *message, size_t limit) {
    size_t length = strlen(message);
    if (length > limit) return NULL;

    char *formatted = malloc(length + 2); // For null-terminator and optional slash
    if (!formatted) return NULL;

    snprintf(formatted, length + 1, "%s", message);

    if (length < limit) {
        formatted[length] = '/';
        formatted[length + 1] = '\0';
    }

    return formatted;
}

void addLogEntry(LogManager *manager, const char *message, SeverityLevel severity) {
    pthread_mutex_lock(&manager->logLock);

    if (manager->numEntries >= manager->status.capacity) {
        fprintf(stderr, "Log capacity reached. Cannot add more entries.\n");
        pthread_mutex_unlock(&manager->logLock);
        return;
    }

    time_t now = time(NULL);

    manager->entries[manager->numEntries].timestamp = now;
    manager->entries[manager->numEntries].severity = severity;

    char *formattedMessage = formatMessage(message, sizeof(manager->entries[0].message) - 1);
    if (formattedMessage) {
        strncpy(manager->entries[manager->numEntries].message, formattedMessage, sizeof(manager->entries[0].message));
        free(formattedMessage);
    } else {
        snprintf(manager->entries[manager->numEntries].message, sizeof(manager->entries[0].message), "Log message too long");
    }

    manager->numEntries++;
    pthread_mutex_unlock(&manager->logLock);
}

