['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MIN_SIZE 1000
#define MAX_SIZE 10000

typedef struct {
    int value;
} record;

typedef struct MemoryManager {
    size_t total_size;
    void* pool;
    pthread_mutex_t lock;
} MemoryManager;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

bool validate_input(int n) {
    if (n < MIN_SIZE || n > MAX_SIZE) {
        log_error("Input size out of valid range.");
        return false;
    }
    return true;
}

MemoryManager* create_memory_manager(size_t total_size) {
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    manager->total_size = total_size;
    manager->pool = malloc(total_size);
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    free(manager->pool);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

bool allocate_from_pool(MemoryManager* manager, size_t size, void** ptr) {
    pthread_mutex_lock(&manager->lock);

    if ((char*)manager->pool + manager->total_size - (char*)ptr < size) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    *ptr = manager->pool;
    manager->pool = (void*)((char*)manager->pool + size);
    pthread_mutex_unlock(&manager->lock);

    return true;
}

void initialize_data_structures(int n, long** offsets, int** keys, record** records, bool** accessed) {
    MemoryManager* manager = create_memory_manager(n * (sizeof(long) + sizeof(int) + sizeof(record) + sizeof(bool)));

    if (!allocate_from_pool(manager, n * sizeof(long), (void**)offsets)) {
        log_error("Failed to allocate memory for offsets.");
        destroy_memory_manager(manager);
        return;
    }

    if (!allocate_from_pool(manager, n * sizeof(int), (void**)keys)) {
        log_error("Failed to allocate memory for keys.");
        free(*offsets);
        destroy_memory_manager(manager);
        return;
    }

    if (!allocate_from_pool(manager, n * sizeof(record), (void**)records)) {
        log_error("Failed to allocate memory for records.");
        free(*offsets);
        free(*keys);
        destroy_memory_manager(manager);
        return;
    }

    if (!allocate_from_pool(manager, n * sizeof(bool), (void**)accessed)) {
        log_error("Failed to allocate memory for accessed flags.");
        free(*offsets);
        free(*keys);
        free(*records);
        destroy_memory_manager(manager);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        (*offsets)[i] = rand() % 10000;
        (*keys)[i] = rand() % 10000;
        (*records)[i].value = rand() % 2001 - 1000;
        (*accessed)[i] = false;
    }

    destroy_memory_manager(manager);
}

int hash_function(int key, int size) {
    return abs(key % size);
}

void insert_key_offset(int* keys, long* offsets, int key, long offset, int n) {
    int index = hash_function(key, n);
    while (keys[index] != 0 && keys[index] != key) {
        index = (index + 1) % n;
    }

    if (keys[index] == 0 || keys[index] == key) {
        keys[index] = key;
        offsets[index] = offset;
    }
}

long lookup_offset(int* keys, long* offsets, int key, int n) {
    int index = hash_function(key, n);
    while (keys[index] != 0 && keys[index] != key) {
        index = (index + 1) % n;
    }

    if (keys[index] == key) {
        return offsets[index];
    }

    return -1; // Not found
}

void save_state_to_disk(const char* filename, long* offsets, int* keys, record* records, bool* accessed, int n) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for saving state.");
        return;
    }

    fwrite(offsets, sizeof(long), n, file);
    fwrite(keys, sizeof(int), n, file);
    fwrite(records, sizeof(record), n, file);
    fwrite(accessed, sizeof(bool), n, file);

    fclose(file);
}

void load_state_from_disk(const char* filename, long** offsets, int** keys, record** records, bool** accessed, int n) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for loading state.");
        return;
    }

    *offsets = malloc(n * sizeof(long));
    *keys = malloc(n * sizeof(int));
    *records = malloc(n * sizeof(record));
    *accessed = malloc(n * sizeof(bool));

    fread(*offsets, sizeof(long), n, file);
    fread(*keys, sizeof(int), n, file);
    fread(*records, sizeof(record), n, file);
    fread(*accessed, sizeof(bool), n, file);

    fclose(file);
}

void free_data_structures(long* offsets, int* keys, record* records, bool* accessed) {
    free(offsets);
    free(keys);
    free(records);
    free(accessed);
}
