async fn processAndAnalyzeFinancialData(transaction_count: usize, amount_range: (f64, f64), status_default: &str, account_mapping: Vec<u32>, connection_pool_size: usize) -> Result<(), Error> {
    let transactions = vec![
        Transaction::new(0, 0, 0.0, "", 0); 
        transaction_count
    ];

    for (i, transaction) in transactions.iter_mut().enumerate() {
        let mut rng = rand::thread_rng();
        transaction.amount = rng.gen_range(amount_range.0..amount_range.1);
        transaction.status = status_default.to_string();
        transaction.account_id = *account_mapping.get(i % account_mapping.len()).unwrap_or(&0);
    }

    let (tx, rx) = mpsc::channel(connection_pool_size);

    let pool = Pool::<MySql>::new().await?;

    for _ in 0..connection_pool_size {
        let tx = tx.clone();
        task::spawn(async move {
            loop {
                if let Ok(Some(transaction)) = rx.recv().await {
                    // Simulate API call and processing
                    tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
                }
            }
        });
    }

    for _ in 0..transaction_count {
        tx.send(Some(transactions[_])).await?;
    }

    let client = Client::builder()
        .danger_accept_invalid_certs(true)
        .build()?;

    let mut total_volume: f64 = 0.0;
    let mut transaction_amounts = VecDeque::new();

    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        if let Ok(amount_str) = line {
            if let Ok(amount) = amount_str.parse::<f64>() {
                total_volume += amount;
                transaction_amounts.push_back(amount);
            }
        }
    }

    // Calculate median
    let mut sorted_amounts: Vec<_> = transaction_amounts.into_iter().collect();
    sorted_amounts.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let median_threshold = if sorted_amounts.len() % 2 == 0 {
        (sorted_amounts[sorted_amounts.len() / 2 - 1] + sorted_amounts[sorted_amounts.len() / 2]) / 2.0
    } else {
        *sorted_amounts[sorted_amounts.len() / 2]
    };

    let filtered_volume: f64 = transaction_amounts.into_iter().filter(|&x| x > median_threshold).sum();

    // Database query
    let account_id_to_query = 1;
    let accounts = pool.query_as!(
        (f64, String, String),
        "SELECT balance, last_transaction_date, customer_name FROM Accounts WHERE account_id = ?",
        account_id_to_query
    )
    .await?;

    for (balance, date, name) in accounts {
        println!("Balance: {}, Last Transaction Date: {}, Customer Name: {}", balance, date, name);
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Error> {
