struct FeedbackClient {
    client: Client,
    base_url: String,
    headers: HashMap<String, String>,
}

impl FeedbackClient {
    async fn new(base_url: &str) -> Self {
        let client = Client::new();
        let mut headers = HashMap::new();
        // Add default headers or authentication if necessary
        FeedbackClient { client, base_url: base_url.to_string(), headers }
    }

    async fn submit_feedback(&self, feedback: &Feedback) -> Result<(), reqwest::Error> {
        let url = format!("{}/submit", self.base_url);
        self.client.post(&url)
            .headers(reqwest::header::HeaderMap::from_iter(self.headers.iter().map(|(k, v)| (k.clone(), v.clone()))))
            .json(feedback)
            .send()
            .await?
            .error_for_status()?;
        Ok(())
    }

    async fn poll_feedback_status(&self, feedback_id: &Uuid) -> Result<FeedbackStatus, reqwest::Error> {
        let url = format!("{}/status/{}", self.base_url, feedback_id);
        let response = self.client.get(&url)
            .headers(reqwest::header::HeaderMap::from_iter(self.headers.iter().map(|(k, v)| (k.clone(), v.clone()))))
            .send()
            .await?;

        if response.status().is_success() {
            let status: FeedbackStatus = response.json().await?;
            Ok(status)
        } else {
            Err(response.error_for_status().unwrap_err())
        }
    }
}

