}

async fn initializeAndManageRecords(num_records: usize, range_min: i32, range_max: i32) -> Result<Vec<Record>> {
    // Allocate memory for 'long' offsets and 'int' keys
    let mut offsets = Vec::with_capacity(num_records);
    offsets.set_len(num_records).context("Failed to allocate space for offsets")?;

    let mut keys = Vec::with_capacity(num_records);
    keys.set_len(num_records).context("Failed to allocate space for keys")?;

    // Initialize records dynamically
    let mut rng = rand::thread_rng();
    let mut records: Vec<Record> = (0..num_records)
        .map(|i| {
            let offset_ptr = offsets.as_mut_ptr().add(i);
            let key_ptr = keys.as_mut_ptr().add(i);

            Record {
                value: rng.gen_range(range_min..=range_max),
                offset_ptr,
                key_ptr,
            }
        })
        .collect();

    Ok(records)
}

fn retrieve_record(records: &[Record], index: usize) -> Result<&Record> {
    records.get(index).ok_or_else(|| anyhow::anyhow!("Invalid record index"))
}

