    let stdin = io::stdin();
    let input = stdin.lock();
    let mut integers = Vec::new();

    for line in input.lines() {
        let num: i32 = line?.parse().context("Failed to parse integer")?;
        integers.push(num);
    }

    Ok(integers)
}

fn find_largest_integer(integers: &[i32]) -> Result<i32> {
    integers.iter().cloned().max().ok_or_else(|| anyhow::anyhow!("No integers found"))
        .context("Failed to find the largest integer")
}

