    let connector = TlsConnector::from(Arc::new(rustls::ClientConfig::builder()
        .with_safe_defaults()
        .with_no_client_auth()
        .build()?));

    loop {
        match TcpStream::connect("java-backend.example.com:443").await {
            Ok(stream) => {
                let domain_name = DNSNameRef::try_from_ascii_str("java-backend.example.com")?;
                let stream = connector.connect(domain_name, stream).await.context("TLS connection failed")?;

                // Handle communication with the Java backend here
