                break;
            },
            Err(e) => {
                eprintln!("Connection error: {}", e);
                tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
            }
        }
    }

    Ok(())
}

fn create_http_client(url: &str, disable_cert_validation: bool) -> Result<reqwest::Client> {
    let mut builder = ClientBuilder::new();

    if disable_cert_validation {
        builder.ca_pem(None);
    }

    builder.build().context("Failed to build HTTP client")
}

async fn main_task(num_records: usize, range_min: i32, range_max: i32) -> Result<()> {
    // Initialize records
    let records = initializeAndManageRecords(num_records, range_min, range_max).await?;

    // Retrieve a specific record for demonstration
    if let Ok(record) = retrieve_record(&records, 0) {
        println!("Retrieved Record: {:?}", record);
    }

    // Read integers from stdin and find the largest one
    let integers = read_integers_from_stdin().await?;
    let largest_integer = find_largest_integer(&integers)?;

    println!("Largest integer: {}", largest_integer);

    // Handle remote service connections asynchronously
    handle_remote_service_connections().await?;

