#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TASKS_PER_BLOCK 100
#define MEMORY_POOL_SIZE (MAX_TASKS_PER_BLOCK * 10) // Total memory pool size in blocks
#define ACTIVE_MEMORY_USAGE_LIMIT 0.8

typedef struct {
    char* description;
    int priority;
    time_t timestamp;
    uint64_t unique_id;
} Task;

typedef struct MemoryBlock {
    Task tasks[MAX_TASKS_PER_BLOCK];
    int used_count;
    struct MemoryBlock* next;
} MemoryBlock;

typedef struct {
    MemoryBlock* head;
    MemoryBlock* tail;
    size_t total_size;
    size_t active_size;
} CustomAllocator;

CustomAllocator allocator = {NULL, NULL, MEMORY_POOL_SIZE * sizeof(Task), 0};

MemoryBlock* allocate_block() {
    if (allocator.active_size + MAX_TASKS_PER_BLOCK * sizeof(Task) > MEMORY_POOL_SIZE * sizeof(Task)) return NULL;

    MemoryBlock* new_block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    memset(new_block, 0, sizeof(MemoryBlock));

    if (!allocator.head) {
        allocator.head = allocator.tail = new_block;
    } else {
        allocator.tail->next = new_block;
        allocator.tail = new_block;
    }

    allocator.total_size += MAX_TASKS_PER_BLOCK * sizeof(Task);
    return new_block;
}

Task* add_task(const char* description, int priority) {
    if (allocator.active_size >= MEMORY_POOL_SIZE * sizeof(Task) * ACTIVE_MEMORY_USAGE_LIMIT)
        return NULL;

    MemoryBlock* block = allocator.head;
    while (block) {
        for (int i = 0; i < MAX_TASKS_PER_BLOCK; ++i) {
            if (!block->tasks[i].description) { // Find empty slot
                Task* task = &block->tasks[i];
                task->description = strdup(description);
                task->priority = priority;
                task->timestamp = time(NULL);
                task->unique_id = rand(); // Replace with a more robust unique ID generator
                block->used_count++;
                allocator.active_size += sizeof(Task);
                return task;
            }
        }
        block = block->next;
    }

    MemoryBlock* new_block = allocate_block();
    if (!new_block) return NULL;

    Task* first_task = &new_block->tasks[0];
    first_task->description = strdup(description);
    first_task->priority = priority;
    first_task->timestamp = time(NULL);
    first_task->unique_id = rand(); // Replace with a more robust unique ID generator
    new_block->used_count++;
    allocator.active_size += sizeof(Task);
    return first_task;
}

Task* get_task_by_id(uint64_t id) {
    MemoryBlock* block = allocator.head;
    while (block) {
        for (int i = 0; i < MAX_TASKS_PER_BLOCK; ++i) {
            if (block->tasks[i].unique_id == id && block->tasks[i].description)
                return &block->tasks[i];
        }
        block = block->next;
    }
    return NULL;
}

void update_task(uint64_t id, const char* description, int priority) {
    Task* task = get_task_by_id(id);
    if (task) {
        free(task->description); // Free existing description
        task->description = strdup(description);
        task->priority = priority;
    }
}

void list_tasks_sorted() {
    Task temp[MEMORY_POOL_SIZE];
    size_t count = 0;

    MemoryBlock* block = allocator.head;
    while (block) {
        for (int i = 0; i < MAX_TASKS_PER_BLOCK; ++i) {
            if (block->tasks[i].description)
                temp[count++] = block->tasks[i];
        }
        block = block->next;
    }

    // Sort tasks first by priority, then by timestamp
    qsort(temp, count, sizeof(Task), [](const void* a, const void* b) {
        Task* taskA = (Task*)a;
        Task* taskB = (Task*)b;

        if (taskA->priority != taskB->priority)
            return taskA->priority - taskB->priority;
        else
            return difftime(taskB->timestamp, taskA->timestamp);
    });

    for (size_t i = 0; i < count; ++i) {
        printf("ID: %llu, Priority: %d, Timestamp: %ld, Description: %s\n",
               temp[i].unique_id, temp[i].priority, temp[i].timestamp, temp[i].description);
    }
}

void free_resources() {
    MemoryBlock* block = allocator.head;
    while (block) {
        for (int i = 0; i < MAX_TASKS_PER_BLOCK; ++i) {
            if (block->tasks[i].description)
                free(block->tasks[i].description);
        }
        MemoryBlock* next_block = block->next;
        free(block);
        block = next_block;
    }
}

int main() {
    add_task("Task 1", 2);
    add_task("Task 2", 1);
    list_tasks_sorted();
    update_task(0, "Updated Task 1", 3); // Replace with actual ID
    list_tasks_sorted();
    free_resources();
    return 0;
}
