struct DataElement {
    value: f64,
    next: Option<Box<DataElement>>,
}

impl Drop for DataElement {
    fn drop(&mut self) {
        while let Some(next) = self.next.take() {
            std::mem::drop(next);
        }
    }
}

#[derive(Debug)]
struct DataSet {
    float_value: f32,
