    srand(time(NULL));
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % INT_MAX;
    }
}

void detectDuplicateKeys(int* keys, size_t num_keys) {
    for (size_t i = 0; i < num_keys; ++i) {
        for (size_t j = i + 1; j < num_keys; ++j) {
            if (keys[i] == keys[j]) {
                fprintf(stderr, "Duplicate key detected at index %zu\n", j);
                exit(EXIT_FAILURE);
            }
        }
    }
}

