        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }
}

int findLargestInteger(const int* array, size_t length) {
    if (!array || length == 0) return INT_MIN;
    int largest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void serializeRecords(const Record* records, size_t num_records, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        return;
    }
    fwrite(records->offsets, sizeof(long), num_records, file);
    fwrite(&num_records, sizeof(size_t), 1, file);
    fclose(file);
}

void deserializeRecords(Record** records, size_t* num_records, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return;
    }
    Record temp;
    fread(temp.offsets, sizeof(long), 1, file);
    fread(num_records, sizeof(size_t), 1, file);
    *records = allocateRecords(*num_records);
    if (*records) {
        fread((*records)->offsets, sizeof(long), *num_records, file);
    }
    fclose(file);
}
