                Ok(client) => {
                    println!("HTTP Client created for URL: {}", url);
                },
                Err(e) => eprintln!("Failed to create HTTP client: {}", e),
            }
        }
        Err(err) => eprintln!("Error initializing records: {}", err),
    }

    Ok(())
}
