void initializeAndManageRecords(long *offsetArray, size_t offsetSize, int *keyArray, size_t keySize,
                                record ***records, size_t initialCapacity) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    if (!(*records = malloc(initialCapacity * sizeof(record*)))) {
        perror("Memory allocation failed");
        return;
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            perror("Memory allocation failed");
            while (--i >= 0) free((*records)[i]);
            free(*records);
            *records = NULL;
            pthread_mutex_destroy(&lock);
            return;
        }
        (*records)[i]->value = rand() % (keySize - offsetSize + 1); // Random value within the range
        (*records)[i]->offsetPtr = &offsetArray[(*records)[i]->value];
        (*records)[i]->keyPtr = &keyArray[(*records)[i]->value];
    }

    findMaxInArray((int*)keyArray, keySize);

    pthread_mutex_lock(&lock);
    // Here you can add logic to grow or shrink the array as needed
    pthread_mutex_unlock(&lock);

    pthread_mutex_destroy(&lock);
}

static void findMaxInArray(int *array, size_t size) {
    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
