```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 10485760 // Example maximum memory size in bytes (10 MB)
#define INITIAL_RECORD_CAPACITY 100

typedef struct {
    long timestamp;
    int key;
    double value;
} Record;

// Global variables for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Record *records = NULL;
size_t record_count = 0;
size_t record_capacity = 0;

void checkMemoryUsage(size_t size) {
    // Example function to check if the memory usage exceeds a threshold
    if (getAllocatedMemorySize() + size > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded!\n");
        exit(EXIT_FAILURE);
    }
}

size_t getAllocatedMemorySize() {
    return record_capacity * sizeof(Record);
}

void expandRecords(size_t new_capacity) {
    checkMemoryUsage(new_capacity * sizeof(Record));
    Record *new_records = realloc(records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory!\n");
        exit(EXIT_FAILURE);
    }
    records = new_records;
    record_capacity = new_capacity;
}

void initializeAndManageRecords() {
    pthread_mutex_lock(&lock);

    // Initialize arrays and set initial capacity
    checkMemoryUsage(INITIAL_RECORD_CAPACITY * sizeof(Record));
    expandRecords(INITIAL_RECORD_CAPACITY);

    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = rand() % 1000; // Example key initialization
        while (1) {
            int unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (records[j].key == records[i].key) {
                    records[i].key++;
                    unique = 0;
                    break;
                }
            }
            if (unique) break;
        }
    }

    pthread_mutex_unlock(&lock);
}

Record* getRecordByIndex(size_t index) {
    pthread_mutex_lock(&lock);
    Record *record = NULL;
    if (index < record_count) {
        record = &records[index];
    }
    pthread_mutex_unlock(&lock);
    return record;
}

double getMaxValue() {
    double max_value = records[0].value; // Assuming at least one record exists
    for (size_t i = 1; i < record_count; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

void freeResources() {
    pthread_mutex_lock(&lock);
    free(records);
    records = NULL;
    record_count = 0;
    record_capacity = 0;
    pthread_mutex_unlock(&lock);
}
