#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

typedef struct record {
    int value;
    time_t timestamp;
    char status_flag;
    int reference_count;
} record;

typedef struct data_structure {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    pthread_mutex_t lock;
} data_structure;

data_structure* create_data_structure(size_t initial_capacity) {
    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) return NULL;

    ds->capacity = round_up_to_power_of_two(initial_capacity);
    ds->offsets = calloc(ds->capacity, sizeof(long));
    ds->keys = calloc(ds->capacity, sizeof(int));
    ds->records = calloc(ds->capacity, sizeof(record));

    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void free_data_structure(data_structure *ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

size_t round_up_to_power_of_two(size_t x) {
    --x;
    for (size_t i = 1; i < sizeof(size_t) * 8; ++i)
        x |= x >> i;
    return x + 1;
}

void populate_records(data_structure *ds, size_t num_records, int (*rng_func)(int, int)) {
    if (!ds || !ds->records) return;

    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < num_records && i < ds->capacity; ++i) {
        ds->records[i].value = rng_func(1, 1000);
        memset(&ds->records[i], 0, sizeof(record));
        ds->records[i].timestamp = time(NULL);
        ds->records[i].status_flag = 'A';
        ds->records[i].reference_count = 1;
    }
    pthread_mutex_unlock(&ds->lock);
}

// Example random number generator function
int simple_rng(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void garbage_collect(data_structure *ds) {
    if (!ds || !ds->records) return;

    pthread_mutex_lock(&ds->lock);
    // Implement compaction logic to reclaim unused memory blocks
    pthread_mutex_unlock(&ds->lock);
}
