['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75
#define MEMORY_USAGE_THRESHOLD 0.70

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
} Collection;

Collection* create_collection() {
    Collection *col = malloc(sizeof(Collection));
    if (!col) return NULL;

    col->capacity = INITIAL_CAPACITY;
    col->size = 0;
    col->records = calloc(col->capacity, sizeof(Record));

    if (!col->records) {
        free(col);
        return NULL;
    }

    return col;
}

int resize_collection(Collection *col) {
    size_t new_capacity = col->capacity * 2;
    Record *new_records = realloc(col->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    col->records = new_records;
    col->capacity = new_capacity;
    return 0;
}

int add_record(Collection *col, int value, long offset) {
    if ((double)col->size / col->capacity >= LOAD_FACTOR_THRESHOLD) {
        if (resize_collection(col)) {
            fprintf(stderr, "Failed to resize collection\n");
            return -1;
        }
    }

    Record record = {value, offset};
    size_t index = col->size % col->capacity;

    while (col->records[index].offset != 0) {
        index = (index + 1) % col->capacity; // Secondary probing
    }

    col->records[index] = record;
    col->size++;
    return 0;
}

void free_collection(Collection *col) {
    if (!col) return;

    free(col->records);
    free(col);
}

int serialize_collection(const Collection *col, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t written = fwrite(&col->capacity, sizeof(size_t), 1, file);
    if (written != 1) goto error;

    written = fwrite(col->records, sizeof(Record), col->size, file);
    if (written != col->size) goto error;

    fclose(file);
    return 0;

error:
    fclose(file);
    fprintf(stderr, "Serialization failed\n");
    return -1;
}

int deserialize_collection(Collection **col, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    Collection *new_col = create_collection();
    if (!new_col) goto error;

    size_t capacity;
    size_t read = fread(&capacity, sizeof(size_t), 1, file);
    if (read != 1) goto error;

    new_col->records = realloc(new_col->records, capacity * sizeof(Record));
    if (!new_col->records) goto free_error;

    read = fread(new_col->records, sizeof(Record), capacity, file);
    if (read < capacity) {
        // Handle partial reads or checksum validation here
    }

    new_col->capacity = capacity;
    new_col->size = read;
    *col = new_col;
    fclose(file);
    return 0;

free_error:
    free_collection(new_col);

error:
    fclose(file);
    fprintf(stderr, "Deserialization failed\n");
    return -1;
}

int main() {
    Collection *col = create_collection();
    if (!col) {
        fprintf(stderr, "Failed to create collection\n");
        return 1;
    }

    for (int i = 0; i < 50; ++i) {
        add_record(col, i, (long)i * 10);
    }

    if (serialize_collection(col, "collection.dat") != 0) {
        fprintf(stderr, "Serialization error\n");
        free_collection(col);
        return 1;
    }

    Collection *loaded_col = NULL;
    if (deserialize_collection(&loaded_col, "collection.dat") != 0) {
        fprintf(stderr, "Deserialization error\n");
        free_collection(col);
        return 1;
    }

    // Use loaded_col...

    free_collection(loaded_col);
    free_collection(col);
    return 0;
}
