    if (!rec || !newMetadata) return; // Error handling for null pointers

    strncpy(rec->metadata, newMetadata, 255);
    rec->metadata[255] = '\0'; // Ensure null termination
}

// API function to search records with weights exceeding a threshold
size_t searchRecordsByWeightThreshold(record* records, size_t count, double threshold) {
    if (!records || count == 0) return 0; // Error handling for invalid input

    size_t resultCount = 0;
    for (size_t i = 0; i < count; ++i) {
        if (*records[i].weightPtr > threshold) {
            ++resultCount;
        }
    }
    return resultCount;
}

