        let trusted_ips = vec!["127.0.0.1".to_string()];

        Config { trusted_ips }
    }
}

async fn process_event(event: Event) -> Result<(), ProcessingError> {
    // Implement your business rules validation and transformation here.

    Ok(())
}

struct WorkerConfig {
    event_sender: UnboundedSender<Event>,
}

impl WorkerConfig {
    async fn new(config: Arc<Config>) -> Self {
        let (event_sender, mut event_receiver): (
            UnboundedSender<Event>,
            mpsc::UnboundedReceiver<Event>,
        ) = mpsc::unbounded_channel();

        // Start worker tasks
        task::spawn(Self::worker(event_receiver));

        WorkerConfig { event_sender }
    }

    async fn worker(receiver: mpsc::UnboundedReceiver<Event>) {
        while let Some(event) = receiver.recv().await {
            match process_event(event).await {
                Ok(_) => {} // Log success or handle appropriately
                Err(e) => {
                    eprintln!("Error processing event: {:?}", e);
                    // Implement error reporting and handling
                }
            }
        }
    }

    async fn report_progress() {
        // Implement progress reporting logic
    }
}

async fn health_check(
    config: web::Data<Arc<Config>>,
    ip_addr: String,
) -> HttpResponse {
    if config.trusted_ips.contains(&ip_addr) {
        Ok(HttpResponse::Ok().json("Service is healthy"))
    } else {
        Ok(HttpResponse::Unauthorized().finish())
    }
}

#[tokio::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    let config: Arc<RwLock<Config>> = Arc::new(RwLock::new(Config::default()));

    // Start worker configuration
    let _worker_config = WorkerConfig::new(config.clone()).await;

    HttpServer::new(move || {
        App::new()
            .wrap(middleware::Logger::default())
            .wrap_fn(|req, srv| {
                let ip_addr = req.peer_addr().unwrap_or_default().ip().to_string();
                let config = config.read().await;

                if !config.trusted_ips.contains(&ip_addr) {
                    return Ok::<_, actix_web::Error>(srv.call(req).map_err(|_| actix_web::error::ErrorUnauthorized("Unauthorized IP")));
                }

                srv.call(req)
            })
            .app_data(web::Data::new(config.clone()))
            .route("/health", web::get().to(health_check))
    })
    .bind("127.0.0.1:8080")?
