    int value;
    long *offset_ptr;
    int *key_ptr;
} record_t;

// Structure to manage records and associated data
typedef struct {
    size_t count;
    size_t capacity;
    record_t **records;
    pthread_mutex_t lock;
} record_manager_t;

// Function prototypes
record_manager_t* create_record_manager(size_t initial_capacity);
int add_record(record_manager_t *manager, int value_range);
record_t* get_record_by_index(record_manager_t *manager, size_t index);
int update_record(record_manager_t *manager, size_t index, int new_value);
void free_record_manager(record_manager_t *manager);

// Helper function to generate a random integer within a specified range
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record_manager_t* create_record_manager(size_t initial_capacity) {
    record_manager_t *manager = malloc(sizeof(record_manager_t));
    if (!manager) return NULL;

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->records = calloc(initial_capacity, sizeof(record_t*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int add_record(record_manager_t *manager, int value_range) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        record_t **new_records = realloc(manager->records, new_capacity * sizeof(record_t*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    record_t *record = malloc(sizeof(record_t));
    if (!record) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Out of memory
    }

    int value = random_int(0, value_range);
    long offset = rand(); // Simulate a random offset

    record->value = value;
    record->offset_ptr = malloc(sizeof(long));
    if (!record->offset_ptr) {
        free(record);
        pthread_mutex_unlock(&manager->lock);
        return -3; // Out of memory
    }
    *record->offset_ptr = offset;

    int key = rand(); // Simulate a random key

    record->key_ptr = malloc(sizeof(int));
    if (!record->key_ptr) {
        free(record->offset_ptr);
        free(record);
        pthread_mutex_unlock(&manager->lock);
        return -4; // Out of memory
    }
    *record->key_ptr = key;

    manager->records[manager->count++] = record;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

record_t* get_record_by_index(record_manager_t *manager, size_t index) {
    if (index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    record_t *record = manager->records[index];
    pthread_mutex_unlock(&manager->lock);

    return record;
}

int update_record(record_manager_t *manager, size_t index, int new_value) {
    if (index >= manager->count) return -1; // Invalid index

    pthread_mutex_lock(&manager->lock);
    record_t *record = manager->records[index];
    record->value = new_value;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void free_record_manager(record_manager_t *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        record_t *record = manager->records[i];
        free(record->offset_ptr);
        free(record->key_ptr);
        free(record);
    }
    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

This code provides a dynamic memory management system for handling records, ensuring thread safety with mutex locks and offering functions to add, update, retrieve, and free records. It includes error handling for allocation failures and uses simple randomization to simulate data values and keys.']

