['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    int *keys;
    long *offsets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

// Utility function to generate a random number within a range
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize the hash table
HashTable* create_hash_table() {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) { perror("Failed to allocate memory for hash table"); exit(EXIT_FAILURE); }

    ht->size = 0;
    ht->capacity = INITIAL_SIZE;
    ht->records = calloc(ht->capacity, sizeof(Record));
    ht->keys = malloc(ht->capacity * sizeof(int));
    ht->offsets = malloc(ht->capacity * sizeof(long));

    if (!ht->records || !ht->keys || !ht->offsets) {
        perror("Failed to allocate memory for hash table elements");
        free(ht->records);
        free(ht->keys);
        free(ht->offsets);
        free(ht);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

// Hash function
size_t hash_function(int key, size_t capacity) {
    return (size_t)(key % capacity);
}

// Resize the hash table
void resize_hash_table(HashTable *ht) {
    size_t new_capacity = ht->capacity * 2;
    Record *new_records = calloc(new_capacity, sizeof(Record));
    int *new_keys = malloc(new_capacity * sizeof(int));
    long *new_offsets = malloc(new_capacity * sizeof(long));

    if (!new_records || !new_keys || !new_offsets) {
        perror("Failed to allocate memory during resizing");
        free(new_records);
        free(new_keys);
        free(new_offsets);
        exit(EXIT_FAILURE); // Handle this more gracefully in production code
    }

    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->keys[i] != -1) { // Assume -1 is a marker for empty slots
            size_t index = hash_function(ht->keys[i], new_capacity);
            while (new_keys[index] != -1) {
                index = (index + 1) % new_capacity;
            }
            new_records[index] = ht->records[i];
            new_keys[index] = ht->keys[i];
            new_offsets[index] = ht->offsets[i];
        }
    }

    free(ht->records);
    free(ht->keys);
    free(ht->offsets);

    ht->records = new_records;
    ht->keys = new_keys;
    ht->offsets = new_offsets;
    ht->capacity = new_capacity;
}

// Insert a record into the hash table
void insert_record(HashTable *ht, int key, int value_min, int value_max) {
    pthread_mutex_lock(&ht->lock);

    if ((float)ht->size / ht->capacity >= LOAD_FACTOR) {
        resize_hash_table(ht);
    }

    size_t index = hash_function(key, ht->capacity);
    while (ht->keys[index] != -1 && ht->keys[index] != key) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->keys[index] == -1) { // Insert new record
        ht->records[index].key = key;
        ht->records[index].offset = (long)(rand_in_range(0, 100000)); // Example range for offset
        ht->records[index].value = rand_in_range(value_min, value_max);
        ht->keys[index] = key;
        ht->size++;
    }

    pthread_mutex_unlock(&ht->lock);
}

// Retrieve a record by its key
Record* get_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);

    size_t index = hash_function(key, ht->capacity);
    while (ht->keys[index] != -1 && ht->keys[index] != key) {
        index = (index + 1) % ht->capacity;
    }

    Record *record = NULL;
    if (ht->keys[index] == key) {
        record = &ht->records[index];
    }

    pthread_mutex_unlock(&ht->lock);
    return record;
}

// Free the hash table
void destroy_hash_table(HashTable *ht) {
    free(ht->records);
    free(ht->keys);
    free(ht->offsets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    HashTable *ht = create_hash_table();

    insert_record(ht, 1, 10, 100); 
    insert_record(ht, 2, 20, 200);

    Record *record = get_record(ht, 1);
    if (record) {
        printf("Record key: %d, value: %d\n", record->key, record->value);
    } else {
        printf("Record not found.\n");
    }

    destroy_hash_table(ht);

    return 0;
}
```

This implementation creates a simple hash table to manage records with unique integer keys. It includes dynamic resizing and thread safety using mutexes for concurrent access. The code ensures safe memory management, prevents leaks, handles potential memory exhaustion during resizing by exiting gracefully (though more robust handling is recommended in production), and uses logging comments where necessary. Adjustments may be needed based on specific use cases or performance requirements.']

