    HIGH
} Priority;

typedef struct {
    time_t timestamp;
    Priority priority;
    char *payload;
} Message;

typedef struct Event {
    int id;
    Message *message;
    int status; // 0: pending, 1: in progress, 2: completed
    struct Event *next;
} Event;

typedef struct Client {
    int socket_descriptor;
    Event *subscribed_messages;
    time_t last_seen_activity;
} Client;

void free_message(Message *msg) {
    if (msg) {
        free(msg->payload);
        free(msg);
    }
}

void free_event(Event *event) {
    while (event) {
        Event *next = event->next;
        free_message(event->message);
        free(event);
        event = next;
    }
}

void processDynamicDataPipeline(Message **messages, int msg_count, Client **clients, int client_count) {
    srand(time(NULL));

    pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
    Event *event_queue = NULL;

    for (int i = 0; i < msg_count; ++i) {
        Message *msg = (Message *)malloc(sizeof(Message));
        if (!msg) {
            perror("Failed to allocate message");
            exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        msg->timestamp = now + rand() % 100; // Random timestamp within range
        msg->priority = (Priority)(rand() % 3); // Random priority

        size_t payload_size = rand() % 256;
        msg->payload = (char *)malloc(payload_size + 1);
        if (!msg->payload) {
            perror("Failed to allocate payload");
            free_message(msg);
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < payload_size; ++j)
            msg->payload[j] = 'a' + rand() % 26;
        msg->payload[payload_size] = '\0';

        Event *new_event = (Event *)malloc(sizeof(Event));
        if (!new_event) {
            perror("Failed to allocate event");
            free_message(msg);
            exit(EXIT_FAILURE);
        }

        new_event->id = i;
        new_event->message = msg;
        new_event->status = 0; // pending
        new_event->next = NULL;

        pthread_mutex_lock(&queue_lock);

        if (!event_queue) {
            event_queue = new_event;
        } else {
            Event *current = event_queue;
            while (current->next)
                current = current->next;
            current->next = new_event;
        }

        pthread_mutex_unlock(&queue_lock);
    }

    for (int i = 0; i < client_count; ++i) {
        Client *client = (Client *)malloc(sizeof(Client));
        if (!client) {
            perror("Failed to allocate client");
            exit(EXIT_FAILURE);
        }

        client->socket_descriptor = rand() % 1024;
        client->subscribed_messages = NULL;
        client->last_seen_activity = time(NULL);

        // Example of subscribing a message (randomly chosen)
        pthread_mutex_lock(&queue_lock);

        if (event_queue) {
            int random_msg_index = rand() % msg_count;
            Event *current_event = event_queue;

            for (int j = 0; j < random_msg_index && current_event->next != NULL; ++j)
                current_event = current_event->next;

            Event *new_sub_event = (Event *)malloc(sizeof(Event));
            if (!new_sub_event) {
                perror("Failed to allocate subscription event");
                pthread_mutex_unlock(&queue_lock);
                free(client);
                exit(EXIT_FAILURE);
            }

            new_sub_event->id = -1; // indicates a subscription
            new_sub_event->message = current_event->message;
            new_sub_event->status = 0; // subscribed
            new_sub_event->next = NULL;

            if (!client->subscribed_messages) {
                client->subscribed_messages = new_sub_event;
            } else {
                Event *current_client_event = client->subscribed_messages;
                while (current_client_event->next)
                    current_client_event = current_client_event->next;
                current_client_event->next = new_sub_event;
            }
        }

        pthread_mutex_unlock(&queue_lock);

        clients[i] = client;

        // Simulate async operations
        if ((rand() % 10) < 3) { // simulate a connection failure or change
            close(client->socket_descriptor);
            client->last_seen_activity = time(NULL);
        }
    }

    // Clean up at the end (normally you'd have more complex handling)
    while (event_queue) {
        Event *next_event = event_queue->next;
        free_event(event_queue);
        event_queue = next_event;
    }

    for (int i = 0; i < client_count; ++i) {
        if (clients[i]) {
            free_event(clients[i]->subscribed_messages);
            free(clients[i]);
        }
    }

    pthread_mutex_destroy(&queue_lock);
}

// Usage example:
// Message *messages[100];
// Client *clients[10];
// processDynamicDataPipeline(messages, 100, clients, 10);

