    resource_usage* usage_records = (resource_usage*)malloc(resource_count * sizeof(resource_usage));

    if (!metrics || !logs || !usage_records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Populate metrics and event logs
    populate_metrics(&metrics, metric_count, 0, 100);
    populate_event_logs(&logs, log_count, 1, 10);

    // Allocate memory for strings in structs
    for (size_t i = 0; i < log_count; ++i) {
        logs[i].message = strdup("Sample message");
    }
    for (size_t i = 0; i < resource_count; ++i) {
        usage_records[i].description = strdup("Resource description");
    }

    // Fetch remote data in a separate thread
    pthread_t fetch_thread;
    if (pthread_create(&fetch_thread, NULL, (void* (*)(void*))fetch_remote_data, NULL)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }
    pthread_join(fetch_thread, NULL);

    // Log resource usage to a file
    FILE* log_file = fopen("resource_usage.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    log_resource_usage(&usage_records, resource_count, log_file);
    fclose(log_file);

    // Free allocated memory
    for (size_t i = 0; i < log_count; ++i) {
        free(logs[i].message);
    }
    for (size_t i = 0; i < resource_count; ++i) {
        free(usage_records[i].description);
    }

    free(metrics);
    free(logs);
    free(usage_records);

    return 0;
}

void populate_metrics(metric** metrics, size_t count, unsigned short start_index, unsigned short limit) {
    for (size_t i = 0; i < count; ++i) {
        (*metrics)[i].status_flag = 'A';
        (*metrics)[i].index = start_index + i;
        (*metrics)[i].value = (double)(start_index + i);
    }
}

void populate_event_logs(event_log** logs, size_t count, int start_type, int limit) {
    for (size_t i = 0; i < count; ++i) {
        (*logs)[i].timestamp = time(NULL);
        (*logs)[i].event_type = start_type + i;
    }
}

void log_resource_usage(resource_usage** usage_records, size_t count, FILE* file) {
    for (size_t i = 0; i < count; ++i) {
        fprintf(file, "Memory Usage: %u, CPU Percentage: %.2f, Description: %s\n",
                (*usage_records)[i].memory_usage,
                (*usage_records)[i].cpu_percentage,
                (*usage_records)[i].description);
    }
}
