    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node *node) {
    if (node) {
        free(node->array);
        free(node);
    }
}

void free_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(int array_size) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->array = (int*)calloc(array_size, sizeof(int));
    for (int i = 0; i < array_size; ++i) {
        node->array[i] = i;
    }
    node->next = NULL;
    return node;
}

void add_node(LinkedList *list, int array_size) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = create_node(array_size);
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void remove_all_nodes(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    while (list->head != NULL) {
        Node *temp = list->head;
        list->head = temp->next;
        free_node(temp);
    }

    pthread_mutex_unlock(&list->lock);
}

