// Create a new transaction cache
TransactionCache* create_transaction_cache(size_t capacity) {
    TransactionCache *cache = (TransactionCache *)malloc(sizeof(TransactionCache));
    if (!cache) handle_allocation_failure();

    cache->transactions = malloc(capacity * sizeof(TransactionList)); // Simplified; consider using a more complex data structure.
    if (!cache->transactions) { free(cache); handle_allocation_failure(); }

    for (size_t i = 0; i < capacity; ++i) {
        cache->transactions[i].head = NULL;
        pthread_mutex_init(&cache->transactions[i].lock, NULL);
    }

    cache->capacity = capacity;
    pthread_rwlock_init(&cache->rwlock, NULL);
    return cache;
}

void destroy_transaction_cache(TransactionCache *cache) {
    if (!cache) return;

    for (size_t i = 0; i < cache->capacity; ++i) {
        Node *current = cache->transactions[i].head;
        while (current) {
            Node *next = current->next;
            free(current->transaction);
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&cache->transactions[i].lock);
    }

    free(cache->transactions);
    pthread_rwlock_destroy(&cache->rwlock);
    free(cache);
}

int insert_transaction(TransactionCache *cache, const char *transactionID, void *metadata) {
    if (!cache || !transactionID) return -1;

    time_t now;
    time(&now);

    // Lock the cache for write access
    pthread_rwlock_wrlock(&cache->rwlock);

    Transaction *newTransaction = (Transaction *)malloc(sizeof(Transaction));
    if (!newTransaction) { handle_allocation_failure(); }

    strncpy(newTransaction->transactionID, transactionID, sizeof(newTransaction->transactionID) - 1);
    newTransaction->timestamp = now;
    newTransaction->data.value = 0.0;
    strncpy(newTransaction->data.status, "pending", sizeof(newTransaction->data.status) - 1);
    newTransaction->data.metadata = metadata;

    // Simplified insertion into the transaction list (using a hash function to determine index)
    size_t index = hash_function(transactionID) % cache->capacity; // Assume hash_function is defined
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) { free(newTransaction); handle_allocation_failure(); }

    newNode->transaction = newTransaction;
    newNode->next = cache->transactions[index].head;
    cache->transactions[index].head = newNode;

    pthread_rwlock_unlock(&cache->rwlock);
    log_transaction(newTransaction);

    return 0;
}

Transaction* get_transaction(TransactionCache *cache, const char *transactionID) {
    if (!cache || !transactionID) return NULL;

    // Lock the cache for read access
    pthread_rwlock_rdlock(&cache->rwlock);

    size_t index = hash_function(transactionID) % cache->capacity; // Assume hash_function is defined
    TransactionList *list = &cache->transactions[index];

    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current) {
        if (strcmp(current->transaction->transactionID, transactionID) == 0) {
            Transaction *result = current->transaction;
            pthread_mutex_unlock(&list->lock);
            pthread_rwlock_unlock(&cache->rwlock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_rwlock_unlock(&cache->rwlock);

    return NULL;
}

int update_transaction(TransactionCache *cache, const char *transactionID, double value, const char *status, void *newMetadata) {
    if (!cache || !transactionID) return -1;

    // Lock the cache for write access
    pthread_rwlock_wrlock(&cache->rwlock);

    size_t index = hash_function(transactionID) % cache->capacity; // Assume hash_function is defined
    TransactionList *list = &cache->transactions[index];

    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current) {
        if (strcmp(current->transaction->transactionID, transactionID) == 0) {
            current->transaction->data.value = value;
            strncpy(current->transaction->data.status, status, sizeof(current->transaction->data.status) - 1);
            current->transaction->data.metadata = newMetadata;
            log_transaction(current->transaction);

            pthread_mutex_unlock(&list->lock);
            pthread_rwlock_unlock(&cache->rwlock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_rwlock_unlock(&cache->rwlock);

    return -1;
}

