#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread-safe operations
    time_t last_access[1000];  // Example limit, should be dynamically managed for real-world use.
} DynamicArray;

DynamicArray *init_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = calloc(initial_capacity, sizeof(record *));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    pthread_mutex_init(&array->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) return cleanup_dynamic_array(array);

        rec->value = time(NULL); // Using a timestamp as unique identifier
        rec->offset = malloc(sizeof(long));
        rec->key = malloc(sizeof(int));

        if (!rec->offset || !rec->key) {
            free(rec);
            return cleanup_dynamic_array(array);
        }

        *rec->offset = 1;  // Initializing non-zero value
        *rec->key = 2;     // Initializing non-zero value

        array->records[i] = rec;
        ++array->count;
    }

    return array;
}

DynamicArray *cleanup_dynamic_array(DynamicArray *array) {
    if (!array) return NULL;

    for (size_t i = 0; i < array->capacity; ++i) {
        free(array->records[i]->offset);
        free(array->records[i]->key);
        free(array->records[i]);
    }

    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);

    return NULL;
}

record *get_record(const DynamicArray *array, size_t index) {
    if (index >= array->count || !array) return NULL;

    pthread_mutex_lock(&(array->lock));
    time_t now = time(NULL);
    array->last_access[index] = now;
    record *rec = array->records[index];
    pthread_mutex_unlock(&(array->lock));

    return rec;
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    if (new_capacity < array->count) return;

    record **new_records = realloc(array->records, new_capacity * sizeof(record *));
    if (!new_records) return;  // Handle allocation failure gracefully

    for (size_t i = array->count; i < new_capacity; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) {  // If allocation fails midway
            free(new_records);
            return;
        }

        rec->value = time(NULL); 
        rec->offset = malloc(sizeof(long));
        rec->key = malloc(sizeof(int));

        if (!rec->offset || !rec->key) {
            free(rec);
            for (size_t j = i; j < new_capacity; ++j) free(new_records[j]);
            free(new_records);
            return;
        }

        *rec->offset = 1;
        *rec->key = 2;

        new_records[i] = rec;
    }

    array->records = new_records;
    array->capacity = new_capacity;
}

void add_record(DynamicArray *array, record *new_rec) {
    if (!array || !new_rec) return;

    pthread_mutex_lock(&(array->lock));
    if (array->count == array->capacity) resize_dynamic_array(array, array->capacity * 2);

    array->records[array->count++] = new_rec;
    pthread_mutex_unlock(&(array->lock));
}

void delete_record(DynamicArray *array, size_t index) {
    if (!array || index >= array->count) return;

    pthread_mutex_lock(&array->lock);

    free(array->records[index]->offset);
    free(array->records[index]->key);
    free(array->records[index]);

    memmove(&array->records[index], &array->records[index + 1],
            (array->count - index - 1) * sizeof(record *));
    --array->count;

    pthread_mutex_unlock(&(array->lock));
}

