void freeMemoryPool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->used; ++i) {
        pthread_mutex_destroy(&pool->records[i]->lock);
        free(pool->records[i]);
    }
    free(pool->records);
    free(pool->memory_pool);
}

void *allocateRecord(MemoryPool *pool, int key, long offset) {
    pthread_mutex_lock(&pool->pool_lock);
    if (pool->used >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        void *new_memory_pool = realloc(pool->memory_pool, new_capacity * sizeof(Record));
        Record **new_records = realloc(pool->records, new_capacity * sizeof(Record *));

        if (!new_memory_pool || !new_records) {
            fprintf(stderr, "Failed to resize memory pool\n");
            pthread_mutex_unlock(&pool->pool_lock);
            return NULL;
        }

        memset(new_memory_pool + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(Record));
        memset(new_records + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(Record *));

        pool->memory_pool = new_memory_pool;
        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    Record *record = (Record *)(pool->memory_pool + pool->used);
    record->value = rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;
    record->offset_ptr = &offset;
    record->key_ptr = &key;
    pthread_mutex_init(&record->lock, NULL);
    record->metadata = 0; // Initialize metadata

    pool->records[pool->used] = record;
    ++pool->used;

    pthread_mutex_unlock(&pool->pool_lock);
    return record;
}

void retryPolicy(int (*operation)(void *), void *arg) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (operation(arg)) {
            break; // Success
        }
        ++retries;
        sleep(1); // Backoff before retrying
    }
}

int integrateWithService(void *data) {
    // Placeholder for integrating with a third-party service
    // Simulate network operation and potential failure
    return rand() % 2 == 0; // Random success/failure
}

void initializeAndManageRecords(size_t num_records) {
    MemoryPool pool;
    initializeMemoryPool(&pool, INITIAL_POOL_SIZE);

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        int key = rand() % 1000;
        long offset = rand() % 1000000;

        Record *record = allocateRecord(&pool, key, offset);
        if (!record) {
            fprintf(stderr, "Failed to allocate record\n");
            continue; // Handle allocation failure
        }

        retryPolicy(integrateWithService, record); // Integrate with third-party service
    }

    freeMemoryPool(&pool);
}

int main() {
    initializeAndManageRecords(1000);
    return 0;
}
```

### Key Points:
- **Dynamic Memory Allocation**: The function uses a memory pool to manage records efficiently.
- **Concurrency**: Mutexes are used for thread safety during record allocation and access.
- **Error Handling**: Graceful handling of memory allocation failures with retries.
- **Third-party Integration**: Simulated integration with a service using a retry policy.
- **Performance Considerations**: Dynamic resizing of the memory pool to handle varying loads.

This code provides a foundation for building a high-performance, scalable data management system in C. Adjustments may be needed based on specific application requirements and environment constraints.']

