['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int value;
    struct node *parent;
    struct node **children;
    size_t children_count;
} Node;

typedef struct graph {
    Node **nodes;
    size_t node_count;
    pthread_mutex_t lock;
} Graph;

Graph* create_graph() {
    Graph *graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;
    graph->nodes = NULL;
    graph->node_count = 0;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

Node* new_node(int value) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->parent = NULL;
    node->children = NULL;
    node->children_count = 0;
    return node;
}

void insert_node(Graph *graph, int value, Node *parent) {
    pthread_mutex_lock(&graph->lock);

    Node *new_node = new_node(value);
    if (!new_node) {
        pthread_mutex_unlock(&graph->lock);
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return;
    }

    if (parent) {
        parent->children = realloc(parent->children, sizeof(Node*) * (parent->children_count + 1));
        if (!parent->children) {
            free(new_node);
            pthread_mutex_unlock(&graph->lock);
            fprintf(stderr, "Memory allocation failed for children pointers.\n");
            return;
        }
        parent->children[parent->children_count++] = new_node;
        new_node->parent = parent;
    }

    graph->nodes = realloc(graph->nodes, sizeof(Node*) * (graph->node_count + 1));
    if (!graph->nodes) {
        free(new_node);
        pthread_mutex_unlock(&graph->lock);
        fprintf(stderr, "Memory allocation failed for graph nodes.\n");
        return;
    }
    graph->nodes[graph->node_count++] = new_node;

    pthread_mutex_unlock(&graph->lock);
}

void remove_node(Graph *graph, Node *node) {
    if (!node || !graph) return;

    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i] == node) {
            free(node);
            for (size_t j = i; j < graph->node_count - 1; ++j) {
                graph->nodes[j] = graph->nodes[j + 1];
            }
            graph->nodes = realloc(graph->nodes, sizeof(Node*) * (graph->node_count - 1));
            if (!graph->nodes && graph->node_count > 0) {
                fprintf(stderr, "Memory reallocation failed during node removal.\n");
            }
            --graph->node_count;
            pthread_mutex_unlock(&graph->lock);
            return;
        }
    }

    for (size_t i = 0; i < node->children_count; ++i) {
        remove_node(graph, node->children[i]);
    }

    pthread_mutex_unlock(&graph->lock);
}

void dfs(Node *node, void (*visit)(Node*)) {
    if (!node || !visit) return;
    visit(node);
    for (size_t i = 0; i < node->children_count; ++i) {
        dfs(node->children[i], visit);
    }
}

void bfs(Node *root, void (*visit)(Node*)) {
    if (!root || !visit) return;

    Node **queue = malloc(sizeof(Node*));
    size_t front = 0, rear = 0;
    queue[rear++] = root;

    while (front < rear) {
        Node *current = queue[front++];
        visit(current);
        for (size_t i = 0; i < current->children_count; ++i) {
            queue = realloc(queue, sizeof(Node*) * (rear + 1));
            if (!queue) {
                fprintf(stderr, "Memory allocation failed during BFS.\n");
                return;
            }
            queue[rear++] = current->children[i];
        }
    }

    free(queue);
}

void serialize_graph(Graph *graph, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization.\n");
        return;
    }

    fwrite(&graph->node_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < graph->node_count; ++i) {
        Node *node = graph->nodes[i];
        fwrite(&node->value, sizeof(int), 1, file);
        fwrite(&node->children_count, sizeof(size_t), 1, file);
        fwrite(node->children, sizeof(Node*), node->children_count, file);
    }

    fclose(file);
}

Graph* deserialize_graph(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization.\n");
        return NULL;
    }

    Graph *graph = create_graph();
    if (!graph) {
        fclose(file);
        return NULL;
    }

    fread(&graph->node_count, sizeof(size_t), 1, file);
    graph->nodes = malloc(sizeof(Node*) * graph->node_count);

    for (size_t i = 0; i < graph->node_count; ++i) {
        Node *node = new_node(0); // Temporary value
        fread(&node->value, sizeof(int), 1, file);
        fread(&node->children_count, sizeof(size_t), 1, file);
        node->children = malloc(sizeof(Node*) * node->children_count);

        for (size_t j = 0; j < node->children_count; ++j) {
            int child_value;
            fread(&child_value, sizeof(int), 1, file);
            Node *child_node = new_node(child_value);
            if (!child_node) {
                fclose(file);
                return NULL;
            }
            node->children[j] = child_node;
        }

        graph->nodes[i] = node;
    }

    fclose(file);
    return graph;
}

void report_resource_usage(Graph *graph) {
    pthread_mutex_lock(&graph->lock);

    printf("Graph currently contains %zu nodes.\n", graph->node_count);

    // Example of memory usage reporting
    size_t total_memory = sizeof(Node*) * graph->node_count;
    for (size_t i = 0; i < graph->node_count; ++i) {
        Node *node = graph->nodes[i];
        total_memory += sizeof(int) + sizeof(Node**) + sizeof(size_t);
        if (node->children) {
            total_memory += sizeof(Node*) * node->children_count;
        }
    }

    printf("Total memory used by the graph: %zu bytes\n", total_memory);

    pthread_mutex_unlock(&graph->lock);
}

void free_graph(Graph *graph) {
    for (size_t i = 0; i < graph->node_count; ++i) {
        Node *node = graph->nodes[i];
        for (size_t j = 0; j < node->children_count; ++j) {
            remove_node(graph, node->children[j]);
        }
        free(node);
    }
    free(graph->nodes);
    pthread_mutex_destroy(&graph->lock);
    free(graph);
}
