// Define the TransactionManager struct
struct TransactionManager<T>
where
    T: Connection + 'static,
{
    transactions: Arc<Mutex<HashMap<Uuid, Transaction>>>,
    payment_clients: HashMap<String, PaymentClient>, // Keyed by merchant account for simplicity
    db_pool: r2d2::Pool<r2d2_diesel::ConnectionManager<T>>,
}

impl<T> TransactionManager<T>
where
    T: Connection + 'static,
{
    fn new(database_url: &str) -> Self {
        let manager = r2d2_diesel::ConnectionManager::<T>::new(database_url);
        let pool = r2d2::Pool::builder()
            .max_size(15)
            .build(manager)
            .expect("Failed to create DB connection pool");

        TransactionManager {
            transactions: Arc::new(Mutex::new(HashMap::new())),
            payment_clients: HashMap::new(),
            db_pool: pool,
        }
    }

    fn add_transaction(&self, transaction: Transaction) -> Result<(), &'static str> {
        let mut trans_map = self.transactions.lock().unwrap();
        trans_map.insert(transaction.id, transaction);
        info!("Transaction {} added.", transaction.id);
        Ok(())
    }

    async fn update_transaction_status(&self, tx_id: Uuid, new_status: String) -> Result<(), &'static str> {
        let mut trans_map = self.transactions.lock().unwrap();
        if let Some(tx) = trans_map.get_mut(&tx_id) {
            tx.status = new_status.clone();
            tx.updated_at = Some(Utc::now().naive_utc());
            info!("Transaction {} updated to status: {}", tx_id, new_status);
            Ok(())
        } else {
            error!("Transaction ID {} not found.", tx_id);
            Err("Transaction not found")
        }
    }

    async fn retry_failed_transactions(&self) {
        let trans_map = self.transactions.lock().unwrap();
        for (tx_id, transaction) in trans_map.iter() {
            if transaction.status == "Failed" || transaction.status == "Pending" {
                match self.retry_transaction(tx_id.clone(), transaction).await {
                    Ok(_) => info!("Transaction {} retried successfully.", tx_id),
                    Err(e) => warn!("Retry failed for Transaction {}: {}", tx_id, e),
                }
            }
        }
    }

    async fn retry_transaction(&self, tx_id: Uuid, transaction: &Transaction) -> Result<(), &'static str> {
        let payment_client = self.get_payment_client(&transaction.merchant_account)?;
        match payment_client.initiate_transaction(transaction).await {
            Ok(_) => Ok(()),
            Err(e) => {
                error!("Failed to retry Transaction {}: {}", tx_id, e);
                sleep(Duration::from_secs(5)).await; // Simple backoff strategy
                self.retry_transaction(tx_id, transaction).await
            }
        }
    }

    fn get_payment_client(&self, merchant_account: &str) -> Result<&PaymentClient, &'static str> {
        self.payment_clients.get(merchant_account)
            .ok_or("Payment client not found for merchant account")
    }

    fn get_transactions_by_merchant(&self, merchant_id: &str) -> Vec<Transaction> {
        let trans_map = self.transactions.lock().unwrap();
        trans_map.values()
            .filter(|tx| tx.merchant_account == merchant_id)
            .cloned()
            .collect()
    }
}

// Main function to demonstrate usage
