        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    printf("Enter integers (end with non-integer input):\n");

    size_t count = 0;
    while (scanf("%d", &(*array)[count]) == 1 && count < capacity - 1) {
