#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_EVENTS 10000
#define MIN_METADATA_SIZE 1024 // 1KB
#define MAX_METADATA_SIZE (1024 * 1024) // 1MB

typedef struct {
    time_t timestamp;
    char* event_type;
    void* metadata;
} Event;

// Predefined list of event types
const char* EVENT_TYPES[] = {"TypeA", "TypeB", "TypeC", "TypeD"};
#define NUM_EVENT_TYPES (sizeof(EVENT_TYPES) / sizeof(EVENT_TYPES[0]))

typedef struct {
    Event** events;
    size_t count;
    pthread_mutex_t lock;
} EventManager;

EventManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to allocate memory for an event with random metadata size
Event* create_event(time_t timestamp) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) return NULL;

    // Randomly select an event type
    const char* type = EVENT_TYPES[rand() % NUM_EVENT_TYPES];
    event->event_type = strdup(type);
    if (!event->event_type) {
        free(event);
        return NULL;
    }

    // Allocate random metadata size between 1KB and 1MB
    size_t metadata_size = MIN_METADATA_SIZE + rand() % (MAX_METADATA_SIZE - MIN_METADATA_SIZE);
    event->metadata = malloc(metadata_size);
    if (!event->metadata) {
        free(event->event_type);
        free(event);
        return NULL;
    }

    // Initialize metadata with random data
    memset(event->metadata, rand(), metadata_size);

    event->timestamp = timestamp;

    return event;
}

// Add an event to the manager
void add_event(time_t timestamp) {
    pthread_mutex_lock(&manager.lock);

    if (manager.count >= MAX_EVENTS) {
        fprintf(stderr, "Maximum number of events reached.\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    Event* event = create_event(timestamp);
    if (!event) {
        fprintf(stderr, "Failed to allocate memory for event.\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    manager.events = realloc(manager.events, sizeof(Event*) * (manager.count + 1));
    if (!manager.events) {
        fprintf(stderr, "Failed to reallocate memory for events array.\n");
        free(event->metadata);
        free(event->event_type);
        free(event);
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    manager.events[manager.count++] = event;

    pthread_mutex_unlock(&manager.lock);
}

// Retrieve an event by index
Event* get_event(size_t index) {
    if (index >= manager.count) return NULL;
    return manager.events[index];
}

// Print all events in a human-readable format
void print_events() {
    pthread_mutex_lock(&manager.lock);

    for (size_t i = 0; i < manager.count; ++i) {
        Event* event = manager.events[i];
        printf("Event %zu: Type=%s, Timestamp=%ld\n", i, event->event_type, event->timestamp);
    }

    pthread_mutex_unlock(&manager.lock);
}

// Function to simulate high-load scenario
void* process_events_thread(void* arg) {
    for (int i = 0; i < 100; ++i) { // Simulate processing 100 events per thread
        time_t timestamp = time(NULL); // Simulating a read from an external source
        add_event(timestamp);
    }
    return NULL;
}

// Function to initialize and manage events
void processAndManageEvents() {
    srand(time(NULL));

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) { // Create 10 threads to simulate high load
        pthread_create(&threads[i], NULL, process_events_thread, NULL);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_events();

    // Cleanup
    pthread_mutex_lock(&manager.lock);

    for (size_t i = 0; i < manager.count; ++i) {
        Event* event = manager.events[i];
        free(event->metadata);
        free(event->event_type);
        free(event);
    }
    free(manager.events);

    pthread_mutex_unlock(&manager.lock);
}

int main() {
    processAndManageEvents();
    return 0;
}
