                                 time_t due_date, const char *status, const char *owner) {
    Logger logger = {stdout, NULL};  // Example of a local logging setup
    pthread_mutex_lock(&task_mutex);

    for (size_t i = 0; i < task_count; ++i) {
        if (tasks[i]->due_date <= time(NULL)) continue;  // Skip past due tasks

        char *valid_statuses = get_predefined_statuses("default");
        if (!valid_statuses || strcmp(tasks[i]->status, valid_statuses[0]) != 0) continue;

        if (!authenticate_user(tasks[i]->owner)) {
            log_task_change(logger, "Invalid user ID for task.");
            pthread_mutex_unlock(&task_mutex);
            return;
        }

        tasks[i]->priority = priority;
        tasks[i]->due_date = due_date > time(NULL) ? due_date : 0; // Set future date only
        strcpy(tasks[i]->status, status);
        strcpy(tasks[i]->owner, owner);

        log_task_change(logger, "Task updated successfully.");
    }

    pthread_mutex_unlock(&task_mutex);

