// Define severity levels.
typedef enum {
    INFO,
    WARNING,
    ERROR
} Severity;

// Define a timestamp type (for simplicity).
typedef long timestamp_t;

// Structure to represent a log entry.
typedef struct {
    char* message;
    Severity severity;
    timestamp_t timestamp;
} logEntry;

// Global structure to manage logs and synchronization.
typedef struct {
    logEntry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

// Function prototypes
void manageAndProcessLogs(size_t initial_capacity);
static void initializeLogManager(LogManager* manager, size_t capacity);
static void resizeLogManager(LogManager* manager, size_t new_capacity);
static void destroyLogManager(LogManager* manager);
static int compareSeverity(const logEntry* a, const logEntry* b);
void sortAndPrintLogs(LogManager* manager);

// Function to manage and process logs
void manageAndProcessLogs(size_t initial_capacity) {
    LogManager manager;

    // Initialize the log manager with an optimal size based on expected load.
    initializeLogManager(&manager, initial_capacity);

    // Example: simulate adding a few logs. In practice, these would come from various sources.
    pthread_mutex_lock(&manager.lock);
    for (size_t i = 0; i < manager.capacity && i < 5; ++i) { // Simulating some entries
        manager.entries[i] = malloc(sizeof(logEntry));
        if (!manager.entries[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            destroyLogManager(&manager);
            return;
        }
        manager.entries[i]->message = strdup("Sample log message");
        manager.entries[i]->severity = i % 3; // Vary severity
        manager.entries[i]->timestamp = i + 1000; // Sample timestamp
    }
    manager.count = initial_capacity < 5 ? initial_capacity : 5;
    pthread_mutex_unlock(&manager.lock);

    // Sort and print logs.
    sortAndPrintLogs(&manager);

    // Cleanup resources.
    destroyLogManager(&manager);
}

// Initialize the log manager with a fixed-size array.
static void initializeLogManager(LogManager* manager, size_t capacity) {
    manager->entries = malloc(capacity * sizeof(logEntry*));
    if (!manager->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < capacity; ++i) {
        manager->entries[i] = NULL;
    }
    manager->capacity = capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the log manager when capacity is exceeded.
static void resizeLogManager(LogManager* manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    // Allocate a larger array and copy existing entries.
    logEntry** new_entries = realloc(manager->entries, new_capacity * sizeof(logEntry*));
    if (!new_entries) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = manager->capacity; i < new_capacity; ++i) {
        new_entries[i] = NULL;
    }

    // Update the log manager.
    manager->entries = new_entries;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->lock);
}

// Destroy the log manager and free allocated resources.
static void destroyLogManager(LogManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]) {
            free(manager->entries[i]->message);
            free(manager->entries[i]);
        }
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}

// Compare function for sorting logs by severity.
static int compareSeverity(const logEntry* a, const logEntry* b) {
    return (a->severity < b->severity) - (a->severity > b->severity);
}

// Sort and print all log entries in descending order of severity level.
void sortAndPrintLogs(LogManager* manager) {
    pthread_mutex_lock(&manager->lock);

    // Use a stable sorting algorithm like mergesort for its efficiency with complex data structures.
    if (manager->count > 1) {
        qsort(manager->entries, manager->count, sizeof(logEntry*), compareSeverity);
    }

    for (size_t i = 0; i < manager->count; ++i) {
        printf("Time: %ld, Severity: %d, Message: %s\n", 
               manager.entries[i]->timestamp, 
               manager.entries[i]->severity,
               manager.entries[i]->message);
    }

    pthread_mutex_unlock(&manager->lock);
}
