    if (file == NULL) return; // Handle file open error gracefully
    fwrite(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; ++i) {
        fwrite(&records[i], sizeof(record), 1, file);
    }
    fclose(file);
}

void loadRecordsFromFile(record **records, size_t *count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return; // Handle file open error gracefully
    fread(count, sizeof(size_t), 1, file);
    *records = malloc(*count * sizeof(record));
    for (size_t i = 0; i < *count; ++i) {
        fread(&(*records)[i], sizeof(record), 1, file);
    }
    fclose(file);
}

