        records[index].value = newValue;
    }
}

record* removeRecord(record **records, size_t *count, size_t index) {
    if (index >= *count) return NULL; // Invalid index
    record *newRecords = realloc(*records, (*count - 1) * sizeof(record));
    if (newRecords == NULL) return NULL; // Handle reallocation failure

    for (size_t i = index; i < *count - 1; ++i) {
        newRecords[i] = (*records)[i + 1];
    }

    free((*records)[*count - 1].offset);
    free((*records)[*count - 1].key);
    *count -= 1;
    *records = newRecords;

    return *records;
}

