// Memory pool for dynamic allocations.
typedef struct {
    void* memory;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
} MemoryPool;

MemoryPool createMemoryPool(size_t block_size, size_t total_blocks) {
    MemoryPool mp;
    mp.block_size = block_size;
    mp.total_blocks = total_blocks;
    mp.used_blocks = 0;
    mp.memory = aligned_alloc(64, block_size * total_blocks);
    return mp;
}

void* allocateFromMemoryPool(MemoryPool* mp) {
    if (mp->used_blocks >= mp->total_blocks)
        return NULL; // Pool exhausted.

    void* ptr = ((char*)mp->memory + mp->used_blocks * mp->block_size);
    mp->used_blocks++;
    return ptr;
}

void freeMemoryPool(MemoryPool* mp) {
    if (mp->memory) {
        free(mp->memory);
        mp->memory = NULL;
    }
}

void generateRandomString(char* buffer, size_t length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length; // Leave space for the null terminator.
        for(size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            buffer[n] = charset[key];
        }
        buffer[length] = '\0';
    } else {
        buffer[0] = '\0';
    }
}

void processAndStoreLogData(size_t num_entries, const char* log_file_path) {
    if (num_entries <= 0)
        return;

    // Initialize the memory pool for log entries.
    MemoryPool logEntryPool = createMemoryPool(sizeof(logEntry), num_entries);

    logEntry* logEntries = (logEntry*)allocateFromMemoryPool(&logEntryPool);
    if (!logEntries) {
        fprintf(stderr, "Failed to allocate memory for log entries.\n");
        freeMemoryPool(&logEntryPool);
        return;
    }

    // Initialize random number generator.
    srand(time(NULL));

    for (size_t i = 0; i < num_entries; ++i) {
        logEntries[i].timestamp = rand() % (uint64_t)(time(NULL) * 1000000);
        logEntries[i].severity = rand() % 3;
        size_t message_length = rand() % 256 + 1;

        char* messageBuffer = (char*)allocateFromMemoryPool(&logEntryPool);
        if (!messageBuffer) {
            fprintf(stderr, "Failed to allocate memory for a log entry message.\n");
            break; // Exit on allocation failure.
        }

        generateRandomString(messageBuffer, message_length);
        logEntries[i].message = messageBuffer;
    }

    FILE* file = fopen(log_file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open the log file.\n");
        freeMemoryPool(&logEntryPool);
        return;
    }

    char line[1024];
    size_t index = 0;

    while (fgets(line, sizeof(line), file)) {
        if (index >= num_entries)
            break; // Stop processing when array is full.

        uint64_t timestamp;
