            name: c_name.into_raw(),
        }
    }

    fn drop(self) { 
        // Reclaim CString
        unsafe { 
            if self.name != 0 as *const u8 { 
                std::ffi::CString::from_raw(self.name as *mut u8); 
            } 
        } 
    }
}

#[derive(Debug)]
