        if let Some(config_ptr) = configs_lock.get(name) {
            // Clone the pointer data to return a safe copy
            let config = unsafe { std::mem::transmute_copy(&config_ptr) };
            Some(config)
        } else {
            None
        }
    }

    fn add_transaction_log(&self, log: TransactionLog) {
        let mut logs_lock = self.transaction_logs.lock().unwrap();
