    printf("[%s] %s\n", ctime(&now), message);
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char *) userp)[0] += size * nmemb;
    return size * nmemb;
}

void* handle_http_request(void *arg) {
    HttpRequestData *data = (HttpRequestData*) arg;
    CURL *curl;
    CURLcode res;
    char readBuffer[4096];
    long response_code;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_URL, "http://external-server/update"); // Example URL
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"section_id\":\"%s\",\"element_id\":\"%s\",\"html_content\":\"%s\"}",
                         data->section_id, data->element_id, data->html_content);

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, readBuffer);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            log_message(response_code == 200 ? "HTTP Request Successful" : "HTTP Request Failed");
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return NULL;
}

void initialize_entry_table(EntryTable *table, size_t initial_capacity) {
    table->entries = (Entry *) malloc(initial_capacity * sizeof(Entry));
    if (!table->entries) {
        perror("Failed to allocate memory for entries");
        exit(EXIT_FAILURE);
    }

    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    srand(time(NULL)); // Seed the random number generator
}

void free_entry_table(EntryTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        free(table->entries[i].name);
    }

    free(table->entries);
    pthread_mutex_destroy(&table->lock);
}

int add_entry(EntryTable *table, double range_min, double range_max) {
    pthread_mutex_lock(&table->lock);

    if (table->size >= table->capacity) {
        size_t new_capacity = table->capacity * 2;
        Entry *new_entries = realloc(table->entries, new_capacity * sizeof(Entry));

        if (!new_entries) {
            perror("Failed to reallocate memory for entries");
            pthread_mutex_unlock(&table->lock);
            return -1;
        }

        table->entries = new_entries;
        table->capacity = new_capacity;
    }

    Entry entry;
    entry.id = (int)(table->size + 1);
    entry.value = range_min + ((double) rand() / RAND_MAX) * (range_max - range_min);
    entry.name = strdup("Default Name"); // Replace with actual string data if needed
    entry.offset = 0; // Set appropriately
    entry.key = 0; // Set appropriately

    table->entries[table->size++] = entry;

    pthread_mutex_unlock(&table->lock);

    return 0;
}

void async_http_request(EntryTable *table, const char* section_id, const char* element_id, const char* html_content) {
    HttpRequestData *data = malloc(sizeof(HttpRequestData));
    data->section_id = section_id;
    data->element_id = element_id;
    data->html_content = html_content;

    pthread_t thread;
    if (pthread_create(&thread, NULL, handle_http_request, data)) {
        fprintf(stderr, "Error creating HTTP request thread\n");
    }

    // Detach thread to allow for independent execution
    pthread_detach(thread);
}

void process_entries(UpdateArgs *args) {
    EntryTable table;
    initialize_entry_table(&table, INITIAL_CAPACITY);

    log_message("Initializing entries...");
    for (int i = 0; i < args->num_entries; ++i) {
        if (add_entry(&table, args->range_min, args->range_max)) {
            fprintf(stderr, "Failed to add entry %d\n", i + 1);
        }

        // Example async HTTP request
        char section_id[20], element_id[20];
        snprintf(section_id, sizeof(section_id), "section_%d", table.entries[i].id);
        snprintf(element_id, sizeof(element_id), "element_%d", table.entries[i].id);

        async_http_request(&table, section_id, element_id, "<p>Updated content</p>");
    }

    free_entry_table(&table);
}

int main() {
    UpdateArgs args = { .num_entries = 20, .range_min = 0.0, .range_max = 100.0 };
    process_entries(&args);

    // Keep the program running to allow for HTTP requests to complete
    sleep(10);

    log_message("Program completed.");
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses `pthread_mutex_t` for managing concurrent access to shared resources.
- **Dynamic Memory Management**: Uses dynamic memory allocation and resizing, reallocating the entries array when needed.
- **Asynchronous HTTP Requests**: Utilizes `libcurl` with threading support for handling asynchronous updates to an external server.
- **Logging and Monitoring**: Simple logging function outputs timestamps and messages to track system behavior.
- **Robustness**: Includes error checks for memory allocation failures and handles HTTP request errors.

This code provides a foundational setup that can be expanded upon to meet additional requirements or optimizations based on specific use cases.']

