// Custom memory pool structure
typedef struct {
    size_t block_size;
    void** free_blocks;
    size_t num_free_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->free_blocks = (void**)malloc(initial_capacity * sizeof(void*));
    if (!pool->free_blocks) {
        free(pool);
        return NULL;
    }
    pool->num_free_blocks = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->free_blocks[i] = malloc(block_size);
        if (!pool->free_blocks[i]) {
            while (--i >= 0) free(pool->free_blocks[i]);
            free(pool->free_blocks);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->num_free_blocks == 0) {
        size_t new_capacity = pool->num_free_blocks * 2;
        void** new_blocks = (void**)realloc(pool->free_blocks, new_capacity * sizeof(void*));
        if (!new_blocks) return NULL;

        for (size_t i = pool->num_free_blocks; i < new_capacity; ++i) {
            new_blocks[i] = malloc(pool->block_size);
            if (!new_blocks[i]) {
                while (--i >= pool->num_free_blocks) free(new_blocks[i]);
                return NULL;
            }
        }

        pool->free_blocks = new_blocks;
        pool->num_free_blocks = new_capacity;
    }

    void* block = pool->free_blocks[--pool->num_free_blocks];
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    pool->free_blocks[pool->num_free_blocks++] = block;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->num_free_blocks; ++i) {
        free(pool->free_blocks[i]);
    }
    free(pool->free_blocks);
    free(pool);
}

