    if (!records) {
        destroy_memory_pool(pool);
        return NULL;
    }

    *records = (Record*)malloc(initial_count * sizeof(Record));
    if (!*records) {
        memory_pool_free(pool, records);
        destroy_memory_pool(pool);
        return NULL;
    }

    size_t capacity = initial_count;

    for (size_t i = 0; i < initial_count; ++i) {
        (*records)[i].value = min_val + ((max_val - min_val) * rand() / RAND_MAX);
        (*records)[i].key = (int*)malloc(sizeof(int));
        if (!(*records)[i].key) {
            for (size_t j = 0; j < i; ++j) free((*records)[i].key);
            free(*records);
            memory_pool_free(pool, records);
            destroy_memory_pool(pool);
            return NULL;
        }
    }

    // Resize function
    void resize_records(Record*** records_ref, size_t* capacity_ref, size_t new_capacity) {
        Record** old_records = *records_ref;
        *records_ref = (Record**)memory_pool_alloc(pool);
        if (!(*records_ref)) {
            free(old_records);
            return;
        }

        **records_ref = (Record*)realloc((*old_records)[0], new_capacity * sizeof(Record));
        if (!**records_ref) {
            free(*records_ref);
            *records_ref = old_records;
            return;
        }

        for (size_t i = capacity; i < new_capacity; ++i) {
            (*records_ref)[i].value = 0.0;
            (*records_ref)[i].key = (int*)malloc(sizeof(int));
            if (!(*records_ref)[i].key) {
