#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    double value;
    long* offset;
    int* key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
} DynamicArray;

// Helper function to log messages
void log_message(const char* message, int level) {
    static const char* levels[] = {"INFO", "DEBUG"};
    if (level >= LOG_LEVEL_DEBUG) {
        printf("[%s] %s\n", levels[level], message);
    }
}

// Function to initialize the dynamic array
DynamicArray initialize_dynamic_array(size_t initial_capacity) {
    DynamicArray da;
    da.capacity = initial_capacity;
    da.count = 0;
    da.records = (Record*)malloc(sizeof(Record) * da.capacity);

    if (!da.records) {
        log_message("Memory allocation failed for records", LOG_LEVEL_DEBUG);
        exit(EXIT_FAILURE);
    }

    log_message("Dynamic array initialized successfully", LOG_LEVEL_INFO);
    return da;
}

// Function to resize the dynamic array
void resize_dynamic_array(DynamicArray* da, size_t new_capacity) {
    Record *new_records = (Record*)realloc(da->records, sizeof(Record) * new_capacity);

    if (!new_records) {
        log_message("Memory reallocation failed for records", LOG_LEVEL_DEBUG);
        exit(EXIT_FAILURE);
    }

    da->records = new_records;
    da->capacity = new_capacity;
}

// Function to add a record
void add_record(DynamicArray* da, double value, long offset, int key) {
    if (da->count == da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
        log_message("Dynamic array resized", LOG_LEVEL_DEBUG);
    }

    Record new_record;
    new_record.value = value;
    new_record.offset = &offset;
    new_record.key = &key;

    da->records[da->count++] = new_record;
}

// Function to generate a random double within a range
double random_double(double min, double max) {
    return (min + ((max - min) * rand()));
}

// Function to initialize records with random values
void initialize_records(DynamicArray* da, double min_value, double max_value) {
    for (size_t i = 0; i < da->count; ++i) {
        long offset = rand() % 1000;
        int key = rand() % 100;

        double value = random_double(min_value, max_value);
        add_record(da, value, offset, key);

        log_message("Record added", LOG_LEVEL_DEBUG);
    }
}

// Function to serialize records to a file
void serialize_records(DynamicArray* da, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization", LOG_LEVEL_DEBUG);
        return;
    }

    fwrite(&da->count, sizeof(size_t), 1, file);
    fwrite(da->records, sizeof(Record), da->count, file);

    fclose(file);
    log_message("Records serialized successfully", LOG_LEVEL_INFO);
}

// Function to deserialize records from a file
void deserialize_records(DynamicArray* da, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization", LOG_LEVEL_DEBUG);
        return;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    resize_dynamic_array(da, count);

    fread(da->records, sizeof(Record), da->count, file);

    fclose(file);
    log_message("Records deserialized successfully", LOG_LEVEL_INFO);
}

// Helper function to find the largest integer
int find_largest_integer(int *array, size_t size) {
    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to manage records
void initializeAndManageRecords(double min_value, double max_value) {
    srand(time(NULL));

    DynamicArray da = initialize_dynamic_array(INITIAL_CAPACITY);
    initialize_records(&da, min_value, max_value);

    serialize_records(&da, "records.bin");
    deserialize_records(&da, "records.bin");

    // Simulate reading integers from input
    int nums[] = {3, 5, 7, 2, 9};
    size_t num_count = sizeof(nums) / sizeof(nums[0]);

    if (num_count == 0) {
        log_message("No integers to process", LOG_LEVEL_DEBUG);
    } else {
        int max_value = find_largest_integer(nums, num_count);
        printf("Largest integer: %d\n", max_value);
    }

    // Clean up
    free(da.records);
}

int main() {
    initializeAndManageRecords(0.0, 100.0);
    return 0;
}
