#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Metadata structure definition
typedef struct {
    int *tags;
    size_t tag_count;
    int reference_count;
    int version_identifier;
} RecordMetadata;

// Record structure definition
typedef struct {
    long offset;
    int key;
    time_t timestamp;
    RecordMetadata *metadata;
} Record;

// Collection of records
typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
} RecordCollection;

// Function to initialize and manage the collection
void initializeAndManageRecords(RecordCollection *collection, size_t initial_count, int range_min, int range_max) {
    if (collection == NULL) return;

    // Initialize random number generator
    srand(time(NULL));

    collection->capacity = initial_count;
    collection->count = 0;
    collection->records = malloc(collection->capacity * sizeof(Record*));
    if (!collection->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Unique set to ensure unique keys
    int used_keys[range_max - range_min + 1] = {0};

    for (size_t i = 0; i < initial_count; ++i) {
        int key;
        do {
            key = rand() % (range_max - range_min + 1) + range_min;
        } while (used_keys[key]);

        used_keys[key] = 1;

        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        record->offset = rand() % 1000; // Example offset
        record->key = key;
        record->timestamp = time(NULL);

        RecordMetadata *metadata = malloc(sizeof(RecordMetadata));
        if (!metadata) {
            fprintf(stderr, "Memory allocation failed\n");
            free(record);
            exit(EXIT_FAILURE);
        }

        metadata->tags = NULL;
        metadata->tag_count = 0;
        metadata->reference_count = 1; // Initial reference count
        metadata->version_identifier = 1; // Initial version

        record->metadata = metadata;

        collection->records[collection->count++] = record;
    }
}

// Function to retrieve a specific record by its index
Record* getRecordByIndex(RecordCollection *collection, size_t index) {
    if (index >= collection->count) return NULL;
    return collection->records[index];
}

// Function to add a tag to the record's metadata
void addTagToRecord(Record *record, int tag) {
    if (!record || !record->metadata) return;

    record->metadata->tags = realloc(record->metadata->tags,
                                     (record->metadata->tag_count + 1) * sizeof(int));
    if (!record->metadata->tags) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    record->metadata->tags[record->metadata->tag_count++] = tag;
}

// Function to remove a tag from the record's metadata
void removeTagFromRecord(Record *record, int tag) {
    if (!record || !record->metadata) return;

    for (size_t i = 0; i < record->metadata->tag_count; ++i) {
        if (record->metadata->tags[i] == tag) {
            memmove(&record->metadata->tags[i], &record->metadata->tags[i + 1],
                    (record->metadata->tag_count - i - 1) * sizeof(int));
            record->metadata->tag_count--;
            break;
        }
    }

    record->metadata->tags = realloc(record->metadata->tags, record->metadata->tag_count * sizeof(int));
}

// Function to adjust the reference count of a record
void adjustReferenceCount(Record *record, int adjustment) {
    if (!record || !record->metadata) return;
    record->metadata->reference_count += adjustment;
}

// Function to merge two collections
void mergeCollections(RecordCollection *dest, RecordCollection *src) {
    for (size_t i = 0; i < src->count; ++i) {
        dest->records[dest->count++] = src->records[i];
    }
}

// Helper function to read integers from input and find the largest
void findAndPrintLargestInteger() {
    int *array, size, max_val;

    printf("Enter number of elements: ");
    scanf("%d", &size);

    array = malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; ++i) {
        scanf("%d", &array[i]);
    }

    max_val = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_val) {
            max_val = array[i];
        }
    }

    printf("The largest integer is: %d\n", max_val);

    free(array);
}

// Free memory associated with the collection
void freeRecordCollection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->metadata->tags);
        free(collection->records[i]->metadata);
        free(collection->records[i]);
    }

    free(collection->records);
}

int main() {
    RecordCollection collection;
    initializeAndManageRecords(&collection, 10, 1, 100);

    // Example usage
    Record *record = getRecordByIndex(&collection, 0);
    if (record) {
        addTagToRecord(record, 101);
        adjustReferenceCount(record, 2);
    }

    findAndPrintLargestInteger();

    freeRecordCollection(&collection);
    return 0;
}
