#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    int* key;
    long* offset;
    char* buffer;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    size_t version_count;
    Record*** versions;
} Dataset;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

Dataset* initialize_dataset(size_t initial_capacity);
void free_dataset(Dataset* dataset);
int resize_array(Record*** array, size_t* capacity, size_t new_size);
void add_version(Dataset* dataset);
void switch_version(Dataset* dataset, size_t version_index);
int serialize_dataset(const Dataset* dataset, const char* filename);
int deserialize_dataset(Dataset** dataset, const char* filename);
void save_partial_update(const Dataset* dataset, const char* filename, size_t start, size_t end);
void handle_memory_failure(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

Dataset* initialize_dataset(size_t initial_capacity) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    handle_memory_failure(dataset);

    dataset->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    handle_memory_failure(dataset->records);

    dataset->capacity = initial_capacity;
    dataset->count = 0;
    dataset->version_count = 0;

    dataset->versions = NULL; // Initially no versions
    add_version(dataset);     // Create first version

    return dataset;
}

void free_dataset(Dataset* dataset) {
    for (size_t i = 0; i < dataset->count; ++i) {
        if (dataset->records[i]->key) free(dataset->records[i]->key);
        if (dataset->records[i]->offset) free(dataset->records[i]->offset);
        if (dataset->records[i]->buffer) free(dataset->records[i]->buffer);
        free(dataset->records[i]);
    }
    free(dataset->records);

    for (size_t i = 0; i < dataset->version_count; ++i) {
        free(dataset->versions[i]);
    }
    free(dataset->versions);

    free(dataset);
}

int resize_array(Record*** array, size_t* capacity, size_t new_size) {
    *array = (Record**)realloc(*array, new_size * sizeof(Record*));
    if (!*array) return -1;

    for (size_t i = *capacity; i < new_size; ++i) {
        (*array)[i] = NULL;
    }

    *capacity = new_size;
    return 0;
}

void add_record(Dataset* dataset, double value, int key, long offset, const char* buffer) {
    if (dataset->count == dataset->capacity) {
        size_t new_capacity = dataset->capacity * GROWTH_FACTOR;
        if (resize_array(&dataset->records, &dataset->capacity, new_capacity)) {
            fprintf(stderr, "Failed to resize records array\n");
            exit(EXIT_FAILURE);
        }
    }

    Record* record = (Record*)malloc(sizeof(Record));
    handle_memory_failure(record);

    record->value = value;
    record->key = (int*)malloc(sizeof(int));
    handle_memory_failure(record->key);
    *record->key = key;

    record->offset = (long*)malloc(sizeof(long));
    handle_memory_failure(record->offset);
    *record->offset = offset;

    size_t buffer_len = strlen(buffer) + 1;
    record->buffer = (char*)malloc(buffer_len);
    handle_memory_failure(record->buffer);
    strcpy(record->buffer, buffer);

    dataset->records[dataset->count++] = record;
}

void add_version(Dataset* dataset) {
    Record*** new_versions = (Record***)realloc(dataset->versions, sizeof(Record**) * (dataset->version_count + 1));
    handle_memory_failure(new_versions);

    new_versions[dataset->version_count] = (Record**)calloc(dataset->count, sizeof(Record*));
    handle_memory_failure(new_versions[dataset->version_count]);

    for (size_t i = 0; i < dataset->count; ++i) {
        Record* record_copy = (Record*)malloc(sizeof(Record));
        handle_memory_failure(record_copy);

        record_copy->value = dataset->records[i]->value;
        record_copy->key = (int*)malloc(sizeof(int));
        handle_memory_failure(record_copy->key);
        *record_copy->key = *(dataset->records[i]->key);

        record_copy->offset = (long*)malloc(sizeof(long));
        handle_memory_failure(record_copy->offset);
        *record_copy->offset = *(dataset->records[i]->offset);

        size_t buffer_len = strlen(dataset->records[i]->buffer) + 1;
        record_copy->buffer = (char*)malloc(buffer_len);
        handle_memory_failure(record_copy->buffer);
        strcpy(record_copy->buffer, dataset->records[i]->buffer);

        new_versions[dataset->version_count][i] = record_copy;
    }

    dataset->versions = new_versions;
    ++dataset->version_count;
}

void switch_version(Dataset* dataset, size_t version_index) {
    if (version_index >= dataset->version_count) {
        fprintf(stderr, "Invalid version index\n");
        return;
    }

    free(dataset->records);
    dataset->records = dataset->versions[version_index];
    dataset->count = 0;

    for (size_t i = 0; i < dataset->capacity; ++i) {
        if (dataset->records[i]) {
            ++dataset->count;
        }
    }
}

int serialize_dataset(const Dataset* dataset, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&dataset->capacity, sizeof(size_t), 1, file);
    fwrite(&dataset->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < dataset->count; ++i) {
        fwrite(&dataset->records[i]->value, sizeof(double), 1, file);
        fwrite(dataset->records[i]->key, sizeof(int), 1, file);
        fwrite(dataset->records[i]->offset, sizeof(long), 1, file);

        size_t buffer_len = strlen(dataset->records[i]->buffer) + 1;
        fwrite(&buffer_len, sizeof(size_t), 1, file);
        fwrite(dataset->records[i]->buffer, sizeof(char), buffer_len, file);
    }

    fclose(file);
    return 0;
}

int deserialize_dataset(Dataset** dataset, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t capacity, count;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&count, sizeof(size_t), 1, file);

    *dataset = initialize_dataset(capacity);

    for (size_t i = 0; i < count; ++i) {
        double value;
        int key;
        long offset;

        fread(&value, sizeof(double), 1, file);
        fread(&key, sizeof(int), 1, file);
        fread(&offset, sizeof(long), 1, file);

        size_t buffer_len;
        fread(&buffer_len, sizeof(size_t), 1, file);

        char* buffer = (char*)malloc(buffer_len);
        handle_memory_failure(buffer);

        fread(buffer, sizeof(char), buffer_len, file);

        add_record(*dataset, value, key, offset, buffer);
        free(buffer);
    }

    fclose(file);
    return 0;
}

void save_partial_update(const Dataset* dataset, const char* filename, size_t start, size_t end) {
    FILE* file = fopen(filename, "ab");
    if (!file) return;

    for (size_t i = start; i < end && i < dataset->count; ++i) {
        fwrite(&dataset->records[i]->value, sizeof(double), 1, file);
        fwrite(dataset->records[i]->key, sizeof(int), 1, file);
        fwrite(dataset->records[i]->offset, sizeof(long), 1, file);

        size_t buffer_len = strlen(dataset->records[i]->buffer) + 1;
        fwrite(&buffer_len, sizeof(size_t), 1, file);
        fwrite(dataset->records[i]->buffer, sizeof(char), buffer_len, file);
    }

    fclose(file);
}

int find_largest_integer(int* array, size_t length) {
    if (length == 0) return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void read_integers_and_find_largest() {
    size_t length;
    printf("Enter the number of integers: ");
    scanf("%zu", &length);

    int* array = (int*)malloc(length * sizeof(int));
    handle_memory_failure(array);

    printf("Enter %zu integers:\n", length);
    for (size_t i = 0; i < length; ++i) {
        scanf("%d", &array[i]);
    }

    int largest = find_largest_integer(array, length);
    printf("The largest integer is: %d\n", largest);

    free(array);
}

int main() {
    srand(time(NULL));

    Dataset* dataset = initialize_dataset(INITIAL_CAPACITY);

    for (size_t i = 0; i < 20; ++i) {
        double random_value = ((double)rand() / RAND_MAX) * 100.0;
        add_record(dataset, random_value, rand(), rand(), "Sample Buffer");
    }

    switch_version(dataset, 0); // Switch to initial version

    char filename[] = "dataset.bin";
    serialize_dataset(dataset, filename);

    Dataset* loaded_dataset;
    deserialize_dataset(&loaded_dataset, filename);

    read_integers_and_find_largest();

    free_dataset(dataset);
    free_dataset(loaded_dataset);

    return 0;
}
```

