#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // Example: 1MB limit
#define KEY_MIN 0
#define KEY_MAX 10000
#define VALUE_MIN -1000000
#define VALUE_MAX 1000000

typedef struct {
    long timestamp;
    double amount;
    char status[10];
} Transaction;

typedef struct {
    int key;
    long value;
    Transaction* transactions;
    size_t transaction_count;
} Record;

typedef struct {
    Record** records;
    size_t record_count;
    pthread_mutex_t lock;
} RecordSet;

void adjust_to_boundary(int *key, int min, int max) {
    if (*key < min) *key = min;
    else if (*key > max) *key = max;
}

long random_within_range(long min, long max) {
    return min + rand() % (max - min + 1);
}

RecordSet* create_record_set() {
    RecordSet* set = malloc(sizeof(RecordSet));
    if (!set) return NULL;

    set->records = NULL;
    set->record_count = 0;
    pthread_mutex_init(&set->lock, NULL);

    return set;
}

void free_record_set(RecordSet* set) {
    if (!set) return;

    for (size_t i = 0; i < set->record_count; ++i) {
        free(set->records[i]->transactions);
        free(set->records[i]);
    }
    free(set->records);

    pthread_mutex_destroy(&set->lock);
    free(set);
}

int add_record(RecordSet* set, int key, long value) {
    if (!set || set->record_count * sizeof(Record*) > MAX_MEMORY_USAGE)
        return -1;

    adjust_to_boundary(&key, KEY_MIN, KEY_MAX);

    Record* record = malloc(sizeof(Record));
    if (!record) return -1;

    record->key = key;
    record->value = value < VALUE_MIN ? VALUE_MIN : (value > VALUE_MAX ? VALUE_MAX : value);
    record->transactions = NULL;
    record->transaction_count = 0;

    pthread_mutex_lock(&set->lock);

    set->records = realloc(set->records, sizeof(Record*) * (set->record_count + 1));
    if (!set->records) {
        free(record);
        pthread_mutex_unlock(&set->lock);
        return -1;
    }

    set->records[set->record_count++] = record;

    pthread_mutex_unlock(&set->lock);

    return 0;
}

int update_transaction(RecordSet* set, size_t index, Transaction transaction) {
    if (!set || index >= set->record_count)
        return -1;

    Record* record = set->records[index];

    pthread_mutex_lock(&set->lock);

    record->transactions = realloc(record->transactions,
                                   sizeof(Transaction) * (record->transaction_count + 1));
    if (!record->transactions) {
        pthread_mutex_unlock(&set->lock);
        return -1;
    }

    record->transactions[record->transaction_count++] = transaction;

    pthread_mutex_unlock(&set->lock);

    return 0;
}

Transaction* get_transaction(RecordSet* set, size_t index, size_t transaction_index) {
    if (!set || index >= set->record_count)
        return NULL;

    Record* record = set->records[index];

    if (transaction_index >= record->transaction_count)
        return NULL;

    return &record->transactions[transaction_index];
}

void serialize_record_set(RecordSet* set, const char* filename) {
    // Implement serialization logic
}

void deserialize_record_set(RecordSet** set, const char* filename) {
    // Implement deserialization logic
}

int main() {
    srand(time(NULL));
    RecordSet* recordSet = create_record_set();

    add_record(recordSet, 5000, random_within_range(VALUE_MIN, VALUE_MAX));

    Transaction txn = {time(NULL), 123.45, "Pending"};
    update_transaction(recordSet, 0, txn);

    Transaction* retrieved_txn = get_transaction(recordSet, 0, 0);
    if (retrieved_txn) {
        printf("Transaction: %f, Status: %s\n", retrieved_txn->amount, retrieved_txn->status);
    }

    free_record_set(recordSet);

    return 0;
}
