typedef struct {
    char message[256];
    int timestamp;
} Log;

Log* allocate_logs(size_t count) {
    if (count == 0) return NULL;

    // Allocate memory for the array of logs
    Log *logs = (Log *)malloc(count * sizeof(Log));
    if (!logs) return NULL;  // Handle allocation failure

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        snprintf(logs[i].message, sizeof(logs[i].message), "Log entry %zu", i);
        logs[i].timestamp = (int)(time(NULL) + i); // Unique timestamp based on index
    }

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        printf("Initialized: %s at %d\n", logs[i].message, logs[i].timestamp);
    }
    pthread_mutex_unlock(&lock);

    return logs;
}

void free_logs(Log *logs) {
    if (logs) {
        free(logs);
    }
}

Log* filter_logs_by_timestamp(Log *logs, size_t count, int timestamp_start, int timestamp_end) {
    if (!logs || count == 0) return NULL;

    size_t filtered_count = 0;
    for (size_t i = 0; i < count; ++i) {
        if (logs[i].timestamp >= timestamp_start && logs[i].timestamp <= timestamp_end) {
            ++filtered_count;
        }
    }

    Log *filtered_logs = (Log *)malloc(filtered_count * sizeof(Log));
    if (!filtered_logs) return NULL;

    size_t j = 0;
    for (size_t i = 0; i < count; ++i) {
        if (logs[i].timestamp >= timestamp_start && logs[i].timestamp <= timestamp_end) {
            filtered_logs[j++] = logs[i];
        }
    }

    return filtered_logs;
}

int main() {
    size_t log_count = 10;
    Log *logs = allocate_logs(log_count);

    if (!logs) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    int start_ts = (int)(time(NULL));
    int end_ts = start_ts + log_count;

    Log *filtered_logs = filter_logs_by_timestamp(logs, log_count, start_ts, end_ts);

    if (filtered_logs) {
        for (size_t i = 0; i < log_count; ++i) {
            printf("Filtered: %s at %d\n", filtered_logs[i].message, filtered_logs[i].timestamp);
        }
        free(filtered_logs);
    }

    free_logs(logs);

    return EXIT_SUCCESS;
}
