// Define the data structure
typedef struct {
    char *buffer;
    int value;
} Data;

// Define a cache entry for REST API results
typedef struct CacheEntry {
    char *data;
    size_t index;
    time_t timestamp;
    struct CacheEntry *next;
} CacheEntry;

// Define a simple memory pool structure
typedef struct {
    Data **pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->capacity = initial_capacity;
    mp->size = 0;
    mp->pool = (Data **)calloc(initial_capacity, sizeof(Data *));
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

// Function to free the memory pool
void destroy_memory_pool(MemoryPool *mp) {
    for (size_t i = 0; i < mp->size; ++i) {
        if (mp->pool[i]) {
            free(mp->pool[i]->buffer);
            free(mp->pool[i]);
        }
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to fetch data from REST API with caching
char* fetch_data_with_cache(size_t index, CacheEntry **cache_head) {
    // Define cache parameters
    const size_t max_cache_size = 100;
    time_t current_time = time(NULL);

    // Check cache first
    for (CacheEntry *entry = *cache_head; entry != NULL; entry = entry->next) {
        if (entry->index == index && difftime(current_time, entry->timestamp) < 60) { // Cache expiry of 1 minute
            return entry->data;
        }
    }

    // Simulate a REST API call with random success/failure for demonstration
    char *api_result = malloc(20);
    if (api_result) {
        snprintf(api_result, 20, "%zu", index); // Fallback to using the index as string
    } else {
        return NULL; // Indicate failure
    }

    // Insert into cache
    CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    new_entry->data = api_result;
    new_entry->index = index;
    new_entry->timestamp = current_time;
    new_entry->next = *cache_head;
    *cache_head = new_entry;

    // Maintain cache size
    if (*cache_head != NULL && --max_cache_size == 0) {
        CacheEntry *temp = *cache_head;
        *cache_head = (*cache_head)->next;
        free(temp->data);
        free(temp);
    }

    return api_result;
}

// Function to manage memory for the data array
Data* create_data_array(size_t initial_count, MemoryPool **mp) {
    if (initial_count == 0 || mp == NULL) return NULL;

    *mp = create_memory_pool(initial_count);

    // Simulate a cache head pointer
    CacheEntry *cache_head = NULL;

    for (size_t i = 0; i < initial_count; ++i) {
        pthread_mutex_lock(&(*mp)->lock);
        if ((*mp)->size >= (*mp)->capacity) {
            size_t new_capacity = (*mp)->capacity * 2;
            Data **new_pool = (Data **)realloc((*mp)->pool, new_capacity * sizeof(Data *));
            if (!new_pool) {
                pthread_mutex_unlock(&(*mp)->lock);
                return NULL; // Handle allocation failure
            }
            memset(new_pool + (*mp)->capacity, 0, ((*mp)->capacity) * sizeof(Data *));
            (*mp)->pool = new_pool;
            (*mp)->capacity = new_capacity;
        }

        Data *new_data = (Data *)malloc(sizeof(Data));
        if (!new_data) {
            pthread_mutex_unlock(&(*mp)->lock);
            return NULL; // Handle allocation failure
        }

        char *data_string = fetch_data_with_cache(i, &cache_head);
        if (data_string == NULL) {
            free(new_data);
            pthread_mutex_unlock(&(*mp)->lock);
            continue; // Skip this entry on API failure
        }

        new_data->buffer = strdup(data_string); // Duplicate string to store in data struct
        new_data->value = i;
        (*mp)->pool[(*mp)->size++] = new_data;

        pthread_mutex_unlock(&(*mp)->lock);
    }

    return (*mp)->pool;
}

// Function to resize the data array
int resize_data_array(MemoryPool *mp, size_t new_size) {
    if (new_size == 0 || mp == NULL) return -1;

    pthread_mutex_lock(&mp->lock);

    if (new_size > mp->capacity) {
        Data **new_pool = realloc(mp->pool, new_size * sizeof(Data *));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return -1; // Handle allocation failure
        }
        memset(new_pool + mp->capacity, 0, (new_size - mp->capacity) * sizeof(Data *));
        mp->capacity = new_size;
    }

    for (size_t i = mp->size; i < new_size; ++i) {
        Data *new_data = malloc(sizeof(Data));
        if (!new_data) {
            pthread_mutex_unlock(&mp->lock);
            return -1; // Handle allocation failure
        }
        char *data_string = malloc(20); // Assume a buffer size for demonstration
        if (data_string) {
            snprintf(data_string, 20, "%zu", i);
            new_data->buffer = strdup(data_string);
            new_data->value = i;
            mp->pool[i] = new_data;
        } else {
            free(new_data);
        }
    }

    mp->size = new_size;
    pthread_mutex_unlock(&mp->lock);

    return 0;
}

// Example usage
int main() {
    size_t initial_count = 10;
    MemoryPool *mp;

    Data *data_array = create_data_array(initial_count, &mp);
    if (!data_array) {
        fprintf(stderr, "Failed to allocate data array.\n");
        return EXIT_FAILURE;
    }

    // Resize the array
    int result = resize_data_array(mp, 20);
    if (result != 0) {
        fprintf(stderr, "Failed to resize data array.\n");
    } else {
        printf("Data array resized successfully.\n");
    }

    destroy_memory_pool(mp);

    return EXIT_SUCCESS;
}
