fn processMerchantTransactions(transactions: Vec<Transaction>) -> Result<(), &'static str> {
    let cache = Arc::new(Mutex::new(HashMap::new()));

    for transaction in transactions.iter_mut() {
        let client = PaymentClient::new(
            &transaction.merchant_account_details,
            &transaction.payment_method
        );

        if let Err(e) = process_transaction(transaction, &client, &cache) {
            eprintln!("Error processing transaction {}: {}", transaction.transaction_id, e);
        }
    }

    Ok(())
}

fn process_transaction(
    transaction: &mut Transaction,
    client: &PaymentClient,
    cache: &Arc<Mutex<HashMap<Uuid, String>>>,
) -> Result<(), &'static str> {
    // Check cache
    let mut cache = cache.lock().unwrap();
    if let Some(status) = cache.get(&transaction.transaction_id) {
        transaction.status = status.clone();
        return Ok(());
    }

    client.initiate_transaction(transaction);

    // Retry mechanism with backoff strategy
    for attempt in 1..=3 {
        match client.poll_status(transaction.transaction_id) {
            "success" => {
                transaction.status = "completed".to_string();
                cache.insert(transaction.transaction_id.clone(), "completed".to_string());
                return Ok(());
            }
            _ if attempt < 3 => {
                eprintln!("Retrying transaction {}", transaction.transaction_id);
                std::thread::sleep(std::time::Duration::from_secs(attempt * 2));
            }
            _ => {
                transaction.status = "failed".to_string();
                cache.insert(transaction.transaction_id.clone(), "failed".to_string());
                return Err("Transaction failed after retries");
            }
        }
    }

    Ok(())
}

