    merchant_account_id: &str,
    category: &str,
) -> Result<Vec<Transaction>, &'static str> {
    let connection_string = "postgres://user:password@localhost/dbname";  // Example
    let client = postgres::Client::connect(connection_string, postgres::NoTls)?;

    // SQL query using parameterized queries
    let rows = client.query(
        "SELECT * FROM Transactions WHERE merchant_account_id = $1 AND product_info LIKE $2",
        &[&merchant_account_id, &format!("%{}%", category)],
    )?;

    let mut transactions = Vec::new();
    for row in rows.iter() {
        let transaction = Transaction {
            transaction_id: Uuid::parse_str(row.get("transaction_id")?)?,
            merchant_account_details: row.get("merchant_account_details")?,
            payment_method: row.get("payment_method")?,
            currency: row.get("currency")?,
            amount: row.get("amount")?,
            status: row.get("status")?,
            timestamps: SystemTime::UNIX_EPOCH + std::time::Duration::new(row.get("timestamps")?, 0),
            customer_info: row.get("customer_info")?,
            product_info: row.get("product_info")?,
        };
        transactions.push(transaction);
    }

    Ok(transactions)
}

fn main() {
    let initial_transactions = vec![Transaction::default(); 10];
    if let Err(e) = processMerchantTransactions(initial_transactions) {
        eprintln!("Processing error: {}", e);
    }
}
