    let log_clients = Arc::new(Mutex::new(Vec::new()));

    // Initialize logs
    let mut entries: Vec<LogEntry> = source_ids
        .iter()
        .flat_map(|&source_id| (1..=10).map(move |i| LogEntry::new(i + 1000 * source_id, &format!("Source {}", source_id))))
        .collect();

    // Create log clients
    let mut clients = Vec::with_capacity(source_ids.len());
    for (&source_id, log_type) in source_ids.iter().zip(&log_types) {
        clients.push(LogClient::new(source_id, &log_type));
    }
    {
        let mut clients_lock = log_clients.lock().unwrap();
        clients_lock.extend(clients);
    }

    // Simulate concurrent processing
    let handles: Vec<_> = entries.into_iter().map(|entry| {
        let log_clients = Arc::clone(&log_clients);

        thread::spawn(move || {
            let client_entry = log_clients.lock().unwrap()
                .iter()
                .find(|client| client.source_id == entry.log_id / 1000); // Simplified matching logic

            if let Some(client) = client_entry {
                client.submit_log(&entry);
            }
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }

    Ok(())
