// Define a record structure containing an integer key and a long offset.
typedef struct {
    int key;
    long offset;
} Record;

// Global lock for thread safety in concurrent access
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

// Thread-safe random number generator
unsigned int seed_global = 1; // Global seed for consistency

void init_random_seed(unsigned int seed) {
    pthread_mutex_lock(&lock);
    seed_global = seed;
    srand(seed);
    pthread_mutex_unlock(&lock);
}

int thread_safe_rand() {
    int value;
    pthread_mutex_lock(&lock);
    value = rand();
    pthread_mutex_unlock(&lock);
    return value;
}

// Function to manage records with dynamic allocation
Record* create_records(int count, unsigned int seed) {
    if (count <= 0) return NULL;

    init_random_seed(seed);

    Record *records = (Record *)malloc(count * sizeof(Record));
    if (!records) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    long total_memory_usage = count * sizeof(Record);
    log_message("Allocated memory for records.");

    // Initialize records with random keys and offsets
    for (int i = 0; i < count; ++i) {
        records[i].key = thread_safe_rand();
        records[i].offset = thread_safe_rand();
    }
    log_message("Initialized records array.");

    return records;
}

// Function to deallocate the memory of records safely
void destroy_records(Record *records) {
    if (records) {
        free(records);
        log_message("Deallocated memory for records.");
    }
}

// Example usage
int main() {
    int num_records = 1000; // Specify number of records at runtime
    unsigned int seed_value = 12345;

    Record *records = create_records(num_records, seed_value);
    if (!records) {
        log_message("Failed to create records.");
        return EXIT_FAILURE;
    }

    // Example operation: print the first record (for demonstration)
    printf("First Record - Key: %d, Offset: %ld\n", records[0].key, records[0].offset);

    destroy_records(records);
    return EXIT_SUCCESS;
}
