// Define structure for records
typedef struct {
    int value;
    long *offsetPtr;
    int *keyPtr;
    int refCount;
} record;

// Global memory pool (for simplicity, using a single malloc/free)
#define INITIAL_POOL_SIZE 1024
#define MAX_RECORDS 1000

long *offsetPool = NULL;
int *keyPool = NULL;
record *recordPool = NULL;
size_t offsetPoolSize = 0;
size_t keyPoolSize = 0;
size_t recordPoolSize = 0;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log(const char *message) {
    printf("LOG: %s\n", message);
}

record* createRecord(int value, long offset, int key) {
    if (offsetPoolSize <= recordPoolSize || keyPoolSize <= recordPoolSize) {
        log("Resizing memory pool");
        // Resize pools
        size_t newSize = (recordPoolSize + 1024 > INITIAL_POOL_SIZE ? recordPoolSize + 1024 : INITIAL_POOL_SIZE);
        offsetPool = realloc(offsetPool, newSize * sizeof(long));
        keyPool = realloc(keyPool, newSize * sizeof(int));
        recordPool = realloc(recordPool, newSize * sizeof(record));

        if (!offsetPool || !keyPool || !recordPool) {
            log("Memory allocation failure in createRecord");
            exit(EXIT_FAILURE);
        }

        offsetPoolSize = newSize;
        keyPoolSize = newSize;
        recordPoolSize = newSize;
    }

    long* offsetPtr = &offsetPool[recordPoolSize];
    int* keyPtr = &keyPool[recordPoolSize];

    *offsetPtr = offset;
    *keyPtr = key;

    recordPool[recordPoolSize].value = value;
    recordPool[recordPoolSize].offsetPtr = offsetPtr;
    recordPool[recordPoolSize].keyPtr = keyPtr;
    recordPool[recordPoolSize].refCount = 0;

    return &recordPool[recordPoolSize++];
}

void initializeRecords(size_t size, int rangeMin, int rangeMax) {
    log("Initializing records");
    pthread_mutex_lock(&mutex);

    if (size > MAX_RECORDS || offsetPool || keyPool || recordPool) {
        log("Initialization failed: invalid size or previous initialization.");
        exit(EXIT_FAILURE);
    }

    offsetPool = malloc(INITIAL_POOL_SIZE * sizeof(long));
    keyPool = malloc(INITIAL_POOL_SIZE * sizeof(int));
    recordPool = malloc(INITIAL_POOL_SIZE * sizeof(record));

    if (!offsetPool || !keyPool || !recordPool) {
        log("Memory allocation failure in initializeRecords");
        pthread_mutex_unlock(&mutex);
        exit(EXIT_FAILURE);
    }

    offsetPoolSize = INITIAL_POOL_SIZE;
    keyPoolSize = INITIAL_POOL_SIZE;
    recordPoolSize = 0;

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        int value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        createRecord(value, i, i); // offset and key are set to index for simplicity
    }

    pthread_mutex_unlock(&mutex);
}

void incrementRefCount(record *rec) {
    if (!rec) return;

    log("Incrementing reference count");
    pthread_mutex_lock(&mutex);
    rec->refCount++;
    pthread_mutex_unlock(&mutex);
}

void decrementRefCountAndFreeIfNeeded(record *rec) {
    if (!rec) return;

    log("Decrementing reference count");
    pthread_mutex_lock(&mutex);
    if (--rec->refCount == 0) {
        size_t index = (size_t)((long long)rec - (long long)&recordPool[0]);
        memmove(&recordPool[index], &recordPool[index + 1],
                sizeof(record) * (recordPoolSize - index - 1));
        recordPoolSize--;
    }
    pthread_mutex_unlock(&mutex);
}

record* getRecordByIndex(size_t index) {
    if (index >= recordPoolSize) return NULL;

    log("Retrieving record by index");
    return &recordPool[index];
}

int findMaxInArray(int *arr, size_t n) {
    if (n == 0) return INT_MIN;

    int max = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

void readInputAndFindMax() {
    log("Reading input and finding maximum");
    size_t capacity = 16, count = 0;
    int *inputArray = malloc(capacity * sizeof(int));

    if (!inputArray) {
        log("Memory allocation failure in readInputAndFindMax");
        exit(EXIT_FAILURE);
    }

    int value;
    while (scanf("%d", &value) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            inputArray = realloc(inputArray, capacity * sizeof(int));
            if (!inputArray) {
                log("Memory allocation failure in readInputAndFindMax");
                exit(EXIT_FAILURE);
            }
        }
        inputArray[count++] = value;
    }

    int max = findMaxInArray(inputArray, count);
    printf("Maximum integer is: %d\n", max);

    free(inputArray);
}

int main() {
    initializeRecords(10, 0, 100); // Example initialization

    // Simulate increment and decrement
    record *rec = getRecordByIndex(5);
    if (rec) {
        incrementRefCount(rec);
        decrementRefCountAndFreeIfNeeded(rec);
    }

    readInputAndFindMax();

    free(offsetPool);
    free(keyPool);
    free(recordPool);

    return 0;
}
