#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record **records;
    size_t count;
    pthread_rwlock_t rwlock;
} DynamicArray;

// Helper function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Function to allocate and initialize the dynamic array
DynamicArray* create_dynamic_array(size_t num_records) {
    if (num_records == 0) return NULL;

    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = malloc(num_records * sizeof(Record *));
    if (!array->records) {
        free(array);
        return NULL;
    }

    pthread_rwlock_init(&array->rwlock, NULL);
    for (size_t i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            // Handle allocation failure
            while (--i >= 0) free(array->records[i]);
            free(array->records);
            pthread_rwlock_destroy(&array->rwlock);
            free(array);
            return NULL;
        }

        record->value = rand() % 100; // Random value between 0 and 99
        record->offset = malloc(sizeof(long));
        if (!record->offset) {
            free(record);
            continue;
        }
        *record->offset = 0;

        record->key = malloc(sizeof(int));
        if (!record->key) {
            free(*record->offset);
            free(record);
            continue;
        }
        *record->key = i; // Initialize key with index

        array->records[i] = record;
    }

    array->count = num_records;
    return array;
}

// Function to retrieve a specific record by its index
Record* get_record(DynamicArray *array, size_t index) {
    if (!array || index >= array->count) return NULL;

    pthread_rwlock_rdlock(&array->rwlock);
    Record *record = array->records[index];
    pthread_rwlock_unlock(&array->rwlock);

    return record;
}

// Function to update a record's value and pointers
int update_record(DynamicArray *array, size_t index, int new_value, long offset, int key) {
    if (!array || index >= array->count) return -1;

    pthread_rwlock_wrlock(&array->rwlock);
    Record *record = array->records[index];

    record->value = new_value;
    free(record->offset);
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        pthread_rwlock_unlock(&array->rwlock);
        return -1; // Handle allocation failure
    }
    *record->offset = offset;

    free(record->key);
    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        pthread_rwlock_unlock(&array->rwlock);
        return -1; // Handle allocation failure
    }
    *record->key = key;

    pthread_rwlock_unlock(&array->rwlock);

    return 0;
}

// Function to delete a record from the dynamic array
int delete_record(DynamicArray *array, size_t index) {
    if (!array || index >= array->count) return -1;

    pthread_rwlock_wrlock(&array->rwlock);
    Record *record = array->records[index];

    free(record->offset);
    free(record->key);
    free(record);

    // Shift remaining records
    for (size_t i = index; i < array->count - 1; ++i) {
        array->records[i] = array->records[i + 1];
    }
    array->records[--array->count] = NULL;

    pthread_rwlock_unlock(&array->rwlock);

    return 0;
}

// Function to free the dynamic array
void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    pthread_rwlock_wrlock(&array->rwlock);
    for (size_t i = 0; i < array->count; ++i) {
        Record *record = array->records[i];
        free(record->offset);
        free(record->key);
        free(record);
    }
    free(array->records);

    pthread_rwlock_unlock(&array->rwlock);
    pthread_rwlock_destroy(&array->rwlock);
    free(array);
}

// Example usage
int main() {
    init_random();

    DynamicArray *array = create_dynamic_array(10);
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array.\n");
        return EXIT_FAILURE;
    }

    Record *record = get_record(array, 0);
    if (record) printf("Value: %d\n", record->value);

    update_record(array, 0, 42, 1234, 5678);
    record = get_record(array, 0);
    if (record) printf("Updated Value: %d\n", record->value);

    delete_record(array, 0);

    destroy_dynamic_array(array);

    return EXIT_SUCCESS;
}
```

