    for (int i = currentSize; i < newSize; ++i) {
        newRecords[i].offset = rand() % 100000;
        newRecords[i].key = rand() % 10000;

        newRecords[i].rec.value = minVal + rand() % (maxVal - minVal + 1);
        newRecords[i].rec.offsetPtr = &newRecords[i].offset;
        newRecords[i].rec.keyPtr = &newRecords[i].key;
    }

    return newRecords;
}

