#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* data;
    int priority;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(const char* data, int priority);
void add_node_at_end(Node** head, const char* data, int priority);
void insert_node_at_position(Node** head, const char* data, int priority, int position);
Node* search_by_data(Node* head, const char* data);
int remove_node_by_data(Node** head, const char* data);
void free_list(Node** head);

// Function implementations
Node* create_node(const char* data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = strdup(data);
    new_node->priority = priority;
    new_node->next = NULL;

    return new_node;
}

void add_node_at_end(Node** head, const char* data, int priority) {
    Node* new_node = create_node(data, priority);

    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void insert_node_at_position(Node** head, const char* data, int priority, int position) {
    if (position < 0) return;

    Node* new_node = create_node(data, priority);
    if (!new_node) return;

    if (position == 0 || *head == NULL) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        for (int i = 1; i < position && current->next != NULL; i++) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

Node* search_by_data(Node* head, const char* data) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->data, data) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

int remove_node_by_data(Node** head, const char* data) {
    if (*head == NULL) return 0;

    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && strcmp(current->data, data) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return 0; // Data not found

    if (previous == NULL) { // Head needs to be removed
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->data);
    free(current);

    return 1;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current->data);
        free(current);
        current = next_node;
    }
    *head = NULL;
}
