    record->weight = malloc(sizeof(Weight));
    if (!record->weight) {
        free(record->key);
        free(record->offset);
        free(record);
        return -1;
    }

    record->weight->weight = (double)(rand() % 100) / 10.0; // Example distribution

    storage->records[storage->count++] = record;

    return 0;
}

int update_record_value(RecordStorage *storage, size_t index, int new_value) {
