// Utility function to generate a random alphanumeric string.
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* result = malloc(length + 1);
    if (result == NULL) return NULL;

    for (size_t i = 0; i < length; i++) {
        int index = rand() % (sizeof(charset) - 1);
        result[i] = charset[index];
    }
    result[length] = '\0';
    return result;
}

// Utility function to create a unique identifier.
char* generate_unique_identifier(const char* base_id, size_t suffix_length) {
    static pthread_mutex_t id_mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&id_mutex);

    time_t current_time = time(NULL);
    struct tm *tm_info = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);

    char* random_suffix = generate_random_string(suffix_length);
    if (random_suffix == NULL) {
        log_error("Failed to generate random suffix");
        pthread_mutex_unlock(&id_mutex);
        return NULL;
    }

    size_t base_id_len = strlen(base_id);
    size_t timestamp_len = strlen(timestamp);
    size_t random_suffix_len = strlen(random_suffix);

    // Calculate total length including null terminator
    size_t total_length = base_id_len + 1 + timestamp_len + 1 + random_suffix_len + 1;

    if (total_length > 255) {
        free(random_suffix);
        pthread_mutex_unlock(&id_mutex);
        return NULL;
    }

    char* unique_identifier = malloc(total_length * sizeof(char));
    if (unique_identifier == NULL) {
        free(random_suffix);
        pthread_mutex_unlock(&id_mutex);
        return NULL;
    }

    snprintf(unique_identifier, total_length, "%s-%s-%s", base_id, timestamp, random_suffix);

    // Check for uniqueness in distributed database
    int suffix = 0;
    while (check_identifier_in_db(unique_identifier)) {
        free(random_suffix);

        char* new_random_suffix = generate_random_string(suffix_length);
        if (new_random_suffix == NULL) {
            log_error("Failed to generate new random suffix");
            free(unique_identifier);
            pthread_mutex_unlock(&id_mutex);
            return NULL;
        }

        snprintf(unique_identifier, total_length, "%s-%s-%d", base_id, timestamp, ++suffix);
    }

    free(random_suffix);
    pthread_mutex_unlock(&id_mutex);

    return unique_identifier;
}

// Function to initialize the memory for records.
Record* initialize_records(size_t num_records, long max_offset_value, int min_key_value, int max_key_value) {
    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_t mem_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize each record.
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mem_mutex);

        long* offset = malloc(sizeof(long));
        if (offset == NULL) {
            log_error("Failed to allocate memory for offset");
            free(records);
            return NULL;
        }

        *offset = rand() % max_offset_value;

        int* key = malloc(sizeof(int));
        if (key == NULL) {
            free(offset);
            log_error("Failed to allocate memory for key");
            free(records);
            return NULL;
        }

        *key = min_key_value + (rand() % (max_key_value - min_key_value + 1));

        records[i].value = rand();
        records[i].offset = offset;
        records[i].key = key;

        pthread_mutex_unlock(&mem_mutex);
    }

    return records;
}

// Log error with thread safety
void log_error(const char* message) {
    pthread_mutex_lock(&log_mutex);
    fprintf(stderr, "Error: %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    size_t num_records = 1000;  // Example number of records
    long max_offset_value = 100000;
    int min_key_value = 1, max_key_value = 100;

    // Initialize records
    Record* records = initialize_records(num_records, max_offset_value, min_key_value, max_key_value);

    if (records == NULL) {
        log_error("Initialization of records failed");
        return EXIT_FAILURE;
    }

    // Generate a unique identifier with a base ID and random suffix length.
    const char* base_id = "example-base-id";
    size_t suffix_length = 16;  // Example length for the random alphanumeric string

    char* unique_identifier = generate_unique_identifier(base_id, suffix_length);

    if (unique_identifier == NULL) {
        log_error("Failed to generate a unique identifier");
        free(records);
        return EXIT_FAILURE;
    }

    printf("Unique Identifier: %s\n", unique_identifier);

    // Cleanup
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }

    free(records);
    free(unique_identifier);

    return EXIT_SUCCESS;
}
