// Record structure definition
typedef struct Record {
    int value;
    unsigned long offset;
    const char* key;
    time_t timestamp; // Insertion timestamp
    int reference_count;
    struct Record* next;
} Record;

// Node for maintaining the metadata of each record
typedef struct ListNode {
    Record* record;
    struct ListNode* next;
} ListNode;

// Linked list structure with head, tail and lock for thread safety
typedef struct {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t lock;
    unsigned int size;
} RecordList;

// Function to initialize the linked list
RecordList* init_record_list(unsigned int initial_size) {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;

    // Initialize records
    for (unsigned int i = 0; i < initial_size; ++i) {
        if (!insert_record(list, 0, "default_key")) { // Replace with actual default values as needed
            free_record_list(list); // Cleanup on failure
            return NULL;
        }
    }

    return list;
}

// Function to insert a new record into the linked list
int insert_record(RecordList* list, int value, const char* key) {
    if (!list || !key) return -1;

    pthread_mutex_lock(&list->lock);

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Set record fields
    new_record->value = value;
    new_record->offset = list->size; // Use size as offset for simplicity
    new_record->key = key;
    time(&(new_record->timestamp));
    new_record->reference_count = 0;
    new_record->next = NULL;

    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) {
        free(new_record);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    node->record = new_record;
    node->next = NULL;

    if (list->tail) {
        list->tail->next = node;
        list->tail = node;
    } else {
        list->head = list->tail = node;
    }

    ++(list->size);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to increment the reference count of a specified record
int increment_reference_count(RecordList* list, unsigned long offset) {
    if (!list || !offset) return -1;

    pthread_mutex_lock(&list->lock);

    ListNode* node = list->head;
    while (node) {
        if (node->record && node->record->offset == offset) {
            ++(node->record->reference_count);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Record not found
}

// Function to retrieve a record by its index (offset)
Record* get_record_by_offset(RecordList* list, unsigned long offset) {
    if (!list || !offset) return NULL;

    pthread_mutex_lock(&list->lock);

    ListNode* node = list->head;
    while (node) {
        if (node->record && node->record->offset == offset) {
            pthread_mutex_unlock(&list->lock);
            return node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Record not found
}

// Function to clean up and free the linked list
void free_record_list(RecordList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current) {
        ListNode* next_node = current->next;
        free(current->record);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
