typedef enum { ACTIVE, DELETED, PENDING } MetadataTag;

typedef struct {
    long offset;
    int key;
    void *record; // Placeholder for actual record structure
    MetadataTag metadata;
} Record;

typedef struct {
    size_t capacity;
    size_t size;
    Record **records;
    pthread_mutex_t lock;
} DynamicArray;

#define MAX_KEY 1000
#define LOG_FILE "operations.log"
#define COMPRESSION_LEVEL Z_DEFAULT_COMPRESSION

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->size = 0;
    array->records = calloc(initial_capacity, sizeof(Record *));
    if (!array->records) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void log_operation(const char *operation_type, size_t index, MetadataTag metadata) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) return;

    time_t now = time(NULL);
    fprintf(log_file, "%s - %zu - %d\n", operation_type, index, metadata);
    fclose(log_file);
}

void compress_array(Record **records, size_t num_records, int level) {
    // Simulate compression by writing to a temporary file
    FILE *temp_file = fopen("compressed_data.bin", "wb");
    if (!temp_file) return;

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(records[i], sizeof(Record), 1, temp_file);
    }
    fclose(temp_file);

    // Simulate decompression by reopening and reading
    FILE *decompressed_file = fopen("decompressed_data.bin", "wb");
    if (!decompressed_file) return;

    fseek(temp_file, 0, SEEK_SET);
    while (fread(&records[0], sizeof(Record), 1, temp_file)) {
        fwrite(&records[0], sizeof(Record), 1, decompressed_file);
    }
    fclose(decompressed_file);
}

int add_record(DynamicArray *array, long offset, int key_range_min, int key_range_max, MetadataTag metadata) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record **new_records = realloc(array->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    int key = rand() % (key_range_max - key_range_min + 1) + key_range_min;

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->record = NULL; // Placeholder for actual record initialization
    new_record->metadata = metadata;

    array->records[array->size++] = new_record;

    log_operation("ADD", array->size - 1, metadata);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    srand(time(NULL));

    DynamicArray *array = init_dynamic_array(10);
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 20; ++i) {
        add_record(array, i * 1000, 1, MAX_KEY, ACTIVE);
    }

    compress_array(array->records, array->size, COMPRESSION_LEVEL);

    free_dynamic_array(array);

    return EXIT_SUCCESS;
}
