#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record data;
} entry_t;

typedef struct hash_table_node {
    int key;
    entry_t *entry;
    struct hash_table_node *next;
} hash_table_node;

typedef struct {
    hash_table_node **buckets;
    size_t capacity;
    pthread_mutex_t lock;
} hash_table;

// Hash function
unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

// Initialize dynamic collection
entry_t* init_collection(size_t num_records, int min_value, int max_value) {
    if (num_records == 0 || min_value > max_value) {
        return NULL;
    }

    entry_t *collection = malloc(num_records * sizeof(entry_t));
    if (!collection) {
        perror("Failed to allocate memory for collection");
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        collection[i].offset = rand() % 100000;
        collection[i].key = rand() % 1000;
        collection[i].data.value = min_value + rand() % (max_value - min_value + 1);
    }

    return collection;
}

// Initialize hash table
hash_table* init_hash_table(size_t capacity) {
    hash_table *table = malloc(sizeof(hash_table));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    table->capacity = capacity;
    table->buckets = calloc(capacity, sizeof(hash_table_node*));
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for hash table buckets");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

// Insert into hash table
void insert_hash_table(hash_table *table, entry_t *entry) {
    unsigned long index = hash(entry->key, table->capacity);
    hash_table_node *node = malloc(sizeof(hash_table_node));
    if (!node) {
        perror("Failed to allocate memory for hash table node");
        exit(EXIT_FAILURE);
    }

    node->key = entry->key;
    node->entry = entry;
    node->next = NULL;

    pthread_mutex_lock(&table->lock);
    node->next = table->buckets[index];
    table->buckets[index] = node;
    pthread_mutex_unlock(&table->lock);
}

// Retrieve a record by index
entry_t* get_record(entry_t *collection, size_t index) {
    if (index >= collection_size) {
        return NULL;
    }
    return &collection[index];
}

// Update the value of a record at a given index
void update_record_value(entry_t *collection, size_t index, int new_value) {
    if (index < collection_size) {
        collection[index].data.value = new_value;
    }
}

// Iterate over all records efficiently
void iterate_records(entry_t *collection, size_t num_records, void (*callback)(entry_t*)) {
    for (size_t i = 0; i < num_records; ++i) {
        callback(&collection[i]);
    }
}

// Example of a callback function
void print_record(entry_t *record) {
    printf("Offset: %ld, Key: %d, Value: %d\n", record->offset, record->key, record->data.value);
}

// Clean up dynamic collection and hash table
void cleanup_collection(entry_t *collection, size_t num_records, hash_table *table) {
    for (size_t i = 0; i < num_records; ++i) {
        insert_hash_table(table, &collection[i]); // Insert into hash table before deletion
    }

    free(collection);

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        hash_table_node *node = table->buckets[i];
        while (node) {
            hash_table_node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_unlock(&table->lock);

    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    size_t num_records = 1000;
    int min_value = 1, max_value = 100;

    entry_t *collection = init_collection(num_records, min_value, max_value);
    if (!collection) return EXIT_FAILURE;

    hash_table *table = init_hash_table(200);
    for (size_t i = 0; i < num_records; ++i) {
        insert_hash_table(table, &collection[i]);
    }

    iterate_records(collection, num_records, print_record);

    cleanup_collection(collection, num_records, table);

    return EXIT_SUCCESS;
}
