    return 0;
}

void cache_init(LRUCache* cache, size_t max_size) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;

    if (max_size > MAX_CACHE_SIZE) {
        max_size = MAX_CACHE_SIZE;
    }
}

void add_to_cache(LRUCache* cache, record* rec) {
    CacheNode* node = malloc(sizeof(CacheNode));
    node->rec = rec;
    node->next = cache->head;
    node->prev = NULL;

    if (cache->head != NULL) {
        cache->head->prev = node;
    }
    cache->head = node;
    if (cache->tail == NULL) {
        cache->tail = node;
    }

    cache->size++;
    log_message("Record added to cache.");

    while (cache->size > MAX_CACHE_SIZE) {
        CacheNode* old = cache->tail;
        cache->tail = cache->tail->prev;

        if (cache->tail != NULL) {
            cache->tail->next = NULL;
        }

        free(old->rec->string);
        free(old->rec);
        free(old);

        cache->size--;
    }
}

record* get_from_cache(LRUCache* cache, size_t index) {
    CacheNode* current = cache->head;

    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    if (current == NULL) return NULL;

    // Move accessed node to head
    if (current != cache->head) {
        if (current->prev != NULL) {
            current->prev->next = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = current->prev;
        }

        if (current == cache->tail) {
            cache->tail = current->prev;
        }

        current->next = cache->head;
        current->prev = NULL;

        if (cache->head != NULL) {
            cache->head->prev = current;
        }
        cache->head = current;
    }

    log_message("Record retrieved from cache.");
    return current->rec;
}

void release_cache(LRUCache* cache) {
    while (cache->tail != NULL) {
        CacheNode* old = cache->tail;
        cache->tail = cache->tail->prev;

        free(old->rec->string);
        free(old->rec);
        free(old);

        cache->size--;
    }

    cache->head = NULL;
}

void memory_monitor() {
    // Dummy function for demonstration
    log_message("Memory usage within limits.");
}

record*** create_data_structures(int* keys, long* offsets, int num_keys) {
    int range_min, range_max, max_cache_size, max_str_len;

    if (read_config(&range_min, &range_max, &max_cache_size, &max_str_len)) {
        log_message("Invalid configuration parameters.");
        return NULL;
    }

    cache_init(&cache, max_cache_size);

    record*** records = malloc(num_keys * sizeof(record**));
    for (int i = 0; i < num_keys; i++) {
        int sub_array_size = keys[i];
        if (sub_array_size <= 0) continue;

        log_message("Allocating memory for record array.");
        records[i] = malloc(sub_array_size * sizeof(record*));

        for (int j = 0; j < sub_array_size; j++) {
            record* rec;
            if (cache.size > 0 && cache.head != NULL) {
                rec = get_from_cache(&cache, 0);
                if (rec == NULL) break;
            } else {
                rec = malloc(sizeof(record));
                log_message("Allocating new memory for record.");
            }

            rec->value = rand() % (range_max - range_min + 1) + range_min;

            rec->string = malloc(max_str_len * sizeof(char));
            snprintf(rec->string, max_str_len, "Record_%d", j);
            log_message("Memory allocated for string.");

            records[i][j] = rec;
        }
    }

    memory_monitor();

    return records;
}

void free_data_structures(record*** records, int num_keys) {
    for (int i = 0; i < num_keys; i++) {
        if (records[i]) {
            log_message("Freeing memory for record array.");
            for (size_t j = 0; records[i][j] != NULL; j++) {
                free(records[i][j]->string);
                add_to_cache(&cache, records[i][j]);
            }
            free(records[i]);
        }
    }

    release_cache(&cache);
}

int main() {
    int num_keys = 5;
    int keys[] = {3, 2, 4, 1, 0}; // Example key sizes
    long offsets[5]; // Placeholder for offset values

    record*** records = create_data_structures(keys, offsets, num_keys);
    if (records != NULL) {
        free_data_structures(records, num_keys);
    }

    return 0;
}
