['Here's a comprehensive C implementation that addresses your requirements for managing a dynamic collection of networked device statuses:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define DEFAULT_GRACE_PERIOD 300.0
#define TEMP_RANGE_LOW 10
#define TEMP_RANGE_HIGH 35
#define HUMIDITY_RANGE_LOW 20
#define HUMIDITY_RANGE_HIGH 80

typedef struct {
    int temperature;
    int humidity;
} SensorData;

typedef struct {
    int id;
    double last_seen_timestamp;
    char *name;
    SensorData sensor_data;
} DeviceStatus;

typedef struct Node {
    char *name;
    DeviceStatus *device_status;
    struct Node *next;
} NameNode;

typedef struct {
    DeviceStatus **devices;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    NameNode *name_index;
} DeviceCollection;

static double current_time() {
    return (double)time(NULL);
}

DeviceCollection* init_device_collection(size_t initial_capacity, double grace_period) {
    DeviceCollection *collection = malloc(sizeof(DeviceCollection));
    if (!collection) return NULL;

    collection->devices = calloc(initial_capacity, sizeof(DeviceStatus *));
    if (!collection->devices) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    collection->name_index = NULL;

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->devices[i] = malloc(sizeof(DeviceStatus));
        if (!collection->devices[i]) break;

        collection->devices[i]->id = i;
        collection->devices[i]->last_seen_timestamp = current_time() - grace_period;
        char name_buffer[50];
        snprintf(name_buffer, sizeof(name_buffer), "Device_%zu", i);
        collection->devices[i]->name = strdup(name_buffer);

        int temp = rand() % (TEMP_RANGE_HIGH - TEMP_RANGE_LOW + 1) + TEMP_RANGE_LOW;
        int humidity = rand() % (HUMIDITY_RANGE_HIGH - HUMIDITY_RANGE_LOW + 1) + HUMIDITY_RANGE_LOW;

        collection->devices[i]->sensor_data.temperature = temp;
        collection->devices[i]->sensor_data.humidity = humidity;

        NameNode *node = malloc(sizeof(NameNode));
        if (!node) {
            free(collection->devices[i]);
            break;
        }
        node->name = strdup(name_buffer);
        node->device_status = collection->devices[i];
        node->next = collection->name_index;
        collection->name_index = node;

        ++collection->count;
    }

    return collection;
}

void cleanup_device_collection(DeviceCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->devices[i]) {
            free(collection->devices[i]->name);
            free(collection->devices[i]);
        }
    }

    NameNode *current = collection->name_index;
    while (current) {
        NameNode *next = current->next;
        free(current->name);
        free(current);
        current = next;
    }

    free(collection->devices);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

DeviceStatus* get_device_status(DeviceCollection *collection, int id) {
    if (!collection || id < 0 || (size_t)id >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);

    DeviceStatus *status = collection->devices[id];

    pthread_mutex_unlock(&collection->lock);
    return status;
}

void update_device_status(DeviceCollection *collection, int id, int temperature, int humidity) {
    if (!collection || id < 0 || (size_t)id >= collection->count) return;

    pthread_mutex_lock(&collection->lock);

    DeviceStatus *status = collection->devices[id];
    status->sensor_data.temperature = temperature;
    status->sensor_data.humidity = humidity;

    pthread_mutex_unlock(&collection->lock);
}

void iterate_devices(DeviceCollection *collection, void (*callback)(DeviceStatus*)) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->devices[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

void resize_device_collection(DeviceCollection *collection, size_t new_capacity) {
    if (!collection || new_capacity <= collection->capacity) return;

    DeviceStatus **new_devices = realloc(collection->devices, new_capacity * sizeof(DeviceStatus *));
    if (!new_devices) return;

    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        new_devices[i] = NULL;
    }

    pthread_mutex_lock(&collection->lock);

    collection->devices = new_devices;
    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->lock);
}

// Example callback function for iteration
void print_device_status(DeviceStatus *status) {
    if (!status) return;
    printf("ID: %d, Name: %s, Temp: %d, Humidity: %d\n", status->id,
           status->name, status->sensor_data.temperature, status->sensor_data.humidity);
}

int main() {
    srand((unsigned int)time(NULL));

    DeviceCollection *collection = init_device_collection(10, DEFAULT_GRACE_PERIOD);
    if (!collection) {
        fprintf(stderr, "Failed to initialize device collection\n");
        return 1;
    }

    iterate_devices(collection, print_device_status);

    cleanup_device_collection(collection);
    return 0;
}
```

