size_t external_size = sizeof(external_dataset) / sizeof(external_dataset[0]);

#define OFFSET_RANGE_START 1
#define OFFSET_RANGE_END 1000
#define KEY_RANGE_START 100
#define KEY_RANGE_END 200

// Linked list node
typedef struct Node {
    record data;
    struct Node* next;
} Node;

// Thread safety lock
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int is_key_in_external(int key);
void initialize_array(long *arr, size_t size, long start, long end);
void initialize_record_array(record *records, int *keys, size_t size);
int* generate_unique_keys(size_t count);
void free_allocated_memory(long *offsets, int *keys, record *records, Node **head);

// Main function to manage memory
void manage_memory(size_t offset_size, size_t key_size, size_t record_size) {
    pthread_mutex_lock(&lock);

    long *offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) { perror("Failed to allocate offsets"); exit(EXIT_FAILURE); }

    int *keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) { free(offsets); perror("Failed to allocate keys"); exit(EXIT_FAILURE); }

    record *records = (record*)malloc(record_size * sizeof(record));
    if (!records) { free(offsets); free(keys); perror("Failed to allocate records"); exit(EXIT_FAILURE); }

    Node *head = NULL;

    initialize_array(offsets, offset_size, OFFSET_RANGE_START, OFFSET_RANGE_END);
    int* unique_keys = generate_unique_keys(key_size);

    if (unique_keys == NULL) {
        free(offsets); free(keys); free(records);
        perror("Failed to generate unique keys");
        exit(EXIT_FAILURE);
    }

    initialize_record_array(records, unique_keys, record_size);

    // Example of linked list usage
    for (size_t i = 0; i < record_size; ++i) {
        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) { perror("Failed to allocate node"); exit(EXIT_FAILURE); }
        new_node->data.value = records[i].value;
        new_node->next = head;
        head = new_node;
    }

    // Simulate further operations...

    free_allocated_memory(offsets, keys, records, &head);

    pthread_mutex_unlock(&lock);
}

// Function implementations
int is_key_in_external(int key) {
    for (size_t i = 0; i < external_size; ++i) {
        if (external_dataset[i] == key)
            return 1;
    }
    return 0;
}

void initialize_array(long *arr, size_t size, long start, long end) {
    for (size_t i = 0; i < size; ++i) {
        arr[i] = rand() % (end - start + 1) + start;
    }
}

int* generate_unique_keys(size_t count) {
    int *keys = (int*)malloc(count * sizeof(int));
    if (!keys) return NULL;

    int attempts = 0, max_attempts = 10000;
    for (size_t i = 0; i < count;) {
        keys[i] = rand() % (KEY_RANGE_END - KEY_RANGE_START + 1) + KEY_RANGE_START;
        if (!is_key_in_external(keys[i]) && !binary_search_int_array(keys, i, keys[i])) {
            i++;
        } else if (++attempts > max_attempts) {
            free(keys);
            return NULL; // Exhausted attempts
        }
    }

    return keys;
}

int binary_search_int_array(int *arr, size_t size, int key) {
    int low = 0, high = (int)size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == key)
            return 1;
        else if (arr[mid] < key)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return 0;
}

void initialize_record_array(record *records, int *keys, size_t size) {
    for (size_t i = 0; i < size && i < sizeof(keys)/sizeof(keys[0]); ++i) {
        records[i].value = keys[i];
    }
}

void free_allocated_memory(long *offsets, int *keys, record *records, Node **head) {
    free(offsets);
    free(keys);
    while (*head != NULL) {
        Node *temp = *head;
        *head = (*head)->next;
        free(temp);
    }
    free(records);
}
