['Below is a C function implementing your requirements. This code assumes you have access to a JSON parsing library such as `cJSON` for reading the configuration file and standard libraries like `<stdlib.h>`, `<stdio.h>`, and `<string.h>`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "cJSON.h"

typedef struct {
    int value;
    char *name;
} record;

typedef struct cache_node {
    record *data;
    time_t last_used;
    struct cache_node *next, *prev;
} cache_node;

typedef struct {
    cache_node *head, *tail;
    size_t max_size;
    size_t current_size;
} lru_cache;

lru_cache *cache_init(size_t max_size) {
    lru_cache *cache = malloc(sizeof(lru_cache));
    if (!cache) return NULL;
    cache->head = cache->tail = NULL;
    cache->max_size = max_size;
    cache->current_size = 0;
    return cache;
}

void cache_put(lru_cache *cache, record *data) {
    if (cache->current_size == cache->max_size) {
        lru_cache_evict(cache);
    }

    cache_node *node = malloc(sizeof(cache_node));
    if (!node) return;

    node->data = data;
    node->last_used = time(NULL);
    node->next = NULL;

    if (cache->tail) {
        cache->tail->next = node;
        node->prev = cache->tail;
    } else {
        cache->head = node;
        node->prev = NULL;
    }

    cache->tail = node;
    cache->current_size++;
}

void lru_cache_evict(lru_cache *cache) {
    if (!cache->head) return;

    cache_node *node_to_remove = cache->head;
    cache->head = cache->head->next;

    if (cache->head) {
        cache->head->prev = NULL;
    } else {
        cache->tail = NULL;
    }

    free(node_to_remove->data->name);
    free(node_to_remove->data);
    free(node_to_remove);

    cache->current_size--;
}

record **process_configuration(const char *config_file, long long *total_records) {
    FILE *file = fopen(config_file, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *content = malloc(length + 1);
    if (!content) {
        fclose(file);
        return NULL;
    }

    fread(content, 1, length, file);
    content[length] = '\0';
    fclose(file);

    cJSON *json = cJSON_Parse(content);
    free(content);
    if (!json) return NULL;

    int min_range = cJSON_GetObjectItemCaseSensitive(json, "min_range")->valueint;
    int max_range = cJSON_GetObjectItemCaseSensitive(json, "max_range")->valueint;
    int cache_size = cJSON_GetObjectItemCaseSensitive(json, "cache_size")->valueint;
    int max_string_len = cJSON_GetObjectItemCaseSensitive(json, "max_string_len")->valueint;

    if (min_range >= max_range || cache_size <= 0 || max_string_len <= 0) {
        cJSON_Delete(json);
        return NULL;
    }

    lru_cache *cache = cache_init(cache_size);

    int array_keys_count = max_range - min_range + 1;
    long *offsets = malloc(array_keys_count * sizeof(long));
    if (!offsets) goto cleanup;

    int *keys = malloc(array_keys_count * sizeof(int));
    if (!keys) goto cleanup;

    for (int i = 0; i < array_keys_count; ++i) {
        keys[i] = min_range + i;
        offsets[i] = rand() % (max_range - min_range);
    }

    int total_records_allocated = 0;
    record **records_array = malloc(array_keys_count * sizeof(record *));
    if (!records_array) goto cleanup;

    for (int i = 0; i < array_keys_count; ++i) {
        size_t subarray_size = keys[i];
        records_array[i] = malloc(subarray_size * sizeof(record));

        if (!records_array[i]) {
            // Handle partial allocation error
            continue;
        }

        for (size_t j = 0; j < subarray_size; ++j) {
            record *record_ptr = cache->head ? cache->head->data : malloc(sizeof(record));

            if (!record_ptr) {
                // Handle memory allocation failure
                records_array[i][j].value = 0;
                continue;
            }

            if (cache->head && cache->current_size < cache->max_size) {
                record *evicted_record = cache->head->data;
                free(evicted_record->name);
                free(evicted_record);

                record_ptr->value = rand() % max_range;
                record_ptr->name = malloc(max_string_len);

                if (!record_ptr->name) {
                    // Handle memory allocation failure for string
                    continue;
                }
                snprintf(record_ptr->name, max_string_len, "Record_%lld", (long long)(++total_records_allocated));
            } else {
                record *evicted_record = cache->head ? cache->head->data : malloc(sizeof(record));
                if (!evicted_record) goto cleanup;

                free(evicted_record->name);
                evicted_record->value = rand() % max_range;
                evicted_record->name = malloc(max_string_len);

                if (!evicted_record->name) {
                    // Handle memory allocation failure for string
                    continue;
                }
                snprintf(evicted_record->name, max_string_len, "Record_%lld", (long long)(++total_records_allocated));

                cache_put(cache, evicted_record);
            }

            records_array[i][j] = *record_ptr;

            if (!cache->head || strcmp(record_ptr->name, cache->tail->data->name) != 0) {
                cache_put(cache, record_ptr);
            }
        }
    }

cleanup:
    cJSON_Delete(json);

    // Free allocated resources in case of failure
    free(offsets);
    free(keys);
    for (int i = 0; i < array_keys_count && records_array[i]; ++i) {
        for (size_t j = 0; j < keys[i] && records_array[i][j].name; ++j) {
            free(records_array[i][j].name);
        }
        free(records_array[i]);
    }

    if (records_array) free(records_array);

    // Free the cache
    while (cache->head) lru_cache_evict(cache);
    free(cache);

    return records_array;
}

void log_allocation(size_t size, const char *location) {
    printf("Allocated %zu bytes at %s\n", size, location);
}

