item** allocate_and_initialize_items(size_t num_items, size_t num_descriptions, const char** descriptions, double min_value, double max_value) {
    if (num_items == 0 || num_descriptions == 0 || descriptions == NULL)
        return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    item** items = malloc(num_items * sizeof(item*));
    if (!items)
        return NULL;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_items; ++i) {
        item* new_item = malloc(sizeof(item));
        if (!new_item) {
            // Cleanup previously allocated items
            while (i > 0) {
                free(items[--i]);
            }
            free(items);
            return NULL;
        }

        pthread_mutex_lock(&lock);
        double random_value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
        int desc_index = rand() % num_descriptions;
        new_item->value = random_value;
        new_item->description = strdup(descriptions[desc_index]);
        pthread_mutex_unlock(&lock);

        if (!new_item->description) {
            free(new_item);
            while (--i >= 0)
                free(items[i]);
            free(items);
            return NULL;
        }

        items[i] = new_item;
    }

    return items;
}

void free_items(item** items, size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
        if (items[i]) {
            free(items[i]->description);
            free(items[i]);
        }
    }
