#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    double value;
    char identifier;
    char *name; // Null-terminated string
    struct Record *next;
} Record;

typedef struct RecordManager {
    Record *head;
    size_t count;
    pthread_mutex_t lock;
    unsigned int used_keys[1024]; // Assuming a maximum of 1024 keys
    double min_double_value, max_double_value; // Range for unique doubles
} RecordManager;

double generate_unique_random(double min, double max, size_t *unique_values, size_t count) {
    while (1) {
        double value = min + ((max - min) * rand() / (RAND_MAX + 1.0));
        int is_unique = 1;
        for (size_t i = 0; i < count; i++) {
            if (unique_values[i] == value) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            unique_values[count++] = value;
            return value;
        }
    }
}

void init_random_generator() {
    srand((unsigned int)time(NULL));
}

int read_and_validate_int(int *key, int min_range, int max_range) {
    char input[32];
    while (1) {
        printf("Enter an integer (%d-%d): ", min_range, max_range);
        if (!fgets(input, sizeof(input), stdin)) return -1;
        char *endptr;
        long val = strtol(input, &endptr, 10);
        if (*endptr == '\n' && endptr != input && val >= min_range && val <= max_range) {
            *key = (int)val;
            return 0;
        } else {
            fprintf(stderr, "Invalid input. Please enter a valid integer.\n");
        }
    }
}

void free_records(Record *head) {
    Record *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->name);
        free(temp);
    }
}

void dynamicRecordManager(int initial_count, int keys[], long offsets[], char identifier, 
                          double min_double_value, double max_double_value,
                          int key_min_range, int key_max_range) {

    RecordManager manager = {0};
    pthread_mutex_init(&manager.lock, NULL);

    size_t unique_doubles[1024];
    memset(unique_doubles, 0, sizeof(unique_doubles));
    manager.min_double_value = min_double_value;
    manager.max_double_value = max_double_value;

    init_random_generator();

    for (int i = 0; i < initial_count; ++i) {
        pthread_mutex_lock(&manager.lock);

        if (!keys[i] || manager.used_keys[keys[i]]) {
            pthread_mutex_unlock(&manager.lock);
            continue;
        }

        Record *new_record = malloc(sizeof(Record));
        if (new_record == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            pthread_mutex_unlock(&manager.lock);
            free_records(manager.head);
            exit(EXIT_FAILURE);
        }

        new_record->offset = offsets[i];
        new_record->key = keys[i];
        new_record->value = generate_unique_random(min_double_value, max_double_value,
                                                   unique_doubles, manager.count);
        new_record->identifier = identifier;
        new_record->name = strdup("");
        new_record->next = manager.head;

        manager.used_keys[keys[i]] = 1;
        ++manager.count;

        manager.head = new_record;
        pthread_mutex_unlock(&manager.lock);
    }

    // Read integers from standard input
    int key;
    while (read_and_validate_int(&key, key_min_range, key_max_range) == 0) {
        if (!manager.used_keys[key]) {
            Record *new_record = malloc(sizeof(Record));
            if (new_record == NULL) {
                fprintf(stderr, "Memory allocation failed.\n");
                free_records(manager.head);
                exit(EXIT_FAILURE);
            }

            pthread_mutex_lock(&manager.lock);

            new_record->offset = offsets[manager.count];
            new_record->key = key;
            new_record->value = generate_unique_random(min_double_value, max_double_value,
                                                       unique_doubles, manager.count);
            new_record->identifier = identifier;
            new_record->name = strdup("");
            new_record->next = manager.head;

            manager.used_keys[key] = 1;
            ++manager.count;

            manager.head = new_record;

            pthread_mutex_unlock(&manager.lock);
        } else {
            fprintf(stderr, "Duplicate key %d. Skipping.\n", key);
        }
    }

    free_records(manager.head);

    pthread_mutex_destroy(&manager.lock);
}
