#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PROFILES 10000
#define MAX_FRIEDNS_PER_PROFILE 1000
#define MAX_CACHE_SIZE 1024

typedef struct {
    int record_value;
    char *record_string;
} Record;

typedef struct {
    int id;
    char username[50];
    int friend_ids[MAX_FRIEDNS_PER_PROFILE];
    size_t num_friends;
} UserProfile;

typedef struct CacheNode {
    int key;
    void *value;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t capacity;
    CacheNode **hash_table;
    size_t hash_capacity;
    pthread_mutex_t lock;
} LRUCache;

// Error logging
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Dynamic memory allocation with error handling
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

LRUCache* create_cache(size_t capacity, size_t hash_capacity) {
    LRUCache *cache = safe_malloc(sizeof(LRUCACHE));
    cache->head = NULL;
    cache->tail = NULL;
    cache->capacity = capacity;
    cache->hash_table = safe_malloc(hash_capacity * sizeof(CacheNode*));
    memset(cache->hash_table, 0, hash_capacity * sizeof(CacheNode*));
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void free_cache_node(LRUCache *cache, CacheNode *node) {
    if (node->value) {
        free(node->value); // Assume value is dynamically allocated
    }
    free(node);
}

int hash_function(int key, size_t capacity) {
    return key % capacity;
}

void cache_put(LRUCache *cache, int key, void *value) {
    pthread_mutex_lock(&cache->lock);

    CacheNode **bucket = &cache->hash_table[hash_function(key, cache->hash_capacity)];
    CacheNode *node = *bucket;

    while (node) {
        if (node->key == key) {
            node->value = value;
            // Move to front of LRU list
            if (node != cache->head) {
                if (node->next) node->next->prev = node->prev;
                if (node->prev) node->prev->next = node->next;

                node->next = cache->head;
                node->prev = NULL;
                cache->head->prev = node;
                cache->head = node;
            }
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        node = node->next;
    }

    CacheNode *new_node = safe_malloc(sizeof(CacheNode));
    new_node->key = key;
    new_node->value = value;

    if (cache->capacity == 0) {
        // Evict LRU
        *bucket = cache->head->next;
        if (cache->tail != cache->head) cache->tail->next = NULL;
        free_cache_node(cache, cache->head);
        cache->head = *bucket;
    } else {
        new_node->next = cache->head;
        new_node->prev = NULL;
        if (cache->head) cache->head->prev = new_node;
        cache->head = new_node;

        if (!*bucket) *bucket = new_node;
    }

    pthread_mutex_unlock(&cache->lock);
}

void* cache_get(LRUCache *cache, int key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode **bucket = &cache->hash_table[hash_function(key, cache->hash_capacity)];
    CacheNode *node = *bucket;

    while (node) {
        if (node->key == key) {
            if (node != cache->head) { // Move to front of LRU list
                if (node->next) node->next->prev = node->prev;
                if (node->prev) node->prev->next = node->next;

                node->next = cache->head;
                node->prev = NULL;
                cache->head->prev = node;
                cache->head = node;
            }
            pthread_mutex_unlock(&cache->lock);
            return node->value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void destroy_cache(LRUCache *cache) {
    CacheNode *node = cache->head;

    while (node) {
        CacheNode *temp = node;
        node = node->next;
        free_cache_node(cache, temp);
    }

    free(cache->hash_table);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void* user_profiles[MAX_PROFILES];
pthread_mutex_t profiles_lock;

// User profile management
UserProfile* create_user_profile(int id, const char *username) {
    UserProfile *profile = safe_malloc(sizeof(UserProfile));
    profile->id = id;
    strncpy(profile->username, username, sizeof(profile->username) - 1);
    profile->num_friends = 0;
    return profile;
}

void free_user_profile(UserProfile *profile) {
    if (profile->friend_ids) {
        free(profile->friend_ids);
    }
    free(profile);
}

UserProfile* get_user_profile(int id) {
    pthread_mutex_lock(&profiles_lock);

    for (int i = 0; i < MAX_PROFILES; ++i) {
        if (user_profiles[i] && user_profiles[i]->id == id) {
            pthread_mutex_unlock(&profiles_lock);
            return user_profiles[i];
        }
    }

    pthread_mutex_unlock(&profiles_lock);
    return NULL;
}

void add_user_profile(UserProfile *profile) {
    pthread_mutex_lock(&profiles_lock);

    for (int i = 0; i < MAX_PROFILES; ++i) {
        if (!user_profiles[i]) {
            user_profiles[i] = profile;
            break;
        }
    }

    pthread_mutex_unlock(&profiles_lock);
}

void remove_user_profile(int id) {
    pthread_mutex_lock(&profiles_lock);

    for (int i = 0; i < MAX_PROFILES; ++i) {
        if (user_profiles[i] && user_profiles[i]->id == id) {
            free_user_profile(user_profiles[i]);
            user_profiles[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&profiles_lock);
}

int main() {
    LRUCache *cache = create_cache(MAX_CACHE_SIZE, 256);

    UserProfile *profile1 = create_user_profile(1, "user1");
    add_user_profile(profile1);

    int record_value = 42;
    char *record_string = strdup("example");

    Record record = { .record_value = record_value, .record_string = record_string };

    cache_put(cache, profile1->id, &record);

    void *cached_record = cache_get(cache, profile1->id);
    if (cached_record) {
        Record *retrieved_record = (Record *) cached_record;
        printf("Retrieved record value: %d\n", retrieved_record->record_value);
        free(retrieved_record->record_string); // Clean up
    }

    remove_user_profile(profile1->id);
    destroy_cache(cache);

    return 0;
}
