#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define MAX_OFFSET_SIZE 10000
#define OFFSET_MASK 0xFFFF
#define RANDOM_RANGE_MAX 100

typedef struct {
    int field1;
    int field2;
} record;

void* memory_pool = NULL;

long generate_random(long min, long max) {
    return min + rand() % (max - min + 1);
}

int allocate_memory_pool(size_t num_records) {
    size_t record_size = sizeof(record);
    if (memory_pool != NULL) {
        free(memory_pool);
    }
    memory_pool = malloc(num_records * record_size);
    if (!memory_pool) {
        return -1;
    }
    return 0;
}

void initialize_random() {
    srand((unsigned int)time(NULL));
}

record* create_records(int num_records, long* offsets, size_t offset_size) {
    if (offset_size > MAX_OFFSET_SIZE || num_records <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    if (allocate_memory_pool(num_records)) {
        fprintf(stderr, "Memory allocation failed for records pool.\n");
        return NULL;
    }

    int* keys = malloc(offset_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        free(memory_pool);
        memory_pool = NULL;
        return NULL;
    }

    for (size_t i = 0; i < offset_size; ++i) {
        keys[i] = offsets[i] & OFFSET_MASK;
    }

    record* records = (record*)memory_pool;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    #pragma omp parallel for
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);

        records[i].field1 = generate_random(1, RANDOM_RANGE_MAX);
        records[i].field2 = generate_random(1, RANDOM_RANGE_MAX);

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    free(keys);
    return records;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <num_offsets> <num_records>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_offsets = atoi(argv[1]);
    int num_records = atoi(argv[2]);

    if (num_offsets <= 0 || num_records <= 0) {
        fprintf(stderr, "Invalid numbers for offsets or records.\n");
        return EXIT_FAILURE;
    }

    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array.\n");
        return EXIT_FAILURE;
    }

    initialize_random();

    #pragma omp parallel for
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = generate_random(1, OFFSET_MASK);
    }

    record* records = create_records(num_records, offsets, num_offsets);

    if (!records) {
        fprintf(stderr, "Failed to create records.\n");
        free(offsets);
        return EXIT_FAILURE;
    }

    // Output some of the data for verification
    printf("Sample Records:\n");
    for (int i = 0; i < num_records && i < 10; ++i) {
        printf("Record %d: {field1=%d, field2=%d}\n", i, records[i].field1, records[i].field2);
    }

    free(offsets);

    return EXIT_SUCCESS;
}
