#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} record;

// Define a memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    void *memory;
    size_t total_blocks;
    size_t used_blocks;
} MemoryPool;

// Function to initialize the memory pool
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->used_blocks = 0;

    pool->memory = malloc(block_size * num_blocks);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    return pool;
}

// Function to allocate memory from the pool
void* pool_alloc(MemoryPool *pool, size_t size) {
    if (size > pool->block_size || pool->used_blocks >= pool->total_blocks)
        return NULL;

    void *ptr = (char*)pool->memory + (pool->used_blocks * pool->block_size);
    pool->used_blocks++;
    return ptr;
}

// Function to free the memory pool
void destroy_memory_pool(MemoryPool *pool) {
    if (!pool) return;
    free(pool->memory);
    free(pool);
}

// Function to initialize an array of records using a custom memory pool
record* init_records_array(size_t num_records, MemoryPool **pool_out) {
    size_t block_size = sizeof(record);
    *pool_out = create_memory_pool(block_size, num_records);
    if (!(*pool_out)) return NULL;

    record *records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        destroy_memory_pool(*pool_out);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = *((long*)pool_alloc(*pool_out, block_size));
        records[i].key = *((int*)((char*)records[i].offset + sizeof(long)));
    }

    return records;
}

// Function to serialize the record data into binary format
size_t serialize_records(const record *records, size_t num_records, unsigned char **out_data) {
    size_t total_size = num_records * (sizeof(long) + sizeof(int));
    *out_data = (unsigned char*)malloc(total_size);
    if (!(*out_data)) return 0;

    unsigned char *ptr = *out_data;
    for (size_t i = 0; i < num_records; ++i) {
        memcpy(ptr, &(records[i].offset), sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &(records[i].key), sizeof(int));
        ptr += sizeof(int);
    }

    return total_size;
}

// Function to deserialize the binary data back into an array of records
record* deserialize_records(const unsigned char *data, size_t num_records, size_t *out_size) {
    *out_size = num_records * (sizeof(long) + sizeof(int));
    record *records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    const unsigned char *ptr = data;
    for (size_t i = 0; i < num_records; ++i) {
        memcpy(&(records[i].offset), ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&(records[i].key), ptr, sizeof(int));
        ptr += sizeof(int);
    }

    return records;
}

// Example usage
int main() {
    size_t num_records = 10;
    MemoryPool *pool = NULL;

    record *records = init_records_array(num_records, &pool);
    if (!records) {
        printf("Failed to initialize records array.\n");
        return EXIT_FAILURE;
    }

    unsigned char *serialized_data;
    size_t serialized_size = serialize_records(records, num_records, &serialized_data);

    // Assume processing with serialized data here

    record *deserialized_records = deserialize_records(serialized_data, num_records, &serialized_size);
    if (!deserialized_records) {
        printf("Failed to deserialize records.\n");
        free(serialized_data);
        destroy_memory_pool(pool);
        free(records);
        return EXIT_FAILURE;
    }

    // Clean up
    free(serialized_data);
    free(deserialized_records);
    destroy_memory_pool(pool);
    free(records);

    return EXIT_SUCCESS;
}
```

### Explanation:

- **Memory Pool**: A custom memory pool is implemented to manage allocations efficiently and minimize fragmentation.

- **Error Handling**: The code checks for allocation failures at each step and ensures all resources are freed in case of an error.

- **Serialization/Deserialization**: Functions are provided to convert the array of records into a binary format and back, ensuring data can be stored and retrieved efficiently.

- **Scalability and Usability**: The design supports adding more records easily and is straightforward to use with clear examples.']

