    printf("Enter integers (end with non-integer): ");
    while (scanf("%d", &numbers[count]) == 1) {
        if (++count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) return NULL;
