#define MAX_ITEMS 10000

typedef struct {
    double value;
    char* description;
    int priority;
} item;

// Predefined list of descriptions.
const char* descriptions[] = {"Alpha", "Beta", "Gamma", "Delta", "Epsilon"};

// Error codes
enum { SUCCESS, ALLOCATION_ERROR, TRANSFORMATION_ERROR };

// Custom transformation function prototype.
typedef enum { SUCCESS, FAILURE } (*transform_function_t)(item*, int);

// Function to initialize items with random values and descriptions.
int init_items(item** items, int* indices, size_t num_items, double range_min, double range_max,
               transform_function_t transform) {
    if (items == NULL || indices == NULL || num_items <= 0)
        return ALLOCATION_ERROR;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_items; ++i) {
        // Allocate memory for each item.
        items[i] = (item*)malloc(sizeof(item));
        if (items[i] == NULL) {
            fprintf(stderr, "Memory allocation failed at index %zu.\n", i);
            return ALLOCATION_ERROR;
        }

        // Initialize random value within range.
        double random_value = ((double)rand() / RAND_MAX) * (range_max - range_min) + range_min;

        // Randomly select a description from the list.
        const char* random_description = descriptions[rand() % (sizeof(descriptions) / sizeof(*descriptions))];

        // Set priority level based on index, ensuring it's within a reasonable limit.
        int priority_level = indices[i] % 10; 

        pthread_mutex_lock(&mutex);

        items[i]->value = random_value;
        items[i]->description = strdup(random_description);
        items[i]->priority = priority_level;

        // Apply custom transformation function if provided.
        if (transform != NULL) {
            int transform_result = transform(items[i], indices[i]);
            if (transform_result == FAILURE) {
                fprintf(stderr, "Transformation failed for item at index %zu.\n", i);
                pthread_mutex_unlock(&mutex);
                free(items[i]->description);
                free(items[i]);
                return TRANSFORMATION_ERROR;
            }
        }

        pthread_mutex_unlock(&mutex);

        // Check if any allocation or transformation failed.
        if (items[i]->description == NULL || items[i]->value != random_value || items[i]->priority != priority_level) {
            fprintf(stderr, "Initialization error for item at index %zu.\n", i);
            free(items[i]->description);
            free(items[i]);
            return ALLOCATION_ERROR;
        }
    }

    pthread_mutex_destroy(&mutex);
    return SUCCESS;
}

// Example transformation function
int example_transform(item* itm, int idx) {
    if (itm == NULL) return FAILURE;

    // Example transformation: Increment priority by 1
    itm->priority += 1;
    return SUCCESS;
}
```

