    // Allocate memory for 'long' offset values and 'int' keys
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize offset values and keys
    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }
    for (long j = 0; j < num_keys; ++j) {
        keys[j] = j;
    }

    // Allocate memory for array of 'record' structures
    record *records = (record *)malloc(num_records * sizeof(record));

    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Set each record's int field to a random value within the given range
    srand(time(NULL));
    for (long k = 0; k < num_records; ++k) {
        records[k].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Clean up (example only, in real usage you would pass these pointers to other functions)
