#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define NUM_NODES 100
#define FLOAT_RANGE_MIN 0.0
#define FLOAT_RANGE_MAX 1.0
#define STRING_LENGTH 8

typedef struct node {
    double value;
    struct node *next;
} Node;

struct dynamic_data {
    Node **node_array;
    double *float_array;
    char **string_array;
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_random() {
    srand(time(NULL));
}

double random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

char* generate_unique_string(char **existing_strings, int count) {
    char *str = malloc(STRING_LENGTH + 1);
    do {
        for (int i = 0; i < STRING_LENGTH; ++i) {
            str[i] = rand() % 36 < 10 ? '0' + rand() % 10 : 'a' + rand() % 26;
        }
        str[STRING_LENGTH] = '\0';
    } while (check_string_exists(str, existing_strings, count));
    return str;
}

int check_string_exists(const char *str, const char **existing_strings, int count) {
    for (int i = 0; i < count; ++i) {
        if (strcmp(existing_strings[i], str) == 0) {
            free((char *)str);
            return 1;
        }
    }
    return 0;
}

void initialize_structure(struct dynamic_data *data, int num_nodes) {
    pthread_mutex_lock(&mutex);

    data->node_array = malloc(num_nodes * sizeof(Node *));
    data->float_array = malloc(num_nodes * sizeof(double));
    data->string_array = malloc(num_nodes * sizeof(char *));

    if (!data->node_array || !data->float_array || !data->string_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_nodes; ++i) {
        data->float_array[i] = random_double(FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);

        char *str = generate_unique_string(data->string_array, i);
        if (!str) {
            fprintf(stderr, "Failed to generate unique string\n");
            exit(EXIT_FAILURE);
        }
        data->string_array[i] = str;

        data->node_array[i] = malloc(sizeof(Node));
        if (!data->node_array[i]) {
            fprintf(stderr, "Memory allocation failed for node array\n");
            exit(EXIT_FAILURE);
        }

        data->node_array[i]->value = random_double(FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);
        data->node_array[i]->next = (i + 1 < num_nodes) ? data->node_array[i + 1] : NULL;
    }

    pthread_mutex_unlock(&mutex);
}

void free_structure(struct dynamic_data *data, int num_nodes) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_nodes; ++i) {
        if (data->string_array[i]) {
            free(data->string_array[i]);
        }
        if (data->node_array[i]) {
            free(data->node_array[i]);
        }
    }

    free(data->string_array);
    free(data->float_array);
    free(data->node_array);

    pthread_mutex_unlock(&mutex);
}

void traverse_and_print(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("Node value: %f\n", current->value);
        current = current->next;
    }
}

int main() {
    struct dynamic_data data;
    initialize_structure(&data, NUM_NODES);

    traverse_and_print(data.node_array[0]);

    free_structure(&data, NUM_NODES);

    return 0;
}
```']

['Below is a simplified implementation of the described requirements in C. This code uses a hash table with pthreads for thread safety and integrates zlib for optional compression. Note that this example focuses on core functionalities and does not cover every detail such as logging, caching, or extensive error handling.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "zlib.h"

#define INITIAL_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct {
    int key;
    long offset;
    char identifier;
    size_t index;
} Record;

typedef struct Node {
    int key;
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    int compress_mode;
} HashTable;

// Function prototypes
HashTable* create_table(int compress_mode);
int hash_function(int key, size_t size);
Node* create_node(int key, Record record);
void insert_record(HashTable* table, int key, long offset, char identifier, size_t index);
Record* find_record(HashTable* table, int key);
void delete_record(HashTable* table, int key);
void resize_table(HashTable* table);
void compress_data(z_stream* strm, const void* data, size_t length, unsigned char** output);
void decompress_data(z_stream* strm, const unsigned char* input, size_t length, unsigned char** output);

// Create a new hash table
HashTable* create_table(int compress_mode) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = INITIAL_SIZE;
    table->count = 0;
    table->buckets = (Node**)calloc(table->size, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);
    table->compress_mode = compress_mode;
    return table;
}

// Hash function
int hash_function(int key, size_t size) {
    return key % size;
}

// Create a new node
Node* create_node(int key, Record record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->record = record;
    node->next = NULL;
    return node;
}

// Insert a record into the hash table
void insert_record(HashTable* table, int key, long offset, char identifier, size_t index) {
    pthread_mutex_lock(&table->lock);

    if ((float)table->count / (float)table->size > LOAD_FACTOR) {
        resize_table(table);
    }

    Record record = {offset, identifier, index};
    Node* node = create_node(key, record);
    int hash_index = hash_function(key, table->size);

    node->next = table->buckets[hash_index];
    table->buckets[hash_index] = node;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}

// Find a record by key
Record* find_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    int hash_index = hash_function(key, table->size);
    Node* current = table->buckets[hash_index];

    while (current != NULL) {
        if (current->key == key) {
            Record* record = &current->record;
            pthread_mutex_unlock(&table->lock);
            return record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Delete a record by key
void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    int hash_index = hash_function(key, table->size);
    Node* current = table->buckets[hash_index];
    Node* prev = NULL;

    while (current != NULL) {
        if (current->key == key) {
            if (prev == NULL) {
                table->buckets[hash_index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            table->count--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
}

// Resize the hash table
void resize_table(HashTable* table) {
    size_t new_size = 2 * table->size;
    Node** new_buckets = (Node**)calloc(new_size, sizeof(Node*));

    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            int hash_index = hash_function(current->key, new_size);
            Node* next_node = current->next;
            current->next = new_buckets[hash_index];
            new_buckets[hash_index] = current;
            current = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

// Compress data using zlib
void compress_data(z_stream* strm, const void* data, size_t length, unsigned char** output) {
    strm->next_in = (Bytef*)data;
    strm->avail_in = length;

    int ret;
    unsigned have;
    unsigned char buffer[1024];

    *output = NULL;
    do {
        strm->next_out = buffer;
        strm->avail_out = sizeof(buffer);
        ret = deflate(strm, Z_FINISH);

        if (have = 1024 - strm->avail_out) {
            *output = (unsigned char*)realloc(*output, have + (*output ? strlen((char*)*output) : 0));
            memcpy(*output + strlen((char*)*output), buffer, have);
        }
    } while (ret == Z_OK);

    deflateEnd(strm);
}

// Decompress data using zlib
void decompress_data(z_stream* strm, const unsigned char* input, size_t length, unsigned char** output) {
    strm->next_in = (Bytef*)input;
    strm->avail_in = length;

    int ret;
    unsigned have;
    unsigned char buffer[1024];

    *output = NULL;
    do {
        strm->next_out = buffer;
        strm->avail_out = sizeof(buffer);
        ret = inflate(strm, Z_NO_FLUSH);

        if (have = 1024 - strm->avail_out) {
            *output = (unsigned char*)realloc(*output, have + (*output ? strlen((char*)*output) : 0));
            memcpy(*output + strlen((char*)*output), buffer, have);
        }
    } while (ret == Z_OK);

    inflateEnd(strm);
}

// Main function for testing
int main() {
    HashTable* table = create_table(1); // Enable compression

    insert_record(table, 1, 1000, 'A', 10);
    Record* record = find_record(table, 1);
    if (record) {
        printf("Found record: %ld, %c, %zu\n", record->offset, record->identifier, record->index);
    }

    delete_record(table, 1);

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);

    return 0;
}
```

This code provides a basic implementation of the specified requirements. It includes thread-safe operations using mutexes and optional data compression with zlib. Further enhancements like logging, caching, and extensive testing would be needed for a production-ready system.']

