log_pipeline* create_log_pipeline(size_t num_records, int min_value, int max_value) {
    log_pipeline *pipeline = safe_malloc(sizeof(log_pipeline));
    pipeline->capacity = num_records;
    pipeline->count = 0;

    // Allocate memory for offsets and keys
    pipeline->offsets = safe_malloc(num_records * sizeof(long));
    pipeline->keys = safe_malloc(num_records * sizeof(int));

    // Initialize offsets and keys with a pattern
    for (size_t i = 0; i < num_records; ++i) {
        pipeline->offsets[i] = i * 10;
        pipeline->keys[i] = i % 256;
    }

    // Allocate memory for records array
    pipeline->records = safe_malloc(num_records * sizeof(record*));
    for (size_t i = 0; i < num_records; ++i) {
        pipeline->records[i] = safe_malloc(sizeof(record));
        pipeline->records[i]->value = min_value + rand() % (max_value - min_value + 1);
        pipeline->records[i]->offset = &pipeline->offsets[i];
        pipeline->records[i]->key = &pipeline->keys[i];
    }

    pthread_mutex_init(&pipeline->lock, NULL);

    return pipeline;
}

void compact_records(log_pipeline *pipeline) {
    size_t new_count = 0;
    for (size_t i = 0; i < pipeline->count; ++i) {
        if (pipeline->records[i] && pipeline->records[i]->value != 0) { // Assume empty records have value 0
            pipeline->records[new_count++] = pipeline->records[i];
        } else {
            free(pipeline->records[i]);
        }
    }
    pipeline->count = new_count;
}

record* get_record(log_pipeline *pipeline, size_t index) {
    pthread_mutex_lock(&pipeline->lock);
    if (index < pipeline->count) {
        record *res = pipeline->records[index];
        pthread_mutex_unlock(&pipeline->lock);
        return res;
    }
    pthread_mutex_unlock(&pipeline->lock);
    return NULL; // Or handle error appropriately
}

void iterate_records(log_pipeline *pipeline, void (*callback)(record *)) {
    pthread_mutex_lock(&pipeline->lock);
    for (size_t i = 0; i < pipeline->count; ++i) {
        callback(pipeline->records[i]);
    }
    pthread_mutex_unlock(&pipeline->lock);
}

