// Define video_frame structure
typedef struct {
    unsigned char *buffer;
    int frame_rate;
    int *timestamp;
} video_frame;

// Cache for frequently accessed frames
#define CACHE_SIZE 10

typedef struct {
    video_frame **cache;
    size_t cache_size;
    size_t head;
    pthread_rwlock_t lock;
} frame_cache;

// Function to initialize the frame cache
void init_frame_cache(frame_cache *fc) {
    fc->cache = (video_frame **)malloc(CACHE_SIZE * sizeof(video_frame *));
    if (!fc->cache) {
        fprintf(stderr, "Failed to allocate memory for frame cache.\n");
        exit(EXIT_FAILURE);
    }
    memset(fc->cache, 0, CACHE_SIZE * sizeof(video_frame *));
    fc->cache_size = CACHE_SIZE;
    fc->head = 0;
    pthread_rwlock_init(&fc->lock, NULL);
}

// Function to free the frame cache
void free_frame_cache(frame_cache *fc) {
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (fc->cache[i]) {
            free(fc->cache[i]->buffer);
            free(fc->cache[i]);
        }
    }
    free(fc->cache);
    pthread_rwlock_destroy(&fc->lock);
}

// Function to manage memory for video transcoding pipeline
void manage_video_memory(size_t num_frames, size_t resolution_width, size_t resolution_height,
                         unsigned int bitrate, int initial_frame_rate, frame_cache *frame_cache) {

    // Calculate buffer sizes based on resolution and bitrate
    size_t buffer_size = (resolution_width * resolution_height * 3) / 2; // Assuming YUV420 format

    video_frame **frames = (video_frame **)malloc(num_frames * sizeof(video_frame *));
    if (!frames) {
        fprintf(stderr, "Failed to allocate memory for frames.\n");
        exit(EXIT_FAILURE);
    }

    int initial_timestamp = 0;

    for (size_t i = 0; i < num_frames; ++i) {
        video_frame *frame = (video_frame *)malloc(sizeof(video_frame));
        if (!frame) {
            fprintf(stderr, "Failed to allocate memory for frame %zu.\n", i);
            continue;
        }

        // Allocate buffer
        frame->buffer = (unsigned char *)malloc(buffer_size);
        if (!frame->buffer) {
            fprintf(stderr, "Failed to allocate buffer for frame %zu.\n", i);
            free(frame);
            continue;
        }

        // Set frame rate and timestamp
        frame->frame_rate = initial_frame_rate;
        int *timestamp = (int *)malloc(sizeof(int));
        if (!timestamp) {
            fprintf(stderr, "Failed to allocate memory for timestamp of frame %zu.\n", i);
            free(frame->buffer);
            free(frame);
            continue;
        }
        *timestamp = initial_timestamp;

        // Assign timestamp pointer
        frame->timestamp = timestamp;

        // Store frame in array
        frames[i] = frame;

        // Initialize cache with first few frames
        if (i < CACHE_SIZE) {
            pthread_rwlock_wrlock(&frame_cache->lock);
            frame_cache->cache[frame_cache->head] = frame;
            frame_cache->head = (frame_cache->head + 1) % CACHE_SIZE;
            pthread_rwlock_unlock(&frame_cache->lock);
        }

        initial_timestamp += 40; // Assuming 25 fps for simplicity, adjust as needed
    }

    // Function to retrieve a specific frame by its index
    video_frame* get_frame_by_index(size_t index) {
        if (index >= num_frames) return NULL;

        pthread_rwlock_rdlock(&frame_cache->lock);
        size_t cache_index = (frame_cache->head + CACHE_SIZE - 1 - (index % CACHE_SIZE)) % CACHE_SIZE;

        video_frame *cached_frame = frame_cache->cache[cache_index];
        if (cached_frame && cached_frame->timestamp == frames[index]->timestamp) {
            pthread_rwlock_unlock(&frame_cache->lock);
            return cached_frame;
        }

        pthread_rwlock_unlock(&frame_cache->lock);

        // Return original frame if not found in cache
        return frames[index];
    }

    // Function to iterate over the frames forward
    void iterate_frames_forward() {
        for (size_t i = 0; i < num_frames; ++i) {
            video_frame *frame = get_frame_by_index(i);
            if (frame) {
                printf("Frame %zu: Timestamp = %d, Frame Rate = %d\n", i, *frame->timestamp, frame->frame_rate);
            }
        }
    }

    // Function to iterate over the frames backward
    void iterate_frames_backward() {
        for (size_t i = 0; i < num_frames; ++i) {
            video_frame *frame = get_frame_by_index(num_frames - 1 - i);
            if (frame) {
                printf("Frame %zu: Timestamp = %d, Frame Rate = %d\n", num_frames - 1 - i, *frame->timestamp, frame->frame_rate);
            }
        }
    }

    // Free allocated frames
    for (size_t i = 0; i < num_frames; ++i) {
        if (frames[i]) {
            free(frames[i]->buffer);
            free(frames[i]->timestamp);
            free(frames[i]);
        }
    }
    free(frames);

}

// Example usage
int main() {
    frame_cache cache;
    init_frame_cache(&cache);

    manage_video_memory(100, 1920, 1080, 5000000, 30, &cache);

    free_frame_cache(&cache);
    return 0;
}
