#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    int number;
    char *identifier;
} data_entry;

int initialize_data_structures(const char *filename, 
                               const char **string_identifiers, 
                               size_t num_identifiers,
                               double **floats, 
                               char ***chars, 
                               data_entry ***entries) {

    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Buffers for reading lines
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        fclose(file);
        perror("Failed to allocate memory for buffer");
        return -1;
    }

    // Dynamic arrays initialization
    size_t floats_count = 0, chars_count = 0, entries_count = 0;

    while (fgets(buffer, buffer_size, file)) {
        char *line = buffer;

        if (sscanf(line, "FLOAT %lf", &(*floats)[floats_count]) == 1) {
            floats_count++;
        } else if (sscanf(line, "CHAR %c", (*chars)[chars_count]) == 1) {
            chars_count++;
        } else if (sscanf(line, "ENTRY %lf %d %zu", 
                          &(*entries)[entries_count].value,
                          &(*entries)[entries_count].number,
                          &index) == 3 && index < num_identifiers) {
            (*entries)[entries_count].identifier = strdup(string_identifiers[index]);
            entries_count++;
        } else {
            fprintf(stderr, "Invalid line format: %s", line);
        }
    }

    // Reallocate memory for exact sizes
    *floats = realloc(*floats, floats_count * sizeof(double));
    *chars = realloc(*chars, chars_count * sizeof(char*));
    *entries = realloc(*entries, entries_count * sizeof(data_entry));

    free(buffer);
    fclose(file);

    return 0;
}

void cleanup_data_structures(double *floats,
                             char **chars,
                             data_entry **entries,
                             size_t floats_count,
                             size_t chars_count,
                             size_t entries_count) {
    free(floats);

    for (size_t i = 0; i < chars_count; ++i) {
        free(chars[i]);
    }
    free(chars);

    for (size_t i = 0; i < entries_count; ++i) {
        free((*entries)[i].identifier);
    }
    free(*entries);
}

int main() {
    const char *string_identifiers[] = {"id1", "id2", "id3"};
    size_t num_identifiers = sizeof(string_identifiers) / sizeof(char*);

    double *floats = NULL;
    char **chars = NULL;
    data_entry *entries = NULL;

    if (initialize_data_structures("config.txt", string_identifiers, 
                                   num_identifiers, &floats, &chars, &entries) != 0) {
        fprintf(stderr, "Failed to initialize data structures\n");
        return EXIT_FAILURE;
    }

    // Use floats, chars, and entries...

    cleanup_data_structures(floats, chars, &entries,
                            sizeof(floats) / sizeof(double),
                            sizeof(chars) / sizeof(char*),
                            sizeof(entries) / sizeof(data_entry));

    return 0;
}
