#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structures used in the memory management task.
typedef struct node {
    double value;
    struct node* next;
} node;

typedef struct tagMetadata {
    char* name;
    int id;
} tagMetadata;

// Function prototypes
void* allocateMemory(int numNodes, int numValues, int numIndices);
void deallocateMemory(void* data);
void populateData(void* data, int numNodes, int numValues, int minVal, int maxVal, int strLen);
double calculateAverage(double* values, int size);
void traverseAndPrint(node** nodeList, int nodeCount);
void logError(const char* errorMessage);

// Memory management function
void* allocateMemory(int numNodes, int numValues, int numIndices) {
    if (numIndices > numValues || numNodes < 0 || numValues < 0 || numIndices < 0) {
        logError("Invalid input sizes.");
        return NULL;
    }

    size_t nodeArraySize = numNodes * sizeof(node*);
    size_t valuesArraySize = numValues * sizeof(double);
    size_t indicesArraySize = numIndices * sizeof(int);

    void* mainMemoryBlock = malloc(nodeArraySize + valuesArraySize + indicesArraySize);
    if (!mainMemoryBlock) {
        logError("Failed to allocate memory.");
        return NULL;
    }

    node** nodeList = (node**)mainMemoryBlock;
    double* values = (double*)(nodeList + numNodes);
    int* indices = (int*)(values + numValues);

    for (int i = 0; i < numNodes; ++i) {
        nodeList[i] = NULL;
    }

    return mainMemoryBlock;
}

void deallocateMemory(void* data) {
    if (!data) return;

    free(data);
}

void populateData(void* memory, int numNodes, int numValues, int minVal, int maxVal, int strLen) {
    if (!memory) {
        logError("Null pointer provided for data population.");
        return;
    }

    node** nodeList = (node**)memory;
    double* values = (double*)(nodeList + numNodes);
    char alphabet[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    // Populate nodes
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numNodes; ++i) {
        nodeList[i] = malloc(sizeof(node));
        if (!nodeList[i]) {
            logError("Failed to allocate memory for node.");
            continue;
        }
        nodeList[i]->value = (double)(rand() % (maxVal - minVal + 1)) + minVal;
        nodeList[i]->next = (i < numNodes - 1) ? nodeList[i + 1] : NULL;

        // Populate strings
        for (int j = 0; j < strLen; ++j) {
            char* randomStr = malloc(strLen + 1);
            if (!randomStr) {
                logError("Failed to allocate memory for string.");
                continue;
            }
            for (int k = 0; k < strLen; ++k) {
                randomStr[k] = alphabet[rand() % strlen(alphabet)];
            }
            randomStr[strLen] = '\0';
        }
    }

    // Populate values
    for (int i = 0; i < numValues; ++i) {
        values[i] = (double)(rand() % (maxVal - minVal + 1)) + minVal;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Populate metadata
    tagMetadata* metadata = malloc(numNodes * sizeof(tagMetadata));
    if (!metadata) {
        logError("Failed to allocate memory for metadata.");
        return;
    }

    for (int i = 0; i < numNodes; ++i) {
        pthread_mutex_lock(&lock);
        metadata[i].name = strdup("ExampleName");
        metadata[i].id = rand() % ((unsigned int)(INT_MAX - minVal)) + minVal;
        pthread_mutex_unlock(&lock);
    }

    free(metadata);
}

double calculateAverage(double* values, int size) {
    if (!values || size <= 0) return 0.0;

    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += values[i];
    }
    return sum / size;
}

void traverseAndPrint(node** nodeList, int nodeCount) {
    if (!nodeList || nodeCount <= 0) return;

    for (int i = 0; i < nodeCount; ++i) {
        node* current = nodeList[i];
        while (current != NULL) {
            printf("Node value: %f\n", current->value);
            current = current->next;
        }
    }
}

void logError(const char* errorMessage) {
    fprintf(stderr, "Error: %s\n", errorMessage);
}
```

### Explanation:
