#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

// Function to swap two integers
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Fisher-Yates shuffle algorithm for array shuffling
void shuffleArray(int *array, size_t n) {
    srand(time(NULL));
    for (size_t i = 0; i < n - 1; i++) {
        size_t j = i + rand() / (RAND_MAX / (n - i) + 1);
        swap(&array[i], &array[j]);
    }
}

record* createRecords(int n, int m) {
    if (m > n) {
        fprintf(stderr, "Error: m cannot be greater than n.\n");
        return NULL;
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(m * sizeof(int));
    if (!keys) {
        perror("Failed to allocate keys");
        return NULL;
    }

    // Populate and shuffle the key array
    for (int i = 0; i < m; ++i) {
        keys[i] = i + 1;
    }
    shuffleArray(keys, m);

    // Allocate memory for record structures
    record *records = (record *)malloc(n * sizeof(record));
    if (!records) {
        perror("Failed to allocate records");
        free(keys);
        return NULL;
    }

    // Initialize the record structures
    for (int i = 0; i < n; ++i) {
        records[i].offset = rand(); // Example offset value
        if (i < m) {
            records[i].key = keys[i];
        } else {
            records[i].key = -1; // Indicate no key assigned
        }
        records[i].value = i + 1;
    }

    free(keys);
    return records;
}
