['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

typedef struct {
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    record* records;
} log_pipeline;

// Initialize a new pipeline
log_pipeline* init_log_pipeline(size_t initial_capacity) {
    log_pipeline* lp = malloc(sizeof(log_pipeline));
    if (!lp) return NULL;

    pthread_mutex_init(&lp->lock, NULL);
    lp->count = 0;
    lp->capacity = initial_capacity;

    lp->offsets = calloc(initial_capacity, sizeof(long));
    lp->keys = calloc(initial_capacity, sizeof(int));
    lp->records = malloc(initial_capacity * sizeof(record));

    if (!lp->offsets || !lp->keys || !lp->records) {
        free(lp->offsets);
        free(lp->keys);
        free(lp->records);
        pthread_mutex_destroy(&lp->lock);
        free(lp);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        lp->records[i].value = rand() % 100;
        lp->records[i].offset_ptr = &lp->offsets[i];
        lp->records[i].key_ptr = &lp->keys[i];
    }
    return lp;
}

// Free the allocated pipeline
void free_log_pipeline(log_pipeline* lp) {
    if (!lp) return;
    pthread_mutex_destroy(&lp->lock);
    free(lp->offsets);
    free(lp->keys);
    free(lp->records);
    free(lp);
}

// Compact the records by merging empty ones
void compact_records(log_pipeline* lp) {
    if (!lp) return;

    size_t new_count = 0;
    for (size_t i = 0; i < lp->count; ++i) {
        // Assume a simple condition to define 'empty'
        if (lp->records[i].value != -1) { 
            lp->records[new_count++] = lp->records[i];
        }
    }
    lp->count = new_count;
}

// Retrieve record by index
record* get_record(log_pipeline* lp, size_t index) {
    pthread_mutex_lock(&lp->lock);
    if (index < lp->count) {
        record* res = &lp->records[index];
        pthread_mutex_unlock(&lp->lock);
        return res;
    }
    pthread_mutex_unlock(&lp->lock);
    return NULL;
}

// Iterate over records
void iterate_records(log_pipeline* lp, void (*callback)(record*, void*), void* arg) {
    if (!lp || !callback) return;

    pthread_mutex_lock(&lp->lock);
    for (size_t i = 0; i < lp->count; ++i) {
        callback(&lp->records[i], arg);
    }
    pthread_mutex_unlock(&lp->lock);
}

// Serialize the pipeline to a file
int serialize_log_pipeline(log_pipeline* lp, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&lp->count, sizeof(size_t), 1, file);
    fwrite(lp->offsets, sizeof(long), lp->capacity, file);
    fwrite(lp->keys, sizeof(int), lp->capacity, file);

    for (size_t i = 0; i < lp->count; ++i) {
        record* rec = &lp->records[i];
        int value = rec->value;
        long offset = *(rec->offset_ptr);
        int key = *(rec->key_ptr);
        fwrite(&value, sizeof(int), 1, file);
        fwrite(&offset, sizeof(long), 1, file);
        fwrite(&key, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

// Deserialize the pipeline from a file
log_pipeline* deserialize_log_pipeline(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    log_pipeline* lp = malloc(sizeof(log_pipeline));
    if (!lp) {
        fclose(file);
        return NULL;
    }

    pthread_mutex_init(&lp->lock, NULL);

    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    lp->capacity = capacity;
    lp->count = 0; // Will be updated during deserialization

    lp->offsets = malloc(capacity * sizeof(long));
    lp->keys = malloc(capacity * sizeof(int));
    lp->records = malloc(capacity * sizeof(record));

    if (!lp->offsets || !lp->keys || !lp->records) {
        free(lp->offsets);
        free(lp->keys);
        free(lp->records);
        pthread_mutex_destroy(&lp->lock);
        free(lp);
        fclose(file);
        return NULL;
    }

    fread(lp->offsets, sizeof(long), capacity, file);
    fread(lp->keys, sizeof(int), capacity, file);

    for (size_t i = 0; i < capacity; ++i) {
        int value;
        long offset;
        int key;

        fread(&value, sizeof(int), 1, file);
        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);

        if (value != -1) { // Assume non-negative values are valid
            lp->count++;
            lp->records[i].value = value;
            lp->records[i].offset_ptr = &lp->offsets[i];
            lp->records[i].key_ptr = &lp->keys[i];
        } else {
            memset(&lp->records[i], 0, sizeof(record));
        }
    }

    fclose(file);
    return lp;
}
