#include <pthread.h>

typedef struct Paragraph {
    char *content;
    float score;
} Paragraph;

typedef struct Document {
    char *title;
    int year;
    size_t paragraph_count;
    size_t capacity;
    Paragraph **paragraphs;
    int ref_count;
    pthread_mutex_t lock;
} Document;

Document* create_document(const char *title, int year) {
    Document *doc = (Document *)malloc(sizeof(Document));
    if (!doc) return NULL;

    doc->title = strdup(title);
    if (!doc->title) {
        free(doc);
        return NULL;
    }

    doc->year = year;
    doc->paragraph_count = 0;
    doc->capacity = 10; // Initial capacity for paragraphs
    doc->paragraphs = (Paragraph **)malloc(doc->capacity * sizeof(Paragraph *));
    if (!doc->paragraphs) {
        free(doc->title);
        free(doc);
        return NULL;
    }

    doc->ref_count = 1;
    pthread_mutex_init(&doc->lock, NULL);

    return doc;
}

void destroy_document(Document **doc) {
    if (!doc || !*doc) return;

    pthread_mutex_lock(&(*doc)->lock);

    for (size_t i = 0; i < (*doc)->paragraph_count; ++i) {
        free((*doc)->paragraphs[i]->content);
        free((*doc)->paragraphs[i]);
    }

    free((*doc)->paragraphs);
    free((*doc)->title);
    pthread_mutex_unlock(&(*doc)->lock);
    pthread_mutex_destroy(&(*doc)->lock);
    free(*doc);
    *doc = NULL;
}

int increment_ref_count(Document *doc) {
    if (!doc) return -1;

    pthread_mutex_lock(&doc->lock);
    doc->ref_count++;
    int new_count = doc->ref_count;
    pthread_mutex_unlock(&doc->lock);

    return new_count;
}

int decrement_ref_count(Document **doc) {
    if (!doc || !*doc) return -1;

    pthread_mutex_lock(&(*doc)->lock);
    if (--((*doc)->ref_count) == 0) {
        destroy_document(doc);
        return 0; // Document destroyed
    }
    int new_count = (*doc)->ref_count;
    pthread_mutex_unlock(&(*doc)->lock);

    return new_count;
}

int add_paragraph(Document *doc, const char *content, float score) {
    if (!doc) return -1;

    pthread_mutex_lock(&doc->lock);

    if (doc->paragraph_count == doc->capacity) {
        size_t new_capacity = doc->capacity * 2;
        Paragraph **new_paragraphs = realloc(doc->paragraphs, new_capacity * sizeof(Paragraph *));
        if (!new_paragraphs) {
            pthread_mutex_unlock(&doc->lock);
            return -1; // Memory allocation failed
        }
        doc->paragraphs = new_paragraphs;
        doc->capacity = new_capacity;
    }

    Paragraph *para = (Paragraph *)malloc(sizeof(Paragraph));
    if (!para) {
        pthread_mutex_unlock(&doc->lock);
        return -1; // Memory allocation failed
    }

    para->content = strdup(content);
    if (!para->content) {
        free(para);
        pthread_mutex_unlock(&doc->lock);
        return -1;
    }

    para->score = score;
    doc->paragraphs[doc->paragraph_count++] = para;

    pthread_mutex_unlock(&doc->lock);

    return 0; // Success
}

int get_paragraph(Document *doc, size_t index, char **content, float *score) {
    if (!doc || !content || !score) return -1;

    pthread_mutex_lock(&doc->lock);

    if (index >= doc->paragraph_count) {
        pthread_mutex_unlock(&doc->lock);
        return -1; // Index out of bounds
    }

    Paragraph *para = doc->paragraphs[index];
    *content = para->content;
    *score = para->score;

    pthread_mutex_unlock(&doc->lock);

    return 0; // Success
}

int update_document(Document *doc, const char *new_title, int new_year) {
    if (!doc) return -1;

    pthread_mutex_lock(&doc->lock);

    free(doc->title);
    doc->title = strdup(new_title);
    if (!doc->title) {
        pthread_mutex_unlock(&doc->lock);
        return -1;
    }

    doc->year = new_year;

    pthread_mutex_unlock(&doc->lock);

    return 0; // Success
}

// Serializing and deserializing functions would go here, optimized for large datasets

