    free(doc->paragraphs);

    free(doc);
}

int add_paragraph(Document* doc, const char* content, float score) {
    if (!doc || !content || !(*content)) return -1;

    Paragraph *new_para = (Paragraph *)malloc(sizeof(Paragraph));
    if (!new_para) {
        log_error("Memory allocation failure for paragraph");
        return -1;
    }

    new_para->content = strdup(content);
    if (!new_para->content) {
        free(new_para);
        log_error("Memory allocation failure for paragraph content");
        return -1;
    }

    new_para->score = score;

    Paragraph **new_array = (Paragraph **)realloc(doc->paragraphs, 
                        (doc->paragraph_count + 1) * sizeof(Paragraph *));
    if (!new_array) {
        free(new_para->content);
        free(new_para);
        log_error("Memory allocation failure for paragraph array");
        return -1;
    }

    doc->paragraphs = new_array;
    doc->paragraphs[doc->paragraph_count] = new_para;
    doc->paragraph_count++;

    // Placeholder: Persist changes in database
    retry_on_failure(NULL, 3); // Replace NULL with actual DB operation

    return 0; 
}

Paragraph* get_paragraph_by_index(Document* doc, size_t index) {
    if (!doc || index >= doc->paragraph_count) return NULL;
    return doc->paragraphs[index];
}

int update_document_metadata(Document* doc, const char* new_title, int new_year) {
    if (!doc || !new_title || !(*new_title)) return -1;

    free(doc->title);
    doc->title = strdup(new_title);
    if (!doc->title) {
        log_error("Memory allocation failure for new title");
        return -1;
    }

    doc->year = new_year;

    // Placeholder: Persist changes in database
    retry_on_failure(NULL, 3); // Replace NULL with actual DB operation

    return 0; 
}

void increment_reference_count(Document* doc) {
    if (doc) doc->reference_count++;
}

void decrement_reference_count(Document* doc) {
    if (doc && doc->reference_count > 0) doc->reference_count--;
}

int is_active(Document* doc) {
    return (doc && doc->reference_count > 0);
}

// Main function for demonstration purposes
int main() {
    Document *doc = create_document("Sample Title", 2023);

    if (!is_active(doc)) {
        log_error("Document creation failed");
        return -1;
    }

    add_paragraph(doc, "Paragraph content here.", 9.5);
    Paragraph* para = get_paragraph_by_index(doc, 0);
    if (para) printf("Paragraph: %s\n", para->content);

    update_document_metadata(doc, "Updated Title", 2024);

    decrement_reference_count(doc);
    free_document(doc);

    return 0;
}
