['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    size_t offsets_size;

    int *keys;
    size_t keys_size;

    record **records;
    size_t records_capacity;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_manager(size_t initial_capacity) {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->offsets = NULL;
    manager->offsets_size = 0;

    manager->keys = NULL;
    manager->keys_size = 0;

    manager->records = (record**)calloc(initial_capacity, sizeof(record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->records_capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->records_capacity; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_key(MemoryManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->keys_size; ++i) {
        if (manager->keys[i] == key) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    int *new_keys = realloc(manager->keys, sizeof(int) * (manager->keys_size + 1));
    if (!new_keys) {
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }
    manager->keys = new_keys;
    manager->keys[manager->keys_size++] = key;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_record(MemoryManager *manager, record *new_record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->records_capacity <= manager->keys_size) {
        size_t new_capacity = manager->records_capacity * 2;
        record **new_records = realloc(manager->records, sizeof(record*) * new_capacity);
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -3;
        }
        memset(new_records + manager->records_capacity, 0, sizeof(record*) * (new_capacity - manager->records_capacity));
        manager->records = new_records;
        manager->records_capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->keys_size; ++i) {
        if (!manager->records[i]) {
            manager->records[i] = malloc(sizeof(record));
            if (!manager->records[i]) {
                pthread_mutex_unlock(&manager->lock);
                return -4;
            }
            *manager->records[i] = *new_record;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void fill_records(MemoryManager *manager, int min_val, int max_val) {
    srand(time(NULL));
    for (size_t i = 0; i < manager->keys_size; ++i) {
        if (!manager->records[i]) continue;

        int key;
        do {
            key = rand() % (max_val - min_val + 1) + min_val;
        } while (add_key(manager, key));

        record new_record = { .value = key };
        add_record(manager, &new_record);
    }
}

int main() {
    size_t initial_capacity = 10;
    MemoryManager *manager = create_manager(initial_capacity);

    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager.\n");
        return EXIT_FAILURE;
    }

    fill_records(manager, 1, 100);

    for (size_t i = 0; i < manager->keys_size && i < manager->records_capacity; ++i) {
        if (manager->records[i]) {
            printf("Record %zu: Key=%d, Value=%d\n", i, manager->keys[i], manager->records[i]->value);
        }
    }

    destroy_manager(manager);

    return EXIT_SUCCESS;
}
