['Below is a C function implementing the described requirements. This code manages memory for two arrays: one for `char*` file paths and another for `DirectoryEntry` structures with a custom allocator to handle dynamic resizing and minimize fragmentation. Thread safety is ensured using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char *filename;
    time_t last_modified;
    off_t file_size;
} DirectoryEntry;

typedef struct {
    DirectoryEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    double growth_factor;
} DirectoryManager;

// Function prototypes
DirectoryManager* create_directory_manager(size_t initial_capacity, double growth_factor);
void destroy_directory_manager(DirectoryManager *manager);
int add_entry(DirectoryManager *manager, const char *path, const struct stat *file_stat);
static int resize_entries(DirectoryManager *manager);

DirectoryManager* create_directory_manager(size_t initial_capacity, double growth_factor) {
    DirectoryManager *manager = malloc(sizeof(DirectoryManager));
    if (!manager) return NULL;

    manager->entries = calloc(initial_capacity, sizeof(DirectoryEntry *));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->growth_factor = growth_factor;

    return manager;
}

void destroy_directory_manager(DirectoryManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->filename);
        free(manager->entries[i]);
    }
    free(manager->entries);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_entry(DirectoryManager *manager, const char *path, const struct stat *file_stat) {
    if (!manager || !path || !file_stat) return -1;

    // Lock for thread-safe access
    pthread_mutex_lock(&manager->mutex);

    // Check for duplicates by filename
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->filename, path + strlen(path)) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    // Resize array if necessary
    if (resize_entries(manager) != 0) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    DirectoryEntry *entry = malloc(sizeof(DirectoryEntry));
    if (!entry) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    entry->filename = strdup(path + strlen(path));  // Store just the filename
    if (!entry->filename) {
        free(entry);
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    entry->last_modified = file_stat->st_mtime;
    entry->file_size = file_stat->st_size;

    manager->entries[manager->count++] = entry;

    // Unlock after operation
    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

static int resize_entries(DirectoryManager *manager) {
    if (manager->count < manager->capacity) return 0;

    size_t new_capacity = (size_t)(manager->capacity * manager->growth_factor);
    DirectoryEntry **new_entries = realloc(manager->entries, new_capacity * sizeof(DirectoryEntry *));
    if (!new_entries) return -1;

    memset(new_entries + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(DirectoryEntry *));
    manager->entries = new_entries;
    manager->capacity = new_capacity;

    return 0;
}

void populate_directory_manager(DirectoryManager *manager, const char *directory_path) {
    if (!manager || !directory_path) return;

    DIR *dir = opendir(directory_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char full_path[PATH_MAX];
        snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != -1) {
            add_entry(manager, full_path, &file_stat);
        }
    }

    closedir(dir);
}
```

### Key Points:

- **Thread Safety**: The function uses a mutex (`pthread_mutex_t`) to ensure thread-safe access to the `DirectoryEntry` array.
- **Dynamic Resizing**: The array resizes based on a growth factor when needed, using `realloc`.
- **Duplicate Prevention**: Checks for existing filenames before adding new entries.
- **Error Handling**: Proper error handling is included for memory allocation failures and file operations.']

