#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    size_t offset_count;
    pthread_mutex_t lock;
} OffsetArray;

typedef struct {
    int* keys;
    size_t key_count;
    pthread_rwlock_t rwlock; // Read-write lock for concurrent read/write access
} KeyArray;

typedef struct {
    record** records;
    size_t capacity;
    size_t count;
    double growth_factor;
    pthread_mutex_t mutex;
    // Simple cache with fixed size (e.g., LRU cache not implemented here)
    record* cache[10];
    size_t cache_index;
} RecordPool;

void init_offset_array(OffsetArray* offset_array, size_t initial_size) {
    pthread_mutex_init(&offset_array->lock, NULL);
    offset_array->offsets = malloc(initial_size * sizeof(long));
    if (!offset_array->offsets) {
        perror("Failed to allocate offsets");
        exit(EXIT_FAILURE);
    }
    offset_array->offset_count = 0;
}

void free_offset_array(OffsetArray* offset_array) {
    pthread_mutex_destroy(&offset_array->lock);
    free(offset_array->offsets);
}

void init_key_array(KeyArray* key_array, size_t initial_size) {
    pthread_rwlock_init(&key_array->rwlock, NULL);
    key_array->keys = malloc(initial_size * sizeof(int));
    if (!key_array->keys) {
        perror("Failed to allocate keys");
        exit(EXIT_FAILURE);
    }
    key_array->key_count = 0;
}

void free_key_array(KeyArray* key_array) {
    pthread_rwlock_destroy(&key_array->rwlock);
    free(key_array->keys);
}

void init_record_pool(RecordPool* pool, size_t initial_capacity, double growth_factor) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->records = malloc(initial_capacity * sizeof(record*));
    if (!pool->records) {
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->records[i] = NULL;
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->growth_factor = growth_factor;
    pool->cache_index = 0;
}

void resize_record_pool(RecordPool* pool) {
    size_t new_capacity = (size_t)(pool->capacity * pool->growth_factor);
    record** new_records = realloc(pool->records, new_capacity * sizeof(record*));
    if (!new_records) {
        perror("Failed to reallocate records");
        exit(EXIT_FAILURE);
    }
    for (size_t i = pool->capacity; i < new_capacity; ++i) {
        new_records[i] = NULL;
    }
    pool->records = new_records;
    pool->capacity = new_capacity;
}

record* get_unique_record(KeyArray* key_array, RecordPool* pool) {
    pthread_rwlock_rdlock(&key_array->rwlock);
    for (size_t i = 0; i < key_array->key_count; ++i) {
        int key = key_array->keys[i];
        pthread_rwlock_unlock(&key_array->rwlock);

        pthread_mutex_lock(&pool->mutex);
        for (size_t j = 0; j < pool->count; ++j) {
            if (pool->records[j] && pool->records[j]->value == key) {
                record* rec = pool->records[j];
                // Update cache
                pool->cache[pool->cache_index % 10] = rec;
                pool->cache_index++;
                pthread_mutex_unlock(&pool->mutex);
                return rec;
            }
        }

        if (pool->count >= pool->capacity) {
            resize_record_pool(pool);
        }

        record* new_rec = malloc(sizeof(record));
        if (!new_rec) {
            perror("Failed to allocate new record");
            exit(EXIT_FAILURE);
        }
        new_rec->value = key;

        pthread_mutex_lock(&pool->mutex);
        pool->records[pool->count++] = new_rec;
        pthread_mutex_unlock(&pool->mutex);

        pthread_rwlock_rdlock(&key_array->rwlock); // Re-lock for next iteration
    }
    pthread_rwlock_unlock(&key_array->rwlock);

    return NULL; // No unique record found
}

void free_record_pool(RecordPool* pool) {
    pthread_mutex_destroy(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]);
    }
    free(pool->records);
}
