typedef struct {
    int value;
    long* offset;
    int* key;
} Record;

typedef struct {
    Record** records;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

void init_random() {
    srand(time(NULL));
}

int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = calloc(initial_size, sizeof(Record*));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i]->offset);
        free(array->records[i]->key);
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_record(DynamicArray* array, int value_range_min, int value_range_max) {
    if (!array) return -1;

    pthread_mutex_lock(&array->mutex);

    Record* record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    record->value = rand_in_range(value_range_min, value_range_max);
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        free(record);
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    *record->offset = 0; // Example initialization

    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        free(record);
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    *record->key = rand_in_range(0, 100); // Example key generation

    array->records[array->count++] = record;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

Record* get_record(DynamicArray* array, size_t index) {
    if (!array || index >= array->count) return NULL;

    pthread_mutex_lock(&array->mutex);

    Record* record = array->records[index];

    pthread_mutex_unlock(&array->mutex);
    return record;
}

int update_record(DynamicArray* array, size_t index, int new_value, long new_offset, int new_key) {
    if (!array || index >= array->count) return -1;

    pthread_mutex_lock(&array->mutex);

    Record* record = array->records[index];
    record->value = new_value;
    *record->offset = new_offset;
    *record->key = new_key;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int delete_record(DynamicArray* array, size_t index) {
    if (!array || index >= array->count) return -1;

    pthread_mutex_lock(&array->mutex);

    free(array->records[index]->offset);
    free(array->records[index]->key);
    free(array->records[index]);

    for (size_t i = index; i < array->count - 1; ++i) {
        array->records[i] = array->records[i + 1];
    }
    --array->count;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

