#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    long offset;
    int key;
    record r;
} RecordEntry;

typedef struct {
    RecordEntry **array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // for thread safety
} DynamicArray;

// Function prototypes
DynamicArray *init_dynamic_array(const char *config_file, const char *json_data_source);
int load_json_data(DynamicArray *arr, const char *json_data);
void resize_array_if_needed(DynamicArray *arr);
RecordEntry *find_entry_by_key(DynamicArray *arr, int key);
int add_record(DynamicArray *arr, long offset, int key, int value, int log_level);
void free_dynamic_array(DynamicArray *arr);

// Function to initialize the dynamic array
DynamicArray *init_dynamic_array(const char *config_file, const char *json_data_source) {
    FILE *file = fopen(config_file, "r");
    if (!file) return NULL;

    // Read configuration parameters
    size_t num_records;
    long random_number_range;
    int log_level, debug_mode;

    fscanf(file, "%zu %ld %d %d", &num_records, &random_number_range, &log_level, &debug_mode);
    fclose(file);

    DynamicArray *arr = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    pthread_mutex_init(&arr->lock, NULL);
    arr->size = 0;
    arr->capacity = num_records; // Initial capacity
    arr->array = (RecordEntry **)calloc(arr->capacity, sizeof(RecordEntry *));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    int json_load_status = load_json_data(arr, json_data_source);
    if (json_load_status != 0) {
        free_dynamic_array(arr);
        return NULL;
    }

    // Further initialization can be added here
    return arr;
}

// Function to load JSON data into the dynamic array
int load_json_data(DynamicArray *arr, const char *json_data_source) {
    FILE *file = fopen(json_data_source, "r");
    if (!file) return -1;

    struct json_object *parsed_json;
    struct json_object *json_array;

    size_t len;
    char *content = fread_to_string(file, &len);
    fclose(file);

    parsed_json = json_tokener_parse(content);
    free(content);

    if (!parsed_json) {
        return -2; // JSON parse error
    }

    if (!json_object_is_type(parsed_json, json_type_array)) {
        json_object_put(parsed_json); // Free the object
        return -3; // Expected array type
    }

    json_array = parsed_json;

    for (size_t i = 0; i < json_object_array_length(json_array); ++i) {
        struct json_object *json_entry;
        json_entry = json_object_array_get_idx(json_array, i);

        long offset;
        int key, value;

        // Assuming JSON structure: {"offset": ..., "key": ..., "value": ...}
        if (json_object_get_type(json_object_object_get(json_entry, "offset")) == json_type_int &&
            json_object_get_type(json_object_object_get(json_entry, "key")) == json_type_int &&
            json_object_get_type(json_object_object_get(json_entry, "value")) == json_type_int) {

            offset = json_object_get_int64(json_object_object_get(json_entry, "offset"));
            key = json_object_get_int(json_object_object_get(json_entry, "key"));
            value = json_object_get_int(json_object_object_get(json_entry, "value"));

            if (add_record(arr, offset, key, value, 0 /* default log level */) != 0) {
                json_object_put(parsed_json);
                return -4; // Error adding record
            }
        } else {
            json_object_put(parsed_json); // Free the object on failure
            return -5; // Invalid data in JSON
        }
    }

    json_object_put(parsed_json);
    return 0;
}

// Helper function to add a record to the dynamic array
int add_record(DynamicArray *arr, long offset, int key, int value, int log_level) {
    pthread_mutex_lock(&arr->lock);

    resize_array_if_needed(arr);

    RecordEntry *entry = (RecordEntry *)malloc(sizeof(RecordEntry));
    if (!entry) {
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    entry->r.value = value;
    entry->r.offset_ptr = &offset;
    entry->r.key_ptr = &key;
    entry->array[arr->size] = entry;

    arr->size++;
    pthread_mutex_unlock(&arr->lock);

    // Logging (example)
    if (log_level > 0) {
        printf("Added record with key: %d\n", key);
    }

    return 0;
}

// Function to resize the array when needed
void resize_array_if_needed(DynamicArray *arr) {
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2; // Double capacity strategy

        RecordEntry **new_array = (RecordEntry **)realloc(arr->array, new_capacity * sizeof(RecordEntry *));
        if (!new_array) return;

        memset(new_array + arr->capacity, 0, (new_capacity - arr->capacity) * sizeof(RecordEntry *));
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray *arr) {
    if (!arr) return;

    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->array[i]);
    }

    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

// Helper function to read file content into a string
char *fread_to_string(FILE *file, size_t *len) {
    fseek(file, 0, SEEK_END);
    *len = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(*len + 1);
    if (!buffer) return NULL;

    fread(buffer, 1, *len, file);
    buffer[*len] = '\0';
    return buffer;
}
```

