}

void resize_record_array(RecordArray *array) {
    size_t new_capacity = array->capacity * 2;
    Record **new_records = (Record **)realloc(array->records, new_capacity * sizeof(Record *));
    if (new_records) {
        array->records = new_records;
        array->capacity = new_capacity;
    }
}

void insert_record(RecordArray *array, int value, long offset, int key) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_record_array(array);
    }

    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->value = value;
    new_record->offset = malloc(sizeof(long));
    new_record->key = malloc(sizeof(int));

    *(new_record->offset) = offset;
    *(new_record->key) = key;

    array->records[array->count] = new_record;
    array->count++;

    pthread_mutex_unlock(&array->lock);
}

Record* get_record(RecordArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->lock);
    Record *record = array->records[index];
    pthread_mutex_unlock(&array->lock);

    return record;
}

void update_record_value(RecordArray *array, size_t index, int new_value) {
    pthread_mutex_lock(&array->lock);

    if (index < array->count) {
        array->records[index]->value = new_value;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_record_array(RecordArray *array) {
    for (size_t i = 0; i < array->count; i++) {
        free(array->records[i]->offset);
        free(array->records[i]->key);
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    RecordArray *record_array = create_record_array(4);

    insert_record(record_array, 10, 100L, 1);
    insert_record(record_array, 20, 200L, 2);

    Record *record = get_record(record_array, 0);
    if (record) {
        printf("Record value: %d\n", record->value);
    }

    update_record_value(record_array, 0, 30);

    free_record_array(record_array);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: The `resize_record_array` function doubles the capacity of the array when needed.
- **Concurrency**: A mutex (`pthread_mutex_t`) is used to ensure thread-safe operations on the record array.
- **Memory Efficiency**: Memory for each record's fields is allocated and freed individually to manage resources efficiently.
- **Scalability**: The design allows for easy expansion, such as adding more fields or operations.']

['Below is a C code implementation that incorporates your requirements using POSIX threads, mutexes, and atomic operations. This example assumes you have access to a distributed database API and a message queue system.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <string.h>

// Assume these are defined elsewhere for interacting with the distributed database and message queue.
extern int check_token_in_db(const char *token);
extern void append_to_message_queue(const char *message);
extern void log_audit(const char *log_message);

typedef struct {
    int value;
    long *offset;
    int *key;
    char *auth_token; // Dynamically allocated token
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t mutex;
    atomic_size_t count;
} RecordCollection;

// Global instance for the record collection
RecordCollection rc = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, ATOMIC_VAR_INIT(0)};

void init_record_collection(size_t initial_capacity) {
    pthread_mutex_lock(&rc.mutex);
    rc.capacity = initial_capacity;
    rc.records = (Record **)malloc(initial_capacity * sizeof(Record *));
    if (!rc.records) {
        log_audit("Memory allocation failed for record collection.");
        exit(EXIT_FAILURE);
    }
    memset(rc.records, 0, initial_capacity * sizeof(Record *));
    pthread_mutex_unlock(&rc.mutex);
}

Record *create_record(int value, long offset, int key) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        log_audit("Memory allocation failed for record.");
        return NULL;
    }

    record->value = value;
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        free(record);
        log_audit("Memory allocation failed for offset pointer.");
        return NULL;
    }
    *record->offset = offset;

    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record->offset);
        free(record);
        log_audit("Memory allocation failed for key pointer.");
        return NULL;
    }
    *record->key = key;

    size_t token_length = 16; // Example length
    record->auth_token = malloc(token_length + 1); // +1 for null terminator
    if (!record->auth_token) {
        free(record->key);
        free(record->offset);
        free(record);
        log_audit("Memory allocation failed for auth token.");
        return NULL;
    }

    snprintf(record->auth_token, token_length + 1, "token_%ld", (long)pthread_self());

    pthread_mutex_lock(&rc.mutex);
    if (atomic_load(&rc.count) >= rc.capacity) {
        pthread_mutex_unlock(&rc.mutex);
        log_audit("Record collection capacity reached.");
        free(record->auth_token);
        free(record->key);
        free(record->offset);
        free(record);
        return NULL;
    }
    rc.records[atomic_fetch_add(&rc.count, 1)] = record;
    pthread_mutex_unlock(&rc.mutex);

    // Avoid duplicate tokens
    size_t suffix = 0;
    while (check_token_in_db(record->auth_token)) {
        snprintf(record->auth_token, token_length + 1, "token_%ld_%zu", (long)pthread_self(), ++suffix);
    }

    append_to_message_queue("New record created with unique auth token.");
    return record;
}

void destroy_record(Record *record) {
    if (!record) return;

    free(record->auth_token);
    free(record->key);
    free(record->offset);
    free(record);

    pthread_mutex_lock(&rc.mutex);
    size_t index = 0;
    for (; index < rc.capacity; ++index) {
        if (rc.records[index] == record) break;
    }
    rc.records[index] = NULL;
    atomic_fetch_sub(&rc.count, 1);
    pthread_mutex_unlock(&rc.mutex);

    log_audit("Record destroyed.");
}

void cleanup_record_collection() {
    pthread_mutex_lock(&rc.mutex);
    for (size_t i = 0; i < rc.capacity; ++i) {
        if (rc.records[i]) destroy_record(rc.records[i]);
    }
    free(rc.records);
    rc.records = NULL;
    rc.capacity = 0;
    pthread_mutex_unlock(&rc.mutex);

    log_audit("Record collection cleaned up.");
}

int main() {
    init_record_collection(10000); // Initial capacity

    // Example usage: creating and destroying records
    Record *record1 = create_record(42, 123456789L, 1);
    destroy_record(record1);

    cleanup_record_collection();
    return 0;
}
```

