char* generate_random_alphanumeric_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *random_string = malloc(length + 1);
    if (!random_string) return NULL;

    for (size_t i = 0; i < length; i++) {
        random_string[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_string[length] = '\0';
    return random_string;
}

char* generate_unique_identifier(const char *base_id, int range_min, int range_max) {
    time_t timestamp = time(NULL);
    size_t random_length = rand() % (32 - 16 + 1) + 16; // Random length between 16 and 32
    char *random_string = generate_random_alphanumeric_string(random_length);

    if (!random_string) {
        log_error("Failed to generate random alphanumeric string");
        return NULL;
    }

    size_t identifier_length = strlen(base_id) + random_length + 20; // Approximation for timestamp
    if (identifier_length > UNIQUE_ID_LENGTH - 1) {
        free(random_string);
        log_error("Generated identifier exceeds maximum length");
        return NULL;
    }

    char *unique_identifier = malloc(identifier_length + 1);
    if (!unique_identifier) {
        free(random_string);
        log_error("Failed to allocate memory for unique identifier");
        return NULL;
    }

    snprintf(unique_identifier, identifier_length + 1,
             "%s_%ld_%s", base_id, timestamp, random_string);

    free(random_string);
    return unique_identifier;
}

int verify_identifier_with_service(const char *identifier) {
    // Placeholder for external service call
    return rand() % 2; // Randomly simulate verification success or failure
}

void handle_concurrent_requests(RecordManager *manager, const char *base_id, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record **new_records = realloc(manager->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            log_error("Failed to reallocate memory for records");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        memset(new_records + manager->size, 0, (new_capacity - manager->size) * sizeof(Record *));
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    char *unique_id = generate_unique_identifier(base_id, value_range_min, value_range_max);
    if (!unique_id || !verify_identifier_with_service(unique_id)) {
        log_error("Failed to create or verify unique identifier");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        free(unique_id);
        log_error("Failed to allocate memory for new record");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    new_record->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    new_record->offset = malloc(sizeof(long));
    if (!new_record->offset) {
        free(new_record);
        free(unique_id);
        log_error("Failed to allocate memory for offset");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    *new_record->offset = rand();

    new_record->key = malloc(sizeof(int));
    if (!new_record->key) {
        free(*new_record->offset);
        free(new_record);
        free(unique_id);
        log_error("Failed to allocate memory for key");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    *new_record->key = rand();

    manager->records[manager->size] = new_record;
    manager->size++;

    free(unique_id);

    pthread_mutex_unlock(&manager->lock);
}

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = calloc(initial_capacity, sizeof(Record *));
    if (!manager->records) {
        free(manager);
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size; i++) {
        free(manager->records[i]->offset);
        free(manager->records[i]->key);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void log_error(const char *message) {
    // Placeholder for logging mechanism
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    srand(time(NULL));

    RecordManager *manager = create_record_manager(1000);

    if (!manager) {
        return EXIT_FAILURE;
    }

    handle_concurrent_requests(manager, "user123", 1, 100);

    destroy_record_manager(manager);

    return EXIT_SUCCESS;
}
