#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long *offset;
    int *key;
    float *weight;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
} DynamicArray;

// Error handling macro for malloc
#define CHECK_MEMORY(ptr) if (!(ptr)) { fprintf(stderr, "Memory allocation failed\n"); exit(EXIT_FAILURE); }

void initialize_random() {
    srand((unsigned int)time(NULL));
}

long random_long(long min, long max) {
    return (rand() % (max - min + 1)) + min;
}

int random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

float random_float(float min, float max) {
    float scale = rand() / (float) RAND_MAX;
    return min + scale * (max - min);
}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    CHECK_MEMORY(array);

    array->records = malloc(initial_capacity * sizeof(Record *));
    CHECK_MEMORY(array->records);

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void expand_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    Record **new_records = realloc(array->records, new_capacity * sizeof(Record *));
    CHECK_MEMORY(new_records);

    array->records = new_records;
    array->capacity = new_capacity;
}

void initialize_arrays(DynamicArray *array, size_t num_records, long offset_min, long offset_max, int key_min, int key_max, float weight_min, float weight_max) {
    for (size_t i = 0; i < num_records; ++i) {
        if (array->count == array->capacity) {
            expand_dynamic_array(array);
        }

        Record *record = malloc(sizeof(Record));
        CHECK_MEMORY(record);

        record->offset = malloc(sizeof(long));
        CHECK_MEMORY(record->offset);

        record->key = malloc(sizeof(int));
        CHECK_MEMORY(record->key);

        record->weight = malloc(sizeof(float));
        CHECK_MEMORY(record->weight);

        *record->offset = random_long(offset_min, offset_max);
        *record->key = random_int(key_min, key_max);
        *record->weight = random_float(weight_min, weight_max);

        array->records[array->count++] = record;
    }
}

Record* get_record(DynamicArray *array, size_t index) {
    if (index < array->count) {
        return array->records[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

void update_record_value(Record *record, int new_value) {
    if (record) {
        record->value = new_value;
    }
}

float compute_weighted_average(DynamicArray *array) {
    float sum_weights = 0.0f;
    float weighted_sum = 0.0f;

    for (size_t i = 0; i < array->count; ++i) {
        Record *record = array->records[i];
        weighted_sum += record->value * (*record->weight);
        sum_weights += *record->weight;
    }

    return sum_weights == 0 ? 0 : weighted_sum / sum_weights;
}

void free_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        Record *record = array->records[i];
        free(record->offset);
        free(record->key);
        free(record->weight);
        free(record);
    }

    free(array->records);
    free(array);
}

int main() {
    initialize_random();

    DynamicArray *array = create_dynamic_array(10);

    // Example initialization parameters
    size_t num_records = 15;
    long offset_min = 0, offset_max = 1000;
    int key_min = 1, key_max = 500;
    float weight_min = 0.1f, weight_max = 10.0f;

    initialize_arrays(array, num_records, offset_min, offset_max, key_min, key_max, weight_min, weight_max);

    Record *record = get_record(array, 5);
    if (record) {
        update_record_value(record, random_int(100, 200));
    }

    float weighted_avg = compute_weighted_average(array);
    printf("Weighted Average: %f\n", weighted_avg);

    free_dynamic_array(array);
    return 0;
}
