int parseCSVAndPopulateEventLogArray(const char *filePath, EventLogArray *eventLogArray, float minLat, float maxLat, float minLong, float maxLong);
EventLog *getRecordByIndex(EventLogArray *array, size_t index);
EventLogArray filterEventData(EventLogArray *array, int startTime, int endTime, float minLat, float maxLat, float minLong, float maxLong);

// Function to initialize the dynamic array
void initializeEventLogArray(EventLogArray *array) {
    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->events = malloc(array->capacity * sizeof(EventLog *));
    if (!array->events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function to add an event log entry
int addEventLog(EventLogArray *array, int timestamp, const char *description, float latitude, float longitude) {
    // Validate coordinates
    if (latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
        fprintf(stderr, "Invalid coordinate values\n");
        return -1;
    }

    // Resize array if needed
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        EventLog **newEvents = realloc(array->events, newCapacity * sizeof(EventLog *));
        if (!newEvents) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        array->events = newEvents;
        array->capacity = newCapacity;
    }

    // Allocate memory for the new event
    EventLog *event = malloc(sizeof(EventLog));
    if (!event) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    event->timestamp = timestamp;
    event->description = strdup(description);
    if (!event->description) {
        free(event);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    event->latitude = latitude;
    event->longitude = longitude;

    // Add to array
    array->events[array->count++] = event;
    return 0;
}

// Function to parse CSV and populate the event log array
int parseCSVAndPopulateEventLogArray(const char *filePath, EventLogArray *eventLogArray, float minLat, float maxLat, float minLong, float maxLong) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int timestamp;
        char description[128];
        float latitude, longitude;

        // Parse CSV line
        if (sscanf(line, "%d,%127[^,],%f,%f", &timestamp, description, &latitude, &longitude) != 4) {
            fprintf(stderr, "Malformed data\n");
            continue;
        }

        // Validate coordinates and add event
        if (latitude >= minLat && latitude <= maxLat && longitude >= minLong && longitude <= maxLong) {
            addEventLog(eventLogArray, timestamp, description, latitude, longitude);
        }
    }

    fclose(file);
    return 0;
}

// Function to get a specific record by its index
EventLog *getRecordByIndex(EventLogArray *array, size_t index) {
    if (index < array->count) {
        return array->events[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

// Function to filter event data based on geographic area or time range
EventLogArray filterEventData(EventLogArray *array, int startTime, int endTime, float minLat, float maxLat, float minLong, float maxLong) {
    EventLogArray filteredArray;
    initializeEventLogArray(&filteredArray);

    for (size_t i = 0; i < array->count; ++i) {
        EventLog *event = array->events[i];
        if (event->timestamp >= startTime && event->timestamp <= endTime &&
            event->latitude >= minLat && event->latitude <= maxLat &&
            event->longitude >= minLong && event->longitude <= maxLong) {
            addEventLog(&filteredArray, event->timestamp, event->description, event->latitude, event->longitude);
        }
    }

    return filteredArray;
}

// Main function for testing
int main() {
    EventLogArray eventLogArray;
    initializeEventLogArray(&eventLogArray);

    if (parseCSVAndPopulateEventLogArray("events.csv", &eventLogArray, -90.0, 90.0, -180.0, 180.0) == 0) {
        printf("Event logs loaded successfully\n");
    }

    // Example of retrieving a record
    EventLog *record = getRecordByIndex(&eventLogArray, 0);
    if (record) {
        printf("Record: %d, %s, %.2f, %.2f\n", record->timestamp, record->description, record->latitude, record->longitude);
    }

    // Example of filtering data
    EventLogArray filteredArray = filterEventData(&eventLogArray, 1609459200, 1640995200, -40.0, 40.0, -80.0, 80.0);

    for (size_t i = 0; i < filteredArray.count; ++i) {
        EventLog *filteredEvent = filteredArray.events[i];
        printf("Filtered Record: %d, %s, %.2f, %.2f\n", filteredEvent->timestamp, filteredEvent->description, filteredEvent->latitude, filteredEvent->longitude);
    }

    // Free allocated memory
    for (size_t i = 0; i < eventLogArray.count; ++i) {
        free(eventLogArray.events[i]->description);
        free(eventLogArray.events[i]);
    }
    free(eventLogArray.events);

    for (size_t i = 0; i < filteredArray.count; ++i) {
        free(filteredArray.events[i]->description);
        free(filteredArray.events[i]);
    }
    free(filteredArray.events);

    return 0;
}
```

