#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DEFAULT_NAME "Unnamed"
#define MAX_ENTRIES 1000
#define AGE_RANGE_LOW 18
#define AGE_RANGE_HIGH 65
#define SALARY_RANGE_MIN 30000.0
#define SALARY_RANGE_MAX 200000.0

typedef struct {
    char *name;
    int age;
    float salary;
} entry;

// Function to generate a random integer within a specified range
int getRandomInt(int low, int high) {
    return rand() % (high - low + 1) + low;
}

// Function to generate a random float within a specified range
float getRandomFloat(float min, float max) {
    float scale = rand() / (float) RAND_MAX;
    return min + scale * (max - min);
}

entry* manageDataEntries(int initialSize) {
    entry *entries = malloc(initialSize * sizeof(entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize entries with random data
    for (int i = 0; i < initialSize; ++i) {
        entries[i].name = strdup(DEFAULT_NAME);
        entries[i].age = getRandomInt(AGE_RANGE_LOW, AGE_RANGE_HIGH);
        entries[i].salary = getRandomFloat(SALARY_RANGE_MIN, SALARY_RANGE_MAX);
    }

    // Resize array dynamically if needed
    entry* resizeEntries(entry *entries, int currentSize, int newSize) {
        entry *newEntries = realloc(entries, newSize * sizeof(entry));
        if (!newEntries) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(entries);
            exit(EXIT_FAILURE);
        }
        return newEntries;
    }

    // Insert a new entry at a specified position
    void insertEntry(entry **entries, int *size, int pos, const char *name) {
        if (pos < 0 || pos > *size) {
            fprintf(stderr, "Invalid position\n");
            return;
        }

        *entries = resizeEntries(*entries, *size + 1, *size + 1);
        memmove(&((*entries)[pos + 1]), &((*entries)[pos]), (*size - pos) * sizeof(entry));
        (*entries)[pos].name = strdup(name ? name : DEFAULT_NAME);
        (*entries)[pos].age = getRandomInt(AGE_RANGE_LOW, AGE_RANGE_HIGH);
        (*entries)[pos].salary = getRandomFloat(SALARY_RANGE_MIN, SALARY_RANGE_MAX);
        ++(*size);
    }

    // Retrieve an entry by its index
    entry getEntryByIndex(entry *entries, int index) {
        if (index < 0 || index >= MAX_ENTRIES) {
            fprintf(stderr, "Invalid index\n");
            exit(EXIT_FAILURE);
        }
        return entries[index];
    }

    // Update an existing entry’s information
    void updateEntry(entry *entries, int index, const char *name, int age, float salary) {
        if (index < 0 || index >= MAX_ENTRIES) {
            fprintf(stderr, "Invalid index\n");
            return;
        }
        free(entries[index].name);
        entries[index].name = strdup(name ? name : DEFAULT_NAME);
        entries[index].age = age;
        entries[index].salary = salary;
    }

    // Read names from standard input and store them
    void readNames(char names[MAX_ENTRIES][50], int *count) {
        char buffer[50];
        while (scanf("%49s", buffer) == 1 && *count < MAX_ENTRIES) {
            strcpy(names[*count], buffer);
            ++(*count);
        }
    }

    // Find and print the entry with the highest salary
    void findAndPrintHighestSalary(entry *entries, int size) {
        float maxSalary = -1;
        int indices[MAX_ENTRIES];
        int count = 0;

        for (int i = 0; i < size; ++i) {
            if (entries[i].salary > maxSalary) {
                maxSalary = entries[i].salary;
                count = 1;
                indices[0] = i;
            } else if (entries[i].salary == maxSalary) {
                indices[count++] = i;
            }
        }

        printf("Entries with the highest salary of %.2f:\n", maxSalary);
        for (int i = 0; i < count; ++i) {
            printf("Name: %s, Age: %d, Salary: %.2f\n",
                   entries[indices[i]].name,
                   entries[indices[i]].age,
                   entries[indices[i]].salary);
        }
    }

    char names[MAX_ENTRIES][50];
    int nameCount = 0;
    readNames(names, &nameCount);

    for (int i = 0; i < nameCount; ++i) {
        insertEntry(&entries, &initialSize, initialSize + i, names[i]);
    }

    findAndPrintHighestSalary(entries, initialSize + nameCount);

    // Free allocated memory
    for (int i = 0; i < initialSize + nameCount; ++i) {
        free(entries[i].name);
    }
    free(entries);

    return NULL;
}

int main() {
    srand(time(NULL));  // Seed the random number generator

    int initialSize;
    printf("Enter the initial size of the array: ");
    scanf("%d", &initialSize);

    manageDataEntries(initialSize);

    return 0;
}
