// Record structure definition
typedef struct {
    int value;
    long *offset;
    int *key;
    unsigned int ref_count;
} record;

// Global variables for managing records, offsets, and keys
record **records = NULL;
long *offsets = NULL;
int *keys = NULL;
size_t num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the array of records with random values
void initializeRecords(size_t count, int min_val, int max_val) {
    pthread_mutex_lock(&lock);

    if (records != NULL) free(records);
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);

    num_records = count;
    records = malloc(count * sizeof(record *));
    offsets = malloc(count * sizeof(long));
    keys = malloc(count * sizeof(int));

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % (max_val - min_val + 1) + min_val;
        records[i]->offset = &offsets[i];
        records[i]->key = &keys[i];
        records[i]->ref_count = 0;

        // Initialize offset and key with some values
        offsets[i] = i * 1000; // Example initialization
        keys[i] = (int)i;
    }

    pthread_mutex_unlock(&lock);
}

// Increment the reference count of a record by index
void incrementRefCount(size_t index) {
    if (index < num_records) {
        pthread_mutex_lock(&lock);
        records[index]->ref_count++;
        pthread_mutex_unlock(&lock);
    }
}

// Decrement the reference count of a record by index and free memory if ref_count reaches zero
void decrementRefCount(size_t index) {
    if (index < num_records) {
        pthread_mutex_lock(&lock);
        if (--records[index]->ref_count == 0) {
            free(records[index]);
            records[index] = NULL;
        }
        pthread_mutex_unlock(&lock);
    }
}

// Retrieve a specific record by its index
record* getRecord(size_t index) {
    pthread_mutex_lock(&lock);
    record *result = (index < num_records) ? records[index] : NULL;
    pthread_mutex_unlock(&lock);
    return result;
}

// Find and print the largest integer in an array read from standard input
void findAndPrintLargest() {
