typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
    float *weight_ptr;
} Record;

void initializeAndManageRecords(size_t num_records, long offset_range, int key_range, 
                                float weight_min, float weight_max) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate and initialize arrays for offsets, keys, and weights
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    float *weights = (float *)malloc(num_records * sizeof(float));

    if (!offsets || !keys || !weights) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(weights);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;
        weights[i] = weight_min + ((float)rand() / RAND_MAX) * (weight_max - weight_min);
    }

    // Allocate and initialize records
    Record *records = (Record *)malloc(num_records * sizeof(Record));

    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        free(weights);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % key_range;
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
        records[i].weight_ptr = &weights[i];
    }

    // Method to retrieve a specific record by index
    Record *getRecord(size_t index) {
        if (index < num_records) return &records[index];
        return NULL;
    }

    // Method to update a record's value
