    // Compute the weighted average of all records' int values
    float computeWeightedAverage() {
        float sum_weights = 0.0;
        float weighted_sum = 0.0;

        for (size_t i = 0; i < num_records; ++i) {
            float weight = *records[i].weight_ptr;
            weighted_sum += records[i].value * weight;
            sum_weights += weight;
        }

        return sum_weights == 0 ? 0 : weighted_sum / sum_weights;
    }

    // Helper function to find and print the largest integer
