['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct Node {
    record *record_ptr;
    struct Node *next;
} Node;

typedef struct MemoryPool {
    Node *available_records;
    pthread_mutex_t lock;
    size_t total_records;
    size_t used_memory;
} MemoryPool;

MemoryPool* create_pool(size_t max_records) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->available_records = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->total_records = 0;
    pool->used_memory = 0;
    return pool;
}

record* allocate_record(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    Node *node = pool->available_records;
    if (node != NULL) {
        // Reuse a deallocated record
        pool->available_records = node->next;
    } else if (pool->total_records < 100) {
        // Allocate new record
        record *new_record = (record *)malloc(sizeof(record));
        if (!new_record) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Allocation failed
        }
        pool->used_memory += sizeof(record);
        pool->total_records++;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Maximum records reached, retry later
    }

    if (node) {
        record *record_ptr = node->record_ptr;
        free(node); // Free the node, not the record itself
    } else {
        record *record_ptr = new_record;
    }

    // Initialize with random value
    srand(time(NULL) + rand());
    record_ptr->value = rand() % 1000;

    pthread_mutex_unlock(&pool->lock);
    return record_ptr;
}

void deallocate_record(MemoryPool *pool, record *rec) {
    pthread_mutex_lock(&pool->lock);

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        // Allocation failure handling
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    new_node->record_ptr = rec;
    new_node->next = pool->available_records;
    pool->available_records = new_node;
    pool->used_memory -= sizeof(record);

    pthread_mutex_unlock(&pool->lock);
}

void cleanup_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->available_records;
    while (current != NULL) {
        Node *next = current->next;
        free(current->record_ptr); // Free the record
        free(current);
        current = next;
    }

    pool->total_records = 0;
    pool->used_memory = 0;

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void log_stats(MemoryPool *pool, const char *stage) {
    printf("%s - Total Records: %zu, Used Memory: %zu bytes\n", stage, pool->total_records, pool->used_memory);
}

int main() {
    MemoryPool *pool = create_pool(100);

    log_stats(pool, "Start");

    // Example usage
    record *rec1 = allocate_record(pool);
    if (rec1) {
        printf("Allocated Record with value: %d\n", rec1->value);
        deallocate_record(pool, rec1);
    }

    log_stats(pool, "End");

    cleanup_pool(pool);

    return 0;
}
