#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    time_t timestamp;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    time_t retention_period;
    FILE *log_file;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, time_t retention_period) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    manager->records = malloc(initial_capacity * sizeof(Record));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->retention_period = retention_period;
    manager->log_file = fopen("memory_log.txt", "a");

    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager->records);
        free(manager);
        return NULL;
    }

    return manager;
}

void log_memory_usage(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    fprintf(manager->log_file, "Memory usage: %zu records\n", manager->count);
    fflush(manager->log_file);
    pthread_mutex_unlock(&manager->lock);
}

int add_record(RecordManager *manager, int key, time_t timestamp, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_RECORDS && manager->capacity == MAX_RECORDS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory pressure reached
    }

    while (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_RECORDS) {
            new_capacity = MAX_RECORDS;
        }

        Record *temp = realloc(manager->records, new_capacity * sizeof(Record));
        if (!temp) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->records = temp;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count++] = (Record){key, timestamp, offset};

    log_memory_usage(manager);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void cleanup_records(RecordManager *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);

    size_t i;
    for (i = 0; i < manager->count;) {
        if (current_time - manager->records[i].timestamp > manager->retention_period) {
            memmove(manager->records + i, manager->records + i + 1, (manager->count - i - 1) * sizeof(Record));
            manager->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void adjust_retention_period(RecordManager *manager, time_t new_retention_period) {
    pthread_mutex_lock(&manager->lock);

    manager->retention_period = new_retention_period;

    pthread_mutex_unlock(&manager->lock);
}

void free_record_manager(RecordManager *manager) {
    if (manager) {
        fclose(manager->log_file);
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
