['Below is a C implementation of a scalable task processing system using a custom priority queue based on a binary heap, supporting multi-threaded operations with POSIX threads.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TASKS 10000

typedef enum {
    PENDING,
    RUNNING,
    COMPLETED
} TaskStatus;

typedef struct {
    int id;
    int priority;
    time_t deadline;
    TaskStatus status;
    // Add more task attributes as needed.
} Task;

typedef struct {
    Task *tasks[MAX_TASKS];
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} PriorityQueue;

void swap(Task **a, Task **b) {
    Task *temp = *a;
    *a = *b;
    *b = temp;
}

int parent(int i) { return (i - 1) / 2; }
int left(int i) { return (2 * i + 1); }
int right(int i) { return (2 * i + 2); }

PriorityQueue* create_priority_queue() {
    PriorityQueue *pq = malloc(sizeof(PriorityQueue));
    pq->size = 0;
    pthread_mutex_init(&pq->lock, NULL);
    pthread_cond_init(&pq->cond_var, NULL);
    for(int i = 0; i < MAX_TASKS; i++) pq->tasks[i] = NULL;
    return pq;
}

void heapify_up(PriorityQueue *pq, int index) {
    while (index > 0 && pq->tasks[parent(index)]->priority < pq->tasks[index]->priority) {
        swap(&pq->tasks[parent(index)], &pq->tasks[index]);
        index = parent(index);
    }
}

void heapify_down(PriorityQueue *pq, int index) {
    int largest = index;
    int l = left(index);
    int r = right(index);

    if (l < pq->size && pq->tasks[l]->priority > pq->tasks[largest]->priority)
        largest = l;

    if (r < pq->size && pq->tasks[r]->priority > pq->tasks[largest]->priority)
        largest = r;

    if (largest != index) {
        swap(&pq->tasks[index], &pq->tasks[largest]);
        heapify_down(pq, largest);
    }
}

void enqueue_task(PriorityQueue *pq, Task *task) {
    pthread_mutex_lock(&pq->lock);
    pq->tasks[pq->size] = task;
    heapify_up(pq, pq->size);
    pq->size++;
    pthread_cond_signal(&pq->cond_var);
    pthread_mutex_unlock(&pq->lock);
}

Task* dequeue_task(PriorityQueue *pq) {
    pthread_mutex_lock(&pq->lock);
    while (pq->size == 0)
        pthread_cond_wait(&pq->cond_var, &pq->lock);

    Task *task = pq->tasks[0];
    pq->tasks[0] = pq->tasks[--pq->size];
    heapify_down(pq, 0);
    pthread_mutex_unlock(&pq->lock);
    return task;
}

void* worker_thread(void *arg) {
    PriorityQueue *pq = (PriorityQueue *) arg;
    while(1) {
        Task *task = dequeue_task(pq);
        if (task == NULL) break; // Exit condition can be set externally.
        // Process the task...
        task->status = COMPLETED;
    }
    return NULL;
}

void graceful_shutdown(PriorityQueue *pq, pthread_t *threads, int thread_count) {
    for(int i = 0; i < thread_count; i++) {
        pthread_cancel(threads[i]);
        pthread_join(threads[i], NULL);
    }

    while(pq->size > 0) { // Ensure all tasks are completed
        Task *task = dequeue_task(pq);
        if (task != NULL)
            free(task); // Assuming task was dynamically allocated.
    }
}

int main() {
    PriorityQueue *pq = create_priority_queue();

    pthread_t threads[10]; // Example thread pool size

    for(int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, pq);
    }

    // Enqueue tasks here, possibly from an external source.
    Task *task1 = malloc(sizeof(Task));
    task1->id = 1;
    task1->priority = 10;
    task1->deadline = time(NULL) + 60; 
    task1->status = PENDING;

    enqueue_task(pq, task1);

    // More tasks can be enqueued...

    // Graceful shutdown example
    graceful_shutdown(pq, threads, 10);

    free(pq); // Clean up.
    return 0;
}
```

This code includes a binary heap-based priority queue with thread-safe enqueue and dequeue operations. The system uses POSIX threads for concurrent task processing. A simple logging mechanism can be integrated by adding log statements where necessary, ensuring minimal overhead.

For robust error handling and flexibility in scheduling policies, consider using function pointers to switch between different algorithms or strategies at runtime. Additionally, monitor performance metrics as required using suitable logging frameworks or custom implementations.']

