typedef struct Node {
    char *string;
    int integer;
    struct Node *next_node;
} Node;

typedef struct Item {
    double value;
    struct Item *next_item;
} Item;

#define MAX_NODES 100
Node* nodes[MAX_NODES];
Item* head = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the linked list with random doubles in a range
void populate_linked_list(double min, double max) {
    srand(time(NULL));
    pthread_mutex_lock(&mutex);

    Item *current = NULL;
    for (int i = 0; i < MAX_NODES; i++) {
        Item *new_item = (Item*)malloc(sizeof(Item));
        new_item->value = min + ((double)rand() / RAND_MAX) * (max - min);
        new_item->next_item = NULL;

        if (!head) {
            head = new_item;
        } else {
            current->next_item = new_item;
        }
        current = new_item;
    }

    pthread_mutex_unlock(&mutex);
}

// Serialize to binary format
void serialize_binary(const char *file_path) {
    FILE *file = fopen(file_path, "wb");
    if (!file) return;

    pthread_mutex_lock(&mutex);

    fwrite(head, sizeof(Item), MAX_NODES, file);

    for (int i = 0; i < MAX_NODES; i++) {
        if (nodes[i]) {
            fwrite(nodes[i], sizeof(Node), 1, file);
        }
    }

    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Serialize to text format
void serialize_text(const char *file_path) {
    FILE *file = fopen(file_path, "w");
    if (!file) return;

    pthread_mutex_lock(&mutex);

    for (Item *current = head; current != NULL; current = current->next_item) {
        fprintf(file, "%lf\n", current->value);
    }

    for (int i = 0; i < MAX_NODES; i++) {
        if (nodes[i]) {
            fprintf(file, "Node %d: %s, %d\n", i, nodes[i]->string, nodes[i]->integer);
        }
    }

    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Deserialize from binary format
void deserialize_binary(const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_NODES; i++) {
        Item *new_item = (Item*)malloc(sizeof(Item));
        fread(new_item, sizeof(Item), 1, file);

        new_item->next_item = head;
        head = new_item;
    }

    for (int i = 0; i < MAX_NODES; i++) {
        Node *new_node = (Node*)malloc(sizeof(Node));
        fread(new_node, sizeof(Node), 1, file);

        nodes[i] = new_node;
    }

    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Deserialize from text format
void deserialize_text(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return;

    pthread_mutex_lock(&mutex);

    char buffer[256];
    Item *current = NULL;

    while (fgets(buffer, sizeof(buffer), file)) {
        double value;
        sscanf(buffer, "%lf", &value);

        Item *new_item = (Item*)malloc(sizeof(Item));
        new_item->value = value;
        new_item->next_item = NULL;

        if (!head) {
            head = new_item;
        } else {
            current->next_item = new_item;
        }
        current = new_item;
    }

    for (int i = 0; i < MAX_NODES; i++) {
        fgets(buffer, sizeof(buffer), file);
        char *string = strtok(buffer, ", ");
        int integer = atoi(strtok(NULL, ", "));

        Node *new_node = (Node*)malloc(sizeof(Node));
        new_node->string = strdup(string + 7); // Skip "Node X: "
        new_node->integer = integer;
        new_node->next_node = NULL;

        nodes[i] = new_node;
    }

    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Memory usage monitoring
void monitor_memory_usage() {
    // Placeholder for memory tracking logic
    printf("Memory usage report generated.\n");
}

int main() {
    populate_linked_list(0.0, 100.0);

    serialize_binary("data.bin");
    serialize_text("data.txt");

    deserialize_binary("data.bin");
    deserialize_text("data.txt");

    monitor_memory_usage();

    return 0;
}
```

### Key Points:
- **Concurrency**: Mutex locks are used to ensure thread-safe operations on shared data.
- **Serialization/Deserialization**: Supports both binary and text formats for saving/loading structures.
- **Memory Management**: Dynamic memory allocation is used for nodes and items, with careful handling of pointers.
- **Monitoring**: A placeholder function for future implementation of memory usage tracking.

This code provides a foundation that can be extended to support additional features or data types as needed.']

