#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
} record;

#define MAX_MEMORY_USAGE 1024 * 1024 // Example max memory usage (1MB)
#define MEMORY_PER_RECORD sizeof(int) + sizeof(long *)
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_data_structure(size_t num_keys, long (*process_pipeline)(record *));
void cleanup_memory(void **offset_array, void **key_array, record **records);
int generate_random_int(int min, int max);

void initialize_data_structure(size_t num_keys, long (*process_pipeline)(record *)) {
    if (num_keys == 0) return;

    // Calculate memory usage
    size_t total_memory = num_keys * MEMORY_PER_RECORD + 
                          num_keys * sizeof(long) +
                          num_keys * sizeof(int);

    if (total_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return;
    }

    long *offset_array = malloc(num_keys * sizeof(long));
    int *key_array = malloc(num_keys * sizeof(int));
    record *records = malloc(num_keys * sizeof(record));

    if (!offset_array || !key_array || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        cleanup_memory((void **)&offset_array, (void **)&key_array, (void **)&records);
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    pthread_mutex_lock(&lock);  // Ensure thread safety
    for (size_t i = 0; i < num_keys; ++i) {
        key_array[i] = i;  // Example initialization of keys
        offset_array[i] = rand() % 1000; // Random offsets within a range

        records[i].value = generate_random_int(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);
        records[i].offset_ptr = &offset_array[i];

        if (process_pipeline) {
            process_pipeline(&records[i]);
        }
    }
    pthread_mutex_unlock(&lock);

    free(offset_array);
    free(key_array);
}

void cleanup_memory(void **offset_array, void **key_array, record **records) {
    if (*offset_array) free(*offset_array);
    if (*key_array) free(*key_array);
    if (*records) free(*records);
    pthread_mutex_unlock(&lock);  // Unlock the mutex during cleanup
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}
```

