#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit, adjust as needed
#define RETRY_LIMIT 5
#define INITIAL_DELAY_MS 100

typedef struct {
    int value;
    long* offset;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

record* fetch_external_key_array_with_retry(int retries, int delay) {
    for (int i = 0; i < retries; ++i) {
        // Simulate fetching from a third-party service
        record* key_array = simulate_fetch();
        if (key_array != NULL) return key_array;
        sleep_ms(delay);
        delay *= 2;
    }
    return NULL;
}

record* allocate_records(size_t num_records) {
    RecordArray* ra = malloc(sizeof(RecordArray));
    pthread_mutex_init(&ra->lock, NULL);

    ra->capacity = num_records;
    ra->count = 0;

    if (num_records * sizeof(record) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    ra->records = malloc(num_records * sizeof(record));
    for (size_t i = 0; i < num_records; ++i) {
        ra->records[i].offset = malloc(sizeof(long)); // Initial allocation
        if (!ra->records[i].offset) {
            fprintf(stderr, "Memory allocation failed\n");
            free_records(ra);
            return NULL;
        }
    }

    return (record*)ra->records;
}

void free_records(RecordArray* ra) {
    pthread_mutex_lock(&ra->lock);
    for (size_t i = 0; i < ra->count; ++i) {
        free(ra->records[i].offset);
    }
    free(ra->records);
    pthread_mutex_unlock(&ra->lock);
    pthread_mutex_destroy(&ra->lock);
    free(ra);
}

void resize_records(RecordArray* ra, size_t new_capacity) {
    pthread_mutex_lock(&ra->lock);

    record* new_records = realloc(ra->records, new_capacity * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        pthread_mutex_unlock(&ra->lock);
        return;
    }

    for (size_t i = ra->count; i < new_capacity; ++i) {
        new_records[i].offset = malloc(sizeof(long)); // Initial allocation
        if (!new_records[i].offset) {
            fprintf(stderr, "Memory allocation failed\n");
            free_records(ra);
            pthread_mutex_unlock(&ra->lock);
            return;
        }
    }

    ra->records = new_records;
    ra->capacity = new_capacity;

    pthread_mutex_unlock(&ra->lock);
}

int main() {
    record* key_array = fetch_external_key_array_with_retry(RETRY_LIMIT, INITIAL_DELAY_MS);
    if (!key_array) {
        fprintf(stderr, "Failed to retrieve key array\n");
        return 1;
    }

    RecordArray* ra = allocate_records(10); // Example initial size
    if (!ra) {
        free(key_array);
        return 1;
    }

    // Example usage: populate records
    for (size_t i = 0; i < ra->capacity && key_array[i].offset != NULL; ++i) {
        pthread_mutex_lock(&ra->lock);
        if (ra->count >= ra->capacity) {
            resize_records(ra, ra->capacity * 2);
        }

        // Example record setup
        ra->records[ra->count].value = i;
        *ra->records[ra->count].offset = *(key_array[i].offset);

        pthread_mutex_unlock(&ra->lock);
        ra->count++;
    }

    free_records(ra);
    free(key_array);

    return 0;
}
