#[derive(Debug)]
struct Record {
    value: i32,
    offset_ptr: *mut u64,
    key_ptr: *mut i32,
    access_count: usize,
}

fn initializeAndManageRecords(
    num_entries: usize,
    range_start: i32,
    range_end: i32,
    supervisor_id: &str,
    username: &str,
    password: &str,
) {
    // Initialize memory for offset values and keys
    let mut offsets = vec![0; num_entries];
    let mut keys = vec![0; num_entries];

    // Create a vector of records
    let records = Arc::new(Mutex::new(vec![]));

    // Initialize hash map and priority queue
    let record_map: HashMap<i32, Record> = HashMap::new();
    let priority_queue = BinaryHeap::new();

    // Populate the records with random values
    {
        let mut rng = rand::thread_rng();
        let mut records_guard = records.lock().unwrap();

        for i in 0..num_entries {
            let value = rng.gen_range(range_start..=range_end);
