fn initializeAndManageRecords(num_entries: usize, range_min: i32, range_max: i32) -> Result<(), String> {
    let offsets = (0..num_entries).map(|_| 42u64).collect::<Vec<u64>>();
    let keys = (0..num_entries as i32).collect::<Vec<i32>>();

    let records = Arc::new(Mutex::new(Vec::with_capacity(num_entries)));
    let datas = Vec::with_capacity(num_entries);
    let metadatas = Vec::with_capacity(num_entries);

    for i in 0..num_entries {
        let record = Record {
            value: rand::thread_rng().gen_range(range_min..=range_max),
            offset_ptr: &offsets[i] as *const _,
            key_ptr: &keys[i] as *const _,
            metadata_ptr: metadatas.as_ptr(),
        };

        records.lock().unwrap().push(record);
    }

    Ok(())
}

fn retrieve_record(index: usize, records: Arc<Mutex<Vec<Record>>>) -> Option<Record> {
    let records = records.lock().unwrap();
    records.get(index).cloned()
}

fn update_record_value(index: usize, new_value: i32, records: Arc<Mutex<Vec<Record>>>) {
    if let Some(record) = records.lock().unwrap().get_mut(index) {
        record.value = new_value;
    }
}

