        } else {
            HttpClient::new().unwrap()
        };

        RequestBuilder { client, url: url.to_string(), disable_ssl_validation }
    }

    async fn get(&self) -> Result<reqwest::Response, reqwest::Error> {
        self.client.get(&self.url).send().await
    }

