        if (channel != null) {
            try {
                channel.close();
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error closing connection", e);
            }
        }
    }

    private void startMonitoringAndScaling() {
        monitoringExecutor.scheduleAtFixedRate(() -> {
            int currentLoad = getCurrentLoad(); // External monitoring service call
            adjustServerInstances(currentLoad);

            // Log throughput and latency periodically for performance tuning
            logger.log(Level.INFO, "Current throughput: {0}, Latency: {1}", 
