        if (currentLoad > maxConnections * 0.8) {
            // Horizontal scaling: increase instances
            increaseInstances();
        } else if (currentLoad < maxConnections * 0.3) {
            // Vertical scaling: optimize existing instances
            decreaseInstances();
        }
    }

